window.D=window.D||{};D.shut=[{"t":"עוד בדין השימוש במכשירים חשמליים-סיום","p":[{"t":"בס\"ד, ב' דר\"ח מר חשון תשע\"ג","b":false},{"t":"סימן ב'","b":true},{"t":"י\"ג. ומ\"ש לעיל דקול של שיר כולל כל קול שיש בו נעימות ונחת, ראיתי כעת בספר נהר שלום על הל' שבת (סימן ש\"ה סי\"א) שם כתב בש\"ע ופוקק זוג וכו'. והמג\"א כתב דצ\"ע דבסימן של\"ח פסקינן דרק קול של שיר אסור, וכתב ואפשר דמשתמע ג\"כ בקול של שיר כמש\"ש עכ\"ל. והנה\"ש כתב, והתם (בסי' ש\"א ססכ\"ג) כתבתי דהרמ\"א שם אזיל לשיטתיה, שפסק (בסימן של\"ח) כהאגור דכלי המיוחד להקיש כגון טבעת הדלת אע\"פ שאינו מתכוין לשיר אסור. אלא שקשה דהב\"י שם חלק על האגור ופסק כרוה\"פ דאע\"פ שהוא מיוחד להשמיע קול, כל שאינו מכוין לשיר שרי, ולהב\"י קשה אמאי פוקק, והרי אין מכוין לשיר.","b":false},{"t":"ונראה דע\"כ לא כתב הב\"י התם, אלא בהקשת דלת שאינו קול הנשמע בנעימה ונחת, אבל קול שיר אע\"ג שאינו מכוין לשיר אסור. וכ\"נ ממ\"ש רש\"י בעירובין וכו', והרמב\"ם ג\"כ הוא מהסוברים (כהרי\"ף) דקול שאינו של שיר מותר, ואעפי\"כ כתב (בפ' כ\"ג) וכן בש\"ע (סימן של\"ט), אסור להשמיע קול של שיר בין בכלי שיר כגון נבלים וכנורות וכו' או לקשקש את האגוז לתינוק, או לשחק בו בזוג כדי שישתוק וכו', והמקשקש באגוז לתינוק כונתו רק להשתיקו ולא לשיר, ואעפ\"כ נכלל בקול של שיר, משום שנשמע בנעימה, והכא נמי בזוג של בהמה עשויה לקול וכו', ואסור כיון שנשמע בנחת ובנעימות. עכ\"ל.","b":false},{"t":"וכבר הבאתי לעיל לדברי רש\"י והרמב\"ם ז\"ל הנ\"ל, וכתבתי להוכיח כן מסוגיא דגמרא בעירובין שם, בכמה אנפין כיע\"ש.","b":false},{"t":"י\"ד. והנה ראיתי להגאון אגרות משה ח\"ד (חא\"ח סימן פ\"ג) דמיפשט פשיטא ליה לאסור מיקרופון בשבת ויום טוב, שכתב תשובה קצרה וז\"ל, ובדבר לתקוע שופר אצל מייקראפאן איננו רואים בזה היתר, דהטעמים שאסרנו מייקראפאן בשבת הוא גם ביום טוב, ולכן אין לתקוע במייקראפאן, ואם יש חולים צריך לתקוע בפניהם במקום ששוכבים, ואקוה שחתנו הנכבד נ\"י יאמר למנהלי מושב זקנים שאסור, וישמעו קולו ולא יכפוהו לתקוע במיקרופון. עכ\"ל.","b":false},{"t":"ובתשובה שאחרי זה (סימן פ\"ד) כתב שהוא פשוט שאסור, וכבר פירסמו אגודת הרבנים שהוא אסור, ואע\"פ שיש שלא יודעים הטעמים, מחוייבים להשמע להוראת חכמים, ואותם שהקלו לא עשו כהוגן, גם אם הם רבנים וגם אם אומרים שהם גדולים בתורה. עכ\"ל.","b":false},{"t":"ואחרי זה כתב הטעמים שהם שנים שיש בהם חשש דאורייתא, ושנים שהם איסורים ודאיים מדרבנן.","b":false},{"t":"א' יש לדעת שהקול הנשמע מהמיקרופון, אינו קול האדם עצמו, רק כשמדבר נעשה רושם מהברותיו, ומה שנשמע הוא קול הברה בעלמא, ורישום זה שנעשה בדיבורו (כונתו שנקלט) יש בו חשש איסור תורה, ואע\"פ שאין זו כתיבה שאינם אותיות, יש עכ\"פ חשש מלאכה מאחר שנתחדש איזה דבר שעי\"ז נשמע קול רם ממרחק, אולי מכה בפטיש ואולי בונה, וצ\"ע בבירור איזו מלאכה. ע\"כ מדב\"ק ז\"ל.","b":false},{"t":"וכבר כתבתי ע\"ד הגרשז\"א ע\"ה, שיש איסור במה שנקלטים הקולות ונהפכים לגלים חשמליים, ושוב נקלטים ונהפכים לקולות. ע\"ש. והגאון ז\"ל חידש שיש בפעולה זו חשש איסור תורה.","b":false},{"t":"עו\"כ שם, שלפי מדת הקול נגדל הוצאת הכח החשמלי, נמצא שבדיבורו מגדיל ומקטין את הכוח האלקטרי, ורואים את זה בחוש כשמחברין המכונה המודדת את הקול. ואע\"פ שלא מחברין אותו בשבת, ידוע שזה מוסיף בכוח האלקטרי כשהוא מדבר בו, וההשתמשות בכוח האלקטרי יש בו חשש איסור דאורייתא, גם בלי הבערה. עכד\"ק.","b":false},{"t":"ונתתי שמחה בלבי, שכבר כתבתי לעיל דברים אלו ממש בהערתי ע\"ד הגאון מוהרש\"ז אורבאך זצ\"ל, וגם בזה הגאון אגרו\"מ ע\"ה, הוסיף ברוח מבינתו שבהשתמשות בכוח האלקטרי, יש חשש איסור תורה.","b":false},{"t":"עו\"כ שם שכיון שרגילין לחבר המיקרופון רק כשצריכים לדבר בו, אסור לחברו אפי' מיום ששי, כמו שאסרו חכמים ליתן חטים בריחיים של מים מערב שבת כמו שאמרו (בשבת י\"ח ע\"א), ובב\"י (סס\"י של\"ח) ד\"ה כתב האגור, שמטעם זה צריך לאסור לערוך השעון המקשקש, ולא התירו אלא מטעם שגם בחול רגילים לתקנו על יום שלם, (משום כך) מותר גם בע\"ש. [וזה האיסור הראשון מדרבנן דאסור לחברו אפי' מערב שבת, שיחשבו שחיברו עתה כפי שרגילים.]","b":false},{"t":"וזה שמחברין אותו רק בשעה שצריכים להשתמש בו, יש לאסור אפי' להכינו מע\"ש, דיחשבו שעתה חיברוהו לפני השימוש כמו שרגילים. ומטעם זה אסור להעמיד רדיו וטלויזיא מע\"ש.","b":false},{"t":"עו\"כ שם שאסור משום שמא יתקן כלי שיר, ובמיקרופון מצוי שמתקנים כשמתקלקל תוך הדבור, והוא דרבנן. [זה האיסור השני מדרבנן.] ולא מהני שיסגרו באופן שא\"א לתקן, שמה שנאסר מדרבנן אסור בכל אופן. וסיים בזוה\"ל: ולכן ברור שהמיקרופון אסור להשתמש בו בשבת ויו\"ט ואין להקל גם לצורך גדול, ולכן אסור לקבל משרה כזו שיצטרך לדבר במיקרופון בשבת ויום טוב. עכ\"ל.","b":false},{"t":"עוד ראיתי להגרמ\"פ זללה\"ה שם (סימן פ\"ה) בענין מכשיר שמיעה לחרש בשבת. כתב שנוהגין אנו כאן להקל, אע\"פ שאוסרים המיקרופון מארבעה טעמים (כהנזכר בתשובתו הקודמת). וכתב דמיקרופון רגילים לחברו רק בשעת השמוש, ואיסור זה הוא רק בדבר שמשמיע קול לרבים, כמו ריחיים של מים, דשבת (י\"ח) דאוושא מילתא. משא\"כ בזה שלא נשמע כלל לאחרים.","b":false},{"t":"והטעם שהכל יכולים לתקנו הוא ג\"כ בכלל איסור כלי שיר, וזה שהוא מיועד רק לחרשים, חשיב כמילתא דלא שכיחא שלא גזרו.","b":false},{"t":"ועוד שלחרשים הוא צורך גדול מאד, שבלי זה יש חשש פקוח נפש, שלא ישמע נסיעת המכוניות, וצריך לדבק איזה דבר שלא יוכל לתקן. דכיון שאין זה בכלל הגזירה מהני תיקון זה.","b":false},{"t":"ובענין שהקול נרשם ונקלט שם, גם אם במכונה זו ג\"כ נרשם כמו מיקרופון, כיון שאין ברור לנו האיסור (כמו שכתב בתשובה הקודמת), ע\"כ אין בידינו לאסור לחולה ולצורך גדול בזה, ובפרט שיש חילוק בין מכונה זו, שאין הקול נעשה רם יותר, ומה שנשמע לחרש הוא משום משיכת הקול לתוך האזן ממש בלי הפסק בינתים, ואין דבר ברור גם אצל המומחים. [וגם בזה זכיתי לכוין לדעתו הרמת'ה, במה שכתבתי לעיל שיש לחלק בין מיקרופון ובין מכשיר שמיעה ע\"ש.]","b":false},{"t":"ומה שכתב שם שמשתמש בכוח האלקטרי שמגביהו, האיסור לא ברור, וגם שנדמה שבמכונה אין חשש זה שאין חילוק אם מדבר בקול גדול או לא. ע\"כ אין לאסור לחולה. והנה אנו רואים שהגאון אגרות משה ע\"ה כבר התעורר במה שהקשה הגרשז\"א ז\"ל דאם אכן המיקרופון אסור איך מותר לדבר עם כבד אזנים שיש לו מכשיר שמיעה ואיך עולה לתורה, וכנ\"ל. וכתבתי לחלק ביניהם, והן עתה מצאתי שכבר קדמנו בכל זה הגאון אגרו\"מ ע\"ה.","b":false},{"t":"עו\"כ באגרו\"מ, ועוד שהחרש לא עושה שום מלאכה, והנידון הוא על המדברים, והמדברים שלא במיוחד לחרש שרי, דאין מתכוין, ואין זה פסיק רישיה, דכמה פעמים לא שומע גם עם המכונה. ואלו המדברים ביחוד לחרש, שבזה הוא מתכוין ואסור, ע\"כ כשאפשר טוב שלא ידברו במיוחד לחרש, ותועיל המכונה לרוב הדברים שצריך לשמוע, כמו ברחוב ובביהכ\"נ וכששואל ישיבו לו בתנועה וברמיזה, וכשאי אפשר כמו ילד קטן שמוכרחים להשיבו דוקא בדיבור, אין לאסור, עכד\"ק ע\"ה. ובכל אלה זכיתי לכוין לדעתו ת\"ל יתברך ויתעלה.","b":false},{"t":"והנה במה שכתבתי למעלה שע\"י השימוש בזרם, נרשם במד החשמל, וגם במחשב של חברת החשמל, שכל צריכה של הזרם משנה את המספרים, שהם עולים והולכים לרשום את הכמות שצורך כל אחד ואחד. הנה ממ\"ש האגרו\"מ (סימן פ\"ד) שדבורו נרשם ויש חשש דאורייתא, ואע\"פ שאין זה כתיבה שאינם אותיות וכו'. ומשמע שאם נרשמים אותיות פשיטא ליה שהוא דאורייתא. והוא חיזוק גדול למה שכתבתי. ועיין עוד לקמן מה שכתב בזה הגאון שבט הלוי שליט\"א, שהיא כתיבה גמורה מן התורה. ושני הנביאים התנבאו בסגנון אחד.","b":false},{"t":"וא\"כ מלבד כל האיסורים דרבנן דשמא יתקן, והשמעת קול, וכו', יש גם איסור כתיבה דאורייתא, בעצם צריכת הזרם ע\"י פעולתו, שעל ידי זה נכתבים ספרות בשעון החשמל הביתי וגם במחשב של חברת החשמל. ואעפ\"י שהוא לא כותב ולא מתכוין לכתוב, מ\"מ הוא פסיק רישיה, דא\"א לצרוך חשמל בלא כתיבה, וזו צריכה היוצא מהפעולה שמפעיל את הרם קול ביום שבת, דאע\"ג שהוא מחובר ומופעל מע\"ש, כל זמן שלא מדברים בו אינו צורך חשמל, וע\"י דיבורו הוא מפעיל כל מערכותיו, והוא צורך זרם חשמלי ונרשם כהנ\"ל. ואין לומר דהוי פסי\"ר דלא ניחא ליה, שכל אדם הגון רוצה לשלם את מה שלוקח, ולא עוד אלא אם לא יירשם לא יספקו לו חשמל, או ינקטו נגדו צעדים אחרים, וע\"כ ודאי ניחא ליה שיירשם כחוק. ויש בזה איסור תורה כפי פסקם של מאורי הדור באגרות משה ובשבט הלוי.","b":false},{"t":"עוד ראיתי לו בתשובה אחרת שם (בסימן י') שהקשו לו למה כתיבת סת\"ם ע\"י צילום פסול, ובשבת ודאי מלאכה היא, ותמה על קושיא זו, דשבת אסור במלאכה ובכל אופן שעושה מלאכת כתיבה אסור שנכתבו אותיות, ולכן ודאי חייב, דכמה דברים נכתבים ע\"י צילום, ורוב הספרים היום נדפסין ע\"י צילום, וגם בשבת חייב גם הצר צורה, ולהרמב\"ם (פי\"א מהל' שבת הי\"ז) הוא תולדת כותב, אבל בסת\"ם לא שייך ענין מלאכה, אלא צריך שאדם יכתוב ולא שיגרום שיהיה כתב, ובס\"ת צריך דוקא דיו וצילום אינו דיו, וכן צריך שרטוט בס\"ת ומזוזות, וגם תפילין לתוס' (גיטין ו') צריך שרטוט, ולא שייך כסדרן בצילום, ועוד הרבה דברים, ולא שייך לדמות ולהקשות כלל. עכ\"ד.","b":false},{"t":"[וכל מה שכתב בזה הוא בצילום, או כתיבה ע\"י מחשב, אבל בכתיבה ע\"י דפוס, פסק הרמ\"ע מפאנו בתשובה, דחשיב כותב ע\"ש. וכ\"פ המג\"א בא\"ח (סימן ל\"ב ס\"ק נ\"ז) והרמ\"ע שם פסק דה\"ה נמי שאפשר לכתוב גט ולהחתים עדים ע\"י הדפוס, וכתב שהוא בקיא במלאכת הדפוס ויודע שהוא כתב גמור. ע\"ש. וידוע שמרן ז\"ל בעל הב\"י והשו\"ע שלח אליו כתב ידי קדשו והוא שהדפיסם באיטליא.]","b":false},{"t":"ואולם בנ\"ד אינו נכתב על הנייר וכדו' רק נרשם במחשב, מיהו בודאי שיש בזה איסור ולדברי האגרו\"מ הנז', וכן לדברי שבט הלוי דלהלן הוא אסור מן התורה.","b":false},{"t":"ט\"ו. והלום ראיתי להגאון הגדול רבי שמואל וואזנר שליט\"א בשו\"ת שבט הלוי ח\"ו (או\"ח סימן ל\"ז) שנשאל על מחשב שפעולתו כידוע היא צירוף קוים, ועי\"ז נעשים ספרות ואותיות, אם נחשב כתיבה בחוה\"מ, שאין הכתיבה מתקיימת, וכן אם אסור בשבת, וכתב שהחיי אדם (הובא במשנ\"ב סימן ש\"מ) שכתב דאסור לחבר אותיות בשבת, אעפ\"י שהאותיות גמורות, אבל זה רק באופן קבוע וכאן זה עראי. ע\"כ מהשואל.","b":false},{"t":"והגאון שבט הלוי השיבו בזוה\"ל: ולדידי לענין שבת לא רק דאסור, אלא גם חיובא דאורייתא איכא, ושתי ריעותות שיש בזה שאין מלאכתו מתקיימת, ושהוא רק דרך גרמא, אינם סיבה לפוטרו ממלאכת כותב דאורייתא בנ\"ד, דכיון דמתקיים בשעתו ועושה פעולה הנצרכה בשלמותה, דהיינו כתיבה המבוקשת, זה כבר בגדר דבר המתקיים, וכמו הכותב על בשרו (שבת ק\"ד ע\"ב) דחייב, וכלשון הרמב\"ם (פי\"א מהל' שבת הט\"ז) דאע\"פ שעובר לאחר זמן. ה\"ז ככתב שנמחק, וה\"נ נעשה פעולה חדשה למוחקו מיד, אבל מעצם הכתב ה\"ז מתקיים ונקרא, ומה שצריך לו נעשה בשלמות, וכתב שכן ראה להגאון רבי מנחם בספר תוצאות חיים (סי' י\"א, ג') שכתב כן לענין כותב על בשרו דחייב, מצד שהכתיבה היא כתיבה גמורה, והמחיקה היא פעולה חדשה שנתחדשה אח\"כ וכן הוא ממש בעניננו. עו\"כ. ולענין בונה דעת כמה פוסקים, דבונה ע\"מ לסתור פטור, ואעפ\"כ אמרו בשבת (צ\"ה ע\"א) דמגבן חייב משום בונה, ובפני יהושע (ביצה י\"ב) עמד ע\"ז, דהא זה ע\"מ לסתור ולאכול, ומ\"ש הפ\"י שם דרק לאוצר הוא דחייב, כבר הרגיש בעצמו הדוחק, ואין דעת הראשונים כן. וכתב לעיין מה שהעיר בזה בשבט הלוי ח\"א (סימן קי\"ט) בדיני בנין לזמן. אבל באמת יש הוכחה מזה דבונה ע\"מ לסתור חייב, או מה שנראה יותר, כיון שבשעתו הוא בנין למה שצריך ה\"ז חייב מה\"ת, ולא מזיק מה שעומד לאכילה דזה דרכו. והרי כותב על שני לוחי הפנקס חייב כמבואר במשנה (שבת שם), וכתב רש\"י דהיינו על לוח שעוה, אע\"פ דידוע ששוב עוברים על השעוה דרך מחיקה ומירוח, ואין הכתיבה עומדת להתקיים, אלא כל קיום בשעתו והושג התועלת הנרצה נקרא מתקיים מלאכתו בשבת.","b":false},{"t":"עו\"כ דמה שדימה להחיי\"א דחיבור אותיות אסור מדרבנן, וזה רק דרך קבע ולא עראי (כך טען השואל), והשיב הגאון בעל שבט הלוי, דכאן לא מיקרי עראי, ועוד דשם האותיות היו שלמות, אבל כאן גורם לאותו סוג כתיבה בתחילה.","b":false},{"t":"ואעפ\"י שלא בידו עושה רק בלחיצת כפתור, כבר כתבתי בשבט הלוי חא\"ח (סי' מ\"ז) בזורה דחייב, אע\"פ שהמלאכה רק דרך גרמא. וכתב הרא\"ש דבהכי חייביה רחמנא, שעיקר עשייתה של מלאכה זו ע\"י הרוח. וע\"כ בכל מלאכה שדרכה לעשותה בדרך זו, נחשב כמעשה בידים, דמלאכת מחשבת אסרה תורה, והו\"ל כעושה מעשה בידים ממש, ורמזתי שם ע\"ד ג\"ע החזו\"א (ב\"ק סימן י\"ד) בחורש או זורע ע\"י מכונה, והאדם לוחץ לחיצה ראשונה בכפתור ועי\"ז נפעלת מערכת הגלגלים זא\"ז ונעשית פעולת חרישה וזריעה, דאעפ\"י שבמציאות החרישה והזריעה לא עשה כלום, מלבד תחילת הלחיצה, חייב מהתורה, שכיון שדרכו בכך היינו מלאכת מחשבת דאורייתא, והכי נמי ממש בדידן.","b":false},{"t":"ולענין חוה\"מ אולי יש לצדד קצת בכתיבה כנ\"ל, כיון דיסוד מלאכת חוה\"מ היא טירחת המלאכה כידוע, לא כלל מלאכת מחשבת. עכ\"ל. (וראיה לדבריו ממלאכת בורר ביו\"ט).","b":false},{"t":"ט\"ז. עוד ראיתי אחרי רואי בדברי הגאון סבא דמשפטים כמהרא\"י וולדינברג זצ\"ל בשו\"ת ציץ אליעזר ח\"ג (סי' ט\"ז) וראיתי לו שם שהוא ז\"ל למד עניני החשמל ומכשיריו ביסודיות לפרטי פרטים מפי גדולי המומחים, וגם מתוך ספרים מיוחדים לזה. כדי ללבן הלכות אלו כדת וכדין.","b":false},{"t":"והעלה שיש ג' צינורות להעברת קול עד השמעתו ברדיו, הראשון בהם הוא \"מיקרופון\" שבו מדברים ומשמעים מנגינות. (צריך להוסיף על דבריו שמיקרופון זה קולט את הקולות והופך אותם לזרמים חשמליים, ושו\"ר שכן כתב הוא ז\"ל להלן.)","b":false},{"t":"והשני הוא \"משדר\" שקולט את הזרמים החשמליים מהמיקרופון. והשלישי הוא \"מקלט\", שקולט מהמשדר את כל מה ששידרו, באמצאות גלי רדיו. (וצריך להוסיף שהופך הגלים החשמליים לקולות).","b":false},{"t":"ומפרש שם, שהקול יוצר תנועה באויר ונוצרים גלי קול, והממברנה (שהוא קרום של פח דק מאד) מזדעזע וקולט הקולות שנהפכים שם לזרמים חשמליים דקים, וכשמפסיק לדבר או לנגן, הזרמים מפסיקים לזרום, ולמעשה אחרי כל הברה, הזרם מפסיק לגמרי, (ומתחדש בהברה הבאה), עו\"כ שעוצמת הזרם משתנה לפי עוצמת הקול או המנגינה.","b":false},{"t":"ואעפ\"י שכתב הדברים הנז', על השידורים שנעשים בתחנות השידור, שהם נקלטים ונשמעים במכשירי הרדיו, מ\"מ רובם של הנקודות האמורות קיימים ומתבצעים גם במיקרופון ובמכשירי הטלפון לסוגיהם. וע\"ש עוד שהאריך לבאר כל התהליך של השידור, ומראה בכמה חילולי שבת כרוך הדבר הזה.","b":false},{"t":"ואחרי זה (בפ\"ב שם) הזכיר הסוגיא דעירובין (ק\"ד ע\"א) ודברי רש\"י בקול של שיר, והירושלמי שמשמע שאוסר כל השמעת קול ואפילו הקשה על הדלת, וכדעת עולא ואביי, ופירש את המחלוקת של האמוראים בזה, דהאוסרים ס\"ל שגזרו על השמעת קול, ועל כן כל השמעת קול אסורה. ורבה שאמר שלא גזרו אלא על קול של שיר, סובר שלא גזרו על השמעת קול, אלא אסור קול של שיר, גזירה שמא יתקן כלי שיר. וכאמור כתב שכן כתב האור שמח בהל' שבת (פכ\"ג ה\"ה). דלעולא ואביי שאסרו כל אולודי קלא א\"צ לגזירה דתיקון כלי שיר. וכן מוכח מהירושלמי דמסקנתו לאסור כל קול, ושם לא נזכרה הגזירה דשמא יתקן כלי שיר. וגם מדוייק בלשון הירושלמי, שכתוב שם, כל משמיעי קול אסורין, משמע דתלוי בהשמעת הקול. ולר\"ח דאסר כל השמעת קול, הוא איסור עצמי ולא תלוי בענין אחר.","b":false},{"t":"עוד דייק שם מהב\"ח (סימן של\"ח) דלא כהאור שמח הנז', אלא ס\"ל דכל האיסור הוא משום גזירה שמא יתקן כלי שיר.","b":false},{"t":"עו\"כ בציץ אליעזר שם (פ\"ב אות ו') דבשו\"ע (סימן של\"ח) גבי השמעת קול של שיר, לא הזכיר שמא יתקן כלי שיר, ורק להלן (סימן של\"ט) בדין דאין מטפחין וכו', כתב, שמא יתקן כלי שיר. עוד מדקדק דהש\"ע (סי' של\"ח) שינה לשונו וכתב השומע קול בכלי שיר, דאכן זה איסור עצמי שאינו תלוי בגזרה, דמלבד הגזרה אסרו גם משום מוליד, אלא דס\"ל דלא אסרו מוליד קול, אלא בקול שיר. והוסיף דקול בכלי שיר יש בו משום שמא יתקן, וגם מוליד. וקול שיר בלא כלי שיר, אסור רק משום שמא יתקן כלי שיר. עכ\"ד. ופירושו צ\"ע דלענ\"ד קשה לחלק כן ועוד חזון למועד אי\"ה.","b":false},{"t":"עו\"כ בציץ אליעזר שם (פ\"ג) דלהנ\"ל עולה דלא רק נגינה ברם קול אסור, שזה ממש קול שיר בכלי שיר, אלא גם אסור לדבר במיקרופון, דעל ידי זה נוצרים גלים חשמליים מהקול, ושוב נהפכים לקולות, דאע\"פ שאינו קול של שיר, מ\"מ יש בזה השמעת קול, דמיקרופון נחשב לכלי שיר. וכל הבא מכלי שיר אסור. ועוד שהרמ\"א (סימן של\"ח ס\"א) פסק שאפי' שאינו כלי של שיר, אם הוא כלי שמיוחד לקול אסור, שהרי אסר טבעת הקבועה בדלת להקיש בה, אפי' שאין מתכוין לשיר.","b":false},{"t":"ובב\"י כתב על זה דחיישי' שמא יכוין לשיר, והמשנ\"ב בביאוה\"ל שם כתב דאין לזה הבנה, דאיך יכוין לשיר בזה. ואילו בלבוש שם כתב, שהואיל וכלי זה מיוחד לקול, חיישינן שמא יתקננו [ולענ\"ד יש מקום לומר דבמיקרופון שאפשר לשיר ולנגן בו, כו\"ע יודו לאסור ושייך גם החשש של הב\"י.]","b":false},{"t":"י\"ז. עו\"כ יתר ע\"כ ראיתי בשו\"ת מהר\"ם שיק חא\"ח (סי' קכ\"ז) בנידון דמשיכת הפעמון בשבת, שביאר טעם האיסור בכלי המיוחד הוא גזירה שמא יתקן כלי שיר. ואע\"פ שהכלי גבוה מהאדם ולא יכול לתקנו זה המושך בו, מ\"מ קי\"ל בסי' רע\"ח שלא חילקו אפי' בגבוה הרבה (גבי שמא יטה) וגזרו בהם. אא\"כ עשו שינוי כדבר כדי להזכר על ידו, שיש דעה במג\"א (שם סק\"ג) להתיר. נמצא דמה שאסרו אסור גם כשלא שייך החשש שיתקן באותה פעולה.","b":false},{"t":"ואעפ\"י שאפשר ללמוד ממהר\"ם שיק שיש צד להקל אם יעשו שינוי במיקרופון לזכירה. מ\"מ המעיין בדברים יראה דלא ניחא ליה להתיר ע\"י שינוי, ואפי' לא בשנים דמידכרי אהדדי, שכתב דכבר הקשה המג\"א דא\"כ גם ברכיבה יהא מותר בשנים ע\"ש. והתו\"ש כתב דאין מדמין בשבותין, ואין לנו אלא מה שכתבו חכמים בפירוש. וכ\"כ המג\"א (בסי' ש\"ו). ואין מקילין בשנים אלא במקום מצוה או חולה. וע\"ש עוד.","b":false},{"t":"עו\"כ שכן אין עצה שיסדרו מיקרופון מיוחד לשבת, כמו שהתיר המג\"א שם (סק\"ג), ותו\"ש (סק\"ב), גבי כלי המיוחד להכות על הדלת, דשם א\"צ התאמת כלי לשם כך, ולא נקרא כלי המיוחד לכך. אבל בזה שצריך להתאים מיקרו' לשם כך, והרי בזה נעשה כלי המיוחד להשמיע קול שאסור.","b":false},{"t":"עו\"כ שם (פ\"ג אות ג') דהתפא\"י בכלכלת שבת מתיר בפעמון בשעה\"ד כשאינו יכול ליכנס לבית, והגם שהמשנ\"ב בביאוה\"ל (סי' של\"ח) מקשה על התפא\"י מ\"מ מסביר להתיר בשעה\"ד הואיל ואינו קול של שיר. ע\"ש. ונר' שבנידוננו יותר חמור מכלי המיוחד להשמעת קול, שהמיקרופון הוא גם מיוחד לעצם השמעת קול שיר. ויש לדון שיש עליו תורת כלי שיר.","b":false},{"t":"עו\"כ שם (אות ד') דמ\"ש הרמ\"א (סימן של\"ח ס\"א) דאם לא עשה מעשה מותר, וע\"כ התיר לצפצף בפה כצפור, וה\"נ (במיקרופון) אינו עושה מעשה. רק מדבר או מנגן לפני המיקרופון. וכתב דכבר התישב בדבר שהרמ\"א לא התיר אלא כשאין שום כלי, כמו המצפצפים בפיהם, שלא דומה כלל לקול הבא ע\"י כלי שיר, ולא שייך בזה שמא יתקן, אבל כשמשתמש בכלי להשמעת קול כמו דיבור לתוך המיקרופון אע\"פ שאינו עושה מעשה, לא מיקרי ע\"י פיו (כמו צפצוף) אלא ע\"י מעשה ופעולת הכלי, ונכלל בגזירת שמא יתקן.","b":false},{"t":"[ולפי מה שכתבתי לעיל ע\"ד הגרשז\"א צ\"ל, עולה דהוי מעשה גמור. ע\"ש.]","b":false},{"t":"שו\"כ שכן הוא בבית יצחק (חיו\"ד ח\"ב במפתחות והגהות לסי' ל\"א) שאסר בטלפון, וכתב שתשו' השבו\"י נכתבה בשנת תפ\"ב, ועדיין לא היה טלפון, והוא התיר כלי אחר שלא היו בו חששות אלו.","b":false},{"t":"וכמו\"כ כתב שם הבית יצחק והזכיר שם שמות המכשירים או חלקים מהם בלע\"ז, ולא יכולתי להבין הכל, אבל עולה ממנו שאין קול המדבר נשמע רק ע\"י וכו'. ואפשר שהוא כמו שכתבתי בעוניי לעיל ע\"ד הגרשז\"א ז\"ל, דכיון שהקול מפעיל חלק מסויים שקולט הקול והופכו לגלים חשמליים, ויש חלק אחר שהופך אותם גלים לקולות ממש, א\"כ הוא מוליד קול חדש, וזה ע\"י דיבורו שזה כוחו, והו\"ל כמו שמפעיל כלי בידיו כדי להשמיע קול.","b":false},{"t":"עו\"כ בציץ אליעזר שם (פ\"ג אות ה') דיש לאסור מיקרופון גם מצד הגזירה שמא יתקן כלי שיר, דבזה מצוי הקלקול [וע\"ש שדיבר על אולפן שידור, והה\"נ לזה], וכתב שבערוך השלחן (סי' של\"ח סק\"ה) אסר אפילו להעמיד כלי שיר מע\"ש, שישיר מעצמו בשבת, שמא יתקן כלי שיר, וכ\"ש בנדוננו ע\"ש.","b":false},{"t":"וכתב שהגרשז\"א (שליט\"א) בעהמ\"ח מאורי אש ומעדני ארץ העיר לו דמשמע מכמה אחרונים דלא כערוך השלחן, ובפרט מהרש\"ם ח\"ג בהשמטות לח\"א סימן מ\"ד, וכן בספר מחזה אברהם לגאב\"ד ברודי. וע\"ש.","b":false},{"t":"וע\"ש (בפרק ד' אות א') שהביא דברי התוס' בביצה (ל' ע\"א) דבימינו שאין בקיאים לעשות כלי שיר לא שייך למיגזר, והובא ברמ\"א (סי' של\"ט ס\"ג בהגה).","b":false},{"t":"וכתב באות ב' שם, שברור שהתוס' כתבו כן רק לענין טיפוח וריקוד שבהם מדבר שם, שבאלה אין שייך תיקון, רק הגזרה שמא ינהוג היתר בכלי שיר, אבל בשימוש בכלי שיר יודו התוס' שהגזרה במקומה עומדת ואסור. וע\"ש שהרחיב לבאר דברי התוס' הנ\"ל. ושזה מדוייק בדבר התוס' שכתבו שהיו בקיאין \"לעשות\" כלי שיר, ולא אמרו לתקן, דבמשתמש בכלי שיר אסור גם בימינו שמא יתקנו.","b":false},{"t":"עו\"כ (באות ג') שם שגם הרמ\"א לא הביא דברי התוס' הנז', אלא בסימן של\"ט דמיירי בסיפוק וריקוד, ולא בסימן של\"ח שמדבר באיסור השמעת קול בכלי שיר.","b":false},{"t":"ובאות ד' שם, הקשה ע\"ד המג\"א (סי' של\"ח סק\"ה) שפירש שהרמ\"א הקיל ע\"י עכו\"ם, משום שאין אנו בקיאים בעשיית כלי שיר. וע\"ש שהאריך בזה. ושוב כתב שהדבר מפורש בתו\"ש שאין להקל מטעם שאין בקיאים בעשיית כלי שיר, אלא לענין טיפוח וריקוד. וע\"ש עוד מזה. ושהרבה חולקים על התוס' בזה. וע\"ש באות ה' שגם המג\"א יודה בענינים אלו.","b":false},{"t":"והנה בציץ אליעזר שם האריך הרחיב הרבה כיד ה' הטובה עליו, אלא שרוב הדיון שלו סובב הולך על תחנת שידור ומה שכרוך בזה, ומ\"מ מתוך הדברים העלה שיש איסור גמור לדבר במיקרופון, מכמה וכמה טעמים שחלקם כבר כתבתים משמו. ובפרק ט' שם דן באורך על שינויי הזרם והחום הנגרם ע\"י הדיבור והנגינה במיקרופון ע\"ש. ובפרק י\"א דן בזה מצד אוושא מילתא ועובדין דחול ע\"ש. ובסוף פי\"ב כתב סיכום ההלכות בקצרה, וכתב באות ח' שאסור הדיבור והנגינה במיקרופון משום השמעת קול ע\"י כלי שיר. וכבר כתבתי לעיל דעתו בזה. ובאות ט' כתב שיש בזה איסור משום אוושא מילתא ועובדין דחול וגם משום זילותא דשבת ויו\"ט. ובאות י' כתב, שהמדבר במיקרופון גורם להכהות אורות ולחימום חוטים והחלשת חומם.","b":false},{"t":"וע\"ש עוד (באות י\"ח) וז\"ל, על אחת כמה וכמה שאסורה בשבת ויו\"ט סיבוב כפתור המקלט על מנת להעביר מגל לגל, הגם שמסודר הכל מע\"ש וערב יו\"ט, ויש בזה כמה גורמי איסור, ובתוכם יש גם הבערה וכבוי. וגם מזה יש חיזוק למה שכתבתי לעיל שיש בזה איסור בהעברת הגלים. וע\"ש.","b":false},{"t":"י\"ח. עוד ראיתי במעשה חושב ח\"ג של מכון מדעי טכנולוגי להלכה (עמוד רכ\"ו) שכתבו, שיש לחוש בהגברת הזרם החשמלי ע\"י דיבור, שגם אם נשמור על צריכת זרם אחידה של המערכת, הרי ברור שבחלקים ממנה עולה הצריכה, וציינו לשו\"ת בית יצחק הנ\"ל. (חיו\"ד במפתחות לסימן ל\"א) שביצירת זרם יש משום איסור מוליד דרבנן, עפ\"י הגמ' (ביצה כ\"ג ע\"א), ופסק הרמ\"א א\"ח (סי' תקי\"א ס\"ד) שאסור להפוך כוס מבוסם על בגדים משום מוליד ריח בבגדים, והבי\"צ סובר שכן הוא ביצירת זרם, ובנ\"ד שכבר יש זרם במערכת יש לדון ע\"פ המג\"א שם (ס\"ק י\"א) שהתיר הוספת ריח בשבת, וכ\"ד שו\"ע הרב (שם ס\"ז), ואפשר שה\"ה בנ\"ד, ולענין המיקרופון העלינו שם שיש מקום לומר שאין דין הוספת זרם כהוספת ריח, אלא כמוליד ריח חדש, שלכו\"ע יש בו משום מוליד. [וכתבו לעיין בספר מעליות שבת סי\"ג]. ולפ\"ז יש לאסור מגבירי קול בשבת משום מוליד. [והוא מלבד כל האיסורים המפורטים לעיל.]","b":false},{"t":"ועוד שיש לחוש משום השמעת קול, שנאסר משום שמא יתקן כלי שיר, ואפילו יתקינוהו באופן שא\"צ לתקנו, עכ\"פ הוא בכלל הגזירה, וכמ\"ש בביצה (ל\"ו ע\"ב) לא מטפחין ולא מספקין ולא מרקדין, ובגמ' אמרו משום גזירה שמא יתקן כלי שיר, ופירש\"י במשנה שם, שמא יתקן כנגדו כלי שיר דקא עבידי מנא.","b":false},{"t":"והזכירו דברי הרמ\"א בהגה (סימן של\"ח ס\"א) שמותר לצפצף בפיו כמו ציפור כדי לקרא לחבריהם, וכתבו, דהתיר בפיו בלא כלי, ולכאורה מבואר שקול אדם בפיו ע\"י כלי, נכלל בגזירה זו. ועיין מה שדנו לענין שופר (בש\"ע תקפ\"ח ס\"ח, ובט\"ז סק\"ח ומג\"א סק\"ד) ושע\"ת (סי' תקצ\"ו סק\"א) שגם בשופר י\"א שגזרו אע\"פ שלא מכוין לשיר כלל.","b":false},{"t":"אמנם עדיין י\"ל שלא מצאנו איסור השמעת קול, כשהקול היוצא הוא כמו דיבור, אפשר דבכה\"ג לא גזרו, ויש פנים לכאן ולכאן, והחמרנו ברם קול דיש לחוש שנכלל בגזירה דשמא יתקן מנא. עכ\"ד.","b":false},{"t":"ולפי עניות דעתי יש לחלק, שכאן המערכת פועלת מכוח הקול, ומשמיעה קול שנברא ע\"י מכונה זאת, והוא מיועד גם לשירה ונגינה, וחשיב כלי שיר, שלא רק קול אדם נשמע שם, ומה שכתב שלא מצאנו שאסרו בקול שהוא כדיבור, אחר המח\"ר לא נראית סברא זו, דאסרו השמעת קול, וכאן משמיע קול וקולות הנוצרים ע\"י כלי זה. ולא חילקו באיסור זה בין קול הדומה לדיבור לשאר קולות, ואיך ס\"ד להתיר, וגם מתקלקל ומתקנים, והוא מצוי מאד, וגם אוושא מילתא. ועיין מ\"ש לעיל ע\"ד הגאון מוהרש\"ז אורבאך זצוק\"ל.","b":false},{"t":"עו\"כ שם לאסור משום דאוושא מילתא, וזילותא דשבתא, כמ\"ש (בשבת י\"ח ע\"א) אסור לתת חטים בריחים של מים מע\"ש משום השמעת קול, ופירש\"י דאוושא מילתא והוי זילותא דשבתא. וכן בעוד ראשונים שם. ומהרי\"ו והאגור דנו מזה לשעון המקשקש, מהרי\"ו אוסר והאגור בשם אביו מתיר. [עי\"ל מ\"ש בזה] וברם קול שאין דרך להכינו יום קודם כמו השעון הנז', יש בו משום אוושא מילתא וזילותא דשבתא, וגם העוברים יחשדו שערכוהו בשבת, ויש בזה פירצה בחומת השבת.","b":false},{"t":"ובאו' ג' שם כתבו שכבדי השמע, יכולים לענות על מה ששומעים במכשיר השמיעה, דיש תשעה עונים, ולכבדי השמיעה הוי כהנפת סודרין בסילקי שבאלכנסדריא (בסוכה נ\"א ע\"ב). ומכשיר זה לא גרע מסודרין.","b":false},{"t":"וע\"ש עוד באות ד', שיש להתיר מכשיר השמיעה ולא דמי למיקרופון. [ועיין לעיל מ\"ש משם אגרו\"מ].","b":false},{"t":"י\"ט. עוד ראיתי להגר\"נ קרליץ שליט\"א בחוט השני (פרק עשרים במלאכת כותב, עמוד קנ\"ג) כתיבה במחשב כדרך שבני אדם עורכים חשבונות ורוצים שיתקיימו עד הערב, מסתברא דמיקרי כתיבה המתקיימת וחייב.","b":false},{"t":"והה\"נ בכתיבה לצורך חולים וכיוצא אם מתקיימת לזמן הצריך לה י\"ל דחייב. ואם בלילה מעביר לכתב המתקיים אפשר דחשיב אינו מתקיים. וצ\"ע.","b":false},{"t":"בשבת (קנ\"ד ע\"ב) תנן הכותב על שני לוחי פנקס והן נהגין זע\"ז חייב, ופירש\"י פנקס של סוחרים וכו', וטוחים בשעוה. עכ\"ל. ובביאוה\"ל (שם ס\"ד סד\"ה במשקין על השלחן) כתב דמשמע מרש\"י דשעוה מיקרי דבר המתקיים. וכן איתה בתוספתא דהכותב על חלב קרוש, חייב, ולקמן (סי' תקמ\"ה ס\"ז) איתא דבלוחות של שעוה הוי דבר שאינו מתקיים, ובהגה כתב דגם בשעוה פטור. ואפשר שיש לחלק בין פנקס של שעוה שהשעוה מרוחה ע\"ג עץ, דמיקרי מתקיים, אבל לוחות שעוה שכל הלוח משעוה, אינו מתקיים, וע\"כ פטור.","b":false},{"t":"עו\"כ כתיבה במחשב יש לדון אי הוי כתיבה מה\"ת, דכיון שנפעל כתיבה ע\"י מעשיו אפשר דמיקרי כתיבה, ואפשר דמיקרי מתקיים דאין זה תלוי במתקיים זמן רב, אלא די בקיום לזמן הצריך לאותו דבר, וכמו בחשבון שדי שעומד עד גמר החשבונות, ועכ\"פ מה שנשמר בזכרון של המחשב גם כשאינו פועל, פשיטא שלא נקרא כתיבה כלל, שהרי נוצר דבר אחר לגמרי מן האותיות.","b":false},{"t":"עוד ראיתי בחוט השני שם (עמוד ר\"ו) בהיתרי הגרמא במלאכות שבת, ואעתיק לשונו: בתקופתנו יצאו כמה וכמה אנשים שרצו להתיר מלאכות שבת ע\"י גרמא והסרת מונע וכדו'. ועפ\"ז התירו הפעלת מכשירים חשמליים וכסא גלגלים וכדו' בשבת ע\"פ שיטה זו.","b":false},{"t":"וכבר נתפרסם מגדולי ישראל זצ\"ל ויבלח\"ט שליט\"א לאסור כל שמוש בהיתרים אלו.","b":false},{"t":"ועיין בתוס' (ס\"פ כירה) ובראשונים כמה חילוקי דינים בגרמא, שיש גרמא שנחשב כמעשה האדם וכו', ויש מאלו מלאכות האסורות מהתורה ממש, ובפרט מכשירים שבנויים באופן כזה שיפעלו לאחר איזה זמן, או הסרת המונע וכדו', שיש מאלו שנחשב כמעשה גמור, ואם הדבר ימסר להכריע בכל פרט, בודאי שיהיו בזה מכשולים רבים, ועוד שמהוה פירצה חמורה בחומת השבת, וקלות ראש בקדושת והלכות שבת. והמתבונן בשורש קולות אלו, יווכח כי מקורם באנשים המחפשים פתרונות לבעית הדת רח\"ל. וחלילה להקל או להסתמך על היתרים אלו. ועיין מ\"ש בחזו\"א בענין אחר, וז\"ל והרי אסרו כילה מפני שאינם בני תורה, והדבר מסור לחכמים לגדור גדר במקום פירצה, וזה יותר חמור מאיסור פרטי ליחיד, כי זה גדר לעם כולו ולדורות. עכ\"ל. עוד הזכיר מספר שבות יצחק דרזי ששמע מהגרי\"ש אלישיב זצוק\"ל, שאסור להשתמש בטלפון גרמא כמו טלפון רגיל ממש. ואפי' מי שצריך לטלפון בשבת משום פקוח נפש, עדיף שישתמש בטלפון רגיל, כדי שלא יטעה לחשוב שיש מקום להקל בטלפון זה כשאין היתר דפיקוח נפש. עוד הוסיף דאין להשתמש בכל המכשירים הנ\"ל, אפילו ימציאו אופן שלא יעשה בו שום איסור מדינא, דהוי פירצה גדולה.","b":false},{"t":"עו\"כ הגר\"נ קרליץ שליט\"א שם, (בהערה י\"א) וז\"ל וכשיסדו את בית החולים מעיני הישועה בבני ברק, הכריעו הרבנים שליט\"א וביניהם הגר\"ש וואזנר שליט\"א בעל שו\"ת \"שבט הלוי\" שאין להתיר בשום אופן התקנת \"מעלית שבת\" וכשמותר להשתמש במעלית משום פקוח נפש, ישתמש במעלית רגילה. עכ\"ל.","b":false},{"t":"והנה לעיל כתבתי שההמצאות הנ\"ל יפים הם לבתי חולים ולעניני ביטחון כגון מחנות צבא וכן מקומות רגילים שצריכים גם חייבים לערוך בדיקות שונות וכו'. והנה אנו רואים שהגאונים הגדולים הגרי\"ש אלישיב זצוק\"ל ויבלחט\"א הגר\"ש וואזנר שליט\"א לא ניחא להו להקל בכלים אלו, ואפילו בבתי חולים או בשעות קשות, אלא פסקו דבמקום פקו\"נ יתירו להשתמש במכשירים רגילים, שלא ילמדו מזה להקל רח\"ל.","b":false},{"t":"ואולם עדיין אני הקטן חושב דבבתי חולים רגילים, עדיף להשתמש במכשירים שממעטים ומרחיקים האיסור, כי יש רבים מהחולים וגם מהרופאים ושאר העובדים, שמקילים וחושבים כל דבר לפיקוח נפש, והואיל וקשה להעמיד מורה הוראה על כל דבר וענין, טוב שישתמשו במכשירים אלו, להרחיקם מאיסור תורה ממש, וכן הוא בדברים של ביטחון שהנטיה בצבור היא להקל, ולחשוב כל דבר לפקו\"נ, דטוב להשתמש במכשירים אלו. אך הבו לה דלא לוסיף עלה ח\"ו. אולם מחוץ לבתי חולים, ומקומות של צבא, ושאר עניני ביטחון, אין להתיר במכשירים אלו, שיש מהם שיש בהם איסורים גמורים, ויש שיש בהם כמה ספקות חמורים, וזה מלבד הפירצה בחומת השבת ויו\"ט, כגון מה שהם מתירים קלנועית לצרכי בית כנסת ולביקורים משפחתיים וחברתיים, וטוב שלא יבואו לביכ\"נ ויתפללו בביתם ביחידות, ולא ישתמשו בדברים אלו שהם אסורים איסור גמור. ויש בזה גם חלול שבת וגם חלול השם.","b":false},{"t":"ואלה המתירים הם פורצי גדר והמתבונן יראה במו עיניו איך שהם מאבדים קדושת השבת, ומעט מעט הופכים שבתם לחול, ולא ישקוטו ולא ינוחו עד שלא ישאירו זכר לשבת קדש, מלבד איזה סמלים נבובים ושדופים. ועושים בקלו\"ר לחבר נימא לנימא שלא כרצון ה' ורצון חכמיו ועבדיו, ונתלים באיזה דברים רחוקים שנכתבו ע\"י יחידים ואשר רוב ככל החכמים דחו היתרים אלו, וגם המתירים רובם ככולם דברו בחולים שיש בהם ספק פקו\"נ, או בסכנות של ביטחון וכנ\"ל.","b":false},{"t":"כ. עוד ראיתי בירחון פעמי יעקב (אב התשס\"ד) מאמר מהגאון רבי מנחם מנדל שפרן שליט\"א, שנתבקש להגיב על מאמר \"הדלקת נורה חשמלית שבת\" שבו פטנט חדש להדלקת נורה בשבת. ובתחילת דבריו העלה לפסול מאמר זה, שגם אם היה מותר עפ\"י דין גדרי עשיית מלאכה, הרי זה אסור מבחינת העמידה על משמר קיום הדת, שגם זה דין והלכה, והכרעת דברים אלו מסורה (לגדולי הפוסקים), ולא כל יודע ספר או עסקן צבורי נחון בכשרונות אלו וכו'.","b":false},{"t":"עו\"כ שהרעיון להדליק ולכבות אור החשמל ע\"י הארכת המצב הקיים, טוב גם כדי לנסוע באוירון והליקופטר בשבת, ולהפעיל מכונת כביסה וייבוש בשבת, ולעבוד במחשב, לבשל, לחרוש ולזרוע, ואפשר להתיר כל מלאכה ע\"י חיבור הפטנט לכל כפתור ושלטר, וע\"ש שהאריך עוד, ואפשר גם לכתוב עליו מיועד לשבת, וכו'.","b":false},{"t":"ומציין לשון הרמב\"ם ז\"ל (פכ\"ד משבת הלכה י\"ב וי\"ג) והעתיקו הב\"י (בריש סימן ש\"ח) וז\"ל אסרו חכמים לטלטל מקצת דברים בשבת כדרך שהוא עושה בחול, ומפני מה נגעו באיסור זה, אמרו ומה אם הזהירו הנביאים שלא יהיה הילוכך בשבת כהילוכך בחול וכו', ק\"ו שלא יהיה טלטול בשבת כטלטול בחול, כדי שלא יהא כיום חול בעיניו ויבא להגביה ולתקן כלים מפינה לפינה, או מבית לבית, שהרי הוא בטל ויושב בביתו, ויבקש דבר להתעסק בו, ונמצא שלא שבת ובטל הטעם שנא' בתורה למען ינוח, ועוד כשיבקר ויטלטל כלים וכו', ע\"ש. עו\"כ שם ועוד מפני שמקצת העם אינם בעלי אומנויות אלא בטלין כל ימיהם וכו', ואם יהיה מותר להלך ולדבר ולטלטל כשאר הימים, נמצא שלא שבת שביתה הנכרת, ומפני דברים אלו נגעו באיסור הטלטול וכו', עכ\"ל. וכתב הרב נר\"ו שרעיון זה גרוע הרבה יותר מכל מה שחששו חז\"ל בטלטול אבנים וכלים.","b":false},{"t":"עו\"כ שם באות ב' שנוגע רק בפרט א' בענין הלכה, שכותבי המאמרים ההם שסומכים על כלל: שמותר להאריך מצב קיים, ואסור לשנות מצב קיים. וזה אינו פסוק ולא משנה, עד שנקבע כללים ע\"פ זה. ועלינו לדון לגופו של ענין, שכאשר החשמל נכבה לשבריר של שניה, עד שעין האדם אינה מבחינה בכך וע\"י פעולת האדם נתפס המחשב לאותו חלקיק שניה ומשאיר המצב כך, זה כיבוי. וכן להיפך בהדלקה, וע\"ש שמבאר איך נדלקת האש ואיך נכבית ... ומזה דוחה מההלכה למ\"ש בעל המאמר.","b":false},{"t":"עוד מחלק בין זה ובין מכשיר שמיעה שנהגו בו היתר. וע\"ש.","b":false},{"t":"כ\"א. עוד ראיתי באוצרות ירושלים (חלק י\"ד סי' פ\"א) תשובת הרה\"ג ר\"מ שטרנבוך משנת התשל\"א, ושם בהערה מבואר תוכן השאלה שדן על רמקול שהמציא פרופ' זאב לאב, שעובד רק ע\"י טרנזיסטורים ולא מחובר לחשמל, וא\"א להפעילו רק ע\"י שעון שבת, ואינו מוליד כוח חדש רק משתמש בכוח שיש בה מקודם, ועשו כמה תנאים כמבואר שם היטב. שמשתומם על השואל בענין רמקול בשבת, והרי גם בחול אין להכניס בקביעות ולהשמיע ש\"צ ברמקול שזה חיקוי לריפורמים ועלול להביא לידי עוגב בביכ\"נ וכו'.","b":false},{"t":"ועוד שיש לאסור מדינא גם בחול, שאין יוצאין י\"ח בשמיעה מהרמקול, ורק אמן אפשר לענות דלא גרע מהסודרין באלכסנדריא דהיו עונים אמן. וע\"ש.","b":false},{"t":"ובשבת גם במכונה המוצעת ע\"י פרופ' לאב, יש בו משום איסור השמעת קול שהחמירו בו חז\"ל, שאסרו בריחיים (של מים לתת חטים אפי' מע\"ש) משום דאוושא מילתא, וכ\"ש להשמיע רמקול בביכ\"נ, אין לך השמעת קול יותר מזה, ועיין פמ\"ג בא\"א (א\"ח סימן ש\"ח ס\"ק ע\"ח) בשעון של משקולות דאסור כמו הריחיים הנ\"ל.","b":false},{"t":"ועוד דאסור משום מראית העין, שמי יודע לחלק בין זה לזה ואפי' מודיע שיש הכשר מהרבנות, לא ישכילו להבחין, ועלולים ללמוד להתיר הדלקת אלקטרו ורמקול בשבת רח\"ל. (ובאמת אין להם הכשר מהרבנות).","b":false},{"t":"וכתב דסוף דבר רמקול זה יביא לא רק לחילול השבת, אלא לביטול השבת, ומציין מעשה שראה באחת מערי אנגליא שהיה קשה עליהם לשמור שבת, ורב חשוב עשה מכירת החנויות לגוים בשטר מכירה כדין, והגוים התעסקו ולא היה שם ישראל כלל, ואחר שנים הבנים לא ידעו משבת כלל וכל העיר מחללי שבת בפרהסיא, משום שלא הבינו החילוק בין שטר מכירה ובלעדיה. ואם אמת שנהגו להקל באיזה בתיכ\"נ, אין לרבנים להמציא היתרים שיביאו ח\"ו להרחבת הפירצה.","b":false},{"t":"עוד דן שיש בו איסור בונה עפ\"י החזו\"א, ובלא\"ה יש בו איסור מגזירת מתקן כלי שיר, שהקלקול מצוי וכו'.","b":false},{"t":"עו\"כ שהיתר זה עלול להביא בכיה לדורות, ומצוה לפרסם בכל תפוצות ישראל שסדרי התפלה יהיו בלא רמקול. ע\"ש ביתר דבריו בזה.","b":false},{"t":"* * *","b":false},{"t":"וזאת תורת העולה מכל האמור, להלכה ולמעשה.","b":true},{"t":"אחר עיון מעמיק בדרכי הפעלתם של המכשירים החשמליים לסוגיהם, וכל הכרוך בזה והיוצא מזה. ואחר בדיקת ענינם במקורות ההלכה בגמרא ובדברי הפוסקים, ראשונים ואחרונים חדשים גם ישנים, עולה בבירור גמור ובלי שום ספק, שאין שום היתר להשתמש במכשירים חשמליים, ולהפעילם בשבת ח\"ו. ואפילו באופן שאין בו הבערה וכבוי, כגון שחיברו אותם בחשמל והדליקו אותם מערב שבת, אסור להפעילם ולהשתמש בהם בשבת, שאין אפשרות להפעילם בלא חילול שבת, באיסורים רבים ומגוונים, מהם דאורייתא ומהם דרבנן.","b":false},{"t":"ואשר על כן, אסור בהחלט להשתמש, בטלפון או מיקרופון (רם קול) או רדיו, וכל שאר המכשירים לא בשבת ולא ביום טוב.","b":false},{"t":"וקל וחומר שאין להשתמש בשום פנים, במכונית שנוסעים בה בשבת ונקראת \"קל נועית\", שמלבד שיש בה איסורי שבת רבים, יש בזה גם חילול ה' נורא.","b":false},{"t":"ופשוט וברור שמי שאין לו שום אפשרות להגיע לבית הכנסת, יתפלל ביחיד בביתו, ולא יחלל קדושת השבת, וקדושת השם יתברך.","b":false},{"t":"וגם הטענות המתחסדות להתיר רם קול כדי לזכות הרבים, ישתקעו היתרים אלו, ולא יעלו על לב.","b":false},{"t":"וכבר עמדו על זה גדולי הפוסקים וכפי שהבאתי מדבריהם בפנים, ומרן הראש\"ל הגאון רבי בן ציון עוזיאל ע\"ה בשו\"ת מפשטי עוזיאל, העלה שבכל הפעלה של מכשיר כזה יש בו חלול שבת דאורייתא, משום מתקן מנא. גם הגאון רבי משה פיינשטיין ע\"ה באגרות משה, ויבלח\"ט הגאון רבי שמואל וואזנר שליט\"א כתבו שיש בזה כמה חלולי שבת דאורייתא, ועוד איסורים רבים דרבנן. וזה מלבד רמיסת השבת וחלול ה'.","b":false},{"t":"והגם שהמציאו דרכים להפעיל מכשירים אלו. בדרך גרמא, כבר נדחו היתרים אלו מן ההלכה כמו שמבורר בפנים, ויש מגדולי הפוסקים (עיין במ\"ש משם הגר\"נ קרליץ שליט\"א בשם הגרי\"ש אלישיב זצ\"ל, ויבלח\"ט הגר\"ש וואזנר שליט\"א, ועוד). שהעלו שאפילו במקום של פקוח נפש ישתמשו במכשירים רגילים, ולא באלה שעשויים בדרך גרמא וכיו\"ב, כדי שלא ילמדו מזה להתיר מכשירים אלה ח\"ו.","b":false},{"t":"ואולם בעניותי העליתי, שבמקום ספק סכנת נפשות, כמו בבתי חולים, או בבדיקות בטחוניות, במחנות הצבא, או שאר מקומות המפוקחים ע\"י הצבא וכוחות הביטחון, באלה, טוב יותר להשתמש במכשירים הפועלים ע\"י גרמא וכיוצ\"ב, משום שיש נטיה בצבור להקל מפני הפחד של פקו\"נ, ופעמים מתירים בלא הצדקה, ע\"כ טוב שישתמשו במכשירים אלו במקום ספק סכנה.","b":false},{"t":"אבל במקום שאין סכנה אין להתיר בשום פנים שבעולם. ולא אעלים ששמעתי שמועה קשה, שיש אחד מחשובי המדענים, שמתכנן להביא המצאה, שתאפשר להפעיל את הרכבת הקלה, שהיא עובדת ע\"י כוח חשמלי, באופן שלפי דעתו אין בו חלול שבת כלל, וטוען שיש רב שהסכים עמו, רק התנה שהנהג והסדרנים יהיו גויים. ויוכלו להפעיל את זה בשבת לרווחת תושבי ירושלים. אוי לאזנים שכך שומעות ישתקע הדבר ולא יאמר. וכתבתי זה להראות לאיזה מצב עלולים להדרדר עם היתרים כאלה רח\"ל.","b":false},{"t":"ויהי רצון שהקב\"ה יערה עלינו רוח קדושה וטהרה, ויאיר עינינו בתורתו, וישים בלבנו אהבתו ויראתו, ולא נבוש ולא נכלם, ולא נכשל לעולם ועד.","b":false},{"t":"המצפה לישועת ה' ברחמים.","b":false},{"t":"שלמה משה עמאר","b":false},{"t":"ראשון לציון הרב הראשי לישראל","b":false},{"t":"הנני כיהודה ועוד לקרא לכל האמור לעיל בפס\"ד הבהיר של כמו\"ר הראשל\"צ נר\"ו בדבר האיסור בשימוש מכשירים חשמליים בשבת וביותר במכונית \"קלנועית\" ואשר בלא ספק שיש כאן איסור חמור הפוגע ביסודות הלכות שבת החמורה וזאת מלבד חילול ה' הגדול שבעצם הנסיעה ברחובות העיר ובחצרות ה'. ביום השבת ...","b":false},{"t":"ואני מוסיף שלענ\"ד מן הראוי שגבאי בית הכנסת לא יצרפו למנין את אלה המגיעים לבית הכנסת בקלנועית בשבת ומכל שכן שאין להעלותם לספר תורה.","b":false},{"t":"ולמזהיר ולנזהר ירבה שלומם כמי נהר. אכי\"ר.","b":false},{"t":"ציון בוארון","b":false}]},{"t":"בשימוש במכשירים חשמליים בשבת מה מותר ומה אסור א","p":[{"t":"בס\"ד, רמת הגולן, מוצש\"ק עקב התשע\"ב.","b":false},{"t":"א. הן ידוע שהתפתחות הטכנולוגיה בדורנו גדלה והתרחבה מאד, והעלתה שאלות רבות וקשות בכל תחומי ההלכה ובמיוחד בדיני שבת החמורים מאד, ודנו בהם גדולי האחרונים, וכפי התחדשותם של השאלות רבו בהם הדעות וגם מחלוקות, שפעמים נבעו מהבנות שונות ברזי הטכנולוגיה, ופעמים נחלקו בגופם של החידושים לאיזה אבות מלאכות או תולדות לדמותם, או לאיסורי רבנן וגזירותיהם, או דיש למנותם בין הדברים המותרים, זה אומר בכה וזה אומר בכה, וכמו שהטכנולוגיה עוררה שאלות חדשות ואתגרים הדורשים פיתרונות הלכתיים, כן ידעה הטכנולוגיה גם למצא פיתרונות לבעיות חמורות, ע\"י דברים הנעשים מאליהם, וגם באלו רבו הדעות וכדרכה של תורה, והדברים ממשיכים עד עצם היום הזה, ועד בכלל. ועינינו הרואות חדשים לבקרים, יום יום וחידושיו, וחכמי ישראל נדרשים להורות לעם ה' את דבר השם זו הלכה, כדת מה לעשות. ומחפשים פיתרונות לבעיות חמורות בשבת קדש, ובפרט בבתי חולים ובעניני ביטחון במקומות שונים ומגוונים. שבלא\"ה יש דברים רבים שהם בגדר ספק פקוח נפש, או קרוב לזה, וע\"י ההמצאות החדישות שהדברים פועלים מאליהם בדרך אוטומטית, או שמבוססים על דרך שממעטת האיסור. ובעת האחרונה קמו גופים שמטפלים בדברים אלו בטוטו\"ד, ונמצאו פתרונות גם לשאלות מיוחדים שמתעוררים במחנות הצבא, ובמקומות שיש עליהם שמירה תמידית וכן בבתי חולים. שיש דברים רבים שנאלצים לעשותם גם בשבת ויו\"ט מפני חשש פקוח נפש, וע\"י המצאות אלו, מתרחקים מחילול שבת ומועד כמה שאפשר, וכל מה שממציאים עושים הכל על פי ההלכה, ותע\"ב.","b":false},{"t":"ואולם יש מתוכם שהרחיבו את השימוש בזה גם לדברים אחרים, ועשו דברים שאין דעת חכמים נוחה מהם, ויש בהם גם איסורים רח\"ל, כגון רם קול לבתי כנסת וכדו', שיש בזה חילול השם, ואין שום סיבה של פקוח נפש או ספק פקו\"נ שבגללה צריכים ליזקק להיתרים דחוקים ולא נכונים, וכן המציאו קל-נועית לזקנים ומתירים לנסוע בה בשבת ועושים שבתם חול גמור, ובדרך זאת ודאי שילכו וירחיקו כל כבוד השבת וקדושתה בטענות שונות, ובהתרים רחוקים מדרך התורה.","b":false},{"t":"והנה דרכם של המחדשים לחפש וליתלות באילני רברבי, ולא יסתפקו ברבנים רגילים רק יחפשו ליתלות בגדולי החכמים, וכן היה מאז ומתמיד, וגם אלו שעקרו גופי תורה, היו נתלים בפסוקים מן התנ\"ך ובאגדות חז\"ל, ובספרי האמונות והדעות וכן בספרי השו\"ת לדורותיהם, וכל הרוצה לטעות ימצא לו מקור כוזב לטעותו, ומנסה להדבק בו, כדי להצדיק דרכו בעיני הבריות, וכדי להשקיט מצפונו שלא יוסיף להציק לו.","b":false},{"t":"ומעשה היה בפאריז העיר הגדולה, שבבית כנסת עתיק וחשוב החליטו להכניס רם קול לדרוש בו בשבתות באומרם שרצונם לזכות הרבים, ורבה הראשי של פאריז המנוח בנן של קדושים, אראלים ותרשישים הרה\"ג רבי דוד משאש ע\"ה נחרד מזה עד עומק לבו, ושלח לי שאלה בהולה בענין, ומיד כתבתי לאסור בכל חומר הדין, ועליתי ושאלתי את פי גדול דורנו בעל יבי\"א שליט\"א והסכים עמי בפשיטות, וגם אישר את זה בכת\"י ובחתימתו, ושלחתי להם תכומ\"י ונתבשרתי שבו ביום ביטלו את זה והרחיקוהו לחלוטין. ת\"ל. וכן היה במדינות אחרות שהשפעתי עליהם והרחיקו את זה.","b":false},{"t":"וכפעם בפעם מתעוררות שאלות בכגון אלו, ויש המנסים להקל, ואם כי כוחא דהיתרא חשוב הוא וגם עדיף, אך זה בענינים קשים שאין להם פיתרון, כמו עגונות, וילדים שנפל עליהם חשש דספק ממזר וכל כיוצ\"ב, שבזה אנו ממשכנים נפשנו בעמל ויגיעה עצומים, ומחפשים חיפוש מחיפוש כדי למצא מזור ולהעלות גהה למכתם האנושה, שהיא מכה שאין לה רפואה, ובחסדי ה' לא נחים ולא נותנים שנת לעינינו ולא תנומה לעפעפינו, כדי למצא פתח להיתר ולפדותם מרדת שחת, והכל בגדר ההלכה הצרופה והברורה, בהסתמך על יסודות נאמנים מן התלמוד וגדולי הפוסקים קמאי ובתראי, ומסתייעים מפי גדולי המורים בדורנו מפיהם ומפי כתבם הלא בספרתם, ברוך שבחר בהם ובמשנתם.","b":false},{"t":"ב. וראיתי שרבים מהמתירים בענינים החשמליים נתלים בדבריו של הגאון הגדול המפורסם כמוהר\"ר רשז\"א ע\"ה במנחת שלמה ח\"א (סימן ט' אות ב') שדן בענין רם קול בשבת ויו\"ט שלא לצרכי תפילה, (שכבר העלה באות א' שם שאין להשתמש במיקרופון לתפלה ולמקרא מגילה וכיוצ\"ב. שא\"א לצאת י\"ח בשמיעה דרך מיקרופון וכיוצ\"ב, שאין זה הקול של החזן, וכמ\"ש שם באורך.) ובאות ב' דן מצד השמוש ברם קול שהיה דלוק ומחובר לחשמל מיום ששי, או נדלק אוטומטית בשבת, באופן שאין יד אדם נוגעת בו בשבת, רק הדיון הוא אם מותר להשמיע בו קול ביום השבת. וכן אם מותר לשמוע שיעורים ברדיו שנשאר דלוק מיום ששי, (באופן שכל המשדרים וכו' המה נכרים).","b":false},{"t":"וכתב בזה\"ל: ונראה דמה שרגילים בשעת השמוש לשנות את הקול, (ברדיו, מגבוה לנמוך ולהיפך), או להעביר הקליטה מגל לגל, מסתבר דאין בזה שום איסור, כיון שלא נעשה בכך שום כבוי והדלקה, הואיל ובסיבוב הרגולטור משתנה רק כוח הזרם, שעובר דרך המנורות מבלי להשפיע כלל על האש עצמה שבתוך המנורות.","b":false},{"t":"עוד כתב שם, וגם לפי המבואר באות הקודם, שהממברנה עצמה חשובה כמשמעת קול, וממילא יש לדון שהמדבר בקירבת מיקרופון יחשב כמשמיע קול ע\"י ממברנה, כיון שכל זה נעשה ע\"י הקול היוצא מפיו, דהו\"ל ממש כוחו, כמו מכבה נר ברוח פיו, או מנפח בכלי זכוכית, דחייב. וכן לענין נזיקין, חמור שנער או סוס שצנף תוך כלי ושברו את הכלי, חייבין לשלם, מ\"מ נראה דלא מצינו איסור השמעת קול כי אם ע\"י מעשה ולא בדבור גרידא, אע\"פ שגורם בכך שגם הכלי ינגן בדיוק כמותו, ומה שע\"י דיבורו הוא משנה את עצמת הזרם להיות פעם חזק ופעם חלש, האי נמי לאו כלום הוא, ורק אם מדבר לפני תקליט שקולט את הקול, כתבו האחרונים דאסור משום דחשיב כעושה כלי בדבורו, משא\"כ כאן אעפ\"י שע\"י דבורו משנה גם את סגולת המגנט אפ\"ה נראה דלאו כלום הוא. עכ\"ל.","b":false},{"t":"וע\"ש שמיד אחרי זה הביא דברי בית יצחק יו\"ד ח\"ב דאוסר בזה, ונושא ונותן בדבריו כדרכה של תורה והעלה במסקנתו דאין להתיר כלל וכדלהלן. מ\"מ המקילים שהרחיבו קולותיהם נתלים בדבריו הראשונים של הגרשז\"א ע\"ה ובונים עליהם מגדלים, ומעלימים עיניהם ממסקנתו ששב והעלה לאסור בזה. וע\"כ אמרתי לבדוק את דבריו הראשונים שבהם הראה פנים להתיר, בעיון הראוי להדר\"ג של האי גאון אמיתי שהרעיש העולם בחריפותו ובגאונותו ובענוותו, זיע\"א. ואע\"פ שידעתי מיעוט ערכי ודלותי וקטנותי, תורה היא וכונתי לכבוד השם ולכבוד השבת ולכבוד עם ישראל שלא תפגע קדושת השבת שהיא נשמת אפינו. ובפרט שגם הוא עצמו חזר ואסר.","b":false},{"t":"תחילה וראש יש להעיר בדב\"ק של המנחת שלמה, במה שכתב דאין בזה משום השמעת קול. וז\"ל דלא מצאנו איסור השמעת קול כי אם ע\"י מעשה ולא בדבור גרידא, אע\"פ שגורם בכך שגם כלי ינגן בדיוק כמותו, ומה שע\"י דבורו משנה את עצמת הזרם להיות פעם חזק ופעם חלש, האי נמי לאו כלום הוא, ורק אם מדבר לפני תקליט שקולט את הקול, כתבו האחרונים דאסור משום דחשיב כעושה כלי בדבורו. וכו' עכ\"ל.","b":false},{"t":"ואחר שהגאון מסכים דיש בזה משום השמעת קול ע\"י כלי, מה דחיה היא זו, דלא מצאנו השמעת קול כי אם ע\"י מעשה ולא בדבור גרידא. וכי ישבו חז\"ל ופירטו כל סוגי השמעות הקול למיניהם וקבעו איזו לאסור ואיזו להתיר, עד שכותב הגאון זללה\"ה דלא מצאנו איסור השמעת קול אלא במעשה ולא בדיבור. וחז\"ל אסרו להשמיע קול בשבת ויו\"ט ודנו על דברים שאירעו לפניהם, וכמו שדנו על אותו מעשה שאחד הכה באגרופו על הדלת, במס' עירובין (ק\"ד ע\"א). וכדלהלן. ולשיטת הגאון ז\"ל שבא לאפוקי השמעת קול ע\"י פיו, האם יעלה בדעת לומר שמותר לחלל בחליל, ולחצרר בחצוצרה וקלריניט וכל כיוצ\"ב, משום שזה נעשה בהבל פיו ולא ע\"י מעשה, אתמהה, אלא נבאר שכונת הגאון ז\"ל, להשמעת קולות שלא דרך כלי זמר שמיוחד להשמיע שיר וניגון, א\"כ י\"ל דלא היה להם דבר כזה שישמיע קול בלי ניגונים, שמופעל בלי ידים רק ברוח הפה, וע\"כ נקטו הדוגמאות הרגילות. ואין מזה הוכחה לשלול השמעת קול של דיבור ע\"י מיקרופון, ולומר שבזה לא גזרו חז\"ל, אלא גזרו שאדם לא ישמיע קול, וזה משמיע קול בכוחו ממש. שהרי ברוח פיו הוא מפעיל את המיקרופון וע\"י זה נשמע קול גדול, ובשלמא אם הרם קול היה משמיע את קולו של זה המדבר בו, רק מגבירו שיגיע למרחקים, היה אפשר לומר דזה קולו של האדם ולא גזרו לאסור בזה כלל, שאם ידבר תוך חצוצרה גדולה שהיא מגבירה את קולו, אבל אין בה שום פעולה ואין בהם שום כוח לא של חשמל ולא כוח אחר כלל, רק המבנה שלה מגביר הקול, בזה באמת לא גזרו, תדע שאפילו בשופר אמרו שאינה מלאכה. אבל מיקרופון שיש בו כוח חשמלי או סוללה שמפעילה אותו, ועוד שהוא מיצר קולות חדשים לגמרי ע\"י פעולתו שמפעילו בהבל פיו, או ע\"י כל קול שנשמע בו, שהקול היוצא מן הרם קול אינו קולו של האדם שדיבר בו או שר בו, אלא קול אחר חדש לגמרי שנולד זה עתה על ידי מכשיר זה. והגאון ז\"ל עצמו כתב כן באות א' שם, וביאר באה\"ט שמשום כך אין יוצאין י\"ח מגילה ותפלה ע\"י רם קול, שאין זה הקול של הקורא או החזן, ולא כמו שטועים העולם לחשוב שקולו של המדבר הוא שהולך למרחקים ע\"י הרם קול, אלא יש במיקרופון חלק שקולט הדיבור או שאר קולות והופך אותם לגלים חשמליים, ומיד עוברים לחלק אחר שנקרא ממברנה, שהוא קולט את הגלים החשמליים והופך אותם לקולות, ואמנם הם דומים לקולו של המדבר או לקול הניגון שמשמיעים בו, דמיון מוחלט, אך אלו קולות חדשים לגמרי. כך כתב הוא ז\"ל וביאר הדברים באה\"ט. והואיל ובסופו של דבר יוצאים קולות חדשים מתוך המיקרופון, והם נוצרים ונעשים מכוחו של האדם ממש, מה לי אם כוח זה הוא מכוח ידיו או מכוח פיו, הרי גם רוח פיו הוא כוחו, וכנ\"ל, וממילא נכלל גם זה בכלל האיסור שאסרו להשמיע קול בשבת. ופשוט.","b":false},{"t":"ועוד דלדעת הרא\"ש ושאר ראשונים וכ\"פ הרמ\"א בהגה, דגם השמעת קול בלא שיר אסור, דלא כהרי\"ף והרמב\"ם ז\"ל, ואחר שברור ופשוט דאסור לנגן בכלי שיר המופעל רק ע\"י הפה בלא ידים, איך נתיר להשמיע קולו ברם קול, והרי ההבל היוצא מפיו הוא כוחו ממש לכל דבר וענין, וכמ\"ש הוא ז\"ל גופיה, וכנ\"ל. ונמצא דבדיבור ברם קול הוא משמיע קול חדש ע\"י כוחו ממש, כמו משמיע קול בידו. ומה גם שהמיקרופון מיועד גם לשירה וזמרה ולא רק לדיבור.","b":false},{"t":"ג. עוד יש להעיר דאחר שהסכים הגאון ז\"ל לדברי האחרונים, שאם מקליט דבורו במכשיר הקלטה (טייפ) חשיב כעושה כלי בדבורו ואסור. א\"כ איך נתיר הרם קול, והרי גם כאן נעשה כעין הקלטה, שבהקדמה לתשובה זו כתב בראשית דבריו בזוה\"ל. מיקרופון, קולט גלי קול והופך אותם לזרמים חשמליים, השינויים בזרם עם הזמן וכן עצמת הזרם אופייניים לקולות שנקלטו ע\"י המיקרופון, המיקרופון בנוי וכו', כך הם מגיעים למכשיר הקולט המכיל \"אזניה\" או רם קול, ההופך את זעזועי הזרם בחזרה לקולות, וכו' עכ\"ל.","b":false},{"t":"נמצא שהתהליך הוא שהקולות נקלטים תחילה ע\"י חלק מהכלי ונהפכים לזרמים חשמליים, ושוב נקלטים ע\"י מכשיר הקולט שיש בו אזניה וכדומה, ושוב נהפכים מזרמים חשמליים לקולות, ונשמעים באותו עובי ובאותו טון שבה נאמרו, עד שאפשר לזהות מי המדבר ע\"י טביעות עינא דקלא, בין ברם קול ובין בטלפון כידוע.","b":false},{"t":"והנה לא מיבעיא אם המכשיר קולט הקול כמו טייפ ומעביר אותו למרחקים ומשמיע את ההקלטה, וכדרך שנעשה בפקס שקולט הכתב בשלב ראשון לתוכו, ואח\"כ משגר מההקלטה לכל מקום שהוא מיועד, שלפי זה בודאי צריך לומר שיש איסור שנחשב כעושה כלי בדבורו, וכמ\"ש הוא ז\"ל משם האחרונים והסכים עמם.","b":false},{"t":"אלא גם אם אכן אינה הקלטה ממש כמו טייפ, רק היא הופכת הדבור לזרמים חשמליים, וזרמים אלו נקלטים במקלט שהופכם תיכף לקולות כשהיו מתחילה, סו\"ס יש כאן הקלטה והוצאה בחזרה שתי פעמים, וזה נעשה ע\"י קולו שהוא כוחו ממש. ואפילו שזה שונה מטייפ, סו\"ס גם בהקלטה הרגילה אין נעשה ציור הנראה לעיין, או שאפשר למששו ביד או באצבע, הכל נעשה רק באופן שהמכשיר יודע לקרא ולהשמיעו וגם להראותו כאשר הוא מצולם או מוסרט, ואין בקולטים של ימינו אפי' סרט שמסתובב ולא שום דבר ממשי רק הכל אלקטורני, עד שתמצא מכשיר שהוא פחות מכזית במשקלו, ואין בו זרת באורכו וברוחבו, ודק מאד, ויכול להכיל בקרבו אלפי שירים, ארוכים וקצרים, וכן סרטי שמחות וצילומים ועוד כהנה וכהנה לאין מספר, ואם תפתחהו לחפש מי השר ומי מנגן ומי מראה ומי משמיע, לא תמצא אחד מהם ולא שום ענין כלל. ואם בהקלטה זו חשיב כעושה כלי בדבורו, למה הקלטת קולות והפיכתם שתי פעמים, פעם נקלטים קולות ונהפכים לזרמים חשמליים, ובפעם השנית נקלטים זרמים בחלק אחר ונהפכים לקולות, למה זה לא יחשב עשיית כלי בדבורו. ואעפ\"י שבטייפ זה נשמר וניתן לשמוע את זה בכל עת, וכאן זה רק לרגע זה, נלע\"ד דאין זה משנה להלכה דענין ההקלטה נעשה באותה מדה, ומה שאפשר לשומרו, אינו מעיד שההקלטה שונה מזה לזה.","b":false},{"t":"ומלבד האמור יש עוד נקודות לדיון, ועדיין אני מהרהר וצריך לברר היטב, האם הגברת זרם החשמל והפחתתו אינה פעולה אסורה, והרי ידוע שכשמשתמשים בכמות גדולה של חשמל אנשים רבים, גורם להפחתת הכוח החשמלי בחברת החשמל, ופעמים כמו בזמן קיץ שכולם מפעילים מזגנים וכו', אין החברה יכולה לעמוד בלחץ, ויש הפסקת חשמל, והכונה לכאורה שהחשמל נשרף ומתכלה, וצריכים ליצר אחר, ואעפ\"י שאיני יודע טיבו של כלוי זה, האם אין בזה שריפת אנרגיה כמו שריפת גז או שמן או נפט וכל כיוצ\"ב. והאם אפ\"ל על כל זה שאינו כלום. ועי\"ל במה שאכתוב בעהי\"ת מדברי מומחה גדול.","b":false},{"t":"ד. וכן נמי יש לדון בדין העברת תחנות, ע\"י סיבוב הרגולטור שמעביר הקליטה מגל לגל, האין זה מעשה בידים שמשמיע קול, שהרי עד עתה היה שקט לגמרי, וע\"י הסיבוב וההכוונה לתחנת היעד מתחיל להשמיע קולות ומנגינות וכו', ולכאורה הוא משמיע קול בפועל ע\"י הכוונה זו. ולא עוד אלא גם אם היה משמיע שירים מתחנה פלונית, והעבירו לגל אחר ובזה שומעים עתה שידורים אחרים שלא היו נשמעים עד רגע זה, האין זה השמעת קול ע\"י מעשה שעשה בידיו בהעבירו את התחנות. וכי אם יפרוט על פסנתר (מיכני או חשמלי שהוא דלוק מאתמול), בנגיעת אצבעותיו בכפתורים, אינו נחשב למשמיע קול בידיו, והגם דשם משמיע קול חדש המיוצר באצבעותיו זה עתה, וכאן הקולות היו בעולם באותה תחנה, וכל המגיע לקלוט אותו גל שומע אותם שידורים, מ\"מ במכשיר זה, ובמקום הזה לא נשמעו עד עתה קולות אלו, וע\"י פעולתו מתחילים להשמע, ואע\"ג שלא הוא שיצר אותם קולות, מ\"מ אפשר שנכלל באיסור משמיע קול. ובמיקרופון ודאי גרע טפי שע\"י שמדבר או שר בו, הוא מיצר קולות חדשים ממש. וכמובן יהיה דיון אם לא משמיע שירים ומנגינות אלא רק קול דבור, שנחלקו בזה מרן והרמ\"א עפ\"י שיטות הראשונים. (כמבואר בב\"י רי\"ס של\"ח).","b":false},{"t":"גם העובדא שכתב הרב זללה\"ה שם, וז\"ל, ומה שע\"י דבורו הוא משנה את עצמת הזרם פעם חזק ופעם חלש, האי נמי לאו כלום הוא. עכ\"ל. וגם מתוך דברים אלו, הרי רואים את כוחו בפיו כמו כוחו בידיו, שגם בפריטה על גיטרה או פסנתר וכיו\"ב או בתיפוף בתוף ומחול, שאם מגדיל עוצמת ההכאה או הפריטה, גובר כוח השמעת הקול, וה\"נ ע\"י הגברת קולו לרמקול גוברת עצמת הזרם, וכן להיפך, והרי זה ממש פועל פעולתו ועולה ויורד כפי שהוא קובע ונותן כוחו, ומרבה הזרם וממעטו וע\"פ מ\"ש לעיל אפשר שמרבה להבעיר בסופו של דבר (ועדיין צריך עיון בזה).","b":false},{"t":"ובאמת כתב שם: אולם ראיתי בשו\"ת בית יצחק יו\"ד ח\"ב במפתחות לסי' ל\"א, דס\"ל דעצם הדבור בטלפון, אסור משום השמעת קול ע\"י כלי, וכו'. וע\"ש דמסתייע מיניה למה שהעלה באות א' שם, דאין יוצאין י\"ח של מקרא מגילה או שופר ע\"י רמקול או טלפון.","b":false},{"t":"והקשה על הבית יצחק דלדבריו שיש בדבור בטלפון איסור השמעת קול, א\"כ אסור לדבר בשבת עם כבדי שמיעה שמשתמשים במכשיר שמיעה. שהמדבר אליהם מכוין להשמיע קול ע\"י המכשיר, והיה אסור להעלותם לתורה, שהקורא ודאי מכוין להשמיע קול הקריאה לאזני העולה. וגם הוא עצמו כשקורא ק\"ש צריך לכוין שלא ישמיע קולו לאזניו ע\"י המכשיר, והוא פלאי. וכו'. עכ\"ל.","b":false},{"t":"ולענ\"ד יש מקום לחלק בין מדבר ברם קול או טלפון, ובין המדבר לאיש אשר לו מכשיר באזניו. שזה מדבר במכשיר להפעילו להשמיע קולו לרבים וגם למרחקים, ולזה אין ענין להגביר קולו, רק מדבר אליו, והוא השומע שם לעצמו כלי עזר כנגדו, ועוד שפעמים מבין מתנועת השפתים, או הבעת פנים ואינו פסי\"ר. עוד צריך לחקור דאפשר שיש הבדל יסודי במכשיר שנותן באזניו שיתכן שהוא מגביר הקול באופן ישיר ולא עובר כל המעברים שעובר הדיבור ברם קול, שנהפך לזרמים וחוזר ע\"י מקלט ונהפך מזרמים חשמליים לקול, וכאן אפשר ששונה מזה, וצ\"ע.","b":false},{"t":"וגם בקריאת התורה, אם קורא לעצמו ולא שמע מהקורא ודאי יצא י\"ח בדיעבד, ואם כן אין הכרח גמור שישמע במכשיר, דאפשר שיכוין לעצמו. ועיקר כונתו של הקורא, הוא לצבור ששומעים קריאתו בתורה, עכ\"פ לא דומה ענין זה של בעל המכשיר לענין הנדון באדם המדבר ברם קול או בטלפון. ובעהי\"ת עוד ארחיב לחלק ביניהם בטעם ובסברא אי\"ה ברוך הוא. לאחר שאלמד הענין המקצועי מפי מומחים.","b":false},{"t":"עו\"כ הגרש\"ז שם, אולם לענ\"ד נראה שזה רק דיבור גרידא, ואין זה אלא אולודי קלא של אדם ובכגון דא לא גזרו רבנן, אף שודאי אסור להשמיע קול אדם בשבת ע\"י כלי המיוחד לכך כמו תקליט וכדו', היינו מפני שהפעלת הכלי שמשמיע קול הוא אסור, אבל אם הכלי ערוך מאתמול, לא מצינו שגזרו חכמים על אדם שלא ידבר או לא ינגן בפיו, מפני שקולו עובר גם דרך כלי ונשמע למרחקים. וכמו שהבית יצחק עצמו מביא שם משם השבות יעקב. ע\"ש.","b":false},{"t":"ובער אני לא אדע מה טענה היא שלא מצינו, ודבר זה לא היה מעולם, ואיך נמצא מקום שגזרו עליו טרם הרים יולדו. והם גזרו על השמעת קול ע\"י כלי, וגם כאן משמיעים קול ע\"י כלי, והיה מקום להבין טענה זו, לו אמרנו שקול האדם המדבר הוא עצמו טס באויר ומגיע לכל מקום שנשלח שם, אך כבר העלה בפשיטות שם שאינו כן, רק הגלים והזרמים החשמליים הן המה שהולכים ונקלטים שם ונהפכים לגלי קול, וא\"כ זה קול אחר בפועל, ולמה אין בזה השמעת קול ע\"י כלי, האם מפני שקול זה שנשמע דומה וזהה לקול האדם, נשתנה דינו ונוציא אותו מן הכלל של איסור השמעת קול, ולא הוציאו וחילקו אלא בין קול של שירה לקול בעלמא וגם זה תלוי במחלוקת האמוראים בגמרא, וכן נמי בפלוגתא דרבוותא קמאי ובתראי. אבל בין קול הדומה לאדם המדבר ובין קולות אחרים לא שמענו שיחלקו.","b":false},{"t":"ומ\"ש דאין זה אלא אולודי קלא עיין להלן שאכתוב בעה\"ו, שיש איסור בהולדת קול מצד עצמו, ולא משום שמא יתקן כלי שיר.","b":false},{"t":"ה. עוד כתב הגרשז\"א ז\"ל שם, וז\"ל, ואע\"ג דיש לחוש שמא יבא לתקן את הכלי כדי להשמיע היטב מה שמדבר או מנגן בפיו, מ\"מ נלענ\"ד דאין זה כלול בגזירת חז\"ל, והו\"ל כגזירה חדשה ואין לנו להוסיף על הגזירות. עכ\"ל. וגם זה נמשך מהטענה הקודמת שזו גזירה חדשה. ומלבד מה שכתבתי, הנה גזרו גם במכה בידו על טבלא או על דלת או ברגלו בקרקע וכו', כלומר בכל גוונא אסרו להשמיע קול, ולמה השמעה זו שהיא חזקה וברורה תהיה שונה, ועל כל הקולות גזרו ולא חילקו, וגזירת תיקון שייכת בזה, יותר מכל שאר הענינים כולם, ובודאי דכשמתופף באצבעותיו על השולחן אין בו תיקון כלל, ואפ\"ה גזרו, וק\"ו בן בנו של ק\"ו בזה, שתמיד מצויים ריעותות ברמקולים וגם בטלפונים, ופעמים שצריך לסגור ולחדש ההדלקה והוא מאד מצוי וזה גלוי וידוע לכל, שכמה פעמים עומד אדם לשיר או לדבר דרך רם קול, ויוצאים קולות משונים, או שלא משמיע קול וסגר עליהם המדבר, עד שמתקנים, או מחברים מחדש, או מחליפים מקום החיבור, ובשני אלו יש כבוי והבערה. ועוד כהנה וכהנה מן הקלקולים, וכן הוא בטלפון גם כן מעשים בכל שעה, שצריך לסגור ולהתקשר מחדש. ופעמים שצריך לחבר כל המערכת מחדש, ועוד כהנה וכהנה תקלות רבות ומצויות, ואיך נתעלם מזה בטענה סתמית שהיא כגזירה חדשה.","b":false},{"t":"עוד כתב שם: ואף שקול המדבר עושה במכשיר שינויים כבירים בזה שגלי הקול משתנים לגלי חשמל, ושוב חוזרים אח\"כ לגלי קול, מ\"מ א\"א לנו לחדש איסור שלא נזכר כדבר הזה בש\"ס ופוסקים, כיון שעינינו רואות שהוא רק משמיע בכך את קולו לאזנו של השומע. עכ\"ל.","b":false},{"t":"וכבר כתבתי שכיון שכבר העלה בפשיטות שאין זה קולו שעובר, ושעל כן אינו יוצא י\"ח ע\"י מכשירים אלו, אז אין מקום לטענה זו. ועוד שמה שגלי הקול משתנים שינויים כבירים כלשונו, כבר כתבתי לעיל, דעי\"ז נחשב כמו מקליט בטייפ שהוא ז\"ל גופיה הסכים לאחרונים שאסור דחשיב כעושה כלי בדיבורו.","b":false},{"t":"עו\"כ שהיה מקום לדון על העברה מגל לגל, דכמו שאסור לנעוץ מחט של גרמופון תוך חריצי התקליט כדי להשמיע קול, דאע\"ג שאפי' לצפצף בפה קול שיר שרי, מ\"מ כששומעים מגראמופון אסור אפי' קול דברים בעלמא, חשיב שפיר כהשמעת קול ע\"י כלי המיוחד לכך ואסור. והיה נראה שגם בנד\"ד הרדיו והרם קול אף אם רק משמיעים קול נגינה, או שיחות אנשים, הרי זה חשיב לפי דברינו כאילו הקרטון של הרם קול והממברנה של הרדיו משמיעים קול כמו תקליט של גראמופון, ולפי זה בשעה שמעביר הקליטה מגל לגל, או משנה עצמת הזרם, חשיב אז כנועץ המחט בתקליט, או כמתקן כלי זמר כדי לשכלל הקול, אפ\"ה נראה דאפשר דשאני הכא כיון דהשמעת קול לא נעשית ממילא, כי אם ע\"י זה שמדבר או מנגן ע\"י המיקרופון לכן גם השמעת הקול מתיחסת רק אליו, ולא לזה שמסבב את הרגולטור (ומשום תיקון כלי יתבאר באות הסמוך דבכה\"ג לא מיקרי מתקן כלי) וקיל טפי אפי' מגרמא, וכ\"ש באופן ששומעים רק קול דברים ולא קול שיר אפ\"ל דבכה\"ג לא גזור רבנן, (ועיין ערוה\"ש או\"ח סימן של\"ח שמצדד להקל במזלג של חזנים, גם מפני שכל תכליתו רק בשביל שירת פה שלא נאסרה. ע\"ש). עכ\"ל.","b":false},{"t":"והנה ההשואה שעשה בין פעולה ההעברה של הרגולטור שמחליף תחנות, או הדיבור במיקרופון ובין שימת מחט הגרמופון בתקליט לכאורה נכונה היא.","b":false},{"t":"ומה שכתב לחלק דשאני הכא שהשמעת הקול לא נעשית ממילא כי אם עי\"ז שמדבר או מנגן ע\"י המיקרופון, וע\"כ גם השמעת קול מתיחסת רק אליו, ולא לזה שמסבב הרגולטור וכו' עכ\"ל. הנה כבר כתבתי שאחר שהסיק והעלה דאין זה הקול של המדבר ולא יוצאים בו י\"ח וכנ\"ל, א\"כ כשהוא מדבר במיקרופון קול היוצא מהמכשיר, אינו קולו של המדבר או של השר אלא הוא קול אחר לגמרי וכנ\"ל. ודיבורו או שירתו של זה ששר בתוך המיקרופון חשיב הפעלה שמפעילו ע\"י כוחו שהוא קולו, כמו שמפעיל כלי נגינה אחר באצבעותיו, כן זה מפעיל בקולו, ושניהם כוחו של האיש, וגם המחליף תחנות ברדיו, אעפ\"י שיש משדר ושר, מ\"מ אינם כאן ולא נשמעים כי אם ע\"י פעולת האיש שמסובב את הרגולטור, ומעמידו בתחנה זו או אחרת, ויש לומר שזה המעביר את הגל הוא זה שמשמיע קול ברעש גדול ביום שבת, והרי הוא בכלל הגזירה של חז\"ל שגזרו ואסרו השמעת קול בשבת. ולמה תיגרע פעולה זו מפעולת נגינה בכלי נגינה וכיו\"ב.","b":false},{"t":"ובענין תיקון כלי כבר כתבתי דכן שייך גזרה זו במכשירים אלו וגם שהוא מצוי ביותר, וכנ\"ל. ומה שהביא מערוך השלחן שאני התם דהכלי עצמו לא משמיע קול כלל, כי אם לאוזנו של החזן כדי שישיר, ובזה הוא דאמר שכיון שעשוי רק לתכלית שישיר בפיו, יש מקום להקל, אבל כאן שמשמיע קול במכשיר זה וגם בשעה שהוא מדבר או שר, אין זה קולו של השר והמדבר שנשמע דרך המיקרופון, אלא קולו מפעיל מנגנון שבסופו של דבר, משמיע קול אחר לגמרי שנולד זה עתה, קול חדש שלא היה בעולם, ואם כי הוא דומה במאד מאד לקולו של השר או המדבר, ברי לן שאין זה קולו, ואיך נדמהו לההיא דערוה\"ש שמשמיע קול הטון לאזניו ותיכף שר בפיו ולשונו, ואין הנדון דומה לראיה. אלא מדבר או שר במיקרופון, ולא דמי כלל. וגם בההיא דערוה\"ש רבו האוסרים, תדע שבימינו כבר לא משתמשים בזה בשבת.","b":false},{"t":"עו\"כ שם, ואפילו להלבוש (סי' של\"ח הובא במשנ\"ב סק\"ד ובשעה\"צ) שכתב דמה שאסור להקיש בדלת בכלי המיוחד לכך, אינו משום שמא יכוין לשיר, אלא שמא יתקן אותו. וגם כאן יש לחוש שמא יתקן הרדיו או הרם קול, מ\"מ נראה דאין לחדש גזירה מעצמנו, לאסור גם בכה\"ג שלא עושה מעשה של השמעת קול, והקול נשמע רק מזה שמדבר או מנגן בקרבת המיקרופון. אך ראיתי בערוה\"ש (סי' של\"ח או' ה') דלהעמיד כלי שיר מע\"ש שישיר מעצמו בשבת ג\"כ אסור, דכיון דהאיסור הוא שמא יתקן כלי שיר, מה לי אם מנגן על ידו או מעצמו, סו\"ס יש חשש שכשיראה שאינו (מכוון) יפה יתקנו. ולפ\"ז מסתבר שגם בנ\"ד אסור מהך טעמא. אולם לענ\"ד נראה פשוט דגזירת חז\"ל היתה שלא לעשות מעשה כדי להשמיע קול בשבת, משא\"כ בכה\"ג דבשבת לא קעביד שום מעשה והכלי מנגן מאליו שרי. וגם בשו\"ע הרב ז\"ל התיר בזוג המקשקש אם ערכו מע\"ש שרי, אפי' שמשמיע קול של שיר ומתכוין לקול זה, וגם השו\"מ (שתיתאי סי' נ\"ג) ועוד גדולי האחרונים, התירו בכלי שיר המנגן מאליו בשבת ואין בו איסור, זולתי שחושדין בו שמנגן בשבת. עכ\"ד.","b":false},{"t":"ואחר המח\"ר טענתו זו חוזרת על עצמה לומר שכן ברם קול לא עושה שום מעשה בשבת כלל, ובכה\"ג לא גזרו, וכבר כתבתי דע\"י דיבורו שהוא כוחו ממש, עושה מעשה גמור ויוצר קול חדש שאיננו קולו כלל, וא\"כ זאת היא הצורה המקורית של השמעת קול שאסרו חז\"ל, משום שמא יתקן כלי שיר. וכאמור גם בכלים אלו מצויים התיקונים, וע\"כ בודאי שייכת בהם גזירת חז\"ל, ויש לאוסרם.","b":false},{"t":"ועוד אוסיף דלא מיבעיא להערוה\"ש וסיעתיה, שמחמירים בכלי שיר שמנגן מאליו אחר שערכוהו מע\"ש, משום חשש דשמא יתקן, אלא גם לש\"ע הרב ז\"ל וגם להשו\"מ וסיעתם, שמתירים בהנ\"ל. יודו בנ\"ד לאסור, משום שכאן עושה מעשה בשבת, שכל שיר או דיבור נהפך לזרמים וגלים חשמליים, ואלו נקלטים במקלט שהופכם לקולות שהם דומים לקול של זה שמנגן או שר במיקרופון, או לקולו של זה המדבר, וכמו שכתב איהו גופיה במנחת שלמה שם, שזו הסיבה שפסק שם בפשיטות, שלא יוצאים בזה י\"ח כלל, כי אין זה קולו של המדבר. וא\"כ עושה מעשה בקולו שהוא כוחו ממש, לא פחות ממה שעושה בידו וכו', והוא עצמו העלה כן, וזה פשוט.","b":false},{"t":"ו. ואחר כל אלה הדברים כתב הגאון ע\"ה בזוה\"ל: אך אעפ\"י כן נלע\"ד שאין להשתמש בשבת ברם קול או ברדיו, אפילו אם הם ערוכים ומיועדים לכך מאתמול, דהא נקטינן דאסור ליתן חטים בערב שבת לתוך רחיים של מים שיטחנו בשבת, אע\"ג דכו\"ע ידעי שהרחיים טוחנים מעצמם, וידעי נמי שהחטים הושמו שם מערב שבת, (וכך לשון התוספות בשבת י\"ח ע\"ב ד\"ה אין נותנים) אפי\"ה אסור מפני שמשמעת קול ואוושא מילתא, שיאמרו רחיים של פלוני טוחנות בשבת, ואיכא זלזול שבת בזה, שהשומעים את קול הטחינה יאמרו התחיל בשבת את מלאכתו. והן אמנם דפליגי רבוותא בזה, ומרן הב\"י נוטה להתיר, עכ\"ז הכריע הרמ\"א (סי' רנ\"ב) כדעת רוב הראשונים שאוסרים, וגם כל גדולי האחרונים הסכימו לכך, והמג\"א (ס\"ק כ\"א) סובר שגם אם ישים החטים בשבת בידיו ברחיים, אין בו איסור תורה, כיון שנטחן מאליו ולא ע\"י אדם, ואפ\"ה החמירו חז\"ל שלא לעשות כן גם מערב שבת. עכ\"ל.","b":false},{"t":"והנה אלה הנתלים בדבריו של הגאון מנחת שלמה ע\"ה, מעלימים עיניהם מהכרעת הגאון ז\"ל במסקנתו, ותופסים לשון ראשון בלבד, ובאמת הכרעתו לאסור, ועוד הוסיף לחזק איסור זה בראיות רבות כדרכו בקדש. ואפשר שסמכו על זה שהעלה דאין בו איסור ממש, רק אוושא מילתא ואיכא בזה זילותא דשבתא, ועוד שכתב שזה תלוי בפלוגתא דמרן והרמ\"א ע\"ה. ומצאו להם עצות להקל. ואולם לפי מה שכתבתי בעניותי יש בזה איסורים דרבנן בודאי, ואפשר מאד שיש באלו גם איסורים של תורה רח\"ל. ואי לאו דמסתפינא הוה אמינא שכל מה שכתב בתחלת דבריו, לפילפולא דאורייתא כתבו, והראיתי בעניותי, שיש מקום חשוב לומר בכל הנ\"ל דאדרבא הסברא היא לאסור, וכמו שהסיק איהו גופיה עליו השלום. להלכה ולמעשה אלא שלפי מה שכתבתי יש גם חששות דאורייתא.","b":false},{"t":"וע\"ש שהוסיף לחזק לאסור עפ\"י מהר\"י וייל ז\"ל (סי' ק\"ל), שאסר בכלי המשקולת שמשמיע קול לפי השעות, אפי' ערכו מע\"ש. דומיא דרחיים, אפילו שאיסור השמעת קול רק דרבנן, כיון דאוושא מילתא ואיכא זילותא בשבת אסור, ואע\"ג דלא קי\"ל כמהרי\"ו, ומתירים להעמיד כלי המשקולות מע\"ש, כמבואר בש\"ע (סי' רנ\"ב וסי' של\"ח) היינו משום שהכל יודעים שבכל יום מכינים אותו בשביל יום המחרת וכמ\"ש בדרכי משה (סי' רנ\"ב אות ז'), וכן בש\"ע הרב (או' ט\"ז), שההיתר הוא מפני שכן דרכו לעולם, ואילולי שכך עושים להכינו יום קודם, היה אסור משום דאוושא מילתא.","b":false},{"t":"עו\"כ דמה שמותר להדליק ולכבות אור החשמל בשבת ע\"י שעון אוטומטי, משום דדוקא השמעת קול הוא דאוושא מילתא, אבל האור רק נראה ולא נשמע, ועיקר החשד באור הוא בכיבוי או בהדלקה וזה נעשה ברגע כמימריה, משא\"כ בהשמעת קול, וכן מדוקדק בהרמ\"א שכתב, ובכל מקום שיש לחוש להשמעת קול אסור. והמשנ\"ב כלל בזה כלל, דמשמיע קול, ואוושא מילתא, ויש זילות לשבת. והוסיף הגרש\"ז אורבאך ע\"ה בזה\"ל: וכיון שכן נראה שגם אם השאיר הרם קול או מקלט הרדיו פתוח מע\"ש, או סידר שידלקו ע\"י אוטומט, כיון דאיכא השמעת קול דאוושא מילתא טפי הרי זה אסור. (והסתפק ברדיו בקול נמוך).","b":false},{"t":"עו\"כ שגם אם יפרסם לרבים שהם פתוחים מאתמול, אסור, דומיא דרחיים דלא מועיל מה שיפרסם, משום שבדר\"כ אין נותנים מאתמול החוטים, וה\"נ רגילין לפתוח ולסגור הרדיו בשעת השמוש, וכן ברם קול ע\"כ מסתבר דאסור. עכ\"ד. ומכל זה מתעלמים, ולומדים להתיר מראשית דבריו. והוא ז\"ל בחכמתו עקר גם מה שחושבים להתיר ע\"י שתולים איזה מודעא על המכונה וכיוצ\"ב. ולפי מ\"ש יש בזה איסורים גמורים.","b":false},{"t":"ז. עו\"כ שאין לומר שאני רדיו דכ\"ע ידעי שהוא רק קולט, ואין חשד שהוא מחלל שבת בהשמעתן כל העת כמו ברחיים וקשקוש השעון, וכתב דאינה סברא לחלק כך, אחר שהכל יודעים שהפעלת רדיו ורם קול כרוך בחילול שבת דאיסור הבערה, וברש\"י ותוס' (שבת י\"ז ע\"ב ד\"ה אין נותנים) שכתבו דכו\"ע ידעו שהרחיים טוחנות מעצמם וידעו שהחטים הושמו שם מע\"ש, ואפ\"ה אסור משום זילותא. [רואים דל\"מ מה שהכל יודעים.]","b":false},{"t":"והביא ראיה מהנוב\"י (או\"ח סי' ל') לענין נשיאת רעגנישירעם בשבת שהיתה פתוחה מאתמול, דכיון שלא כולם יודעים שזה מאתמול, אסור מדרבנן בודאי משום מראית העין. ובפרט בדור זה דנפישי שאינן שומרי תורה וכו'. ועיין בשע\"ת (סימן ש\"א סע\"ק מ\"ה).","b":false},{"t":"והביא סעד גדול מהפרמ\"ג (סי' ש\"ח א\"א ס\"ק ע\"ח) שהעלה דעריכת שעון בשבת הוא איסור תורה, של מכה בפטיש, דאל\"כ איך השוו קשקוש השעון לרחיים של מים, נמצא דאילולי שרגילי' לערוך השעון מאתמול היה אסור להשאירו שיקשקש בשבת, ולא מחשד דהשמעת קול בשבת שהוא מדבריהם, אלא שיחשדו שערכו בשבת שהוא מדאורייתא משום מכה בפטיש. ואע\"ג דהרבה אחרוני' לא פירשו כן בכונת הש\"ע, אלא שס\"ד שאסור הקשקוש משום שיחשדו שמשמיע קול שיר בשבת. דגם בדרבנן שייך מראית העין, עכ\"פ למדנו מהפרמ\"ג שאין חילוק אם החשד על עצם הקול, או שיחשדו שהפעיל את זה בשבת. וגם כאן יש חשד שיטעו לחשוב שהפעילו בשבת שיש בזה הבערה. ובפרט שהדלקת המנורות שבהם, אינה דבר צדדי כלל אלא חלק חשוב מעיקר המכשיר.","b":false},{"t":"עו\"כ וזאת למודעי, שאיני אוסר הרדיו מחשש שיכבה או ידליק כמו שמא יחתה בגחלים, וגם לא משום שמא יתקן, כי אין בכוחנו לחדש גזרות, אלא משום דמפורש בש\"ע דכל השמעת קול יש זילות לשבת, וראינו שכל גדולי עולם השוו שעון לרחיים של מים, ומוכח דבכל אופן שיש השמעת קול אסרו, וזה בכלל הגזרה, ולא גזרה חדשה.","b":false},{"t":"וכן אין לחלק בין שבת ליו\"ט, שגם ביו\"ט אסור להדליק חשמל משום הוצאת אש, שלהט\"ז סימן תק\"ב איסורו מן התורה. ע\"ש. עכ\"ל.","b":false},{"t":"ואולם לענ\"ד גם החשש דשמא יתקן שייך בזה והוא מצוי ביותר, וכמו שכתבתי לעיל. ועל כן יש לאסור גם מטעם זה. ועוד דלא רק זילותא יש בזה אלא לפי מה שביארתי לעיל בעניותי, הרי זה חלק מגזרת חז\"ל שאסרו להשמיע קול בשבת ע\"י מעשה שעושה בין בידיו בין ברגליו, וכאן הוא עושה מעשה בקולו ובהבל פיו, ויוצא ע\"י זה קול אחר מן המכשיר הזה, והוא ממש בכלל הגזרה בלא הבדל. וכאמור יש גם חששות לאיסורים דאורייתא.","b":false},{"t":"ח. והנה מקור הדין דהשמעת קול בשבת הוא במסכת עירובין (ק\"ד ע\"א) עולא איקלע לבי רב מנשה, אתא ההוא גברא טרף אבבא, אמר מאן האי ליתחל גופיה דקא מחיל ליה לשבתא, א\"ל רבה לא אסרו אלא קול של שיר. [ופירש\"י טרף אבבא, הקיש על הדלת באגרופו והשמיע קול. דקא מחיל שבת, דקסבר כל אולודי קול אסור. קול של שיר, הנשמע כעין שיר בנעימה ובנחת. עכ\"ל.]","b":false},{"t":"איתיביה אביי, מעלין בדיופי ומטיפין מיארק לחולה בשבת. לחולה אין, לבריא לא, ה\"ד לאו דנים וקא בעי דליתער ש\"מ אולודי קלא אסור, לא דתיר וקא בעי דלינים דמשתמע כי קלא דזמזומי.","b":false},{"t":"[ופירש\"י, מעלין בדיופי, מעלין יין מחבית לחבית ע\"י שני קנים החתוכים באלכסון, ומניח ראשין המשופעים זה כנגד זה, ונותן אחד מן הקנים בחבית ומוצץ בפיו בראש הקנה האחר מעט מן היין אליו, ומסלק משם, והיין יוצא כולו מאליו, דיופי שתי פיות. ומטיפין מיארק לחולה, כלי הוא ופיו צר ושל מתכת הוא ומנוקב בתחתיתו נקבים נקבים דקין וממלא מים וסותם פיו העליון, וכל זמן שפיו סתום אין המים יוצאין בנקבים התחתונים, וכשרוצה נוטל פקק העליון והמים יוצאין בנקבים טיף אחר טיף ונותן תחתיו כלי מתכת וקולן נשמע לחולה. לאתעורי ע\"י קול זה, ומתיראין להקיצו בידים שמא יבעית, וכיון דלהקיץ הוא, לא בנעימה ובנחת נשמע, שהרי קול נעים מרדימו והולך, אפילו הכי לבריא לא. עכ\"ל. וע\"ש שיש עוד בגמרא שהמשיכו להקשות על רבה דאמר שאסרו רק קול של שיר, ותירצו כל הקושיות.","b":false},{"t":"והנה לעולא כל מוליד קלא אסור אפילו כשמכה באגרוף על הדלת שיפתחו לו, ורבה סובר שלא אסרו אלא קול של שיר, ובפשטות היינו שמנגן בכלי שיר, או שמתופף בכלי תיפוף, או אפי' מתופף על שלחן וכדומה, לתת קצב לשירה, בכל זה מיקרי קול שירה ואסור גם לרבה.","b":false},{"t":"ואולם מדברי רש\"י ז\"ל שכתב, קול של שיר, הנשמע כעין שיר בנעימה ובנחת. משמע דלא רק שיר הוא שאסור, אלא כל שהוא כעין שיר, שמשמיע קול בנעימה ובנחת, מיקרי קול של שיר ואסור גם לרבה. ואפשר שלמד את זה ממה שאמרו שם, ומטיפין מיארק לחולה בשבת, ואמרו שמדובר שהחולה היה ער ורוצים להרדימו ובזה לא התירו אלא לחולה, ולא לבריא. והרי קול זה אין בו ניגון ושיר, אלא שהיין מטפטף בנחת תוך כלי מתכת, ונשמע קול נעים ומרגיע שיכול לקרב לו שינה, ועם כל זה אסרוהו לבריא, ומזה למד רש\"י ז\"ל דמ\"ש רבה קול של שיר, הכונה לקול נעים ומרגיע, ולא שיר ממש דוקא. וכן חזר וכתב רש\"י ז\"ל להלן בד\"ה ומטיפין מיארק, דאם מכוונים להעיר, לא בנעימה ובנחת נשמע, שהרי קול נעים מרדימו וכו'. נמצא שגם קול שאין בו ניגון של שיר, רק שהוא עשוי בשובה ובנחת, נכלל בקול של שיר, ואסור גם לרבה.","b":false},{"t":"וכ\"נ גם ממה שהקשו בגמרא שם להלן, על רבה, ואלא הא דא\"ר יהודה אמר רב נשים המשחקות באגוזים אסור, מאי טעמא לאו דקא מוליד קלא, וכל אולודי קלא אסור, לא דילמא אתו לאשווי גומות וכו'. ופירש\"י ז\"ל, משחקות באגוזים, לגלגלן דרך דף ומכות זו את זו, כדרך שמשחקות הנשים. עכ\"ל.","b":false},{"t":"והנה לפי זה אין ראיה, דרבה תירץ דאיסור המשחק באגוזים הוא משום אשוויי גומות ולא משום השמעת קול. ואולם התוס' שם (ד\"ה הכי) כתבו שר\"ח גורס הכי אלא הא דא\"ר יהודה נשים המשחקות באגוזים וכו', לא דמשתמע קלא כי זמזומי, פירוש שזורק אחד ומקבל אחד בהשמעת קול דאסור. והדר קאמר ואלא הא דאמר רב יהודה נשים המשחקות בתפוחים וכו', ומשני לא משום אשוויי גומות. והשתא תרי עניני איסור אשמועינן וכו'. וגם הרי\"ף גורס בזה כר\"ח רבו, וכן הוא בהרמב\"ם ז\"ל. ולגירסא זו יוצא דאיסור האגוזים הוא באמת משום השמעת קול. ולא אמרו משום אשוויי גומות אלא בתפוחים, וצ\"ל למה קול זה של האגוזים אסור לרבה, והא אין זה קול של שיר, אלא ע\"כ דלא בעי רבה שיר ממש, רק כעין שיר, והוא כל קול הנשמע בנחת ובנעימה, וזה מ\"ש בגירסת ר\"ח ז\"ל דמשמתע קול כי זמזומי (כנ\"ל). ונמצא שגם רבה לא מצריך קול שירה ממש אלא כדפירש\"י ז\"ל, וזה מוסכם גם להרי\"ף ז\"ל דפליג על ר\"ח ופוסק כרבה.","b":false},{"t":"ובאמת שדבר זה מדוקדק היטב גם בלשון הרמב\"ם ז\"ל, בהלכות שבת (פרק כ\"ג ה\"ד) שכתב וז\"ל \"כל דבר שהוא גמר מלאכה חייב עליו משום מכה בפטיש, ומפני זה הגורר כל שהוא או המתקן כלי באיזה דבר שיתקן חייב, לפיכך אסור להשמיע קול של שיר בשבת בין בכלי שיר כגון כנורות ונבלים בין בשאר דברים, אפילו להכות באצבע על הקרקע או על הלוח או אחת כנגד אחת כדרך המשוררים, או לקשקש את האגוז לתינוק או לשחק לו בזוג כדי שישתוק, כל זה וכיוצא בו אסור גזירה שמא יתקן כלי שיר\". עכ\"ל.","b":false},{"t":"ויש לדקדק דהרמב\"ם ז\"ל פתח הדין דהשמעת קול, בדין דמתקן כלי שהוא מדאורייתא, משום מכה בפטיש, ואח\"כ כתב לפיכך אסור להשמיע קול של שיר. ובזה פסק כרבה בעירובין (ק\"ד ע\"א) דלא אסרו אלא קול של שיר, וכמו שפסק הרי\"ף ז\"ל, ודלא כרבינו חננאל ז\"ל, ופירט שאסרו לשמוע קול כינורות ונבל וכו' ואפילו להכות יד כנגד יד כדרך המשוררים וכו', וכן קשקוש באגוזים וכו'. וצ\"ל אחר שהרמב\"ם ז\"ל פסק כהרי\"ף דרק קול של שיר הוא שאסור, איך אסרו לקשקש באגוזים, בשלמא הכאה באצבע על הלוח או אצבע כנגד אצבע, אסרו אותם אעפ\"י שאין זה דומה לנבל וכינור, מ\"מ בזה הוא נותן קצב לשירה ונותן בה טעם וריח, ובזה אפשר לשייך אותו עם קול של שיר. אבל אגוזים שמשחקים בהם או מקשקשים להשתיק תינוק, איך זה נכלל בקול של שיר. ובע\"כ צ\"ל דגם הרמב\"ם סובר כרש\"י ז\"ל דכל קול שהוא בנעימה ובנחת נכלל בקול של שיר, ואסור להשמיעו גם לרבה. ולא בא רבה לאפוקי אלא כגון זה דטריף אבבא באגרופו, ושאר קולות שבאים להקיץ נרדמים, וכדמשמע בגמ' בהא דמטיפין מיארק לחולה בשבת, דאם החולה ניים ורוצה להעיר אותו אינו בכלל קול של שיר. אבל כשהקול הוא נעים ומרגיע ומרדים את החולה הוא בכלל קול של שיר, ואסור גם לרבה. וכנ\"ל.","b":false},{"t":"ט. ואפשר שרש\"י והרמב\"ם ז\"ל למדו כן ממה שדקדק רבה ואמר קול של שיר, ולא אמר שיר. דמשמע דגם כעין שיר שהוא בנעימה ונחת גם כן אסור.","b":false},{"t":"עוד ראיתי לדקדק כן מהגמ' דעירובין הנ\"ל, שאמרו ומטיפין מיארק לחולה בשבת, לחולה אין לבריא לא, היכי דמי לאו דניים וקא בעי דליתער, ש\"מ אולודי קלא אסור. וכו'. ולכאורה היה צריך לומר, אי דניים וקא בעי דליתער (ואפ\"ה לבריא אסור) ש\"מ דכל אולודי קלא אסור, ולא רק קול של שיר ותיובתא דרבה, דאמר לא אסרו אלא קול של שיר. ומה זה שאומר: ש\"מ אולודי קלא אסור. והרי לכו\"ע אולודי קלא אסור, אלא שנחלקו עולא ורבה אם כל אולודי קלא אסור, ואפילו נקישות על הדלת, או רק קול של שיר הוא שאסור, וכאן הקשו על רבה, שאמר לא אסרו אלא קול של שיר, והו\"ל למימר ש\"מ כל הקולות אסורים, או כל אולודי קלא אסור. ולא כמו שאמרו, ש\"מ אולודי קלא אסור.","b":false},{"t":"ונראה מזה דמחלוקתם היא, אם האיסור הוא רק משום גזירה דשמא יתקן כלי שיר, או שזה איסור בפני עצמו, שלא מחמת גזירה. עולא סובר שהוא איסור בפני עצמו שאסרו להוליד קול, ולא מחשש שיתקן כלי שיר, וע\"כ כל קול אסור אפילו לנקוש על הדלת להעיר מאן דהוא, או לקרא להם לפתוח הדלת ג\"כ אסור, דאין זה קשור בשיר כלל וכלל, רק גזרו ואסרו כל הולדת קול. וכמו שאסרו מוקצה שאינו תלוי בגזירה שמא יבא לעשות איסור תורה. אלא הוא איסור שאסרו חז\"ל בפני עצמו בלבד.","b":false},{"t":"ורבה ס\"ל שכל האיסור של השמעת קול בשבת הוא משום שמא יתקן כלי שיר, וע\"כ הוא סובר דרק קול של שיר הוא שאסור, דכיון שעוסק בקול של שיר להשמיעו, חיישינן שמא יתקן כלי שיר. אבל קול המעורר וקורא כמו נקישה על הדלת אינו אסור, דבזה לא שייך לגזור ולחשוש שמא יתקן כלי שיר.","b":false},{"t":"וכאן הקשו על רבה ממטיפין מיארק דרק לחולה התירו ולא לבריא, ואם מדובר שמתכוין להעיר אותו משנתו, ועם כל זה אסור לבריא, ש\"מ שאין זה תלוי בגזירה דשמא יתקן כלי שיר, אלא הוא איסור עצמי, וזה שאמר שם, ש\"מ אולודי קלא אסור. ר\"ל דמזה מוכח שאין האיסור תלוי בגזירת תיקון כלי שיר, דכאן ראינו דאסרו גם קולות שמעוררים, שאין להם קשר לשיר כלל, ובע\"כ דכל אולודי קלא אסור ולא מטעם גזירת תיקון כלי שיר, וע\"כ אמרו ש\"מ אולודי קלא אסור. כלומר דלא משום גזירת כלי שיר אסור, אלא הוא איסור בפני עצמו, וקשה על רבה. ותירץ רבה, דמיירי שהחולה ער והוא מבקש להרדימו, ומשמיע לו קול נעים בנחת שזה מרדים את השומע, וקול כזה הוא מכלל קול של שיר וע\"כ אסור לבריא.","b":false},{"t":"ויש חיזוק לזה מדברי הרמב\"ם ז\"ל הנ\"ל, שהוא פסק כרבה דלא אסרו אלא קול של שיר, וע\"כ פתח באיסור דאורייתא שהוא תיקון כלי שחייב משום מכה בפטיש. ואח\"כ כתב, לפיכך אסרו להשמיע קול, דתולה כל האיסור רק בגזירה דשמא יתקן כלי שיר, וע\"כ לא אסרו אלא קול של שיר, שבזה שייך לגזור שמא יתקן כלי שיר. אלא שכאמור ס\"ל דגם קול קשקוש האגוזים העשוי בנחת הוא מכלל איסור קול של שיר. וכנ\"ל.","b":false},{"t":"ואשו\"ר בציץ אליעזר ח\"ג (חא\"ח סימן ט\"ז פ\"ב אות א) שגם כן תלה מחלוקתם כהנ\"ל, דעולא ואביי שאוסרים כל קול, ס\"ל שהאיסור הוא שמוליד קול בשבת, ורבה סובר דלא אסרו להוליד קול בשבת, רק אסרו קול של שיר גזירה שמא יתקן כלי שיר, וכמ\"ש בביצה (ל\"ו ע\"א) לא מטפחין ולא מספקין ולא מרקדין גזירה שמא יתקן כלי שיר.","b":false},{"t":"וע\"ש שכתב (באות ג') שכן כתב האור שמח בהל' שבת (פכ\"ג ה\"ה) דלאביי דאסר כל אולודי קלא, א\"צ לגזירה, וביאר שכן דעת הירושלמי שאמרו שם, \"כל משמיע קול אסור בשבת\". דמשמע משום אולודי קלא, ולפ\"ז לר\"ח שאסר בכל קול, הוי איסור השמעת קול איסור עצמי של מוליד קול, ואינו תלוי בגזרה. וע\"ש בציץ אליעזר (באות ד') שדקדק מהב\"ח (סי' של\"ח) דלא כאור שמח בזה.","b":false},{"t":"ושמחתי ע\"ז מאד, ולפי מה שכתבתי דברי האור שמח מדוקדקים בלשון הגמ' וכנ\"ל.","b":false},{"t":"ולפי\"ז יש לומר דלהרמ\"א ז\"ל שפסק כר\"ח ז\"ל וסיעתיה, דכל הקולות אסורים ולא רק קול של שיר, ואשר לפי זה אין איסור זה כרוך בגזירה דשמא יתקן כלי שיר. א\"כ גם למ\"ש הגרשז\"א ז\"ל שאין בהם גזירת שמא יתקן כלי שיר, מ\"מ אסור דאולודי קלא ודאי יש בהם. ומה שטען שלא אסרו אלא בעושה מעשה המשמיע קול, כבר הבהרתי דגם הפעלת מערכת בקולו חשיב שפיר מעשה גמור, דהוא כוחו ממש, לא פחות ממה שעושה בידיו.","b":false},{"t":"י. ושוחחתי ארוכות בחקירות אלו מבחינה מקצועית עם אנשים חכמים ומדענים חשובים מאד ויר\"ש מרבים, הרב ד\"ר מאיר דנינו הי\"ו, ומתוך החקירות הוא נועץ באחיו המלומד הרב ד\"ר חיים הי\"ו.","b":false},{"t":"בתחילה עוררתי בענין העברת הקליטה מתחנה לתחנה, ואמרתי שאפשר שהשינוי עושה רושם ומבזבז יותר אנרגיה (וזאת מלבד מ\"ש לעיל דאפשר דנחשב שמשמיע קול בשבת ע\"ש). ונחלקו בזה שני האחים, ודעת רח\"ד שאם מעבירים לתחנה שהיא רועשת יותר יש שינוי בהגברה, ואע\"פ שר\"מ חולק ע\"ז, מכלל ספק לא נפק, ומצד ההגיון הפשוט קשה לומר שלא חל שום שינוי כשמעביר מתחנה לתחנה.","b":false},{"t":"עו\"כ לי ר' מאיר הי\"ו, דברדיו ישן הפועל על שפופרת, יתכן שכאשר התחנה מכוונת היטב לתדר פעיל, שתהיה זרימה בשפופרת ואפשר שתהיה שם מעט הארה, בשל החום הנוצר בשפופרת, ויתכנו גם ניצוצות, עכ\"ל בזה. וזכורני שהגאון מו\"ר רבי יוסף משאש זצ\"ל בשו\"ת מים חיים חא\"ח, כתב על ענין החשמל בשבת, שכשהביאו הצרפתים חשמל לערי מרוקו התעוררה שם השאלה על החשמל לענין שבת, והוא ע\"ה הלך לתחנת החשמל שהקימו הצרפתים שם, והמהנדס הראשי הסביר לו כל ענין החשמל באר היטב עד שהוא ע\"ה למד כל פרטיו אחת אל אחת כראוי, והעלה שהוא איסור גמור מדאורייתא וחייבים עליו סקילה, וסיים בזה\"ל: ודברי העורים המתירים, לרוח יהיה פזורים. ושם בתוך דבריו כתב שאמרו לו שמלבד ההבערה והכבוי הנעשים ע\"י לחיצת הכפתור בעת שמדליק או מכבה, עוד נמצא כי בכל פעולה של חשמל יוצא איזה ניצוץ כל שהוא, וגם זה הוא הבערה.","b":false},{"t":"עו\"כ לי רבי מאיר הי\"ו, שברדיו טרנזיסטורים לא קיימת אותה תופעה. אך במערכות רדיו מודרניות דיגיטליות, ישנה תצוגה הכוללת תאורה מסוגים שונים, וזו משתנה בעת שינוי התחנה, וכן בעת הגברת הזרם, שהוא חילול שבת גמור. עכ\"ל.","b":false},{"t":"עו\"כ שם, בקשר לשאלותי, שאולי נדלקים אורות, ושרואים שהאור מתחזק ומתמעט לפי הכיוון, של התחנות. וכתב שיש בחלק מהמערכות תאורה המציינת שהמכשיר מכוון לתדר פעיל, והיא נמוגה כשמתרחקים מהתחום הפעיל, שגם הוא חילול שבת הקשור ישירות לפעולת הכיוון או ההגברה. עכ\"ל.","b":false},{"t":"הנה בכל זה רואים שגם בהכוונת התחנות ע\"י הרגולטור יש חילול שבת שנדלקים ונכבים אורות שונים ע\"י פעולה זאת, וזה מלמד שהחשמל מתחבר ומתנתק, שאעפ\"י שבכל אותה עת הרדיו מחובר לחשמל, מ\"מ יש עוד מגעים שמתהדקים וגם מתנתקים, וזה משתקף באותם אורות הנראים לעין כל אדם, ופעמים שגם יוצאים ניצוצות, ומי יודע עוד איזה דברים קורים שאין העין קולטתם. וכבר ראינו שהמדענים אומרים מסקנות ברורות וחלוטות, ואחר איזה זמן באים מדענים אחרים ועורכים מחקרים וסותרים דברי קודמיהם, ומפרסמים דעתם, ומילתא דשכיחא היא שאלה סותרים את דברי אלה מן הקצה אל הקצה, ופעמים רבות מתבררים גילויים חדשים שלא שערום המדענים שקדמו להם, ואין לנו להחפז ולקבוע היתרים בשבת החמורה, עד שיתלבנו הדברים כל צרכם.","b":false},{"t":"ובאשר לחקירתי על הגברת הקול שזה לוקח יותר אנרגיה ומכלה אותה ואולי יש בזה הבערה או איסור אחר. כתב לי על זה שאכן בעת הגברת מכשיר חשמלי אנו צורכים יותר אנרגיה מהמאגר של חברת החשמל, אולם בחברת החשמל אינם צריכים להגביר את הייצור של האנרגיה בעקבות זה, משום שהם מכינים מאגר גדול בהתאם לצריכה גדולה שתספיק גם כשצרכנים רבים מגבירים צריכתם בבת אחת. ורק במקרים קיצוניים שהרבה מפעילים מזגנים ותאורה וכו' יחד, אז הם נאלצים להגביר את היצור ולהפעיל עוד טורבינה.","b":false},{"t":"עוד הוסיף, שבהחלט יש חשש שהגברה ביתית של מכשיר מסויים תיצור לפעמים דיווח למערך הבקרה שבחברת החשמל, שיש בה גם מצגים דיגיטליים, שבהם מתעדכנת החברה לגבי רמת הצריכה, התצוגה נערכת במסך ע\"י תאורה או כתיבה על מסך מחשב הבקרה. ע\"כ.","b":false},{"t":"והנה לפי זה בכל שימוש באנרגיה יש השפעה על המצב של הבקרה שנרשמת הצריכה במסך הבקרה של חברת החשמל בכתב או ע\"י תאורה, כדי לעדכן הנתונים של הצריכה שידעו לקראת מה הם עומדים. ומלבד זה דבר ברור הוא שכל התגברות של הזרם, מחסרת מהמלאי של האנרגיה שמכינה חברת החשמל, רק שכתב המומחה, שאין בזה לגרום לחברה להגביר את הייצור או להפעיל טורבינה אחרת, שזה עושים רק במקרים קיצונים שהיתה צריכה גבוהה במיוחד. וכנ\"ל.","b":false},{"t":"ומיהו לענ\"ד עצם כילוי האנרגיה החשמלית ע\"י שמשתמשים בה בכל דבר, כולל שימוש של הגברת קול הרדיו או העברה לתחנה אחרת, יש בו חילול שבת, ועוד יתבהר הענין להבינו בעה\"ו.","b":false},{"t":"עוד שאלתי את המומחה על עידכון המונה של החשמל שקיים בכל בית, שזה בודאי פועל ומתעדכן בכל הפעלה של הזרם או הגברתו, ובכל פעם שצורכים אנרגיה המספרים מתעדכנים להורות על כמות הצריכה, שהרי משלמים לפי הכמות שצורכים, שזה נמדד לפי משקל מסויים, והשיב שכיום כבר לא שולחים איש שירשום מהמונה את כמות הצריכה, אלא המונים היום הם דיגיטלים, ועובדים באופן שוטף והמספרים משתנים עם הגברת הזרם במכשיר חשמלי זה או אחר. והרישום נעשה ע\"י נורות קטנות שנדלקים ונכבים (ביטים) ובזה נרשם הקצב, ושאין לו ידיעה בהלכה של נורות אלו. עוד הוסיף, שכיום המצב של כמות הצריכה מתעדכן מיד גם במחשב של החברה, ועל פי זה נקבע גובה התשלום לכל בית, מבלי שיבא האיש לרשום את המצב של המונה, כי הכל עובר מיד למחשבים של החברה ומתעדכנים בכל עת ובכל שעה.","b":false},{"t":"עוד הוסיף שכעת גם במוני מים מודרניים דיגיטליים משדרים את רמת הצריכה למחשב המרכזי באופן שוטף. (בין פעם בשנייה לפעם בכמה דקות). עכ\"ל.","b":false},{"t":"ולפי זה נמצא שבכל פעולה שמגבירה את כמות הצריכה של החשמל, ע\"י פעולה זו גם מפעיל את השעון המודד, ומיד מתעדכן גם המחשב המרכזי, בצורה של כתיבה או בדרך של הדלקת נורות קטנות שבזה נרשם הכל, הן בחשמל והן במים. ולא יעלה בדעת שזה יחשב להיתר גמור גם מדרבנן, וכי יש שמתיר לכתוב במחשב ח\"ו, והטענות של מלומדים למיניהם ידועים הם, אבל אין בכוחם להתיר את האסור. ולענ\"ד יש בזה גם חששות דאורייתא רח\"ל.","b":false},{"t":"ואין ספק שבכל שימוש במיקרופון או שאר מכשירי החשמל שמתגברת הצריכה, וממילא יש עליה ברישום וזה נרשם דיגיטלית במונה הביתי ומשם למחשב המרכזי של חברת החשמל, ואין ספק שיש בזה איסור או מהרישום או מהנורות הנדלקות ונכבות לפי הצריכה, וזאת מלבד מה שכתבתי לעיל שבזה מכלה אנרגיה ויש חשש גדול בכילוי זה אם לא מתכלה בדרך שיש בו חילול שבת. ועוד חזון למועד אי\"ה.","b":false},{"t":"יא. ואבא אל העי'ן והנה ראיתי בשו\"ת משפטי עוזיאל למרן הראש\"ל ע\"ה (בחלק א' סימן י\"ג), שכתב שגם להרי\"ף וסיעתו שפסקו כרבה, הגראמופון אסור, דמשמיע קול שיר, ויש חשש שיתקן, ואפילו הטליפון אסור משום דהוי קול של שיר, דאע\"ג דאינו מתכוין לשיר, מ\"מ הקול הוא קול של שירה, ודייק את זה ממה שאמר רבא, לא אסרו \"אלא בקול של שיר\", ומדלא אמר קול שיר, משמע דהעיקר הוא באיכות הקול, כל שמשתמע כקול של שיר אסור, וכמו קול דיופי שאסור (בגמרא שם), משום דמשתמע כקלא דזמזומי.","b":false},{"t":"ושמחתי שכיוונתי בזה לדעתו הגדולה, ולענ\"ד הוא מפורש בדברי רש\"י ז\"ל שהזכרתי לעיל, וכן דייקתי היטב מהגמרא שם, וגם מלשון הרמב\"ם ז\"ל וכמו שכתבתי לעיל בס\"ד.","b":false},{"t":"והמשפטי עוזיאל מוכיח כן גם מדברי מרן ז\"ל בש\"ע (סימן של\"ח) שכתב, השמעת קול בכלי שיר אסור, אבל להקיש על הדלת וכיוצא שאינו דרך שיר מותר, ומשמע שהשמעת קול בכלי שיר אעפ\"י שאינו מתכוין לשיר אסור, ולא התירו להשמיע קול אלא בשני תנאים, להקיש על הדלת (שאינו כלי שיר), ושאינו בדרך כלי. ומזה למד הרב ז\"ל לאסור הטלפון שהפעמון מצלצל ע\"י אחיזת השפופרת ביד, שהוא כלי שיר, וגם בדרך שיר, ואצ\"ל גרמופון ורדיו שהם עצמם כלי שירה ועשויים לשיר, בודאי שאסור להשמיע קול על ידם בשבת ויו\"ט. עכ\"ל.","b":false},{"t":"ומדבריו ז\"ל משמע שהמשמעות של כלי שיר, אינו רק כינור או תוף וחליל, אלא גם רדיו וגרמופון יש להם דין כלי שיר, ואפילו טלפון לשיטתו, מיקרי כלי שיר.","b":false},{"t":"עו\"כ לחדש דאיסור השמעת קול בכלי שיר, אינו משום סייג אלא איסור גמור, דסתם כלי שיר זקוק לתיקונים למתוח הנימים, כדי להנעים קולו, ועיין רש\"י (עירובין ק\"ג ד\"ה אף הוא) והו\"ל מתקן מנא. ולמד כן מהרמב\"ם ז\"ל (בהלכות שבת פכ\"ג ה\"ד) וז\"ל כל דבר שהוא גמר מלאכה חייב עליו משום מכה בפטיש, ומפני זה הגורר כל שהוא או המתקן כלי באיזה דבר שיתוקן חייב. לפיכך אסור להשמיע קול של שיר בשבת, בין בכלי שיר כגון כינורות ונבלים, ובין בשאר דברים, אפילו להכות באצבע על הקרקע או על הלוח, או אחת כנגד אחת כדרך המשוררים, או לקשקש את האגוז לתינוק או לשחק בו בזוג כדי שישתוק, כל זה וכיוצא בו אסור, שמא יתקן כלי שיר. עכ\"ל. וכתב דכינורות ונבלים אסורים משום שבודאי מתקן כלי שיר, וגזירת חז\"ל שגזרו שמא יתקן כלי שיר, קאי על מכה באצבע על הלוח או לקשקש בזוג, וכן לענין דאין מספקין ואין מרקדין ואין מטפחין בשבת. ובזה נבין פסק מהר\"ם ז\"ל שהתיר טבעת שיש בה אבן או עופרת שמשמיע קול (הגהמ\"י שם), דאינו צריך לקול זה והוא נשמע מאליו גם בלא מעשה, ע\"כ מותר דאין בזה אפילו גזירה שמא יתקן כלי שיר. עכ\"ל.","b":false},{"t":"והנראה שבכינור וגיטרה ועוד וכיוצ\"ב, ס\"ל דבודאי שהוא צריך לתקנם בעת שרוצה לנגן בהם, ויתחייב משום מכה בפטיש כשיתקן, אך אם לא יתקן נראה דגם המשפטי עוזיאל מודה שאין בו אלא איסור דרבנן, שאסרו גם בלא מתקן משום גזרה דשמא יתקן. אלא דבא לומר שבכלים אלו בודאי שיתקן, כי כן הדרך של המנגנים בבואם לנגן שמותחים ומתקנים עד שמתאימים הקולות כדבעי, וזה ידוע ומפורסם. אלא שלא הבנתי מה ראיה מביא מהרמב\"ם ז\"ל, דזה לא נרמז בלשונו הזהב של הרמב\"ם. ועיין לעיל שדקדקתי בלשון הרמב\"ם ז\"ל דאזיל בשיטת רש\"י שקול שיר הוא לאו דוקא אלא כעין שיר ג\"כ אסור אפילו לרבה, עי\"ש. אך מה שכתב הגאון משפטי עוזיאל דבודאי יתקן ושעל כן קורא לו שאינו גזירה אלא איסור גמור, לזה לא מובן מאי מייתי מהרמב\"ם ז\"ל.","b":false},{"t":"ועוד דמאן לימא לן שמתיחת המיתרים וכיוונם חשיב מתקן מנא גמור וחייב מהתורה. ובפשטות י\"ל דמתקן מנא שכתב הרמב\"ם ז\"ל שהוא חייב משום מכה בפטיש, לא קאי אלא אם נקרעה נימה ומחליפה, או נשמטו לגמרי ממקומם וצריך אומנות להשיבם, או נשבר הכלי ומדבקו שבר אל שבר יחדיו ידובקו, וכל כיוצא בזה. אבל תיקון הנימין לכוונם, שזה דבר שא\"צ אומן ונעשה תמיד, בודאי שאינו חייב עליו. ולא חשיב מכה בפטיש.","b":false},{"t":"ואולי כונת הרב זללה\"ה היא, שכינור וכל כלי של שיר, אסור מדרבנן, אך לא מצד הגזירה אלא איסור עצמי דאולודי קלא, וכמ\"ש לעיל משם האור שמח ע\"ה, וכתבתי לדקדק כן מהגמרא דעירובין שם. ומה שכתב דבהשמעת כלי שיר הוא איסור גמור, דסתם כלי שיר זקוק לתיקון למתוח הנימים וכו', כונתו לאיסור דרבנן, ולא לאיסור דאורייתא, דמן התורה אינו חייב אלא על תיקון גמור וכנ\"ל.","b":false},{"t":"יב. וע\"ש במשפטי עוזיאל שהזכיר להתוס' (ביצה ל' ע\"א ד\"ה תנן) שאנו שאין בקיאים בתיקון כלי שיר לא שייך לגזור. וכן פסק הרמ\"א ז\"ל (בסימן של\"ט ס\"ג). דמרן ז\"ל שם כתב, אין מטפחין להכות כף על כף ולא מספקין להכות כף על ירך וכו', או לקשקש באגוז לתינוק או לשחק בו בזוג כדי שישתוק. כל זה וכיוצא בו אסור גזירה שמא יתקן כלי שיר. ולספק כלאחר יד מותר. והרמ\"א ז\"ל כתב בהגה, והא דמספקין ומרקדין האידנא ולא מחינן בהו, דמוטב שיהיו שוגגין וכו'. וי\"א דבזה\"ז הכל שרי דאין אנו בקיאין בעשית כלי שיר, וליכא למגזר שמא יתקן, דמילתא דלא שכיח הוא, ואפשר שעל זה נהגו להקל בכל. עכ\"ל. וכתב המשפטי עוזיאל שדברי התוס' וכן דברי הרמ\"א ז\"ל, קאי רק אמטפחין ומרקדין שאיסורם הוא משום גזירה, אבל בכלי שיר שמוכרח לתקנו ולכוונו והוא חלק מהניגון בו ובודאי יתקנו, מודים התוס' והרמ\"א ז\"ל שיש לאסור גם בזה\"ז. כי באמת בסימן של\"ט מיירי מדין מטפחין ומספקין. (וכמ\"ש בלשון הש\"ע).","b":false},{"t":"עו\"כ המשפטי עוזיאל שם וז\"ל, ועוד אני אומר דהשמעת קול ע\"י גראמופון וטלפון ורדיו, גרע מהשמעת קול ע\"י כלי שיר, מטעם שמכונות אלו אינן שלמות בעצמם, וצריכים תיקון בשעת השמוש לגלגל וכו', (להפעילם) ובכלים אלו אין חשש שמא יתקן, אלא מתקן מנא ודאי שאסור מדאורייתא. וע\"ש עוד מזה שמחזק לזה בראיות שהוא אסור מדאורייתא. וע\"ש שהרבה לתמוה על ספר אור חדש (להרה\"ג אפרים זלמן הלוי ז\"ל) שכתב שמשיכת החוטים ע\"י מפתח (בטלפון) (ובימינו ע\"י חיוג) לתאם עם מי שרוצה לדבר, וגם אח\"כ כשגומרים לדבר, אינו דומה לעריכת זוג המקשקש לשעות, ששם נערך עי\"ז לכל הזמן, משא\"כ בזה. ותמה דמנין לו לחלק בין מתקן לכל הזמן או לזמן קטן, ובלי הנעת יד המכונה (או בלי שיחייג) אינה ראויה להשמעת קול, וכבר כתב הרמב\"ם המתקן כלי בכל ענין שיתקן חייב.","b":false},{"t":"עו\"כ באור חדש, שאין לאסור הטלפון מצד מכה בפטיש, והסתייע מהט\"ז (שי\"ג סק\"ז) שהתיר הדוק חבית של ברזל, שהואיל ועיקר תשמישו ע\"י פירוק לא נקרא גמר מלאכה. והראש\"ל ז\"ל דחה דבריו וכתב, ואין הנידון דומה לראיה, שהחבית ראויה לשמוש גם כשהיא פתוחה וכיון שעיקר תשמישה ע\"י פירוק, אין ההדוק נחשב גמר מלאכה, אבל מכונות אלו שבלי הנעת כוח החשמל או הנחת המחט של גרמופון וכו', אין ראוי לכלום, ועל ידי שמפעיל או מכוין אותם עושה אותם כלי, והו\"ל מתקן מנא ואסור בודאי. עכ\"ד. נמצא שכל מכשיר שמפעילים אותו ועושה פעולתו, הוי ליה מתקן מנא וחייב מן התורה. והה\"נ במיקרופון שע\"י הדיבור הוא עושה פעולתו ומשמיע קולות, ויש בזה חיוב משום מתקן מנא, שכתב בזה\"ל: וכלל גדול למדנו מהרמב\"ם ז\"ל (הל' שבת פכ\"ג ה\"ד) שהמתקן כלי באיזה אופן שיתקן חייב.","b":false},{"t":"עו\"כ שם שכתב כל זה להראות שגם כשאין הבערה וכבוי בהפעלת טלפון או רדיו, ג\"כ אסורים משום השמעת קול, ומשום מתקן מנא.","b":false},{"t":"אבל במקום שיש הבערה וכבוי כמו כל המכונות שקשורים למרכזים עירוניים וממשלתיים, בזה יש איסור מבעיר נוסף על מתקן מנא, שגם ביו\"ט לא התירו אלא הבערה שיש בה צורך קצת, או שהיא עצמה מעין אוכל נפש, כגון מדורה להתחמם בה שמותרת ביו\"ט, שמתוך שהותרה לצורך וכו', או שהנאת חימום היא אוכל נפש.","b":false},{"t":"אבל טלפון ורדיו הוי הבערה שלא לצורך כלל (עיין טוש\"ע סימן תצ\"ה וסי' תקי\"ח). עכת\"ד.","b":false},{"t":"והמתבונן בדב\"ק של מרן הראש\"ל הג\"ר ב\"צ מאיר חי עוזיאל ע\"ה שהזכרתי, יראה שהוא תנא דמסייען בהרבה פרטים שהעליתי בעניותי בדינים אלו.","b":false}]},{"t":"בדין ירקות עלים שמצויים בהם תולעים","p":[{"t":"בעהית\"ש. ערש\"ק אחרי קדושים, ה' אייר התשע\"ב.","b":false},{"t":"תופעת התולעים בירקות ידועה מאד מאז ומתמיד, והיינו נמנעים מחלק מהירקות, כמו כסה שלא אכלנו בכל ימות השנה מלבד בליל הסדר של פסח, בשביל לקיים מצות אכילת מרור, ואז היינו מורידים העלים ומשאירים רק הקלחים, ורוחצים אותם במים וסבון וגם משפשפים במברשת, ואח\"כ זורקים עליהם מים רבים בזרם חזק, על כל הצדדים, ואח\"כ בודקים אותם בעיון רב לאור השמש. וכן הנענע שאותו נותנים בתה, לא שתינו אלא ע\"י סינון מבד או מצמר גפן, ושאר העלים היו מרבים לרוחצם ולבודקם, ויש דברים שנמנעו מהם בזמנים החמים, או שאכלו מהם רק כשהם יבשים וכן על זה הדרך.","b":false},{"t":"א. והנה בימינו התחדשו הגידולים של ירקות בחממות, שנקראים ירקות ללא תולעים, ויש להם הכשרים מרבנים ובתי דין שונים, ומעט מעט התפשטו בכל הארץ, וברוב המקומות נדרשים בעלי המלונות ובעלי אולמות וקייטרינגים וכו', להשתמש רק בירקות מגידולים אלו, ומתחילה נעשו בגוש קטיף ע\"י מומחים, ואח\"כ התפשטה תעשיה זאת גם בשאר מקומות, והיתה הרוחה. (וזכורני המאבק הגדול שניהלתי עם בעלי המלונות של תל אביב יפו ת\"ו, בהיותי מכהן שם ברבנות, שאיימו בבג\"צ כמו שנפוץ בימינו, וסוף דבר הצלחנו לשכנע אותם, וקיבלו את הדין, בחסדי ה' יתברך).","b":false},{"t":"ואולם מדי פעם כפעם, מוצאים שיש תולעים וחרקים לרוב ואז טוענים שהיתה תקלה וכדומה. אך גם הסחורה הטובה, אינה נקיה לגמרי, אלא שפחתו החרקים בכמות עצומה, ויש טוענים שגם המעט שמצוי, הוא בולט לעין כי זה מסוג מסויים שהם גדולים וצבעם שונה, ואפשר להזהר. והמדקדקים בודקים גם בירקות אלו אחר שרוחצים הדק היטב, בודקים בעיון טוב, והנמנעים מבדיקתם אין ספק שיש בזה מכשולים ה' יצילנו.","b":false},{"t":"ולפני איזה זמן היה אצלי אחד מגדולי המומחים והחוקרים בעניני תולעים, ואמר לי, שכל המגדלים ירקות ללא תולעים, משתמשים בחומרי הדברה לרוב, ויש חומרים שאסור להשתמש בהם כלל וכלל לפי הוראות משרד הבריאות, והם כן משתמשים בהם, ויש חומרים שמותר להשתמש בכמות קטנה, והם משתמשים בכמות גדולה ומוגזמת מאד, והראה לי טבלה שהעלה במעבדה שלו מתוך בדיקות מדוקדקות, שיש חומרים שמשתמשים בכמות של שמנה ועשר פעמים מעל המותר, ויש דברים שהם מסוכנים ביותר לבריאות ואסור שיגעו במאכל כלל, והם משתמשים בהם דרך קבע.","b":false},{"t":"עד שנמצא שלא רק את התולעים והחרקים הם מדבירים, אלא גם מסכנים מאד את אוכלי הירקות הללו, וידוע ומפורסם שזה מסכן האדם בחלאים קשים ומסוכנים ה' יצילנו.","b":false},{"t":"והדברים הללו אמר לי אותו מומחה בפני ראשי הכשרות וכולנו נחרדנו מאד, ומאז לא מצאתי מנוח לנפשי, איך נתעלם מסכנות חמורות אלו, וחמירא סכנתא מאיסורא. ובאים להציל מאיסור חמור, ומביאים חמור יותר ויותר רח\"ל.","b":false},{"t":"ואמרתי אולי טוב לנו לשוב לדרך קדמונינו שקנו ירקות רגילים, ועשו כל אשר לאל ידם כדי להמנע מאיסור בעלי חיים החמור, ע\"י רחיצה חזקה וע\"י הורדת רוב העלים, וכן ע\"י עצות ודרכים כלים מכלים שונים. ולא לגרום לחלאים רעים ולסכן הבריות רח\"ל, ומי יודע אם אין זה בין הגורמים לרבוי החלאים ה' ישמור את עמו ישראל.","b":false},{"t":"ויש לחקור ולהעזר במומחים כדי למצא דרכים נכונות שיכולים לבער הבעלי חיים מהירק, בלא לסכן את הבריות רח\"ל. וכן למצא חומרים לשטיפת הירקות שאין בהם סכנה, ולמצא דרכים לבדיקה ע\"י רבוי האור וכדומה, ועלים שאין אפשרות לנקותם, יש להמנע מלאוכלם ככל האפשר. ויש לעודד גידולים חליפיים לאותם דברים, שמטבעם יש בהם פחות חרקים, או שניתנים לבדיקה וניקוי בדרך נוחה יותר, והבא להטהר מסייעין אותו מהשמים.","b":false},{"t":"ודעת לנבון נקל, שבודאי אבותינו ורבותינו, לא נכשלו באיסורים חמורים אלו, שהיו בודקים ואוכלים, וש\"מ דיש דרך ויש אפשרות לרחוץ ולהסיר מהם כל החרקים, ובודאי חיפשו ומצאו. ובמקומות שהיו מצויים ביותר, נמנעו מהרבה ירקות עלים, ואם תאמר שימצאו רבים שמתעצלים לעמוד בכל הנטל הכבד של נקיון חזק ובדיקה מדוקדקת ויאכלו איסורים, הן גם היום יש רבים שקונים משאר הגידולים, והם רוב רובו של העם, ובפרט כאשר יודע ברבים הסכנה הטמונה בירקות המושגחים ורעתם כי רבה, תהיה אנדרלמוסיא גדולה, וסוף דבר הכל נשמע, ויאכלו משאר הגידולים בלא רחיצה ובדיקה כראוי. ומה גם שגם הגידולים הללו אם לא בודקים כדבעי בודאי יש מכשולות. ע\"כ טוב יותר שנתחיל מעתה לתור ולאתר את הדרכים הנכונות, ולה' הישועה.","b":false},{"t":"ב. ותחילה וראש אקדים להביא דברי הגאון ערוך השלחן ע\"ה, ששלח אלי ידידי הרה\"ג הרד\"ב שליט\"א אחר שדיברתי בענין בשיעור. והוא ביורה דעה (סימן ק' סעיפים י\"ג – י\"ח) ואביא מלשונו הטהור: ודע דבכל המדינות הידועים לנו, בימות הקיץ הרחש מצוי בכל מיני מאכל, וביחוד אלו הנמלים הנקראים מילב'ין מצויין הרבה בכל מיני קמח ובכל מיני גרויפ'ין, וכמעט שא\"א להמלט מזה, ובודאי הזריזין מדקדקין בכל האפשר להמלט מזה, ועדיין כולי האי ואולי, וק\"ו כל המון בית ישראל שאינם מדקדקים, ואוכלים מכל הבא לידם כשאינם רואים להדיא המילבי'ן, וחלילה לומר שכלל ישראל יכשלו באיסור גדול כזה, ולא ניחא למרייהו דאמרת הכי, וראוי לחפש זכות, וכבר נתעוררו גדולים בדורות שלפנינו להמציא זכות בענין הגדול הזה, ונבאר בס\"ד מה שהם אמרו, ומה שנראה לענ\"ד, עכ\"ל.","b":false},{"t":"והדברים ברורים וידועים, ואע\"פ שיש מקום לומר שאם היה בימינו היה כותב שבודאי שאין לסמוך על לימוד זכות, ויש לקחת מהירקות הנקיים, מ\"מ אם היה יודע שיש באכילתם סכנה חמורה לא היה אומר כן.","b":false},{"t":"וע\"ש שהביא דברי הגאון כרתי ופלתי (רי\"ס ק') שכתב לסמוך ע\"ד רבינו שמשון והרשב\"א (שהביא שם) דבריה בטלה בקרוב לאלף, וכתב דבודאי דתמיד ימצא שיעור זה וגם יותר נגד החרקים, וכתב שכן סובר גם בה\"ג שכל דבריו דברי קבלה, וכמ\"ש בהג\"א על הרא\"ש (פ' השוכר את הפועל, במס' ע\"ז ע\"ד. סימן י\"א) וז\"ל פירש בה\"ג דשרץ לא בטיל כי אם באלף, והכי איתמר בירושלמי עכ\"ל. עו\"כ שם דהכי ס\"ל גם להרב אור זרוע דאע\"ג דבריה לא בטלה לאכול גוף הבריה, מ\"מ כשנתערבה ואינה ניכרת אינה בטלה בשישים, אבל בתשע מאות וששים היא בטלה, כדמשמע בירושלמי. עכ\"ל. ואביא מדבריו עוד להלן.","b":false},{"t":"וראיתי להר\"ן בחידושיו על הרי\"ף במס' חולין (ל\"ו ע\"א מדפי הרי\"ף) ד\"ה גרסינן בגמ' עלה דהך מתניתין ולבטיל ברובא וכו', ואחר זה כתב והוי יודע דלא מיקרי בריה אלא בשלשה תנאים וכו', ואחר שפירשם באורך. כתב בסוף ע\"א, (בד\"ה) ואיכא מ\"ד דכי אמרינן דבריה לא בטלה, היינו שאינה בטלה בששים או במאה, אבל בטלה היא באלף, והכי אמרינן בירושלמי (תרומות פ\"י ה\"ה) הורה רבי בון בהדין עכברא חד באלף. ורבינו שמשון ז\"ל למד ממשנה אחת שבמסכת תרומות (פ\"י מ\"ח) לפי מה שפירש הרב ז\"ל אותה משנה דבריה בטלה בתשע מאות וששים, וכי אמרינן בירושלמי חד באלף, כך היה מעשה. ולא מחוור, דהא קתני בריה דהיינו גיד הנשה דומיא דחתיכה הראויה להתכבד, דבתרוויהו תנן כולן אסורין, דבודאי חתיכה הראויה להתכבד אינה בטלה אפילו באלף, דבהדיא תניא (בתוספתא פ\"ז ה\"ג) חתיכת איסור שנתערבה בין החתיכות, אפילו הן אלף כולן אסורות, ודכוותה גבי בריה משמע דכולן אסורות אפילו באלף, ובירושלמי ודאי לאו מתורת בריות אתו עלה, דהיכי דמי אי לבטל פליטתה למה לי כולי האי הא בששים נמי בטלה, כדתנן בהדיא והרוטב בנותן טעם, שאין חשיבות בריה אלא שלא לבטל היא גופה, אבל לבטל פליטתה לא, ואי בשנמחית בטלה היא כמו שכתבנו, ואי בשלא נמחית יסלקנה משם, אלא ודאי בירושלמי לבטל פליטתה קאמר, דס\"ל דעכבר נותן טעם עד אלף, והיינו דמייתי התם גבי ציר דגים דאמרינן לעיל בגמרא (צ\"ט ע\"א) דשיעורו קרוב למאתים. מיהו בהא נמי פליג אגמרא דילן, דבפרק בתרא דע\"ז (ס\"ט.) משמע דעכבר לא יהיב טעמא אלא בששים. עכ\"ל. ומדבריו ז\"ל למדנו שהוא חולק על רבינו שמשון ז\"ל ומפרש בירושלמי שאמרו דמבטלים באלף כונתם על הטעם של הבריה כמו עכבר, ולא גוף הבריה. וגם בזה דעתו כתלמוד דידן בע\"ז (ס\"ט ע\"א) דעכבר לא יהיב טעמא אלא בששים.","b":false},{"t":"ג. עו\"כ בערוך השלחן שם, שגם הרי\"ף ז\"ל ס\"ל כן (דבריה בטיל באלף), שהרי השמיט כל המשנה דגיד הנשה שנתבשל עם הגידין וכל סוגיית הש\"ס, וטעמו דס\"ל כפירש\"י ז\"ל פ' השוכר (ע\"ז ע\"ד ע\"א) דתנן התם, אלו אסורין ואוסרין בכל שהוא וכו', ופירשו בגמרא דהאי תנא (תרתי אית ליה), דבר שבמנין ואיסורי הנאה. [וארחיב מעט הדברים במה שפירש\"י ז\"ל שם שכשיש שני אלה הוא דלא בטיל, וע\"כ לא מנה חמץ בפסח, דאע\"ג שאסור בהנאה אין דרכו להמנות, ולא אמר נבלה דאע\"ג דהוי דבר שבמנין מ\"מ אינה אסורה בהנאה, וע\"כ שני אלה איסורם מתבטל. וכתב הרב ערוה\"ש דלפי זה המשנה הזאת חולקת על המשנה דחולין, דתנן התם (צ\"ו ע\"ב) דגיד הנשה שנתבשל עם הגידים ואינו מכירו כולן אסורים. ובגמ' שם (סוף צ\"ט ע\"ב) שאלו, וליבטול ברובא, ותירצו, בריה שאני. וכתבו התוס' שם (ק' ע\"א) בריה שאני, ואפילו באלף לא בטיל, וכן חתיכה הראויה להתכבד לא בטלה כדאמר הכא, והיכא דפירש חד מינייהו נמי אסור וכו', ודבר שאינו לא בריה ולא חתיכה הראויה להתכבד, בטל ברוב, ואפילו איסור דרבנן ליכא. ע\"ש.] וכתב בערוה\"ש שם שהרי\"ף פוסק כהמשנה דע\"ז הנזכרת, וא\"כ נוכל לצרף גם דעת הרי\"ף ואפשר שגם דעת רש\"י ז\"ל להנ\"ל, וגם הרשב\"א ז\"ל בחידושיו לחולין (צ\"ז ע\"ב) כתב בשם הראב\"ד ז\"ל דבריה בטלה באלף ומאתים, נמצא דבה\"ג והרי\"ף והראב\"ד והר\"ש בעל התוספות והרשב\"א ואור זרוע ואפשר גם דעת רש\"י כן. ומה שהקשה הרא\"ש על שיטה זו מסוגיית הש\"ס יש ליישב ע\"ש.","b":false},{"t":"וראיתי בקובץ מפרשים (על הרא\"ש בתלמוד הוצאת עוז והדר) שפירשו דברי הגהות אשרי הנ\"ל באופן אחר, שהזכיר שם שהר\"ן פירש את הירושלמי דאיירי בפליטת טעמו דנותן טעם עד תתק\"ס, ולא קי\"ל כן, דבסוגיין אמרו דעכברא בטילה בשיכרא (דבמסקנא אמרו בששים).","b":false},{"t":"עו\"כ שם ולפ\"ז יש לעיין בהג\"א, שאחרי זה הביא בשם בה\"ג, דשרץ לא בטיל כי אם באלף והכי איתמר בירושלמי, ואין לסמוך על זה, כיון שתלמוד שלנו חולק על זה ופסיק, עכברא בין בחלא בין בשיכרא בששים. עכ\"ל. וכתבו בקובץ מפרשים שם (אות א') דנראה מזה דדעת בה\"ג, דילפינן מהירושלמי דאפילו לטעמו בעינן תתק\"ס, וכהר\"ן הנ\"ל, שהבין כן בירושלמי, וא\"כ לא מוכח מידי מהירושלמי שסובר שגופו בטל בהאי גוונא, וצ\"ע בפוסקים, אמנם הגה' ראשונה (הכונה לדבור הראשון שבהגה\"א הנ\"ל), נעתקה מאור זרוע ושניה מהתוס', וכבר נחלקו הראשונים בפירוש הירושלמי. ארץ צבי. עכ\"ל.","b":false},{"t":"ובאמת בכרתי ופלתי שהביא בערוה\"ש הנז', למד שגם בה\"ג שבהגהות אשרי הנז', מבאר כונת הירושלמי, שהבריה גופה מתבטלת בתתק\"ס, ולא מיירי הירושלמי בטעם של הבריה, אלא בגופה של הבריה, וכמ\"ש בהג\"א לפני כן משם הא\"ז. אלא שלשון הגהת אשרי לא משמע כן, דאחר שכתב שם, שבה\"ג כתב דשרץ לא בטיל אלא באלף כדאיתא בירושלמי, הוסיף וכתב שאין לסמוך על זה, כיון שתלמוד שלנו חולק ופסיק עכברא בין בחלא בין בשיכרא בששים. עכ\"ל. ובתלמודנו בודאי דמיירי מהטעם של העכבר, שע\"כ אמרו בששים, וכתב שהוא חולק על הירושלמי, וש\"מ שהרב הגה\"א הבין שבה\"ג למד גם בדברי הירושלמי, שמדבר על הטעם ולא על גופה של הבריה. והיינו כהבנת הר\"ן ז\"ל בירושלמי, (שהבאתי לעיל את לשונו). וכמו שכתב ארץ צבי הנזכר, וצ\"ע בדברי הכו\"פ בפנים, ואולי למד שבעל הגה\"א הוא שהוסיף וכתב ע\"ד בה\"ג, שאין לסמוך על זה כיון שתלמוד שלנו וכו'. ולפי זה בה\"ג באמת סובר שגם גופה של הבריה בטל בתתק\"ס. וצ\"ע.","b":false},{"t":"ד. ואבא לעיין במשנה דתרומות (פ\"י מ\"ח) דתנן, דג טמא שכבשו עם דג טהור, כל גרב שהוא מחזיק סאתים, אם יש בו משקל עשרה זוז ביהודה שהן חמש סלעים בגליל דג טמא, צירו אסור, רבי יהודה אומר רביעית בסאתים, ורבי יוסי אומר אחד מששה עשר בו. ע\"כ.","b":false},{"t":"ופירש הרע\"ב ז\"ל כל גרב שהוא מחזיק סאתים, אם נכבש דג טמא עם הרבה דגים טהורים בתוך חבית והחבית מחזיק סאתים, ויש מציר דג טמא משקל עשר זוזים של יהודה, שהם חמש סלעים של גליל, וכל השאר ציר דג טהור, שנמצא ציר דג טמא אחד מתשע מאות וששים של דג טהור אסור, ואם היה הציר של דג טמא פחות מכן, מותר. עכ\"ל. וע\"ש שאחר שפירש דברי ר' יהודה ור' יוסי דמתניתין כתב, והלכתא דציר בטל ביותר מאלף, אם יש יותר מאלף מדג טהור, ואחד מדג טמא הכל מותר, ואם לאו הכל אסור. עכ\"ל.","b":false},{"t":"מדברי רבינו עובדיה ז\"ל נראה דפוסק לבטל באלף כמו שפסקו בירושלמי, אלא שמדקדוק לשונו עולה דלא מבטלים הדג עצמו אלא מבטלים הציר שלו, ולפי\"ז אפשר דבריה לא בטלה גם באלף. אלא דלפי\"ז קשה לי טובא בדבריו ז\"ל דאם הבין כך בירושלמי איך כתב, והלכתא דציר בטל באלף והלא כבר פסקו בגמ' דילן שם (ע\"ז דף ס\"ט ע\"א) בהאי לישנא, והלכתא אידי ואידי (בין בחלא בין בשיכרא) בשתין, וכן כל איסורין שבתורה. ע\"כ. ומאי שנא ציר דג טמא דמצריך הרע\"ב ז\"ל יותר מאלף. ובתוספות רעק\"א (תרומות פ\"י מ\"ח) שם כתב ע\"ד הרע\"ב ז\"ל הנז', וז\"ל, והטעם דאיתא בירושלמי הורה ר\"י ב\"ר בון בעכברא (שם מקום) אחד לאלף, וס\"ל להרע\"ב דהורה היינו לאיסור, דבאלף אסור וביותר מותר, כ\"כ הפר\"ח (יו\"ד סימן פ\"ג). והר\"ש פירש דמתניתין לא מיירי בטעם רק בדג טמא שנתערב עם דגים טהורים, דמתסרי כולהו משום דבריה לא בטלה אלא בתתק\"ס, והירושלמי דהורה א' לאלף לאו דוקא דה\"ה בתתק\"ס ע\"ש. עכ\"ל.","b":false},{"t":"נמצא דגם רעק\"א ז\"ל הבין בדברי ר\"ע מברטנורה ז\"ל דמפרש בירושלמי שהטעם והציר בטל באלף ולא עצם הדג, וע\"כ הביא כנגד זה לדברי הר\"ש שפירש דמתניתין לא מיירי בטעם, אלא בדג עצמו שהוא טמא שנתערב בדגים טהורים שכולם אסורים עד שיהיה תתק\"ס נגד הטמא. והיינו כמו שפירשתי בעניותי את דברי הרע\"ב ז\"ל, אלא דקשה על זה כמו שכתבתי. (וע\"ל בדברי הלח\"מ).","b":false},{"t":"ובעצם זה כלול בהערת הר\"ן ז\"ל בחולין הנז', דפירש שהירושלמי מיירי בטעם ולא בגוף הדבר האסור, וכתב ע\"ז דלא קי\"ל כן, אלא כתלמודין דבטל בששים.","b":false},{"t":"והנה התוי\"ט שם הביא דברי הרע\"ב ז\"ל, שפירש שמשקל עשרה זוז הם א' מתתק\"ס, והביא דברי הירושלמי שמפרש כיצד, סאה עבדה כ\"ד לוגים ולוג ב' ליטרא וליטרא ק' זוז, נמצא דסאתים עולים לצ\"ו מאות זוז, וצ' מאות הם עשר פעמים תשע מאות, נשאר ו' מאות שהם עשר פעמים ששים. (כלומר צ\"ו מאות הם עשר פעמים תתק\"ס 960X10=9600 והם 96 מאות). ובמשנה אמרו עשרה זוז, נמצא שלכל זוז תתק\"ס אחד. ע\"כ. ועיין בתפארת ישראל יכין אות ל\"ה.","b":false},{"t":"עו\"כ התוי\"ט בהמשך שם, רבי יוסי אומר אחד מששה עשר בו, וכתב רש\"ל בספר ים של שלמה פ' גיד הנשה (סימן מ\"ח) דנ\"ל טעמו, מדתנא קמא בעיא תתק\"ס [כמ\"ש הרע\"ב לעיל] שהוא שיעור ט\"ז פעמים ששים [צריך להוסיף: שעל כן אמר ר' יוסי א' מששה עשר בו, כלומר א' מט\"ז שבתתק\"ס שזה עולה ששים]. וכתב שכהאי גונא כתב המ\"מ, אלמא שיעור ששה עשר היה מצוי בשיעורי חכמים לחומרא וה\"ה לקולא. ע\"כ. ואכתי קשיא לי דערבך ערבא צריך, דמה טעם יש בשיעור ששה עשר, ובספר תורת האשם כלל מ\"א דין א' הארכתי קצת. עכ\"ל.","b":false},{"t":"ה. ודברי הרע\"ב ז\"ל הנ\"ל, מקורם ברוך בפירוש המשניות להרמב\"ם ז\"ל, שכתב בתחילת משנה ח' שם את דברי ת\"ק, ואח\"כ כתב, וביארו בגמרא שהוא חלק מתשע מאות וששים, וזה מבואר אחר שזכרנו כי הלוג שני ליטרא, והליטרא מאה זוז שהם נ' סלעים. ורי\"א עד שיהיה שיעור רביעית מדג טמא בשיעור סאתים מדג טהור ואז יאסר צירו. ורבי יוסי וכו'. וההלכה חלק באלף אסור, ואם הוא חלק מדג טמא ביותר מאלף מדג טהור אז יהיה צירו מותר. עכ\"ל.","b":false},{"t":"ולשון הרמב\"ם ז\"ל בהלכה שכתב הוא שונה מזה שכתב הרע\"ב ז\"ל, ובלשונו זה היה אפשר לפרש, שלא על הציר והטעם לבד הוא מדבר אלא על הדג עצמו, ונמצא לפי\"ז שהרמב\"ם סובר שגם הבריה עצמה בטלה בתתק\"ס, ומ\"ש בסוף דבריו: אז יהיה צירו מותר אולי מיירי בשמכיר הדג הטמא. אך עדיין צ\"ע בזה דאי מכירו וזורקו למה צריך תתק\"ס, אלא ע\"כ שהעיקר הוא שגם הרמב\"ם מפרש בירושלמי דמדבר על הציר ולא על גוף הדג.","b":false},{"t":"ובפירוש הרמב\"ם ז\"ל בתרגום החדש (של מכון המאור) כתוב בזה\"ל: וההלכה שאם היה חלק אחד של דג טמא עם מאתים דג טהור, יהיה ציר הכל מותר. עכ\"ל. וגם כאן מפרש דקאי על הציר ולא על עצם הדג.","b":false},{"t":"ואולם בהלכות מאכלות אסורות (פ\"ט סוף הלל\"ד) כתב וז\"ל, דג טמא שכבשו עם דג טהור [ציר] הכל אסור, אלא א\"כ היה הטמא אחד ממאתים מן הטהור. עכ\"ל. וע\"ש בפירוש הרדב\"ז ז\"ל.","b":false},{"t":"ובלחם משנה שם הזכיר את המשנה דתרומות (פ\"י מ\"ח) הנ\"ל וכתב, ומפרש רבינו מתניתין דאיירי לענין איסור הציר היוצא מן הדג הטמא שהוא נותן טעם, אבל לא לענין הדג עצמו, דודאי אם הדג עצמו נתערב לא בטיל, דבריה לא בטיל. והכי דייקא מתניתין דקאמרה שכבשו, דאם איירי באיסור הדג עצמו, שנתערב למה לי כבישה, לימא שנתערב, אלא ודאי לענין איסור הציר איירי מתני', ותנא קמא סבר דאם יש משקל עשרה זוז שהוא חלק א' מתתק\"ס מהדג הטמא, אז ודאי צירן אסור, כמ\"ש רבינו בפי' המשנה, וטעמו דת\"ק דאע\"ג דשאר האיסורים בששים, שאני ציר שהוא חריף וקשה, ושיערו חכמים שיעור א' בתתק\"ס נותן טעם, ור' יהודה אומר דדי ברביעית בסאתים שהוא קרוב לאחד למאתים, וכמ\"ש הרע\"ב ז\"ל, ור' יוסי מקל טפי ואומר א' מששה עשר בו, ופסק רבינו כסברא אמצעית והיינו כר' יהודה וע\"כ כתב א' ממאתים, כנ\"ל לישב דעתו.","b":false},{"t":"עו\"כ שהרב רבינו שמשון ז\"ל בפי' המשנה שם, אינו סבור כן. אלא דמתניתין איירי בענין ביטול הדג עצמו, ומאי דקאמר שכבשו אורחא דמילתא נקט, והברייתות שבירושלמי שדברו על איסור הציר, כתב הוא ז\"ל שאינו ענין למשנתנו שבמשנה מדובר בבטול הדג עצמו. ונדחק בזה מפני שהוא סבור דבכל האיסורין לא משערים אלא בס' לענין הטעם, וע\"ש שהאריך לבאר דברי הר\"ש ודברי רבינו, והסיק, ופירוש רבינו וגירסתו נראית עיקר מפני שהר\"ש דחק הרבה בפירוש המשנה והירושלמי. עכ\"ל.","b":false},{"t":"ובנובי\"ק (חיו\"ד סימן כ\"ו ד\"ה ובזה) הזכיר המשנה דתרומות (פי' מ\"ח) כל גרף וכו' צירו אסור, והקשה למה נקט \"צירו אסור\" והול\"ל הכל אסור, ובשלמא לפירוש הר\"ש דמיירי שאינו מכיר הדג הטמא ונתערב עם טהורים נמצא אפילו יש תתק\"ס, הציר מותר והדגים אסורים, שהרי אינו מכיר איזה טהור ואיזה טמא. ולדעת הר\"ש אם היה מכיר הגוף הטמא ומוציאו לא היה נאסר אלא עד ששים, ופירושו דחוק מאד ועיין לח\"מ סו\"פ ט\"ו ממ\"א. (הוא הלח\"מ הנ\"ל).","b":false},{"t":"אבל להרמב\"ם דהכל משום נתינת טעם, היה צ\"ל הכל אסור, שגם הדגים הטהורים נאסרים מחמת הציר הטמא, וכתב הנוב\"י שעלה בדעתו ללמוד מזה שהדג אינו בולע בכבוש, וע\"כ לא נאסר אלא הציר שהוא צלול, אבל מה אעשה והרמב\"ם כתב בפירוש דג טמא וכו' הכל אסור אא\"כ היה א' ממאתים, וא\"כ גם הדג טבעו לפלוט וגם לבלוע בכבוש. עכ\"ד. ולענ\"ד נראה להוכיח כן ממה שאמרו במשנה, שהדג הטמא פולט צירו וטעמו ואוסר את הטהורים, ואחר שמבואר שפולט טעמו ע\"י כבישה, י\"ל דכמו שפולט ע\"י כבישה, ה\"נ בולע ע\"י כבישה.","b":false},{"t":"ובמרכבת המשנה (הל' מ\"א פט\"ו הלל\"ד) כתב משם שו\"ת הרשב\"א (סימן שצ\"ב) שכתב דהרמב\"ם ז\"ל פסק כר' אבהו דציר במאתים, ובשער אפרים שנ\"א הקשה דילמא איירי בדג עצמו שנתערב והוא חתוך דלא חשיב בריה, וכתב המרכה\"מ דלק\"מ דא\"כ למה כתב רבינו שכבשו, עיין לח\"מ (הנ\"ל), וכ\"כ רבינו להדיא לעיל בהלכה זו, נאסר מפני צירו, והוא דבר הלמד מענינו. עכ\"ל. ולענ\"ד י\"ל דאם מיירי בחתיכת דג למה צריך מאתים, והלא ביבש ביבש סגי ברובא, ואם משום שבלע ע\"י הכבישה, א\"כ היינו ציר שהוא עובר ע\"י הכבישה, ופולט ונבלע, ומפני חריפותו וחוזקו צריך מאתים וכמ\"ש הלח\"מ, וזה שפירשו דמיירי בציר ופשוט.","b":false},{"t":"עו\"כ במרכה\"מ שם בסו\"ד, ורבינו פסק כר\"י, וחזר בו מפי' המשנה דשם פסק כת\"ק, (שצריך תתק\"ס), הואיל ובחולין (צ\"ט.) א\"ר יוחנן שהרי ציר שיעורו קרוב למאתים, וכן בירושלמי יש מי שפוסק כר\"י. עכ\"ל.","b":false},{"t":"ועיין בספר הליקוטים ברמב\"ם הוצאת הר\"ש פרנקל, ובשו\"ת רלב\"ח שם, על הלכה זו.","b":false},{"t":"ו. עוד בענין בריה יש פוסקים דס\"ל שהתולעים הנולדים בפירות אפילו רחשו ויצאו ונאסרו, מ\"מ אין להם דין בריה משום שאין איסורן מתחילת לידתן, ואע\"פ שרבו החולקים, מכלל פלוג' לא נפק.","b":false},{"t":"ועיין מטה יהונתן (ברס\"י ק') על מה שכתב מרן ע\"ה בתחילת הסימן, בריה דהיינו כגון נמלה, או עוף טמא, וגיד הנשה וכו', אפילו באלף לא בטלה. וכתב הגר\"י אייבשיץ ז\"ל במט\"י שם, ולענין פרעוש אי הוי בריה או לא, פלוגתא בין רבוותא האחרונים, ועיקר שדין זה תליא בפלוג' הר\"י מאורליינש ור\"ת שהביאו התוס' פ\"ק דשבת, דלר\"ת דס\"ל דחייב משום שבת (אם הרגו) א\"כ אית ביה חיותא שפיר הוי בריה, משא\"כ לר\"י דפטור עליה משום שבת, אלמא דלית בית חיותא וליכא שם בריה עליה, ועיין שו\"ת צ\"צ. עכ\"ל. ודבריו ז\"ל סובבים על מה שכתב מרן ז\"ל בהמשך הסעיף הנז', דאין לו דין בריה אא\"כ הוא דבר שהיה בו חיות, לאפוקי חיטה אחת של איסור. ועפי\"ז הזכיר המחלוקת אם פרעוש הוי בריה או לא.","b":false},{"t":"ובהג\"ה ע\"ד מט\"י הנז', כתוב בזה\"ל, ועיין בכרתי ופלתי דהביא מחלוקת הפוסקים אי צריך שיהיה אסור מתחילת ברייתו, דעת הרא\"ש דא\"צ שיהיה אסור מתחילת ברייתו רק דכל שיחלק ואין שמו עליו מקרי בריה, וכתב דמזה יצא לנו דין גדול שהתולעים קטנים המתהוים בעפושי הפירות, דכל זמן שלא פירשו מותרים, א\"כ אין כאן איסור מתחילת ברייתו וכו', הילכך לדידן דקי\"ל כהרשב\"א דבעי' נאסר מתחילת ברייתו, (שלא כהרא\"ש הנז') לא מיקרי בריה, ומיהו ח\"ו להקל בזה.","b":false},{"t":"וכתב ע\"ז הגאון מוהר\"ר בצלאל הכהן ז\"ל מ\"צ דווילנא על גליון כרתי ופלתי שלו, שבשו\"ת טורי אבן (סי' כ\"ו) חולק ע\"ז והביא לשון הרשב\"א בתו\"ה הארוך (בית ד' שער א') ואיזה בריה שאינה בטלה דוקא שאסורה מחמת עצמה כנמלה וגיד הנשה שאיסורן מחמת עצמן מתחילת ברייתן, אבל בריה מותרת שקיבלה איסור מחמת דבר אחר, כגון שור הנסקל וצפורי מצורע ותרנגולת טריפה, אין זה בריה שאינה בטלה. עכ\"ל האו\"ה. וכתב הטורי אבן, ומשמע שאיסור מחמת עצמה ומתחלת ברייתה חדא מילתא היא, כלומר שאסורה מחמת עצמה מחמת ברייתה, שברייתה וצורתה גרמה האיסור, שאותה בריה אסרה התורה לפי שהיא בצורה זאת, כגון נמלה וכו' ודאי חשובה בריה ולא בטלה, לא שנא נאסרה מתחילת ברייתה או באמצע ימיה, כיון דברייתה גרמה האיסור הוי כנאסרה מתחילת ברייתה שמתחילת ברייתה אסורה משעה שתרחש ותפרוש ממקום למקום. אבל אם אח\"כ קיבלה איסור כצפורי מצורע וערלה וכו', שלא צורתה גרמה האיסור אלא דבר אחר היא בטלה, עכ\"ד הטורי אבן. והג\"ר בצלאל הכהן ז\"ל כתב אמנם אין בכל זה לדחות דברי הגאון בעל הפלתי ז\"ל, ויש מקום לבעל דין לחלוק ולומר שגם בנבלה, הלא אין איסור זה נוהג בכל הבע\"ח, כגון דגים וחגבים שאין נוהג בהם דין נבלה וטרפה, וא\"כ בהמה וחיה ועוף שנוהג בהם הוא חשיב מתחילת ברייתן שצורתם היא הגורמת להם איסורם, ומה לי איסור טריפות מה לי איסור שקצים ורמשים, ודו\"ק. עכ\"ד הג\"ר בצלאל הכהן ז\"ל. ובמקום אחר כתבתי ע\"ז והבאתי דברי מרן החיד\"א ז\"ל ועוד. ואכמ\"ל.","b":false},{"t":"על כל פנים מכלל פלוגתא לא נפק דלדעת הכו\"פ כל התולעים שנוצרים תוך הפרי או הירק, ואח\"כ פורשים ונאסרים אין להם דין בריה והם בטלים בששים כשאר האיסורים. וכן דעתו של הגאון רבי בצלאל הכהן מו\"צ דווילנא.","b":false},{"t":"ז. ובפ\"ת (סק\"א) שם הזכיר דעת הכו\"פ הנז', ושבטורי אבן (סימן כ\"ו) חולק ע\"ז ופסק דגם זה מיקרי בריה ולא בטלה. עו\"כ הפ\"ת דבמשכנות יעקב (סי' ל\"א) למד היתר אחר על המילוי'ן, ומסיק למצא זכות וצד היתר על אכילת קמח בימות החמה הגם שהוא קרוב לודאי שיש בו מילוי'ן ע\"ש. ומזה שהרב פ\"ת הביא דברי המשכנות יעקב שמלמד זכות על ישראל שאוכלים קמח וכדו' בימות החמה, הגם שהוא קרוב לודאי שיש בו מילוי'ן ולא העיר עליו כלום, משמע דניחא ליה בזה.","b":false},{"t":"עוד יש לצרף מ\"ש הרמ\"א ז\"ל בהגה (בסימן ק\"ג ס\"א) וז\"ל. מיהו דברים החשובים, כבריה או כיוצא בה, אם אינם פגומים בעצמם, אע\"פ שפוגמים התבשיל, אינן בטלים אפילו באלף. (וכ\"כ הארוך כלל ל\"ב). עכ\"ל.","b":false},{"t":"וע\"ש בצבי לצדיק (בגליון הש\"ע) שכתב וז\"ל, משמע דאם פגומים בעצמם גם בריה בטיל, ולפ\"ז לא אדע למה החמירו כ\"כ האחרונים בסימן פ\"ד בענין מילבי'ן ושארי תולעים הפגומים בעצמם דלא בטלים הם בששים כה\"ג. עכ\"ל.","b":false},{"t":"ואולי צ\"ל דהחמירו משום שי\"ח על הרמ\"א ז\"ל בזה, וס\"ל דאפי' פגומין מעצמם יש להם דין בריה, וכמ\"ש בפ\"ת שם (סק\"א) וז\"ל וע\"ש עוד שחלק על הרמ\"א ופסק דבריה אף שנסרח אינה בטלה באלף, ובשאר דברים חשובים כמו חתיכה הראויה להתכבד וכיו\"ב מודה להרמ\"א. עו\"כ, שגם אא\"ז בתשו' פנים מאירות ח\"ב (סימן ס\"ז) חולק על הרמ\"א בזה וסובר ג\"כ דבריה אפי' פגומה בעצמה אינה בטלה, והבאתיו לעיל (סי' ק' סק\"ג), והסכים עמו הגאון בעל חות יאיר שם. עכ\"ל. וי\"ל דלכן החמירו. ואי לאו דמסתפינא הייתי אומר שיש קצת לימוד לשיטתם ממ\"ש ברי\"ס ק', כגון נמלה וכו'. ונמלה היא מאוסה מצד עצמה, וחשיבה בריה ולא בטלה, ואולי יש לחלק בין נמלה לתולעים, ולא מסתבר.","b":false},{"t":"ובחידושי בית מאיר (בגליון הש\"ע שם) כתב ע\"ד הרמ\"א ז\"ל, משמע דאם פגומים בעצמם לא חשיבי ובטלים, וע\"כ היינו דוקא בריה כמו עכברא דדברא שהיה חשוב ונפגם אח\"כ, אבל דברים שפגומים מעיקרא כתולעת וכיוצ\"ב ומ\"מ התורה אוסרתו שפיר חשיבי ולא בטלי, כדמשמע מכל הפוסקים ודוכתי טובא. אח\"ז כמה שנים מצאת בתשו' פ\"מ ח\"ב (סי' ס\"ז) חקר אחר הגה זאת, ולענ\"ד כונתו כמו שכתבתי ע\"ש ודו\"ק.","b":false},{"t":"עו\"כ הב\"מ, ששו\"ר שהפר\"ח כבר קדמו בפירוש זה אלא מה דמשמע מיניה דאיירי שנפסל מאכילת אדם אינו מוכרח, אלא כל שנסרח עד שטעמו לפגם שוב בטל החשיבות לענין התערובת, אע\"פ שלאוכלו בעינו עודנו באיסורו עומד, מ\"מ חשיבות בריה אין עליו. אך מ\"מ נראה שהדין עמו דכל זמן שראוי לאכילת אדם ולוקין עליו בפחות מכזית, גם לענין התערובות נשאר בחשיבותו, ועיין בס' פמ\"ג. עכ\"ל.","b":false},{"t":"ומדברי הב\"מ בודאי נראה דהבין ברמ\"א שלא כהבנת הרב צבי לצדיק. דהב\"מ מבאר דתולעים וכדו' דין בריה עליהם תמיד, ובהגה זו מדבר בדבר שהיה משובח ונפגם וכנ\"ל. וכאמור כן משמע מדברי השו\"ע וכל הפוסקים בריש סימן ק', וכנ\"ל.","b":false},{"t":"שו\"ר בגליון מהרש\"א ז\"ל שהעיר מנמלה וכמ\"ש בעוניי, שכתב על דברי ההגה הנז', משמע דפגום מעצמו בטל, ובאמת זה אינו דהא נמלה פגום בעצמו, ועיין תשו' פ\"מ ח\"ב (סי' ס\"ז וסימן ס\"ח), וכן משמע מסימן ק\"ד ס\"ג, ממ\"ש ונמחה גופם, משמע דכל שהוא שלם אינו בטל, אך בפר\"ח כאן ביאר היטב דפגומן מעצמם, היינו שבעצם אינו פגום כמו צפור טמאה ואח\"כ הבאיש ונסרח, ולקמן סימן ק\"ד היינו שבעצם הוא נמאס. ולדעתי בדעת הרמב\"ם בנמאס מעיקרו אף שהבאיש ונסרח גם אח\"כ מ\"מ אסור, ועיין תוס' ע\"ז (ס\"ט ע\"א) דרגלי דבורים עצמות נינהו ומותרים. (ומשמע ממהרש\"א ז\"ל שגם הוא הבין שהרמ\"א מקיל בזה).","b":false},{"t":"והרב כה\"ח (בסימן ק\"ג סק\"ו) כתב שעכברים וזבובים ושקצים ורמשים שהם פגומים מעיקרם אם נסרחו אח\"כ ואינם ראויים למאכל אדם בטלים הם ברוב אם נתערבו, או\"ה, וכן משמע במ\"מ (פ\"ב מהמ\"א דין כ\"א), פרי תואר (אות ב'), ודלא כהפר\"ח שם שאוסר, ער\"ה (אות א') חוו\"ד אות ג', מש\"ז אות ב', והחק\"ל (חי\"ד סימן ע\"א) ג\"כ דחה את הפר\"ח בזה, זב\"צ אות ה'. ע\"כ.","b":false},{"t":"ח. עו\"כ בערוך השלחן שם ע\"ד הכרתי ופלתי הנ\"ל, והנה דברי הגאון א\"צ חיזוק, והרי בריש נדה אמרו מעשה ועשה רבי כרבי אליעזר, לאחר שנזכר שרבים פליגי עליה, אמר, כדאי הוא ר\"א לסמוך עליו בשעת הדחק, ע\"ש. הרי דאפילו ביחיד במקום רבים סמכינן בשעת הדחק באיסור דרבנן, והכא נמי איסור דרבנן הוא, כמ\"ש בסעיף ב', וא\"כ אפילו הוה רוב דעות לאיסור, בשעת הדחק כזה שאי אפשר לצייר (אולי צ\"ל: להזהר) אא\"כ לא נאכל לחם וגרופי'ן, ודאי סמכינן, וק\"ו כשיש הרבה מרבותינו הקדמונים (שמתירים כנ\"ל) שנוכל לסמוך בשעת הדחק. עכ\"ל.","b":false},{"t":"וכונת הערוה\"ש דהוי דרבנן, היינו התערובת דמן התורה בודאי גם הבריה בטלה ברוב, אם הוא יבש ביבש, או אם מבושל בטלה בששים. מלבד דברים חריפים כמו ציר דג טמא שפסק הרמב\"ם ז\"ל להצריך מאתים כנגדו כמ\"ש בסוף פרק ט\"ו מהמ\"א הנ\"ל. ואפשר שגם זה הוא חומרא דרבנן. ודין בריה בודאי שלדעת רוב ככל הפוסקים מדרבנן הוא דאינה בטלה מפני חשיבותה. ובדרבנן אמרו כדאי הוא דעת יחיד לסמוך עליו בשעת הדחק.","b":false},{"t":"ועוד נלע\"ד להוסיף על דברות קדשם של הכו\"פ ושאר הפוסקים והגאון ערוה\"ש ע\"ה, די\"ל דע\"י הרחיצה החזקה והעיון המדוקדק וכו', כמ\"ש לעיל, לפחות הוי ליה ספק אם נשארו בו תולעים או לא, ואת\"ל שנשארו יש עוד ספק אולי נחתך מהם איזה אבר בחיתוך שחותכים הירקות לסלט או למרק, וספיקא דרבוותא כהנ\"ל והו\"ל ס\"ס ויש להקל בדרבנן, בפרט בשעת הדחק הזה. וגם יש ספק שנימוח בבישול. ובפרט שהגאון בעל החזון איש ע\"ה בהלכות תולעים (סימן י\"ד א אות ו') ד\"ה ושיעור נמוח וכו', כתב בזו הלשון: ונמוח שמתבטל אין חילוק בין מתמעך בקדרה מחמת חום הבישול, ובין מתמעך בפיו ע\"י לעיסה, וכל שנתבטלה ממנו הכרת העין קודם הבליעה, יש כאן דין ביטול יבש ביבש. וכל שנתבטלה צורתו קודם הבליעה בטל מניה דין בריה. וכו'. עכ\"ל. [ועיין עוד שם שהתיר בכמה דברים מכוח ס\"ס ועוד אשוב להביא מדברות קדשו ע\"ה.]","b":false},{"t":"והנה לדעת הגאון ע\"ה גם המיעוך והחיתוך שנעשה תוך כדי הלעיסה של האוכל, בטרם יכנס בבית הבליעה, גם הוא חשיב מיעוך, ומאז אין לה דין בריה ומתבטלת כמו כל האיסורים, נמצא דיש כאן כמה ספקות וס\"ס, ספק בכל חתיכה של ירק אם היה בה חרקים ותולעים, ואת\"ל היו שם, שמא יצאו משם ע\"י הרחיצות והנקיונות כלים מכלים שונים, ועוד יש ספק שמא נחתכו בחיתוך הירקות, או נתפרק מהם איזה אבר על ידי החיתוך וע\"י הטלטולים בשפשוף וגם ברחיצה, וכן בבדיקות המרובות. ותו אין להם דין בריה דאינה בטלה, ואם הם ירקות המתבשלים במרק ושאר בישולים שמא נמעך ונחתך מן החום והבישולים המרובים, ועצם הביעבוע של הרתיחה יכולים לפרק מהם רגל או כנף, וק\"ו שגם בוחשים כל הקדרה כמה פעמים. ועוד ספק נוסף שמא נחתך ונמעך בלעיסה שהאדם האוכל אותם ירקות לועס בין שיניו, ואפילו את\"ל שנשאר איזה בריה שלמה אחר כל הדברים האלה, יש ספק פלוגתא דרבוותא שמא הלכה כמ\"ד דבריה עצמה בטלה בתתק\"ס או באלף, וכמעט תמיד יש אלף נגד הבריות הקטנטנות הללו, וכמ\"ש בעל ערוה\"ש ועוד. וכל אותם ספקות הם בדרבנן וכנ\"ל, ועוד שהוא שעת דחק גדול עצום ורב. ויש להתיר לפחות בדיעבד. וטוב לנו לסמוך על כל הספקות הנ\"ל, אחר השקעת מאמצים רבים בנקיון של הירקות, מאשר ליכנס לסכנות גדולות כאלה רח\"ל.","b":false},{"t":"והנה בדברי החזו\"א שם (הל' תולעים סימן י\"ד, א, אות ו') דן בכינים שנמצאים בדג, שהחכמת אדם אסרם, משום שכתב שהם באים מעלמא, והחזו\"א כתב שאחר חקירה התברר שהם נמצאים מעל עור הדג, ונראה שמתהוין על העור ולא מעלמא קאתו, והדין נותן להתירן כל זמן שלא פירשו, אלא שלפעמים תוך כדי הניקוי פורשים על היד וחוזרים, והו\"ל פירשו. ואפילו אם נדחפו ממקום למקום אפשר דחשיב פירשו (ע\"ש שכתב דאם מסירין אותם בסכין ומניחים אותם במים הם חיים במים), ואחר כל זה כתב בזה\"ל: ולפ\"ז אם כבר נתבשלו יש להתיר דיעבד מחמת ס\"ס, ספק אם פירשו, ואם פירשו ספק אם חזרו, ואם חזרו ספק אם נימוחו, וכמו שכתב הרשב\"א בתשובה שהביא הב\"י (בסימן פ\"ד), והט\"ז בסי' י\"ז במעשה שהביא, ובנקודות הכסף אוסר במעשה הט\"ז משום שהמילבי'ן מצויין ואינו ספק וכו', ומ\"מ מודה הש\"ך בספק גמור דמצטרף ספק נמוח להיות ס\"ס, עכ\"ל.","b":false},{"t":"ואע\"ג דבירקות ובעלים הוי מצוי כמו המילבי'ן, ולהש\"ך אפשר דלא נחשב ספק, מ\"מ בכהאי גוונא שרוחצים ומשפשפים במים וסבון וכל הדרכים האפשריים, וגם בודקים בעיון טוב, י\"ל דיודה הש\"ך בכה\"ג דחשיב ספק.","b":false},{"t":"ט. עו\"כ החזו\"א שם, ושיעור נמוח, היינו שאין העין מכירתו כלל, הלכך מתבטל כדין יבש ביבש, אבל אם העין מכירתו כשיפגשנו, אע\"ג שאין כוח באדם לחפש אחריו, חשיב כאיסור ניכר ולא בטל. ואם אין העין מכירתו מחמת קטנותו ועדיין הוא שלם, אינו בטל מדרבנן מדין בריה, והילכך בהני כיני דגים, יש לצרף ספק נמוח, דמסתבר דמתבטלת הכרתן ע\"י בישול והוי כמו רוב להיתר, ואף אם יש ספק אם הם שלמים, אין כאן רק ספק דרבנן של בריה, אבל מסתבר כיון שבטלה הכרתה, חשיב בלבול צורה ובטל דין בריה וכמ\"ש הרשב\"א בתשובה שבב\"י (סס\"י ק\"ד), ונמוח שמתבטל אין חילוק בין מתמעך בקדרה מחמת חום הבישול, ובין מתמעך בפיו ע\"י לעיסה וכו' (כמ\"ש לעיל). עכל\"ה.","b":false},{"t":"והארכתי בהעתקת לשונו הנזכר, שהוא קרוב מאד לנידון דידן, ולא מיבעיא בירקות מבושלים במרק ושאר סוגי בישולי ירקות, דיש להתיר מכוח ס\"ס כאשר כן העלה החזו\"א בדגים, אלא אפי' בירקות הנחתכים לסלט נלע\"ד שיש להקל, שעל ידי השטיפות ורחיצות ורובי השפשופים ע\"י מברשת ובידיו עם רבוי חומרי הניקוי, אעפ\"י שזה פחות מהבישול מ\"מ הוי ספק אם עודנו עומד במקומו, ואם עומד ספק אם פירש או לא פירש כלל, ומצטרפים גם שאר הס\"ס וכנ\"ל.","b":false},{"t":"ועיין עוד בהמשך דברי החזו\"א שם (ד\"ה ובמעשה דהט\"ז יש מקום להקל וכו'), דנראה שנוטה דעתו לפסוק בזה כהט\"ז ולא כהש\"ך בנקודות הכסף שחולק עליו.","b":false},{"t":"וכתב שם, וז\"ל, ואף אם יש כאן ספק בריה הוי ספק דרבנן, וגם שעל הרוב מתבלבל צורתה בבישול, ואפשר דכל שאין העין שולט בו לאו בריה היא, ולא דנו בסימן ק\"ד אלא בשרץ כעדשה לדעת רש\"י דחשיב בריה, ובזה הגם שנתערב יבש ביבש ואינו ניכר, מ\"מ לא אבד חשיבות בריה, דגופו קיים וניכר, אלא מפני שנתערב בגופים אחרים כתוארו, אין העין מבחנת בינו לבין אחרים, ועיין מש\"כ לקמן סימן ל' סק\"ג. עכ\"ל.","b":false},{"t":"י. והן עתה הראוני שבספר קנות דעת (הל' תערובות סימן ק' אות ט') הביא דעת החזו\"א הנזכרת שגם מעוך בפה קודם הבליעה חשוב מיעוך ובטלה ממנו דין בריה, וכתב שלכאורה דבריו נסתרים מסוגיא דסוף פ' גיה\"נ (חולין ק\"ג:) דקי\"ל כר' יוחנן שהנותן כזית אמ\"ה בפיו וחילקו בפנים חייב, ופירשו התוס' שם שהטעם הוא, שדרכו ליחלק בפיו בשעת לעיסה. ודבריו הם מתוך דברי הרב משאת משה ח\"ג (חיו\"ד סימן ג') שהובא בשו\"ת חקרי לב (חיו\"ד סי' מ\"ג) שהזכיר שם, שחקר במי שאוכל פרי מתולע ולועסו היטב קודם הבליעה, אם הולכים אחר שעה שמכניסו לפיו ולוקה, או דאזלינן בתר בליעה וכבר יצא מכלל בריה, ופשט מהתוס' הנ\"ל שכיון שדרך שנחלק בפיו חשוב בריה.","b":false},{"t":"והרב חק\"ל שם כתב מתחילה, דמשמע מהרמב\"ם בהמ\"א (פ\"ה ה\"ד) שאע\"פ שנחלק בפיו קודם שיבלענו חייב, והיינו שנחתך סמוך לבית הבליעה, אבל חילקו בשיניו ואח\"כ בלעו בזה אחר זה פטור גם לר' יוחנן ושזה דעת רש\"י. ואח\"כ העלה כדעת התוס' הנ\"ל, שאפי' נחתך קודם בין שיניו חייב.","b":false},{"t":"ושכן מפורש בירושלמי (נזיר פ\"ו ה\"א) (כ\"ה ע\"ב) דאיתפלגון ר' יוחנן ור\"ל גבי אמ\"ה שחלקו בפיו ואכלו, ר' יוחנן עבד פיו כלפנים, ור\"ל עבד פיו כלחוץ, וקשה מזה ע\"ד רש\"י דבשלמא בבבלי אפ\"ל שחלקו בפנים היינו בלעו לחצאין וסמוך לבית הבליעה יש כזית שלם, אבל בירושלמי דנקט חלקו \"בפיו\" אין משמעו בית הבליעה, ושכ\"מ במאירי (ק\"ג: ע\"ה אמ\"ה כבר) שכתב וז\"ל, הכניסו בפה כאחד וחילקו מבפנים ובלעו לחצאין חייב, ומשמע דעיקר כהתוס'. ודברי הרמב\"ם לא מוכיחים כ\"כ שחולק על התוס'. עכ\"ד החק\"ל.","b":false},{"t":"עו\"כ שראה בס' מגילת ספר (אות ב') שכתב שהגרש\"ז אורבאך זצ\"ל בתשובה (בספר בדיקת מזון עמוד 179) העלה דאזלינן בתר ההכנסה לפה, מדקי\"ל כרבי יוחנן דחילקו בפנים חייב. עכ\"ד.","b":false},{"t":"י\"א. ואולם לענ\"ד דברי החזו\"א ישרים ונכוחים הם, ובדאי לא נעלם מעיני קדשו סוגיא מפורשת. אלא ששני דינים שונים הם. והנה בגמ' (חולין ק\"ג ריש ע\"ב) בעא מיניה רשב\"ל מרבי יוחנן חלקו מבחוץ מהו, א\"ל פטור. מבפנים מאי, א\"ל חייב. [ופירש\"י ז\"ל חלקו מבחוץ, לכזית אבר מן החי חלק לשנים קודם שיתננו לתוך פיו, ואכל זה לבדו ואח\"כ השני. מהו, מי מצטרפי לחייוביה ככל שאר איסורים דקי\"ל דמצטרפי שיעורייהו לחצאין בתוך כדי אכילת פרס, כדאמרי' ביומא (פ' ע\"א), או דילמא כיון דחידוש הוא, דהא גידין ועצמות דעלמא לא מיחייב עלייהו והכא מיחייב, ואימא אין לך בו אלא חידושו, וכי אכיל ליה בבת אחת מיחייב, אבל לחצאין לא. מבפנים, לאחר שבא סמוך לבית הבליעה בלעו לחצאין. עכ\"ל.] עוד שם, כי אתא רבין אמר חלקו מבחוץ פטור, מבפנים ר\"י אמר חייב, ור\"ל אמר פטור. ר\"י אמר חייב הרי נהנה גרונו בכזית, ור\"ל אמר פטור אכילה במעיו בעינן וליכא. (ופרש\"י ז\"ל אכילה במעיו, כשהוא יורד לתוך מעיו צריך שיהיה בו שיעור אכילה.) אלא לר\"ש בן לקיש היכי משכחת לה דמחייב, א\"ר כהנא בגרומיתא זעירתא. (ופירש\"י ז\"ל היכי משכח\"ל, בכזית הא א\"א ללעוס אכילה לבולעה כולה יחד. בגרומיתא זעירתא, עצם קטן שעל כף הירך שיש בו משהו בשר, וגיד ועצם משלימו לכזית, ואין אדם לועסו אלא בולעו. עכ\"ל.","b":false},{"t":"ולפי פשט הסוגיא לא קשה מידי ע\"ד החזו\"א ע\"ה, דכאן מדובר בדין צירוף של כזית מתי נחשב כמו שאכלו בב\"א וחייב, ומתי נחשב לשתי אכילות של שני חצאי זית ופטור. ואין זה ענין לנידון דהחזו\"א שדיבר בדין בריה שאם ניטל ממנה אפילו כנף וכיוצ\"ב בטיל ממנה דין בריה, וכל שכן אם נחתכה, ואין בזה שאלה אם מצטרף או לא, רק אם עדיין בריה חשובה היא ולא בטלה, או איבדה חשיבותה ובטלה ברוב.","b":false},{"t":"והתוס' שם (ד\"ה חלקו מבחוץ) דקדקו דמשמע מרש\"י, שאם חלקו לשנים ונתן שני החצאים בפיו ובלען בב\"א חייב לכו\"ע. והקשו ע\"ז ממה ששאלו בגמ'. לריש לקיש היכי משכח\"ל דמחייב. וכי לא יכול לבלוע כזית בבת אחת, והא אמרי' ביומא (פ' ע\"א) דבית הבליעה מחזיק כביצת תרנגולת דגדולה יותר מכרגוגרת שהיא גדולה יותר מכזית כדמוכח בשבת (צ\"א ע\"א) ובכריתות (י\"ד ע\"א) אמרו שבית הבליעה אינו מחזיק יותר משני זיתים, (ואכן כביצה הוא ב' זיתים) ועוד דכמו שלר' יוחנן דאזיל בתר אכילת פיו, מיחייב כשחלקם בחוץ והכניסם לפיו בב\"א, ה\"נ לר\"ל דאזיל בתר אכילת מעיו, אפי' אכלן זה אחר זה יתחייב דיש כזית בב\"א במעיו, ונראה לפרש דחלקו מבחוץ פטור אפי' אכלו בב\"א דבעי' שיהיה מחובר בפיו, ויהיה עליו שם אבר, משום דהכא חדוש הוא כדפירש בקונט' דבעלמא לא מיחייב אגידים ועצמות ואין לך בו אלא חדושו, אבל חלקו בפנים חייב דהדרך הוא שנחלק בפה בשעת לעיסה. ור\"ל פוטר אפי' בחלקו בפנים, ולכך דוחק הש\"ס אליביה היכי משכח\"ל שיתחייב בדרך אכילה, ומשני בגרמיתא זעירתא דאין אדם לועסו אלא בולעו, ומיהו לר\"א ודאי חייב חלקו מבחוץ דאפי' אכל זה אחר זה חייב. עכ\"ל.","b":false},{"t":"נמצא דלפירש\"י ז\"ל החיסרון בחלקו מבחוץ, איננו בחלוקה שחילקו את האבר מן החי, אלא החיסרון הוא באכילה, שאכל זה לבדו ואח\"כ אבל את החלק השני, וכמבואר להדיא בתחילת לשונו של רש\"י ז\"ל. ופירש שם, דבכל האיסורים מצטרפים האכילות כל שהוא בכדי אכילת פרס, ואמ\"ה שאני דחידוש הוא שחייבה התורה גם על הגיד והעצם של אמ\"ה, (משא\"כ בכל התורה), וע\"כ אינו חייב אלא כשאכלו בב\"א.","b":false},{"t":"וזה שהביא לבעלי התוס' לדקדק מרש\"י ז\"ל, דאם חילקו לשניים בחוץ, ונתן שני החצאים בפיו ואכלם בב\"א דחייב לכ\"ע. והקשו מה שהקשו ודחו לפירש\"י ז\"ל, ופירשו הם, דאם חלק האמ\"ה בחוץ פטור עליו, אפילו אכל שני החצאים בבת אחת ממש, משום דחידוש הוא באמ\"ה שחייבה תורה על גידים ועצמות. אבל חלקן בפנים (תוך פיו) חייב, ופי' התוס', דדרך אכילה בכך. שתוך כדי אכילה נלעס ומתחלק לחלקים. וריש לקיש פוטר אפילו כשחילקו בפנים, וע\"כ שאלו היכי משכחת לר\"ל דחייב, ושני בגרומיתא שאין לועסים אותו ולא מתחלק לא בחוץ ולא בפנים.","b":false},{"t":"וזאת עלינו לדעת דהחידוש של אמ\"ה (שכתבו רש\"י והתוס' כאן) הוא שמתחייב על כזית בשר שנתלש מאבר מן החי כגון מהלשון או מהכליות וכדלהלן. או על אבר שהוא כלול מבשר וגיד ועצם, ויש בו כזית מבין כולם, אפילו שהבשר הוא מיעוט חייב, וזה חידושו של אמ\"ה.","b":false},{"t":"והדבר מבואר בגמרא שם (ק\"ב סע\"א), דאמרו: אמר רב אבר מן החי צריך כזית, מ\"ט אכילה כתיבה ביה. (ופירש\"י ז\"ל שם, דאין אכילה פחות מכזית), מתיב רב עמרם אכל אבר מן החי ממנה (מעוף טמא) אינו סופג את הארבעים, ואין שחיטה מטהרתה ואי ס\"ד בעינן כזית תיפוק ליה דאכל כזית (ולמה לא סופג הרי אכל כזית טמאה), כדאמר רב נחמן במשהו בשר ופירש\"י ז\"ל במשהו בשר גידין ועצמות, הכא נמי במשהו בשר גידין ועצמות.","b":false},{"t":"ופירש\"י ז\"ל במשהו בשר, גידין ועצמות משלימים לכזית, דמשום טומאה לא מיחייב דאין בגידים ועצמות טעם טמא, ומשום אבר מחייב, דלהכי פלגינהו קרא לאבר מן החי ובשר מן החי, דמחייב אאבר אע\"ג דאין שיעור בשר, ואבשר אע\"פ שאינו אבר. עכ\"ל.","b":false},{"t":"הנה מבואר ומפורש דבעינן כזית לאמ\"ה, משום דכתיב ביה אכילה, ועוד חידשו דאבר שמצורפים בו בשר גידין ועצמות, אפילו שאין כזית בבשר, מצטרפים שלשתם, ואם יש בהם בכולם כזית, לוקה. וזה בודאי חידוש בדין אמ\"ה, ושם מפורש דבשאר איסורים כגון בטמאים, אינו לוקה אא\"כ יש כזית בשר.","b":false},{"t":"וזה הוא החידוש שהזכירו רש\"י ותוס' שם, ושעל כן אם נתחלק האבר אינו לוקה עליו, דאין לך בו אלא חידושו, ונחלקו בזה ר\"י ור\"ל, לר\"י לא נפטר ממלקות אלא אם התחלק מבחוץ, ולר\"ל אפי' נתחלק תוך הפה פטור, ולריש לקיש אינו חייב אלא בגרומיתא זעירתא ופירש\"י ז\"ל שיש בו משהו בשר, וגיד ועצם משלימו לכזית ואין אדם לועסו אלא בולעו. עכ\"ל.","b":false},{"t":"י\"ב. והרמב\"ם ז\"ל בהלכות מאכלות אסורות (פ\"ה ה\"א) כתב, מפי השמועה למדו שזה שנאמר בתורה, לא תאכל הנפש עם הבשר, לאסור אבר שנחתך מן החי וכו', איסור אמ\"ה נוהג בבהמה חיה ועוף, בטהורים ולא בטמאים. ובהלכה ב', כתב, אחד אבר שיש בו בשר וגידים ועצמות כגון היד והרגל, ואחד אבר שאין בו עצם כגון הלשון וכו', אלא שהאבר שאין בו עצם בין שחתך כולו בין שחתך מקצתו (כמו חצי לשון או חצי לב וכדו'. הכותב), הרי זה אסור משום אמ\"ה. והאבר שיש בו עצם אינו חייב עליו משום אמ\"ה עד שיפרוש כברייתו, בשר וגידים ועצמות, אבל אם פירש מן החי, הבשר בלבד, חייב עליו משום טריפה כמו שביארנו, לא משום אמ\"ה.","b":false},{"t":"עו\"כ בהלכה ג': האוכל מאבר מן החי כזית לוקה, ואפילו אכל אבר שלם, אם יש בו כזית חייב, פחות מכזית פטור. חתך מן האבר כברייתו בשר גידים ועצמות, כזית, ואכלו לוקה, אע\"פ שאין בו בשר אלא כל שהוא. אבל אם הפריד האבר אחר שתלשו מן החי, והפריש הבשר מן הגידים ומן העצמות אינו לוקה עד שיאכל כזית מן הבשר לבדו, ואין העצמות והגידין מצטרפים בו לכזית ששנה ברייתו.","b":false},{"t":"ובהלכה ד' שם, כתב, חלקו לאבר זה ואכלו מעט מעט, אם יש במה שאכל, כזית בשר חייב, ואם לאו פטור. לקח כזית מן האבר כברייתו בשר גידים ועצמות, ואכלו אע\"פ שנחלק בפיו בפנים קודם שיבלענו חייב. עכ\"ל הרמב\"ם ז\"ל.","b":false},{"t":"והעולה הוא דבעינן כזית באמ\"ה כדי שיתחייב, אבל פחות מכזית, אפילו שהוא אבר שלם בבשר וגיד ועצם פטור. ועוד פסק כדרב נחמן הנ\"ל, דחתיכה שיש בה כזית אעפ\"י שהבשר שבה הוא מועט, ורק ע\"י הגידים והעצמות הוא דיש בו כזית חייב.","b":false},{"t":"וכ\"פ כר' יוחנן (בדף ק\"ג ע\"ב) הנז', דאם התחלק בחוץ פטור, דהיינו שנפרד הבשר מן העצם והגיד, בחוץ ואח\"כ אכלם פטור, עד שיאכל כזית בשר. כלומר דבזה שנפרד הבשר מהגידים והעצמות, שוב לא מצטרפים לכזית, ולא לוקה עד שיהיה כזית בבשר לבדו, דזה שהגידים והעצמות מצטרפים עם הבשר לכזית, הוא רק בכדרך ברייתן ולא אחר שנתחלקו. אבל אם נתן הכזית (מבשר גידים ועצמות) תוך פיו, אע\"פ שנחלק בפיו, קודם שבלעו חייב עליו משום אמ\"ה.","b":false},{"t":"נמצא דדין אמ\"ה בכזית ככל איסורי תורה, וכשיש כזית בשר האוכלו חייב בין שנתחלק לחתיכות בחוץ ובין נתחלק בפנים, (אדרבא יש בזה חומרא מיוחדת לדעת הרוגוצ'ובי בצפנת פענח ע\"ה דאפילו אכלו מעט מעט, ביותר מכדי אכילת פרס חייב, והוא חידוש גדול ולמד כן מלשון הרמב\"ם פ\"ה ה\"ד, שכתב, חלקו לאבר זה ואכלו מעט מעט, אם יש במה שאכל כזית בשר חייב. ויש מקום לדון אך צריך לעיין בדב\"ק בפנים). כל שאכל כזית חייב כמו כל האיסורים.","b":false},{"t":"וחידושו של אמ\"ה הוא בחתיכה שיש בה פחות מכזית בשר והגידין והעצמות שבה משלימים אותה לכזית, דחייב עליה, ובזה הוא שאמר נתחלק בחוץ פטור, שהחידוש הזה הוא בחתיכה טבעית שהבשר והגידים והעצמות הם גדלו יחד ומחוברים כאחד, בזה חידשה התורה שגם הגידים והעצמות מצטרפים לכזית, ובזה אמרו אין לך בו אלא חידושו, דהיינו כמו שאסרתו התורה, אבל אם הפריד בין הבשר לבין הגידים והעצמות, תו לא מצטרפי אהדדי, ואינו חייב עד שיהיה כזית בשר.","b":false},{"t":"ויש מקום לבאר ענין זה, דבאמ\"ה כתיב אכילה, ושע\"כ בעינן כזית כשאר האיסורים, אלא שיש בו חידוש שגו\"ע מצטרפים לכזית, והחידוש הזה מותנה בכך שאותם גידים ועצמות הם מחוברים כדרך ברייתן עם המעט בשר, אבל אחר שנפרדו זמ\"ז, חזר דינם כשאר איסורים ולא לוקה רק אם יש בו כזית בשר לבדו. דאחר שנפרדו בטל מהם החידוש הזה והגו\"ע לא מצטרפים עוד לשיעור כזית, ולרבי יוחנן דין זה הוא רק בנתחלק בחוץ, אבל אם נתן החתיכה כמות שהיא בפיו, ונתחלק ע\"י הלעיסה קודם הבליעה חייב, שזה דרך אכילה.","b":false},{"t":"י\"ג. ולענ\"ד אין לנו ללמוד מזה לדין בריה, שדין בריה שאינה בטלה היא גזרת חז\"ל, ואין זה תלוי באכילה, דהא לא בעי' כזית אלא אפילו קטנה ביותר אם אכלה כולה לוקה עליה, וגזרו חז\"ל שכל זמן שהיא שלמה לא מתבטלת, אבל נמוחה או נחתך ממנה כל שהוא, איבדה חשיבותה ומתבטלת. ורבינו בעל החזו\"א זיע\"א חדית לן דאפילו נחתכה בתוך הפה היא בטלה, ושפת אמת בפיהו ע\"ה, דדין בריה לא בעי' כזית, דלא כתיב בה אכילה, אלא יש דין שלא בטלה מפני חשיבותה, וכשבטלה חשיבותה אפי' תוך הפה, היא בטלה, ובשעת הבליעה כבר נתבטלה ואין איסור, ולא שייך בזה טענת התוס' דדרך אכילה הוא שמתחלק, דזה שייך באמ\"ה שבעינן כזית דאכילה כתיבה ביה, בזה אמרו שאפי' נפרד בפה לא נשתנה דינו, שעדיין יש ע\"ז שם אכילה, משום שכך דרך אכילה כמ\"ש התוספות הנ\"ל. אבל בריה לא תלויה בכזית, ולא איכפת לן אם דרכו או אין דרכו בכך שכל ענינה בחשיבותה, וחשיבותה היא בשלמותה, ומשנחתכה וכדו' בטלה חשיבותה ודינה ככל האיסורים, והואיל וטעמה פגום גם מאוס בטלה ברוב, ואין בזה חשש. עוד יש להוסיף שלא רק לענין ביטול אמרינן כן, אלא גם לדין מלקות על בריה יש לומר כן שאם נחתך תוך הפה לא לקי, ולא שייך לומר שאם נחתכה בפה לא בטל ממנה דין בריה כי דרך אכילה הוא, שבבריה לא כתיב אכילה, אלא כל חיובה הוא כשהיא שלמה דוקא, וגם גזירת חז\"ל דלא בטלה הוא רק בעודה שלמה לגמרי, וע\"כ גם בנחתכה בפה קודם שבלעה י\"ל דבטלה חשיבותה ובטלה ברוב ההיתר. וכן נמי אין בה מלקות בכה\"ג. ובענין מלקות עדיין צ\"ע.","b":false},{"t":"ויש להוסיף דכזית מאבר מן החי, ואפי' מיעוטו בשר והגו\"ע משלימים אותו לכזית, לוקה מן התורה, וכלשון הגמ' (ק\"ב סע\"א) וכן לשון הרמב\"ם בהמ\"א (פ\"ה ה\"ג) האוכל מאבר מן החי כזית לוקה. וכו', חתך מן האבר כברייתו בשר וגידים ועצמות כזית ואכלו לוקה, אע\"פ שאין בו בשר אלא כל שהוא. אבל אם הפריד וכו', עכ\"ל. הרי מבואר בלא שום ספק שמדובר באיסור תורה דלקי עליה. וי\"ל דרך באיסור תורה הוא דמצטרפי, ואין לנו ללמוד מזה לענין ביטול של בריה, שכולו דרבנן בלבד. דאפשר שבביטול שהוא דרבנן יודה ר' יוחנן דאפילו נתחלק בפה בטלה חשיבות הבריה ומתבטלת ברוב, ואפילו תימא שיש ספק בזה הוי ספק בדרבנן. ולפי זה י\"ל שלענין מלקות דבריה אפילו נחלק בפה לוקה, אבל לענין ביטול שהוא דרבנן, כל שנחתך קודם הבליעה בטל חשיבותו, ובטל ברוב.","b":false},{"t":"והנה דין בריה כולל גם אמ\"ה וכמ\"ש בש\"ע (סימן ק' ס\"א) וז\"ל, בריה דהיינו כגון נמלה או עוף טמא, וגיד הנשה, ואבר מן החי, וכו', אפילו באלף לא בטלה. וכו'. עכ\"ל. וכתב הש\"ך שם (סק\"א) דגיד הנשה ואמ\"ה הוה ביה חיותא , הרשב\"א והר\"ן פג\"ה.","b":false},{"t":"והפ\"ת (סק\"ב) כתב בשם פני אריה, דלא חשיב אמ\"ה בריה אלא כשיש בו כזית מהבשר וגידים ועצמות, אבל אמ\"ה שהוא פחות מכזית שנתערב, בטל כשאר יבש ביבש, ע\"ש. עו\"כ שהפמ\"ג דעתו אינו כן. והוסיף שבספר לבושי שרד (סימן כ\"ו) כתב שהיה עובדא בשוחט. אחד שחתך רגלי העופות בטבת ושבט, ולרוב המהירות ורבוי השחוטים, לקח גם רגל א' מאווז חי, שהיתה מעורבת בין השחוטות, והיו יותר מששים כשרות, והשוחט השליך רגל א' וחשב שהשאר בטל בשישים, שאין זו חה\"ל שצריך עוד תיקון השיער, ובאמת אמ\"ה לא בטל שדין בריה יש לו, והורה (הלבו\"ש) דאם ברור לו שבשום פעם שבישל לא היה ס' נגד הרגל, הכלים אסורים. אבל אם מסופק שאולי היה עכ\"פ בבשול אחד, ששים, אזי מותרים הכלים, ע\"ש באורך בביאור הטעם. ע\"כ. [וצ\"ע בפנים].","b":false},{"t":"ואנו רואים שהגם שיש דין בריה באמ\"ה ולא בטיל, עכ\"פ בעינן שיהיה בו כזית, והטעם כדאמר רב שם, דאכילה כתיב ביה. והדרינן למה שכתבתי דרק בזה שייך לומר בנחלק בפה שהוא דרך אכילה, אבל נמלה וכדו', אין בה דין אכילה, רק התורה חייבה מלקות למי שאוכלה שלֵמה אפילו שהיא בגודל של חרדל. וע\"כ י\"ל דכל שנחלק בטלה חשיבותו, ומתבטל, אפי' שנחלק תוך הפה. דלא שייך לומר דכן דרך האכילה, מאחר ולא כתוב בה אכילה.","b":false},{"t":"והנה במטה יהונתן שם, כתב, יש לדקדק דהא לא מיקרי בריה אלא היכא דליכא שיעור באכילתו, כגון נמלה וכיוצ\"ב דלוקה עליה בין גדולה ובין קטנה, משא\"כ שאר איסורים שיש שיעור באכילתן לא מיקרי בריה, וכיון דקי\"ל כרב דאמ\"ה צריך כזית, וכמ\"ש הרמב\"ם בהמ\"א פ\"ה, א\"כ אמ\"ה אמאי איקרי בריה, וכתב דצ\"ל כיון שאין שיעור לבשר אע\"ג דצריך שיעור לאבר מ\"מ מיקרי בריה, וליכא שיעור באכילתו קרינן ביה, אמנם לפי מ\"ש הרמב\"ם (בפ\"ד ה\"ג מהמ\"א) האוכל עוף טהור חי כל שהוא לוקה משום אוכל נבלה, ואם אכלו אחר שמת עד שיהיה בו כזית, אע\"פ שאין בבשרו כזית, הואיל וכולן כזית חייב עליו, וא\"כ מוכח מהרמב\"ם דאף שבבשר א\"צ כזית, מ\"מ כיון שבכולו בעי כזית לא מיקרי בריה, דהרי נבלה לא הוי בריה ואפי' היא שלמה צריך שיעור, וא\"כ אמ\"ה לא מיקרי בריה, כיון שצריך שיעור לאכילתו. ובהגה ע\"ד מט\"י שם כתבו, שכאן לא תירץ, אך בכו\"פ תירץ (בסק\"ג) דבאמת לדעת הרמב\"ם ז\"ל גם נבלה שלמה הוי בריה כיון דסגי בכזית בין הכל, אך המחבר פסק דלא כוותיה, משום דדברי הרמב\"ם צ\"ע, שהוא נגד סוגיא דגמ' לפי פירש\"י והתוס' ע\"כ. והג\"ר שלמה כהן מו\"צ ווילנא, תמה עליו דהא י\"ל דהרמב\"ם ז\"ל דבעי' שאם יחלק שמו עליו וכמ\"ש הטור והב\"י בשם הרא\"ש ועוד, ונבלת עוף טהור אם יחלק עדיין שמו עליו, ולכן הוי בריה, ע\"כ.","b":false},{"t":"והנה דין אוכל עוף טהור הוא בחולין (ק\"ב ע\"א) ורש\"י שם פירש דאכלו חי חייב משום אמ\"ה, וע\"ש במ\"מ.","b":false},{"t":"ובש\"ע יו\"ד (סימן ס\"ב – ס\"א) בדיני אבר מן החי, כתב שאמ\"ה אסור בבהמה בחיה ובעוף, וברמב\"ם כתוב, שנוהג בטהורים ולא בטמאים, והש\"ך (סק\"ג) עמד על זה שמרן ז\"ל השמיט את זה, דאזיל לטעמיה שהקשה בב\"י על הטור שכתב בטהורים ולא בטמאים, למה כתב דין זה דאין נ\"מ לדידן דסו\"ס אסירי. אבל הב\"ח כתב דנ\"מ היכא דאסור משום אבמ\"ה הוי בריה ולא בטיל כדלקמן (סי' ק') ודבריו נכונים בזה.","b":false},{"t":"[וחידושי רעק\"א כתב על זה, ועיין בת' ב\"ה (סי' קל\"ז) ועיין בתפל\"מ לקמן (רס\"י ק'). עכ\"ל.] וצריך לי עיון בספרים הנ\"ל ולע\"ע אינם תח\"י.","b":false},{"t":"והנה אעפ\"י שנוהג דין בריה גם באמ\"ה וכנ\"ל, מ\"מ כשנחלק מבחוץ דפטור אינו מדין בריה שנחתכה, אלא זה דין מיוחד באמ\"ה, שאם אין כזית בשר והגו\"ע משלימים לכזית, אין בזה חיוב מלקות אלא כשהבשר מחובר עם הגו\"ע כדרך ברייתן. אבל אם נתפרקו אין לזה דין אבר, ואין בבשר כזית, וא\"כ אין כאן לא אבר מן החי, ולא בשר מן החי. תדע שאם יש כזית מן הבשר של החי, אפילו שנחתך לחתיכות דקות מבחוץ ואח\"כ אכלו לוקה משום בשר מן החי, והיינו בבשר של אבר שאין בו עצמות כגון לב וכבד וכיו\"ב. (אבל אם הפריש הבשר מאבר שיש בו גו\"ע אם יש בבשר כזית לוקה משום טרפה ולא משום אמ\"ה ע\"ש ברמב\"ם).","b":false},{"t":"ועוד דדין זה הוא בדאורייתא דאין לוקה על אמ\"ה אא\"כ יש בו כזית, וחידשה תורה דחייבים על אבר שיש בו כזית מבשר וגו\"ע, אבל אם נפרדו זה מזה לא לוקה, וכתב הרמב\"ם ז\"ל (פ\"ה מהמ\"א סוף ה\"ג) וז\"ל אבל אם הפריד האבר אחר שתלשו מן החי, והפריש הבשר מן הגידים ומן העצמות, אינו לוקה עד שיאכל כזית מן הבשר לבדו, ואין העצמות והגידים מצטרפים בו לכזית, מאחר ששנה ברייתו. עכ\"ל. ובזה הוא דאמרו שאם נחלק תוך פיו קודם שיבלענו חייב, שזה דרך ברייתו והפירוק בא דרך אכילתו.","b":false},{"t":"וכבר כתבתי לעיל, דרק באמ\"ה דכתיב ביה אכילה, והצריכו בו כזית, שהוא שיעור אכילה, בזה אמרי' שכל שהכניס האבר שיש בו כזית מבין הבשר והגו\"ע, חייב שיש כזית דרך ברייתו, בזה הוא דאמרו לא חשיב שנשתנה מברייתו ע\"י הלעיסה, שהתורה אסרתו באכילה וזה הדרך של האכילה.","b":false},{"t":"אבל נמלה וזבוב וכל כיוצ\"ב, שלא נאמר בהם אכילה, ואין בהם דין כזית, רק התורה אסרתם כמו שהם גם כשהם קטנים ביותר, וחז\"ל החשיבום וקבעו שאינם בטלים כל זמן שהם שלמים, וע\"כ אפי' להתוס' דבפה זה דרך אכילה, י\"ל דהם בטלים באוכלים אחרים הנמצאים עמהם.","b":false},{"t":"י\"ד. וכעת ראיתי בשו\"ת חק\"ל (חיו\"ד א' סימן מ\"ג) שהביא דברי הרב משאת משה שעלה נסתפק בח\"ג חיו\"ד (סי' ג') באכל פרי שיש בו תולעת שלעסו בפה ואכלו, אי לקי עליו כדין בריה, כיון שבא שלם לתוך פיו, או דילמא עיקר המלקות על הבליעה, ובאותה שעה כבר נתרסקה הבריה בלעיסה. ומכלל הראיות הביא מהגמ' חולין (ק\"ג ע\"ב) חלקו לו בפנים ר\"י אומר חייב הרי נהנה גרונו בכזית. ור\"ל אמר פטור אכילה במעיו בעינן וליכא. וכ\"כ הרמב\"ם ז\"ל בהמ\"א (פ\"ה ה\"ד). אלמא ש\"מ דלעיסה לא חשיב אכילה, דאל\"כ מאי קא מיבעיא הא כיון דלעסו אע\"ג דבלעו בשתים עלה לו דהרי נהנה פיו בכזית. ולמה אמר ר\"י דחייב אהנאת גרונו, תיפו\"ל דפיו נהנה אלא ע\"כ דליתא, ושוב דחה הרב ראיה זו, לדעת התוס' דבחלקו מבפנים, לאו בחלקו לשנים שלא יבלענו כאחת, אלא בחלק הבשר מעל העצם שיבטל ממנה שם בריה, וקי\"ל דחייב, אלמא חלקו מבפנים בדרך לעיסה לא יאכילנו מכף האיסור, (אולי צ\"ל, לא יצילנו) ה\"נ לדאתאן עלה וכו'. את\"ד.","b":false},{"t":"ומיהו לענ\"ד נ\"ל גם להתוס' כל החלוקה היא שמפריד הבשר מגו\"ע, ותו לא הוי כברייתו, ואין בו דין אמ\"ה אלא בכזית בשר לבד, וקמ\"ל דבזה שהכניסו תוך פיו כברייתו, חייב עליו וכבר הצטרפו הגו\"ע אל הבשר ויש בהם ביחד כזית, וחייבים. ולע\"ד זה דין מיוחד בדין אבר מן החי, שבזה מצטרפי' הגו\"ע לבשר לשיעור כזית. אבל כשיש כזית בשר מאבר שאין בו עצם כמו מהלשון, אפי' חתכו לחתיכות קטנות ואכלו מעט מעט מצטרף וחייב, ואין לנו מזה לימוד לדין בריה וכמו שביארתי לעיל, והרי גם כזית בשר מאמ\"ה יש לה דין בריה, וגם אם חתכה בחוץ נשאר בה דין בריה, וכל הדיון הוא לענין מלקות, ואינו מלמד על דין בריה של נמלה וכיו\"ב.","b":false},{"t":"והרב חק\"ל כתב שהמשאת משה תולה דין בריה במחלוקת רש\"י ותוס', דלרש\"י פטור ולתוס' חייב. ומפרש שהמשאת משה למד ממ\"ש רש\"י וז\"ל לאחר שבא סמוך לבית בליעתו בלעו לחצאין, שמזה נראה שאם חלקו קודם שבא סמוך לבית בליעתו גם לר\"י פטור, שר\"י אמר שנהנה גרונו, ש\"מ שצריך שכל הכזית יהיה סמוך לבית הבליעה, ואז הוא חייב, ומינה לדין בריה, כל שנתרסקה קודם שהגיעה לחיך שהוא סמוך לבית הבליעה פטור.","b":false},{"t":"משא\"כ להתוס' בחלקו בפנים היינו בפיו, דלר\"י חייב כיון שדרך הוא שנחלק בפיו בעת הלעיסה, ומינה שבריה שנתרסקה בפיו חייב.","b":false},{"t":"ומדברי הרב (משאת משה) יש לדייק דהרמב\"ם שם נוטה לפירש\"י, וע\"כ דקדק הרמב\"ם וכתב, אעפ\"י שנחלק בפיו בפנים קודם שיבלענו חייב, נראה שאינו מחייב אלא בהיותו שלם סמוך לבית הבליעה, ומשמע דאם נחלק בשינים קודם שהגיע לחיך פטור, והרי תולע הפרי מתרסק מיד בהניח הפרי בפה.","b":false},{"t":"עוד כתב החק\"ל דעיקר הראיה לחייב ממ\"ש בירושלמי (נזיר פ\"ג מינין ה\"א) חלקו לאמ\"ה בפיו ר\"י אומר חייב דעביד פיו כלפנים, ור\"ל פטור דעביד פיו כלחוץ, ואמרי עלה, נמלה שחלקה בפיו ואכלה, בפלוג' דר\"י ור\"ל. וקשה מזה על פירש\"י ז\"ל, דבשלמא בתלמוד בבלי פירש\"י שחילקו בפנים היינו סמוך לבית הבליעה, דבזה הוא דמחייב ר\"י דבולע כזית שלם, ודייקי דר\"י אמר הרי נהנה גרונו, אבל בירושלמי אין במשמע פיו כלל (סמוך) לבית הבליעה. עו\"כ בזוה\"ל: ועוד מדתלו בנמלה שחלקה בפיו ואכלה בפלוג' דר\"י ור\"ל, והרי בדין בריה גם רש\"י מודה דכשחלקה לשנים קודם שהגיע סמוך לבית הבליעה אפי' ששני החצאין סמוך לבית הבליעה פטור, דגבי אבר ס\"ל לרש\"י הגם שחלקם בחוץ, אם אכלם בב\"א חייב, וזה לא יתכן בדין בריה. וא\"כ איך אמרו בנמלה שנחלקה בפיו דלר\"י חייב, א\"ו עיקר הפי' כדברי התוס'. ודברי הרמב\"ם לא מוכרח כולי האי דפליג על התוס'. וצ\"ע גם להתוס' איך לא דחו פירושו (דרש\"י) מהירושלמי הזה, וי\"ל דס\"ל דכיון דשינה הש\"ס בבלי נקוט חלקו מבפנים, וגם שאמרו (בבבלי) הרי נהנה גרונו. ובירושל' נקטי חלקו בפיו, ש\"מ דש\"ס בבלי ס\"ל דלא נחלקו כי אם לבלעו לחצאין, ואה\"נ דלש\"ס בבלי, נמלה שחלקה בפיו גם לר\"י פטור. ואינו מספיק לדחות הירושלמי כל שאפשר להשוותם דלא פליגי. כי ע\"כ נ\"ל עיקר מהך ירושלמי כדברי התוס', ומינה נתבאר דעיקר ספק הרב (משאת משה) היינו מאי דפליגי ר\"י ור\"ל בנמלה שחלקה בפיו לר\"י חייב וידוע דקי\"ל כר\"י. עכ\"ל.","b":false},{"t":"והנה ממה שאמרו בירושלמי הנז' דר\"י ור\"ל פליגי גם בנמלה, משמע דלא כמו שכתבתי למעלה לחלק בין אמ\"ה ובין בריה כנמלה וכיו\"ב, וזה בודאי דלא כמו שכתב החזו\"א ע\"ה, ואולי י\"ל דגם בירושלמי ל\"פ אלא לענין מלקות, אבל הדין דבריה, לא בטלה שהוא דרבנן, וגם שאינו תלוי רק בענין מלקות אלא עיקרו משום חשיבות, אפשר שגם להירושלמי כו\"ע יודו דבריה שנחתכה בפה בטלה ככל האיסורים, משום דאיבדה חשיבותה.","b":false},{"t":"ועוד דלפי שיטת רש\"י, בע\"כ צ\"ל דהבבלי חולק בזה על הירושלמי, וכמו שדקדק רבינו בעל החק\"ל ע\"ה. וכן צ\"ל גם לשיטת הרמב\"ם ז\"ל.","b":false},{"t":"ועיינתי בירושלמי שם וראיתי בדברי שירי קרבן (שבסוף המסכת) ד\"ה מה פליגין כשחלקו בפיו, והביא דברי התוס' (דחולין ק\"ג ע\"ב) שהשיגו על פירש\"י ז\"ל, הנ\"ל: וכתב, ואני תמה על פירש\"י הרי בסוגיין (ירושלמי) מפורש כפי' התוס', דלפירש\"י קשה למה קאמר חלקו בפיו פליגי, הו\"ל נתן שניהם בפיו בב\"א פליגי, ועוד מדפריך א\"כ אפילו חלקו בחוץ, ש\"מ אם הניח שני החלקים בפיו בב\"א, אפי' לר' יוחנן פטור וכמ\"ש בקונטרס, ומ\"ש התוס' דלכך פטור דבעינן שיהא עליו שם אבר וכו', א\"נ כן מסוגיין, אלא הטעם דלאו דרך אכילה הוא, תדע שאין הטעם משום חידוש כדפירש\"י, דהא מסיק (בירושלמי) דגם בנמלה ובערלה ומצה פליגי, גם עיקר פירושו תמיה שכתב או דילמא כיון דחידוש הוא וכו' (ע\"ש שרוצה לומר שכיון שחידוש הוא אדרבא יש להחמיר בו בכל החומרות שיש באיסורים אחרים וי\"ל באמ\"ה שמצטרפין ככל איסורי תורה. וכו'.) והמעיין יראה שכונתו שם לומר דמסוגיית הירושלמי לא משמע לא כרש\"י ולא כתוס', ובע\"כ שיסברו שהבבלי פליג בזה אירושלמי, ולפי\"ז אין לנו להקשות מהירושלמי על ההלכה העולה מהתוס' ומרש\"י ומרמב\"ם ז\"ל, דהם אזלי כשיטת הבבלי.","b":false},{"t":"ט\"ו. ושו\"ר באור שמח על הרמב\"ם בהמ\"א פ\"ה ה\"ג, ד\"ה אבל אם הפריש האבר וכו', והפריד הבשר וכו'. שכתב דהרמב\"ם ז\"ל למד זה מהירושלמי נזיר (פ\"ו ה\"א) דאמר הואיל ונבטל מטומאתו נבטל מאיסורו, ובכה\"ג שנפרד הבשר אינו מטמא הבשר, אולם מלשון רבינו מוכח דאם יש בו כזית בשר חייב משום אבר מן החי, ולא משום בשר החי, (ר\"ל שלא משום טרפה אלא איסור אמ\"ה) שלשונו, אינו לוקה עד שיאכל כזית מהבשר לבדו, מוכח דאע\"ג דלא חשיב אמ\"ה לענין טומאה, בכל זאת כזית מהבשר מחייבו משום אבר, דוגמא שפסק רבינו דהלשון והטחול והביצים וכיו\"ב בכולם חייב משום אמ\"ה (הכונה על כזית מהם) אע\"ג דפסק בהל' שאר אבות הטומאות, דלא מטמאין, והכא נמי כיון שפירש כברייתו, אע\"ג שאינו מטמא עכשיו, בכל זה לקי משום אמ\"ה, רק דאין גו\"ע מצטרפין, (אחרי שהופרשו בחוץ) ודו'ק.","b":false},{"t":"עו\"כ, ובאמת נראה דכונת הירושלמי בשאין כזית באבר מן החי, דכולו פחות מכזית, ובכל זאת חייב משום בריה, ופליג על הך דרב (חולין ק\"ב סע\"א) דאכילה כתיבא בה, דהכי נמי מחייב בענבה לנזיר, אע\"ג דלית בו כזית משום דבריה הוי, וצ\"ע ליישב שם הסוגיא, ובחידושי הארכתי ועדיין הוא ענין מעומעם. אך פשט הירושלמי משמע דבאין בו כזית מיירי, ולכך חלקו פטור דשוב אינו בריה ולית ביה שיעורא, ולמד רבינו לשיטת הש\"ס דילן דאין מצטרפין גו\"ע ודוק'. ומה שכתב רבינו בהלכה ד' חלקו לאבר זה וכו' ולקח כזית וכו', הוא מש\"ס דילן, ודלא כהלח\"מ. יע\"ש. עכ\"ל האור שמח.","b":false},{"t":"וגם אני הקטן כיונתי לדברות קדשו, שכתבתי שאם אכל כזית מהבשר אפי' נפרד מבחוץ לוקה, והוא כמפורש להדיא בדברי הרמב\"ם, וכמ\"ש האו\"ש בפתיחת דבריו, וגם שאין הבדל בין זה ובין כזית בשר מהלב, או מהלשון וכיוצ\"ב. והוא ז\"ל חידש עוד, דבירושלמי משמע דאפילו שאין כזית באבר, כל שהוא כברייתו בשר וגידין ועצמות, חייב עליו אפי' אין בו כזית. וזה בודאי היפך מ\"ש הרמב\"ם ז\"ל בריש הלכה ג', וז\"ל, אכל אבר שלם אם יש בו כזית חייב פחות מכזית פטור. והיא מימרא דרב בחולין (ק\"ב סוף ע\"א) ובזה פירש האור שח ע\"ה דין הענבה שחייב בנזיר להירושלמי שבריה היא, וחייב עליה גם כשאין בה כזית, וגם האבר מן החי בריה הוי, וחייב גם בפחות מכזית. וחזר וכתב: אך פשט הירושלמי משמע דבאין בו כזית מיירי.","b":false},{"t":"ולפי\"ז יובן מה שהשוו בירושלמי דין נמלה וענבה ומצה, לאמ\"ה, ושבכולם חולקים ר\"י ורשב\"ל.","b":false},{"t":"וממילא עולה ברור לדברי האו\"ש, דלסוגיית הבבלי, דאזלא כרב דאם אין בו כזית פטור, דאכילה כתיבא ביה, וחידושו הוא, שגם גו\"ע מצטרפים עם הבשר לכזית, ומ\"מ אם אין כזית בין כולם פטור דאכילה כתיב ביה וליכא.","b":false},{"t":"ממילא אין ללמוד דין בריה מדין אמ\"ה, דלא קרב זה אל זה, דבריה לא כתיב בה אכילה, וא\"צ כזית לכו\"ע, וכל חומרתה בשלמותה, שרק בזה הוא דחייבים עליה, אבל אם יחסר ממנה כל שהוא, בטל ממנה חיובה, ובזה תלו חז\"ל את חשיבותה לומר דחשובה היא ואינה מתבטלת. וכיון דאין כתוב בה אכילה, אין שייך לומר בה שזה דרך אכילה, וכל שנחלקה או נחסר ממנה יד או רגל וכיוצ\"ב אפילו בפה, בטל ממנה החיוב, וק\"ו שבטל חשיבותה ומתבטלת ברוב אם היה עמה אוכל אחר.","b":false},{"t":"וכבר כתבתי לעיל לחלק בין דין בריה לענין מלקות שהוא מדאורייתא ובין דין ביטול שהוא מדרבנן, וי\"ל דגם ר' יוחנן מודה בזה שכל שנחתכה אפילו בפה, בטלה ברוב, וגם אם יש ספק בזה הוי ספיקא בדרבנן ולקולא.","b":false},{"t":"ט\"ז. ואתמול ביו\"ט דשבועות חשבתי עוד לחדש בס\"ד, דיש מקום לומר דהא דמחייב ר\"י גם בנחתך בפה, וכתבו התוס' משום דהוי דרך אכילה, הנה וגם אם נאמר שהבבלי מסכים לירושלמי דה\"ה בנמלה שנחתכה בפת דחייב לר' יוחנן. גם אם נקבל את זה, יש לומר דזה רק לענין מלקות שחייבים על בריה שלמה, ולא לענין ביטול, (ולא רק מפני שזה דאורייתא וזה דרבנן כהנ\"ל). אלא י\"ל עוד טעם אחר בדבר, דהתורה אסרה הנמלה והזבוב כמו שהיא ובגודל שלה, וחייבה מלקות על אכילתה, ובזה י\"ל דאפי' נחתכה בלעיסה קודם הבליעה לוקה עליה, דזהו האיסור שאסרה תורה. אבל בגזרת חז\"ל שלא תתבטל אין זה ענין באכילה, שאם אכלה כבר אכלה, אלא מיירי שנתערבה כגון שיש לפנינו סיר של מרק וידעינן שנתערבה בו נמלה, בזה אסרו את הכל משום שאינה בטלה, וי\"ל דרק בכה\"ג שהיא עומדת שם שלמה הוא דגזרו כן. אבל כשאכלה עם שאר ירקות, הרי בודאי אין מלקות, אפי' לא נחתכה, דמה\"ת בטלה ברוב, ואולם חז\"ל אמרו דלא בטלה אך לא שייך מלקות ופשוט, וכיון שנחתכה ובטלה חשיבותה, י\"ל דבזה לא העמידו דבריהם, ובטלה היא גם מדרבנן, וכמ\"ש החזו\"א ע\"ה.","b":false},{"t":"עוד ראיתי בחקרי לב שם, שהקשה על הרב משאת משה שהסתפק אם לוקה על התולע שבפרי משום בריה וכנ\"ל, והרי התולעת שנוצרה בפרי בתלוש הותרה כל עוד לא פירשה, כמבואר בטור יו\"ד (סי' פ\"ד), והרי אכל פרי עם התולע שבתוכו, ומנא לן דפריש כי היכי דלילקי, וגם אם נולדה בעוד הפרי מחובר, דבזה ס\"ל לשמואל בחולין (ס\"ז ע\"א) קישות שהתליעה באיביה אסור, הרי התוס' שם (ס\"ז ע\"ב ד\"ב דיקא) כתבו בשם ר\"ת ורבינו נתנאל וריב\"א דאין הלכה כשמואל, ואיך ילקה על הספק במקום שנחלקו גדולי עולם, והביא מהרב משאת משה גופיה (שם סימן ה' דף ז') שעשה ס\"ס ביפראקיש (עלי הגפן) כיון שנחלקו בו הראשונים, אי קי\"ל כשמואל, ובדוחק י\"ל שספקו של הרב הוא אליבא דהפוסקים כשמואל, אך סתם דבריו וקיצר במקום שהיה לו לפרש.","b":false},{"t":"עו\"כ, עוד יש לתמוה עליו איך יתכן דלילקי והרי אמרו בזבחים (ע\"ח ע\"א) דאיסורים מבטלים זא\"ז, וע\"ש בתוס' (ד\"ה הפיגול) כשרוב התר דמבטל לאיסור, וכבר תמהו עליו בזה בספר פרי האדמה בח\"א (פ\"ג מהל' מאכלות אסורות) ע\"ש. עכ\"ל.","b":false},{"t":"וכונתו בקושיא השנית, דאיך ילקה על בריה אפי' שהיא שלמה הרי מה\"ת היא בטלה ברוב, ורק רבנן הם שאמרו דלא בטלה, ואיך ילקה.","b":false},{"t":"ונמצא דמלבד מ\"ש לעיל דהבבלי פליג על הירושלמי לשיטת רש\"י ז\"ל, והרמב\"ם ז\"ל, (וכתבתי שהאור שמח שם העלה שגם להתוס' מוכרחים לומר כן). הנה עתה הקשה על דברי הרב משאת משה כמה קושיות, ושכבר השיגו הרב פרי האדמה, וא\"כ דברותיו לאסור ולחייב על התולעת אינם אמורים אליבא דהלכתא. וק\"ו לענין ביטול שהוא רק מדרבנן דאין לנו להחמיר בזה, ובפרט לאור מה שכתבתי ובארתי לעיל, וע\"כ נלע\"ד שדברי החזו\"א עיקר.","b":false},{"t":"י\"ז. והלם ראיתי להגאון שדי חמד מערכת הב'ית (סימן כ') פאת השדה, שדן בדין בריה דלא בטלה אם הוא מן התורה או מדרבנן, ושם (בעמוד 388) כתב: זאת אגיד שראיתי עתה בספר טהרת המים לרב גדול משאלוניקי שכתב במערכה זו (אות ב\"ן) בשם הרב עוגת אליהו (סימן כ\"ח) דבריה לא בטיל הוא מדאורייתא, ושכתב כן משמא דגמ' ערוכה, ואין מי שחולק בזה, ותמה עליו שסותר דברי עצמו, שבספרו קול אליהו ח\"ב חיו\"ד (סס\"י ב') כתב בפשיטות היפך מזה וציין לעיין בספרו מעט מים (סי' פ\"ט) וע\"ש מ\"ש בזה.","b":false},{"t":"ואחרי זה הביא דברי הרשב\"א בתורת הבית הארוך (בית רביעי שער א' דס\"ז ע\"ב) דבריה דלא בטלה דרבנן הוא ולקולא. וכתב שגם הפר\"ח כתב כן בשם הר\"ן שאינה בטלה הוא מדרבנן, וכ\"כ הרא\"ש דמדאורייתא לא שנא חשוב לא שנא לא חשוב חד בתרי בטל, וכיון שהטעם שבריה לא בטלה הוא משום חשיבות, ושכ\"כ הרשב\"א בתשובה (סי' רע\"א) שכל אלו שאינן בטלים בחד בתרי במינו, דרבנן הוא, וכ\"ש במ\"ש במאה ובמאתים ודבר שבמנין וחה\"ל ובריה כולן דרבנן, שמהתורה חד בתרי בטל וכן הבין בדעת הרמב\"ם ז\"ל (פט\"ז מהמ\"א), ובתוס' בכמה מקומות, ותמה על מ\"ש מהרי\"ל (בתשו' סי' ע\"ו) דמהתוס' בב\"מ (דף ו' ד\"ה קפץ) משמע שהוא מהתורה.","b":false},{"t":"עו\"כ שהגאון ערך השלחן (יו\"ד רס\"י ק', ד\"ה ודע) כתב דבריה ודבר חשוב דלא בטיל אינו אלא מדרבנן, כמו שהוכיח הרשב\"א (סי' תר\"ס) דמדאורייתא כל האיסורים בטלים ברוב, וכן בפ' גיד הנשה תנן גיד הנשה שנתערב בין הגידין בזמן וכו', ואם אינו מכירו כולן אסורים. ובגמ' הקשו וליבטיל ברובא, ופרקינן בריה שאני. אלמא מאן דקא מותיב ליבטיל ברובא, לית ליה בריה לא בטלה, ואם איתא לא הו\"ל למימר בריה, שאני אלא גיד בריה הוא וכו' עכ\"ל. [כנר' דמזה מוכיח דאינו דאורייתא דלא\"כ איך סבר המקשה שהיא בטלה]. וכתב השד\"ח הא למדת דרבים וכן שלמים מהראשונים נקטי דבריה שלא בטלה דרבנן הוא. וע\"ש.","b":false},{"t":"עו\"כ שבבואו לעה\"ק חברון ת\"ו השיג הספר עוגת אליהו ושם השיג ע\"ד אביו הרב משאת משה (בחיו\"ד סימן ג') והשגתו היא על פי הנחה דהא דבריה לא בטלה אינו אלא דרבנן ומדאורייתא בטלה, וכתב, ולדידי לאו תיובתא היא ע\"ד הרב אבא מארי, ומעכ\"ת ראה מ\"ש הפר\"ח (סי' ק') דהא דבריה לא בטלה הוי מדרבנן. והרואה יראה דזה תלוי בפלוגתא דרבוותא, וע\"ש בזה.","b":false},{"t":"משמעות דבריו שמׂר אביו הגאון משאת משה ס\"ל שהדין שבריה לא בטלה הוא מן התורה, ומישב מה שתמהו עליו בזה, ע\"י שהביא דעות דרבוותא דס\"ל שהוא מה\"ת. (וצ\"ע בתחילת דברי השד\"ח סוף עמוד 387). וכן מוכח מהשגת השד\"ח על דבריו. שכתב וז\"ל, ולי ההדיוט תמיה לי אם עיין הרב (עוגת אליהו)בגוף דברי הראשונים שציין הפר\"ח, שכתבו מפורש דבריה אינה בטלה מדרבנן הוא, איך תנוח דעת העליון להעלות במחשבה להחליט שהוא מדאורייתא, עפ\"י ההוכחה לפי דעתו מסוגיא דגמרא, וגם אם היה מפורש בש\"ס, לא היה בכוחנו לדחות דברי הראשונים, רק היינו תמהים על דב\"ק, וכ\"ש דאחר המחילה מכ\"ק אין ראיתו מוכרחת כלל, לא מהש\"ס ולא מדברי הרא\"ש, וכו', ואין לנו אלא דברי הראשונים ז\"ל שכולם פה אחד אמרו שדין בריה דאינה בטלה אינו אלא דרבנן. ע\"כ.","b":false},{"t":"מדבריו מוכח שהרב משאת משה ז\"ל ס\"ל שהדין דבריה לא בטלה הוא דין תורה. ולפי\"ז יש מקום לומר דמה שהשוה משאת משה הנ\"ל דין בריה לדין אמ\"ה, הוא משום שהוא סבור שגם זה הוא מן התורה ודוק.","b":false},{"t":"עו\"כ השד\"ח שם, וראיתי בטהרת המים (מערכה זו אות ס\"ו) שכתב שכל אלו שאינן בטלים (בריה וכו') אינו אלא מדרבנן, ושכן הסכימו הפוסקים, ואח\"כ כתב בשם ר' ישעיה ברלין בס' מיני תרגימא (בליקוטים שבסופו), שהם למ\"ד דמדאורייתא מבטלין איסור לכתחילה, מדאמרי' בקידושין (דף נ\"ו) לא אמרה תורה שלח לתקלה, ומאי תקלה איכא הרי מותר לבטל איסור לכתחילה, הא הצפור המשתלח מתבטל ברוב הציפורים. ומזה הכריח דמ\"ד בריה בטלה מה\"ת בע\"כ סבור דאין מבטלי' איסור לכתחילה ומאן דס\"ל דיש ביטול מהתורה, בע\"כ ס\"ל דבריה לא בטלה מהתורה. והשד\"ח כתב דלפי\"ז יקשה על הרשב\"א ז\"ל שבמשמרת הבית כתב דמבטלים איסור לכתחילה, והוא עצמו ס\"ל דבריה בטלה מהתורה, וע\"כ דחה מסקנת הרב מיני תרגימא, והקושיא מזה שלא אמרה תורה שלח לתקלה, כבר עמדו ע\"ז גדולי האחרונים ואמדו בזה כמה סברות, וע\"ש בשם הפלתי, ומה שפקפק בדבריו.","b":false},{"t":"עו\"כ השד\"ח שם (עמוד 389, ד\"ה ועל מה) שחכם א' כתב לו על מה שכתב בענין בריה אי בטלה בתתק\"ס, שכן מבואר בב\"י (סי' ק') בשם הרשב\"א דבריה בטלה בתתק\"ס, ותמה איך פסק מרן בש\"ע סעיף ג', בקדרה של מרק שנפל בה בריה אסורה, ובאה\"ג ציין שהוא מהרשב\"א בתשובה, והרי בודאי יש תתק\"ס, ולמה אסורה, ואפשר י\"ל דכיון דהוי תבשיל עבה שא\"א לסננו הו\"ל כהוכר האיסור, וע\"ש שציין להגר\"א (סי' ק\"ד סק\"ו). ע\"כ. וצ\"ע בזה. ויש מזה חיזוק למה שכתב הערוך השלחן בשם הכו\"פ, דבכל תולעת וכיוצ\"ב יש ספק שמא הלכה כאותם פוסקים דס\"ל דבריה בטלה בתתק\"ס, וכמ\"ש למעלה.","b":false},{"t":"[וע\"ש עוד בדבור שאחרי זה בדין בריה שנולדה בפרי בתלוש שלא היתה אסורה מעיקרא אלא עד שיפרשו אם יש לה דין בריה, וע\"ש באורך.]","b":false},{"t":"י\"ח. ומ\"ש הרב קנות דעת בשם הגרשז\"א ז\"ל שבריה שנחתכה בפה לא בטלה שלא כדעת החזו\"א ע\"ה, אחר המחילה אינו כן, שהרי הגרש\"ז אורבך ע\"ה בספרו הבהיר מנחת שלמה ח\"ב (סי' ס\"א) כתב בענין החשש מתולעים מפני מיעוט המצוי, שלצערנו הוא דבר מצוי וחמור מאד שגם בכה\"ג שא\"א לבדוק אלא ע\"י טורח גדול מאד, שזה ודאי רק מדרבנן, אפ\"ה החמירו בזה הפוסקים. ומ\"ש הכרו\"פ (סי' ק' סק\"ד) דלא חשיב כבריה ומהני ליה ביטול מפני שאינו אסור מתחילת ברייתו לפני ששורץ, רבים השיגו עליו כמבואר בפ\"ת סק\"א ובדר\"ת סק\"ד. וכן מה שהעלה הגאון שיבת ציון (סי' כ\"ח) בדבר שהוא ממש מאוס אפשר דחשיב כאינו מתכוין לענין התולעת וכמתעסק בעלמא, וכדברים האלה כתב בדר\"ת (סי' פ\"ד אות כ\"ח) בשם הגאון בית אפרים, אך כתב שלא הסכימו לזה, וגם האמרי בינה (בהל' בב\"ח סי' ב') הביא סברא זו משם גאון אחד, ואין דעתו נוחה מזה.","b":false},{"t":"והוסיף המנח\"ש בזוה\"ל: ואיך שהוא נראה דבשעה שמכניסן לתוך הפה חשיב כספק עברה מפני שהוא ממש עושה עכשיו (מעשה), וכמ\"ש רעק\"א ביו\"ד (סימן פ\"ו ס\"ו) דבכה\"ג לא נחשב לאין מתכוין, מ\"מ על צד רחוק אולי אפשר לדון דבדבר שאפשר ללעוס היטב חזי לאצטרופי דשפיר חשיב כאינו מתכוין, דיתכן שסמוך לבליעתו כבר יתרסק ויתמעך באופן דמהני ליה ביטול ונהפך להיות היתר, ונמצא דבשעה שמכניס הפרי תוך הפה הו\"ל כאינו מתכוין כלל לתולעת ויש ספק על להבא דשמא לא יהיה אח\"כ שום איסור, וזה אמנם דבודאי תולעת חלילה לסמוך על זה כמובא בדר\"ת (סי' ק' אות ב'), מ\"מ לגבי החשש דמיעוט המצוי אפשר שיכולים להתחשב עם זה. כי יש מקום לומר דאע\"ג דקי\"ל כר' יוחנן דחילקו בפנים בתוך הפה עדיין יש על זה דין בריה, מ\"מ בדבר שהוא מתועב ומאוס, ולא שייך כלל לומר בו שכך דרך אכילתו, שהרי כל אדם היה שמח אם היה יכול להסירו בקל, לכן אפ\"ל דאע\"ג שהתורה אסרתו אפי' כשהוא ממש מאוס וגם חשיב בריה, מ\"מ אם נתרסק סמוך לבליעתו אפשר דבכה\"ג תו לא חשיב בריה וצ\"ע. כמובן שזה רק הערה גרידא ולא להלכה. עכ\"ל. והנה אם עלה ע\"ד של הרב הכותב נר\"ו דהחזו\"א ע\"ה לא ראה לסוגיא דחולין הנ\"ל, הנה הגרש\"ז אורבך ז\"ל הביאה, וכתב שיש לחלק ולומר דבתולעת אם נתרסקה בפה לפני הבליעה, כבר לא חשיבא בריה, ונתן טעם חדש בדבר דכיון שהיא מתועבת ממש, לא שייך לומר בה כלל שכן דרך אכילתו, ובטלה. וע\"ל שכתבתי זה מטעמים אחרים, ונצדקו דברי החזו\"א ע\"ה שדבר ה' היה בפיהו.","b":false},{"t":"עו\"כ שם ועתה הגם שלא הייתי רוצה להזדקק לשאלותיכם מחמת מיעוט ידיעתי ונוסף לזה חולשת זכרוני, מ\"מ מפני הכבוד הנני משיב הפעם בקצירת האומר כפי סדר האותיות המחכימות, רק ממה שנלענ\"ד מסברא לפי קט שכלי.","b":false},{"t":"וע\"ש שבאות א' העלה כהמשכנו\"י (סי' י\"ז) דמיעוט המצוי הוא עשרה אחוז, ויש לחשוש, בברוקולי. ע\"ש.","b":false},{"t":"ובאות ג' כתב, נראה דבבישול יש ס\"ס, שמא לא היו ואת\"ל היו שמא נתמעכו ונתבטלו, אבל ברחיצה א\"ל שמא לא היו ואם היו שמא הוסרו ע\"י רחיצה דהוא רק ספק אחד, אם הוא בדוק מתולעים או לא, ואם רחיצה לא חשיבא בדיקה הר\"ז חשוב כלא נבדק, אך צ\"ע לדעת דמה טעם לא נתחשב לדעת אם גם אחר הרחיצה יש עדיין שיעור המצוי, וכמו\"כ נראה דיכולים לסמוך תמיד בדברים הנראים מבחוץ יפה אם גם בכאלה יש מיעוט המצוי.","b":false},{"t":"ובאו' ה' נראה שמי שעבר ובישל כסה וכדו' בלי בדיקה שרי באכילה מכוח תרי ספיקי (שמא אין ושמא נתרסק) כנ\"ל או' ג'. ושרי גם לאחרים. ע\"ש.","b":false},{"t":"והעלה דאפי' נתבשל בשביל ישראלים, כגון מסעדה שמסתמא מקפידים על תולעים הנראים לעין, ומבשלים כי סומכים על איזה רבנים שמותר לבשלם כך, ונעשה עבור אלה שסומכים עליהם, (כלומר שבישלו עבור אלה שסומכים על הרבנים ההם), מותר גם לאחרים לאכול אע\"פ שלכתחילה לא היו סומכים ע\"ז. וזה בצירוף שהמניעה מבדיקה היא מחמת הטורח הגדול, ולא מפני שרוצים ליהנות משרצים שהם מאוסים מאד אצל כל אדם, ובכה\"ג לא חשיב מבטל איסור לכתחילה, ולכן נלענ\"ד דשפיר מותר גם לאחרים, ובאות ו' כתב לסמוך על הפר\"ח דאחר ו' חדשים ממיתת התולעת נעשה כעפר. (פר\"ח בסי' פ\"ד סקכ\"ג), אע\"ג דיש אוסרים בממית אותם בידים.","b":false},{"t":"ובאות ח' כתב בברוקולי שהתולעים מכוסים תוך הפרחים, ואפשר להסיר חלקם ע\"י רחיצה ושפשוף במים, למה לא לעשות, אך אם עי\"ז יפסיד גם מהפרחים שגם הם נאכלים, צ\"ע. ע\"כ.","b":false},{"t":"ומכל הפרטים האלה יש חיזוק גדול למה שכתבתי, דיש בזה ספקות וס\"ס רבים, ויש מקום לצרפם ולהתיר ע\"י בדיקה ורחיצה כראוי, וכנ\"ל.","b":false},{"t":"י\"ט. עו\"כ במנח\"ש שם (סימן ס\"א – ב') בתשובה לרה\"ג שמעון שוואב במסעדות ומלונות המגישים כסה כרובית וכרוב תרד ואספרגוס ואין יכולים לבדוק כל עלה בנפרד, רק שורין אותן במי מלח ואומרים שהתולעים עולים למעלה ושופכים המים ורוחצים במים, ותולעים אלו לא נראים לרוב בנ\"א רק כנגד נורת חשמל, ומשרד הבריאות דורש שיגישו ירקות אלו, ויש הפס\"מ אם לא ישתמשו בהם.","b":false},{"t":"וכתב דמסתבר דע\"י ששרו, חשיב ספק דרחוק שיהיה בכל עלה חשש תולעת, ואפילו בספק איסור ממש כתב הפר\"ת דגם לסוברים שאין מבטלים איסור לכתחילה הוא מה\"ת, מ\"מ בספק איסור אפי' רבנן לא גזרו, והובא בשד\"ח כללים (מער' א' אות ה'). ומהרש\"ם ח\"ב (סי' כ\"ח) סמך על זה ומתיר לבטל ספק איסור לכתחילה, וכ\"ש בזה דאינו רוצה כלל בתולעים דמאיסי, וגם טרח רבות לנקותם, ועוד דכשיש טורח גדול מאד, מבואר באחרונים דחשיב כדיעבד לענין חטים מחומצים לפני פסח שעדיין הוא היתר, וברית אברהם חא\"ח (סי' ל\"ד או' ג') הסתמך על מ\"ש תוי\"ט שהסתמך על הרמב\"ם (פי\"א מתרומות ה\"ד) דכשלא מתכוין לבטל את האיסור לא מטריחינן יותר מכדי לכבד כדרכו, אך כ\"ז בתרומה ולא בתולעים.","b":false},{"t":"עו\"כ ומעתה אע\"פ שבריה לא בטיל, מ\"מ אפשר דבכה\"ג שאינם נראין לעין כלל גם כנגד השמש אע\"פ שמסתבר שלגבי דאורייתא ה\"ז בריה והאוכלה לוקה, דלא דמי לשרצים שאין נראים אלא ע\"י מיקרוסקופ או זכוכית מגדלת, דכאן הם נראים ע\"י עין רגילה בלי מכשיר, מ\"מ לענין זה דבריה אינה מתבטלת שהוא רק דרבנן משום דחשיב טפי שלוקין עליה אפי' שהיא קטנה מאד ואין לה שיעור, מ\"מ בכגון זה שלא נראים לאור יום רגיל לא הפקיעו מהם חז\"ל דין ביטול, ומיד אחר שנבדקו כהנ\"ל הם בטלים, וכ\"ש אחר הבישול שכבר לא רואים אותם לגמרי וא\"א לבוררם.","b":false},{"t":"וגם אפשר שכיון שהם עדיין קטנים מאד, חושבני שע\"י הרתיחה נמסים הם ותו לא הוו בריה, גם לא מסתבר שראשונים כמלאכים נכשלו בזה, והרי הזכיר כב' ענין ס\"ס, דאפשר שלרוב קטנותם עדיין לא שרצו במחובר, ומוסיף, דאפשר שנתרסקו ע\"י הלעיסה לפני הבליעה, ואע\"ג דקי\"ל כרבי יוחנן דנתחלקו בפנים עדיין יש עליהם דין בריה, מ\"מ במאוס ומתועב דודאי לא ניחא ליה אפשר דלא שייך כלל הטעם שכך דרך אכילתו. (והנה עוד חילוק על מה שכבר כתבתי לעיל. שמ\"ע).","b":false},{"t":"ומלבד כ\"ז יש להזכיר ד' הכרו\"פ (סי' ק' סק\"ד) דשרץ לא חשוב כאסור מתחילת ברייתו, כיון שאיסורו מתחיל רק לאחר ששרץ, ולא חשיב בריה, והשיבת ציון (סי' כ\"ח) כתב שאם אין דעתו על התולעת חשיב מתעסק, וכ\"כ אמרי בינה דין בב\"ח סס\"י ד' בשם גאון אחד, ובדרכ\"ת (סי' פ\"ד או' כ\"ח) כתב כן משם בעל בית אפרים, ולא דמי למ\"ש אין מתעסק בחלבים מפני שנהנה, דהכא שאני שההנאה מהפרי לא מהתולעת, ואע\"ג דהוי כספק פסי\"ר לשעבר דלא חשיב אינו מתכוין, כמ\"ש רעק\"א ביו\"ד סי' פ\"ז ס\"ו, מ\"מ נראה שאם הבירור אינו יכול להיות רק ע\"י טורח גדול מאד חשיב כדיעבד, ושפיר חשיב בנ\"ד כנעשה אח\"כ בשעת אכילה ע\"י מתעסק וכאינו מתכוין דמותר, שגם גרירת מטה וכדו' יכולים לדעת מראש ע\"י מומחה גדול, ואפ\"ה מותר, וכיון דשרי לבעל המסעדה ה\"ה דשרי גם לאחרים.","b":false},{"t":"ושוב אני מדגיש שזה רק להעיר, וע\"כ לא הקפדתי לכתוב כראוי ויותר מדוייק ומסודר. עכד\"ק.","b":false},{"t":"כ. ובערוך השלחן שם כתב עוד, שהגאון משכנות יעקב (בסימן ל\"א) אחר שכתב שיש לסמוך על כל הני רבוותא הנז', כתב עוד היתר, וז\"ל דהנה בגמרא מדמה בריה לחתיכה הראויה להתכבד, ועביד בינייהו צריכותא והטעם הוא מפני החשיבות, ודבר חשוב לא בטל. וא\"כ נראה דהיינו דוקא אם הבריה או החתיכה הראויה להתכבד עומדת בעינה וניכרת, רק שאין ידוע איזו האסורה שחשיבותן עליהן, אבל אם מעוצם קטנותן נאבד ממשן, והוא דבר המתערב ממש ונדבק בפת, או שנתערב בתבשיל וא\"א להפרידן כלל, כמו המילבי'ן הקטנים ולא יהיה לעולם בעין בפני עצמו, רק תמיד בתערובת לא נודע מקומם איה, לא נאמר עליו בריה שאני, כיון שאין לו מקום בפ\"ע שיהא חשיבותו עליו וכו'. עכ\"ל.","b":false},{"t":"וכתב הערוה\"ש דיש מקום למערער לערער ע\"ז, דעכ\"פ התורה חייבה עליו מלקות, וכדאיתא בש\"ס אכל נמלה לוקה חמש, וכפי שנתבאר, הטעם שהחמירו חכמים בביטולן הוא משום שיש בהם מלקות, וא\"כ כל זמן שלוקין עליהן כשהן בפ\"ע אינן בטלין בתערובתן. עכ\"ד.","b":false},{"t":"ואילולי דב\"ק היה מקום לומר דנכון שיש בהם מלקות, ועכ\"ז לא אמרו שאינם בטלים אלא מפני חשיבותן וכמו חה\"ל, דכזית נבלה ג\"כ יש בו מלקות ואפ\"ה בטל כמו כל האיסורים, ורק כשהיא חה\"ל דחשיבא אז דינה שאינה בטלה, נמצא דלא המלקות הוא שגורם שלא יתבטל, אלא החשיבות גורמת. ובריה חשובה כשהיא בריה שלמה, ודעת משכנו\"י דכשאינה עומדת בפ\"ע בטלה חשיבותה, וע\"כ אע\"פ שיש בה מלקות בטלה כשאר איסורים. וצ\"ע.","b":false},{"t":"עו\"כ בערוה\"ש שם, שיש היתר אחר לכל הדעות, דהב\"י (סס\"י ק\"ד) כתב דברים המאוסים שנפשו של אדם קצה בהם כנמלים וזבובים ויתושים שכל אדם בודל מהם למאיסותן, אפילו נתערבו בבישול ונמחה גופן לתוכו, אם ההיתר רבה עליהן מותר. עכ\"ל. והדברים ק\"ו אם במין בשאינו מינו, דלרוב הפוסקים טעם כעיקר דאורייתא, באלה א\"צ ששים, כ\"ש בביטול בריה דזה רק מדרבנן, דפשיטא שלא גזרו על דברים המאוסים כנמלים וכו'. והן אמת דבאכילה בפ\"ע חייב מלקות, מ\"מ א\"א לומר שחכמים גזרו עליהם שלא יתבטלו כלל. [ואחר המח\"ר יש מקום להשיב, ודי בזה.]","b":false},{"t":"עו\"כ שם, ועוד דטעם זה דהגזרה מפני חיוב מלקות לא נאמר בגמ', ורק יש מהפוסקים שכתבו כן, ופשיטא דלישנא משמע משום חשיבות, כחתיכה הראויה להתכבד ודבר שבמנין, וכשם שהתורה חייבה מלקות על בריה משום חשיבות כדאיתא במכות. [צ\"ל דחייבה גם כשאין בה כזית, והוא משום חשיבות. הכותב]. כמו\"כ גזרו חכמים שלא תתבטל משום חשיבות, וכשם שהתורה חייבה מלקות על בריה שנסרחה ג\"כ, כמו שכתב הרמב\"ם בהמ\"א ספ\"ב, ובודאי שחז\"ל לא יאמרו שלא בטל, דטעם לפגם מותר גם מן התורה, ה\"נ גם דברים המאוסים לא גזרו שלא יתבטלו. עכ\"ד.","b":false},{"t":"ואחר המח\"ר השתא דהכריע שהכל תלוי בחשיבות, היה לו לשוב וליישב דברי משכנו\"י ממה שהקשה עליו קודם, וכמו שכתבתי לעיל בעניותי. ועוד דיש חילוק בין בריה שנסרחה ובין דברים המאוסים, דדברים המאוסין התורה אסרתן כמו שהן, אבל בריה שהיתה טובה כמו צפור נבלה ואח\"כ הסריחה, דלא אסרתה תורה בצורה זו, י\"ל דיצא ממנה שם איסורה ע\"י שנסרחה, וכמו כל נותן טעם לפגם. תדע דבדין בריה (בסימן ק' ס\"א) כתוב: כגון נמלה וכו', אפילו באלף לא בטלה. עכ\"ל. הנה מפורש להדיא שגם נמלה דין בריה עליה ולא בטלה. וע\"ל שהזכרתי פלוג' דבתראי בענין זה, ורוב האחרונים פשיטא להו דגם בדברים המאוסים יש דין בריה.","b":false},{"t":"כ\"א. ועפ\"י האמור יש מקום להעיר גם בראיה שהביא לזה, שכתב וז\"ל, וראיה ברורה לזה מדברי בעל או\"ה הארוך (כלל ל\"ב דין ו') וז\"ל ואפילו בריה שלמה מוסרחת שנתערבה אף גופה בטל במינו ברוב, כגון נמלה, ובשאינו מינו בששים כשאר איסורין, שאע\"פ שעדיין חשובה היא אפי' למלקות וכו', דלא חילקה תורה בין שרץ המסריח לשאינו מסריח, מ\"מ לענין ביטול בטלה חשיבותה. עכ\"ל. וכ\"כ רבינו הרמ\"א (בסי' ק\"ג ס\"א) וז\"ל מיהו דברים החשובים, כבריה או כיוצ\"ב, אם אינם פגומים בעצמם, אע\"פ שפוגמין התבשיל, אינן בטלים אפילו באלף. עכ\"ל. וכתב הערוה\"ש על זה, אבל כשפגומים בעצמם בטלים, והרי אין לך פגום יותר מנמלה וזבוב ותולעת וכיו\"ב, שהם מאוסים ונפש האדם קצה בהם, ולכן פשוט שהם בטלים. וכו', עכ\"ל.","b":false},{"t":"ואחר המח\"ר מהדר\"ג של בעל ערוה\"ש ע\"ה, הרמ\"א ז\"ל מדבר על דברים מאוסים שהתקלקלו והסריחו ממש, וגם האו\"ה מיירי בזבוב או נמלה שהסריחו, בזה ס\"ל דבטל ממנה דין בריה, אבל כשהם במצבם הרגיל באמת יש להם דין בריה אע\"פ שהם מאוסים ונפש האדם קצה בהם, מ\"מ כך אסרתם התורה, ומ\"ש האו\"ה כשהסריחו אז בטל מהם דין בריה, והרמ\"א ז\"ל כתב ג\"כ דאם אינם פגומים, כלומר שלא התקלקלו מכפי שהם בטבעם, יש להם דין בריה, אע\"פ שהם פוגמים המאכל שהרי מאוסים הן, ואשר ע\"כ דין בריה יש להם לכל הדברים המאוסים מטבעם, כל זמן שלא התקלקלו מכפי טבעם ולא הסריחו.","b":false},{"t":"ואכן גם הרב ערוה\"ש שב וכתב, וראיתי מי שכתב לחלק בין סירחון דאתי מעלמא לסירחון דידהו, דבסירחון דידהו אינם בטלים, (פמ\"ג בש\"ד סק\"א) ותמהני דממ\"נ אם מדמה למלקות הוא גם בסירחון דאתי מעלמא חייב מלקות כל זמן (שלא נפסלו מאכילת אדם) שראוי לאכילה בדוחק. ואם לא נדמה למלקות ותלוי רק בחשיבות, היעלה בדעת דבסירחון דידהו יש חשיבות, ומנ\"ל לומר דבר נגד הסברא ונגד האו\"ה והרמ\"א. וראיתי בדבריו שהוסיף וכתב משם הפנים מאירות דבריה הפגומה בעצמה בטלה חשיבותה, והגאון חות יאיר הודה לדבריו, וא\"כ הדברים ברורים בס\"ד, והמקום ידון אותנו לזכות בשם שאנו דינים זכות על כלל ישראל. עכ\"ל.","b":false},{"t":"ואם לסברא יש מקום לומר שסירחון הטבעי שלהם לא מוציאם מדין בריה, שהתורה אסרתם כמות שהם. וחז\"ל קבעו שיש להם דין מיוחד שלא מתבטלים, ולא קבעו את זה על נמלה משופרת ומתוקנת אלא כדרך ברייתה, ורק כשמתקלקלת ומסריחה, בזה כתב האו\"ה דבטל ממנה דין בריה. וכבר כתבתי לעיל דרוב האחרונים מפרשים דברי הרמ\"א ז\"ל בהגה (סימן ק\"ג ס\"א) דלא בטל מהם דין בריה אלא כשהתקלקלו והסריחו, אבל כשהם כדרך ברייתם לא בטלי כלל, ורק בצבי לצדיק (שבגליון הש\"ע) מפרש כדעת הערוך השלחן, אבל כל שאר המפרשים חולקים על זה, ומ\"ש בערוך השלחן שהפנים מאירות מפרש כדעתו והסכים עמו החו\"י, הוא פלא שבפירוש כתב הבית מאיר שכונת הרמ\"א ז\"ל בהגה' הנז', היא בדברים שהיו משובחים כעכברא דדברא שהסריחו, דבטל ממנו דין בריה, אבל תולעים וכיוצ\"ב שטעמם פגום ומאוס מעיקרא, לא בטל, וכתב שכן עיקר בכונת פנים מאירות.","b":false},{"t":"ואולם הפ\"ת (בסי' ק\"ג סק\"א) אכן כתב שהפנים מאירות הבין שכונת הרמ\"א ז\"ל לומר שאין דין בריה בזבובים וכיוצ\"ב, אך מ\"מ הוסיף שהפמ\"א חלק עליו ופסק דבריה אפי' פגומה בעצמה לא בטלה. ומבואר עוד בפ\"ת (סי' ק' סק\"ג) והבאתיו לעיל, שגם שם מבואר להדיא שהפ\"מ חולק על הרמ\"א. ואולם הבית מאיר מבאר שגם הרמ\"א ז\"ל מודה בזה, דגם זבובים וכדו' לא בטלי, אלא כונת הרמ\"א (בסי' ק\"ג ס\"א) היא על דברים שאינם פגומים בטעמם כמו צפור טמאה וכיו\"ב, דאם הסריחו בטל מהם דין בריה. ופלא על הרב ערוה\"ש שהעלים עיניו מכל זה.","b":false},{"t":"ושו\"ר אחרי רואי שכבר העיר עליו בכף החיים (בסימן ק\"ג סק\"ה ע\"ד ההגה שאם אינן פגומים בעצמם וכו'.) ששם כתב וז\"ל, משמע דאם הם פגומים בעצמם כגון שסרחו בטלים ברוב, והיינו דוקא בדברים שהם חשובים מעיקרא כגון צפור טמא, וחתיכת נבלה הראויה להתכבד, ודבר שבמנין שנסרחו אח\"כ הם מתבטלים, אבל דברים המאוסים מצד עצמם כעכברים וזבובים ויתושים ושקצים ורמשים וכיוצא, הגם שיש להם טעם פגום ומאוס אינם בטלים. מנחת כהן בס' התערובות, פר\"ח (או' א'), לה\"פ (אות ו'), בל\"י (או' ג'), ודלא בפנים מאירות ח\"ב (סי' ס\"ז) שהבין שגם בזה מתיר הרמ\"א וחלק עליו ע\"ש. גם דלא כערוה\"ש (אות י\"א) שכתב דהרמ\"א מתיר גם תולעים המאוסים בעצמם וכן זבובים ופרעושים וכיוצ\"ב שנאבדו תוך התבשיל ואינם ניכרים, דבטלים לגמרי ע\"ש. דהוא נגד דברי הפוסקים הנ\"ל, וגם הוא נגד דברי הרשב\"א שפסק השו\"ע בסס\"י ק\"ד, ומבואר שם בב\"י דדוקא אם חסרו או נתרסקו בטלים ברוב, ולא כשהם שלמים וגם מ\"ש (בערוה\"ש) שכן מבואר באו\"ה (סי' ל\"ב דין ו') אינו, כי שם כתוב אם סרחו, ולא כשהם פגומים בעצמם, וכ\"ה בהדיא בתו\"ח (כלל פ\"ה דין כ\"ד). וע\"ל סימן ק\"א אות ל\"ב. עכ\"ל. נמצא שגם הכה\"ח העיר עליו וס\"ל ככל שכתבתי לעיל.","b":false},{"t":"ואמנם יש מקום לומר שכונת בעל ערוה\"ש הוא לומר, שדעת הרמ\"א ז\"ל להתיר בזבובים וכיוצ\"ב שאין להם דין בריה מפני מאיסותם, ושכן הבין הפנים מאירות בכונת הרמ\"א ז\"ל (סי' ק\"ג ס\"א), ואעפ\"י שהפנים מאירות פליג עליו לדינא, מ\"מ כך הבין בדעת הרמ\"א ז\"ל, והוא מצרף את דעת הרמ\"א ללמד זכות.","b":false},{"t":"וכבר כתבתי שגם הרב צבי לצדיק (בגליון הש\"ע שם) הבין כן בדעת הרמ\"א ופוסק כן. ואע\"ג דרבו החולקים והבאתי דברי הב\"מ שהוא מפרש כן כדעת הרמ\"א ז\"ל, מ\"מ מכלל פלוגתא לא נפק, והגאון ערוה\"ש בא לומר שיש דעות שסוברים כן, ובשעה\"ד גדול סומכים גם על דעת המיעוט באיסורא דרבנן, וכמו שהקדים שם.","b":false},{"t":"ועוד נלע\"ד להוסיף עוד צד של היתר, דגם לדעת רוה\"פ שסוברים דבריה מאוסה לא בטלה, מ\"מ זה רק כשהיא עדיין במצב רגיל אבל אם התקלקלה ונסרחה, לכו\"ע בטל ממנה דין בריה וכאשר העליתי, (וכן מבואר בכה\"ח שם אות ו') שאפילו עכברים וזבובים וכיו\"ב (שמברייתם הם מאוסים וע\"כ לא בטלים כהנ\"ל.) אם נסרחו אח\"כ ואינם ראויים למאכל אדם בטלים ברוב. או\"ה שם, וכן משמע במ\"מ (המ\"א פ\"ב הכ\"א), פר\"ת (אות ב') ודלא כהפר\"ח שאוסר, ערך השלחן (אות א'), חו\"ד (אות ג') מש\"ז (אות ב'), והחק\"ל חי\"ד (סימן ע\"א) כתב לדחות דברי הפר\"ח הנז'. זבח\"צ (אות ה').","b":false},{"t":"ובתולעים וחרקים שבירקות רבים מהם מתים ומתעפשים בתוך כפלי העלים ומתרקבים ומתבטל מהם דין בריה, וע\"כ בכל מה שנשאר ולא עלה בידו להסירו, יש להסתפק שמא הסריח עד שאינו ראוי לאכילה, ובטל ברוב. וגם ספק זה מצטרף לשאר הספקות הנזכרים למעלה.","b":false},{"t":"* * *","b":false},{"t":"העולה מן הענין, שיש חומרים מסוכנים שמשתמשים בהם בדרך כלל, להדברת החרקים מן הירקות, ולטענת מומחים (כמ\"ש לעיל, וכן שמעתי עוד מאחרים שמועות חזקות ולא פוסקות), הרי שבירקות המפוקחים מפני החרקים, משתמשים בכמויות יותר גדולות שיש בהם סכנה מוחשית לבריאותם של אוכלי ירקות אלו.","b":false},{"t":"מאידך המגדלים עצמם והסוחרים וכן כמה רבנים חשובים, שמסוככים עליהם בהשגחה כשרותית רחבה, מכחישים טענות אלו בתוקף גדול מאד.","b":false},{"t":"ולמעשה על בעלי הירקות וכל המתעסקים בהם, מוטלת חובת ההוכחה להוכיח בבירור גמור את צדקת טענתם, ואין שום הצדקה בעולם שאנשים שנזהרים מאיסור תולעים וחרקים, שהוא איסור חמור ומרובה מאד, ומשלמים על זה במיטב כספם, וגם מיעוטי יכולת מקמצים מעיסתם וחוסכים מאכל מפיהם ומפי עולליהם, כדי להנצל מאיסורים חמורים, ויפלו בסכנות שהם חמורות יותר מן האיסורים, ואפילו אם תמצי לומר שעדיין לא הוכח הדבר לגמרי, לחוש מיהא בעי, ובזה אין מחלוקת, וספק חמור זה לא יוסר בדברים וצעקות אלא בבדיקות מוסמכות ומוכחות, ע\"י מעבדות חיצוניות, שאין להם שום קשר עמם, ושאין שום ספק במיומנותם ובנאמנותם.","b":false},{"t":"ומן הראוי שמחלקת הכשרות הארצית תקח לידיה הנאמנות והמיומנות, את הטיפול בענין זה, ע\"י פניה רשמית למשרד הבריאות, בעמידה איתנה ועיקשת על האמת. או בכל דרך אחרת שיסכימו עליה עם הסוחרים, ובלבד שלא יהיה בה שום ספק כלל ועיקר ויבררו הענין היטב, וכתורה יעשו.","b":false},{"t":"ובינתים הדברים כתובים וערוכים, והספקות מונחים לעיני כל, וכל איש יעשה בביתו כפי שנראה לו, או כפי אשר יורו לו רבותיו, וכל רב ינהג כיד ה' הטובה עליו.","b":false},{"t":"ולענין הכשרים ציבוריים הדבר נתון לשיקול דעתם של נותני ההכשר, כל אחד יבדוק עד היכן שידו מגעת ויורה הלכה כאשר נראה לו. עד אשר תתוקן המציאות בדרך נכונה כהנ\"ל. ולה' הישועה.","b":false}]},{"t":"בענין כניסת כהנים למוזיאון השואה","p":[{"t":"בס\"ד, י\"ב תשרי, תשס\"ז בדבר השאלה אם מותר לכהנים לבקר במוזיאון השואה ביד ושם בעה\"ק ירושלים ת\"ו, אשר שם מונח אפר של קדושים שנספו בשואה ושרפום בני עולה. הי\"ד. א. בדין אפר אדם אם מטמא. הנה במשנה באהלות (פ\"ב מ\"א), תנן אלו מטמאים באהל המת, וכזית מן המת, וכזית נצל וכו'. ובמשנה ב' שם תנן, רביעית דם, ורביעית דם תבוסה ממת אחד, וכו'. אפר שרופים, רבי אליעזר אומר שיעורו ברובע, וחכמים מטהרים. ופירש הרב ז\"ל אפר שרופים, אדם שנשרף ונעשה אפר, ולא נתערב בו מאפר עצים: שיעורו ברובע, קב אפר מטמא, וחכמים מטהרים, והלכה כחכמים. עכ\"ל. והמלאכת שלמה שם כתב, דבנדה פ' המפלת (כ\"ז ע\"ב), אמרינן דרבי יוחנן ס\"ל כר\"א. ועיין בפי' הר\"ש ז\"ל שכתב, ומיהו כי מעיינת בה שפיר, אפילו ר' יוחנן כרבנן כדפרישית לעיל ע\"ש. עכ\"ל. והנה בנדה (כ\"ז ע\"א), איתא, ת\"ר שליא בבית הבית טמא, לא שהשליא ולד, אלא שאין שליא בלא ולד עמה, דברי ר\"מ, ר' יוסי ור' יהודה ור\"ש מטהרין, אמרו לו ר\"מ אי אתה מודה שאם הוציאוהו לבית החיצון שהוא טהור, אמר להן אבל, ולמה לפי שאינו, (פירש\"י הואיל וטלטלוהו נימוק), אמרו לו כשם שאינו בבית החיצון כך אינו בבית הפנימי, אמר להן אינו דומה נימוק פעם אחת לנימוק ב\"פ, יתיב רב פפא אחוריה דרב ביבי קמיה דרב המנונא, ויתיב וקאמר מ\"ט דר\"ש קסבר כל טומאה שנתערב בה ממין אחר בטלה, ופירש\"י ז\"ל מ\"ט דר\"ש, נהי דנמוק, מ\"מ כל גופו של מת כאן הוה, והו\"ל כרקב וכנצל, ממין אחר, אפילו ממין טומאה אם אינה שוה לה בטלה. עכ\"ל. עוד אמרו בגמרא שם (ע\"ב), דתניא איזהו מת שיש לו רקב ואיזהו מת שאין לו רקב. נקבר ערום בארון של שיש, או ע\"ג רצפה של אבנים זהו מת שיש לו רקב, נקבר בכסותו או בארון של עץ או ע\"ג רצפה של לבנים זה מת שאין לו רקב. ולא אמרו רקב אלא למת בלבד, למעוטי הרוג דלא, ופירש\"י ז\"ל שאין לו רקב, שאין רקב שלו מטמא. בארון של שיש וכו', דהשתא אין תערובת ברקבוביתו. נקבר בכסותו, דאיכא רקבובית וכו'. שאין לו רקב מפני דבר אחר המעורב בו. לאפוקי הרוג, לפי שיצא דמו וחסר, וקי\"ל במס' נזיר (נ\"א ע\"א), מת שחסר אין לו רקב. עכ\"ל. עוד אמרו שם (סוף ע\"ב), ר\"ל אמר שפיר שטרפוהו במימיו נעשה כמת שנתבלבלה צורתו. א\"ל ר' יוחנן לר\"ל מת שנתבלבלה צורתו מנלן דטהור וכו'. (ושם כ\"ח ע\"א), א\"ל רבינא לרב אשי ר' יוחנן דאמר (רש\"י ר' יוחנן דבעי למימר מת שנתבלבלה צורתו טמא), כמאן, כר' אליעזר, דתנן (אהלות פ\"ב מ\"ב), אפר שרופין ר\"א אומר שיעורו ברובע. ה\"ד מת שנשרף ושלדו קיימת אמר אביי כגון ששרפו ע\"ג קטבלא (פירש\"י עוד שלוק וקשה, ואינה נשרפת עם המת). רבא אמר ששרפו ע\"ג אפודרים (אבן שיש שאין העפר יכול להתפזר), רבינא אמר כגון דאיחרוני אחריני (פירש\"י, המת, ולא נעשה אפר). ע\"כ. והנה בזה יובן מ\"ש הר\"ב ז\"ל בפירושו למשנה הנ\"ל, שלא נתערב בו מאפר עצים. וע\"ש בתפארת ישראל (או' כ\"ג), שכתב, שנשרפו ע\"ג אבן, דאז אין בו תערובת עצים שהתערבו תחת האבן. עוד כתב שם (אות כ\"ד), דחכמים מטהרים אפר המת לגמרי. ושם בבועז (אות ג'), הקשה מ\"ש אפר (שחכמים מטהרים), מרקב, ומ\"ש שנעשה הגוף אפר ע\"י רקבון או ע\"י שריפה. וגם לר\"א קשה דהרי רקב חמור מעצמות, דשיעור עצמות ו' בצים, ורקב שיעורו מלא חפניו, ולמה בשרוף משער ר\"א כשיעור העצמות, והרי האפר דומה לרקב ולא לעצמות. וי\"ל שאני רקב ששלטה בו כוח המיתה טפי מעצמות וע\"כ גם שיעורו חמור מעצמות, משא\"כ אפר שרוף שלא כוח המיתה עשאו אפר וע\"כ שיעורו כעצמות, ולרבנן כיון שנשתנה ע\"י דבר אחר שלא ע\"י מיתה הו\"ל כבריה חדשה דטהור. עכ\"ד. ובאמת מיד שראיתי תחילת דברי התפא\"י, תמהתי וכי זה בנוי עפ\"י סברא, והרי כל דינים אלו מהפסוקים ומהקבלה הם, ומיד תמהתי ע\"ז מהרמב\"ם בהל' טומאת מת (פ\"ג ה\"ו), וז\"ל טחן המת עד שנעשה רקב אינו מטמא עד שירקיב מאליו. עכ\"ל ואולי זו היא כונתו, ובאמת בסוף דבריו הזכיר את הרמב\"ם ז\"ל הזה. ועיין במשנה אחרונה דהקשה על ר\"א דס\"ל דהאפר דינו כעצמות, והא קי\"ל כל האיסורים שנשרפו עפרן מותר, וחמץ שחרכו מותר בהנאה. שאני טומאה כדפי' לעיל, דר\"א דריש לכל טומאתו וכו', ומשום דלא ידעינן אפר זה אי רובו מן העצמות או מן הבשר, כשיש בו רובע ממ\"נ טמא דמן העצמות שיעורו ברובע, ואם מן הבשר כ\"ש דטמא ששיעור הבשר בכזית. וחכמים מטהרים דלא דרשי לכל טומאתו, לטומאות הפורשות, כדפי' לעיל. עכ\"ל. ובאמת שאין צריכים לטעמים וסברות. דהכל מגזרת הכתוב וקבלת חז\"ל. אך באמת גם בגזרת הכתוב ניתן לומר טעם, בדרך אפשר. וכן שמעתי בזמנו מפי מו\"ר הגאון מוהרי\"נ רוזנטל שליט\"א שדיבר עם מרן בעל החזו\"א ע\"ה, והחזו\"א אמר טעם ושאלו, והר\"ז גזה\"כ, והשיב בגזה\"כ א\"צ טעם, אבל אין איסור לתת טעם. ובפירוש המשנה להרמב\"ם ז\"ל כתב, ואפר השרופין, האפר אשר ישרפו מהאדם, באשר לא התערב בו מאפר העצים, וחכמים שמו זה האפר במדרגת הגוף, כי כאשר נשרף יצא מדין המתים. עכ\"ל. והוא כהנ\"ל אלא דמלשונו ז\"ל כאן משמע קצת דמחלוקתם הוא לא בדרשות אלא בסברא, דר\"א ס\"ל דבטומאה ל\"מ שריפה לטהרו, ואפשר דלמד כן מן הרקב שדומה לשריפה וטמא. וחכמים משוים את זה לשאר האיסורי', וזה מ\"ש הר\"מ וחכמים שמו זה האפר וכו'. ולא כמ\"ש המשנה האחרונה, דמחלוקתם אי דרשי' לכל טומאותם לטומאה הפורשת מהן או לא דרשי'. ואולי יש נ\"מ אם זה מן התורה או מדרבנן, אלא דאין נ\"מ למעשה, דהלכה כחכמים שמטהרים האפר לגמרי. ועיין ברמב\"ם ז\"ל בהלכות טומאת מת (פ\"ג ה\"ט), כתב, המת שנשרף ושלדו קיימת, והוא השדרה והצלעות הרי זה מטמא כמת שלם. וא\"צ לומר אם נחרך. אבל אם נשרף עד שנתבלבלה צורת תבניתו טהור. וכן שפיר מרוקם שטרפו במים טהור, שהרי נתבלבלה צורתו. עכ\"ל. וע\"ש במקורות וציונים בשם צפנת פענח (בהמאכ\"א פ\"ב הט\"ו), שהעיר דבהל' אבות הטומאה (פ\"ד הי\"ב), לענין שרף שנשרף ושלדו קיים טמא. כתב שם הרמב\"ם ז\"ל, וקרוב בעיני שטומאה זו מדבריהם. עכ\"ל. ואולי זה שייך עם מה שדקדקתי לעיל מדברי הרמב\"ם ז\"ל בפי' המשנה הנ\"ל. ומאידך ראיתי בספר המפתח (ברמב\"ם הוצאת הר\"ש פרנקל ז\"ל), דכתבו משם שאילת יעב\"ץ ח\"ב (סי' קס\"ט), דמשמע דמטמא מדאורייתא ואסור לכהן ליטמא לזה ודלא כהירושלמי. וכנראה שלמד את זה ממ\"ש ה\"ז מטמא כמת שלם. ויש מקום לדון בזה. ובנ\"ד שיש שם אפר קדושי השואה הי\"ד. ששרפום עד שהיו לאפר גמור, דטהור הוא דקי\"ל כחכמים. ובודאי דאין בו טומאת אהל כלל, דלא רק בנתבלבלה צורת תבניתו מיירי, אלא שהכל נשרף והפך לאפר גמור דבודאי שאין בו טומאה כלל. ב. דין אפר הנשרפים כשהם חיים. ועוד דבהרוגי השואה, שרפו אותם בעודם חיים רח\"ל, וזה עוד יותר קל, ומבואר ברמב\"ם ז\"ל שם הלכה י', וז\"ל בשם המת שנפרך ונעשה כקמח טהור. וכן אפר השרופים טהור. עכ\"ל. והנה בהלכה ט' משמע דרק בנשרף עד שנתבלבלה תבניתו הוא דאינו מטמא. וכאן משמע דכל מה שנשרף אינו מטמא, וכנראה שכאן מדובר בנשרף בעודו חי, וכמשמעות הלשון דבהלכה ט' כתב, המת שנשרף וכו', ובהל' י' כתב, וכן אפר השרופין וכו'. שמשמעותו ששרפום בעודם חיים רח\"ל. ואפשר דבכה\"ג בכל אופן טהור הוא. ושו\"ר בספר המפתח שכתבו שהרב צפנת פענח עמד על הנ\"מ שבין ב' הלכות אלו. אך אינו מצוי איתי לעיין בו. ועיין חזו\"א חיו\"ד (סימן קי\"ד ס\"ז), באורך בענין שריפת המת והשלדה קיימת ע\"ש. ובנ\"ד ששמו שם אפר של קדושי השואה מאשר שרפו אנשים חיים במשרפות שלהם בודאי דאין בזה שום טומאה וגם אין לחוש לשמא נשאר איזה עצם, דמה שאמרו עצם כשעורה מטמא היינו לטומאת מגע ומשא, ומסתמא אין לחוש לזה. ואע\"ג דגזרו על בית הפרס, היינו דוקא בשדה שנחרש קבר ואבדו עצמותיו (עיין רמב\"ם הל' טומאת מת פ\"ב הט\"ז), אבל כאן ששרפום לאפר דק, אין לחוש לזה כלל. ואין לגזור מדעתנו, ועל אחת כמה וכמה כשאינו דומה בכלל. ג. גזירת בית הפרס היתה משום חשש מגע ומשא, ובמקום שלא שייך מגע ומשא מותר לכהן ליכנס. זאת ועוד, דגם בבית הפרס לא גזרו אלא על מגע ומשא, דעצם כשעורה מטמא במגע ובמשא. וכמ\"ש שם, וכן בפ\"ג (מהטו\"מ), ה\"ב, וז\"ל ואלו מטמאין במגע ובמשא ואין מטמאין באהל, אבר מן החי וכו' ועצם א' אפילו כשעורה. עכ\"ל. וכאן לא נוגעים באפר וא\"א לנגוע בו, שהרי הוא מכוסה ואין שייך בו טומאה כלל, אפילו אם היה ידוע שיש שם עצם כשעורה. ומצד טומאת אהל בעינן שיעור גדול, וכמ\"ש שם (פ\"ג ה\"א), אלו מטמאין במגע ומשא ובאהל, המת וכו', והשדרה והגולגולת, ורוב בנינו. ורוב מנינו ורובע עצמות מכל מקום, אעפ\"י שאין בהם לא רוב בנין ולא רוב מנין. וכו'. עכ\"ל. וזה ודאי דלא שייך לחשוש. וא\"כ פשיטא דאין שייך בזה טומאת אהל. [ולענ\"ד גם טומאת מגע ומשא אין בזה, אלא דאין נ\"מ בזה דבלא\"ה אינם יכולים לנגוע בו]. ואפילו תימא שיש שהרגו אותם בגזים וכו' ואח\"כ שרפו לגופותיהם בעוה\"ר, מ\"מ אין כאן צורת תבניתו של מת, ולא כיוצא בה, לא מניה ולא מקצתיה, רק אפר דק כקמח. ואין פה טומאה ומותר לכהנים להכנס לשם. ולי-ה עינינו נשואות תלויות, עד שיחננו ויוציאנו מאפילה לאורה, ומיגון לשמחה, ומאבל ליום טוב, ולעולם שכולו טוב בב\"א. שלמה משה עמאר ראשון לציון הרב הראשי לישראל","b":false},{"t":"בס\"ד, י\"ב תשרי, תשס\"ז","b":false},{"t":"בדבר השאלה אם מותר לכהנים לבקר במוזיאון השואה ביד ושם בעה\"ק ירושלים ת\"ו, אשר שם מונח אפר של קדושים שנספו בשואה ושרפום בני עולה. הי\"ד.","b":false},{"t":"א.","b":false},{"t":"בדין אפר אדם אם מטמא.","b":true},{"t":"הנה במשנה באהלות (פ\"ב מ\"א), תנן אלו מטמאים באהל המת, וכזית מן המת, וכזית נצל וכו'. ובמשנה ב' שם תנן, רביעית דם, ורביעית דם תבוסה ממת אחד, וכו'. אפר שרופים, רבי אליעזר אומר שיעורו ברובע, וחכמים מטהרים. ופירש הרב ז\"ל אפר שרופים, אדם שנשרף ונעשה אפר, ולא נתערב בו מאפר עצים: שיעורו ברובע, קב אפר מטמא, וחכמים מטהרים, והלכה כחכמים. עכ\"ל.","b":false},{"t":"והמלאכת שלמה שם כתב, דבנדה פ' המפלת (כ\"ז ע\"ב), אמרינן דרבי יוחנן ס\"ל כר\"א. ועיין בפי' הר\"ש ז\"ל שכתב, ומיהו כי מעיינת בה שפיר, אפילו ר' יוחנן כרבנן כדפרישית לעיל ע\"ש. עכ\"ל.","b":false},{"t":"והנה בנדה (כ\"ז ע\"א), איתא, ת\"ר שליא בבית הבית טמא, לא שהשליא ולד, אלא שאין שליא בלא ולד עמה, דברי ר\"מ, ר' יוסי ור' יהודה ור\"ש מטהרין, אמרו לו ר\"מ אי אתה מודה שאם הוציאוהו לבית החיצון שהוא טהור, אמר להן אבל, ולמה לפי שאינו, (פירש\"י הואיל וטלטלוהו נימוק), אמרו לו כשם שאינו בבית החיצון כך אינו בבית הפנימי, אמר להן אינו דומה נימוק פעם אחת לנימוק ב\"פ, יתיב רב פפא אחוריה דרב ביבי קמיה דרב המנונא, ויתיב וקאמר מ\"ט דר\"ש קסבר כל טומאה שנתערב בה ממין אחר בטלה, ופירש\"י ז\"ל מ\"ט דר\"ש, נהי דנמוק, מ\"מ כל גופו של מת כאן הוה, והו\"ל כרקב וכנצל, ממין אחר, אפילו ממין טומאה אם אינה שוה לה בטלה. עכ\"ל.","b":false},{"t":"עוד אמרו בגמרא שם (ע\"ב), דתניא איזהו מת שיש לו רקב ואיזהו מת שאין לו רקב. נקבר ערום בארון של שיש, או ע\"ג רצפה של אבנים זהו מת שיש לו רקב, נקבר בכסותו או בארון של עץ או ע\"ג רצפה של לבנים זה מת שאין לו רקב. ולא אמרו רקב אלא למת בלבד, למעוטי הרוג דלא, ופירש\"י ז\"ל שאין לו רקב, שאין רקב שלו מטמא. בארון של שיש וכו', דהשתא אין תערובת ברקבוביתו. נקבר בכסותו, דאיכא רקבובית וכו'. שאין לו רקב מפני דבר אחר המעורב בו. לאפוקי הרוג, לפי שיצא דמו וחסר, וקי\"ל במס' נזיר (נ\"א ע\"א), מת שחסר אין לו רקב. עכ\"ל.","b":false},{"t":"עוד אמרו שם (סוף ע\"ב), ר\"ל אמר שפיר שטרפוהו במימיו נעשה כמת שנתבלבלה צורתו. א\"ל ר' יוחנן לר\"ל מת שנתבלבלה צורתו מנלן דטהור וכו'. (ושם כ\"ח ע\"א), א\"ל רבינא לרב אשי ר' יוחנן דאמר (רש\"י ר' יוחנן דבעי למימר מת שנתבלבלה צורתו טמא), כמאן, כר' אליעזר, דתנן (אהלות פ\"ב מ\"ב), אפר שרופין ר\"א אומר שיעורו ברובע. ה\"ד מת שנשרף ושלדו קיימת אמר אביי כגון ששרפו ע\"ג קטבלא (פירש\"י עוד שלוק וקשה, ואינה נשרפת עם המת). רבא אמר ששרפו ע\"ג אפודרים (אבן שיש שאין העפר יכול להתפזר), רבינא אמר כגון דאיחרוני אחריני (פירש\"י, המת, ולא נעשה אפר). ע\"כ.","b":false},{"t":"והנה בזה יובן מ\"ש הר\"ב ז\"ל בפירושו למשנה הנ\"ל, שלא נתערב בו מאפר עצים. וע\"ש בתפארת ישראל (או' כ\"ג), שכתב, שנשרפו ע\"ג אבן, דאז אין בו תערובת עצים שהתערבו תחת האבן.","b":false},{"t":"עוד כתב שם (אות כ\"ד), דחכמים מטהרים אפר המת לגמרי. ושם בבועז (אות ג'), הקשה מ\"ש אפר (שחכמים מטהרים), מרקב, ומ\"ש שנעשה הגוף אפר ע\"י רקבון או ע\"י שריפה. וגם לר\"א קשה דהרי רקב חמור מעצמות, דשיעור עצמות ו' בצים, ורקב שיעורו מלא חפניו, ולמה בשרוף משער ר\"א כשיעור העצמות, והרי האפר דומה לרקב ולא לעצמות. וי\"ל שאני רקב ששלטה בו כוח המיתה טפי מעצמות וע\"כ גם שיעורו חמור מעצמות, משא\"כ אפר שרוף שלא כוח המיתה עשאו אפר וע\"כ שיעורו כעצמות, ולרבנן כיון שנשתנה ע\"י דבר אחר שלא ע\"י מיתה הו\"ל כבריה חדשה דטהור. עכ\"ד.","b":false},{"t":"ובאמת מיד שראיתי תחילת דברי התפא\"י, תמהתי וכי זה בנוי עפ\"י סברא, והרי כל דינים אלו מהפסוקים ומהקבלה הם, ומיד תמהתי ע\"ז מהרמב\"ם בהל' טומאת מת (פ\"ג ה\"ו), וז\"ל טחן המת עד שנעשה רקב אינו מטמא עד שירקיב מאליו. עכ\"ל ואולי זו היא כונתו, ובאמת בסוף דבריו הזכיר את הרמב\"ם ז\"ל הזה.","b":false},{"t":"ועיין במשנה אחרונה דהקשה על ר\"א דס\"ל דהאפר דינו כעצמות, והא קי\"ל כל האיסורים שנשרפו עפרן מותר, וחמץ שחרכו מותר בהנאה. שאני טומאה כדפי' לעיל, דר\"א דריש לכל טומאתו וכו', ומשום דלא ידעינן אפר זה אי רובו מן העצמות או מן הבשר, כשיש בו רובע ממ\"נ טמא דמן העצמות שיעורו ברובע, ואם מן הבשר כ\"ש דטמא ששיעור הבשר בכזית. וחכמים מטהרים דלא דרשי לכל טומאתו, לטומאות הפורשות, כדפי' לעיל. עכ\"ל. ובאמת שאין צריכים לטעמים וסברות. דהכל מגזרת הכתוב וקבלת חז\"ל.","b":false},{"t":"אך באמת גם בגזרת הכתוב ניתן לומר טעם, בדרך אפשר. וכן שמעתי בזמנו מפי מו\"ר הגאון מוהרי\"נ רוזנטל שליט\"א שדיבר עם מרן בעל החזו\"א ע\"ה, והחזו\"א אמר טעם ושאלו, והר\"ז גזה\"כ, והשיב בגזה\"כ א\"צ טעם, אבל אין איסור לתת טעם.","b":false},{"t":"ובפירוש המשנה להרמב\"ם ז\"ל כתב, ואפר השרופין, האפר אשר ישרפו מהאדם, באשר לא התערב בו מאפר העצים, וחכמים שמו זה האפר במדרגת הגוף, כי כאשר נשרף יצא מדין המתים. עכ\"ל.","b":false},{"t":"והוא כהנ\"ל אלא דמלשונו ז\"ל כאן משמע קצת דמחלוקתם הוא לא בדרשות אלא בסברא, דר\"א ס\"ל דבטומאה ל\"מ שריפה לטהרו, ואפשר דלמד כן מן הרקב שדומה לשריפה וטמא. וחכמים משוים את זה לשאר האיסורי', וזה מ\"ש הר\"מ וחכמים שמו זה האפר וכו'. ולא כמ\"ש המשנה האחרונה, דמחלוקתם אי דרשי' לכל טומאותם לטומאה הפורשת מהן או לא דרשי'. ואולי יש נ\"מ אם זה מן התורה או מדרבנן, אלא דאין נ\"מ למעשה, דהלכה כחכמים שמטהרים האפר לגמרי.","b":false},{"t":"ועיין ברמב\"ם ז\"ל בהלכות טומאת מת (פ\"ג ה\"ט), כתב, המת שנשרף ושלדו קיימת, והוא השדרה והצלעות הרי זה מטמא כמת שלם. וא\"צ לומר אם נחרך. אבל אם נשרף עד שנתבלבלה צורת תבניתו טהור. וכן שפיר מרוקם שטרפו במים טהור, שהרי נתבלבלה צורתו. עכ\"ל.","b":false},{"t":"וע\"ש במקורות וציונים בשם צפנת פענח (בהמאכ\"א פ\"ב הט\"ו), שהעיר דבהל' אבות הטומאה (פ\"ד הי\"ב), לענין שרף שנשרף ושלדו קיים טמא. כתב שם הרמב\"ם ז\"ל, וקרוב בעיני שטומאה זו מדבריהם. עכ\"ל. ואולי זה שייך עם מה שדקדקתי לעיל מדברי הרמב\"ם ז\"ל בפי' המשנה הנ\"ל. ומאידך ראיתי בספר המפתח (ברמב\"ם הוצאת הר\"ש פרנקל ז\"ל), דכתבו משם שאילת יעב\"ץ ח\"ב (סי' קס\"ט), דמשמע דמטמא מדאורייתא ואסור לכהן ליטמא לזה ודלא כהירושלמי. וכנראה שלמד את זה ממ\"ש ה\"ז מטמא כמת שלם. ויש מקום לדון בזה.","b":false},{"t":"ובנ\"ד שיש שם אפר קדושי השואה הי\"ד. ששרפום עד שהיו לאפר גמור, דטהור הוא דקי\"ל כחכמים. ובודאי דאין בו טומאת אהל כלל, דלא רק בנתבלבלה צורת תבניתו מיירי, אלא שהכל נשרף והפך לאפר גמור דבודאי שאין בו טומאה כלל.","b":false},{"t":"ב.","b":false},{"t":"דין אפר הנשרפים כשהם חיים.","b":true},{"t":"ועוד דבהרוגי השואה, שרפו אותם בעודם חיים רח\"ל, וזה עוד יותר קל, ומבואר ברמב\"ם ז\"ל שם הלכה י', וז\"ל בשם המת שנפרך ונעשה כקמח טהור. וכן אפר השרופים טהור. עכ\"ל. והנה בהלכה ט' משמע דרק בנשרף עד שנתבלבלה תבניתו הוא דאינו מטמא. וכאן משמע דכל מה שנשרף אינו מטמא, וכנראה שכאן מדובר בנשרף בעודו חי, וכמשמעות הלשון דבהלכה ט' כתב, המת שנשרף וכו', ובהל' י' כתב, וכן אפר השרופין וכו'. שמשמעותו ששרפום בעודם חיים רח\"ל. ואפשר דבכה\"ג בכל אופן טהור הוא. ושו\"ר בספר המפתח שכתבו שהרב צפנת פענח עמד על הנ\"מ שבין ב' הלכות אלו. אך אינו מצוי איתי לעיין בו. ועיין חזו\"א חיו\"ד (סימן קי\"ד ס\"ז), באורך בענין שריפת המת והשלדה קיימת ע\"ש.","b":false},{"t":"ובנ\"ד ששמו שם אפר של קדושי השואה מאשר שרפו אנשים חיים במשרפות שלהם בודאי דאין בזה שום טומאה וגם אין לחוש לשמא נשאר איזה עצם, דמה שאמרו עצם כשעורה מטמא היינו לטומאת מגע ומשא, ומסתמא אין לחוש לזה. ואע\"ג דגזרו על בית הפרס, היינו דוקא בשדה שנחרש קבר ואבדו עצמותיו (עיין רמב\"ם הל' טומאת מת פ\"ב הט\"ז), אבל כאן ששרפום לאפר דק, אין לחוש לזה כלל. ואין לגזור מדעתנו, ועל אחת כמה וכמה כשאינו דומה בכלל.","b":false},{"t":"ג.","b":false},{"t":"גזירת בית הפרס היתה משום חשש מגע ומשא, ובמקום שלא שייך מגע ומשא מותר לכהן ליכנס.","b":true},{"t":"זאת ועוד, דגם בבית הפרס לא גזרו אלא על מגע ומשא, דעצם כשעורה מטמא במגע ובמשא. וכמ\"ש שם, וכן בפ\"ג (מהטו\"מ), ה\"ב, וז\"ל ואלו מטמאין במגע ובמשא ואין מטמאין באהל, אבר מן החי וכו' ועצם א' אפילו כשעורה. עכ\"ל. וכאן לא נוגעים באפר וא\"א לנגוע בו, שהרי הוא מכוסה ואין שייך בו טומאה כלל, אפילו אם היה ידוע שיש שם עצם כשעורה.","b":false},{"t":"ומצד טומאת אהל בעינן שיעור גדול, וכמ\"ש שם (פ\"ג ה\"א), אלו מטמאין במגע ומשא ובאהל, המת וכו', והשדרה והגולגולת, ורוב בנינו. ורוב מנינו ורובע עצמות מכל מקום, אעפ\"י שאין בהם לא רוב בנין ולא רוב מנין. וכו'. עכ\"ל. וזה ודאי דלא שייך לחשוש. וא\"כ פשיטא דאין שייך בזה טומאת אהל. [ולענ\"ד גם טומאת מגע ומשא אין בזה, אלא דאין נ\"מ בזה דבלא\"ה אינם יכולים לנגוע בו].","b":false},{"t":"ואפילו תימא שיש שהרגו אותם בגזים וכו' ואח\"כ שרפו לגופותיהם בעוה\"ר, מ\"מ אין כאן צורת תבניתו של מת, ולא כיוצא בה, לא מניה ולא מקצתיה, רק אפר דק כקמח. ואין פה טומאה ומותר לכהנים להכנס לשם.","b":false},{"t":"ולי-ה עינינו נשואות תלויות, עד שיחננו ויוציאנו מאפילה לאורה, ומיגון לשמחה, ומאבל ליום טוב, ולעולם שכולו טוב בב\"א.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"מלך המשיח – ובית המקדש השלישי בב\"א","p":[{"t":"בעהית\"ש. אור ליום ששי ערש\"ק מטות עשרים יום בתמוז התשע\"א.","b":false},{"t":"בין המצרים, אשא עיני אל ההרים, לעורר זכות ישרים, אבותינו הטהורים, זכים קדושים וברים, לפני אדיר אדירים, גדול עצה משפיל ומרים, רב להושיע מתיר אסורים, הוא יתיר שבועות ונדרים, יסיר קוצים וסירים, לפנות דרכים ואתרים, וקרן עמו יחיש להרים, יאיר חשכינו באור אורים, לשמח בני ציון היקרים, טף ונשים זקנים ונערים, בהגלות מבשר בראש הרים, בתרועת צהלה בלי שברי'ם, לשמח לב בנים והורים, באין אומר ואין דברים, וכל הנדחים והשבורים, יעלו ציון עדרים עדרים, בפנים זוהרים מאירים, ושמחת עולם על ראשם בבא לציון גואל בב\"א.","b":false},{"t":"א. הנה לשונו הטהור של רבינו הרמב\"ם ז\"ל בהלכות מלכים (פי\"א ה\"א), מורה לכאורה שרק מלך המשיח הוא שיבנה את ביהמ\"ק. וז\"ל שם, המלך המשיח עתיד לעמוד ולהחזיר מלכות בית דוד ליושנה הממשלה הראשונה, ובונה מקדש, ומקבץ נדחי ישראל, וחוזרין כל המשפטים בימיו כשהיו מקדם, מקריבין קרבנות, ועושין שמיטין ויובלות ככל מצותן האמורות בתורה.","b":false},{"t":"וכל מי שאינו מאמין בו, או מי שאינו מחכה לביאתו, לא בשאר הנביאים לבד הוא כופר, אלא בתורה ובמשה רבינו, שהרי התורה העידה עליו, שנאמר ושב ה' א-ל-היך את שבותך ורחמך, ושב וקבצך מכל העמים וכו', אם יהיה נדחך וגו'. ואלו הדברים המפורשים בתורה הם כוללים כל הדברים שנאמרו על ידי כל הנביאים.","b":false},{"t":"גם בפרשת בלעם נאמר שם, ונבא בשני המשיחים, במשיח הראשון שהוא דוד שהושיע את ישראל מיד צריהם, ובמשיח האחרון שיעמוד מבניו שיושיע את ישראל מיד בני עשו. ושם הוא אומר, אראנו ולא עתה, זה דוד. אשורנו ולא קרוב, זה מלך המשיח. וכו'. (ע\"ש שהאריך עוד בביאור הפסוקים מנבואת בלעם על שני המשיחים הנ\"ל.)","b":false},{"t":"ובהלכה ב' שם כתב, שגם בערי המקלט, הוא אומר כי ירחיב ה' וגו', אבל בדברי הנביאים אין הדבר צריך ראיה, שכל הספרים מלאים מזה. עכ\"ל.","b":false},{"t":"וממה שכתב שמלך המשיח מחזיר מלכות בית דוד, ובונה מקדש, משמע שזה מתפקידו של מלך המשיח, והיה אפשר ללמוד מזה שאין אנו רשאים לבנותו עד בא מלך המשיח. ואולם קשה לומר כן שהרי בריש הלכות מלכים (פ\"א ה\"א) כתב: שלש מצות נצטוו ישראל בשעת כניסתן לארץ, למנות להם מלך, שנאמר שום תשים עליך מלך, ולהכרית זרעו של עמלק, שנאמר תמחה את זכה עמלק. ולבנות להם בית הבחירה, שנאמר לשכנו תדרשו ובאת שמה. עכ\"ל. הרי שלא תלה כאן בנין ביהמ\"ק בביאת המשיח. ואולם יש מקום לדחות ולומר שבהלכה זו לא מיירי ממה שעתיד לבא, אלא ממה שנצטוו בעת כניסתם לארץ בימי קדם, ושכן הלשון מורה באומרו, שלש מצות נצטוו בשעת כניסתן לארץ, וכן משהזכיר מלחמת עמלק, ושימת מלך שהיה בימי שמואל הנביא ע\"ה, כיע\"ש בהמשך דבריו ז\"ל.","b":false},{"t":"אבל באמת הדבר מבואר ומפורש במקום אחר שיש מצוה בכל עת לבנות ביהמ\"ק, והוא בהלכות בית הבחירה (פ\"א ה\"א) וז\"ל: מצות עשה לעשות בית לה' מוכן להיות מקריבין בו הקרבנות, וחוגגין אליו שלש פעמים בשנה שנאמר, ועשו לי מקדש. וכבר נתפרש בתורה משכן שעשה משה רבינו, והיה לפי שעה, שנא' כי לא באתם עד עתה וגו'. עכ\"ל. ומהלשון נראה שהיא מצות עשה שאינה תלויה בשום ענין. וגם בזה\"ז אם היינו יכולים להשיג הדבר בהיתר ובלי סכנת נפשות רח\"ל. יש מצוה לבנותו.","b":false},{"t":"וכן משמע במנין המצות (מ\"ע כ') וז\"ל, והמצוה העשרים היא שציונו לבנות בית עבודה, בו יהיה ההקרבה והבערת האש תמיד, ואליו יהיה ההליכה והעליה לרגל, והקבוץ בכל שנה כמו שיתבאר, והוא אומרו יתעלה, ועשו לי מקדש. ולשון ספרי שלש מצות נצטוו ישראל בשעת כניסתן לארץ, למנות להם מלך, ולבנות להם בית הבחירה, ולהכרית זרע של עמלק. הנה התבאר שבנין בית הבחירה מצוה בפני עצמה, וכבר ביארנו (ריש שרש י\"ב) שזה הכלל הוא כולל חלקים, ושהמנורה והשלחן והמזבח וזולתם כולם הם מחלקי המקדש וכו', עכ\"ל.","b":false},{"t":"ב. וצריכים להבין מה שכתב רבינו בפרק י\"א מהלכות מלכים, שמלך המשיח בונה המקדש וכו', והיה נראה לומר דבפי\"א מיירי מהבית השלישי שאליו עינינו צופיות מאז החורבן של בית שני בעוה\"ר. וזה תלוי במלך המשיח, אך מ\"ש בהל' בית הבחירה, הוא לא בבית שלישי אלא מצות עשה לעשות בית לה' מוכן להקריב בו קרבנות. וצ\"ע אם מדבר על הר הבית, או בכל מקום כגון המשכן שעמד שנים רבות בשילה ובנוב וגבעון. תדע שגם בפ\"א ה\"א (בהל' מלכים הנז') שכתב ג' מצות נצטוו ישראל בשעת כניסתן לארץ, ופירשתי דמיירי בכניסתן לא\"י בפעם הראשונה גם שם מיירי בבית בחירה זמני בלבד. דידוע דלא בנו מקדש מיד רק העמידו המשכן שנים רבות כל פעם במקום אחר, עד שנתעורר דוד המלך ע\"ה על בנייתו ופנה אל נתן הנביא ע\"ה, כמו שנאמר, ויהי כי ישב המלך בביתו וה' הניח לו מסביב מכל אויביו, ויאמר המלך אל נתן הנביא, ראה אנכי יושב בבית ארזים, וארון הא-ל-הים יושב בתוך היריעה (שמואל ב', ז') והכס\"מ (הל' בית הבחירה פ\"א ה\"א) כתב משם הסמ\"ג (מ\"ע קס\"ג) שכתב וז\"ל, תניא ג' מצות נצטוו ישראל וכו', ולבנות בית הבחירה שנא' והיה המקום אשר יבחר ה' א-ל-היכם לשכן שמו שם, שמה תביאו וגו', והוסיף שזמן מצות בנין ביהמ\"ק לא הגיעה עד ימי דוד וכן הוא אומר ויהי כי ישב המלך וגו'. וכתב מרן ז\"ל שהסמ\"ג לא כתב את הפסוק, ועשו לי מקדש, כמו שכתב רבינו, משום דההוא קרא במשכן שבמדבר איירי. ורבינו לא נ\"ל הפסוק של הסמ\"ג, שלא כתוב בו בנין ביהמ\"ק אלא מספר שיביאו שם קרבנות, ולא ציוה על בנייתו. ואע\"ג דועשו מקדש איירי במשכן, משמע לרבנו דכלל הוא מכל מקום בין למשכן שבמדבר ובין לשילה ונוב וגבעון בין לבית עולמים, ודייקא נמי דקאמר ועשו לי מקדש, ולא קאמר ועשו לי משכן.","b":false},{"t":"ובפי\"א שמדבר על מלך המשיח שעתיד לעמוד, ומפרט את תפקידו ויעודו אשר יעד לו הקב\"ה, מנה ביניהם גם את בנין ביהמ\"ק, ואמר ובונה מקדש. ומה שלא אמר שבימיו יקום בית שלישי, רק תלה אותו בו ואמר שיבנהו, אפשר שבא לאפוקי מדעת רש\"י ותוספות, דס\"ל שביהמ\"ק השלישי ירד בנוי מן השמים. שכן כתב רש\"י במסכת ר\"ה (ל' ע\"א) וכן בסוכה (מ\"א ע\"א) וגם התוספות בסוכה שם כתבו כן, וכן בשבועות (ט\"ו ע\"ב) והוא עפ\"י מדרש תנחומא ועוד. ובהמשך נשוב לענין זה, בעה\"ו.","b":false},{"t":"ועוד י\"ל אפילו תימא שגם מה שכתב בהלכות בית הבחירה (פ\"א ה\"א) מצות עשה לעשות בית לה' וכו'. דקאי גם על הבית השלישי, באופן שהיא מצוה מוטלת על כלל ישראל, ולא קשורה בביאת המשיח בלבד, מ\"מ כתב אצל המשיח, ובונה מקדש, דאע\"ג שהיא מוטלת על הכלל, מ\"מ אצל מלך המשיח היא חיובית ביותר, ובה יִוַדַע כי משיח ה' הוא, שהרי המשיח הוא אדם מתוך אנשי הדור, ואינו צריך לעשות אותות ומופתים או לחדש דברים בעולם כדי שידע שהוא המשיח, וכמבואר ברמב\"ם (הל' מלכים פי\"א ה\"ג) אל יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים וכו', שהרי ר\"ע חכם גדול מחכמי המשנה היה, והוא היה נושא כליו של בן כוזבא המלך, והוא היה אומר עליו שהוא מלך המשיח, ודמה הוא וכל חכמי דורו שהוא המלך המשיח, עד שנהרג בעונות, כיון שנהרג נודע שאינו משיח, ולא שאלו ממנו חכמים לא אות ולא מופת. וכו'. עו\"כ בהלכה ד' (שם) אם יעמוד מלך מבית דוד הוגה בתורה ועוסק במצות כדוד אביו, כפי תורה שבכתב ושבע\"פ, ויכוף כל ישראל לילך בה ולחזק בדקה, וילחם מלחמות ה', הרי זה בחזקת שהוא משיח. אם עשה והצליח ונצח כל האומות שסביביו, ובנה מקדש במקומו, וקבץ נדחי ישראל, הרי זה משיח בודאי. ואם לא הצליח עד כה, או נהרג בידוע שאינו זה שהבטיחה עליו תורה, והרי זה ככל מלכי בית דוד הכשרים שמתו. וכו' (ושם הביא ענין ישוע הנוצרי, ושל זה הישמעאלי ע\"ש). נמצא שיש לו דברים שצריך להשלים ואז יודע כי משיח השם הוא, ואחד מהם הוא שהוא בונה מקדש במקומו.","b":false},{"t":"והנה עתה נלע\"ד לחזק הפירוש הראשון שכתבתי, והוא ממה שכתב הרמב\"ם ז\"ל גבי משיח ובונה מקדש במקומו\". ומזה נראה שהוא כמו שכתבתי לפני כן, שאפשר שרק המשיח בונה בית שלישי שהוא במקומו ממש. אבל המצוה המוטלת על כלל ישראל אפשר שזה מקדש זמני, ואולי בשאר המקומות יבנו אותו. ואם זה נכון אתי שפיר מה שלא הזכיר תיבת \"במקומו\" אלא במלך המשיח, (פי\"א מהל' מלכים ה\"ד), אבל בפ\"א ה\"א שם לא כתב במקומו, ולפי מה שכתבתי לעיל שם מיירי בכניסה ראשונה לארץ, ואז לא בנו במקומו עד שנתעורר עליו דוד מלך ישראל, ובנאו שלמה בנו על מקומו. וגם בריש הלכות בית הבחירה, שכתב מצות עשה לעשות בית לה', ג\"כ לא כתב במקומו. ולא עוד אלא הוסיף וכתב, מצות עשה וכו' שנאמר ועשו לי מקדש, וכבר נתפרש בתורה משכן שעשה משה רבינו, והיה לפי שעה, שנאמר כי לא באתם עד עתה וגו' עכ\"ל. וצ\"ל למה הוסיף כאן להודיענו שמשכן שעשה משה היה לפי שעה, וכאן לא מדבר בענין המשכן כלל, ואם נאמר שגם מצות בניית המקדש שכתב כאן, וכן במנין המצות היא לפי שעה עד בא משיח, אתי שפיר. ועוד שהוסיף הרמב\"ם ז\"ל שם את כל המקומות שעמד בהם המשכן, שבגלגל עמד י\"ד שנים, וכן הזכיר ופירט על נוב וגבעון ובית אל, ואין זה המקום של המשכן וגלגוליו, אלא אם נאמר שגם מצות עשה דבניית בית הבחירה, היא באותה מתכונת זמנית. ועכ\"פ הרי מפורש להדיא דאינו משיח בודאי עד שיעשה שלש אלה ינצח, ויקבץ, ויבנה, שאם שלש אלה יעשה אז הוא משיח בודאי, אבל אם לא ישלים שלשת הדברים הללו שהן המטרות שלו והמיוחדות לו, ואחת מהן שיבנה מקדש במקומו, לא מיקרי משיח. וכל זמן שרואים שהוא עוסק בהם, הרי הוא בחזקת משיח, עד שישלים לשלשתם, ואז יקרא משיח ודאי. ואפשר דשני הדברים אמת שאצל מלך המשיח הוא באמת הכרחי שיבנה המקדש, ובאלו יבחן שאמת משיח ה' הוא, ומיהו בעינן גם שיהיה במקומו, ומה שכתב בהלכות בית הבחירה שיש מצות עשה לעשות מקדש ולהקריב קרבנות, אפשר שזה לא מקדש עולמים אלא זמני, ואפשר שאינו מדבר על מקומו ממש. אלא בכל מקום שיבנו בית לה' מוכן להיות מקריבים בו הקרבנות וחוגגים אליו וכו', מקיימים בזה מצות עשה דועשו לי מקדש ושכנתי בתוכם, וזהו ההבדל שבין הלכות בית הבחירה (פ\"א ה\"א), דמיירי בזה\"ז, ועל כל מקום ומקום קאי, וע\"כ דקדק לכתוב שגם המשכן היה לשעה וכו'. אבל בהל' מלכים ששם מדבר על כך שמשיח בונה המקדש, שם דקדק לכתוב, ובונה מקדש \"במקומו\", דוקא.","b":false},{"t":"אלא דקשה לומר זה, שהרמב\"ם ז\"ל עצמו כתב שם (בהל' בית הבחירה פ\"א ה\"ג) וז\"ל, כיון שנבנה המקדש בירושלים, נאסרו כל המקומות כולן לבנות בהם בית לה', ולהקריב בהם קרבן, ואין שם בית לדורי הדורות אלא בירושלים בלבד ובהר המוריה שבה. שנאמר ויאמר דוד זה הוא בית ה' הא-ל-הים וזה מזבח לעולה לישראל, ואומר, זאת מנוחתי עדי עד. עכ\"ל. וע\"ש ברדב\"ז ובכסף משנה שציינו המשנה (בזבחים קי\"ב ע\"ב) והגמ' שם (קי\"ח ע\"ב וקי\"ט ע\"א).","b":false},{"t":"ועיין רש\"י (חולין – כ\"ד ע\"א) בסוף העמוד ד\"ה במה דברים אמורים, וכו' וז\"ל: ירושלים נקראת בית עולמים דמשנחרבה לא היתה אחריה היתר לשאר מקומות, אבל קדושת שילה היתה אחריה היתר לבמות כל ימי נוב וגבעון. עכ\"ל. וברש\"י ז\"ל מפורש שמשנחרבה ירושלים לא היה עוד היתר לשום מקום אחר.","b":false},{"t":"ואמנם ברמב\"ם הנ\"ל אפשר לדחוק ולומר דה\"ק, משנבנה המקדש בירושלים נאסרו כל המקומות וכו', אבל אחר שנחרב אפשר שחזר ההיתר למקומות אחרים, כמו שהיה אחר שנחרב שילה. ומ\"ש עוד ואין שם בית לדורי הדורות אלא בירושלים בלבד, היינו בית קבוע שיהיה לדורי הדורות, אבל בית זמני אפשר שיהיה בכל מקום. ודוחק.","b":false},{"t":"ובני הרב יש\"י הי\"ו הראני שמרן החיד\"א ע\"ה בספרו הבהיר חומת אנך ח\"ב (בסוף מלאכי, דף ס\"ח ע\"ב אות ג') וערבה לה' מנחת יהודה, וז\"ל: יש מי שפירש דמשחרב בית המקדש הותרו הבמות, אבל אין מקריבין מנחה בבמה, ולעתיד לבא כשיבנה בית המקדש יקריבו מנחה, ולז\"א וערבה לה' מנחת יהודה. עכ\"ל. והיש מי שפירש הזה בודאי דלא כרש\"י ז\"ל, ובע\"כ שמפרשים כן בדברי הרמב\"ם הנ\"ל. ובזה יש מקום לפירוש שפירשתי בס\"ד ודוק'.","b":false},{"t":"ד. והנה מבחינת ההוכחה שמשיח הוא, אם אכן ירד בנוי מן השמים בימיו, אדרבה זו ההוכחה הגדולה ביותר כי משיח הוא ושהשם הסכים על ידו, ועשה פלא מופלא לכבדו ולהרים קרנו בעיני ישראל ובעיני העולם כולו. אלא שהלשון של הרמב\"ם ז\"ל שכתב בהלכה א' ובונה מקדש, וכן בהלכה ד', שכתב ובנה מקדש. משניהם משמע להדיא שהוא בונה ולא שיורד בנוי מן השמים.","b":false},{"t":"ועוד דכבר כתב הרמב\"ם (בהלכה ג') אל יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם. וכו'. ואם היה סובר כרש\"י ותוס' דהמקדש השלישי ירד בנוי ומשוכלל מן השמים, הרי אין לך אות ומופת גדול מזה. ואין לך חידוש כזה בעולם, אלא ודאי שמדבר על בנין בידי אנשי מקצוע שיבנו ויקימו מקדש בחכמה ובדעת כל יקר ונעים. כמו בצלאל ואהליאב וכל חבריהם שבנו את המשכן ע\"י משה רבינו ע\"ה, במדבר. וע\"כ נראה דבאמת הרמב\"ם חולק בזה על שיטת רש\"י ותוספות הנז'. וסבירא ליה שגם בית שלישי יבנה ע\"י עם ישראל, כמצות השם, ועשו לי מקדש.","b":false},{"t":"וצ\"ל במאי פליגי הני רבוותא, בענין בית שלישי אם יבנוהו הבונים עלי אדמות, או שירד בנוי מן השמים, כי אתה ה' באש הצתה ובאש אתה עתיד לבנותה.","b":false},{"t":"והיה מקום לתלות מחלוקת זו, במה שחקרו האחרונים אם מצות בניית המקדש היא גוף המצוה, או שאינה אלא הכשר המצוה, דהמצוה היא העבודה של ביהמ\"ק, קרבנות וקטורת, תמידים כסדרן ומוספין כהלכתן, עבודת השבתות ור\"ח וחגים ומועדים, ועבודת יום הכיפורים וכו', ובנין ביהמ\"ק הוא הכשר מצוה, שיבנו המקדש כדי להקריב קרבנות ולעלות אליו בשלש רגלים להראות אל פני האדון ה' צבאות, ואין מצוה בעצם בנייתו אלא היא הכשר מצוה שע\"י בנייתו ניתן להקריב בו קרבנות וכו', וכמו בניית סוכה שאינה מצוה לעצמה אלא שעל ידי בנייתה, ניתן לקיים מצות לישב בסוכה שהיא המצוה, בסוכות תשבו שבעת ימים, וכן נמי תקיעת שופר, שהעלה הרמב\"ם בתשובתו שהתקיעה היא הכשר המצוה בלבד. והמצוה היא לשמוע קול שופר. וע\"כ לא מברכים על תקיעת שופר. או נאמר שעצם בנייתו של המקדש היא מצוה בפני עצמה.","b":false},{"t":"ועיין בספר המפתח בריש הלכות בית הבחירה, שעמדו ע\"ז כמה גדולים, מהר\"ם שיק חא\"ח (סימן רפ\"ב), ומקדש דוד ס\"א, ואורים גדולים (דרוש לפ' תרומה י\"ד, ג-ד), וצפנת פענח כאן ועוד כיע\"ש.","b":false},{"t":"וי\"ל שלדעת רש\"י והתוספות שסוברים שהבית השלישי ירד בנוי מן השמים, סברי מרנן שכל מצות בנייתו היא הכשר לקיום מצותו שהיא עבודת ביהמ\"ק, והעיקר הוא שיהיה מקדש ושם נעבוד עבודת א-ל-הינו. וע\"כ אין קפידא שיבנה על ידינו, אלא ירד בנוי ומשוכלל מן השמים, ושם נעבוד עבודת ה' כמו שציונו, כהנים בעבודתם, ולויים בדוכנם, וישראל במעמדם, ואילו עצם הבניה אינה מצוה בפני עצמה, אלא היא הנותנת לנו הזדמנות לקיים מצות ה' ע\"י עבודת הקרבנות וכו'. ואשר ע\"כ כשירד בנוי ומוכן מהשמים די לנו בזה כדי שנוכל לעבוד עבודת המקדש, ולחגוג אליו שלש פעמים בשנה.","b":false},{"t":"אבל הרמב\"ם ז\"ל וסיעתיה, סוברים שבנייתו היא עצם המצוה, שהקב\"ה ישכין שכינתו בתחתונים, וכמו שציוה במשכן שבמדבר ועשו לי מקדש, ושם בודאי שעצם בנייתו ועשייתו היא מצוה, וכן נמי לדורות, ובאמת גם זה של הדורות נלמד מאותו פסוק של המשכן, ללמד שעצם עשייתו היא מצוה לעצמה. ויש עוד מצות העבודה והם כרוכים זב\"ז, אבל לא מתקיימת מצות הקמת המשכן שהיא מצוה לעצמה אלא כשאנו נבנה אותו כאשר בנו אבותינו משה וכל ישראל את המשכן במדבר, כמו שנאמר ועשו לי מקדש ושכנתי בתוכם. אבל אם ירד בנוי ומוכן מן השמים, אעפ\"י שאפשר לקיים בו מצות הקרבנות וכו', מ\"מ לא מתקיימת מצות בנייתו על ידינו.","b":false},{"t":"והנה מעצם הלימוד שלמד הרמב\"ם ז\"ל מצות עשה זו מהפסוק של עשיית המשכן, מזה גופו נלמד שצריכי' אנו לבנותו בעצמנו כמעשה אבותינו במדבר, ולמד כן מדכתיב, ועשו לי מקדש, ולא כתב, ועשו לי משכן. וכמ\"ש מרן ז\"ל בכסף משנה הנ\"ל.","b":false},{"t":"והסמ\"ג הנז' שלמד מצוה זו מדכתיב, והיה המקום אשר יבחר ה' א-ל-היכם בו לשכן שמו שם, שמה תביאו את כל אשר אנכי מצוה אתכם עולותיכם וזבחיכם וכו'. מזה נ\"ל דס\"ל לבעל הסמ\"ג שאין בבנית המקדש עצם המצוה, אלא הכשר מצוה, שע\"י הקמתו נוכל לקיים עבודת המקדש, והבאתם שמה עולותיכם וזבחיכם וכו'. שהרי בפסוק זה לא נזכרת בניית המקדש כלל, וכמ\"ש מרן ז\"ל בכסף משנה שם.","b":false},{"t":"ואע\"ג שהרמב\"ם ז\"ל כתב מצות עשה לעשות בית לה' מוכן להיות מקריבים בו הקרבנות וחוגגין אליו שלש פעמים בשנה שנא' ועשו לי מקדש. אין כונתו לומר שהמקדש הוא כהקמת סוכה שאין בעצם הקמתה מצות עשה, אלא היא הכשר המצוה, שע\"י שיש סוכה יכולים לקיים מצותה לישב בסוכה כל שבעת ימי החג באכילה ושינה וכו'. וכמ\"ש הרמב\"ם בתשובה (לענין שמיעת קול שופר) שגם התקיעה עצמה היא רק הכשר המצוה כמו הקמת סוכה, והמצוה היא לשמוע קול שופר, ושעל כן לא מברכים לתקוע בשופר או על תקיעת שופר. כמו שלא מברכים על מצות סוכה לעשות סוכה. אלא לישב בסוכה, שהיא גוף המצוה, וגם בשופר מברכים, לשמוע קול שופר, שהשמיעה היא המצוה, ולא התקיעה עצמה. אבל כאן המצוה היא בנייתו כמו שסיים: שנאמר ועשו לי מקדש, וכבר נתפרש בתורה משכן שעשה משה רבינו, וידוע שבמשכן המצוה היא עצם עשייתו, ומאחר ומשם נלמדה המצוה גם לדורות ש\"מ שבנייתו עצמה מצוה, ומ\"ש להיות מקריבים בו קרבנות וחוגגים אליו ג\"פ בשנה, מבאר תכלית מצוה זו, שלא שיהיה מקדש לראותו בלבד, אלא נבנהו, ונשלים את יעודו להקריב בו הקרבנות, ולחגוג אליו ג\"פ בשלש רגלים.","b":false},{"t":"והרי זה דומה למצות עשה של כתיבת ס\"ת, שנלמד מדכתיב ועתה כתבו לכם את השירה הזאת, ואע\"פ שיש מצות עשה בעצם כתיבת ס\"ת לכל איש ישראל, התכלית היא לקרא וללמוד תורת ה' תמימה, לאהבה את השם ולקיים מצותיו ולעשותם, וכן במלך נאמר, וכתב לו את ספר התורה הזה, והיה עמו וקרא בו כל ימיו. ואין במה שכתוב והיה עמו וקרא בו וכו', לשלול מצות הכתיבה של ס\"ת עצמו, אלא לבאר את תכליתה של המצוה. וה\"נ אמר מצות עשה לעשות בית לה', מוכן להיות מקריבין בן הקרבנות וכו', שיש מצוה בעשייתו, ותכליתו היא לקרבנות.","b":false},{"t":"ועוד י\"ל בכונת הרמב\"ם ז\"ל, דהכי קאמר שמצות עשיית המקדש ובנייתו לא תושלם, אלא כשבונים אותו כדי לעבוד בו את ה', בקרבנות וחגיגות וכו'. אבל אם יבנוהו להתפלל ולהתייחד עם ה' באהבה וביראה, לא קיימו המצוה של בניית המקדש, אלא מצוה של בית תפלה ובית המדרש. אבל במצות עשה של בניית בית הבחירה בעינן שבנייתו ועשייתו תהיה במטרה ברורה להקריב בו הקרבנות כהלכתן. ולעלות אליו בשלש רגלים לראות פני ה' ברוך הוא.","b":false},{"t":"וכן נראה מלשונו הזהב במנין המצות שהזכרתי לעיל. (הובא בדברי מרן ז\"ל בכסף משנה שם פ\"א ה\"א בתחלתו), וז\"ל, שציונו לבנות בית הבחירה לעבודה, בו יהיה ההקרבה והבערת האש תמיד, ואליו תהיה ההליכה והעליה לרגל, והקבוץ בכל שנה. והוא אומרו יתברך, ועשו לי מקדש. עוד כתב שם, הנה נתבאר שבנין בית הבחירה מצוה בפני עצמה. וכבר ביארנו שזה הכלל הוא כולל חלקים, ושהמנורה והשלחן והמזבח וזולתם כולם הם חלק מחלקי המקדש, והכל יקרא מקדש, וכבר ייחד הציווי בכל חלק וחלק. וכו'. עכ\"ל. והרי מבואר בדבריו שמצות בנייתו היא מצוה בפני עצמה, ואע\"ג דאפשר לדחות ולבאר באופן אחר, מ\"מ הפשט לא יופשט.","b":false},{"t":"וראיתי כעת בקנאת סופרים על מנין המצות, שגם הוא עמד ע\"ד הסמ\"ג שלמד מפסוק והיה המקום וגו'. וטעמו משום שאין ללמוד מהפסוק ועשו לי מקדש, שהוא למצות שעה נאמרה על המשכן שעשו במדבר, והוא ז\"ל מקיים דברי הרמב\"ם דציווי זה קאי גם לדורות מדכתיב ביה, וכן תעשו. דהיינו לדורות, וכמ\"ש רש\"י ז\"ל שם, וקאי לעשיית המקדש וכליו שיהיו מעין הנעשה במדבר. וכדמשמע ממ\"ש בשבועות (ט\"ו ע\"א) ככל אשר אני מראה אותך, את תבנית המשכן ואת תבנית כל כליו וכן תעשו, לדורות, וכו'. עכ\"ל.","b":false},{"t":"וכבר כתבתי שמרן ז\"ל בכסף משנה שם מפרש שהרמב\"ם למד שהיא מ\"ע לדורות מדכתיב ועשו לי מקדש, ולא כתב \"משכן\" וכנ\"ל. והקנאת סופרים תלה את זה בהמשך הכתוב, וכן תעשו. ואלו ואלו דא\"ח. (וקנאת סופרים הוא של הגאון רבי חנניה קזיס מחכמי ליוורנו – איטליא, ונזכר בהערת הגאון רבי משה חגיז עלי ספרו של אביו רבי יעקב חגיז שו\"ת, הלכות קטנות, שהיה מחכמי פאס – מרוק, ובא לליוורנו להדפיס ספריו, וסופו שעלה לירושלים והקים בה ישיבה גדולה, הכי קרא שמה בית יעקב ושם למדו הפר\"ח ובעל גט פשוט ובעל גינת ורדים, ובנו רבי משה הנז' ועוד, ורבי משה הזדמן בליוורנו בשנת ... וקראוהו לעלות לס\"ת ביו\"ט שני של גלויות וכו', וע\"ש מה שנתוכח עם רבי חנניה קזיס הנז' הוא בעהמ\"ח קנאת סופרים)","b":false},{"t":"כללו של דבר שמלשון הרמב\"ם ז\"ל נראה שבניית המקדש היא מצוה בפני עצמה אלא שצריך לעשותו לקיים בו כל המצוות הכרוכות בו. ויש עוד מקום לומר שהרמב\"ם ז\"ל והסמ\"ג נחלקו בביאור המצות עשה של בנין בית הבחירה, וזה ע\"פ מה שביארתי לעיל דהרמב\"ם מחלק בין מ\"ע זו, ובין תפקידו של מלך המשיח, דמלך המשיח עתיד לעמוד ולבנות מקדש במקומו. והמ\"ע הוא לבנות בית זמני דומה למשכן, ועל כן למד מפסוק זה דועשו לי מקדש, ועוד הוסיף שידוע המשכן שעשה משה והיה לשעה. לומר שגם המצוה שכתב כאן מדברת על בית זמני, ועוד הוסיף וביאר כל המקומת שבהם עמד המשכן בגלגל ונוב וכו', לומר שגם המ\"ע מדובר בבית זמני ואפילו שלא במקומו, ואולי י\"ל דמשום דקדוקים אלו, עמד הסמ\"ג ושינה מדברי הרמב\"ם ז\"ל וכתב שזה נלמד מפסוק אחר והיה מקום וכו', כלומר שהוא סובר, שהמצות עשה דבניית בית הבחירה היא לבנות בית של קבע, ובמקומו ממש. [וצ\"ע עוד בסמ\"ג לראות מה כתב בענינו של מלך המשיח ואינו תחת ידי, ועוד חזון למועד אי\"ה].","b":false},{"t":"ה. וכאמור רש\"י ז\"ל רוח אחרת עמו בענין זה, שכן כתב בר\"ה (ל' ע\"א סוף ד\"ה ל\"צ דאיבני סמוך לשקיעת החמה דחמיסר) וז\"ל, וא\"ת היכי משכחת לה דאיבני בחמיסר ביו\"ט, ודאיבני בליליא, והא קי\"ל במס' שבועות (ט\"ו ע\"ב) דאין בנין בהמ\"ק לא בי\"ט ולא בלילה, הני מילי בידי אדם, אבל בנין העתיד לבא בידי שמים הוא. עכ\"ל. ובסוכה (מ\"א סע\"א) כתב רש\"י ז\"ל, ואי קשיא דבלילה אינו נבנה, כדקי\"ל בשבועות (ט\"ו:) דכתיב וביום הקים, ולא בחמיסר שהוא י\"ט ואינו דוחה יום טוב כ\"מ בשבועות שם, ה\"מ בידי אדם אבל מקדש העתיד שאנו מצפין בנוי ומשוכלל הוא, יגלה ויבא משמים, שנאמר מקדש ה' כוננו ידיך. עכ\"ל. וכן הסכימו בתוס' שם. ולדבריהם יש לומר דמצות בניית המקדש אינה מצוה בפני עצמה, אלא הכשר מצוה, והרי היא כהקמת הסוכה שאינה מצוה בפני עצמה, אלא הכשר לקיום מצות ישיבה בסוכה, וה\"נ בנייתו היא הכשר לקיום מצות העבודה של הקרבנות. ואשר על כן גם ברדתו בנוי ומשוכלל משמיא נחית, אין בזה חיסרון. שמצות הקרבנות וכו', יתקיימו כהלכתן.","b":false},{"t":"וראיתי בדברי יציב להגה\"ק מקלויזנבורג זצ\"ל ח\"ו הל' מקדש וקדשיו (סימן פ\"ז, עמוד רכ\"ח) שגם הוא כתב שלשיטת רש\"י ותוס' אין חיוב לבנותו אלא שיהיה. וע\"ש עוד שהזכיר דברי הזהר הקדוש בפרשת פקודי (דף ר\"מ ע\"א) וקיצר בו מאד. והנה בזהר שם איתא ויקם משה את המשכן, במאי אוקים ליה וכו'. תא חזי כתיב זכור ה' לבני אדם את יום ירושלים האומרים ערו ערו עד היסוד בה. ועל דא זמין קוב\"ה למבני יסודי ירושלים, מיסודין אחרנין דישלטו על כולא. ומאן אינון ספירין, דכתיב ויסדתיך בספירים (ישעיה נ\"ד) וכו'. מאי טעמא בגין דאבנין קדמאין מאינון יסודי, יכילו שאר עמין למשלט עלייהו, מ\"ט כיון דלית בהו נהירו עלאה כדקא יאות, אבל אילין יהון נהירין מגו נהירו עלאה כדקא יאות. וכו'. א\"ר אלעזר רזא איהו וכו', ת\"ח אינון אבניו דיסודי ציון וירושלים, חס ושלום דשלטו בהו שאר עמין, ולא אוקדו לון, אלא כולהו אתגניזו ולא אתאבידו מנייהו אפילו חד, וכד יהדר קוב\"ה ויוקים לה לירושלם על אתריה, אינון יסודי אבנין קדמאי יהדרון לאתרייהו, ולא ישלוט בהו עינא אחרא בר בזימנא דיכחול בר נש עינוי בההוא פוכא וכו'. וכדין כי עין בעין יראו בשוב ה' ציון. וכו' ע\"כ. וכתב הרב דברי יציב שבניצוצי אורות להחיד\"א ציין לעשרה מאמרות (של הרמ\"ע מפאנו) שכתב ששם מדובר באבני חומת העיר, וק\"ו למקדש שנסתלקו אבני קדש בנס להתנוסס במקום שאין היד שולטת.","b":false},{"t":"עוד ציין לספר עמודיה שבעה (עמוד שלישי סימן י\"ד) בשם ספר היכלות, ששלח הקב\"ה מלאכים והביאו לבנים ועפר וסיד ממקום אחר להשביע עינו של אותו רשע, והמקדש עצמו נבלע בארץ וכו', וקדושה ראשונה במקומה עומדת, שעיני ה' בה תמיד וכו', אלא שבעו\"ה נעלם מעינינו הבנין. ולפי האמת לא נחרב, ויעלה בעתיד כבראשונה, שלא יהיה בית מקדש חדש אלא הראשון והובא בספרו ראש דוד, וכן בספרו מדבר קדמות (מערכת מ' אות מ\"ג) ע\"ש. ובאור החמה שם, כתב דפליגי ת\"ק (שבזהר הנז') עם רבי אלעזר, שלת\"ק נחרב ביהמ\"ק השני ולעתיד לבא יבנה אחר, אבל לר\"א לא שלטו בהם זרים וכולם עומדים ונסתרים, ולעתיד לבא יתגלו, ועין בעין נראה בשוב ה' שיבת ציון.","b":false},{"t":"וע\"ש שהזכיר עוד מהזהר במקום אחר, והרב דברי יציב ע\"ה תולה המחלוקת שבזהר ובמדרשים הנ\"ל, בחקירה שכתב משם הגאון הרוגוצ'ובי ע\"ה. וז\"ל ועכ\"פ י\"ל דפליגי בהנ\"ל, דת\"ק (כונתו ת\"ק דר\"א שבזהר פקודי) והתנחומא ס\"ל שהחיוב רק שיהיה. ורבי אלעזר ס\"ל שהמצוה היא לבנות ולא מתקיימת (המצוה) ע\"י שיוריד השי\"ת (מקדש בנוי), ובע\"כ שיחזרו אותן שנבנו מכבר. עכ\"ל.","b":false},{"t":"ו. והיה מקום לומר בהיפך, דת\"ק שכתב שביהמ\"ק אכן נחרב ושלטו זרים באבניו, שבזה פירש הכתוב, ערו ערו וגו'. הוא סובר שיש מצוה בבנייתו, וע\"כ צריכין לחזור ולבנותו מחדש, ומה שאמר, ועל דא זמין קוב\"ה למבני יסודי ירושלים וכו'. אין הכונה שהקב\"ה בונהו ויורד בנוי מן השמים, שלא נחלקו ת\"ק ור\"א בפלוגתא דרש\"י והרמב\"ם, אלא כאן יש מחלוקת אחרת, האם ביהמ\"ק נחרב וצריך אבני ספירין שלא יכולים לשלוט בהם זרים לעולם, ומהם נבנה אותו. ור\"א סובר שלא נחרב מעולם, ולא יבנה מחדש אלא יחזור אותו מקדש בעצמו, וממילא דלרבי אלעזר אין המצוה בעצם הבניה, אלא שיהיה לנו מקדש. ואפשר שגם ת\"ק וגם ר\"א סוברים שיש מצוה בבנייתו, ולא בזה הם חולקים, אלא אם בכלל צריך לבנותו, או שאין צריך לבנותו שלא נחרב מעולם.","b":false},{"t":"ובדיבור שקדם לזה כתב: ולא זכיתי להבין מ\"ש בחתם סופר הנדמ\"ח עמ\"ס סוכה ע\"ד רש\"י, דאכתי מלאכת בנין היא, שהמביא אהל בנוי ומעמידו על הארץ חייב משום בונה. ע\"ש. ולהנ\"ל שלא יהיה דבר גשמי, לא שייך משום בנין בשבת ודו\"ק. ושוב מצאתי בלחם שמים להיעב\"ץ בהקדמתו למס' מדות שכתב, שהמקדש ירד מלמעלה ויתגשם בירידתו לארץ וכמו הלוחות ע\"ש ודו\"ק. עכ\"ל.","b":false},{"t":"והיה מקום לפרש בדברי החת\"ס הנז', דמפרש בדעת רש\"י כדעת רבי אלעזר שבזהר הקדוש הנז'. שהמקדש שמור למעלה עם עציו ואבניו, רק שהוא נסתר מעינינו, ולעת\"ל ירד בנוי ומשוכלל מן השמים כמ\"ש רש\"י ז\"ל, ומצד זה שאין אנו עוסקים בבנינו, נאמר מקדש ה' כוננו ידיך, והחת\"ס כתב דמ\"מ מתקיימת מצות בניה ע\"י זה שיורד ועומד בארץ, ר\"ל דמיתקרי בנין ביהמ\"ק, אפילו שלא נגעו בו ידי אדם, מ\"מ בנין מיקרי, ואעפ\"י שהוא בנוי מאז ומקדם, עכ\"פ בירידתו ועמידתו על הארץ נחשב שנבנה, אבל לא נבנה ע\"י אדם אלא כמ\"ש רש\"י שיורד בנוי מן השמים. ומ\"ש החת\"ס שהמביא אהל בנוי ומניחו על הארץ חייב משום בונה בשבת, רצה להוכיח מזה שיש בזה מלאכת בנין אם אדם מוריד אהל בנוי בידיו ומעמידו על הארץ. וע\"כ גם במקדש שיורד בנוי מהשמים, שייך בו בנין בעצם העובדא שיורד ועומד על הארץ, אך אין שייך בזה חיוב, שהרי לא אדם הוא שהורידו והעמידו, אלא בידי שמים, והכל מובן. ולא קשה מה שהקשה הגאון דברי יציב דלא שייך בנין בדבר שאינו גשמי. דלפי\"ז ר\"א אומר שאותו המקדש כמו שהיה בנוי מאז, הוא שמור בדבר ה', ובמאמרו ירד ויתגלה לעינינו, כמו שהוא בנוי מאז. וא\"כ הוא גשמי ממש, וע\"כ כתב החת\"ס דע\"י שיורד ועומד על הארץ, נחשב לבנין, ולק\"מ.","b":false},{"t":"ולהנ\"ל עולה דגם שיטת רש\"י ותוס' שיורד מן השמים, אפשר להעמידם בשיטת רבי אלעזר שבזה\"ק, שבית המקדש לא נחרב ולא שלטו בו ידים, רק עלה ונתעלם מעינינו, ובבא העת ירד בנוי ומוכן מן השמים, ועכ\"ז כתב דשייך בו בניה רק אמנם אינה בידי אדם. וא\"צ לשיטת היעב\"ץ ע\"ה בלחם שמים הנ\"ל, שהוא קאי בשיטת האומרים שירד ביהמ\"ק של אש, וכמ\"ש בדברי יציב שם שכתב משם הזהר (בראשית דף כ\"ח) שכתב אני ה' אהיה לה חומת אש סביב, ובגין דא בטורא דא אתבני מקדשא על ידא דקוב\"ה. ופירש הרב ז\"ל שזה כמו בחגיגה (י\"ד ע\"ב) וירדה אש מן השמים וסיבבה את כל האילנות. וע\"ש.","b":false},{"t":"ועל דרך זאת שנבנה באש, בזה הוא דקאמר הלחם שמים שהמקדש ירד מלמעלה ויתגשם בירידתו לארץ, וכמו הלוחות. וכנ\"ל.","b":false},{"t":"וגם בדברי הזהר הזה קיצר הרב ז\"ל, ואעתיק לשונו במשלם, והוא (בראשית דף כ\"ח ע\"א) וז\"ל, ועלה אתמר, ואני אהיה לה נאם ה' חומת אש סביב (זכריה ב'), ובגין דא בטורא דא אתבני מקדשא על ידא דקוב\"ה יהא קיימא לדרי דרין. ועליה אתמר גדול יהיה כבוד הבית הזה האחרון מן הראשון (חגי ב'), דקדמאה אתבני על ידא דבר נש, והאי על ידא דקודשא בריך הוא, ובגין דא, אם ה' לא יבנה בית שוא עמלו בוניו בו. (תהלים קכ\"ז). ע\"כ.","b":false},{"t":"ואי לאו דמסתפינא הייתי אומר שזו שיטה אחרת שלישית, דבזהר פקודי נחלקו ת\"ק ור\"א, אם נחרב המקדש והקב\"ה יבנה אחר, שזו שיטת ת\"ק, ור\"א אומר שלא נחרב אלא הוא שמור ונעלם מעינינו וה' מחזירו על כנו, ושניהם סוברים שהוא מאבנים. ובזהר בראשית היא שיטה שלישית שביהמ\"ק השלישי אכן יבנה ע\"י הקב\"ה, ואולם יהיה כולו מאש. וי\"ל שלפי שיטה זו אמר הלחם שמים שיתגשם ברדתו לארץ, שבא לבאר הכיצד תתקיים מצות בנייתו ועשייתו אם הוא כולו רוחני. ויישב שיתגשם ברדתו לארץ.","b":false},{"t":"ז. ואפשר לפרש בס\"ד דשני מקדשות היו במשכן, האחד הוא המשכן שנבנה ע\"י משה ובני ישראל במדבר, והשני הוא המקדש רוחני שנבנה למעלה בשמים, והמקדש הרוחני מתלבש בתוך המשכן שבנו משה ובני ישראל, ובתוך הרוחני שוכנת שכינת האל ב\"ה. והוא עפ\"י מה שכתבתי בלוחות במקום אחר בספר ברכת אליהו פרשת כי תשא, דשתי לוחות הם רוחניים וגשמיים וכדלהלן בעה\"ו.","b":false},{"t":"וזאת בהקדים מ\"ש רבותינו בבמדבר רבה (פי\"ב) א\"ר סימון בשעה שאמר הקב\"ה לישראל להקים את המשכן, רמז למלאכי השרת שיעשו גם הם משכן, ובעת שהוקם המשכן למטה, הוקם המשכן למעלה. וכה\"א מכון לשבתך פעלת ה'. וכו'. והובא בדברי יציב (ריש עמוד רכ\"ב) שם.","b":false},{"t":"נמצא ששני המשכנות נבנו יחד בד בבד, אחד למטה ע\"י בני ישראל, ואחד למעלה בשמים ע\"י מלאכי השרת, ואין ספק שהם מכוונים זה כנגד זה, וכמאמרם ז\"ל ירושלים של מטה מכוונת כנגד ירושלים של מעלה, והן משפיעות זע\"ז וקשורות זב\"ז.","b":false},{"t":"וצריכים להבין דברי חכמים וחידותם, אחר שציוה השם יתברך לעמו ישראל לאמר ועשו לי מקדש ושכנתי בתוכם, למה ציוה גם למלאכי השרת לעשות לו מקדש, והלא הוא ישתבח שמו איוה שתהיה לו דירה בין התחתונים, ולמה ציוה למלאכי השרת שיבנו גם הם משכן למעלה בשמים.","b":false},{"t":"ובעל כרחינו אנו צריכים לומר שבשביל השראת שכינה ממש, חייב להיות משכן רוחני שמימי, ואין מציאות שתשרה שכינה בדבר גשמי בלבד, וא\"ת איך שרתה שכינה בהר סיני, י\"ל שעל כן נאמר וירד ה' בענן, והנה ה' בעב הענן, והר סיני עשן כולו והיתה עליו אש כמו כבשן. אך איוה הקב\"ה לדור בתחתונים באהבתו לבנ\"י בנו בכורו באהבת עולם בחסד וברחמים, ורצה לקרבם אליו ישתבח שמו, וע\"כ צוה להם לאמר, ועשו לי מקדש ושכנתי בתוכם, ובאותה עת ציוה גם למלאכים להכין לו משכן למעלה, ואז השמים כסאו, והארץ הדום רגליו, ושכן בתוכנו.","b":false},{"t":"ומצאתי ראיה נכוחה להוכיח אמיתות ענין זה, בפרשת יתרו (י\"ט, כ') שם נאמר, וירד ה' על הר סיני, וגו'. וכתב רש\"י ז\"ל בזוה\"ל: יכול ירד עליו ממש, תלמוד לומר כי מן השמים דברתי עמכם (להלן כ', י\"ט) מלמד שהרכין שמים העליונים והתחתונים והציען על גבי ההר כמצע על המטה, וירד כסא הכבוד עליהם (מכילתא). עכ\"ל. הרי מפורש שאין שייכות שירד ה' על ההר ממש, אע\"פ שההר התקדש אז, והיה קדש קדשים כמבואר בראשונים שם, מ\"מ צריך מצע רוחני, ועל כן שינה הקב\"ה סדרי בראשית והוריד שמים ושמי שמים והציעם על גבי ההר כמצע על המטה, ועליהם הניח את כסא כבודו יתברך, שא\"א שתשרה שכינת הא-ל על דבר חומרי כלל, וחייב להיות מצע רוחני שעליו תשרה השכינה. וע\"כ בשעה שציוה לישראל לעשות משכן, ציוה גם למלאכי השרת לבנות לו מקדש, כדי שזה המקדש הרוחני של מלאכי השרת, יהיה מצע שעליו יעמוד כסא כבוד ה' יתברך ועל זה תשרה השכינה, וכמו שאמר הכתוב, השמים כסאי, והארץ הדום רגלי, ומשום זה נקרא שהוא יתברך דר בין התחתונים, כאשר התאוה כביכול. ואולי משום זה אמר, ושכנתי \"בתוכם\", בתוך שני המקדשות, הרוחני והגשמי.","b":false},{"t":"ועוד נלע\"ד יותר מזה שהקב\"ה מחבר את המשכן השמימי אשר בנו מלאכי השרת, עם המשכן שעשו בני ישראל, והיו לאחדים, כשהמשכן הגשמי נעשה מסגרת למשכן הרוחני השמימי, והיו אחד. והשי\"ת שוכן במשכן השמימי, כשמשכן זה מונח תוך המשכן הגשמי מעשה ידיהם של בני ישראל, והוי ליה דירה בתחתונים ממש, ושפיר מיקרי: ושכנתי בתוכם. וידוע מה שפירש בזה הרב ראשית חכמה, דלא אמר ושכנתי בתוכו, אלא בתוכם, בתוך לבו של כל אחד מישראל. ועפ\"י מה שביארתי בזה יוצא פירוש נפלא, ששני מקדשות הם, הרוחני תוך הגשמי והשם יתברך שוכן \"בתוכם\" תוך שניהם יחד.","b":false},{"t":"ולפי זה הזהר דבראשית הנז' אינו חולק על מ\"ש בזהר דפקודי, ונראה שזו שיטה שלישית. שמחלוקת ת\"ק ור\"א בזהר פ' פקודי, היא אם בית המקדש נחרב ויבנהו ה' באבנים אחרות, או שהוא קיים ושלם כמו שהיה מעיקרו, אך שמור ומכוסה מעינינו, ועתיד ה' לגלותו. ולא דיברו על אש. וגם רש\"י ותוס' משם התנחומא לא דיברו על בנין של אש, וכן כתבתי שעל שיטה זו קאי היעב\"ץ בלחם שמים, שכתב שכשיורד הוא מתגשם. כדי להסביר איך תתקיים בנייתו של המקדש, ואפשר שגם החת\"ס בא לישב אותה שאלה, איך תתקיים מצות בנייתו, אלא שקשה לו אפילו למ\"ד שיורד בנוי באבנים, סו\"ס לא נגעו בו ידים, לזה אמר דכשיורד ועומד על הארץ נחשב בנין. וצ\"ע להבין את הדברים.","b":false},{"t":"ח. ולפני שאבאר ענין זה אקדים מה שראיתי בחפש'י למרן בעל יביע אומר שליט\"א בספרו הבהיר מאור ישראל על ר\"ה (ל' ע\"א) ע\"ד רש\"י ז\"ל שביהמ\"ק העתיד לבא בידי שמים הוא. והתוס' בשבועות (ט\"ו ע\"ב) אמרו שכן מבואר במדרש תנחומא, ולמדו כן מהפסוק, מקדש ה' כוננו ידיך. וכתב שהתנחומא הוא בסוף פרשת נח סימן י\"א, וכן בתנחומא (ס\"פ פקודי). במעשה ידיך ארנן זה בנין ביהמ\"ק שיבנה במהרה בימינו, והראב\"ן ז\"ל בר\"ה (ל' ע\"א, דף קע\"ז סוף ע\"ג) כתב, לפי שהקב\"ה בעצמו יבנה בהמ\"ק השלישי, כמ\"ש בב\"ק (ס' ע\"ב) שלם ישלם וכו' (הזכיר הגמרא הנ\"ל). הנה גם הראב\"ן מפרש כרש\"י ותוס' הנ\"ל. וכן הוא בפסיקתא רבתי (פכ\"ט עמ' קל\"ד) מקדש ראשון שבנאו בשר ודם נפל ביד שונא. אבל מקדש אחרון שהקב\"ה בונהו, שנא' בונה ירושלים ה', שוב לא יחרב לעולם. וכן הביא מהתנא דבי אליהו רבה (פרק ל') שהקב\"ה בונה בית שלישי. וכן במדרש שוחר טוב (מזמור כ\"ב) הבית השלישי שיבנה ע\"י הקב\"ה לא יחרב לעולם. וע\"ש עוד מזה.","b":false},{"t":"ואולם במדרש רבה פרשת צו (פרק ט' סימן ו') עורי צפון ובואי תימן, זה מלך המשיח שנתון בצפון, יבא ויבנה בהמ\"ק הנתון בדרום, הה\"ד, העירותי מצפון וגו' (ישעיה מ\"א), וכן הוא במד\"ר (פרשת נשא), ושה\"ש (סוף פרשה ד'). וע\"ש מה שכתב משם שו\"ת חזון נחום (סימן מ\"ח).","b":false},{"t":"וע\"ש שהוכיח מהמאירי בר\"ה (ל' ע\"א) וסוכה (מ\"א.) דאזיל בשיטת הרמב\"ם ז\"ל שבנין בהמ\"ק השלישי הוא על ידי אדם. שגם הוא הקשה איך יבנה בחמיסר והלא חמיסר והוא יום טוב, ותירץ דכיון שהותרה מלאכת אוכל נפש, וגם בנין דאוכל הותר (שהוא המגבן) ע\"כ איסור בנין ביו\"ט אסור רק משום עובדין דחול, ובמצוה דרבים גדולה כזאת לא אסרו, ע\"ש.","b":false},{"t":"וכתב שכן העיר החת\"ס (בשבת צ\"ה ובסוכה מ\"א.) וכן בשו\"ת באר יצחק א\"ח (סימן י\"ג ענף ד') ובערוך לנר, ובשו\"ת מהרי\"א הלוי ח\"א (סימן פ\"ח), ועונג יו\"ט (סימן צ\"ב ובהגה).","b":false},{"t":"וכתב מרן הגאון מאור ישראל שליט\"א וז\"ל: ונראה שמחלוקת המדרשים תלויה במה שאמרו (חז\"ל), זכו עם ענני שמיא, לא זכו עני ורוכב על חמור (סנהדרין צ\"ח ע\"א), והרמב\"ם לטעמיה שאין בין העוה\"ז לימות המשיח אלא שעבוד מלכויות בלבד. (שבת ס\"ג.) עכ\"ל. ועיין עוד שם נוסחא אחרת בזה. על כל פנים רואים שדברים אלו שנויים במחלוקת במדרשים, וכן נמי נחלקו בהם הראשונים.","b":false},{"t":"וכבר כתבתי שנראה לענ\"ד דמ\"ש בזהר בראשית וכן בגמרא דב\"ק הנ\"ל ע\"פ דברי זכריה הנביא ע\"ה שהקב\"ה בונה ירושלים באש, אינו מכלל המחלוקת דת\"ק ור\"א שבזהר פרשת פקודי, וכן נראה שאין זה מכלל מחלוקת המדרשים, אם ירד בנוי או שישראל יבנו אותו, אלא הנראה לענ\"ד שיש בזה תוספת של הוד והדר ועטרת גדולה של אש מאת ה', להיות לה חומת אש סביב, ולכבוד אהיה בתוכה. ואע\"ג שהבנין יהיה בנין אבנים ועצים, בין אם הם האבנים הראשונים עצמם, ובין אם הם אחרים, יבא הבנין של אש שהוא כולו רוחני, ויקיף אותו ויהיה לחומה בעדו וייראו כל עמי הארץ כי שם ה' נקרא עלינו, וכן משמעות דברי הנביא זכריה ע\"ה, ואני אהיה לה חומת אש סביב. וקרוב לזה ראיתי בדברי יציב שם ד\"ה ומ\"ש חומת אש וכו', נראה שרצה לומר רוחני דלא שייך דבר גשמי בשמים ועיין באור החמה הנ\"ל. וזה כמו בחגיגה (י\"ד ע\"ב) [כשעסקו במעשה מרכבה] ובאה אש מן השמים וסיבבה את כל האילנות. ושם (בדף ט\"ו ע\"א) בתוס' ד\"ה שובו הביאו מהירושלמי [שבבריתו של אלישע בן אבויה, ישבו חכמי ישראל] ירדה אש מן השמים והקיפה אותם, אמר לון אבויה אבא גברין מה באתם לשרוף ביתי, א\"ל ח\"ו וכו' ע\"ש. וכן בכמה מקומות נמשלו דברים דקים ורוחניים לאורות ואש והבן. עכ\"ל.","b":false},{"t":"והנה לפי מה שחידשתי בס\"ד דשני משכנות היו, וכן בבית שלישי שיבנה בב\"א יהיה המקדש שיבנה מלך המשיח מאבנים גשמיים, ויהיה מקדש אחר שירד מן השמים שהוא כולו רוחני, וישכון בתוך המקדש הגשמי, ובתוכו תשרה שכינת א-ל יתברך, הכל יובן על נכון בס\"ד, בלי מחלוקת כלל, אלא אלו ואלו דברי א-לקים חיים, וכבר ביססתי את הענין וחיזקתי חידוש זה בראיות נכוחות בעה\"ו, והכל על מקומו יבא לשלום.","b":false},{"t":"ט. ואל תתמה על חיבור הגשם והרוח לעשותם אחד, איך אפשר, דיד ה' לא תקצר וכל אשר יחפוץ יעשה, ואין מי שיאמר לו וכו'. והרי גם האדם עצמו כך הוא, שה' א-ל-הים יצר את האדם עפר מן האדמה, וגזר הבורא יתברך, להיות גוף ונשמה באוצר אחד בחבילה אחת, דבוקים וקשורים זל\"ז כל ימי חיי האדם עלי אדמות, כדכתיב וייצר ה' א-ל-הים את האדם עפר מן האדמה, ויפח באפיו נשמת חיים, ואמרו בזהר הקדוש, מאן דנפח מדיליה קא נפח, שהנשמה ממנו כמאמר איוב, וחלק א-ל-וה ממעל. ונפחה בגוף של עפר ומים אש ורוח. ומשכינם יחד בכפיפה אחת כל ימי שנות חיי האדם אשר הוא חי עלי אדמות. והם מנוגדים בתכלית הניגוד זה חומרי לגמרי עפר מן האדמה, וזה חלק משכינתו יתברך, ושוכנים יחד וחיים יחד במאמר ה' וגזרתו.","b":false},{"t":"והנה כתבתי כעין זה בחידושים לחומש (שמות פרשת כי תשא ל\"א, י\"ח) על לוחות הברית, שנאמר, ויתן אל משה ככלתו לדבר אתו בהר סיני שני לוחות העדות, לוחות אבן כתובים באצבע א-ל-הים. ותירגם יונתן בן עוזיאל ע\"ה, ויהב למשה וכו', תרין לוחי סהדותא לוחי דאבן ספירינון מכורסי יקרא, מתקלהון ארבעין סאין כתיבין באצבעא דה'. ובפירוש יונתן שם כתב וז\"ל, דאבן ספירינון, הכי הוא בפרקי דר\"א (פרק מ\"ו) הלוחות לא נבראו מן הארץ אלא מן השמים ושל ספירין הוא. ועיין ברקנטי מ\"ש בזה. עכ\"ל.","b":false},{"t":"ותמהתי בדבריו אם הם מן השמים, איך אחזם משה בידיו, ושני לוחות אבנים הוריד בידו, ואיך אפשר לראותם, והקשה מכולם איך שיבר משה את הלוחות, האם דבר שכולו רוחני שייך בו שבירה. וחז\"ל אמרו לוחות ושברי לוחות מונחם בארון.","b":false},{"t":"ומפני זה אמרתי שהיו לוחות רוחניים עשויים מספירינון מתחת כסא כבודו. והמה מעשה א-ל-הים, והיו עוד לוחות שציוה ה' למשה לאמר פסול לך שני לוחות אבנים וגו', ומשה מפסל אותם מן הגשמיות כמובן, ולוחות הגשמיים אשר פיסל משה גם הם נעשו מאבן ספירינון, וצ\"ל שהספירינון הזה הוא גשמי, וע\"כ יכול משה לעשות ממנו לוחות, ועוד שאמרו חז\"ל שמשה התעשר מן הפסולת של הלוחות, שדרשו פסול לך, שהפסולת תהיה שלך, ואם זה רוחני איך התעשר מזה.","b":false},{"t":"וזיכני ה' בחסדיו ושו\"ר ברש\"י ז\"ל (ל\"ד, א') שכתב פסול לך, הראהו מחצב סנפירינון מתוך אהלו, ואמר לו הפסולת יהיה שלך ומשם נתעשר משה הרבה. עכ\"ל. נמצא שמחצב הסנפירינון הוא תוך אהלו של משה רבנו ע\"ה, ויונתן ב\"ע כתב שהספירינון מתחת כסא הכבוד הוא וכן הוא בפרקי דרבי אליעזר. אלא על כרחך ששני ספירינון הם. אחד רוחני לגמרי, ואחד גשמי לגמרי, והקב\"ה עשה הלוחות מהספירינון שתחת כסא הכבוד, והוא רוחני בתכלית, וציוה למשה לאמר, פסול לך, שיפסל שני לוחות מהסנפירינון שנמצא תוך אהלו, שהוא חומרי וגשמי. והקב\"ה חיבר שתי הלוחות, אלה הרוחניים עם אלה הגשמיים, והיו לאחדים בידיו של משה רבנו ע\"ה. והיו הלוחות הגשמיים שעשה משה, כעין מסגרת ללוחות הרוחניים אשר עשה השם מספירינון העליון שכולו רוחני לגמרי.","b":false},{"t":"ושם פירשתי בזה מה שאמר הכתוב (שם ל\"ד, א') ויאמר ה' אל משה פסֹל לך וגו' וכתבתי על הלוחות את הדברים אשר היו על הלוחות הראשונים וגו'. והיה צריך לומר וכתבתי וגו', כדברים הראשונים. ומזה שכתב את הדברים, משמע שאותם דברים עצמם שהיו כתובים על הלוחות הראשונים, עתה שם אותם על הלוחות השניות, שבשעה ששיבר משה את הלוחות לא נשברו הלוחות הרוחניים שלא שייך בהם שבירה כלל, אלא שיבר הלוחות הגשמיים שעשה מספירינון שלקח מהמחצב שבתוך אהלו, אותם שבר תחת ההר. והלוחות הרוחניים שנעשו מספירינן שתחת כסא הכבוד עלו למעלה שלמות כמו שהיו, שלא שייך בהם שבירה. וכדוגמת מה שאמרו, גוילין נשרפין ואותיות פורחות באויר.","b":false},{"t":"ובזה יתפרש יפה מה שאמר לו הקב\"ה למשה פסול לך שני לוחות אבנים כראשונים, כאן כתב כראשונים בכף הדמיון. (הכונה שיהיו כמו הראשונים אשר שברת), וכתבתי על הלוחות את הדברים אשר היו על הלוחות הראשונים אשר שברת. שאני אכתוב ואקבע אותם הדברים עצמם שהיו על הלוחות הראשונים הם עצמם שמורים וקיימים, ואותם אכתוב על הלוחות האלה שאתה מפסל זה עתה, ולא דומה להם ולא כיוצא בהם, אלא הם עצמם ממש.","b":false},{"t":"ודקדוק זה של וכתבתי את הדברים אשר היו. מצאתי ראיתי שכיוונתי בזה לדעתו הגדולה של הרב כלי יקר ע\"ה שכתב כן. ת\"ל יתברך.","b":false},{"t":"והנה שם על פי פירוש זה גם ביארתי המשנה באבות (פרק ה', ו') עשרה דברים נבראו ע\"ש בין השמשות, ופירשתי בס\"ד דביה\"ש הוא זמן שאור וחשך משמשין בעירבוביא, והיינו שבכל עשרת הדברים הללו יש אור הוא הרוחניות, וחשך שהוא הגשמיות, ומשמשים יחד בעירבוביא, כמו המן שהוא לחם שמים, שאופים אותו וטוחנים ומבשלים וכו', ומאידך נבלע במעיהם ולא יוצא, ורואים שיש בו רוח וגשם מעורבים, וכן פירשתי בכל עשרת הדברים השנויים שם, והלוחות גם כן שנים הם, לוחות רוחניים ולוחות גשמיים ממוזגים זע\"ז כחדא שריין וכחדא נפקן. וכנ\"ל.","b":false},{"t":"וראיתי לתלמיד רש\"י רבי יעקב ב\"ר שמשון בפירושו לאבות (הוצאת מוסד הרב קוק) שכתב, שהלוחות היו כתובים על גבי הלוחות, והרב המהדיר תיקן וכתב שצ\"ל שהדברות כתובים על הלוחות. ולהנ\"ל א\"צ לתקן, אלא דבר אמת הוא שהלוחות הרוחניים כתובים וחקוקים ככתבם וכצורתם ע\"ג הלוחות הגשמיים ממש. ומשה רבינו הוריד בידו שני לוחות אבנים שהם הלוחות הגשמיים, ובתוכם היו שני לוחות רוחניים מעשה א-ל-הים המה, שעשה הוא יתברך מן הספירינון שתחת כסא הכבוד. ושברי הלוחות שבארון, פשוט שהם שברי הלוחות הגשמיים שעשה משה רבינו ע\"ה. (ועיין עוד בברכת אליהו שם).","b":false},{"t":"והנה עפ\"י הפירוש הנזכר בענין הלוחות עלה בדעתי לפרש שגם במשכן כך היה, ששני משכנות היו, המשכן שבנה משה ובני ישראל עפ\"י מצות השם, ועשו לי מקדש. והמקדש שבנו מלאכי השרת למעלה, כפי שציוה להם ה' באותה שעה שציוה לבני ישראל לעשות לו מקדש למטה, וכמאמר רבי סימון (במדרש רבה במדבר) הנ\"ל.","b":false},{"t":"והקב\"ה מחבר לשניהם יחד, שמלביש המשכן הרוחני שעשו מלאכי השרת בתוך המשכן שבנו משה ובני ישראל. ועל המשכן הרוחני שוכנת שכינת הא-ל ברוך הוא. דמשכן זה הרוחני הוא מצע לשכינה, וכמו שהציע שמים עליונים ושמים תחתונים על הר סיני כמצע על המטה, ועליהם הניח את כסא כבודו, שא\"א שישכון על ההר עצמו שהוא חומרי, גם כאן א\"א שישכון במקדש הגשמי, עד שיציע אל תוכו את המשכן הרוחני, ועליו שוכן כבוד ה'.","b":false},{"t":"ושילוב זה הוא כמו האדם עצמו שהוא מעורב בגשם ורוח, שהגוף חומרי מורכב מארבע יסודות, וכנ\"ל.","b":false},{"t":"י. ועל פי הדרך הזאת יש לפרש בעה\"ו, שגם הבית השלישי יהיה מתוקן משני מקדשות, ואין מחלוקת בין רש\"י ותוס' ובין הרמב\"ם ז\"ל, אלא שהרמב\"ם מדבר על המקדש החומרי שהוא יבנה במקומו על ידי מלך המשיח במצות השם ב\"ה. ורש\"י והתוספות מדברים על המקדש הרוחני שנעשה ביד ה', שעליו נאמר מקדש ה' כוננו ידיך, והוא ירד בנוי ומשוכלל מן השמים. ויתלבש תוך המקדש הגשמי.","b":false},{"t":"ומעתה אבא להסביר יפה את מאמר הגמרא (ב\"ק ס' ע\"ב) כי תצא אש וגו' שלם ישלם המבעיר את הבערה, אמר הקב\"ה עלי לשלם את הבערה שהבערתי, אני הצתי אש בציון שנאמר, ויצת אש בציון ותאכל יסודותיה. (איכה ד', י\"א) ואני עתיד לבנותה באש, שנאמר, ואני אהיה לה חומת אש סביב ולכבוד אהיה בתוכה. (זכריה ב, ט).","b":false},{"t":"וצ\"ל פשר הענין שכאן אומר הנביא זכריה ע\"ה, ואני אהיה לה חומת אש סביב וגו'. ובגמרא אמרו, אני הצתי אש וכו', ואני עתיד לבנותה באש. ושלזה מכוין הפסוק שלם ישלם המבעיר את הבערה. וכן מהזהר (בראשית דף כ\"ח ע\"א) הנ\"ל משמע שה' יבנה ביהמ\"ק השלישי באש, ודרשו מאותו פסוק של הנביא זכריה הנז' בגמ'. שאמר הקב\"ה, אני הצתי אש בציון שנאמר ויצת אש בציון וגו', ואני עתיד לבנותה באש, שנאמר ואני אהיה לה חומת אש סביב, ולכבוד אהיה בתוכה. (זכריה ב', ט'). ולכאורה גמרא זו שקלא ואזלא כשיטת רש\"י ותוספות שירד מקדש בנוי ומשוכלל מן השמים, וזה אומרו ואני עתיד לבנותה באש. ומשמע שלא אנחנו בונים את ביהמ\"ק אלא הקב\"ה בונה אותה. ומה שאמר באש, הכונה באש רוחנית שאין בה גשמיות. ולכאורה קשה על הרמב\"ם ז\"ל.","b":false},{"t":"ונראה בס\"ד דלא קשה מידי, דהכי קאמר שבאמת עם ישראל ובראשם מלך המשיח הם יבנו את בית המקדש בחומרים גשמיים, כמו שבנה משה רבנו ובני ישראל את המשכן. והקב\"ה ישתבח שמו ישלים הבניין הזה באש שלו כדי שיתוקן ויושלם שיהיה ראוי להשראת השכינה, וזה שאמר ואני עתיד לבנותה באש, כלומר אני עתיד לבנות את ביהמ\"ק הרוחני שכולו אש, שנאמר ואני אהיה לה חומת אש סביב, כדי להקיפה באש העליונה שכולה רוחנית, ושמא תאמר שזה יהיה רק סביב מבחוץ ולא מבפנים, לזה המשיך הנביא ואמר, ולכבוד אהיה בתוכה. נמצא שיש בזה אור מקיף וגם אור פנימי, וא\"כ אין כאן שלילת בנין הבית השלישי על ידינו. אלא מדבר על החלק הרוחני של הבית שהוא חלקו של הקב\"ה בבנין הבית, שהוא יכין המצע הרוחני עליו ישכון כבוד השם, כאשר היה ברדת השם על הר סיני, וכנ\"ל. ולזה אמר, אני אהיה לה חומת אש סביב, כלומר אתם תבנו ואני אקיף אותה בחומת אש מלמעלה, סביב לכל הבית, וגם זאת אעשה: ולכבוד אהיה בתוכה, שזה המצע להשראת שכינה ממש.","b":false},{"t":"ויהיה הבית שיבנה על ידנו דמות הגוף, ובו יתן הקב\"ה הבית של האש העליונה, דוגמת הנשמה שנפח בקרב האדם הגשמי.","b":false},{"t":"וכן אפשר שהקב\"ה בונה מקדש זה מספירינון, כמעשה הלוחות שעשה מספירינון שתחת כסא כבודו וכנ\"ל. שבזהר הקדוש (פקודי ר\"מ ע\"א) הנ\"ל, נאמר: ועל דא זמין קוב\"ה למבני יסודי ירושלים מיסודין אחרנין וכו', ומאן אינון ספירין. דכתיב, ויסדתיך בספירים (ישעיהו נ\"ד) ע\"ש. ואולי ספירים אלו הם ספירינון הנזכרים גבי לוחות, וכן אמר הפסוק ותחת רגליו כלבנת הספיר. וצ\"ע בזה.","b":false},{"t":"יא. והנה בבין המצרים אמרתי שיעור לרבני ישראל בכינוס שהתקיים בשבת, ודברתי בענין זה בעה\"ו ומעלת הרה\"ג רבי משה הבלין שליט\"א רבה של קרית גת, אמר לי שבנקודה זו שיהיו ב' בתי מקדש אחד תוך השני, כבר כתב כן האדמו\"ר מחב\"ד ע\"ה וזיע\"א, ושלח לי צילום מספר הלכות בית הבחירה להרמב\"ם ז\"ל עם חידושים וביאורים מכ\"ק האדמו\"ר זיע\"א, (ובסימן י\"ט סעיף ב') ד\"ה וי\"ל, כתב: וי\"ל שבנין ביהמ\"ק דלעתיד תלוי בשני האופנים הנ\"ל, שבגאולה, זכו, יגלה ויבא מן השמים. לא זכו, יהיה הבנין בידי אדם. (ע\"י משיח). עו\"כ. ובעומק יותר הפירוש בזה וכו', והמצב של זכו פועל שתהיה הוספה, שבתוך המקדש שלמטה יבא ויתלבש המקדש דלמעלה, ויבא ויגלה מן השמים. עכ\"ל. עו\"כ שם (בסימן א' ס\"ו) וז\"ל וי\"ל שכשם שהוא בנוגע ללימוד וכו', ידוע שבאופן בנין ביהמ\"ק דלעתיד, ישנן שתי דעות וכו', עו\"כ להלן: או באופן אחר, בנין הבית למטה יהיה בידי אדם – ע\"י משיח וכו', ובמקדש זה שלמטה \"יתלבש\" המקדש שלמעלה. ובדוגמת ועל דרך, האש שלמעלה שנתלבשה באש שלמטה, שמצוה להביא מן ההדיוט. שזה יביא הנצחיות בהבנין דלעתיד.","b":false},{"t":"עו\"כ, ובזה מוסבר טעם השינוי והחילוק שבין ב' הדעות הנ\"ל. דעת הרמב\"ם שמשיח יבנה את המקדש וכו' (וע\"ש שמפרש שהרמב\"ם ז\"ל הוא ספר הלכות ומדגיש הבנין שע\"י ישראל. אבל המדרש והזהר מדברים, על השלמות של ביהמ\"ק דלעתיד, וע\"ש באורך ותרוה נחת). עכ\"ל. ושמחתי שמחה גדולה, שהגם שביססתי את החידוש שיש ב' בתי מקדש זה מלביש לזה וכנ\"ל, עדיין היה לבי נוקפי לחדש חידוש כ\"כ גדול, ועתה ששתי על זה כמוצא שלל רב, שבחסדי ה' ברוך הוא כיונתי לדעתו הגדולה של האדמו\"ר זיע\"א.","b":false},{"t":"ואולם יש מעט הבדל בין מה שכתב האדמו\"ר ע\"ה ובין מה שכתבתי בעניותי, שהוא ע\"ה תלה ענין זה והצורך שיהיה הבית מקדש שלמעלה מולבש תוך ביהמ\"ק שלמטה, כדי שזה יביא הנצחיות בהבנין דלעתיד. שזה לשונו בסוף סימן א' ס\"ו הנ\"ל. וכונתו פשוטה לפניה, שאין אפשרות שיהיה נצחי אם זה בנין שבנו אותו בני אדם אשר חומר יסודם, אבל בהתלבש בו הבנין שלמעלה שכולו רוחני, זה ינציח את זה. ואולם אני הגעתי לזה מנקודה אחרת, שכתבתי שאי אפשר לשכינה לשרות על דבר גשמי בשום פנים, והוכחתי את זה בבירור מדברי חז\"ל שבפירש\"י על הפסוק וירד ה' על הר סיני, שהקב\"ה הרכין השמים העליונים והשמים התחתונים והציען על הר סיני וכו', כלומר שבלי מצע זה שהוא כולו רוחני שמים עליונים ותחתונים, לא היתה השכינה יורדת על הר סיני. וכנ\"ל. ואשר ע\"כ אי אפשר שתשרה שכינה על בנין של בשר ודם שהוא בנוי מחומר גשמי, וע\"כ הלביש בתוכו את המקדש השמימי אשר כולו רוחניות והוא המצע שעליו שורה השכינה. וכמו שביארתי לעיל באר היטב בעה\"ו.","b":false},{"t":"ויהי אחר הדברים האלה זיכני הקב\"ה עוד וראיתי בצילום מספר שבילי המקדש (סימן י\"ב עמוד קנ\"ו) שהביא דברי הגאון ערוך לנר (על מסכת סוכה מ\"א), שהקשה על פירש\"י ז\"ל שכתב שביהמ\"ק השלישי ירד בנוי מן השמים, א\"כ היה צריך לומר, (בגמרא שם) מהרה יגלה המקדש, ולא יבנה ע\"ש. וכתב: ולכן היה נראה לע\"ד דודאי בית המקדש שלעתיד לבא יבנה בנין ממש בידי אדם, ומה שנאמר מקדש ה' כוננו ידיך, שנדרש בתנחומא שירד למטה, הוא בית מקדש רוחני שיבא לתוך בית המקדש הנבנה גשמי, כנשמה תוך הגוף. וכמו שירד במשכן ובבית המקדש, האש של מעלה תוך האש של ההדיוט שנבער בעצים. וכן במכילתא שבית המקדש של מעלה מכוון כנגד בית המקדש של מטה, ועל זה קאמר, מקדש ה' כוננו ידיך. וכו'. עכ\"ל.","b":false},{"t":"ושמחתי עוד שהדברים מכוונים כדברי גאון נודע בישראל בעל ערוך לנר ע\"ה. שבח לא-ל. ובעניותי כבר הבאתי הוכחות רבות לזה, וגם שכבר פירשתי כן בלוחות על אותו רעיון ממש, וכנ\"ל. והוכחתי מרבי סימון שבמדרש רבה, שגם במשכן שבנו משה ובני ישראל כן היה, ושעל כן נאמר ושכנתי בתוכם, תוך שתי המקדשות.","b":false},{"t":"י\"ב. ובזה אבא לפרש בחסדי ה' דבר חדש, במה שאומרים בתפלת העמידה של שלש רגלים, והראנו בבנינו, ושמחנו בתיקונו. ועיין בדברי יציב הנ\"ל בסוף הסימן מה שפירש בזה, ולפני כארבעים שנה שמעתי מפי גדול דורנו מרן הראש\"ל בעל יבי\"א שליט\"א (איני יודע אם משלו או מפי ספרים) שפירש את זה עפ\"י שיטת רש\"י ותוס', שביהמ\"ק ירד בנוי מן השמים. שלזה אמר והראנו בבנינו, שאין לאדם שמחה אלא במה שהוא עושה בידיו, וזה שירד בנוי אין לנו בו שמחה כל כך, שאין בזה חדות יצירה שלא עמלנו בבנינו. רק והראנו בבנינו. אבל הקב\"ה משמח אותנו שמניח לנו לעשות בו כמה תיקונים, והיא שמחתנו. ע\"כ אומרים, ושמחנו בתיקונו. וש\"י.","b":false},{"t":"ולפי המהלך דלעיל יש לפרש בדרך אחרת והראנו בבנינו, קאי על הבית מקדש שאנו בונים עם מלך המשיח, את זה יכולים אנו לראות עין בעין, שכן הוא חומרי ויש כוח בעין לראותו. אבל הבית שיורד מן השמים הוא רוחני כולו ואין כוח בעין החומרית לראותו, ע\"כ תיבת \"והראנו\", אבל הבית הרוחני שיורד מן השמים ושהוא תיקונו של ביהמ\"ק, שבלעדיו אין השראת שכינה כלל וכנ\"ל, ובו נאמר \"ושמחנו בתיקונו\". שאי אפשר לראותו, אבל ברור לנו שהוא ירד מוכן מן השמים ועל ידו יש השראת השכינה, ואנו שמחים בו שמחת עולם. אך לא רואים אותו ראיית עין, רק יודעים שהוא ירד ותיקן לביהמ\"ק, וע\"כ מתפללים, ושמחנו בתיקונו, יראו עינינו וישמח לבנו, יראו עינינו הבימ\"ק החומרי והשכינה השורה בו, וישמח לבנו בתיקונו, שהוא המקדש הרוחני שמלובש בתוכו ומתקנו.","b":false},{"t":"ועינינו לי-ה ולי-ה נשואות להחיש גאולתנו ופדות נפשנו בישועה ורחמים בשובה ונחת נושעה בב\"א.","b":false},{"t":"המצפה לישועת ה' על עמנו ועל נחלת אבותינו.","b":false},{"t":"ע\"ה שלמה משה עמאר","b":false},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"נ\"ט בר נ\"ט דמותר לעשותו לכתחילה","p":[{"t":"בעהית\"ש. בששי בשבת שמנה ועשרים יום בשבט התשס\"ז. בא סימן ואלה המשפטים אשר תשים לפניהם (מתוך אגרת ברכה לספר דרכי אי\"ש לאיש טבריה הגאון המובהק רבי יוסף שמואל אבואלעפייא זצ\"ל אשר חי ופעל בערי מרוקו ומנוחתו כבוד שם).","b":false},{"t":"מדי עוברי בין דברי הגאון המחבר זצ\"ל ראיתי לו בעניני יו\"ד (והוא בסימן ו') והוא פסק שכתב המחבר בעיר מוגאדור במרוקו וכתבה להרב הגאון רבה דעמיה וכו' כמוהר\"ר יוסף אלמאליח ע\"ה, שדן במאני דחספא דשתו בהו בצפרא חלב רותח, ורוצים לשתות בהם קפה או תה אחר סעודה של בשר ועוף. ופלפל והאריך הרחיב בדברי הפוסקים כיד ה' הטובה עליו, באורך גדול, ושם (עמוד ס\"ג) כתב ודעדיפא מינה אמינא וכו', ושם דן בדין נ\"ט בר נ\"ט, והביא דעת סמ\"ק ורבינו ירוחם והגהמי\"י דאוסרים לכתחילה נ\"ט בר נ\"ט, והיינו שלא לבשל בכלי שבישלו בו בשר, על דעת לאכול את זה עם חלב, וא\"כ גם בזה לדידהו, לא שפיר דמי לבשל תה או קפה בכלי חלבי כדי לשתות בהם בתוך סעודה בשרית. עו\"כ, ברם הא חזינן למרן (סימן צ\"ט) שהביא דבריהם וכתב, אבל בעל התרומות וכו', ורואים שפוסק כבעה\"ת דשרי גם לכתחילה לבשל ולהעלות דגים בכלי בשרי, ע\"מ לאוכלו עם חלב, וע\"ש שכתב להוכיח מהתוס' והרא\"ש ז\"ל והר\"ן ז\"ל ושאר ראשונים שהקשו מפסחים (ל') דאין טשין את התנור, והוכיח דס\"ל להתיר נ\"ט בר נ\"ט גם לכתחילה, כדעת בעה\"ת, עוד הביא ראיה ממ\"ש הרא\"ש ז\"ל (פסחים פ\"ב סימן ז') שכתב, ובערב פסח קודם שעה חמישית מותר להגעיל אפילו בן יומו, דהוי נ\"ט בר נ\"ט, והוי כמו דגים שעלו בקערה, ואם נ\"ט בר נ\"ט אסור לכתחילה, היכי שרי להגעיל לכתחילה, ואיך מדמה לדגים, דבהם עצמם אסור לכתחילה, א\"ו דפשיטא ליה שגם לכתחילה שרי כדעת בעה\"ת, וזו היא דעת מרן ז\"ל.","b":false},{"t":"ודברי הרא\"ש ז\"ל הנז' מוסכמים מכל הפוסקים, וכ\"פ מרן ז\"ל בא\"ח (סימן תנ\"ב ס\"א). וע\"ש דבזה ארווח לן, דבב\"י הסיק כבעה\"ת, ובשו\"ע סתם דבריו, ולא ידענא מה דעתו, איברא דכל כהאי, מילתא דפשיטא היא שגם בשו\"ע זה דעתו, ועוד דבבדק הבית דבתראה הוא, שהביא החילוק שבין לכתחילה ובין דיעבד משם רבינו ירוחם, וכתב עליו דלא נהירין ליה אלא גם לכתחילה נמי שרי, ומסתמא שכן דעתו גם בשו\"ע, וע\"ש ואח\"כ כתב בזה\"ל, סופא דמילתא, בהא סלקינן ובהא נחתינן דדעתיה דמרנא לאשרויי נ\"ט בר נ\"ט לכתחילה, ומהי תיתי למימר דבשו\"ע הדר ביה. עכ\"ל.","b":false},{"t":"עוד תמה על הש\"ך שם (סק\"ג) שכתב, והמנהג לאסור לכתחילה לאוכלו בכותח, אבל לבשלם לכתחילה בקדרה של בשר כדי לאוכלם בכותח אסור אפילו להמחבר וסיעתו, ואייתי מהסמ\"ק וכו' ע\"ש. ותמה עליו איך כתב שגם להמחבר אסור, והרי בבדק הבית הכריע בפירוש להתיר, ועוד שבב\"י עצמו ג\"כ הכריע דלא כהסמ\"ק והגה\"מ וכנ\"ל.","b":false},{"t":"וכתב שאחרי זה ראה בכנה\"ג (הגהב\"י יו\"ד) דדחי דברי הש\"ך ואותביה מהא דאמרן. וע\"ש עוד מ\"ש בזה.","b":false},{"t":"ולהלן הביא דברי הרב מהר\"א ן' טווא (סי' ל\"ג) דגם הוא פשיטא ליה דנ\"ט בר נ\"ט שרי לכתחילה, ולמד כן מדין דהגעלה הנ\"ל, ושמח ע\"ז, ושוב חזר וכתב (בד\"ה תו חזינן) וז\"ל והשתא ארווח לן שמעתתא דמצינן למימר בפשיטותא דס\"ל למרן דנ\"ט בר נ\"ט שרי לכתחילה, מדין ההגעלה. וכו'. ושו\"כ לדחות הראיה מדין הגעלה דש\"ה שיש ג' נ\"ט, החמץ בכלי, והכלי במים, והמים בלי, ושלשתם להיתר, ושכ\"כ המג\"א (סימן תמ\"ז סק\"א) וע\"ש שנו\"נ באורך בזה, ומול סוף (ד\"ה ותו אנא חזינא) הביא דברי מהר\"י עייאש ז\"ל בספר מטה יהודה שהביא משם זקנו של הרב המחבר מהר\"ח אבולעפיא ז\"ל (נשיא ומיסד העיר טבריה) בספרו מקראי קדש, וכ' דיש לדון בדבריו. וע\"ש שכתב שהיה קשה לו להשלים כי אין הספרים עמו, והיה טרוד לעבור ממוגאדור לטאנזיר. ולא נמצאו סיום הדברים, מ\"מ ברור שהוא ז\"ל מכריע בדעת מרן ז\"ל דנ\"ט בר נ\"ט מותר לכתחילה, וכבר הארכתי בזה מאד בספרי הקטן שו\"ת שמע שלמה ח\"א (חיו\"ד סימן ב') שכתבתי לדחות דברי מו\"ר הגאון הגדול מוהר\"ש משאש זצ\"ל, והוא חזר וכתב בענוותו לדחות את דברי, והבאתי דבריו בשו\"ת שמע שלמה ח\"ג (חיו\"ד סימן ד') ובסימן ה' שם שבתי לקיים דברי, וע\"ש עוד בסימן ו' שהגאון זצ\"ל חזר וכתב לקיים דברו שהוא סובר בדעת מרן ז\"ל שאסור לגרום נ\"ט בר נ\"ט לכתחילה, ובהסכמה שכתב לי מרן הראש\"ל נשיא החכמים רבינו עובדיה יוסף שליט\"א התייחס לזה והצדיק את מה שכתבתי בעניי שדעת מרן ז\"ל ברורה שמותר לכתחילה לבשל ירק או שאר דברים בכלי שבישלו בו בשר, אפילו הוא בן יומו, רק שיהיה נקי לגמרי, כדי לאוכלם עם חלב, והאריך להוכיח כן כיד ה' הטובה עליו. ע\"ש. והנה עתה יש עוד סיוע מפי הספר הקדוש הזה שגם הוא ז\"ל מיפשט פשיטא ליה שלדעת מרן מותר נ\"ט בר נ\"ט לכתחילה, וכבר כתבתי שם שכן היה נהוג בחלב עפ\"י דעת מרן ז\"ל.","b":false},{"t":"המצפה לישועת ה' על עמנו ועל נחלת אבותינו בישועה וברחמים","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"עגונה שנחטף בעלה ע\"י מחבלים","p":[{"t":"בעהית\"ש, בששי בשבת שלשה ועשרים יום לאדר א' התשס\"ה, רומא - איטליה","b":false},{"t":"פנה אלינו מר מ. ג. נ\"י, על פרשה עגומה ומצערת, בדבר בירור מעמדה של אמו תחי', כי אביו מר ס. ג. שהיה מנהל את הקהילה היהודית בביירות שבלבנון, וסייע בידי רבים לעלות ארצה לשלום, נחטף ע\"י אירגוני מחבלים הקשורים עם הסורים, בשנת 1984, ומאז נעלם ועקבותיו לא נודעו.","b":false},{"t":"המקרה מטופל ע\"י הגורמים הבטחונים המתאימים במשרד ראש הממשלה. והם הודיעו לבני המשפחה שניתן להכריז על האב כהרוג מלכות, דבר שיביא לשיפור ניכר במצב הכלכלי של המשפחה.","b":false},{"t":"אשת הנעדר כבר הוכרה ע\"י הרה\"ר לישראל כאשה עגונה, ואמנם היא מתקשה לחתום על הצהרה שאינו בין החיים מפני שאין בידה פסק הלכה, ומבקשים להורות להם דרך בבעיא ההלכתית והמוסרית הזאת.","b":false},{"t":"כמו\"כ הוגש לנו מכתב מלשכת ראש המוסד, מיום כ\"ט מרחשון תש\"ס שתוכנו הוא: חטיפתו של ס. ג. ידועה להם מזה שנים רבות, הוא היה מסייע בעליית יהודים לא\"י, אך לא היה בקשר עמם. לפי ידיעתם הוא גוייס ליחידת איסוף צהלי\"ת בשנות ה-50, ובשלב מסויים הופסקה עבודתו מפני שהוא יהודי. בשנת 82 ביקר בא\"י וביקש לעבוד עמם, אך סורב.","b":false},{"t":"ומזה כמה שנים המוסד בקשר עם הרעיה והבן משה יבלחט\"א. ובהמלצתם היא הוכרה כאסירת ציון (בזכות עצמה, כי גם היא פעלה רבות וגם נאסרה שם על פעילותה למען א\"י), וסירבה להצעת המוסד להכריז עליו כהרוג מלכות. דבר שיכול לזכותה בתנאים סוציאלים משופרים.","b":false},{"t":"עוד כתבו שלקחו מבני המשפחה בדיקות דם (שׂA), כדי לשמרם במאגר לעת מצא, וכן המליצו להעלות את עניינו בכל מסגרת שיחות עם לבנון, סוריה וחיזבאללה. ע\"כ.","b":false},{"t":"ביום א' ניסן התשס\"ד קיבלו מכתב מיועץ ראה\"מ, שעניינם מטופל בכל הדרכים האפשריים, אך לע\"ע אין בידם מידע נוסף.","b":false},{"t":"אחר הדברים הנ\"ל הקמתי בית דין מיוחד בו ישבו יחד עמי, חבר ביה\"ד הגדול הגר\"ש דיכובסקי שליט\"א, והרה\"ר לצה\"ל תא\"ל הרה\"ג רי\"מ וייס שליט\"א, כדי לחקור בענין.","b":false},{"t":"הישיבה הראשונה התקיימה ביום שני ב' כסלו התשס\"ה, בפתיחת הישיבה נמסרה סקירה מקפת של כל המידע שיש עד היום ע\"י הרה\"ר לצה\"ל שליט\"א, אשר טרח ואסף חומר בענין זה. ממקורות שונים ומפי גורמים רבים ורחוקים.","b":false},{"t":"בנוסף למה שכבר כתבתי, הוסיף הרב וייס שליט\"א שלפי נתונים שלוקטו ע\"י אנשי המוסד, הרי שבשנות התש\"ן (1980), היו בלבנון גלי חטיפות, בס\"ה היו אחד עשרה חטופים. וידוע שארבעה מהם הובאו לקבורה, כמו\"כ פורסם ששבעה הוצאו להורג, אך מקום קבורתם לא נודע, לששה מהם אין שארים בארץ, וע\"כ אין להם דורש והשביעי הוא מר ג', שבני משפחתו דורשים את עניינו. ולפי השערות והערכות המוסד, ועפ\"י היכרותם את התנהלות הסורים בלבנון, נראה שהאיש נרצח זמן קצר לאחר חטיפתו, עוד צויין שבכל המו\"מ להחלפת שבויים בעשרים השנים האחרונות, הלבנונים לא העלו נושא זה, וזה מעיד שאין הם יודעים דבר על מקום קבורת החללים.","b":false},{"t":"מסקנתם המקצועית של אנשי המוסד היא זו שהביאתם להציע לאשת הנעדר לקבל על עצמה את ההכרה שבעלה \"הרוג מלכות\". באותו יום הופיע הבן מ. והודיע שאמו נאותה לקבל את הצעת המוסד להכיר בה כאשתו של הרוג מלכות. והדגיש שאין לה כל כונה להנשא ולא דורשת מאתנו היתר נישואין, כי אם ההכרה הנ\"ל שיש בה כדי לקבל זכויות מן המדינה.","b":false},{"t":"הבן הנ\"ל היה קטן בעת חטיפת אביו, אך מן הסיפורים הידועים בבית בעיקר מן האם. עולה שהאב נחטף שבע פעמים, ואח\"כ חזר לביתו שלם, אך בפעם האחרונה נחטף ולא שב עוד, וסיפר שגויים שכנים ראו בעיניהם את החטיפה ואומרים שיש ארגון סורי שעובד בלבנון ושמם \"חומזי קומי סורי\", והם שחטפוהו.","b":false},{"t":"עוד סיפר הבן מ. שאמו סיפרה שיום אחד קודם החטיפה, באו אנשים הביתה וביקשו לדבר אתו, והיא אמרה להם שהוא לא מרגיש טוב וישובו למחר. ולמחרת כשיצא מהבית עשה תנועת שלום שלא כהרגלו, והלך למשרדו, ומשם נחטף.","b":false},{"t":"אחר ששמענו את דברי הבן וראינו שכל דבריו הם מפי האם, החלטנו לקיים ישיבה נוספת, ובה נשמע את דברי האם.","b":false},{"t":"וביום שני כ\"ט טבת התשס\"ה, התקיימה הישיבה השניה של ביה\"ד הנ\"ל. (אלא שהגר\"ש דיכובסקי שליט\"א לא יכל להגיע לישיבה, וצירפנו את הרה\"ר ליהדות אתיופיה הר\"י הדאנה שליט\"א לאותה ישיבה).","b":false},{"t":"הופיעה האם ובנה משה וגם הבן הצעיר שלום, ועמם הופיע חבר הכנסת לשעבר מר י. כ. שהיה יו\"ר הועדה לשירותים חשאיים, שגם יש לו קירבה משפחתית לאשת הנעדר (היא אחות גיסו), ובדבריו חזר ואישר את כל האמור לעיל בהרחבה.","b":false},{"t":"לפי השאלות השיבה האשה, שס. היה בעלה הראשון והיחיד והתחתנו בשנת 1997 בבירות ע\"י חכם שאול שרים ז\"ל, (שכיהן לאחר מכן כרב בסאן פאולו ברזיל). ויש להם שלשה ילדים, היא ילידת דמשק וברחה לבירות, בעלה עסק בעניני בגדים, והרבה שנים לפני נישואיהם הוא עבד עם ישראל, לה לא היה הדבר ידוע, אך ראתה שנכנסים ומדברים עמו בהסתר, וכן במלחמת של\"ג היו נכנסים קצינים לבית ודיברו עמו. והוא לא רצה לעזוב את ביירות משום דאגתו לקהלה שם, ולארבעים ושנים ס\"ת שהיו שם.","b":false},{"t":"עוד סיפרה שבעלה היה בארץ בשנת 84-82 והיא נשארה בביירות. הבן הקטן – ש. היה בן שש שנים בהעלמו של אביו.","b":false},{"t":"לשאלה סיפרה, שהחוטפים נכנסו למשרדי הקהלה שע\"י ביהכ\"נ בביירות ואיימו עליו באקדח והכניסוהו למכונית וולקסווגן, כך סיפרו לה שכנים נאמנים, בתוך הדברים הגיע שם הבן הגדול מ. ואמר לו אביו שישחק בחוץ וכשנכנס אח\"כ מצא את המשרד הפוך ומבולגן, והאשה המתינה, והלכה למשטרה ופתחו תיק, בינתיים קרעה ואיבדה את כל המסמכים המחשידים, ואומרת שאחרי זה ביקשו ממנה את כל הדרכונים שלו. וכן ביקשו כופר בסך 100 אלף דולר או 50,000. כאמור כל זה בחטיפה האחרונה שממנה לא שב עוד, אבל לפני חתונתו נחטף פעמים רבות. עוד סיפרה שלימים דרשו ממנה אנשי חיזבאללה את הבן הגדול כעיסקת חליפין תמורת בעלה, ודחתה את הצעתם על הסף.","b":false},{"t":"הבנים ציינו שאמם בהיותה בלבנון היתה חזקה ואמיצה, וכאן עבר עליה מהפך נפשי וכמעט לא מדברת בזה. האשה מוכרת כאסירת ציון (בזכות עצמה), ומבקשת שיכירו בה כאשתו של הרוג מלכות.","b":false},{"t":"באותו יום הופיע גם ידיד המשפחה ה\"ר שלמה זיתוני נ\"י ואמר שתפקידו של ס. היה, מזכיר הקהילה, וזה שקדם לו בתפקיד נחטף ונהרג, והוכר ע\"י המדינה כהרוג מלכות.","b":false},{"t":"עוד סיפרה אשת הנעדר, שהיו ארבעה שנחטפו ונהרגו, וזרקו את גופותיהם על פתח ביתה, ובמו ידיה קברה אותם, ובזה מילאה את מקום בעלה הנעלם.","b":false},{"t":"שאלתי אותה להרגשת הלב שלה, והיתה מתקשה להשיב, ואמרה אני פוחדת להוציא מן הפה מה שהלב חושש. והוסיפה ראיתי בעיני מה עלה בגורל החטופים, ואני חוששת שזה גורל בעלי. והבן מ. אמר, המשפחה רוצה בכיוון של הכרזה כהרוג מלכות, אך אנו פוחדים שהכרזה כזו תגרום שהמוסדות המוסמכים יפסיקו את החיפושים אחריו.","b":false},{"t":"הר' שלמה זיתוני הוסיף, שבזמן מלחמת של\"ג, שירת כקצין קישור בין הקהלה הלבנונית ובין צה\"ל, וס. היה מזכיר הקהילה בעת ההיא, ובפסח שאחר מלחמת של\"ג הגיע ארצה והיה בביהכ\"נ שלהם בחולון, ובשנת 84 הגיעה השמועה ע\"י אחיותיו (בבת ים), שהוא נחטף, ובביכ\"נ שלו אמרו שעבד עם המוסד, וגם החטיפות הקודמות היו על רקע זה שסייע ליהודים להבריחם ארצה. ומדגיש שמאז שנחטף לא נשמע ממנו כל זכר או סימן חיות כלל ועיקר.","b":false},{"t":"עוד אמר שבירר ביחידה הסודית שהיא יחידית ביצירת קשר כל שהוא, ואמרו שמעולם לא היה שום קשר אתו, וכבר עברו למעלה מעשרים שנה ואין קול ואין עונה.","b":false},{"t":"ע\"כ דברי הצדדים, והעדים, והחומר שנתקבל ממשרדי הממשלה.","b":false},{"t":"והנה ברור לכו\"ע שהאיש נחטף ע\"י כת של מחבלים מלבנון, שכל המגיע לידם אחת דתו להמית רח\"ל, וזה דרכם כסל למו, להרוג ולשפוך דם נקיים בלא הבחנה, ומתפארים הם באכזריותם, וככל שמרבים לשפוך דם, הרי זה שבחם ותפארתם, והדברים ידועים ומפורסמים בכל העולם, והם עצמם מכריזים ע\"ז בכל עוז, וראינו באחרונה בשלשת הארונות שהשיבו לא\"י אשר במשך שנים רבות, לא גילו כלל שכבר הרגו אותם, והשאירו את משפחותיהם תלויים ועומדים במצב נורא בחוסר ידע מוחלט, ואינם יודעים אם להתאבל או להתפלל, ועד הרגע האחרון ממש עדיין היו מלאים בספקות וספיקי ספיקות ביגון ובמרר. וקל וחומר בזה שכבר הוזהר על ידם כמה פעמים שהושב מהחטיפות הקודמות, וכנראה שלא רצו למצות אתו את דינם מיד משום שהיה מזכיר הקהלה היהודית שם, ולא רצו לעמוד בביקורת בינלאומית קשה. אך בחטיפה זו נראה שגמרו אומר לחסלו, ובפרט שכבר עברו למעלה מעשרים שנה, ולא נזכר ולא נרמז כלל בשום אפשרות שבעולם, נראה ברור דאינו עוד בין החיים.","b":false},{"t":"א.","b":false},{"t":"מי שודאי סופו למות אי מעידין עליו ובאיזה אופנים.","b":true},{"t":"והנה בשו\"ע אהע\"ז (סימן י\"ז סעיף כ\"ט), כתוב, אין מעידין עליו אלא כשראוהו שמת ודאי ואין בו ספק, כיצד ראוהו שנפל לגוב של אריות ונמרים וכיוצ\"ב אין מעידין עליו, שמא לא היו רעבים ולא אכלוהו, אבל אם נפל לחפירת נחשים ועקרבים מעידין עליו, מפני שע\"י שדוחקן כשעומד עליהן, מזיקין אותו. עכ\"ל. והוא מברייתא ביבמות (קכ\"א ע\"א).","b":false},{"t":"ובאוה\"פ שם (ס\"ק רמ\"ה אות ב'), דנו בדברי הפוסקים, אי בעינן שהחפירה תהיה מלאה נחשים, או אפילו שאינה מלאה. וכן דנו שם (אות ג'), אי בעינן שתהיה עמוקה, ומדבריהם עולה, שכל שהענין ברור שימות מאותה נפילה מעידין עליו, אבל כשאין הענין ברור כגון גוב אריות אין מעידין עליו.","b":false},{"t":"עוד אמרו שם בשו\"ע (סעיף ל'), נפל לתוך כבשן האש, או לתוך יורה רותחת מלאה יין או שמן או מים וכו', מעידים עליו שמת שודאי סופו למות, וכן כל כיוצא בזה מדברים שא\"א שיחיה אלא ימות מיד בזמן קרוב, הרי אלו מעידין עליו.","b":false},{"t":"והח\"מ וב\"ש שם (ס\"ק צ\"א), כתבו דזה דלא כהירושלמי (פט\"ז דיבמות ה\"ג), שהובא בתוס' (יבמות קכ\"א ע\"ב, ד\"ה אין), שאמרו אפילו נפל לכבשן האש אין מעידין עליו שמא נעשו לו נסים כחנניה מישאל ועזריה, וגם בהגהמ\"י כתב ע\"ד הרמב\"ם ז\"ל, דהיינו שלא כהירושלמי, ונמצא דלתלמוד דידן אין חוששין למעשה נסים, ועיי\"ש בבאה\"ט (ס\"ק צ\"ד), שהבנימין זאב פסק כהירושלמי אך באוה\"פ שם (סעי' ל' ס\"ק רמ\"ח אות א'), כתבו דלא נמצא כן בבנימין זאב, ואדרבה נמצא שם (סימן כ\"א וכ\"ו), דאנן סמכינן אתלמודא דידן דלא חיישינן למעשה נסים, ושגם בעצי ארזים (ס\"ק קכ\"ה), תמה ע\"ז. וע\"ש עוד מ\"ש בזה, הבאתים בשו\"ת שמע שלמה ח\"ה (חאהע\"ז סימן ט\"ז אות ד'), דכה\"פ פוסקים בזה כהבבלי דלא חיישינן למעשה נסים. (וע\"ע בשמע שלמה שם או' ו'). ובסוף אות ז' הבאתי דברי החזו\"א (סימן נ\"ב אות ז'), דאין למסור כלל בזה אלא הכל לפי ראות עיני הדיין. וע\"ש עוד מ\"ש בזה.","b":false},{"t":"וכאן שהוברר בבירור גמור שהוא נחטף, וכמו שסיפרו לה השכנים בדרך מסל\"ת את כל פרטי הענין, איך נכנסו ואיך לקחו אותו, וכן עולה מאותם נסיונות שנעשו ע\"י אותם כתות שביקשו מאשתו, את בנה הגדול וכן ממון רב. וכנ\"ל.","b":false},{"t":"ב.","b":false},{"t":"מי שנחטף ביד חבלנים שכל מטרתם לשפוך דם נקי מישראל רח\"ל.","b":true},{"t":"והנה החטיפה הזאת בוצעה ע\"י המחבלים בלבנון, הידועים לשמצה באכזריותם ובמעשיהם הנוראים, והם שופכי דמים מפורסמים, וכל באיהם לא ישובון רח\"ל, וקל בעיניהם לשפוך דם נקיים אנשים ונשים וטף, והיא גאותם ותפארתם, וכל המרבה לשפוך דם משובח בעיניהם ונערץ. ואפילו דמי אחיהם קל בעיניהם, וגם על עצמם אינם חסים, שמאבדים עצמם כדי לשפוך דמים של יהודים, ואין דבר יקר להם כמו לשפוך דם יהודים. ולכאורה זה כמו מי שנפל ביורה רותחת וכדומה, שאין מזה שום הצלה, ומעידים עליו להתיר אשתו.","b":false},{"t":"והלום ראיתי בשו\"ת היכל יצחק חאהע\"ז ח\"א (סימן כ\"ד), בדין עגונות של השואה, ודן בזה שהגויים התנפלו עליהם להורגם ושמו אותם בב' קבוצות, האחת לעבודת פרך, והשניה להריגה, וגם מקבוצת העבודה רובם מתו, אך בקבוצה השניה רובא דרובא למיתה שכבר פסקו דינם הרשעים למיתה, ומיהרו להוליכם למקום המיתה, ורק במקרים נדירים מאד ניצל מי שהוא ע\"י קפיצה מהקרון וכדומה.","b":false},{"t":"ג.","b":false},{"t":"כשהתנפלו רוצחים על יהודים, וניצל אחד אם יכול להעיד על חבריו שנהרגו.","b":true},{"t":"והזכיר מ\"ש בשו\"ת נר אהרן (להגאון ר\"א הכהן מטווריג ז\"ל), בעובדא דיליה, שהתנפלו רוצחים על קבוצה של יהודים להורגם, ואחד נצול באופן פלא והוא העיד ע\"ז. אלא שלא ראה את ההריגה, ודן בזה והעלה כלל חדש, דהיכא שהתנפלו רוצחים בכונה רק על עסקי נפשות על יהודים בלתי מזויינים ואין מידם מציל, אעפ\"י שאין עדות על עצם ההריגה של כולם, חזקה שביצעו את זממם, וכאילו ראה את עצם ההריגה של כולם. ועדותו של זה שניצל בדרך נס, מספיקה להתיר את כולם. ע\"כ.","b":false},{"t":"וכתב הרב ז\"ל דדבריו של הגאון הנז' צ\"ע, דביבמות (קט\"ו ע\"א), אבעיא להו החזיקה היא מלחמה בעולם מהו, (אי חיישינן שסומכת על המצב ואומרת בדדמי), ורצו לפשוט מברייתא, נפלו עלינו נכרים, נפלו עלינו לסטים, הוא מת, ואני ניצלתי נאמנת, והרי זו מלחמה ונאמנת, ודחו, התם כדרב אידי דאמר אשה כלי זיינה עליה, וכתב בהיכל יצחק, דהיינו שיסוד הענין שחוששין במלחמה שהיא מפחדת מחצים וכדו', ובורחת ולא עומדת לראות אותו שמת. אבל במלחמה קטנה שנפלו עליהם לסטים דאין בזה חצים דלא באו אלא להרוג יחידים, אינה מפחדת מפני שכלי זיינה עליה.","b":false},{"t":"יוצא דבכה\"ג אין חוששין שתאמר בדדמי משום שכלי זיינה עליה, ואלמלי כן היינו חוששין שתאמר בדדמי גם במלחמה קטנה, ומזה מקשה על הגאון נר אהרן ז\"ל, (שכתב עליו, והנה רב גובריה דהאי גאון אמיתי, ובתשובה אחרת תיארו כגדול הדור), דאם כדבריו אין מקום לכל הדיון הזה. די\"ל דנאמנת משום שנפלו עליהם לסטים, ואפילו שלא ראתה המיתה, מ\"מ נפלו עליהם לסטים שבאו על עסקי נפשות להרוג ולאבד ודי בזה להתירה. שהרי מיעוטא דמיעוטא ניצלים בנסיבות כאלה, ולזה אין חוששין. ובפרט שהיא אומרת בפי' שהוא נהרג. ועוד דיש מהפוסקים דס\"ל דהחשש דאמרה בדדמי הוא רק חשש דרבנן, וע\"כ בדיעבד שנישאת לא תצא. וא\"כ איך רצתה הגמרא לפשוט מזה לענין מלחמה ממש דהחזיקתה היא שתהיה נאמנת, והרי החשש שתאמר בדדמי דרבנן, ועם זה שנפלו לסטים ודאי יש להתירה גם לכתחילה להנשא. (ועיקר קושיתו היא דאפילו בלי שאמרה שנהרג בעלה, יש להתירה בזה שאמרה שלסטים באו עליהם להורגם והיא ניצלה בנס, וכפי שפסק הנר אהרן בעובדא דיליה).","b":false},{"t":"וע\"ש שכתב שאעפי\"כ לא אומר שבטלה דעתו משום קושיא זו, דעדיין י\"ל שההוכחה היא מעצם הלשון שלא אמרו בברייתא תינשא, אלא נאמנת, דמשמע שמחזיקים דבריה לאומרת אמת, ואי ס\"ד דחיישינן שאומרת בדדמי, אעפ\"י שמותרת לינשא משום סברת נר אהרן, הו\"ל למימר תינשא, אבל הברייתא כתבה, נאמנת. ודקדקו מזה דכשהיא החזיקה מלחמה בעולם נאמנת לומר מת בעלה, ולא חיישינן דאמרה בדדמי, אבל לדינא בכה\"ג מותרת להנשא מהטעם שאין שייך להנצל וכמ\"ש הנר אהרן.","b":false},{"t":"ושוב כתב לדחות דאפשר לפרש מ\"ש בברייתא נאמנת, היינו על הנסיבות שקרו, וע\"כ מותרת דהואיל ונאמנת שנפלו עליהם לסטים, ע\"כ לא איכפת לן אם אמרה בדדמי לענין מיתת בעלה. ואיך פשטו מכאן דבהחזיקה מלחמה לא חיישינן שתאמר בדדמי ולא היו צריכים לדחיה דאשה כלי זיינה עליה. עוד כתב דאעפי\"כ אפשר לקיים דברי חכם גדול זה, דאפ\"ל דאה\"נ יכל לדחות כן, אבל היה צריך להאריך ולחלק בין רוב לרוב, וע\"כ קיצר ודחה, דאשה כלי זיינה עליה. עכ\"ד.","b":false},{"t":"ובמחילת כת\"ר מעיקרא לא קשה מידי, דהתם נפלו עליהם לסטים או נכרים, ואפשר דבאו על עסקי ממון דהא רובם שודדים וגזלנים, ולא מדובר בכתות של רוצחים, אלא שהיא אמרה שהרגו את בעלה דגנבים כשנתקלים בהתנגדות, הורגים, וכמ\"ש חז\"ל על ענין גנב הבא במחתרת. וכל הדיון שם אם היא מדייקת, או אומרת בדדמי, דבאמת מצד הלסטים אין מקום להתיר, דבגנבים ושודדים איירי, וכל ההיתר בנוי רק על מה שאמרה שראתה אותו מת.","b":false},{"t":"ואין מזה שום קושיא על הגאון נר אהרן, דאיירי ברוצחים שהתנפלו על עסקי נפשות דוקא, וכמבואר בלשונו להדיא, בזה הוא דאמר דיש להתיר דחזקה שהרגו את כולם, עד כדי שכתב שם, חזקה שביצעו את זממם, וכאילו ראו את ההריגה עצמה של כולם. אבל בסוגיא דגמרא דנפלו עליהם נכרים או ליסטים, בדרך כלל באים על עסקי ממון, ולק\"מ.","b":false},{"t":"עוד ראיתי לו שם (אות ז'), שנדחק לחלק בין ליסטים גויים, לבין ליסטים ישראל, וי\"ל דבגמרא מיירי בליסטים ישראל, וע\"ש שהאריך בזה. ולפי האמור אין צורך לידחק. וע\"ש עוד.","b":false},{"t":"ד.","b":false},{"t":"יש לחלק בין היוצא ליהרג בב\"ד למי שטבע במים שאל\"ס.","b":true},{"t":"וע\"ע שם אות ג', שהקשה מנא ליה להגאון מטווריג ז\"ל, שהתנפלות של גויים שונאי ישראל, שזה עדיף ממים שאין להם סוף, וכתב שהגאון הנז', הקשה על הא דתנן במסכת גיטין (כ\"ח ע\"ב), היוצא ליהרג נותנים עליו חומרי חיים וחומרי מתים, וא\"ר יוסף לא שאנו אלא בב\"ד של ישראל, א\"ד א\"ר יוסף ל\"ש אלא בב\"ד של עכו\"ם, אבל בב\"ד של ישראל כיון דנפק ליה דינא לקטלא קטלי ליה, דלאחר גמר דין לא חזו ליה זכותא. ופירשו התוס' שם, שאעפ\"י שהיה אחד רוכב על סוס וסודרין בידו, ואם מצאו לו זכות היה מניף בסודרין, מ\"מ לא שכיח. נמצא דהטעם שזה מיעוט, ומקשה הרב ז\"ל הרי גם במים שאל\"ס הניצולים המה מעטים, ולמה לא מתירים את אשתו. ואפשר לומר דבנגמר דינו למיתה, הניצולים הם מיעוטא דמיעוטא. [ויש מקום לדון בזה וע\"ש בתחילת דברי היכל יצחק] וכתב שהגאון מטווריג ז\"ל מחלק בין מים שאל\"ס שהרוב למיתה אבל זה רוב התלוי במקרה, ובזה לא מתירים א\"א ברוב זה. אבל אדם העושה פעולה בכונה תחילה, והתחיל בפעולה ועפ\"י הרוב הוא יגמור את הפעולה, הר\"ז רוב חזק ודנים על פיו כאילו ראינו את כל הפעולה, וכ\"נ באלו שהתנפלו עליהם רוצחים להורגם דעפ\"י רוב מבצעים זממם רח\"ל, אפשר להתיר עפ\"י הרוב הזה דרוב אלים הוא. וע\"ש שדן ומפלפל בחילוק זה בכמה מסוגיות הש\"ס, והגאון הנז' הוכיח כדבריו מהרמב\"ם ז\"ל בהל' בכורות (פ\"ד), בלוקח בהמה מהעכו\"ם ספק ביכרה וילדה אצלו, שהוא לבעלים שהמוציא מחברו עליו הראיה, ולמה צ\"ל דהמע\"ה, תיפוק ליה משום רובא דהרוב אינם בכורים. ובע\"כ צ\"ל דאין זה רוב דאוריתא הואיל והוא רוב במקרה, וע\"כ אתו עלה מצד המע\"ה. ובהיכל יצחק שם דן בזה ועל שאר הראיות כיע\"ש וכיד ה' הטובה עליו.","b":false},{"t":"עוד כתב בהיכל יצחק (או' י\"ז), דבחידושו של הגאון הנז', גם ברוב התלוי במקרה, במיעוטא דמיעוטא נחשב רוב מהתורה, וגם במשל\"ס מותרת, אלא שרבנן החמירו בהם, אבל ביוצא מב\"ד לא החמירו.","b":false},{"t":"והגרי\"א הרצוג ז\"ל העיר מהתוס' (יבמות ל\"ו ע\"ב ד\"ה הא לא שהה), דבטעם הראשון כתב שכן החמירו במשאל\"ס משום דהוי מיעוט המצוי, ושוב הביא דברי מהרי\"ל דיסקין ז\"ל, שכתב דאמנם רחוק מאד שינצלו, אלא כונת התוס' דשכיח שהספינות טובעות בפרט בימיהם שהיו שוהות זמן רב בים ומפליגות בכוח הרוח, אבל שבית הדין דנים למיתה לא שכיח, שסנהד' ההורגת א' לע' שנה נקראת קטלנית. (ודבריו בס' תורת אהל משה דף י\"ב).","b":false},{"t":"ה.","b":false},{"t":"אלה שהיו בשואה הנוראה אי חשיבי כמי שיצא גמר דינם ליהרג בב\"ד.","b":true},{"t":"עוד כתב הגריא\"ה הרצוג ז\"ל שבענין השואה גם בלי חידושו של הגאון מטווריג ז\"ל, כיון שבאו בחוק מלכותם להשמיד וכו', רק לשם השמדת זרעו של אברהם אבינו ע\"ה בלי חמדת ממון וכדו', ורובם הגדול של אלה שייחדום למיתה הומתו, ודאי אין בזה איסור תורה. רק השאלה אם זה דומה למשאל\"ס, ולכאורה דומה לחייבוהו בב\"ד של ישראל שפסק הרמב\"ם ז\"ל בפי' המשנה, וכן בהלכות ערכין (פ\"א הי\"ג), כלישנא בתרא דרב יוסף, דמתירין את אשתו, ואם זה דומה לזה אז מותרת, רק צריך לבדוק כל מקרה לאיזה סוג הוא שייך (וע\"ש שדן בנאצים ימ\"ש שלא הועיל כופר).","b":false},{"t":"ואמנם הח\"מ (סימן י\"ז ס\"ק ס\"ו), כתב דגם ללישנא בתרא דרב יוסף, לא הותרה אלא לתרומה, ולא להנשא, אך כבר דחו דעתו, ראה באה\"ט שם (ס\"ק קי\"ג), וע\"ש עוד מ\"ש מהב\"ש. ולא הבנתי עדיין מה הרויח בזה בדחותו את ד' הגאון הנז'.","b":false},{"t":"עוד כתב שם (אות כ\"ב), להקשות מברייתא (באבות דר\"נ פרק ל\"ח), בהרוגי ביתר שלא ניצל אחד מהם, שיעיד על אשה להתירה להנשא, ולמה לא התירו על יסוד זה שלא נותר אחד מהם. ושם קראו עליהם מקרא זה והיו נשיכם וגו', ויישב דהכונה שלא נמלט אחד מהם אבל לא כולם נהרגו, שיש שנלקחו בשבי, ולא היה מי שיעיד עליהם.","b":false},{"t":"וע\"ש עוד שדן למה לא התירום מצד דרובם למיתה, וגם דאבד זכרם כדכתב הר\"א מוורדון ז\"ל, וע\"ש.","b":false},{"t":"עוד הזכיר הגמ' דב\"מ (ל\"ח ע\"ב), דאין מורידין קרוב לנכסי שבוי, ובגמ' שם, מיתיבי ר\"א אומר ממשמע שנאמר וחרה אפי והרגתי אתכם, יודע אני שנשותיהם אלמנות וכו', מלמד שנשותיהם מבקשות להנשא, ואין מניחין אותן וכו', ופירש\"י ז\"ל, שילכו בשבי ולא ידעו ביניהם אם חיים או מתים, ויהיו נשיהם אלמנות לעולם שאין מניחין אותן להנשא. (ר\"ל דמשום השביה א\"א להתיר אלמנותיהם).","b":false},{"t":"ו.","b":false},{"t":"בספינה שאבדה בים למה לא נתיר מטעם דרובא וחזקה רובא עדיף.","b":true},{"t":"עוד כתב הרב ז\"ל דבגיטין (כ\"ח ע\"ב), ספינה שאבדה בים נותנים עליהם חומרי חיים וחומרי מתים, ומשמע שהוא ספק דאורייתא ומשום חזקת א\"א אזלינן לחומרא. וקשה דהא רובא וחזקה רובא עדיף. ובמס' ב\"ב (קנ\"ג ע\"ב), אמרו שספינות הטובעות בים רובם למיתה, וע\"כ לא תהא זו אלא חומרא דרבנן.","b":false},{"t":"והגאון מטווריג ז\"ל למד מכאן לחזק סברתו דרוב התלוי במקרה אינו רוב מן התורה, [ובני הרב יש\"י נר\"ו כתב על זה, דלכאורה הכי משמע מהתוס' בכתובות (ט.) בד\"ה ואבע\"א באשת ישראל, דרוב דרצון לא חשיב רוב אלא מדרבנן, ע\"ש. ואפשר לפרש הטעם משום דהוא תלוי במקרה]. ויש לדחות דשאני הכא שיש תרי חזקות חזקת א\"א, וחזקת חיים של האיש, וכן הוא בריב\"ש ז\"ל (סימן שע\"ט), ושוב דקדק דהן חזקה א' שאילמלא שבעלה חי אין היא אשת איש וא\"כ הן שתיים שהן אחת, וכ\"כ הנוב\"י. [ולענ\"ד יש ליישב דברי הריב\"ש ז\"ל דה\"ק, דחזקת א\"א בפני עצמה כל זמן שאין לנו בירור שהשתנתה, נותנת גם חזקת חיים לבעל, מכוח העובדא שעד עתה היתה א\"א, והו\"ל חזקה עד שיודע אחרת. ועוד שידענו שהבעל הזה חי ויש להחזיק עובדא זו עד שיודע שמת, וזה עושה אותה לא\"א, ואעפ\"י שהן משפיעות זו על זו, מ\"מ יש כאן שתי כוחות משני כיוונים נגד הרוב שבא לפרק ב' הנהגות אלו, ובכה\"ג לא אמרינן רובא עדיף להריב\"ש ז\"ל. שמ\"ע].","b":false},{"t":"ז.","b":false},{"t":"היכא דאיכא אומדנא דמוכח שהאדם נהרג.","b":true},{"t":"ואוסיף לחזק פסק דין זה ממ\"ש בשו\"ת מהר\"ש ענגיל ז\"ל ח\"ג (סימן י\"א), הוב\"ד בקונטרס התשובות שבאוצר הפוסקים סס\"י י\"ז והוא בכרך ח' בסופו (דף ע\"ו ע\"ב), ביהודי שנסע מביתו לרגל מסחרו ברכבת, ונתפס ע\"י גויים ומאז לא נשמע ממנו זה שנתים, ויצא קול שנהרג ע\"י פורעים שהרגו אז כמה נפשות מישראל, ונתפרסם בכל עיתוני העולם, וקצין אחד בירר הענין ואמר לאשת האיש הנז' בסוד, שנודע לו משוטר א' שבעלה נהרג ע\"י פ' ופ' הרוצחים ונקברו, ואח\"כ הוצאו משם והובילום לכפר אחר סמוך וצילמו הגופות וקברום שם. ומיד נסע הקצין וראה תמונה של א' שהוא דומה ממש לתמונה שהראתה לו האשה מבעלה. ולא רצה לקבל שכר עבור טרחתו.","b":false},{"t":"וכתב דכאן לא הוי מסל\"ת שהכל נעשה לשאלת האשה, וגם לא אמרו שראוהו מת, ואפשר שאמרו כן משום שידעו שהיה במקום סכנה, וכן נסתפק אם סומכים על התמונה, ובפרט שצילמו אחר שעבר זמן רב ממיתתו.","b":false},{"t":"ואולם כתב שם, שיש אומדנות דמוכחי טובא שהאיש מת, כי נלקח למקום סכנה במקום דשכיח שפיכות דמים, וגם נאבד זכרו יותר משנתיים, ונתפרסם בכל העולם ואילו היה חי, היה מודיע לאשתו שעמה היה חי בשלום, ובזה יצאה מאיסור תורה, ויש להתיר על פי הספקות הנ\"ל.","b":false},{"t":"א' יפה כתב הרב המתיר (בעל אמרי יושר), דהרמ\"א (סי' י\"ז סט\"ו), שכתב דאם יש אומדנות וגוי שאינו מסל\"ת, דמועיל רק שלא תצא, אבל לא מהני להתירה להנשא לכתחילה. והיינו כשאין הוכחה מדברי הגוי שאומר אמת, אבל זה שלא רצה לקבל כסף ואמר שרוצה להטיב ליהודים, וכן אמר שמות הרוצחים שזה מוכיח שאומר אמת, בזה אפילו אינו מסל\"ת מהני דיבורו להצטרף לשאר אומדנות, להתיר גם לכתחילה. וכיון שיצאה מאיסו\"ת יש לסמוך על התמונה, דלרוה\"פ החשש דאשתני אחר ג' ימים הוא דרבנן, ויש לצרף דעת הכנסת יחזקאל דבקבר לא משתנית צורתו כמו במים.","b":false},{"t":"עוד הביאו שם תשובה מקונטרס באר מים חיים מרדכי על הנידון הנ\"ל. שכתב שכיון שבלי עדות הגוי, נודע שנסע רק לאיזה ימים וישוב, ובזמן הזה יש טליגרף ודואר קבוע, ואבד זכרו זה שנתיים, וגם יש קלא דלא פסיק, ונתפרסם בעיתונים שנהרג באותו מקום, שהעידו ב' כשרים שהורד מהרכבת ע\"י שני חיילים מאנשי הצבא ונשאר בידם, וידוע שבאותו זמן נהרגו כמה נפשות מישראל, ומי שנפל בידם לא יצא חי. ובמבי\"ט (סי' שכ\"ו), כתב משם תשובת הגאונים שהתירו בקול הברה, והגם שהשו\"ע פסק כהחולקים שרבו עליהם, מ\"מ אפשר שגם החולקים יודו בנ\"ד שהועד ע\"י עדים שנפל לידי רוצחים שכל מטרתם להרוג יהודים, וע\"י כ\"ז ודאי לא תצא. ויש מקום גם להתירה לכתחילה, על פי מה שאמר שיש תמונה דומה, ואעפ\"י שקצין זה מומר ופסול מדאורייתא, ואינו מסל\"ת, חידש לנו הנוב\"י דכשיש רגלים לדבר נאמן עכו\"ם אפילו אינו מסל\"ת, ואעפ\"י שהחת\"ס דחה סברא זו, במקום כזה יודה החת\"ס (ע\"ש). ועוד שהקצין גילה שהשופטים עצמם הם הרוצחים, ובודאי ידע שבגילוי סוד זה ישטמוהו [בסוף הלשינו עליו שמגלה סודות וברח למקום אחר], ויש חזקה שאמר אמת. ועוד שלדעת המבי\"ט באיסור דרבנן נאמן עכו\"ם אפילו שאינו מסל\"ת, ויש להתיר.","b":false},{"t":"ומשתי תשובות אלו יש חיזוק לתשובתו של הגאון מטווריג ז\"ל בעל שו\"ת נר אהרן הנ\"ל, דגם בזה יסוד ההיתר הוא שידוע שנפל בידי כת של רוצחים שכל באיה לא ישובון.","b":false},{"t":"ח.","b":false},{"t":"המחבלים דרכם לומר שיש בידם שבויים או גופות כדי לעשות החלפת שבויים. ובנ\"ד לא אמרו דבר מעולם.","b":true},{"t":"בנ\"ד כת המחבלים החוטפים שבאו ולקחוהו מתוך משרדו לאור היום לעיני השכנים וכו', והדבר ידוע ונתפרסם מאד בכלי התקשורת בכל העולם בזמן שזה קרה. וזה יותר מעשרים שנה שאבד זכרו לגמרי, וכתות אלו ידועים כשופכי דמים מהגרועים שהיו אי פעם בעולם, ומעולם לא העלו את זכרו אפילו למשא ומתן. וידוע ומפורסם שגם בגופות של חטופים שהם רצחו, עשו על גבם מו\"מ עם חיילי צה\"ל והמדינה, והיו מטעים את כל העולם כאילו הם עדיין חיים, ובאכזריותם הנוראה שיחקו בנפש קרוביהם בלי נדנוד עפעף, ואם היה בידם אפילו הגופה שלו לא היו שותקים, וק\"ו אם היה חי עדיין, היו מנצלים כל דבר כדרכם הרעה, רח\"ל. וע\"כ אין ספק שיש בכל זה כדי להתיר אשה זו לעלמא.","b":false},{"t":"ט.","b":false},{"t":"היכא דיש אומדנות שהבעל נהרג וא\"א להכירו בפניו אלא בטב\"ע דגופא.","b":true},{"t":"ועיין עוד בשו\"ת חבצלת השרון (סימן כ\"ד), הובא בקונטרס התשובות שבאוה\"פ כרך ח' (דף ע\"ט ע\"א טור א'), באיש שהועד עליו שראוהו מובל בידי אנשי צבא, ומאז נעלם ולא נודע מה היה לו, ונתברר שחיילים אלו מוחזקים לרוצחים, ואח\"ז נמצאת גופה ביער שבסביבות הכפר שהוליכוהו דרך שם, וא\"א היה להכירו בפניו. אלא הוכר בטב\"ע דגופא, בקומתו ובעוביו ובשערות ראשו, וכן הכירו בטב\"ע בכליו ומלבושיו שזה אותו האיש.","b":false},{"t":"וידוע דבטב\"ע מעידים רק על הפנים, וגם בבגדים חיישינן לשאלה, וע\"ש שדן בכל זה בדברי הפוסקים.","b":false},{"t":"ובסוף דבריו כתב, בפרט בנ\"ד דאיכא אומדנות דמוכחות טובא, שראוהו בידי החיילים המוחזקים לרוצחים, ומאז אבד זכרו, ונמצא אח\"כ באותו דרך לבוש בכל מלבושיו, וכו', לכן יש להתיר האשה. ע\"כ.","b":false},{"t":"שוב רואים דהאומדן הגדול עליו בנה בנינו וצירף כל מה שצירף, הוא המצב שבו נודע שהיה בידי רוצחים, וק\"ו בנ\"ד שהם מפורסמים בכל העולם מזה עשרות שנים רבות שזו דרכם כסל למו, ולשפוך דם הוא כל מאודם. וגם דנתפרסם בענין מאד, ועברו יותר מעשרים שנה, דיש מקום לדון ע\"ז.","b":false},{"t":"ועיין בשו\"ת צור יעקב (סי' ל\"ז), הובאו בקונט' התשובות שבאוה\"פ הנז' (דף פ' ע\"א), שכתב דגם בלא אמירת האיש המעיד, האחרונים הוכיחו מהתשב\"ץ דבאבד זכרו ע\"י המלחמה, יצאה אשתו מחזקת א\"א, וכיון שכן בנ\"ד שהעידו על כל אותה פלוגה שנאבדה בקרב, אעפ\"י שלא העידו בפירוש עליו, ויש חשש שמא ערק לעלמא, עכ\"פ העידו שהוא במקום סכנה איומה, וגם אבד זכרו זה עשר שנים, וכיון שבזה יצאה מכלל א\"א, אז יכולים לסמוך על המספרים (שסיפרו לא' החיילים שהוא נהרג), אפילו אם המספרים גויים. שהרי השואל שאל על עוד חיילים ואח\"כ ע\"ז, ואין כונה להתיר. וי\"ל שגם לא התכוין להעיד. וע\"ש שי\"א שבאינו מתכוין להעיד א\"צ לומר קברתיו. וע\"ש. וע\"ע בתשובתו (סימן ל'), והובאה באוה\"פ שם (דף פ\"א ע\"א), שחזר על אותם דברים.","b":false},{"t":"י.","b":false},{"t":"במטוס שנפל למים ונפלטו ממנו כמה גופות, אם יש אומדנא דמוכח על השאר שלא נמצאו.","b":true},{"t":"והנה התשובה האחרונה שבקונטרס הנז' (דף פ\"א ע\"א), היא מהיכל יצחק הרצוג (סימן כ\"ט-ל'), במטוס צבאי שיצא מדרום אפריקה בזמן מלחמת העולם השניה להפציץ את האויב, והיה דרך הים, ולא חזר המטוס מפעולה זו, וההשערה שנפל בים ואבד עם שמונת אנשי הצוות, ואחד מהם קצין יהודי, ומאז לא נשמע מהם מאומה, אחר זמן הים פלט ארבעה גופות, ומהממונה קיבלו מכתב שסיים חקירתו הקובעת בתור אומדנא דמוכח, שהקצין הנ\"ל מת.","b":false},{"t":"וא\"כ אין עדות מיתה, אלא שנעלם ותו לא. והרב ז\"ל כתב דאעפ\"י שלא נמצאו שברי האוירון, חזקה שנשבר ונפל בים מזה שלא מצאו את שבריו. וכן יש להוכיח מהארבעה גופות שנפלטו מהים, ואין לפקפק בעדות של הכרת הצוות דהמפקדה יש לה דין ערכאות. וע\"ש עוד. וכתב דגם אין לחוש לטעות דמידק דייקי טובא. ואצל חייל לא חיישינן שהשאיל בגדיו. וגם אין חשש שניצל וברח, דהבורח מן המערכה אחת דתו להמית. וכו'. ולשביה אין לחוש דכבר החזירו השבויים. וגם שלא בא לאשתו זמ\"ר, ויצאה בזה מכלל איסור דאורייתא, ועוד דן בדין משאל\"ס ובמצב האוירון וכו'.","b":false},{"t":"ובסוף צירף סברת הר\"א מוורדון ז\"ל ובזמנינו נתחזקה סברא זו, והשבו\"י מקל במשאל\"ס בעגונה רכה בשנים, והעלה להתיר. וכתבו שם שיש נידון דומה, באגרות משה סימן מ\"ח.","b":false},{"t":"יא.","b":false},{"t":"יחיד שנחטף ע\"י מחבלים יש יותר אומדנא שנהרג, מההמונים שנעלמו בימי השואה האיומה.","b":true},{"t":"ונידון דידן עדיף שנלקח ע\"י מחבלים הידועים לשמצה, ושכל באיהם לא ישובון רח\"ל, והדבר נתפרסם בכלי התקשורת בקול גדול עצום ורב, ואנשי המוסד מודיעים שמאז ניסו להוודע עליו ומעולם לא הגיעה שום ידיעה ממנו, לא דרכו ולא דרך המדינאים ואנשי הצבא.","b":false},{"t":"ולענ\"ד זה גרע מאלו שהיו כבושים אצל הנאצים ימ\"ש, דשם היתה תפיסה ענקית של מליונים רבים, והיו מעטים שהצליחו להמלט ולהציל נפשם מרדת שחת, אבל אלו שתופסים איש אחד, או כמה אחדים, וידועים ומפורסמים בכל העולם באכזריותם. וברוע מעלליהם, ובפרט בתוך לבנון ובאותם הימים, שזה היה אחד המבצרים הגדולים שלהם, והיו שם כמו מדינה בתוך מדינה, ועשו כחפצם באין מפריע, בודאי דיצאה מכלל א\"א דאורייתא, ורוב השנים שעברו, עם רבוי החקירות והדרישות מכל הגורמים, ראויים להצטרף להתירה.","b":false},{"t":"ועיין עוד במנחת יצחק ח\"ו (סימן קנ\"ו), באשה שמת בעלה בלא בנים, והיו לבעלה ב' אחים שנספו בימי הזעם רח\"ל, אבל אין עדות גמורה, רק שהובילו אותם הצוררים ימ\"ש בטראנספורט למקום הפורענות, וגם בחיפוש ע\"י הצלב האדום וכיו\"ב לא העלה כלום, ועל אח אחד, יש אחד שאמר שלפי השמועות לא חזר שום א' מהטרנספורט ההוא, (ודן שם בזה שאחד האחים הוא מעל גיל ע' שנה. ע\"ש).","b":false},{"t":"וכתב שהגאון רח\"ד פדווא (שליט\"א), דן באותו שהובילוהו הצוררים ימ\"ש למחנות ההשמדה, דיש להם עכ\"פ דין מים שאל\"ס. וכתב שכבר דן בזה במנח\"י ח\"א (מסימן א' ולהלן), והוכיח כן מכמה טעמים, ויפה כתב הרה\"ג הנ\"ל דבצירוף מה שעברו כמה שנים ואבד זכרם, ואין ספק אצלנו שמתו, כ\"ז הוי יסוד גדול, וכמ\"ש בתשו' אחיעזר (אהע\"ז סימן ל\"ו), להתיר יבמה לשוק במשאל\"ס ואבד זכרו. עכ\"ד.","b":false},{"t":"ונ\"ד חמור טפי דאע\"ג דבשואה רצחו מליונים רח\"ל, עכ\"פ כיון שזה היה בהמוניות, היו הרבה יחידים שיכלו להמלט ולחמוק, אבל אלה שתופסים א' או איזה אחדים המצב קשה להם יותר רח\"ל. וגם שזה עשרים ואחד שנה שאבד זכרו לגמרי, וכל החיפושים לא הועילו. וע\"כ בזה יודו האחיעזר והמנח\"י שבזה יש להתיר גם בא\"א.","b":false},{"t":"יב.","b":false},{"t":"היוצא למלחמה ולא חזר מן הסתם שהוא נהרג.","b":true},{"t":"עוד ראיתי למרן מופה\"ד ביבי\"א ח\"ז (אהע\"ז סימן י\"ד), שכתב, בא' שנלקח לצבא הרוסי להלחם בצבא גרמניה ולא שב, ואשתו מבקשת היתר להנשא. ובאות א' הזכיר דברי התוס' בכתובות (ט ע\"ב), ד\"ה כל היוצא למלחמת בית דוד וכו', שהקונטרס נקט אגב ריהטא אם ימות, דסתם מי שאינו חוזר מן המלחמה, הוא לפי שמת. וכ\"כ בתוספות הרא\"ש שם.","b":false},{"t":"וכ\"כ בשו\"ת חסד לאברהם תאומים מה\"ת (חאהע\"ז סימן כ\"א), באיש שנלקח לצבא ומאז לא נודע מה היה לו. שנראה לדון שהאשה יצאה מחזקת א\"א, כיון שכל אנשי הצבא על משמרתם, וזה לא נמצא בידוע שמת, דאין לחוש שברח שהרי אחת דתו ליסרו ביסורים קשים וכו'.","b":false},{"t":"ובשו\"ת התשב\"ץ ח\"א (סימן פ'), הביא דברי הירושלמי יבמות (פ' ט\"ו ה\"א), ששאלו על פ' היכן הוא ואמר לון מית וכו', ואמר ר' אייבו בר נגרי שעת מלחמה הות, הדא אמרה שע\"א במלחמה נאמן. וכתב הרשב\"ץ ז\"ל ללמוד מזה דהיוצא למקום סכנה כגון למלחמה, ואותם שיצאו הגיעו עד שערי מות וחזרו, וזה לא חזר ולא העידו עליו שמת, רק אמרו שאם היה חי היה חוזר, לכתחילה אין להתיר את אשתו, ואם נישאת לא תצא, והנכסים בחזקת היורשים ע\"ש. וציין שכ\"כ בשו\"ת צור יעקב (סימן ל\"ז), (שהבאתי לעיל), מהרשב\"ץ הנז'.","b":false},{"t":"עוד כתב שגם הגאון רבי שמחה זליג מו\"צ דבריסק כתב לרבי אליהו קלאצקין, והובא בספר דברים אחדים (אות מ\"ג עמוד כ\"ה), דבאמת רוב ההולכים למלחמה ואין מהם ידיעה, וגם לערכאות אין ידיעה עליהם, הוא מחמת שנהרגו במלחמה, ובפרט שהיה חי עם אשתו בשלום וזה זמן שלא כתב לה, ולא השיב על הבשורה שנולד לו בן, אין ספק שיש רוב למיתה יותר ממים שאל\"ס.","b":false},{"t":"וכיו\"ב כתב האחיעזר ח\"א (סי' י\"ז אות ה'), בד\"ה וגדולה מזו, דאעפ\"י שבסתם מלחמה אין ע\"א נאמן דאמר בדדמי, מ\"מ אם היה במלחמה ואבד זכרו, הוי אומדנא גדולה שמת, ואיתרע עי\"ז, חזקת חי דבעל וחזקת א\"א דאשתו, וי\"ל דע\"א נאמן בכה\"ג אפילו בלא קברתיו.","b":false},{"t":"וכתב ביבי\"א דבמלחמה של גרמניה ברוסיה, שיצאה מכלל סתם מלחמה, נראה דהוי אומדנא גדולה שמת, ובכה\"ג י\"ל שעד נאמן גם בלא קברתיו. וכ\"כ הגרא\"י קוק ז\"ל בשו\"ת עזרת כהן (סי' כ\"ה), שכיון שלא חזר מן המלחמה ולפי אומד הממשלה הוא מת כבר, הו\"ל כנפל למים שאל\"ס שאם נישאת לא תצא.","b":false},{"t":"יג.","b":false},{"t":"הנחטף ביד מחבלים ועקבותיו לא נודעו הרי זה גרוע ממי שנפל לגוב של אריות.","b":true},{"t":"והלום ראיתי מ\"ש ידידי הגר\"ש דיכובסקי שליט\"א חבר ב\"ד הגדול, בפס\"ד על אשה שבעלה נחטף בידי מחבלים ועקבותיו לא נודעו, ובסוף התשובה כתב, שבספר \"אמירה נעימה\" (לרי\"צ הלוי, מהד\"ק סימן ע\"ט ענף ד'), הסיק שאנשים שנחטפו ע\"י כנופיה ערבית גרע מגוב של אריות. ע\"ש. והוסיף שבימינו הדבר הוא על אחת כמה וכמה, כפי הידוע ממעשה אכזריותם של המחבלים ושליחיהם. עכ\"ל.","b":false},{"t":"ומצאנו חבר להגאון נר אהרן ז\"ל הנ\"ל הוא הרב אמירה נעימה, ובנידוננו שהחטיפה היתה ע\"י המחבלים והיא עובדא ברורה, נמצא דזה קיל טפי מנידון דידם, שדיברו ביש אומדנות שנחטף ע\"י מחבלים.","b":false},{"t":"יד.","b":false},{"t":"בזמנינו שיש טלפון ואמצעי תקשורת יש לצרף את סברת הר\"א מוורדון.","b":true},{"t":"ומעתה יש לנו לצרף את האומדנא של הר\"א מוורדון ז\"ל. וכבר כתבתי בתשובות קודמות דאע\"ג דמרן הב\"י ז\"ל שדא בה נרגא, הנה רבו הפוסקים שמצרפים אומדנא זו בפסקיהם וכמו שהארכתי באותם תשובות, והחת\"ס כתב דבימיו שיש טלגראף יש מקום חשוב לצרף ד' הר\"א מוורדון ז\"ל דאם איתא שניצול והוא עדיין בחיים, היה מתקשר לביתו ולילדיו, וע\"ש מ\"ש בשם הגאון מהרי\"א הרצוג ז\"ל בהיכל יצחק.","b":false},{"t":"ועיין עוד במ\"ש מרן יבי\"א ח\"ז (אהע\"ז סימן י\"ד), וז\"ל באות ו' שם, ונוסף לכל הנ\"ל הרי בנ\"ד עברו למעלה מעשרים שנה, מיום שנתקבלה הידיעה על מות בעלה, ומאז נעלם מן האופק ונשתקע שמו ואבד זכרו, וא\"כ יש לצרף מ\"ש המרדכי (סוף יבמות), בשם רבי אליעזר מוורדון בתשובה (והיא לו נדפס'ה בשו\"ת זכרון יהודה להר\"י בן הרא\"ש דנ\"ב ע\"א), וזת\"ד, רואה אני מה שאמרו משאל\"ס אשתו אסורה, ולא אמרו אסורה לעולם. ש\"מ דלאו לעולם קאמר, וכ\"נ שרבותינו תלו הדבר וסמכו על חכמי הדור ויר\"ש שישכילו בענין המאורע בדורותם, ועל עובדא אתינא הכא, שזה כשבע שנים שטבעה ספינה בים סמוך לעיר פיזארו, ע\"י רוח סערה חזק מאד ששיבר וטיבע באותו לילה יותר מששים ספינות, והנה חזקה שאילו היה רבי שלמה מוורנא בחיים, איך היה עומד מחוץ לביתו שבע שנים מבלי להודיע לבני ביתו על המצאו, והוא הניח אשה צעירה לימים ובן ובת, ואביו עשיר גדול ושלח שלוחים ולא מצאוהו, וחזקה שרחמי האב על בניו הקטנים, וגם שאינו עובר על חיוב שאר כסות ועונה, ועל כיבוד אב וכו'. וכיו\"ב בכתובות (כב ע\"ב), באומרת ברי לי, ופירש\"י שאילו היה קיים היה בא, ומ\"ש הר\"ן לחלוק בזה על רש\"י, שאני התם שיש שני עדים שאומרים שלא מת, וע\"כ לא סגי ברי לי נגד עדים, וכ\"כ החת\"ס חאהע\"ז (סימן נ\"ח). וע\"ע בכתובות (ס\"ב ע\"ב), כפו מטתו שאלמלי יהודה קיים לא ביטל עונתו, וכן בירושלמי (יבמות פט\"ו ה\"א), אילו הוו חיין לא הוו מייתין. וכן באו\"ז ח\"א (סי' תרצ\"ג), ובשו\"ת התשב\"ץ (ח\"א סי' פ'), ואפילו ר\"מ דחייש למיעוטא, למיעוטא דמיעוטא לא חיישינן, ולכן נ\"ל שאשתו מותרת להנשא לכתחילה. וחתום עלה הרב אליעזר בר שמואל.","b":false},{"t":"והן אמת שהמרדכי שם, הביא דברי רבינו אברהם בר משה ורבינו ברוך שחלקו ע\"ז למעשה, וקשה בעיניהם להתיר, ושכ\"כ ראבי\"ה, שאין בידינו לתת זמן קצוב ואמתלאות להקל, ודבריו הובאו בראבי\"ה, ומרן הב\"י (סימן י\"ז), הביא דברי המרדכי, וכתב, הנך רואה כמה רברבי חולקים על הר\"א מוורדון בטעמים נכונים וברורים, והגס לבו בהוראה להתיר עגונה ע\"פ אותה תשובה עתיד ליתן את הדין, ושומר נפשו ירחק ממנה. ע\"כ. וכן בשו\"ת ב\"י (דיני מסל\"ת סי' א'), האריך לדחותה בשתי ידים. אולם המבי\"ט בתשו' ח\"א (סי' קפ\"ז), האריך לגונן על ת' הר\"א מוורדון, ודחה ד' הב\"י, וגם רבו של מרן מהר\"י בירב (סי' י\"ג), צירף תשובה זו בנידונו. וכתב המבי\"ט (בסי' קפ\"ח), שאם היו דבריו בטלים ח\"ו, לא היה מהר\"י בירב מביאו לסניף היתר. ע\"ש. ובשו\"ת חיים ושלום ח\"ב (סי' א'), כתב שגם האגודה (בסוף יבמות סי' קכ\"ה), פסק כד' הר\"א מוורדון, ושכן הובא בשו\"ת מהר\"י מברונא (סי' רט\"ו), ושאילו ראה מרן הב\"י תשו' רבו מהר\"י בירב, ודברי האגודה, לא היה מפריז על המדה לכתוב שדבריו בטלים, וכבר תמה בזה בסדר אליה רבה (דף ל' ע\"ד), על מרן. וביקש להמליץ עליו שלא כתב כן אלא כלפי המעיינים. ושכן דעת מהר\"א ממיץ כהר\"א מוורדון, וכן מוכח בתשובת רבינו משולם בן רבינו קלונימוס. ובשו\"ת מהרש\"ם ח\"ב (סי' קס\"ח), העיר מכל זה, וכתב הנך רואה כי אין הר\"א מוורדון יחיד בדבר זה כמו שחשב הב\"י. גם הגאון ר\"י ענגיל בשו\"ת בן פורת ח\"ב (סי' ח'), האריך הרחיב לקיים שיטת מהר\"א מוורדון ושיש להסתמך על אומדנא דמוכח כה\"ג. וע\"ש עוד מ\"ש בשם הגר\"ח מודעי ז\"ל. וע\"ע שם אות ז' שהאריך הרחיב בזה, והביא דברי החת\"ס שבימינו דאיכא בי דואר קביעי וכו', ומ\"ש ע\"ז האחרונים והעלה במסקנתו להתיר בנידונו. ע\"ש.","b":false},{"t":"וכבר הארכתי בכמה תשובות בדברי גדולי האחרונים לדורותיהם, שכמעט כולם יחד מצרפים דעת הר\"א מוורדון לשאר סניפי ההיתר שהעלו בנידונם, וכבר פשטה הוראה לצרף גם את זה. ועוד יותר בימינו שהטלפונים התפשטו בכל אתר ואתר, ועוד נוספו הפלאפונים שאין לך אדם שאינו נושא עמו מכשיר אחד או שנים ויותר, ומדבר בו עם כל העולם ממש, עומד במדינה זו ומדבר עם חברו בסוף העולם כאשר ידבר עם חברו פנים אל פנים, ונוסף הפקס ושאר אתרי התקשורת כלים מכלים שונים, וגם העיתונות והרדיו והטלויזיה גדלו והתעצמו, ותמלא הארץ אותם ובקצה תבל מיליהם. ובזה שעברו אחד ועשרים שנה, והדבר התפרסם בזמנו בכל העולם, ואשתו וילדיו קיימים, ויש לו קרובים ומכירים בא\"י ובכל העולם, ומעולם לא נשמע ממנו זכר מאז שלקחוהו עמם, בודאי שיש לצרף אומדנא גדולה זו להתירא דהאי איתתא.","b":false},{"t":"טו.","b":false},{"t":"בדברים מובהקים אפשר לפסוק באומדנא דמוכח.","b":true},{"t":"ובתשובה שכתבתי בשו\"ת שמע שלמה ח\"ה (סימן ט\"ו אות ט'), הארכתי לבאר ולהוכיח, שדין תורה הוא לפסוק עפ\"י אומדנא דמוכח גם בדיני ממונות, אלא שהגאונים כתבו, דנתמעטו המוחות ונסתמו הלבבות ואין איש איתנו יודע לכוין עפ\"י אומדן. אבל בדברים כאלו מובהקים ושיש הרבה צירופים, ואומדנא זו שכבר סמכו עליה כל גדולי עולם ודאי חזי לאצטרופי.","b":false},{"t":"וע\"כ אמינא בס\"ד, שגם אם תרצה האשה הנצבת בזה להנשא, אני מוכן להצטרף להתירה כדמו\"י. ופשיטא שיש לתת לה פסק דין שהיא נחשבת אלמנת הרוג מלכות, שתוכל לקבל זכויותיה המגיעים לה כדת וכדין, ויהיה לה מקור לפרנס עצמה ולכלכל שיבתה, ושנמנעה מזה עד היום רק לרוב עדינות נפשה וכאב לבה, שלא רצתה לבקש להכריז על בעלה שהוא כבר מת, ולמרות השנים הרבות נמנעה מכך עד שבאו מים עד נפש.","b":false},{"t":"וע\"כ נראה לדינא, שיש לשנות את מעמדה של האשה מנשואה לאלמנה, ופס\"ד זה הוא לענין הזכויות המגיעים לה כאלמנת הרוג מלכות. [שעל זה באה לבקש], ולא לענין נישואין. ואם תרצה לינשא לאיש, תפנה אלינו ונפסוק בענין בעה\"ו.","b":false},{"t":"תוקף פס\"ד זה הוא מיום היעלמותו של בעלה מר ס. ג. ז\"ל.","b":false},{"t":"בברכת התורה, ובתפילה לפני אבינו בשמים שיאמר די לצרותינו, ויושיענו ברחמיו שנית, לעיני כל חי בישועה ורחמים מרובים על עמנו ועל נחלת אבותינו בב\"א.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false},{"t":"ונשיא ביה\"ד הרבני הגדול","b":false},{"t":"ואלו דברי הרבנים שנצטרפו עמדי","b":false},{"t":"אני מצטרף לפסק דינו של כבוד הנשיא שליט\"א","b":false},{"t":"שלמה דיכובסקי","b":true},{"t":"חבר ביה\"ד הרבני הגדול","b":false},{"t":"אף אני הקטן מצטרף לפסקו של כבוד הרב הראשי הראשון לציון שליט\"א","b":false},{"t":"בברכת התורה","b":false},{"t":"ישראל וייס","b":true},{"t":"הרב הראשי לצה\"ל","b":false}]},{"t":"בענין אכילת תותים בלי לבדוק במקרוסקופ","p":[{"t":"בעהית\"ש. ערב חג הפסח התשס\"ט.","b":false},{"t":"לכבוד מעלת הרב יואל פרידמן שליט\"א","b":false},{"t":"מכון התורה והארץ בישוב ניצן","b":false},{"t":"שלום בכפלים ומועדים לשמחה!","b":false},{"t":"א.","b":false},{"t":"בדין חרקים המצויים במאכלים ואינם נראים אלא ע\"י מיקרוסקופ אם מותרים באכילה","b":true},{"t":"במה ששאלת ממני לחוות דעתי, בדבר התותים שהתגלו בהם חרקים, בבדיקות שערכו במעבדות, ויש שפרסמו לאסור אכילתם. וכב' כתב על זה, והעלה להתירם באכילה, דאעפ\"י שנמצאו חרקים והוא בגדר מיעוט המצוי, אין בכח זה לאוסרם באכילה, אלא זה מחייב אותנו לדרוש מאותם מגדלי ירקות ללא חרקים, שיבדקו עצמם ביתר שאת. אבל אינם אוסרים את התותים, מאחר שלא רואים אותם חרקים בעין, אלא על ידי מיקרוסקופ. והדגיש שאפילו מומחה אינו מבחין בהם, אלא ע\"י מכשירים מתאימים. וסמך דבריו על מה שכתבו, החכמת אדם בנשמת אדם (כלל ל\"ח סימן מ\"ט), וערוך השלחן יו\"ד (סימן פ\"ד סעיף ל\"ו), שחרקים שאינם נראים בעין רגילה אינם אסורים, שלא ניתנה תורה למלאכי השרת.","b":false},{"t":"והנה בענין החרקים והתולעים הנמצאים במים או בפירות, ואינם נראים לעין כלל, אא\"כ יביטו דרך זכוכית מגדלת או על ידי מיקרוסקופ, כבר עמד על זה פוסק דורנו, מרן בעל יביע אומר שליט\"א בשו\"ת יחוה דעת ח\"ו (סימן מ\"ז), והתירם בשופי. וכתב בפתיחת דבריו בזה\"ל, הדבר ברור שכל מה שאסרה תורה בדברים התלויים בבדיקה על ידי ראייה, אינם אלא ע\"י ראיה טבעית וכו', ולכן תולעים שאינם נראים לעין כלל אין בהם שום איסור, אעפ\"י שהם נראים ע\"י זכוכית מגדלת ומיקרוסקופ.","b":false},{"t":"וסמך יתדותיו על דברי החכמת אדם בבינת אדם (כלל לח סימן מ\"ט) שהביא מה שכתב בספר הברית, שנתברר ע\"י חכמי המחקר, שאי אפשר ליין להיות חומץ עד שירום תולעים, והמסתכל במיקרוסקופ יראה שהחומץ מלא תולעים רוחשים, ואסור לאכול ממנו אפילו ע\"י סינון, עד שירתיחנו ואח\"כ יסננו בבד דק מאד. והחכמת אדם דחה דבריו ז\"ל שהתורה אמרה בנזיר, חומץ יין לא ישתה, הא לשאר אדם מותר, וברות נאמר, וטבלת פיתך בחומץ, וכי הכתוב יסתום כל כך שלא יפרש שזה רק דרך בישול והרתחה תחלה. ע\"ש.","b":false},{"t":"ב.","b":false},{"t":"קשקשי דגים הנראים ע\"י מיקרוסקופ בלבד אם מותרים באכילה","b":true},{"t":"וכן הביא דברי מאורי אור (חלק קן טהור, חולין נ\"ח ע\"ב), שמה שלא נראה אלא ע\"י מיקרוסקופ וכיו\"ב לא חששו להם חכמים כלל, ורק אם נראים לעין, יש לחוש אפילו שהם קטנים מאד ע\"ש. ושכן פסק בערוך השלחן (סימן פ\"ד סעיף ל\"ו), וכ\"כ הגאון רבי שלמה קלוגר ז\"ל בספרו טוב טעם ודעת תנינא (קו\"א סימן ג\"ן), שבדיקת המיקרוסקופ לא מעלה ולא מורידה מצד ההלכה, שידוע שהמומחים אומרים שאם נסתכל במים במיקרוסקופ נראה תולעים רוחשים ואפילו אם יסננו אותם, וממה שאין משגיחים על זה, מוכח שאין לחוש לזה אפילו לחומרא. ובהערה שביחו\"ד שם האריך הרחיב במו\"מ בזה כיד ה' הטובה עליו.","b":false},{"t":"וע\"ש עוד שהזכיר דברי הראשון לציון הגאון יש\"א ברכה בשו\"ת יש\"א איש (חיו\"ד סימן א'), ומה שדייק ממנו הגאון רבי משה שתרוג ז\"ל (מחבר שו\"ת והשיב משה שהיה ראב\"ד תונס). דמהני ראיה במיקרוסקופ להוכיח שיש קשקשים לדגים, ומ\"מ תולעים שאין נראים אלא ע\"י מיקרוסקופ, אין לאוסרם.","b":false},{"t":"והגאון רבי כלפון משה הכהן ז\"ל בשו\"ת שואל ונשאל ח\"ה (חיו\"ד סימן ס\"ה) השיב עליו, והעלה דראיה דע\"י כלי אינה ראיה לא לאסור ולא להתיר. ושכן העלה מר זקנו הג\"ר משה הכהן ז\"ל. ומרן שליט\"א ביחוה דעת שם כתב, ונראה דס\"ל להרב יש\"א ברכה, שאם הקשקשים לא נראים אלא על ידי מיקרוסקופ, בודאי שאין הקשקשים שלהם נקלפים ביד או בסכין באופן שיראו לעינים, ולכן לא חשש להשיב על עצם השאלה. עכ\"ד.","b":false},{"t":"ואילולי דברות קדשו הייתי אומר דס\"ל להגאון ישא ברכה ע\"ה, דתולעים הנראים רק ע\"י כלי הבטה, עדיין לא באו לכלל איסור כלל, וכמו שאבאר להלן בס\"ד. ואפ\"ה הכשיר בקשקשים הנראים ע\"י מיקרוסקופ, דס\"ל דכיון דהדג גדול וניכר, וע\"י מיקרוסקופ רואים שיש קשקשים, סוף סוף יש סימן טהרה ומותרים, דסו\"ס יש קשקשים, ואין בתורה שיעור לקשקשים, ועיין לקמן שאביא דברי שבט הלוי שהעיר בדברי הגאון מוהרש\"ק ז\"ל במה שכתב על הגאון יעב\"ץ.","b":false},{"t":"ולא דמי לנקבים הנראים ע\"י מיקרוסקופ בריאה או באתרוג, דהתורה לא אסרה אלא נקב הנראה לעין. מיהו הג\"ר כלפון הכהן ז\"ל סובר, דה\"נ יש לומר שאין סימן טהרה אלא בקשקשים הנראים לעין רגילה, וכ\"נ שסובר מרן שליט\"א, אלא שהוא מפרש שגם הגאון יש\"א ברכה סובר דאין להתיר בקשקשים שנראים רק ע\"י מיקרוסקופ וכנ\"ל. וכן כתבו במאסף (חוברת ב' סימן מ\"ב) בסכין שחיטה שראו ע\"י המיקרוסקופ שיש בה פגימות רבות, שאין לחוש לזה כלל.","b":false},{"t":"עו\"כ ביחו\"ד שם, שכ\"כ הגר\"י משאש ז\"ל בשו\"ת מים חיים (סימן רנ\"ט), באתרוג שנבדק ע\"י מיקרוסקופ ונמצאו בו נקבים שאין לחוש לו וכשר למהדרין. ושכן הורה הרה\"ג מהר\"ח בלייח ז\"ל, לענין פירודי אותיות בס\"ת תפילין ומזוזות. וכ\"כ בשו\"ת דובב מישרים ח\"א (סימן א'). וע\"ש שכתב שהגאון מהרי\"ז מינצברג ז\"ל בשו\"ת שארית ישראל (סימן י\"א י\"ב) השיב על זה, וציין הרב לעוד ספרים שדנו בזה. וסיכם והעלה שמה שלא נראה רק ע\"י המיקרוסקופ אין בו איסור כלל לא מדברי תורה ולא מדברי סופרים. ע\"כ.","b":false},{"t":"ג.","b":false},{"t":"כל שאין החרקים נראים לעין אין להם דין תולעים וחשובים כפרש בעלמא","b":true},{"t":"והתבוננתי לחקור להבין בדברי רבותינו המתירים, שהם רוב מנין ורוב בנין של הפוסקים, האם הטעם הוא משום שהתורה מחייבת את האדם, רק במה שהוא מסוגל ויכול לעמוד בו, וכיון שתולעים קטנים אלו, אין אפשרות לראותם כלל בעין אנוש, לכך לא חייבה אותנו תורה להפרישם ולהמנע מאכילת אותם פירות, כי לא ניתנה תורה למלאכי השרת, אלא בחר הקב\"ה בעם ישראל עלי אדמות ונתן לנו תורתו, וציונו והזהירנו במה שיכולים לעמוד בו, ופטרנו מדברים שהם מעל ומעבר ליכולת שלנו כבני אדם, המוגבלים ומצומצמים במגבלות הגוף שהוא בשר ודם. וגם חז\"ל לא גזרו בהם מאותם סיבות עצמם. ולפי זה יוצא שהם חשובים תולעים שהרי כשיגדלו ויראו לעין יאסרו, אלא שהתורה לא אסרה מה שלא נראה לעין, שלא ניתנה תורה למלאכי השרת. וזה צד אחד. ומאידך אפשר לומר דאין כאן איסור כלל ועיקר, כי מה שהתורה אסרה הוא דוקא תולעים ושאר חרקים, ואילו אלו שהם זעירים כל כך שאין עין אדם שולטת בהם, לא חשיבי תולעים אלא כפרש בעלמא, והרי זה דומה לביצית של אדם או של בהמה וחיה, שיש בה כוח לפרות ולהיות ליצור חי כפי המוצא של אותה ביצית, אך לעת עתה אינה חשובה לדבר חי כלל, והרי ביצה של תרנגול מותרת בחלב אע\"פ שנולדה מן העוף שאסור בחלב מדרבנן, ולא עוד אלא ממנה יוצא אפרוח שגודל ונהיה תרנגול, עם כל זה הביצה מותרת בחלב. וכן נמי מי שיאבד וישחית ביצית הלקוחה מאשה, אין בו דין של מאבד נפש האדם כלל ועיקר. והכא נמי אין דין של בעל חי על החרק או התולעת, אלא בהגיעה לגודל כזה שעין האדם רואה ומבחינה בה וברחישתה. אבל לפני כן גם בהתברר בבירור גמור (ע\"י מכשירים ומעבדות) שתולעת היא, עדיין אינה אסורה ולע\"ע אין עליה דין תולעת, אלא נחשבת חומר העתיד להתהוות ולהתפתח לתולעת, אבל כעת אינה עדיפה מביצת תרנגולת ומביצית של אדם ובהמה, וכנ\"ל.","b":false},{"t":"ונלע\"ד שהטעם הזה הוא העיקר, שכל שאינו נראה ע\"י עין רגילה, אין עליו דין של בעל חי כלל, אלא הרי הוא בכלל החיידקים (מיקרובי'ם), ואעפ\"י שיש בהם חיוּת, כל חיוּתם מתבטאת בכך שהם עתידים להמשיך להתפתח עד שיהיו לבעלי חיים ממש, אך לע\"ע אינם בכלל בעלי חיים כלל, אלא הם פרש בעלמא, ולא זה מה שאסרה תורה. ואע\"פ שאין גילוי לזה בתורה, שהרי אסרתם בסתם, מיהו י\"ל דמעצם העובדא שאסרתם וקראה בשמותם, זו הוכחה שמדובר במה שהעין הרגילה רואה, ולא במה שאינו מושג ע\"י עין האדם. דאיך תאסור לנו התורה מה שאיננו רואים ואיננו משיגים. ואולי גם אלה שאמרו: לא ניתנה תורה למלאכי השרת, אין כונתם משום שאי אפשר ואין ברירה, וחשיב כאונס, אלא רוצים לומר דהואיל שלא ניתנה תורה אלא לבני אדם, זה מוכיח שלא נאסר לנו אלא מה שהעין רואה. דמה שאין עין אדם יכולה לראות כלל, איך תאסור אותו התורה, וכל אותם דורות שלא היה מיקרוסקופ לא ידעו מזה כלל, ואנחנו לא מלאכים.","b":false},{"t":"תדע שבכל דבר יש שלבים, וגם האדם והבהמה נוצרים מן הזרע של אב ואם, אך אין על זרע זה דין של בעל חי, עד שיתרקם ויהיה ולד ורק אחר ארבעים יום מיום היצירה יקרא אדם. וכן ביצים של עופות, וזחלים של תולעים ושקצים, אין להם דין של בעל חי, עד שתגמר יצירת הולד ותבקע הביצה ויצא האפרוח או הבעל חי. וגם בפירות יש תהליך של התפתחות בשלבים שונים, שהרי בתחילה העץ מציץ פרח ובפרח יש ניצן, וכל זה עדיין אין לו דין פרי אעפ\"י שסופו להיות פרי אמיתי, ואפילו כשהפרי יצא הן בעודנו קטן מאד שאינו ראוי לאכילה כלל, עוד אין עליו חיובי תרומה ומעשר, וא\"א לעשר ממנו על אחרים וכו', עד שיהיה ראוי לאכילה לפחות ע\"י הדחק, וגם האוכלו א\"צ להפריש ממנו מאומה, וגם אין עליו ברכה כלל, עד שיגדל ויהיה ראוי לאכילה. ואעתיק כאן לשון הרמב\"ם ז\"ל בהלכות מעשר (פ\"ב ה\"ג), פירות שאינן ראויות לאכילה בקוטנן, כגון הבוסר וכיוצא בו, אינן חייבים במעשרות, עד שיגדלו ויעשו אוכל, וכו', וקודם שתגיע התבואה והפירות לעונה זו, מותר לאכול מהם כל מה שירצה ובכל דרך שירצה. [ועיין כרם שלמה ח\"א תרו\"מ סימן ו' אות ב' מה שכתבתי בזה].","b":false},{"t":"וק\"ו לחיידק שאין בו לא ריח ולא טעם, ואפילו ממשות לא שייכת בו, וגם עין האדם הרואה הכל אינה שולטת בו כלל, דבודאי שאין בו שום איסור כלל, לא דאורייתא ולא דרבנן. תדע שהמדענים אומרים, שבכל דבר שבעולם יש חיידקים רבים לאין מספר אלא שהם אובדים וכלים ברובם הגדול, כי חיותם מועטת ומוגבלת מאד.","b":false},{"t":"עוד תדע שגוף כל בעל חי מלא נקבים רבים לאין מספר, ויש דרך זה נשימה כל שהיא, ועם כל זה חז\"ל קבעו שנקובת הריאה או הושט או הקבה ועוד, היא טרפה. ואם יבדקו כל אבר ואבר במיקרוסקופ יראו שהם נקובים בנקבים רבים, ועם כל זה כשרים הם, משום שלא אסרו אלא נקב שהעין קולטתו, אבל אותם הנקבים אפילו שהם קיימים, ונראים בבירור דרך המיקרוסקופ, לא נחשבים לנקבים. וק\"ו לנידון זה שעדיין לא התפתח ולא הגיע ליקרא בשם בעל חי. ועיין מה שכתב הרב תפארת ישראל על המשנה (ע\"ז פ\"ב משנה ו', בבועז אות ג'), והביאו מרן נר\"ו ביחוה דעת הנ\"ל. שהעלה שם שדעת תורה לסמוך רק על מה שנראה לעין אדם רגיל.","b":false},{"t":"ואפשר גם כן, שחז\"ל קבעו שכל מה שאסרה תורה, וכל מה שציותה לעשות, הכל בנוי עפ\"י עין האדם, וכוח השגתו עפ\"י חושיו הטבעיים, ותו לא מידי, דכל מה שנזקק למכשירים וכדומה כדי לראותם או לחוש אותם אינו כלום, ולא זה מה שאסרה התורה.","b":false},{"t":"ד.","b":false},{"t":"בענין המילבי\"ן המצוי באורז","b":true},{"t":"והנה הרב פתחי תשובה (בסימן פ\"ד סק\"ה בסופו), כתב משם שאילת יעב\"ץ ח\"ב (סימן קכ\"ד) שגם לאורז יש תקנה בבדיקה ע\"י חימום וראות עין יפה, ומבדקי נמי בשמשא או ע\"י כלי זכוכית מגדיל הראות, והמחמיר יחמיר לעצמו אבל אין להורות איסור לאחרים. ע\"ש. עכ\"ל.","b":false},{"t":"והרב דרכי תשובה שם (ס\"ק צ\"ד) כתב שבתשובת היעב\"ץ הנז' כתב, ידוע שאין האורז מתליע במחובר כלל רק בתלוש, ונמצא בו שני מיני תולעים, המין הא' תולעים גדולים, ומשליכים אותם, וגם מיא בדקי להו, שהתולעים צפים במים, ומהני אפילו למתולעים בודאי וכ\"ש לספק מתולעים, וכו', והמין השני הוא הכנימה שקורין מילבי'ן, וזה ג\"כ ישנו בבדיקה ע\"י חמים ועין יפה, ומבדקא בשמשא או ע\"י כלי זכוכית מגדלת הראות, ואם נמצא בודאי נאסר כולו, ולא מהני ליה שום תיקון לאוכלו, אכן כל שנבדק כנ\"ל ולא נמצא בו אין לחוש וכו', ולא ניתנה תורה למלאכי השרת. ע\"ש. והביאו במחזיק ברכה אות מ\"א. עכ\"ל.","b":false},{"t":"ומדבריו ז\"ל נראה שהמילבי'ן האלו, הם לא בגדר חיידקים, שהרי כתב שאפשר לבודקו בשמש או בזכוכית מגדלת, ואם נראה בשמש, היינו בעין רגילה, אלא שמרוב קוטנו וצבעו שהוא דומה לאורז קשה להבחין בו, וצריך לאור השמש, או זכוכית מגדלת. (וזכוכית מגדלת, אינה בגדר מיקרוסקופ שבמיקרוסקופ מתגלים ונראים דברים שא\"א לראותם בעין רגילה כלל וכלל, אבל זכוכית מגדלת מראה דברים שעין אדם בריאה רואה אותם, אלא שהזכוכית הזו מגדילתן ונראים בקלות יותר וגם ברור יותר).","b":false},{"t":"וע\"ש בדרכי תשובה שאחרי זה הביא מדברי הרב טוב טעם ודעת תנינא (בקו\"א סימן ג\"ן), [והובאו ביחו\"ד הנ\"ל] שכתב דחלילה לסמוך על בדיקת הזכוכית מגדלת, דבדיקה ע\"י כלי זה וכיו\"ב לא מהני, שהמומחים אומרים שאם נביט במים ע\"י זכוכית הנ\"ל, נראה שכל המים מלאים תולעים ומדלא משגיחין על זה, בע\"כ דאין סומכין על בדיקה זו, ואם אינה ראיה להחמיר ק\"ו שאינה ראיה להקל עי\"ז, כיון שלא חשיבה בדיקה כלל וע\"ש בדרכי תשובה שרמז גם על דברי הרב בינת אדם הנז' שדחה דברי ספר הברית, שאין לסמוך על המיקרוסקופ. עכ\"ד. (ונראה שגם הרב טוטו\"ד מיירי במיקרוסקופ).","b":false},{"t":"וראיתי להגאון הגדול בעל שבט הלוי בחלק ז' (יו\"ד סימן קכ\"ה אות ב') שהקשה ע\"ד הרב טוב טעם ודעת הנ\"ל, דמה דאין חוששין לזכוכית מגדיל ראות או מיקרוסקופ להחמיר בכל מים, אינו משום דלאו בדיקה היא להחמיר, אלא משום שלא חייבה תורה על תולעים וכיו\"ב אלא מה שנראה לעיני אדם, דאל\"כ אין לך דבר שבעולם שלא נראה בו בע\"ח קטנים, ע\"י מיקרוסקופ, אבל לבדוק להחמיר ע\"י זכוכית כזה באורז, כדי להרגיש במה שצריך להרגיש, אלא שלפעמים העין קצר הראות, ועין חדה יכולה לראות כזה, ועין בינונית לא תרגיש רק ע\"י זכוכית כזה, אין זו בדיקה להקל, אלא להחמיר במה שצריך להחמיר, דהיינו במילב'ין של אורז וכיוצ\"ב, ובודאי דמה שאין עין אדם יכולה לראות, אפילו שהיא עין חדה וחריפה, בזה בודאי שאין צריך בדיקה כלל, וכבר כתבתי בעניי בזה בכמה מקומות. עכ\"ל. ומפורש בדבריו, שגם הוא פוסק דדבר שלא נראה לעין האדם, א\"צ בדיקה כלל, ואפילו יבדק ויראו במיקרוסקופ שיש בו חרקים לא נאסר.","b":false},{"t":"וקושייתו ע\"ד הטוטו\"ד הינה תפיסה חזקה. ויש לחזקה עוד במה שדקדקתי בדברי הגאון יעב\"ץ הנז', דהמילבי'ן נראה ע\"י עין רגילה רק שהוא קטן וצבעו כאורז ע\"כ צריך לעיין בו בשמש, או ע\"י זכוכית מגדלת וכיו\"ב. ומאחר וכן צדקו דברי השאלת יעב\"ץ, שיבדקנו בשמש או ע\"י זכוכית מגדלת. ולא שייך לומר בזה דאינה בדיקה, כי כל זה נאמר דוקא על הדברים שאינם נראים בעין רגילה שאין לאוסרם דלא שמה ראייה, אבל אם רוצה לדקדק בבדיקתו ולהתרחק מן הספק, בודאי דבדיקה מעולה היא, ואם יראה מילבי'ן יאסור. ורק לאסור מה שאין העין רואה, לא חיישינן לה ואפילו שנראית ע\"י זכוכית מגדלת. אבל אם יש חשש מילבי'ן ובדקו ע\"י זכוכית ושאר כלים, ולא מצאו, ודאי שבדיקה זו מועילה.","b":false},{"t":"ואפשר שהגאון טוטו\"ד ס\"ל דאין לסמוך על הזכוכית ועל המיקרוסקופ. דאין הראיה ברורה על ידם, משום שבפעולתם הם מגדילים את הדבר, אבל לעומת זאת הריהם מטשטשים את המראה וקשה להבחין במה שרואים דרכם, ואם כך הוא הדבר, ה\"ה שגם לבדוק האורז כדי לשלול מילבי'ן וכיוצ\"ב, לא מהני. וצ\"ע בדבריו.","b":false},{"t":"ואולם לפי מה שהעליתי בעניותי דכל שלא נראה בעין רגילה, עדיין לא בא לכלל בעל חי כלל, ולא חל עליו שם של איסור, ואם כן כל שלא נראה בעין מותר גמור, וא\"צ בדיקה, וגם אם יבדקו ע\"י מיקרוסקופ ויראו תולעים מותר גמור משום דלא נחשבים לבעלי חיים כלל. אך בנדון המילבי'ן שזכר היעב\"ץ ז\"ל מיירי שניתן לראותו בעין רגילה, רק שקשה להבחין בו, וצריך לאור השמש או מגדלת, ובזה ס\"ל להרב שאילת יעב\"ץ ז\"ל דמהני בדיקת הזכוכית, דאם אין רואים המילבי'ן ע\"י זכוכית המראה גם דברים שעין רגילה אינה רואה, זה ברור שאין באורז הזה מילבי'ן ומותר. ודלא כהשגת הטוטו\"ד.","b":false},{"t":"והן היום (ערב שביעי של פסח) התפללתי בשחרית אצל ג\"ע מאור ישראל מרן בעל יבי\"א שליט\"א, ואחר התפלה שאלתי לפניו, אם נכון לומר שהחרקים והתולעים שאינם נראים אלא ע\"י מיקרוסקופ וכדומה (שהעלה הוא להתירם וכנ\"ל) שאין בהם איסור כלל, משום שעדיין לא באו לגדר של בעל חי, שאינם אלא כפרש בעלמא, ואין זה היתר מטעם אונס משום שאי אפשר לראותם ולא ניתנה תורה למלאכים, אלא מותרים הם משום שאינם תולעים כלל וכנ\"ל. ומרן שליט\"א השיב לי שאכן זו האמת וזה הפירוש האמיתי, ובפירוש נתן הסכמתו שאכתוב כן משמו, ותאזרני שמחה.","b":false},{"t":"ובבואי הביתה השגתי את דברי הבינת אדם הנ\"ל, וראיתי שהדברים מפורשים שם להדיא. וזה לשונו. תשובה. מה שכתב לאסור החומץ הבל הוא, שהרי התורה אמרה בנזיר חומץ יין וכו', וכי התורה תסתום באיסור לאו, ולמה לא תפרש חומץ מבושל, או לומר בעל פה למשה רבינו ע\"ה, הלל\"מ שחומץ צריך בישול, וגם אין לומר שכונתו שחומץ בכֹח יש בו תולעים, דא\"כ גם ביצים לא נאכל, שהרי כתב שבזרע האדם נראה אדם, ובקשר הביצה נראה תרנגולת, ולא אסרה תורה מה שבכֹח אלא מה שיצא בפועל. עכ\"ל.","b":false},{"t":"וממה שכתב בסוף דבריו שיש בו תולעים בכֹח, מוכח להדיא כמו שכתבתי, והכי קאמר, דאפילו תאמר שמה שרואים במראה החומץ ע\"י מכשירים המגדילים, שהתולעים רוחשים שם, אפילו אם אמת נכון הדבר, מ\"מ הוא עדיין בכח, כלומר שרק יש בנקודה זו, או בדבר זה כֹח להוציא בעל חי מסויים, אך לעת עתה עדיין לא יצא מן הכח אל הפועל, והרי הוא כפרח בעץ פרי, שברור לנו שמן הפרח הזה יציץ פרי ויגמול שקדים, אך כל זמן שלא יצא אל הפועל עדיין לא מיקרי פרי, ומתי מגיע לצאת מן הכֹח אל הפועל, קבעו לו זמן, שיתגלה ויראה לעין האדם בראיה רגילה.","b":false},{"t":"ה.","b":false},{"t":"תולעים שאי אפשר לראותם מותרים משום דלא ניתנה תורה למלאכים","b":true},{"t":"ואולם מדברי הרב ערוך השלחן ע\"ה נראה דס\"ל להתיר משום שאין יכולים לעמוד על זה כלל, שא\"א להזהר בדבר שלא רואים אותו בעינים. שהוא ז\"ל דן בחומץ הנ\"ל, ובתוך דבריו (יו\"ד סימן פ\"ד סעיף ל\"ו) כתב, אמנם האמת היא דלא אסרה תורה במה שאין העין שולטת בו, דלא ניתנה תורה למלאכים, דאם לא כן הרי כמה מהחוקרים כתבו, שגם האויר כולו מלא ברואים דקים מן הדקים, וכשאדם פותח פיו בולע כמה מהם, אלא ודאי הבל יפצה פיהם, ואף אם כן הוא כיון שאין העין שולטת בהם לאו כלום הוא. אבל במה שהעין שולטת ויכול לראות אפילו נגד השמש, ואפילו דק מן הדק הוי שרץ גמור. עכ\"ל.","b":false},{"t":"ונראה ממה שכתב, שלא ניתנה תורה למלאכים, דרצה לומר שאכן חשיבי בעלי חיים, אלא כיון שאי אפשר להזהר מהם ע\"כ לא אסרתם עלינו, שלא ניתנה תורה למלאכים.","b":false},{"t":"אמנם ממה שסיים וכתב: כיון שאין העין שולטת בהם לאו כלום הוא, משמע דר\"ל דאין עליהם דין בעלי חיים כלל, ועוד הוסיף וכתב, אבל במה שהעין שולטת וכו', ואפילו דק מן הדק הוי \"שרץ גמור\". וש\"מ דמה שלא נראה לעין אין לו דין שרץ גמור, שהוא עדיין שרץ בכח ולא בפועל. וע\"כ אפשר דמה שכתב שלא ניתנה תורה למלאכים, בא לישב למה חז\"ל לא אסרום והרי הם עתידים לגדול ולהיות תולעים, לזה אמר דכיון שא\"א לראותם לא יוכלו להיזהר בהם, ולא ניתנה תורה למלאכים. וזה נלע\"ד עיקר כונתו, ועיין לעיל מה שפירשתי במה שאמרו לא ניתנה תורה למלאכי השרת.","b":false},{"t":"עוד יש לומר דהכי קאמר, דבע\"כ צ\"ל, שלא אסרה תורה אלא מה שהעין רואה באופן רגיל, דמזה שלא ניתנה תורה למלאכים אלא לבני אדם, מוכיח את זה, דאל\"כ איך סלקא דעתין שהתורה תאסור עלינו מה שאין העין שלנו רואה, וכי מלאכים אנחנו. והוא כמו שכבר ביארתי לעיל.","b":false},{"t":"ו.","b":false},{"t":"בדברי החזו\"א שאוסר בחרקים שאין מבחינים בחיותם וברחישתם","b":true},{"t":"וחתני כבני הרה\"ג רבי עובדיה יוסף נר\"ו, הראני שבשו\"ת חיי הלוי ח\"ג (חיו\"ד סימן נ\"ו אות ה') כתב בשם הגרש\"ז אוירבך זצ\"ל שרצה לומר, שכל שאין מבחינים בחיותם וברחישתם, אין בהם איסור כלל, אלא שחזר בו משום שנודע לו שהחזון איש אוסר בזה ונשאר בצ\"ע. עכ\"ל.","b":false},{"t":"ואבא אל הע'ין והנה החזון איש ביורה דעה (סימן י\"ד אות ו'), כתב בד\"ה ושיעור נימוח, היינו שאין העין מכִּירתו כלל, והילכך מתבטל כדין יבש ביבש, אבל אם העין מכִּירתו כשיפגשנו, אע\"ג שאין כוח באדם לחפש אחריו, חשיב כאיסור ניכר ואינו בטל. ואם אין העין מכִּירתו מחמת קטנותו, ועדיין הוא שלם אינו בטל מדרבנן מדין בריה. והילכך בהני כיני דגים יש לצרף ספק נמוח, דמסתבר שמתבטלת הכרתן ע\"י הבישול, והוי כמו רוב להיתר, וגם אם יש ספק אם הם שלמים אין כאן רק ספק דרבנן של בריה, אבל מסתבר דכיון דבטלה הכרתה חשיב בלבול צורה, ובטל דין בריה. וכמ\"ש בתשובת הרשב\"א שבב\"י (סס\"י ק\"ד). [וע\"ש שכתב דאין חילוק בין נמוח בקדרה, או בפה קודם הבליעה, בכל גוונא יש בזה דין ביטול. ע\"ש].","b":false},{"t":"ואמר לי חתני הנז', שכנראה שלזה כיוונו באומרם שהחזו\"א ע\"ה אוסר גם אם אין החרקים נראים לעין. ואולם כשעיינתי בדברים נראה שמזה אין ראיה, דבאמת קשה שתאמר שרבינו בעל החזו\"א יחלוק על כל הני רבוותא, שאמרו שמה שלא נראה לעין אין בו איסור, ובפרט שכן כתב הרב חכמת אדם, שהחזון איש כתב עליו במקום אחר (בענין מסורת על בהמות וחיות טהורות) שבליטא נהגו לפסוק כדבריו, וכאן לא הזכיר את דעתו כלל, והיא סוגיא בדוכתה.","b":false},{"t":"אלא נראה שהחזון איש כאן לא דיבר כלל על תולעים שנראים רק ע\"י מיקרוסקופ, אלא מדבר בדין בריה, שנפלה תולעת וכיו\"ב לתוך אוכל והיא נראית בעין רגילה, רק שאבדה תוך האוכל, דקי\"ל דבריה לא בטלה אפילו באלף, ומיהו אם נחתכה או נימוחה, בטלה. ובא הרב ז\"ל להגדיר מה נקרא נמוח. וכמו שהתחיל וכתב, ושיעור נמוח היינו וכו', כלומר שבא לתת גדר מה נקרא נימוח שמבטל ממנה דין בריה, ותתבטל בהיתר. ותחילה כתב שאם נתערבה הבריה ולא רואה אותה, אין זה ביטול, דאם יפגשנה יכירנה, וכמובן שכונתו היא דיכירה בעין רגילה, שהרי לא הזכיר זכוכית מגדלת ולא שום כלי, גם לא אמר שאין רואים אותו בעין רגילה, דלא מיירי בבריות שלא נראות לעין כלל.","b":false},{"t":"ומש\"כ ואם אין העין מכִּירתו מחמת קטנותו ועדיין הוא שלם וכו'. אין כונתו לומר שהחרק היה כל כך קטן, עד שאי אפשר לראות אלא במיקרוסקופ, דלא הזכיר כאן מדברים אלו ואפילו לא ברמז. אלא כונת הרב ז\"ל היא שאם נצטמק ע\"י הבישול עד שנשתנה, ורק ע\"י עיון מרוכז רואים אותו בעין רגילה, שכן לא הזכיר שום ענין אחר. ובזה הוא שכתב דאינו בטל מדין בריה, שהרי עדיין נראה בעין רגילה.","b":false},{"t":"ואחר זה כתב דהני כיני דדגים יש לצרף ספק נמוח, דמסתבר שמתבטלת הכרתן ע\"י הבישול, והוי כמו רוב להיתר, ואפילו אם יש ספק אין כאן רק ספק דרבנן של בריה. וגם בפרט זה אינו מדבר אלא מדין נמוח, ולא דן על תולעים שלא נראים ע\"י עין רגילה, וכנראה שכיני דגים הם תולעים קטנים הנראים לעין רגילה, וקשה להוציא את כולם, ולזה אמר שיש בזה גם ספק נמוח כדי לבטלן, ולא נאמר בריה אינה בטלה.","b":false},{"t":"עו\"כ החזו\"א שם, ובמעשה דהט\"ז יש מקום להקל דהמילבי'ן להפלגת קטנותן ודאי אבדו הכרת העין, ויש כאן ביטול יבש ביבש, וגם אם יש ספק בריה הוי ספק דרבנן, וגם על הרוב מתבלבל צורתה ע\"י הבישול. ואפשר דכל שאין העין שולט בו לאו בריה הוא, ולא דנו בסימן ק\"ד אלא בשרץ כעדשה שלדעת רש\"י חשיב בריה, וכו'. עכ\"ל.","b":false},{"t":"והנה כבר הוכחתי לעיל שהמילבי'ן הוא ניכר ע\"י עין רגילה, וכמו שכתבתי לדייק מדברי השאילת יעב\"ץ הנ\"ל. אלא שהם קטנים מאד ולפי הצבע והבישול מאבדים הכרת העין, ושם כתב שבשביל לראותם צריך להעמידם בשמש, או להביט בהם ע\"י זכוכית מגדלת. ובזה יתפרשו גם דברי החזו\"א כאן על נכון, שממה שכתב כאן, במילבי'ן שלהפלגת קטנותן ודאי אבדו הכרת העין. משמע שכל מה שכתב כאן על קטנות, אינו מתכוין לקטנים שא\"א לראותם ע\"י עין כלל, אלא שצריך עיון טוב כראוי. ולא דיבר כלל במקום זה לא במיקרוסקופ ולא בכלי זכוכית וכיו\"ב, כי אינו מדבר בתולעים שאין נראים לעין כלל, אלא בתולעים שנראים לעין אדם רגיל, אלא שכשהם מתערבים ומתבשלים קשה מאד לזהותן, ודן בזה אם עדיין יש עליהן דין בריה ולא בטלי כלל. או שנחשבים דברים אלו כנמוח ושוב לא חשיבי בריה, שכן בריה שנחתכה בטלה חשיבותה, ומתבטלים כדין יבש ביבש. זה הנראה לענ\"ד בהבנת דברי גאון זיע\"א, ומה שאומרים בשמו איננו כאן, גם לא ראיתיו בכל הסימן הזה (סימן י\"ד) שהוא הסימן הדן בהלכות תולעים, ואולי סמכו על דבריו במקום אחר. ועוד חזון למועד אי\"ה יתברך.","b":false},{"t":"ז.","b":false},{"t":"בנקודות שרואים ע\"ג פירות ואי אפשר לזהותן אלא ע\"י מיקרוסקופ אם הם חרקים אם מחוייב להסירם קודם אכילה","b":true},{"t":"והנה במה שכתב כב', עולה דלפעמים רואים נקודה על גוף התות, אלא שאי אפשר לזהותה אם תולעת היא, או לכלוך בעלמא, ובבואה לפני עין המיקרוסקופ, אזי ניתן להבחין ולקבוע מהותה של נקודה זו. וכב' מדגיש, שגם האומן אינו יכול להבחין טיב הנקודה ההיא, רק על ידי המכשירים המיוחדים, אבל למראה עיניו אינו יכול להבחין בה כלל כדי להכיר את מה שטמון בה.","b":false},{"t":"ויש לחקור בזה אם ראיית הנקודה חשיבא כראיית התולעת, ואסור לאכול פרי זה, שאף על פי שאינו רואה בעינו מהותה של נקודה זו, על כל פנים זה מודיע שיש ריעותא בפרי זה, דהוי ספק אם תולעת או לכלוך, ויאסר באכילה עד שיבדוק אותה ויברר ענינה. או נימא דכיון דבעין לא רואים כי אם נקודה, וגם המומחה לא יכול לדעת מה היא, עדיין נחשבת לדבר שלא רואים בעין, ולא אסרתו תורה.","b":false},{"t":"ולפי מה שכתבתי לעיל, דכל זמן שלא רואים התולעת עדיין לא חל עליה איסור, אעפ\"י שרואים אותה ע\"י מכשירים, וברור לנו שהיא תולעת, עכ\"פ עדיין אינה בפועל אלא בכח, ולא נאסרה. יש מקום חשוב לומר, שגם בכה\"ג שרואים אותה נקודה בעין, כיון שאין שום אפשרות לקבוע מהותה בלי מכשירים מיוחדים, עדיין לא הגיעה לכלל בעל חי, ולא נאסרה. ועוד אפשר לומר דגם אם בדקו הנקודה, ואמרו שהיא בודאי תולעת, עדיין היא בהיתרה. דזה דומה עדיין לביצית או לניצן של הפרי, שאפילו שרואים ויודעים בבירור שממנו יציץ ציץ ויגמול שקדים, מ\"מ לעת עתה אינו כלום, הכא נמי לעת עתה עדיין התולעת נמצאת רק בכוח ולא יצאה לפועל, ואין בה איסור.","b":false},{"t":"ואם נכון הוא דבר זה, יוצא דגם אינו חייב לבדוק ואפילו ראה את הנקודה, ויש חשש גדול שהוא חרק, עם כל זה אינו חייב לבודקה, דגם אחר שיתברר שהוא באמת חרק, עדיין אינו נקרא חרק ממש, שעדיין אינו בפועל אלא בכוח ומותר.","b":false},{"t":"ומה שרואים בנקודה צורה ברורה של חרק ע\"י המכשירים המיוחדים אין זה כלום, שגם בקשר של ביצה רואים צורת תרנגולת, וגם ברור לנו שתצא ממנה תרנגולת, וגם בזרע אדם רואים ע\"י המיקרוסקופ צורת אדם, וברור שאם ישתמשו בו נכון, יוולד ממנו אדם, ואעפ\"י כן אין לזה דין אדם לשום ענין כלל, ואם יקח זרע הנתון בכלי וכדומה וישפכנו על הארץ אין בו איסור, ובודאי לא שייך למאבד נפש ח\"ו. ואיסור הוצאת ז\"ל הוא ענין אחר לגמרי, שבפעולה זו יש עוון חמור מאד רח\"ל, אבל אם יקח מבית חולים צנצנת זרע וישפכנה אין בו שום קשר עם מאבד נפש, אעפ\"י שעתיד לצאת מזה אדם חי ובריא. וכן נמי מותר לבשל הביצה בחלב ולאוכלה, דאין לה דין של תרנגולת. וה\"נ הגם שיש צורת חרק או תולעת לאותה נקודה, מאחר ובעין רגילה אין לזה צורת תולעת או צורה אחרת ורק נראית נקודה, ולא רוחשת כלל, רק עומדת על עומדה בלי תנועה כלל. אין לחוש לה. וע\"כ אין חייבים לבודקם ע\"י מכשירים. [א\"ה חתן הרמה\"ח שליט\"א, ולכאורה אפשר לחלק דשאני לענין זרע של אדם וביצת תרנוגלת, שהרי זה מחוסר מעשה כדי שיתפתח, ולכן אינו נחשב עדיין בכלל בעל חי, משא\"כ בנ\"ד שהתולעת גדילה מאליה, ומחוסר זמן לאו כמחוסר מעשה, וממילא אפשר לומר שכבר מעתה יש עליה תורת בעל חי, ורק האדם אינו מבחין בה. ושו\"ר בתשובה הבאה שכתב לדון בחילוק בכיו\"ב].","b":false},{"t":"וכעת הראוני דברי הגאון אגרות משה חיו\"ד (ח\"ב סימן קו\"מ) שכתב וז\"ל, ומה שכת\"ר כתב ודימה את זה למה שמותרים לאכול הדברים שנתחמצו, הגם שידוע שהחימוץ מתבצע ע\"י תולעים, ורואים אותם ע\"י המיקרוסקופ, והטעם מפני שהתורה לא אסרה אלא תולעים ורמשים שנראים לעין, וכמו ששמע מפי זקנו הגאון ר' שמחה זעליג זצ\"ל שאמר שכן שמע משם הגאון ר' חיים מבריסק זצ\"ל. והאגרו\"מ הוסיף דבעצם לא היה צריך להביא מדברים שנתחמצו, דהא כל האויר מלא שקצים ורמשים כאלו, ובכל נשימה האדם בולע אלפים ואולי מיליונים מהם, ובהכרח שאינם בכלל הרמשים שאסרה התורה. ע\"כ.","b":false},{"t":"והנה גם הוא ז\"ל סובר דכל זמן שלא נראים לעין האדם, אינם בכלל התולעים שאסרה תורה, וכתבו כן משם הגאון ר' חיים מבריסק ע\"ה, וזה סיוע גדול לכל מה שביארתי בזה.","b":false},{"t":"וכן כתב גם באגרות משה ח\"ג מאה\"ע (סימן ג\"ל), שאין שום איסור כלל בשקצים הנראים ע\"י מיקרוסקופ, כל זמן שאין רואים אותם בעין רגילה וז\"ל תוך הדברים, וכמו שרצים שלא נראו לעין אלא ע\"י דבר המגדיל שאינו כלום דהא כל האויר שאדם שואף לתוכו הוא מלא משרצים כאלו שנקראו מיקראבין שע\"י ספאקטיווע המגדיל ערך אלף פעמים ויותר הן נראים ואין שום איסור בזה, וכמו כן מה שנראה הפסק באות בתפילין ומזוזות ע\"י ספאקטיווע ולא נראה לעין בעצמו לא נחשב הפסק וכשר, וכדומה הוא בהרבה ענינים וכו', ומתוך זה יצא לדון שחרש ששומע רק ע\"י מכונה מיקרי חרש יעו\"ש.","b":false},{"t":"והלום הראני חתני הנ\"ל נר\"ו שבספר ילקוט יוסף (של הגאון רבי אבהו שליט\"א) ח\"ט (או\"ה ח\"ב סימן פ\"ד, עמוד קצ\"ה) בסוף ד\"ה וכיוצא בזה וכו', כתב וז\"ל: גם בספר ארחות רבינו הקהלות יעקב ח\"ג כתב משם הגאון חזון איש והגאון קהלות יעקב ע\"ה, דראייה ע\"י מיקרוסקופ אינה חשיבא ראייה כלל. עכ\"ל. וגם ספר זה אינו עמי.","b":false},{"t":"עו\"כ בילקו\"י שם (עמוד רכ\"ב) בד\"ה והגרש\"ז אוירבאך זצ\"ל הובאו דבריו בספר שמירת שבת כהלכתה ח\"א (פ\"ג הערה ק\"ה), דלכאורה אם אי אפשר שיגיעו למצב כזה, שיהיה אפשר להבחין בחיותן וברחישתן, לא שייך בכלל לכנותן בשם שרץ השורץ. ואמנם לאחר זמן חזר בו, אחר שנודע מבאי ביתו של החזון איש שחשש בזה לאיסור תולעים. וגם נודע לו כי לפני שהכנימות מתכסות בקליפת המגן, גם בעין רגילה יכולים להרגיש ברחישתן. וראה בהקדמה לספר זכרון שאול ח\"א להגר\"ש ברזם זצ\"ל, שחקר את הנושא. ע\"כ.","b":false},{"t":"והן הם הדברים שכתב בשו\"ת חיי הלוי משם החזו\"א וכנ\"ל. ומה שהוסיף על הכנימות צריך לי עיון בדבר.","b":false},{"t":"והנה לפי מ\"ש הגרש\"ז אורבך זצ\"ל שהכנימות רוחשות קודם שמתכסות בקליפת מגן, דבר זה צ\"ע לעצמו, ועוד צ\"ע אם זה שוה בכל הפירות, כגון התותים שבהם אנו דנים, אם אותם נקודות ג\"כ רוחשות, ואם נראה הדבר בעיון טוב ע\"י עין רגילה בלי מכשירים.","b":false},{"t":"והנראה לעניות דעתי בזה, דהטוב להדר ולרחוץ על ידי חומרים מתאימים, שהרי כב' כתב שבמכון הוולקני שע\"י משרד החקלאות, ערכו בדיקה מקצועית ע\"י שהשרו התותים במים וסבון במשך עשר דקות, ושפכו את המים דרך מסננת, ובדקו את הממצאים שעל המסננת ע\"י זכוכית מגדלת, והבודק מצא חמשה חרקים שהועברו לצלוחית עם אלכוהול לבדיקה של \"בניקולר\" שהוא מיקרוסקופ משוכלל, ובזה וידאו שאכן מדובר בחרקים, ואח\"כ בוצעה השריה נוספת של התותים במים וסבון, ושפכו המים דרך המסננת, והתגלו עוד שני חרקים, זה היה בתותים בגידול ביו אורגאני, ואח\"כ בדקו את התותים שגדלו גידול רגיל, ובבדיקות כהנ\"ל התגלו רק שני נשלים כי החרק התפרק מזמן, וכן התגלה חרק אחד. ומזה הסיק הרב השואל שהם בגדר מיעוט מצוי. והדגיש שחלק מן החרקים רואים בעין רק נקודה שגם המומחה לא יכל לזהות את מהותה, כי אם ע\"י המיקרוסקופ כהנ\"ל.","b":false},{"t":"ועל כל פנים למדנו שע\"י שריה במים וסבון במשך עשר דקות, יורדים אותם חרקים מהתותים, ואמנם בשריה נוספת ירדו עוד שנים מהם. והנה לפי המבואר עולה שאין בהם איסור ואין חייבים לבדוק אותם, אך מהיות טוב, עדיף למי שרוצה להתרחק מחשש איסור שבזמן שמודיעים שיש בהם תולעים וכו'. לנהוג בהם כדלהלן: ראשית יחתוך בסכין את הפרח המעטר את ראש התות עם השכבה העליונה שמתחת לפרח, ששם הוא מקום מחבואם, שדרכם לחפש מקום מוסתר ככל האפשר. ולאחר מכן ישרו אותם במים וסבון במשך עשר דקות, ואח\"כ ישפשפו כל אחד בזרם מים חזק, וטוב שיבדקו אותם בראייה טובה במקום שיש בו אור טוב, או לאור השמש. ואז יאכלו ענוים וישבעו. ואם רוצים להניחם ליום או יומיים יניחו אותם במקרר, שלא יתפתחו חרקים אחרים, אבל הטוב ביותר שכל זה יעשו סמוך לאכילה. ויאכלו אותם תיכף באופן שאין חשש להתפתחות נוספת של חרקים.","b":false},{"t":"זה הנלע\"ד בענין התותים. לעת עתה עד שנברר דעת המומחים לגבי כמה שאלות העומדות על הפרק. ועוד חזון למועד אי\"ה. וה' יצילנו מכל מכשול ותקלה לעד אמן.","b":false},{"t":"[ועיין עוד במה שכתבתי בתשובה הבאה].","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"בעניני תולעים שאינם נראים כי אם ע\"י מיקרוסקופ","p":[{"t":"בעהית\"ש. ברביעי בשבת שמנה ועשרים יום בניסן התשס\"ט","b":false},{"t":"א.","b":false},{"t":"אם יש חילוק בין חיידקים זעירים שאינם נראין אלא ע\"י מכשיר מיקרוסקופ לבין תולעים קטנים מאד אשר אינם נראים אלא ע\"י המיקרוסקופ הנ\"ל","b":true},{"t":"בתשובה הקודמת נשאלתי בענין התותים, והעליתי שהתולעים שאינם נראים לעין רגילה, אין להם דין תולעים ואין בהם איסור כלל, ורק כשיתפתחו ויגיעו לשלב שהם נראים בעין רגילה, אזי הם נחשבים לשרצים ורמשים שאסרה תורה.","b":false},{"t":"וידידי הרש\"ז ריוח שליט\"א יו\"ר המכון למצות התלויות בארץ והרב של מושב בית עוזיאל, שלח לי צילום של \"קונטרס עין לא ראתה\", מאת הרה\"ג רבי ישראל דוד הלברשטאם זצ\"ל מלונדון, והוא סובב הולך לדחות דברי כל המתירים בתולעים וחרקים שלא נראים, ויצא בכחא דאיסורא, ומפני שכתב סברות יפות לחלק בין חיידקים ומיקרו'ב, ובין התולעים הקטנים מאד שלא נראים בעין כלל, אבל סופם להתפתח ולגדול, וגם דן בדברי האחרונים כיד ה' הטובה עליו, עברתי על דבריו בעיון הראוי כדי לשוב ולבחון את אמיתות הענין, ולאסוקי שמעתתא אליבא דהלכתא, כי תורה היא, ואני תפילתי לה' שלא יסיר מפי דבר אמת, ויכין צעדי להלך באמיתו לעד, ולא נבוש ולא נכלם ולא נכשל לעולם ועד.","b":false},{"t":"והנה הרב ז\"ל הקדים שמתוך עיון בסוגיא זו ראה שגם הסברא המוזכרת באיזה מאחרוני זמנינו, שדבר שאינו נראה לעין אין בו איסור, ולדעתו סברא זו ליתא, וכתב: אמנם בזה איני אומר קבלו דעתי, כי סוף כל סוף סברא זו מוזכרת באיזה אחרונים, אבל אני לעצמי ברור לי שליתא לסברא זו, וכמו שהבאתי בתשובתי ראיות עצומות נגדה. וגם ביררתי שעיקר ההכרח שלהם שדבר שאינו נראה לעין אין בו איסור, הוא ממה שנתגלה שיש באויר ובמים אלפים ורבבות שרצים שנראים ע\"י מיקרוסקופ, והם הבאצילע'ן והמיקראבע'ן [ר\"ל חיידקים ומיקרובי'ם] ואם דבר שלא נראה לעין אסור, אי אפשר לחיות, ובע\"כ צריך לומר שדבר שאינו נראה לעין אין בו איסור. אמנם לדעתי שלש תשובות בדבר.","b":false},{"t":"בראשונה כתב לחלק דשאני חיידקים ומיקרוב'ים, שלעולם לא יתגדלו, אלא ישארו בקטנותם לעולם, משא\"כ שרץ קטן שאעפ\"י שלא נראה לעין, מ\"מ לאחר זמן יגדל ויהיה אסור מן התורה. וע\"כ אסור גם מקודם. ואיך נאמר על שרץ שאסרה תורה, שאין בו איסור משעת לידתה, אלא פתאום באמצע חייו, כשמתחיל להראות לעין האדם, חל עליה איסור מן השמים, זה אי אפשר. אלא פשוט וברור ששרץ שאסרה תורה, אסור משעת לידתו, משא\"כ חיידקים שלעולם לא יגדלו אפשר שלא אסרתם התורה כלל. וכתב שכ\"פ הגר\"מ שטרנבוך שליט\"א בתשובה, וכ\"כ בשו\"ת מחזה אליהו (סימן צ\"א), מדברי הרשב\"א במקואות. ע\"כ.","b":false},{"t":"ב.","b":false},{"t":"סברת ההיתר באכילת בע\"ח וחרקים וכדו' אשר אינם נראים לעין אדם","b":true},{"t":"ואחר המחילה רבה, כשנעמיק בדבר יותר, נראה שאין בכוחו של חילוק זה לאסור התולעים שלא נראים לעין, דזה ברור שהתורה לא אסרה מה שלא נראה לעינים, דבזמן שאסרה תורה את התולעים, וגם דורות רבים מאד אחרי זה. לא היה מיקרוסקופ, ולא היה אפשרי לראות אותם תולעים וחרקים שהם דקים כ\"כ, וממילא לא היה שייך ליזהר מהם כלל וכלל, אא\"כ לא יאכל כלום ולא ישתה כלום, דאיך ידע ממה ליזהר, ובעל כורחינו לומר, שהתורה לא אסרה אלא מה שהעין רואה בלבד. ומעתה החקירה איננה אם הדבר אסור או לא, אלא מדוע אינו אסור. ויש שתי אפשרויות להסביר ענין זה. הראשונה היא משום שאין אפשרות ליזהר ולא ניתנה תורה למלאכים, והפירוש הזה קשה, שעולה ממנו דבאמת התולעים הקטנים הבלתי נראין אסורין באכילה, ומה שאין אנו נמנעים מלאכול פירות אע\"פ שיש בהם מן התולעים הקטנים הללו הבלתי נראין הוא משום שאי אפשר, ודומה לאנוס דרחמנא פטריה, ולהכי מותר, ואה\"נ דבמקרה שניתן לברר לכאורה יהיה אסור, לפי טעם זה. וע\"י המיקרוסקופ ניתן להבחין ולהשמר. ואולם אם זה נכון, יתחייב הבא לאכול להעביר כל פרי וכל ירק (ששייך שיהיו בו חרקים) תחת עין המיקרוסקופ, ויהפך המיקרוסקופ למצרך חובה על כל שולחן, אפילו יותר מהמלחיה.","b":false},{"t":"ולכן כתבתי דלענ\"ד יש דרך אחרת להסביר ענין זה, שהטעם הוא, שהתורה לא אסרתם אלא משעה שהגיעו לגודל הנראה לעין אדם רגילה, וכמ\"ש בתשובה הקודמת, דאחר שברור לנו שקודם שהעין קולטתם אינם אסורים כלל, נראה שהסברא הישרה היא, שאין בזה איסור בשלב הזה.","b":false},{"t":"וכבר כתבתי שם, דלכל דבר יש שלב מסויים שבו חל עליו הדין, שהתורה קבעה לו, וכמו שהתרנגולת צריכה שחיטה ואסורה בחלב, והביצה מותרת בחלב, ואינה צריכה שחיטה, ולא מיקריא בריה, אעפ\"י שברור כשמש שממנה יתפתח אפרוח ויהיה לתרנגול, עכ\"פ עתה עדיין לא הגיעה לשלב זה. וכן הפרי בעודו ניצן אעפ\"י שהוא הפרי גופו, עדיין לא חלים עליו דיני הפרי, ואפילו כשיצא הפרי גופו, כל זמן שהוא קטן אין חלים עליו לא חיובי תרומה ולא חיובי מעשר, וה\"נ בחרקים יש שלב שבו חל עליהם האיסור, ובשלב שעדיין לא נראה אינו אלא דבר מה שעתיד להיות לבעל חי.","b":false},{"t":"צא וחשוב בתולעי משי, המטילים בצים לרוב וידוע שמכל אחת יצא זחל, שנהפך עם הזמן לגולם ואח\"כ לפרפר, ואח\"כ ממנו התולעת, ואטו הביצה יהיה לה דין תולעת? וכן אפילו בצית של אדם המונחת במעי אשה שממנה עתיד לצאת אדם שלם, אין לה עדיין הדין של אדם, עד שתתפתח ותהיה אדם, ואין לומר שאני ביצית של אדם הצריכה פעולה של הפריה, דיש כאלה שצריך הפריה מצד אחר, ויש שמאליו זה מתפתח כמו ביצי התולעת, עכ\"פ רואים שלא משעת ההיווצרות או הלידה זה נאסר אלא יש לכל דבר ודבר העת הראויה לו, וה\"נ אחר שברור לנו שלא נאסר, מהתורה ולא מדרבנן אלא עד בא עת שהעין מבחינה בו, וכמו שביארתי, נראה בפשיטות דעד אז אין לו דין בעל חי כלל, אלא הרי הוא כמו ביצה של תרנגולת, או שאר בע\"ח המטילים ביצים, דאע\"פ שעתיד להתפתח ולצאת ממנו בע\"ח, מ\"מ לע\"ע איננו בע\"ח, וה\"נ לא שנא, ורק שכאן לא נוצר בצורת ביצה, אלא יצור קטן כ\"כ שאין עין שולטת בו, וזה נחשב כשלב של ביצה, ובהגיעו לגודל שאדם יכול לראותו, היא עת לידתו ובקיעתו, ורק אז חל עליו האיסור שאסרתו תורה ולא קודם. ועוד, מי אומר שאין זו סוג של ביצה שמתפתחת לתולעת. ואם משום שבמיקרוסקופ רואים צורת בע\"ח, הרי גם בביצה רואים צורת תרנגולת.","b":false},{"t":"ועוד שאין הכרח לחלק בין מיקרוב לחרק קטן, דאם זה נקרא בעל חי, אע\"פ שאינו נראה, מי התיר את המיקרוב, והרי אותם ידים ורגלים יש להם, ושניהם שורצים או מעופפים, ומי מדד בשעלו לחלק מה עתיד לגדול ומה לא, ויצטרכו בכל דבר להביא מכשירים לראות בהם, וגם מומחים להבחין ולחלק וכו', והפשוט והישר הוא, שאחר שזה ברור בלא ספק שהאיסור חל רק על דבר הנראה לעין, דלא יתכן לומר שגם מה שלא נראה בעין אסור, דאיך תאסור התורה מה שלא היה אפשר לראות כלל, וגם מה שלא היה אפשר לדעת ממנו בעת ההיא. ומעתה אין לחלק בין זה ובין זה, וכל מה שלא נראה לעין אדם אין בו איסור כלל, והוא כביצה של תולעת ותו לא מידי.","b":false},{"t":"תדע שגם עובר במעי אמו קודם מ' יום אין לו דין של אדם ממש. ואפילו אחר מ' יום שדרש רבי ישמעאל בסנהדרין (נ\"ז ע\"ב), שופך דם האדם באדם דמו ישפך, איזהו אדם שהוא באדם, הוי אומר זה עובר שבמעי אמו. מ\"מ להלכה לא נפסק כן, שהרמב\"ם ז\"ל (בהלכות רוצח פ\"א ה\"ו) כתב אחד ההורג את הגדול, או את הקטן בן יומו וכו', והוא שכלו לו חדשיו. אבל אם נולד לפחות מתשעה חדשים, הרי הוא כנפל, עד שישהה שלשים יום, וההורגו בתוך שלשים יום, אינו נהרג עליו. עכ\"ל. וק\"ו לעובר אפילו אחר ארבעים יום דבודאי לא נהרג עליו. ואין לו דין אדם להתחייב עליו מיתה.","b":false},{"t":"ואם משום שבמיקרוסקופ רואים צורת התולעת ברגלים וכנפים, הלא גם בביצה רואים צורת תרנגולת במיקרוסקופ, וכן בזרע האדם והבהמה, ופרי קטן, ואפילו עובר קטן שעדיף מהם, דרואים בעין ועדיין אין בו הדינים של הגדול, ועל אחת כמה וכמה באלו שבהן אין רואים כלום. באופן שגם אם מצינו לומר חילוק בין החיידקים לתולעים הזעירים, מ\"מ אין בכוח החילוק הזה לאסור התולעים שאינם נראים לעין.","b":false},{"t":"ג.","b":false},{"t":"אכילת ובליעת חרקים שאינם נראים אינה דרך אכילה ובענין בע\"ח ב\"כח\" ולא ב\"פועל\"","b":true},{"t":"עו\"כ שם באות ה', עוד יש לחלק דשאני מיקרובי'ם שאין בהם ממש אלא הם כעננים וכאויר עבה, שלא יצאו מן הכח אל הפועל, ואם לא יאכל אדם כלום ולא ישתה כלום, אלא יבלע כל היום מיליוני מיקרוב'ים, מ\"מ ימות ברעב, משא\"כ שרצים קטנים שכבר יצאו מכח אל הפועל, אלא שאינם נראים לעין, ואם יאכל מהם הרבה, יחיה וישבע, בודאי שהם אסורים, שיש בהם ממש והם בני אכילה ושתיה, משא\"כ מיקרובי'ם, וכו', ובאמת איני יודע היאך אפשר להעלות על הדעת, שהתורה תאסור דבר שאין בו ממש ואינו בר אכילה, וכבר הבאתי ראיה חותכת, שהרי עננים שאנו רואים אותם בעינינו כאויר, ואעפי\"כ אנו נושמים ובולעים אותם ביום הכיפורים, וע\"כ הטעם הוא משום שאין בהם ממש, ועדיין לא יצאו מן הכוח אל הפועל, וע\"כ אין בהם שום איסור אפי' אם נראין לעין, וכ\"ש החיידקים ומיקרובי'ם. עכ\"ל.","b":false},{"t":"ואחר המחי\"ר אטו שייך דרך אכילה בחרקים שעין אדם לא רואה אותם כלל, ומה הבדל בינם ובין החיידקי'ם שכל כך פשוט לו שאין בהם איסור, עד שהרבה לתמוה, איך אפשר להעלות על הדעת שהתורה תאסור דבר שאין בו ממש ואינו בר אכילה, עכ\"ל. וא\"כ גם התולעים הקטנים אינם בני אכילה ואין בהם ממש, שאין נראים לעין ואין חוש המישוש שולט בהם, ומי גילה לו רז זה שאמר, שאם יאכל הרבה שרצים קטנים שאין נראים לעין שישבע, ולא זכיתי להבין מנין קבע קביעה כזאת בלא בדיקה ובלא חקירה, ואדרבה נראה פשוט שהם ממש כחיידקים, ולא תשבע נפש באדם לא מאלה ולא מאלה, והם באותו גודל ובאותה מציאות, וההבדל היחידי הוא מה שכתב שם באות א' הנ\"ל, שזה עתיד לגדול ולהתפתח וזה לא משתנה, וגם בזה צ\"ע עוד. ועוד שכבר כתבתי שאין בכוח החילוק הזה לעשות נפקא מינה לדינא, וכנ\"ל. דלעת עתה שוים הם, ולא זה מה שאסרה תורה, גם מ\"ש שתולעים זעירים שאין העין שולטת בהם, הם בני אכילה ושתיה, משא\"כ מיקרובים, מנין לו זאת, והלא עינינו רואות שביצת תרנגולת מתקיימת בלא אכילה ובלא שתיה, ובבא היום מתפתחת ובוקע ממנה אפרוח חי ונושם, וכן שאר ביצים, וכן ביצי תולעים, וגם הזחל חי בלא אכילה ושתיה ויש עוד דברים רבים כאלה, וממתי ראה תולעים קטנים שאינם נראין לעין אדם שהם ברי אכילה ושתיה, ואם ידוע לו כן מספרים או ממדענים, הרי מסתמא שאין זה דרך אכילה הרגילה ולא שתיה רגילה, ועוד דמסתמא שגם החיידקים דרכם בכך ואין הבדל.","b":false},{"t":"עוד כתב שם שבבינת אדם כלל ל\"ח כתב שההיתר הוא משום שלא יצא מכח אל הפועל, וכתב דלפי זה תולעת קטנה להרב בינת אדם, או טיפת דם שיצאה מכח לפועל אסורים אפילו אם לא יהיו נראים לעין לעולם. ע\"כ.","b":false},{"t":"ובמחכ\"ת אינו נכון, ואדרבה מדברי הרב בינת אדם הנז' הוכחתי בתשובתי הקודמת, שתולעים זעירים עוד לא יצאו אל הפועל, שהרי לא חילק כלל בין חיידקים ליצורים זעירים, אלא סתם והעלה שכל שאין עין אדם שולטת בו, הוא עדיין בבחינת כח, ולא יצא אל הפועל, ולא נאסר.","b":false},{"t":"ועוד שהרב בינת אדם שם כתב על דברי ספר הברית, גם אין לומר שבחומץ יש בכוח תולעים ולכן הוא אסור, דא\"כ גם ביצים לא נאכל, שהרי כתב שבזרע האדם נראה אדם, ובקשר הביצים נראה תרנגולת, ולא אסרה תורה מה שבכח, אלא מה שיצא אל הפועל. עכ\"ל. ומזה שכתב שא\"כ נאסור הביצה משום שנראה בה תרנגולת, ולמעשה לא אסרינן לה כלל, ואע\"פ שנראה בה תרנגולת, ועתיד לצאת ממנה תרנגולת, והיא בת אכילה. וא\"כ הוא לא אמר את זה רק במיקרובי'ם שאינם עתידים לגדול ולהתפתח, ולא ברי אכילה, אלא גם בדבר שהוא בר אכילה, וגם עתיד לצאת ממנו תרנגולת. מ\"מ כיון שלעת עתה אין התרנגולת נראית בעינו של אדם עדיין מיקרי שהיא בכח ולא יצאה לפועל ומותרת. וה\"ה והוא הטעם לתולעים זעירים שלע\"ע אינן נראים לעין, שנחשבים שהן רק לדבר שבכח ולא בפועל, ומותרים הם, ואין בכח אותם חילוקים לאוסרם, והחכמ\"א בבינת אדם התיר כל מה שלא נראה לעין וזה ברור בס\"ד.","b":false},{"t":"ד.","b":false},{"t":"חיידקים המתפתחים במאכלים אם יש להם דין שרץ העוף או חשיב כצומח","b":true},{"t":"עו\"כ שם (אות ג'), דהחיידקים אינם כלל במציאות של \"שרץ העוף\" שאין להם כנפים, ולא כוח לעוף, ומה שנראה במיקרוסקופ שמעופפים, אינו מכח עצמם אלא מפני קלותם הם נישאים ברוח, וגם אפשר שכוח המשיכה לא שולט עליהם, (וכתב מה שהיה עם האסטרונאוטים בחלל, שהוא חוץ לשליטת כוח המשיכה), והחליט שלחיידקים אין כוח תנועה כלל רק הרוח מוליכתם כעלים קלים הנישאים ברוח, ולכל היותר החיות שלהם כמו של צומח, ואין דמיון לתולעים זעירים, שהם מתנועעים מכוח עצמן, והם שרץ גמור גם קודם שנראה לעין. וכתב שכ\"כ בשו\"ת להורות נתן בשם הרה\"ג ר' ישראל וועלץ בספרו שו\"ת דברי ישראל, בשם חכמי הטבע שהחיידקים הם צומח ולא בעל חי. עכ\"ד.","b":false},{"t":"ואע\"פ שקשה לומר שהתולעים שנראים תוך החומץ, שהם הופכים היין לחומץ שהם צומח, וכן במים ובאויר וכו', וכגון דא צריך מומחה, וספק אם המומחים עצמם יש להם הגדרה ברורה בזה, וגם אם נקבל את דבריהם במלואם, י\"ל דגם התולעים והחרקים בעוד שלא נראים לעין, הרי הם כמו החיידקים, והתנועות שרואים אצלם דרך המיקרוסקופ, אינם מכח חיותם, אלא מחמת קלותם נישאים ברוח ונזרקים לכל עבר, עד שנדמה כאילו הם הולכים ומתנועעים. ושרש הבנת דברים אלו הוא בזה, דבתורה לא נאמר שחיידקים מותרים, וגם לא בשום הלכה, רק הפוסקים העלו שמה שאין העין שולט בו, לא אסרתו תורה, ובזה גם הוא יודה, דלא יעלה בדעת שנתחייב לבדוק כל דבר במיקרוסקופ קודם אכילה, וגם לבדוק אח\"כ במעבדה ע\"י מומחים שיאמרו אם זה חיידק או תולעת, וזה בעוד שבזמן שהתורה ניתנה וגם במשך דורות עולם, לא היו מכשירים אלו קיימים כלל, ולא ידעו מהם. וגם לא ידעו שיש תולעים או חיידקים שאין העין שולטת בהם כלל, ושצריך לדון עליהם אם הם אסורים או מותרים.","b":false},{"t":"והחכמים שהתירו כל מה שהעין לא רואה אותו, הטעם הוא, מפני שהם סבורים שהאיסור של תורה חל רק במה שהאדם מסוגל לראות, דאי אפשר שתאסור מה שאי אפשר לראותו, ואין עין אדם שולטת בו. ולא נכנסו לחילוקים אם זה שרץ העוף או צומח, ואם הוא חיידק או מיקרו'ב, או חרק שעדיין לא הגיע לכלל דבר שעינו של אדם מבחינה בו. רק אמרו מה שהעין לא רואה אינו אסור, ותו לא מידי. וכל החילוקים האלו היו שייכים רק אם היתה הלכה שחיידקים מותרים, ובאים ללמוד מזה היתר לחרקים ותולעים זעירים, אז צריך לחקור אם הם דומים, ואז היה מקום לחלק בין אלה ובין אלה. אבל לא כן הדבר, אלא שקבעו הפוסקים מתוך הכרח המציאות, שלא יתכן שהתורה אסרה את מה שלא נראה ע\"י העין. ולא דיברו על חיידקים כלל, דמאן דכר שמייהו בתורה, אלא אדרבה דיברו בהדיא על תולעים ובע\"ח שאותם אסרה התורה, ועל זה אמרו, דלא אסרה תורה אלא מה שהעין רואה בלבד. אבל מה שרואים ע\"י מיקרוסקופ לא נכלל באיסורי התורה. ובאו עוד אחרונים לחזק היתר זה, ואמרו דאם נחשוב שגם מה שהעין אינה רואה אסור, אז לא נוכל לאכול ולשתות מאומה ואפילו לנשום לא יותר לנו, שהרי כל המים וכל האוכל, וגם האויר הכל מלא חיידקים לאין מספר.","b":false},{"t":"ועוד גם התולעים שאין נראים מי אמר שהם הולכים או עפים, הא אינם אלא כמו כתם של לכלוך בלי תנועה ובלי צורה, ועפי\"ר אין נראים כלל, אלא שטוען הרה\"ג הנ\"ל, שעתידים לגדול ולהתפתח וגם לעוף וללכת, ורוצה לאוסרם ע\"ש העתיד. וכבר הוכחתי מן האדם ומכל חי, וגם מן הצומח, שיש זמן לכל דבר ואין דנים ע\"ש מה שעתיד להתפתח. ועוד דמי יבדוק ויבחין בין אלה ובין אלה, ומי יפסוק מה זה ומה זה, וכבר כתבתי מזה למעלה.","b":false},{"t":"עו\"כ, כב' הרב הנ\"ל ע\"ה שם, היוצא לנו מכל הנ\"ל שאין שום ראיה מהחיידקים ומיקרובי'ם שדבר שאינו נראה לעין אין בו איסור, דשאני מיקרובי'ם וכו', וכיון שניטלה הראיה ונפל היסוד נפל כל הבנין שלהם וכו'. ע\"כ.","b":false},{"t":"והם הן הדברים שכתבתי שהמחבר הזה ע\"ה, מדבר כאילו כתוב בתורה או לפחות בשו\"ע שהחיידקי'ם מותרים, ומהם למדו האחרונים להתיר כל שאין העין שולטת בו, והוא מסיר ראייתם ונוטל את היסוד שעליו בנו בנינם. ולא היא, אלא היסוד והבנין כולו הוא בנוי על המציאות הפשוטה, שהתורה לא אסרה כל דבר שהעין לא רואה אותו, וממילא אין מקום לכל דבריו בזה.","b":false},{"t":"ה.","b":false},{"t":"בדברי הגאונים שהתירו בעלי חיים שאינם נראים","b":true},{"t":"עו\"כ שם, ובאמת לא מצאנו שום פוסק מהדורות שלפנינו שיתיר דבר שאינו נראה לעין, ומ\"ש ערוה\"ש (סי' פ\"ד סל\"ו) וכן מה שמביאים בשם הגר\"ח מבריסק ז\"ל (כונתו למה שכתב הגאון אגרו\"מ) שתולעים שלא נראים לעין מותרים, היינו שלא יהיו נראים לעולם כמו מיקרובי'ם, אבל תולעים שיראו במשך הזמן לעין ואותם התורה אסרה, אסורים הם גם קודם שנראים לעין. ואין כוח לשום אחרון לחדש שיעור חדש שלא נזכר בשום ראשון ובשום אחרון מגדולי האחרונים. עכ\"ד.","b":false},{"t":"והנה מלבד שהחכמת אדם לא דן על מיקרו'ב, אלא על תולעים שבחומץ שאינם נראים לעין, ואחר המחילה מכב' תורתו של המחבר הזה ע\"ה, לא בדק אם לא גודלים, וידוע ומפורסם שאם מניחים החומץ בלי טיפול ראוי, שבסופו מתמלא תולעים הנראים לכל עין, ועיני ראו ולא זר יין שהתקלקל אצלי בבית, והיה מלא יבחושים ופרעושים בלא מספר, והם גדולים כמעט כגרגירי האורז וצבעם היה קרוב ללבן ואח\"ז נעשה כהה, ומי אמר שאלה אינם אותם תולעים עליהם דיבר בעל \"ספר הברית\", ואשר בגללם ביקש לאסור את כל החומץ עוד בטרם יראו לעין, משום שנראים ע\"י המיקרוסקופ, וע\"ז כתב החכ\"א שהוא הבל, שהתורה לא אסרה מה שלא נראה לעין, ולא נתן שום חילוק או הגדרה, שזה רק צומח או אויר בעלמא וכדו', רק תלה כל ההיתר בכך שאין העין שולטת בהם.","b":false},{"t":"ומ\"ש בסוף הדברים, ואין כוח לשום אחרון לחדש שיעור חדש שלא נזכר בשום ראשון, וכו', אמת הדבר שלא נזכר לא במשנה ולא בגמרא ולא בגאונים ולא בראשונים, דכל אותם דורות טרם נוצר מיקרוסקופ, ולא ידע אדם מציאות זו שיש תולעים שלא נראים ויש חיידקים, רק דנו על פי עין רואה, ותו לא מידי.","b":false},{"t":"ועוד שבספר מאורי אור (ראה בתשובה הקודמת) כתב שמה שלא נראה לעין אלא ע\"י מיקרוסקופ, לא חששו להם חכמים כלל, ורק אם נראים לעין יש לחוש אפילו שהם קטנים מאד. ע\"ש. ומשמע דמיירי גם בדברים שגודלים עם הזמן, ואותם מתיר כל זמן שלא נראים לעין, ואוסר אותם בעצמם משיגדלו ויהיו נראים לעין, ואפילו שהם קטנים מאד כלשונו. וכ\"נ מדברי הרב ערוה\"ש הנ\"ל.","b":false},{"t":"גם הג\"ר שלמה קלוגר ז\"ל בטוטו\"ד תנינא (קי\"א סי' ג\"ן), כתב שבדיקת המיקרוסקופ לא מעלה ולא מורידה מצד ההלכה, ע\"ש.","b":false},{"t":"וכ\"כ הג\"ר כלפון משה הכהן משם זקנו רבי משה הכהן ז\"ל והסכים גם הוא, שבדיקת המיקרוסקופ אינה ראיה לא לאסור ולא להתיר, וגם הגאון יש\"א ברכה והגאון רבי משה שתרוג ז\"ל מודים שאין לאסור ע\"י מיקרוסקופ, עיין בדבריהם בתשובה דלעיל. וכ\"כ הגר\"י משאש ז\"ל בשו\"ת מים חיים גבי אתרוג שראו בו נקבים ע\"י מיקרוסקופ, ושכ\"כ מהר\"י בלייח ז\"ל לענין פרודי אותיות שבס\"ת ע\"י מיקרוסקופ. וכ\"כ בדובב מישרים ח\"א סימן א', ועוד כן כתב האגרו\"מ בשם הג\"ר שמחה זליג דיין דבריסק שכתב כן משם הגר\"ח מבריסק ז\"ל.","b":false},{"t":"וא\"כ איך כתב הרב הנז' ששום אחד לא כתב כן. ואם כונתו על גדולים שלפניהם, בזה הוא צודק, שבגמרא ובראשונים לא נאמר דבר זה וגם לא בגדולי האחרונים, אך אין זו ראיה, דבימיהם לא היה מיקרוסקופ, ולא ידעו מהימצאות יצורים זעירים כלל, ולא היה לפניהם רק מה שהעין רואה בלבד, ואיך ידברו על מה שלא היה ידוע.","b":false},{"t":"עו\"כ בהערה שם למטה (אות א), וז\"ל, ובאמת המימרא הזאת מהגר\"ח ז\"ל ומרבי שמחה זעליג ז\"ל הדיין מבריסק, לאו מר בר רב אשי חתים עליה, דכל המימרא הזאת נובעת מנכדו של הדיין מבריסק ז\"ל שהעיד בזקנתו, כחמשה ועשרים שנה אחרי המלחמה, באגרו\"מ ח\"ב סימן קמ\"ו, מה ששמע בנערותו כמה וכמה שנים לפני המלחמה מזקנו הנ\"ל, ששמע מר' חיים ז\"ל שהטעם שהחומץ מותר הוא משום שהתולעים אינם נראים לעין, והנה החכ\"א בבינת אדם כבר עמד בזה וכתב טעם אחר להא דתולעים שבתוך החומץ מותרים, והוא משום שעדיין לא יצאו מן הכח אל הפועל, וכנ\"ל. ולא משום שאינם נראים לעין, וכו' עכ\"ל.","b":false},{"t":"ולא זכיתי להבין הלשון, דלאו מר בר רב אשי חתים עליה, וכי הגרמ\"פ ז\"ל קטיל קני באגמא ח\"ו, ואם הוא קיבל עדות זו, מי יבא אחר המלך לערער בחדריו, ולהשתמש בלשון קשה כזו. ועוד מי הוא זה שהעיד בענין זה, הלא העד הוא נכדו של הדיין מבריסק שהעיד מה ששמע בנערותו מסבו הגדול. והאם יש טוב מזה, ודברים רבים נאמרים בשם גדולים מבלי שמתברר מי בעל השמועה, רק קול הברה בעלמא. וכאן הנכד מעיד ששמע מזקנו, שהיה דיין דמתא בריסק בימי הגר\"ח ז\"ל, ואומר בשמו למופה\"ד הגרמ\"פ ז\"ל, ומה מקום יש לערער עוד.","b":false},{"t":"ועוד דמתמיה עליהם שזה נגד החכ\"א בבינת אדם הנ\"ל, וזאת קשה מהראשונה, דאיך ניתן לומר שהחכ\"א בבינ\"א אמר טעם אחר, ולא משום שאינם נראים לעין, וזה מתמיה מאד, שהרי כל הדיון של הבינת אדם שם, הוא אך ורק על התולעים שאינם נראים לעין כלל כי אם ע\"י מיקרוסקופ שמביט דרכו ורואה שכל החומץ מלא תולעים, והביא ע\"ז את דברי ספר הברית שכתב שלכך אסור לאכול חומץ וכו'. והוא ז\"ל השיב שזה הבל, שהתורה התירה חומץ, ומכריח מזה דשרי, ובודאי שההיתר הוא דלא אסרה תורה אלא מה שהעין רואה בלבד, שהרי הוסיף וכתב בזוה\"ל: וגם אין לומר דכונת הרב ספר הברית שהחומץ כבר יש בו תולעים. דא\"כ ביצים לא נאכל, שהרי כתב ג\"כ שבזרע אדם נראה אדם, ובקשר הביצה נראה תרנגולת, אלא דבר הבל הוא, ולא אסרה תורה מה שבכח אלא מה שיצא לפועל. עכ\"ל.","b":false},{"t":"והנה מ\"ש דא\"כ גם ביצים לא נאכל, משום שרואים בקשר שלה תרנגולת, וברור דרואים זה רק ע\"י המיקרוסקופ, ולזה אמר אם תאסור התולעים בהחומץ שנראים רק ע\"י המיקרוסקופ, א\"כ לא נאכל ביצים שגם שם נראית התרנגולת ע\"י המיקרוסקופ, ומזה שכן אוכלים ביצים, הוכיח שדבר הבל הוא, שהתורה לא אסרה מה שבכח, דהיינו שלא נראה בעין רגילה, אלא מה שיצא לפועל. שהוא נראה בעין רגילה. וזה פשט פשוט וברור אין מי שיטעה בו, וא\"כ מה שכתבו בשם הגר\"ח מבריסק ז\"ל הוא מבואר ומפורש להדיא בבינת אדם. והוא ז\"ל מתמיה שמ\"ש בשם הגר\"ח, הוא נגד מה שכתב החכ\"א בבינת אדם. ולא ידעתי להבין דבריו ז\"ל כלל.","b":false},{"t":"וראה עוד בבינת אדם שם שאחר שדחה דברי ספר הברית, כתב בזוה\"ל, אך כונתו דיש חומץ שכשמסתכלים נגד השמש נראים בו התולעים, וזה נראה דיש לו דין חומץ שיש בו תולעים, שכתב הב\"י בבד\"ה בשם ר' ירוחם ז\"ל חומץ שיש בו תולעים אם פירשו לאויר נקרא פרשו, אבל מן החומץ לתבשיל, לא הוי פרשו ומותרים. עכ\"ל. וע\"ש שהאריך בזה מאד. ומן המעט שכתבתי תראה שכל החילוק שבין חומץ מותר ובין חומץ אסור הוא, שבראשונה דיבר באין נראים התולעים בעין אלא במיקרוסקופ, והוא המותר. ואח\"כ דיבר על חומץ שנראים בו התולעים נגד השמש, והיינו בעין רגילה, שבזה כתב שהוא אסור אם פרשו. ומעתה אין עוד שום ספק בעולם שמה שכתב \"בכח\" הוא שאין נראה לעין, וכשנראה לעין מיקרי שיצא אל הפועל. ודי בזה.","b":false},{"t":"וע\"ש עוד בדברי הרב הכותב, שהוסיף וכתב בזה\"ל והיאך נאמר שנעלמה מהגר\"ח ז\"ל הרב של בריסק ומר' שמחה זעליג ז\"ל הדיין דבריסק דברי החכ\"א, ואמרו טעם אחר, אשר לפי הטעם של החכ\"א אין לה שום אחיזה ומקום וכו', עכ\"ל.","b":false},{"t":"ובמח\"כ ככל שמוסיף דברים, דבריו הופכים לתמוהים יותר ויותר, כי דברי הגר\"ח והג\"ר שמחה זליג מבריסק ז\"ל הם דברי החכ\"א ממש. ועוד הוסיף וז\"ל, שהרי אם יש לנו הטעם של החכ\"א שעדיין לא יצא מכח אל הפועל, אין עוד שום מקום להוכיח מכאן שדבר שאינו נראה לעין מותר. עכ\"ל. ולא ידעתי איך מפרש מ\"ש החכ\"א שהוא בכח ולא יצא לפועל, הרי ברור בדבריו, דב\"כח\" הוא מה שנראה רק ע\"י מיקרוסקופ, וכשנראה בעין רגילה, הוא נקרא דבר שיצא אל הפועל. וכנ\"ל.","b":false},{"t":"וע\"ש שהאריך עוד למה יחלקו הגר\"ח מבריסק והדיין ז\"ל על החכ\"א, ומה ראו על ככה, ולא הזכירוהו ומשמע שנעלם מהם, ולא מסתבר שנעלם מהם וכו' ע\"ש. וכאמור לא נעלם מהם ולא חלקו עליו, אלא חזרו על דבריו ממש, בסגנון שונה.","b":false},{"t":"וסיים הרב הכותב בזוה\"ל, ועכ\"פ המימרא בשם הגר\"ח ז\"ל בתולעים נראה שאינה נכונה משום שהיא נגד החכ\"א, אמנם אפילו אם יתברר שהיא נכונה מ\"מ אין ראיה ממנה לכל התולעים, דמימרא זאת לא מיירי אלא בתולעים שלא יתגדלו לעולם. עכ\"ל. וכבר כתבתי שדבריהם ודברי החכ\"א אחד הוא. ובהמשך דברי החכ\"א נראה דמיירי בתולעים שמתגדלים אח\"כ וכנ\"ל.","b":false},{"t":"ו.","b":false},{"t":"במי שרואה הלבנה ע\"י מיקרוסקופ אם יכול לברך עליה ברכת הלבנה וכן לענין קידוש החודש","b":true},{"t":"עו\"כ הרב הכותב הנז', ולא אמנע מלהביא כדמות ראיה שבבריסק ג\"כ סוברים שדיני התורה ניתנו אפילו על דבר שאינו נראה לעין, דבחידושי הגרי\"ז על התורה (סטנסיל) פר' בא, במה שפירש\"י החדש הזה וגו', וז\"ל נתקשה משה על מולד הלבנה באיזה שיעור תראה ותהיה ראויה לקדש. והראה לו באצבע את הלבנה ברקיע וא\"ל כזה ראה וקדש עכ\"ל. והקשו המפרשים איזה שיעור שייך בקידוש לבנה, שיתקשה בה משה רבינו והלא שום שיעור לא שייך, רק שתראה הלבנה, אפי' כל שהוא מקדשין ואם לאו אין מקדשין, ותירץ הגרי\"ז דמשה הסתפק אי בעינן שתהיה נראית ע\"י עין האדם דוקא, או אפילו ע\"י זכוכית מגדלת, והראה לו הקב\"ה וכו', שצריכה להיות גדולה שתראה בעיניך בלא זכוכית מגדלת. עכת\"ד הגרי\"ז ז\"ל. והשתא אם איתא שכל דיני התורה לא נאמרו על מה שלא נראה לעין, מה הספק של משה רבינו, ומאי שנא הלבנה מכל התורה, ובשלמא אם נאמר שכל דיני התורה נאמרו אפילו על דבר שלא נראה לעין, נסתפק משה רבינו על המולד שהוא יציאתה לעולם, דכשם שבאדם ובבהמה לא מיקרי נולד אלא ביציאה חשובה, וכן שאר דינים כברכת המזון שיש שיעור, כמו\"כ ביציאת הלבנה יש שיעור, עד שתהא גדולה שנראית לעין לכל באי עולם, ואמר לו הקב\"ה שהוא אמת שמדין שיעור צריך שתהא נראית לעין. עכ\"ל.","b":false},{"t":"ולענ\"ד הדברים הפוכים הם, שמהספק של משה רבינו ע\"ה, עולה מזה שהיה ברור לו שכל דיני התורה נאמרו אך ורק על מה שעין רואה בלבד, אלא שבלבנה, שיש מרחק עצום ורב מאד מאד, הדעת מחייבת שמה שלא רואים בעין אינו מורה שהמולד לא יצא לעולם, שהרי המרחק מפריע לעין לראות, ואם ע\"י מיקרוסקופ היא נראית, היה מקום לומר שאפשר לקדש, דהמיקרוסקופ בכהאי גוונא בא להסיר המניעות של המרחקים ומגלה האמת, שאם היינו קרובים בודאי היינו רואים בעין רגילה, ויש מקום לקדש. ועל ספקו זה השיבו הקב\"ה, כזה ראה וקדש, כלומר שהתורה ניתנה לאדם על הארץ עם המגבלות שלו ועם העיכובים של המרחקים, ובתנאים אלו נתנה התורה, וא\"צ לחפש כלים להסיר מניעות ועכבות, אלא כזה ראה וקדש, ותו לא מידי.","b":false},{"t":"ואדרבה זה מחזק מאד מה שהעלו כל גדולי הפוסקים הנ\"ל, ובתוכם גם הגר\"ח ז\"ל, שכל דיני התורה לא נאמרו אלא על מה שעין אדם רואה, ותו לא. ואפילו במולד שברור שיש מגבלות של מרחק, ומה שלא רואים את המולד אינו מוכרח שלא יצא המולד, ויש מקום גדול לומר שהמיקרוסקופ מראה בזה, מה שהעין יכולה לראות בשופי, אם היה עומד קרוב יותר, ושפיר ראוי לקדש. ועכ\"ז א\"ל דבעינן ראיית עין רגילה, וק\"ו בן בנו של ק\"ו לשרצים ושאר הענינים.","b":false},{"t":"ז.","b":false},{"t":"מי שראה ע\"י מיקרוסקופ תולעת ויודע בה ע\"י המיקרוסקופ בלבד שהיא תולעת אם מותרת באכילה","b":true},{"t":"עו\"כ בקונטרס הנז': הן אמת שאין חיוב לבדוק עד הבדיקה, או תולעים בזכוכית מגדלת, שלא מצינו בשום מקום וכו', אמנם אם קרה שבדקו עד הבדיקה ע\"י זכוכית מגדלת ומצאו עליו דם, או שמצאו איזה תולעת ע\"י זכוכית מגדלת, בודאי היא טמאה, והתולעת אסורה. למה הדבר דומה לי\"ח טריפות שאין חייבים לבדוק (כמ\"ש ביו\"ד סי' ט\"ל), אמנם אם נמצא היא טרפה. עכ\"ל.","b":false},{"t":"וגם זה לא מוכרח כלל, ולענ\"ד אפי' נראה דם אינה טמאה, וגם התולעת מן הדין אין בה איסור, וכן אם בדקו הריאה וכיו\"ב ומצאוה מלאה נקבים מותרת, וכן האתרוג שנמצא מלא נקבים ע\"י מיקרוסקופ, וכן בסת\"ם, וכן בסכין שחיטה וכו'. וההיא שהביא מי\"ח טריפות, לאו שמה מתיא, דשם בדק בעין רגילה וגילה הנקב או החסרון וכיו\"ב ולא דמי לכאן כלל. שהרי כאן לא נמצא הדבר אלא ע\"י מיקרוסקופ, אבל בעין רגילה לא נראה כלל, ולכך אינו נחשב שמצאו שם דבר מה, כי כל מה שלא נראה בעין רגילה אינו כלום.וכבר הוכחתי מהחכמת אדם היפך דבריו, וא\"צ להאריך עוד.","b":false},{"t":"ח.","b":false},{"t":"דעת הרב מאורי אור בתולעים שאינם נראים","b":true},{"t":"עו\"כ שם (אות כ'), מדרכי תשובה (סימן פ\"ד אות נ\"ט) בשם מאורי אור, דאותם (מילב'ין) שהם קטנים מאד שהם בתוך הקמח, שאינן נראין רק ע\"י כלי הבטה המגדיל הראות אין חשש, כיון דמיניה קא רבו, ואין חשש רק שמא פירשו, ובהם גם אם פירשו אין חשש דלעולם יש משהו קמח סביביו וכו'. וא\"כ לא נאסר מעולם שהוא תמיד מסובב בקמח. עכ\"ל. מבואר מדבריו שגם דבר שאינו נראה לעין אסור, דרק משום שעדיין לא פירשו מותרים, אבל בלא\"ה אסורים. ע\"כ דברי הרב הכותב בקונ' עין לא ראתה.","b":false},{"t":"והנה בעל הקונטרס הנז' חשב דמ\"ש במאורי אור הנז', שאין נראין אלא וכו', דהיינו שאין נראין כלל, בלא כלי הבטה. ואם באמת זו היא כונת הרב מאורי אור, א\"כ הוא סותר למה שכתב איהו גופיה בחלק קן טהור (חולין נ\"ח ע\"ב), שמה שלא נראה אלא ע\"י מיקרוסקופ לא חששו להם חכמים כלל, ורק אם נראים לעין יש לחוש אפילו שהם קטנים מאד, ע\"ש. וכאן אומר אפילו לא נראים לעין כלל אסורים. ובע\"כ צ\"ל שכונתו במה שכתב, שא\"א לראותם בלי כלי הבטה, רצונו לומר, דקשה להבחין בהם משום שהם קטנים מאד וגם הצבע שלהם דומה לקמח, וע\"י כלי הבטה שמגדיל אותם ניתן להבחין בהם ולזהותם תוך הקמח. מיהו אם יפרישו אותם מן הקמח ויעמידום בפני עצמם ניתן לראותם בעין רגילה, ובכה\"ג בודאי שהם אסורים, וכמו שכתב הוא עצמו בחלק קן טהור הנז', דאם נראים בעין אפילו קטנים מאד אסורים, והתירם רק מהטעם דלא פירשו.","b":false},{"t":"וכבר הוכחתי כן בתשובה הקודמת משאילת יעב\"ץ, שכתב על המילב'ין באורז שאין נראין אלא ע\"י זכוכית המגדיל, או בשמש. וש\"מ דניתן לראותם בעין רגילה כשעומדים בשמש, מיהו בצל קשה להבחין בהם מרוב קטנותן וגם שהצבע דומה לאורז, אבל ע\"י כלי המגדיל, או כשמעמידם בשמש הם נראים גם לעין רגילה, וע\"כ אסורים הם לכו\"ע היכא דפירשו. אבל לעולם כל שאין נראים לעין אדם כלל מותרים הם, ואין מכאן שום ראיה.","b":false},{"t":"ט.","b":false},{"t":"ביאור דעת הגר\"ש קלוגר ז\"ל ושאר פוסקים בענין הנז'","b":true},{"t":"עו\"כ הרב הכותב (שם אות ג'), עוד הבאתי ראיה ממ\"ש בשו\"ת טוטו\"ד למהרש\"ק הובא בדרכ\"ת (סי' פ\"ד אות צ\"ד) בגראפ'ין המוחזקין בתולעים אסורים. וחלילה לסמוך על בדיקת זכוכית מגדלת, ומוכיח מזה דגם כשאין נראים אלא ע\"י זכוכית מגדלת אסורים. ע\"כ.","b":false},{"t":"וכבר הזכרתי בתשובה הקודמת להטוטו\"ד הזה, והוא ז\"ל העיר שם על דברי השאילת יעב\"ץ ח\"ב (סימן קכ\"ד) שהובא בפ\"ת (סי' פ\"ד סוף סק\"ה), דשכיחי שני מיני תולעים, האחד, הם מיני תולעים ממש אשר קל לבודקן, והשני, הוא המילבי'ן וזה ישנו ג\"כ בבדיקה ע\"י חמין, ועין יפה מבדקא בשמש, או ע\"י זכוכית מגדיל ראות, ע\"ש. וכבר כתבתי לעיל, דממה שכתב שניתן לבדוק אותו ע\"י עין יפה בשמש, היא הוכחה שהוא נראה לעין, רק שצריך אור שמש כדי להבחין בהם, משום שהם קטנים ודומים לאורז.","b":false},{"t":"ובדרכ\"ת שם הביא מדברי הטוטו\"ד למהרש\"ק ז\"ל, שהעיר על הגאון יעב\"ץ ז\"ל במה שהזכיר שאפשר לבדוק גם ע\"י כלי זכוכית, ומהרש\"ק כתב דחלילה לסמוך על זה, דהבדיקה לא שייך רק במה דאפשר בכל אדם, אבל במה דא\"א רק בדרך רחוק ע\"י כלי, לא נחשב בדיקה לסמוך ע\"ז, שהרי המומחים אומרים שאם נביט במים בכלי זכוכית המגדיל נראה שיש בהם תולעים, ומדלא משגיחין על זה בע\"כ דהבדיקה בכלי אינה נחשבת ראיה אפילו להחמיר, א\"כ מכ\"ש דאינה ראיה להקל על ידי הכלי (ואין להתיר את האורז ע\"י בדיקה זו). דלא נחשב בדיקה כלל. ע\"ש.","b":false},{"t":"וכבר כתבתי לעיל דמדברי היעב\"ץ נראה בהדיא דתולעים אלו נראים בעין רגילה, רק שקשה להבחין בהם ולזה צריך שיבדוק בשמש, או ע\"י כלי הזכוכית. וגם מהרש\"ק לא העיר בזה מאומה, רק הוא סובר דאין לסמוך על בדיקת המגדלת לא להחמיר וכ\"ש דלא להקל. ואין מזה שום ראיה כלל.","b":false},{"t":"וכן הבין גם בעל שבט הלוי (בח\"ז יו\"ד סי' קכ\"ה אות ב') שתמה על דברי מהרש\"ק ז\"ל הנז', וז\"ל ולא הבינותי זה כלל, דמה דאין חוששין לזכוכית המגדיל או מיקרוסקופ במים, אינו משום דלאו בדיקה הוא, אלא דלא חייבה תורה על תולעים וכיו\"ב, אלא מה שנראה לעין האדם, דאל\"כ וכו', אבל לבדוק להחמיר ע\"י זכוכית כזה באורז כדי להרגיש במה שצריך להרגיש, אלא לפעמים העין קצרת הראות, ועין חדה יכולה לראות בזה, ועין בינוני לא מרגישה רק ע\"י זכוכית כזה, אין זו בדיקה להקל אלא להחמיר במה שצריך להחמיר, דהיינו במילב'ין של אורז וכיו\"ב.","b":false},{"t":"והנה גם הוא למד בפשיטות שמהרש\"ק מיירי בתולעים שהעין רואה אותם, רק שצריך לזה עין חדה, אבל לעין בינונית צריך עזרת הכלי זכוכית. וזה מפורש בדבריו. וכבר הוכחתי כן מדברי הרב שאילת יעב\"ץ וכנ\"ל. והרב הכותב ז\"ל הזדרז בראיותיו ולא בדק הדברים לעומקם. עוד יש לציין שבדברי הרב שבט הלוי הנזכר, מפורש ומבואר בבירור גמור דמה שאין העין יכולה לראות, ולא נראה כי אם ע\"י מכשירים או זכוכית מגדלת, אין בו איסור וא\"צ לבדוק אחריו, שהרי כתב בסוף הדברים, וז\"ל: ובודאי מה שאין עין אדם אפילו חדה וחריפה יכולה לראות כלל, בזה בודאי אין צריכים לבדוק כלל, וכבר כתבתי בעניי בזה בכמה מקומות. עכ\"ל. וזה בודאי דלא כהרב המחבר קונטרס עין לא ראתה ע\"ה.","b":false},{"t":"י.","b":false},{"t":"בענין דגים שא\"א להבחין בקשקשיהם אלא ע\"י מיקרוסקופ אם מותרים באכילה","b":true},{"t":"עו\"כ (בקונטרסו הנ\"ל אות ד') עוד הבאתי ראיה מתפא\"י (פ\"ב דע\"ז בבועז אות ג'), בדג הנקרא ברביט\"א שאין רואין הקשקשים שבהם, רק ע\"י זכוכית מגדלת, ואעפ\"כ התירוהו רוב הראשונים. ולמד מזה שגם מה שלא נראה לעין דינו כמו דבר הנראה לעין. עו\"כ בקונטרס הנז', דגם הראשונים שאסרו הדג הזה, הוא מטעם דקשקשים צריכים להיות כלבוש לדג, כמבואר בנדה (נ\"א), והקשקשים הקטנים מאד לא חשיבי כלבוש לדג.","b":false},{"t":"וכבר הזכרתי לעיל דברי הראש\"ל יש\"א ברכה ז\"ל בענין זה, ושהגאון ר\"מ שתרוג בשו\"ת ישיב משה, למד מזה להתיר קשקשים הנראים רק ע\"י מיקרוסקופ, והג\"ר כלפון הכהן חלק עליו, ועי\"ל מה שכתבתי בזה.","b":false},{"t":"אך לעולם התולעים הנראים רק ע\"י מיקרוסקופ מותרים הם, וקשקשים שאני, דיש פה דג, והמיקרוסקופ מראה שיש לו קשקשים רק קטנים הם, ובזה חולקים. אבל באמת התפא\"י עצמו כתב שם שיש שרצה להתיר ואוושו עליה כו\"ע, ונפיק שיפורי מבי מדרשא לאיסורא, ונשתקע הדבר ולא יאמר, והטעם לכך שכל שלא נראה לעין בלי כלי הבטה, לא נחשב קשקשת, וכו', ע\"ש. ולא ידעתי למה הרב בעל הקונטרס לא הביא כל דברי התפא\"י ע\"ה.","b":false},{"t":"יא.","b":false},{"t":"במעשה הגאון חת\"ס שהורה לתלמידיו לבדוק עלי חסה בזכוכית מגדלת","b":true},{"t":"עו\"כ (בקונטרס הנז' אות ה' שם) להביא ראיה מהחת\"ס שציוה לבחורים לבדוק עבורו את השלאטין (חסה) לליל פסח בסדר, וציוה שיבדקו בזכוכית מגדלת, כמובא במנהגיו, ושאל למה צריך זכוכית מגדלת, הא אם לא יראו בעין מותרים הם, ע\"ש שהאריך בזה.","b":false},{"t":"ובמחילה מכבודו, גם זו אינה ראיה כלל, שהחַסָּה יש לה קפלים רבים, ומצויים בה חרקים דקים מאד והצבע שלהם דומה לחסה, ומסתתרים בין החרכים, וצריך לבדוק עלים רבים בכל קפליהם וקמטיהם, וחשש שלא יתאמצו או לא ישימו עין עיונם היטב כדבעי, ולחומרא דרש שיסתכלו בזכוכית מגדלת להטיב הראות ולהקל על ההבחנה, וגם למקד התשומת לב, אבל מדובר במה שנראה לעין, שהוא אסור לכו\"ע , והדברים ברורים ופשוטים בעה\"ו. ועל כן אין מזה שום ראיה.","b":false},{"t":"יב.","b":false},{"t":"בדברי הפלתי והחוו\"ד בשרצים הנולדים בפירות","b":true},{"t":"עו\"כ (בקונטרס שם אות ו') ראיה מהפלתי (סי' ק') ששרצים הנולדים בפירות יש להם דין ביטול, ואין להם דין בריה, משום שאינם אסורים מתחילת בריאתם, שכל זמן שלא פירשו מותרים הם. [בתשו' אחרת לפני שנים, כתבתי כמדומני בשם החיד\"א דודאי יש לה דין בריה, כי מעת שנבראו, דינם שאם יפרשו יאסרו, וחשוב שפיר מתחילת בריאתם, והוי בריה שאינה בטלה].","b":false},{"t":"וכתב הרב ז\"ל, והשתא דדבר שלא נראה לעין מותר, א\"כ תולעים שנולדו בפירות יהיה בהם דין ביטול, דמ\"מ אינם אסורים משעת בריאתם עד שיגיעו לגודל הנראה לעין. וגם מזה אין שום הוכחה, דלפי מה שהסברתי עולה דכל זמן שלא נראין לעין עדיין לא חשיבי ברואים כלל, שהתורה לא אסרתם ולא החשיבתם לבעלי חיים עד שיגיעו למצב שהעין רואה אותם, ואז היא תחילת בריאתן, ודי בזה.","b":false},{"t":"עו\"כ (שם אות ז') דגם להרב חות דעת שחולק על הפלתי הנז', לפי החילוק השני שם בחו\"ד הוא רק בשרצים שנתהוו בפירות, שכל זמן שלא פירשו, עדיין אינם שרצים, אלא הם כחלק מן הפרי, אבל שרצים שלא נולדו בפירות שלא נאמר בהם דין זה דעד שיפרשו, דמיד הם שרצים, אם בעודם קטנים (שלא נראים) אין בהם איסור, א\"כ גם להחו\"ד, אינם אסורים מתחילת ברייתן, ואין להם דין בריה, ומדלא אמרינן כן מוכח שהם אסורים מתחילת ברייתן, אפי' שעדיין לא נראים לעין. עכ\"ל.","b":false},{"t":"ואחר המחילה כראוי, גם מזה אין הוכחה, דכל זמן שלא נראים לעין, הוי כלא נולדו כלל, ותחילת ברייתן הוא מרגע שהם נראים לעין רגילה בלא מכשירים נוספים. ומ\"ש גבי שרצים שבתוך הפירות שכל זמן שלא פירשו עדיין אינם שרצים, היינו בנראים לעין, דאפ\"ה הם כחלק מהפרי עד שיפרשו. ובזה באמת אם אינם תוך הפרי הרי הם אסורים מיד משעה שנראין לעין, ואין שייך בזה דין דפירשו.","b":false},{"t":"יג.","b":false},{"t":"אם מותר להכניס לבית הכסא תנ\"ך זעיר שאי אפשר לקוראו אלא ע\"י מיקרוסקופ","b":true},{"t":"עו\"כ (באות ח') להוכיח מתשובת מהרש\"ם ז\"ל (ח\"ג סי' שנ\"ז) בצילום של תנ\"ך קטן כל כך, שא\"א לראות האותיות אלא ע\"י זכוכית מגדלת, שהעלה שאין להכניסו לבית הכסא, אלא בתיק בתוך תיק. ומוכיח מזה דדיני תורה נאמרו גם על מה שלא נראה לעין. עכ\"ד. ולא דמי דשם צילמו מכתב ברור רק הקטינוהו כל כך, וע\"י זכוכית מגדלת אפשר לקרא נמצא שיש פה כתב בפועל, בזה שייך להחמיר. אבל תולעים שלא נראים לעין, לפי מה שביארתי אינם תולעים כלל שעדיין לא נקראים בשם זה, ואעפ\"י שרואים במיקרוסקופ שהם תולעים, אינם כלום, אלא הרי הם פירשא בעלמא.","b":false},{"t":"יד.","b":false},{"t":"בדברי החזו\"א ז\"ל בענין מילבי\"ן","b":true},{"t":"ובאות ט' שם, העתיק דברי החזו\"א (ביו\"ד סי' י\"ד או' ו' ד\"ה ובמעשה דהט\"ז) שכתב דיש מקום להקל במילבי'ן, דלהפלגת קטנותן ודאי אבדו הכרת העין, ויש כאן ביטול יבש ביבש וכו', ואפשר דכל שאין העין שולט בו לא בריה הוא וכו', עכ\"ל החזו\"א. וכתב הנה לפניכם שגם החזו\"א נקט בפשיטות שאפי' דברים שאינם ניכרים לעין, כמו מילב'ין, צריך ביטול ברוב, ולא איבדו רק החשיבות ד\"בריה\", אבל לא את איסורם בכלל, ובדברי החזו\"א הללו הרווחנו דרך אגב טעם נוסף דא\"צ לבדוק שום פרי בזכוכית מגדלת, והוא משום שאפילו אם יש בה תולעת קטנה כזו בטלה ברוב, אבל אם הוכרה כגון שנתגדלה או נפרדה אסורה באיסור גמור. עכ\"ל הרב הכותב ז\"ל.","b":false},{"t":"וכבר הוכחתי שהמלבי'ן הוא נראה לעין רק שצריך שמש, או זכוכית מגדלת, משום שהוא קטן וצבעו כצבע הקמח או האורז וקשה להבחין בו. ובתשובה הקודמת הבאתי כל לשון החזו\"א וביארתיו על נכון, והוכחתי בבירור, שמדבר בתולעים שהעין רואה אותם, רק נתערבו במאכל, וא\"א לגלותם, ודן אם זה נחשב כנימוח ובטל ממנו דין בריה או לא. ולא הזכיר שם לא מיקרוסקופ ולא זכוכית מגדלת משום שלא על זה מדבר. אלא שם הוא דן על מה שהעין רואה. ע\"ש.","b":false},{"t":"וגם מה שכתב כאן שהחזו\"א סובר שבגלל שהוא קטן בטל ממנו דין החשיבות של \"בריה\", ובטל יבש ביבש. והזדרז הכותב ללמוד מזה עוד טעם למה א\"צ לבדוק כל פרי בזכוכית מגדלת וכנ\"ל. אחר המחי\"ר מכת\"ר, גם בזה נלע\"ד דמסקנת החזו\"א היא, שכיון שהמילב'ין (נראה לעין) רק איבד הכרתו מתוך שנתערב בתבשיל, ולא יכירנו מקומו עוד, אבל גופו קיים ואם יפגשנו יראה וגם של יכירה, ולא אבד ממנו גם החשיבות של בריה, וזה שכתב: ובזה אף שנתערב יבש ביבש ואינו ניכר, מ\"מ לא אבד חשיבות בריה, דגופו קיים וניכר אלא מפני שנתערב בגופים אחרים כתוארו אין העין מבחנת בינו לבין האחרים, עכ\"ל. (שהעתיק הרב ז\"ל). הרי מבואר דעדיין יש לו גם דין בריה. והטעם שרצה ללמוד הרב הנ\"ל ז\"ל אינו קיים. דבאמת עדיין חשוב ולא בטיל, ומיהו כל זה בגודל שעין אדם רואה אותו, אלא מתוך שנתערב בדברים כתוארו אינו מכירו.","b":false},{"t":"טו.","b":false},{"t":"בסוגיא דהנשבע שלא יאכל כלום ואכל שקצים ורמשים","b":true},{"t":"עו\"כ בקונט' הנז' (אות י') שכבר הביא ראיה נפלאה מהא דאמר ר\"ל (בריש פ' יוה\"כ), דלרבי עקיבא דסבר שהנשבע שלא יאכל איזה דבר אוסר עצמו בכל שהוא. מעמיד המשנה דהנשבע שלא יאכל, ואכל שקצים ורמשים חייב, ור\"ש פוטר בסתם, דר\"ש לטעמיה דגם על כל שהוא מושבע מהר סיני, ולא חלה שבועתו, אבל ת\"ק ס\"ל דאינו מושבע על כל שהוא מהר סיני, וע\"כ אפי' אכל שקצים שמושבע עליהם מהר סיני, עבר על שבועתו, כי אינו מושבע מהר סיני על כל שהוא משקצים, ואילו השבועה חלה על כל שהוא ג\"כ, ועבר גם על השבועה.","b":false},{"t":"וע\"ז כתב המחבר ז\"ל דאם מה שלא נראה לעין אין בו איסור דלא ניתנה תורה למלאכי השרת, אמאי פטור לר\"ש, והלא מסיני אינו מושבע על מה שהעין לא רואה, ובשבועה אוסר גם מה שלא נראה, דלר\"ע כשנשבע, הוא רוצה לאסור על עצמו אפי' מעט מן המעט, וא\"כ גם מה שיכול לראות ע\"י זכוכית מגדלת אוסר על עצמו בשבועתו, ואמאי פטור לר\"ש, אלא ודאי שגם מה שלא נראה לעין אסור מן התורה, וע\"כ לא חלה שבועתו גם ע\"ז דמושבע ועומד מהר סיני גם על מה שהעין אינה רואה. וסיים: היוצא לנו מכל הנ\"ל שמבואר בכל הפוסקים שדבר שאינו נראה לעין אסור באיסור גמור כדבר הנראה לעין, וכ\"ש דאיתניהו במציאות וכו'. עכ\"ל.","b":false},{"t":"וגם זו אינה ראיה, דהרב הכותב ז\"ל הניח הנחה מלבו הטהור, וע\"ז מקשה ומוכיח ומסיק שהיא ראיה נפלאה, והנחתו היא שע\"י השבועה לר\"ע, ודאי אוסר גם מה שהעין לא רואה, ועל יסוד זה בנה ראיתו, ואם היסוד הזה היה נכון אזי באמת הוא מוכיח נכון. אך היסוד הזה שהניח לא נכון הוא אחר המחי\"ר, דגם שבועה לא תחול, שהרי נשבע שלא יאכל, ואין זו אכילה כלל, דאטו דבר שהעין לא שולטת בו שייך בו אכילה, והרי הוא מבחינת גודלו ומשקלו כחיידק, ואין אדם מרגיש בהם כלל, לא בפיו ולא בבני מעיו, ואיך יכלל בכלל שבועה שלא יאכל, והרי לא אכל בשום פנים. ובפרט למה שהוכחתי בס\"ד שכל שעדיין לא נראה לעין לא מיקרי תולעת, ופשיטא דלא חשיב אוכל כלל, ולכל היותר הרי זה פירשא בעלמא ותו לא מידי. וזה נשבע שלא יאכל, ולר\"ע חלה שבועתו גם על כל שהוא, ואפי' כשהוא מעט מן המעט, עכ\"פ בעינן שיש בו ממשות אבל שרצים קטנים וחיידקים אין בהם אפילו מעט מן המעט כלל שלא נראים ולא נרגשים כלל וכלל, ולא עוד אלא שאין זה שרץ בשלב זה, אלא פירשא בעלמא שעתידה להתפתח לבע\"ח שיקרא שרץ.","b":false},{"t":"ומ\"ש שמכל הפוסקים מבואר וכו', כבר הוכחתי שכולם מודים שמה שלא נראה לעין אין בו איסור כלל לא מה\"ת ולא מדרבנן.","b":false},{"t":"טז.","b":false},{"t":"ישוב כמה הערות בענין תולעים שאינם נראים וביאור הא דאמרו רבותינו שיתסר מיל קא שלטא עינא דרועה","b":true},{"t":"עוד ראיתי להרב הכותב הנז' שבעמוד אחרון מקונטריסו הנ\"ל, כתב ששלח לו הר\"מ ויא שליט\"א מכתב מהרה\"ג ר' אברהם יעקב זלזניק שליט\"א ראש ישיבת עץ חיים בירושלים, שם מעיר על מה שכתבו בידיעון מס' 35, שהתורה אסרה רק תולעים הנראים לעין ללא זכוכית מגדלת וכיו\"ב, והוא כתב שאין לזה בסיס ומי יכול לחדש הלכה כזו. וממ\"נ אם הדבר הוחזק בתולעים רק לא נראים מי יתיר אותם, אטו תולעים שאין נראים אינם תולעים.","b":false},{"t":"וכתב ששמע משם הגאון ר\"ד בהר\"ן זצ\"ל שדקדק מהגמ' (בכורות נ\"ד ע\"ב) דאמר שיתסר מיל קא שלטא עינא דרועה, ועין שלנו גם עם זכוכית מגדלת לא מגיעה לזה, ואטו התורה נשתנתה ח\"ו, דבזמנם שהעין חזקה אותם תולעים היו אסורים, ולנו מותרים משום שנחלשה רְאִיָתֵנוּ, ובאמת יתכן שכל ההבדל בין הרועים החיים בחיק הטבע, לסתם אנשים החיים בבתים, ומשתמשים באור מלאכותי, ובודאי שאין לחלק בין איש לאיש, ובין זמן לזמן.","b":false},{"t":"ואי מיירי בדבר שלא הוחזק בתולעים בכלל, אין חייב לבדוק מעיקר הדין כשאין ריעותא בפרי. וכמ\"ש ביו\"ד לגבי דם ביצים (בסי' ס\"ו ס\"ח), דסומכים על הרוב שאין בהם דם, אלא שהרמ\"א כתב, שאם אוכל ביום נוהגין לראות אם יש בהם דם. אבל בלילה לא בודקים, וא\"כ גם דבר שאינו מוחזק בתולעים א\"צ בדיקה כלל, אפילו בעין רגילה.","b":false},{"t":"ואין להוכיח להתיר מהחיידקים, כי החיידקים אינן בע\"ח כלל, אע\"פ שהרופאים קוראים להם, \"חי חד תאי\", אינו כלום להלכה, וכי יהיה אסור להורגם בשבת ע\"י חימום או חיטוי, משא\"כ תולעים שאסרתן תורה בלי תנאי שיראו לעין רגילה. עכ\"ל.","b":false},{"t":"ועיינתי היטב במכתב חשוב זה, ולענ\"ד יש מקום לתשובה, ואיני כמשיב על דברי הגאון הכותב, אלא מקיים דבריהם של גדולי עולם מדורות קודמים וגם גדולי דורנו, אשר כולם סוברים שבעל חי שאינו נראה בעין של אדם בלי מכשירים, אין בו איסור כלל וכלל. והראיות וההערות שבמכתב זה באים לסתור דברי כל גדולי עולם שהזכרתי כבר בתשובה הקודמת, ולקיים דבריהם אני בא היום.","b":false},{"t":"וכבר העליתי בתשובתי הקודמת, דכל בע\"ח שהעין לא רואה אותו אינו נחשב לתולעת כלל, ולא חל עליו איסור כלל. וביארתי עוד שאין ההיתר תלוי באונס, שזה דבר שלא נראה ואנוס רחמנא פטריה כאשר כתב הרב ערוך השלחן, אלא שעדיין לא חל עליו שום איסור עד שיגיע לגודל שהעין קולטתו. וע\"כ מה שכתבו במכתב זה בראשית הדברים, ומי יכול לחדש הלכה כזו. עכ\"ל. אחר המחילה כראוי, אין כאן שום חידוש, שהרי דורות רבים מאד אחר מתן תורה, עדיין לא ראה אדם בעל חי או תולעת אלא אם כן היתה בגודל שעין אדם קולטת אותה, שהרי לא היה מיקרוסקופ בעולם, ואיך יעלה בדעת שהתורה תאסור דבר שאין אדם רואהו ליזהר ממנו, ולהמנע מאכילתו, ולא ניתנה תורה למלאכי השרת, ואין זה חידוש לומר שמה שלא נראה בעין לא נאסר, שאין זה תנאי, רק שאין שייכות לאסור מה שלא נראה בעין כלל, ומזה גופו אנו למדים שכל דבר שלא נראה אינו קיים. ובודאי אין עליו שם של בעל חי, וק\"ו שאין בו שום איסור כלל. עד שנמצא שמי שבא לחדש ולאסור מה שהעין אינה רואה, הוא זה שצריך להביא ראיה, כי בפשטות זה דבר חדש לגמרי ולא נרמז בשום מקום, והוא היפך כל סברא, לומר שהתורה אסרה דבר שאין בכוח האדם להבחין בו, עד עבור אלפי שנים ויבא יום וימציאו המיקרוסקופ שאפשר על ידו לבחון בדברים. ועתה שהתגלה הדבר ע\"י אותו מכשיר שיש יצורים זעירים אשר לא שערום ולא ראום אבותינו בכל הדורות הרבים ההם, מתמיהים לאמר מי יכול לחדש הלכה כזו.","b":false},{"t":"וגם מה שכתב עוד אטו תולעים שאינם נראים אינם תולעים. אכן אמת הדבר שאינם תולעים עד שיראו בעין של האדם בלי מכשירים.","b":false},{"t":"גם מה שכתב משם הגר\"ד בהר\"ן ז\"ל שהרועים היו קולטים שיתסר מיל, וכמ\"ש במסכת בכורות (נ\"ד ע\"ב), ותמה, האם התורה נשתנתה ח\"ו שבזמנם שראייתם היתה חזקה התולעים הקטנים היו אסורים, וכיום שנחלשה ראייתנו יהיו מותרים.","b":false},{"t":"ולא ידעתי מי גילה לו רז זה, שהיתה ראייתם חזקה וראו תולעים בעיניהם, גם מה שלא נראה בעין שלנו, אלא ע\"י מיקרוסקופ, ואדרבה ברור לכולי עלמא שמה שנראה כיום ע\"י מיקרוסקופ, לא שזפתו עין אנוש מעולם, וכפי שנראה ברור מהחכמת אדם בהשגתו על ספר הברית בענין החומץ הנ\"ל. והרועה הנזכר בגמרא דבכורות הנ\"ל, אין מדובר כאן בחדות הראיה, אלא שהרועה מקיף שטח של ששה עשר מיל, מתוך שהוא מכיר היטב את השטח, מקיף אותו בקלות ובחדא מחתא הוא סוקר כל השטח של ט\"ז מיל בסקירה אחת. ואין מדובר על דברים קטנים וגדולים, אלא כמה גודל המקום שרועה אחד יכול לשמרו, ואמרו דקים להו לרבנן דשיתסר מיל קא שלטא עינא דרועה. והוא ענין של שליטה וְהֶרְגֶל והכרת השטח במקום הכרה קרובה וחזקה, ואין להסיק מזה שהראייה השתנתה, ובודאי שההלכה לא השתנתה ולא תשתנה ח\"ו. [א\"ה חתן הרהמ\"ח שליט\"א. ובאמת שכן פירש התפא\"י בבכורות שם. אבל בילקוט הראובני (פרשת בראשית דף מ' ע\"ב) פי' דברי הגמ' כפשוטם דמיירי על ראיית האדם למרחוק. ע\"ש. וכ\"כ בבן יהוידע (ערובין סה.) דבדורות הראשונים היה חוש הראות חזק מאה ידות על דורות אלו. ע\"כ.]. ואדרבה מתוך המציאות עולה שלא יעלה בדעת לומר שהתורה אסרה מה שלא היו רואים כלל, מוכרחים לומר שגם היום אחר הגלות עין המיקרוסקופ, עדיין הם מותרים, ומי שחולק ע\"ז, הרי הוא צריך לחוש שלא יאמרו שההלכה משתנה ח\"ו.","b":false},{"t":"עו\"כ במכתב הנ\"ל, דאי מיירי בדבר שהוחזק בתולעים חייבים לבדוק, ואם לא הוחזק בתולעים אינו חייב לבדוק וכנ\"ל. וכנראה שמתכוין שדבר שהמיקרוסקופ מראה שיש בהם תולעים, הוא נחשב מוחזק בתולעים, אבל באמת אין פה שום חזקה שמה שלא נראה בעין של אדם, אינו אסור ולא מיקרי תולעים, ובודאי שלא שייך לקרא לו, מוחזק בתולעים.","b":false},{"t":"גם מה שכתב שאין ללמוד מחיידקים שאינן בעלי חיים כלל, משא\"כ תולעים שהתורה אסרתן בלא תנאי שיראו לעין רגילה. גם זה אינו מחייב כלל, דדין התולעים הלא נראים בעין של אדם כלל, רק על ידי מיקרוסקופ, דינם כחיידקים לכל דבר. ואמת שהתורה אסרה תולעים בלא תנאי, אבל אלו שהעין לא רואה אותם עדיין לא נקראים תולעים, ולא נכללו באיסור תולעים, וכאמור זה הכרחי, שאין שום סלקא דעתין למימר, שהתורה אסרה תולעים אלה, שהרי העין לא גילתה אותם, עד אחר אלפי שנים ממתן תורה, והוא עד שנוצר מיקרוסקופ שעל ידו גילו שיש תולעים קטנים מאד מאד, אבל כל הדורות אכלו ולא יכלו לדעת, ואיך יעלה בדעת שהתורה תאסור דבר שאי אפשר להמנע ממנו בשום פנים שבעולם.","b":false},{"t":"וא\"כ עולה דכל מה שכתבו גדולי האחרונים, וביניהם כל גדולי דורנו ועל ראשם מרן שליט\"א בשו\"ת יחוה דעת, שהביא דברי כל הפוסקים בזה, שכמעט כולם מתירים את התולעים שאין עין האדם מבחינה בהם. והתורה ניתנה לבני אדם אשר יצר ה' עפר מן האדמה עם איבריהם, ועם מעלותיהם ומגבלותיהם, ובודאי שהאיסור הוא על תולעים הנראים בעין הרגילה שיש לנו.","b":false},{"t":"ופירשתי בס\"ד דאין הכוונה שהתולעת אסורה, ומפני שלא נראית בעין לא אסרתה התורה, אלא שהתורה אסרה תולעים וחרקים, וכשלא נראים בעין מרוב קטנותם, אינם נקראים תולעים ואינם מכלל בעלי החיים כלל. וכבר הארכתי בזה, וזה נראה לי ברור בס\"ד.","b":false},{"t":"ועל כן אין מקום לאסור בעלי חיים, אלא אלו שעין אדם מבחינה בהם בלבד. זה הנראה לעניות דעתי בסוגיא זו.","b":false},{"t":"והקב\"ה יאיר עינינו בתורתו, ויצילנו מכל מכשול ותקלה, וינחנו בדרכו ובאמיתו לעולם.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"תשובה בעניין המסוק","p":[{"t":"בעהית\"ש. באחד בשבת תשעה עשר יום בטבת התשע\"א.","b":false},{"t":"\"להתיר בחינה קטנה, שבבחינת העגונה הגדולה, שעליה אמר שלמה: ראיתי דמעת העשוקים ואין להם מנחם, וכל מי שמתיר עגונה אחת בזה\"ז כאילו בנה אחת מחורבות ירושלים העליונה, להציל בחינה אחת מאשת חיל\". ע\"כ מהרב הפוסק בשו\"ת הב\"ח החדשות (סימן ס\"ד בסופו). והובא בראש סימן ג' בשו\"ת יבי\"א ח\"ו חאה\"ע. וע\"ש עוד.","b":false},{"t":"כרעם ביום בהיר היתה השמועה, על האסון הנורא, שאירע ביום ט\"ו באב התש\"ע, על התרסקות מסוק של צה\"ל בשמי רומניה, תוך כדי תרגיל אימונים שבוצע בתנאי מזג אויר קשים, וכל נוסעי המסוק נספו, ולא נותר שריד ופליט. והקמנו ב\"ד מיוחד שידון בתוצאות האסון ויפסוק במצבם של הנספים ודינם לכל פרטי הענין, ובמותב תלתא כחדא הוינא (כב' הגר\"ש דיכובסקי נר\"ו חבר ב\"ד הגדול בדימוס, והרה\"ר לצה\"ל הרה\"ג הר\"ר פרץ נר\"ו ואני הכותב). ואתו לקדמנא המומחים שטיפלו בזיהוי הנספים, ומסרו בפרטות את כל עבודתם אשר עשו באמת ובמסירות רבה, וגם שאלנו וחקרנו בענין כנדרש בחמורות אלה, ועל הכל השיבו על הן הן ועל לאו לאו, במקצועיות ובמיומנות, כי כל אחד מהם ידיו רב לו במקצוע שבו הוא עוסק, ובאמונה הם עושים.","b":false},{"t":"ושם עמנו היה גם סגן הרה\"ר לצה\"ל הרה\"ג ר\"א קרים נר\"ו שריכז את כל החומר וגם כתב חו\"ד בענין חמור זה.","b":false},{"t":"והנה דבר ברור וידוע הוא שבהתרסקות מסוק באופן חמור שכזה, לא יוצאים ממנו אנשים חיים, על פי דרך הטבע. שכן מדובר בפגיעה חמורה ביותר, שתוך כדי טיסה בין הרים גבוהים ובתנאי מזג אויר קשים במיוחד, פגע המסוק בקצה צוק של אחד ההרים הגבוהים, פגיעה שגרמה להתפוצצות המסוק והתפרקותו לחלקים קטנים, שהתפזרו על פני שטח של ארבע מאות מטרים, מפיסגת ההר ועד הנחל שבתחתיתו, שהרי עם עוצמת המכה מתפרצת אש נוראה האוכלת ומכלה את המסוק לכל חלקיו וכל אשר בו, ובד בבד מתפרקים כל חלקיו לחלקים קטנים הנפוצים לכל עבר, ואין צורך להאריך בתיאורים אלו שהם ברורים לכל מבין, וכך העידו אותם מומחים שהלכו שם וראו הכל בעיניהם, ובדקו וחקרו בשבע בדיקות ושבע חקירות על כל אחת בשבעה עינים, והתברר להם בבירור מושלם שכל הנוסעים נספו.","b":false},{"t":"וחלקים מגופות הנוסעים נאספו על ידי צוותי הצלה של הכוחות מרומניה תיכף ומיד לזמן האסון, מחשש שהגופות יושחתו ע\"י חיתו יער המשוטטים שם, עד הגיע צוותי הצלה מישראל ביום השני לאסון, והם השלימו את מלאכת האיסוף במסירות ובשלמות עד היכן שיד אדם יכולה להגיע.","b":false},{"t":"ושאלנו למומחים מנין להם שהששה האמורים, אכן היו כולם במסוק בהתרסקותו. והשיבו, שיש נהלים קבועים שלפני כל טיסה עורכים תוכנית מפורטת בכתב, והוא חוק ולא יעבור, ושם כותבים את תוכנית הטיסה ליעד והחזרה בפרטי פרטים, ורושמים במדוייק את כל אלה שמשתתפים בטיסה ותפקידיהם, איש על דגלו ואיש על מחנהו בתכלית הדקדוק. ואמרו לנו שבדקו היטב כל החומר הכתוב עם התוכנית של אותו יום, והיה רשום בדיוק מי ומי הטסים במסוק זה, ותיאור תפקידו של כל אחד ואחד, וכן בדקו את תדריך הטיסה של אותו היום, ובדקו גם באישור הטיסה והשוו את הכל זה לעומת זה, והכל היה ברור ומדוייק, ועוד שדברו בזה עם המפקדים במקום, ושיחזרו עמם כל הפרטים בע\"פ, ואישרו בפניהם את כל הפרטים עד לאחת.","b":false},{"t":"וכן ציינו שלפי הנוהל אין לרדת מהמטוס טרם הטיסה, אלא באישורו של המפקד. וכן ביררו באר היטב ששום אחד לא ירד מהמסוק בחניה וכיוצ\"ב, ולא נעלם אחד מהם.","b":false},{"t":"והגם שבמהלך התרגיל נחתו המסוקים, והיו חילופי טייסים, על כל פנים לא טסו חזרה לפני שבדקו את כל העולים, וביררו שכל אחד שב למקומו, והכל בודאות מוחלטת ואחרי זה טסו יחד שני המסוקים כמבנה אחד. וכן יש נוהל שהקברניט לא ממריא, עד שיקבל אישור מהמכונאי המוטס שהוא אחראי על המטען, וזה אינו מאשר עד שמוודא שכל מי שירד חזר אל מקומו.","b":false},{"t":"מציאת הגופות וזיהויים, נבדק למול דברי המפקדים והמדריכים, באתר הפריסה, ע\"י בודקים שונים שכולם מקצועיים ומיומנים היטב בתפקידם. כמו כן נעשה בירור עם צוות המסוק השני, לברר מי ומי הנוסעים, וכן התברר שאיש מהם לא ראה ולא שמע שמי שהוא נשאר בשטח, וגם לא היה שום קשר בין שני המסוקים על דבר זה או דומה לו.","b":false},{"t":"ומלבד כל הבירורים הנ\"ל אשר יש בהם די כדי להסיק שאכן רשימת הנוסעים במסוק היא ברורה, ואין חשש שחסר אחד מהם או התחלף אחד מהם, עוד התברר הדבר והוכח בהוכחה גמורה, על ידי בדיקת הגופות שנמצאו, ואותרו בהם טביעות אצבע של כל אלה הרשומים כנוסעי המסוק הזה. בלבד, בלא חסר ויתר, וכן נמצאו זיהויי דנ\"א שלהם. וכל הממצאים של הבדיקות והדגימות שנמצאו, תואמים במדוייק לדיווחים הכתובים, וכן לעדויות של המפקדים והמדריכים וכל האחראים, דיוק מלא באין פרץ ואין יוצא מן הכלל.","b":false},{"t":"והדברים הנ\"ל התבררו בפנינו במותב תלתא כחדא, כשבאו אנשי המקצוע בתחום טביעת אצבעות, וזיהוי דנ\"א, ומומחה לצילומי שינים וזהותם, והעידו על כל פרט ופרט והתלבנו הדברים הדק היטב היטב, עד שלא נותר שום ספק בדבר.","b":false},{"t":"עד כאן תיאור העובדות והעדויות לבירור המצב.","b":false},{"t":"והנה כשבאים לדון להלכה ולמעשה בדינם של נוסעי המסוק הנ\"ל, אשר עליו בסערה השמימה, בעת שהמסוק ונוסעיו צללו כעופרת בוערה המתנפצת ומתפרקת בין צוקי ההרים הגבוהים, אל קרקעית הנחל, אשר סלל נתיבות עזות בין שרשי ההרים ועיקריהם, עולה ונצבת לפנינו העובדא המצערת ומצמררת, ממה שעלה בגורלם של אנשי צוות המסוק, אשר לא נותר מהם שריד ופליט, והיו כולם למאכלת אש נוראה, וכל בית ישראל יבכו השרפה אשר שרף ה'.","b":false},{"t":"והדברים התלבנו והתבררו בבירור גמור, ובהוכחות מספיקות. הוכחות המתחלקות לשתי מערכות, המורכבות מפרטים רבים, אך הן מערכות מדוקדקות ומדוייקות, אשר טופלו בידים אמינות ומיומנות, הן של צוותי החקירה המקצועיים, שרמתם היא מהמעולות בכל העולם בתחומים אלה, והדברים ידועים ומפורסמים. והן על ידי אנשי הרבנות הצבאית אשר לדאבונינו ידם רב להם בנסיון גדול שנצבר במשך מלחמות ישראל, ובמה שביניהם, והם אמונים על דבר השם, זו הלכה, ויודעים את גודל האחריות הרובצת על צוארם, ומבררים הדברים בדרך נכונה ואמיצה, ולא מוותרים על כחוט השערה, אלא מתאמצים ומתיעצים בכל דבר, ותשועה ברוב יועץ. וגם טרם יקברו את הגופות, היו מתיעצים עמי בכל הענין באמיתות ובענוה.","b":false},{"t":"ובמערכת הבדיקות של הזיהויים, נעשו כל המאמצים להשיג כל מה שאפשר, אך יש חלק מהבדיקות שלא ניתן היה לבצעם בכל הגופות, וע\"כ יש מהם שנבדקו בשלשת הבדיקות הנ\"ל ושלשתם התאימו לזהות אחת, שלפי הרישום בצה\"ל או לפי המשפחות, זה מלמד שאכן זהו החייל פלוני. ויש מהם שביצעו רק שתי בדיקות מתוך השלש, ולא היה פחות משתי הבדיקות, ואע\"ג שכל אחת היא סימן מובהק וכדלהלן בעה\"ו. מ\"מ בשנים מן הבדיקות ניתן לפסוק ולהתיר אשת המת, שגם בשני סימנים שאינן מובהקים, יש להם דין של סימן מובהק, ק\"ו לשני סימנים מובהקים, דיש בזה זיהוי מוחלט לדעת מי הוא האיש הזה.","b":false},{"t":"והנה מעצם העובדא שאנשים אלו שהו יחדיו בצותא חדא תוך המסוק מרגע שעלה ועד שהתרסק, יש בזה כדי לדון בהם שהם מתו בודאות ואפילו לא היו מוצאים את הגופות. דמי ינצל ממסוק שהתפוצץ מתוך התנגשות חזיתית בצוק סלע שבראש ההר, אשר תיכף עלה כל המסוק בדם ואש ותמרות עשן, ואם קרה איזה פעם שיצא אדם חי מתוך פיצוץ כזה בתנאים כאלה (שכפי הנראה לא היה דבר כזה). בודאי שזה נס גלוי ממש, וקי\"ל דלא חיישינן לנס וכדלהלן. אלא דנים עפ\"י טבע הדברים, ולפי הנראה אין אפשרות בעולם שיצאו משם חיים, דאפילו בלא האש ובלי התפוצצות, אלא גם אם היו בתוך ארגז מעץ שעומד בקצה ההר הגבוה ההוא, והתחלק הארגז והתדרדר למטה, הרי פשוט וברור שלא היו מגיעים לקרקע עד שנעשים אברים אברים רח\"ל, וק\"ו בהיותם תוך מסוק עם כל מה שיש בו מן הדלק והחשמל ושאר משאותיו הרגילים להיות עמו. דפשיטא שאין אפשרות טבעית שינצל אחד מהם. ומה ששומעים לפעמים שיש ניצולים הוא בהיות קלקול במנוע, והוא נוחת נחיתה שלא כרגיל ונחבט על הקרקע דעד שנדלק הכל יש חלק מועט שמצליחים לברוח מן התופת, או בנחיתה על הים, אבל בזה שהתפוצץ מכוח החבטה בגבהי ההרים, לא נותר סיכוי לאחד מהם לצאת לחיים.","b":false},{"t":"ואע\"ג דאין מעידין על אדם שמת, אלא א\"כ ראוהו שמת ודאי, ואין בו ספק. מ\"מ נראה שבכהאי גונא חשיב בודאי שמתו כל נוסעיו של אותו מסוק.","b":false},{"t":"וסוגיא זו שרשה ביבמות (קכ\"א ע\"א) דתנן התם, נפל למים בין שיש להם סוף ובין שאין להם סוף אשתו אסורה. א\"ר מאיר מעשה באחד שנפל לבור הגדול, ועלה לאחר שלשה ימים. א\"ר יוסי מעשה בסומא שירד לטבול במערה, וירד מושכו אחריו, ושהו כדי שתצא נפשם, והשיאו את נשותיהם, ושוב מעשה בעסיא באחד ששלשלוהו לים ולא עלתה בידם אלא רגלו, אמרו חכמים מן הארכובה ולמעלה תנשא, מן הארכובה ולמטה לא תנשא.","b":false},{"t":"ובגמרא שם נאמר עלה דמתניתין. ת\"ר נפל למים בין שיש להם סוף ובין שאין להם סוף אשתו אסורה, דברי רבי מאיר. (ונמצא דמתניתין ר\"מ היא), וחכ\"א מים שיש להם סוף אשתו מותרת, ושאין להם סוף אשתו אסורה. היכי דמי מים שיש להם סוף, אמר אביי כל שעומד ורואה מארבע רוחותיו. ופירש\"י ז\"ל, כגון מערה מלאה מים והרואה שנפל שם, שוהה שם בכדי שאין יכול להיות חי בתוך המים ובא לו. עכ\"ל. וע\"ש בכמה עובדות שהביאו בענין זה. והעולה הוא דכשאפשר לראות מכל רוחותיו של אותו מקום, והעד מעיד שעמד וראה במשך זמן שלא עלה משם, מעידים עליו ואשתו מותרת, אבל אם יש אפשרות שיכול לצאת למקום אחר, או שלא יכולים לראות כל הכיוונים מסביב, דעי\"ז יש ספק אולי יצא ממקום אחר, ולא ראוהו, אין משיאין את אשתו. דאין משיאין אשתו, עד שיתברר בודאות שהוא מת.","b":false},{"t":"ואפילו אם יש ספק רחוק אין להשיא את אשתו, וכמו מעשה שנאמר שם בברייתא שר\"ג היה בא בספינה וראה ספינה אחרת שנשברה והיה מצטער על ת\"ח שבה, ומנו ר\"ע וכשעליתי ליבשה בא וישב ודן לפני בהלכה, אמרתי לו בני מי העלך, אמר לי דף של ספינה נזדמן לי, וכל גל וגל שבא עלי נענעתי לו ראשי. וכן מעשה בר\"ע שהצטער על רבי מאיר, וכששאלו בני מי העלך, אמר לי גל טרדני לחברו וחברו לחברו עד שהקיאני ליבשה, ואמרו באותה שעה כמה גדולים דברי חכמים שאמרו מים וכו', ושאין להם סוף אשתו אסורה.","b":false},{"t":"ומעשים אלו ללמד באו דאע\"ג דהאניה נשברה בלב ים, ונפלו כל נוסעיה בגלים ענקיים יעלו שמים ירדו תהומות, ושם רמש ואין מספר, ולויתנים וכרישים ושאר חיות פרא הצמאים לדם כי יזדמן להם לטרף, ועם כל זה ניצל ר\"ע וניצל ר\"מ. וצ\"ל דקים להו לחז\"ל שאין זה בדרך נס, אלא עדיין היא הצלה טבעית, וע\"כ אין משיאין את אשתו.","b":false},{"t":"מ\"מ אין זה דומה לנידוננו, דשם אמנם נשברה הספינה ומסתמא אינה גדולה בממדיה מן המסוק, אבל ספינתם נוסעת במפרשי הרוח ולא באש זלעפות של בנזין מיוחד כמו זה של מטוסים, אשר נדלק באש להבת שלהבת שבכוחה להתיך פלדה וברזל עד שיהיו נשפכים כמים, וכמו שהיה בימינו בפיצוץ הנורא של בניני התאומים בנו יורק שבאמריקא בעיר מנהטן, שע\"י שפגעו אותם רשעים ארורים מן המחבלים הידועים לשמצה, במטוס נוסעים באחת הקומות הגבוהות, המטוס התפוצץ בעוצמת ההתנגשות ונפלה אש נוראה שכילתה בניני ענק של מאה ועשרים קומות על כל מה שהכילו כמו עיירה שלמה, ונהרגו למעלה מחמשת אלפים מבני אדם שהיו שם, וכל המתכת החזקה שממנה בנוי השלד של הבנין נמסה ונשפכה כמים, והכל בזמן קצר ביותר. ומעט מאד היו הניצולים, ומן הקומות העליונות לא ניצלו כלל. וק\"ו שכאן התפוצץ המסוק באויר, כשהוא תלוי על בלימה ובגובה עצום מאד דבודאי הכל הותך באש התופת, ותוך כדי הנפילה היה נחבט ומתגלגל מצוק זה לאבן זאת, וממנה נשלכת כקופסה לעוד צוק הנקרה על דרכה, והכל בעוצמה מסחררת עד הגיעם אל תהום פעורה בנחל שבקרקעית ההרים. ומי ישרוד את כל גלגולי מחילות התופת הללו. וכדי לשרוד את זה צ\"ל נס גלוי בסדר גודל של קריעת ים סוף. ולנסים לא חיישינן.","b":false},{"t":"דאמרו עוד שם, תנו רבנן נפל לגוב אריות אין מעידין עליו, לחפירה מלאה נחשים ועקרבים מעידין עליו, רבי יהודה בן בתירא אומר אף לחפירה מלאה נחשים ועקרבים אין מעידין עליו, חיישינן שמא חבר הוא. ות\"ק אגב איצצא מזקי ליה. ופירש\"י ז\"ל, שמא חבר הוא, יודע ללחוש. אגב איצצא, שדוחקן שעומד עליהם, אבל גוב אריות רחב הוא ופעמים שאינם רעבים ואין אוכלים אותו. עכ\"ל. וכל השם לבו לחילוקים שאמרו רבותינו בין גוב אריות, ובין חפירת נחשים ועקרבים, יראה שהחילוק הוא, שבאריות יש צד שלא יאכלוהו כשאינם רעבים, ואדהכי אפשר שימצא דרך לברוח מהם, ואילו בחפירת נחשים שהיא צרה ובעל כרחו דורך ועומד עליהם, בודאי ישכו אותו וימות. וע\"כ יכולים להעיד עליו להתיר את אשתו, כי בודאי ימות שם.","b":false},{"t":"עוד אמרו שם (בעמוד ב') תנו רבנן נפל לתוך כבשן האש מעידין עליו, נפל תוך יורה מלאה יין ושמן (מרותחת על האור. רש\"י.) מעידין עליו, משום רבי אחא אמרו של שמן מעידין עליו מפני שהוא מבעיר, של יין אין מעידין עליו מפני שהוא מכבה, אמרו לו תחלתו מכבה וסופו מבעיר.","b":false},{"t":"עוד אמרו שם, א\"ר מאיר מעשה באחד שנפל לבור הגדול וכו', תניא אמרו לו לרבי מאיר אין מזכירין מעשה נסים. והתוספות שם כתבו תימא לר\"י והא קאמר לעיל נפל לגוב אריות וכן למים שאין להם סוף אין מעידין עליו, ותירצו דשם זה לא נס ממש, אלא יש לתלות שאינם רעבים, ובמים שאל\"ס יש לתלות בדף של ספינה. ושוב הביאו ירושלמי שכתב בגוב אריות אין מעידין עליו שמא נעשה לו נס כדניאל, נפל לכבשן האש אין מעידין עליו שמא נעשה לו נס כחנניה מישאל ועזריה. וע\"ש. ומשמע מדברי התוספות דלפי הבבלי דאין סומכין על הנס, היינו שלא תולין בנס גמור, אבל בכה\"ג שאפשר שתהיה הצלה, כמו בגוב אריות, אע\"פ שזה דבר רחוק שינצל מזה, בזה אנו מצרפים האפשרות שיהיה נס ותהיה הצלה. אבל בדבר שצריך נס גמור ואין דרך של הצלה דרך הטבע, בזה לא חיישינן לנס.","b":false},{"t":"על כל פנים מפורש בברייתות, דבמקום שאין סיכוי טבעי שינצל מאותו מקום שנפל בו, מעידין עליו ומתירין את אשתו. ומדקיימא לו נפל לכבשן האש מעידין עליו, וכן פסקו שם הרי\"ף והרא\"ש ז\"ל. וכ\"פ הרמב\"ם והטוש\"ע (סימן י\"ז סעיף ל'), ש\"מ דלא קימא לן כהירושלמי דקאמר שאין מעידין עליו שמא נעשה לו נס כחנניה מישאל ועזריה. וע\"ש.","b":false},{"t":"ומסוק זה שהתנפץ בצוק ונדלק, הרי הוא גרע מכבשן האש שכוח האש הזה חמור מכבשן של אש, ועוד שהוא בגבהים עצומים תלוי על בלימה בין שמים לארץ.","b":false},{"t":"והנה בקרבן נתנאל על הרא\"ש (פרק ששה עשר סימן ה' אות ע') כתב, נפל לתוך כבשן האש, דוקא בכה\"ג שהוא עמוק ואינו יכול לעלות משם, אבל אם נפל לתוך המדורה י\"ל שמא יצא. רשב\"א והמגיד, א\"נ לתוך המדורה והוא ששהה עליו כדי שישרף. עכ\"ל. וגם הרשב\"א יודה בנידון זה דאין שום פתח להצלה שאם יצא יפול מגבהים כאלה ובודאי ימות ואם ישאר אותו דבר ואין כאן דרך שתצילהו. וראיתי בנמוק\"י (דף מ\"ה סוף ע\"ב) שגם הוא מחלק בין כבשן שהוא עמוק ואינו יכול לעלות ממנו, ובין מדורה שאין מעידין עליו אא\"כ שהה שם עד שנשרף. וגם הוא ז\"ל יודה בנידון זה. וכנ\"ל.","b":false},{"t":"ואע\"ג דבכל הברייתות מיירי שראו אותו שנפל לכבשן האש, או ליורה רותחת של שמן או של יין וכו'. וכאן לא ראתה אותם עין אנוש בעת הזוועה. מ\"מ אחר שהתברר לנו ע\"י הרישומים של המפקדים ושל התוכניות, שאלו הם האנשים שטסו במסוק זה בטיסה זו, והתברר הדבר בבירור גמור, הרי זה כמו שעמדו עדים וראו אותם תוך כבשן האש הנורא הזה. דכל דבר שהתברר הוי כמו שראוהו בעיניהם.","b":false},{"t":"תדע דאפילו במקום דבעינן עדות גמורה של עדים כשרים, אמרינן דאם זה ברור דאנן סהדי שכך הוה, חשיב כעדות שראו שנעשה הדבר. וכן ראיתי באגרו\"מ (חיו\"ד ח\"א סימן מ\"ז) שדן חלב של החברות הגדולות, שיש פיקוח ממשלתי שלא יערבו בו חלב אחר אלא של פרות בלבד. וכתב תחילת דבריו, דידיעה ברורה היא כראייה ממש. כהא דשבועות (ל\"ד) גם לעדות דממון, וגדולה מזו איתא בתוספות ביבמות (דף מ\"ה) בשם יש מפרשים גם לדין ראיית ב\"ד לטבילת גר עיי\"ש, וזהו גדר אנן סהדי בהרבה מקומות. וגם לעדי קיום של קידושין, שאפילו לא ראו אלא היחוד, הוא כמו שראו הביאה ונעשית א\"א גמורה, לחייב הבא עליה אח\"כ, ושלא יתפסו בה קידושין אחרים. ועוד דגם אנן סהדי פחותה מזו כהא דחזקה אין אדם עושה בעילתו בעילת זנות, אמרינן שהיא כראיה ממש ונחשב כהוו עדים לקיום, אפילו לקולא שלא להצריכה גט מהשני, בקטנה שלא מיאנה והגדילה וניסת לשני, בכתובות (ע\"ג). ושמואל שחולק, הוא משום דאין אדם יודע שאין קידושי קטנה כלום, ועל דעת קידושין ראשונים בעל. ע\"ש.","b":false},{"t":"ורב שאמר שהיא מקודשת, בודאי יודה שיש מיעוט שאין יודעים שאין קידושי קטנה כלום, מ\"מ כיון שהרוב יודעים אמרינן שמקדשה בביאה והיא א\"א גמורה, וגם בחזקה דאין אדם עושה בב\"ז, בודאי שיש מיעוט שכן עושים, אפ\"ה אמרינן דמקדש לה בביאתו, וע\"ש שכתב עוד דיש ידיעה שגם בנפשות נחשב כראיה, דבמנאפים אמרו עד שיראו כדרך המנאפים, הגם שהחיוב הוא עד שיהיה כמכחול וכו', ונהרגין על זה, וע\"ש.","b":false},{"t":"וי\"ל דק\"ו לנידוננו שלא הצריכו עדות גמורה, דעד אחד כשר לעדות זו ומתירים אשה על פיו אם אמר שמת בעלה, ואפילו אשה או עבד כשרים, ואפילו עד מפי עד, וכן גוי מסל\"ת, באופן שההיתר תלוי בבירור הענין לאשורו, ומאחר והתברר ע\"י מסמכים של הצבא די בכך, ונחשב כמו שראו עדים שאנשים אלו נכנסים למסוק, ונסגרו הדלתות והמריאו.","b":false},{"t":"וידוע דמסמכים של הצבא, נחשבים לנאמנים וסמכינן עלייהו, אפילו אם הודיעו במסמך שפלוני נפל בקרב וכיו\"ב, מתירים את אשתו, ואפילו בצבא של גוים. ואע\"ג שהגוי פסול לעדות מן התורה, וכמ\"ש התוספות במסכת גיטין (ט' ע\"ב ד\"ה אעפ\"י), וכ\"כ בשו\"ת כתב סופר (סי' כ'), מ\"מ כתב בספר עזרת נשים (עזרה שמינית אות ג') דאעפי\"כ י\"ל דערכאותיהם נאמנים מן התורה, משום דהוי מילתא דעבידא לאגלויי, ולא מרעי נפשייהו. שזה הטעם שע\"א נאמן על מיתת הבעל, דהוי מילתא דעבידא לאגלויי. וכמ\"ש התשב\"ץ (מסימן ע\"ד עד סימן פ\"ד), וכן הוא בנוב\"י (סימן ל\"ג), ובפרט שבעדות אשה א\"צ משפטי העדות, וכמ\"ש בחידושי הרי\"מ (סימן י\"א), והחת\"ס (סימן צ\"ב), דמהתורה די שנדע שהדבר אמת. י\"ל שהערכאות שיש להם חזקה גדולה ולא מרעי נפשייהו, אפשר שיהיו נאמנים מן התורה.","b":false},{"t":"וכבר פשטה הוראה בין הפוסקים לקבל דברי הערכאות ולהתיר האשה, ובפרט די\"א שאין הגוי פסול לעדות מן התורה. וכמ\"ש בהג\"א בגיטין (י' ע\"ב), במשנה דכל השטרות העולים בערכאות של נכרים אע\"פ שחותמיהן נכרים כשרים, וכתב משם רבינו יקיר, שנכרי מצד עצמו כשר לעדות, אלא שאין מאמינים אותו מפני שחשוד לשקר. וע\"כ בערכאות דקים להו לחז\"ל שאין משקרים, נאמנים הם. וכ\"כ התוספות בב\"ק (פ\"ח) ד\"ה יהא עבד כשר, לפי שיטת רש\"י. ובעזרת נשים (עזרה שמינית אות א') כתב כן משם שו\"ת בית שלמה (סימן מ\"ז), והכת\"ס חאה\"ע (סימן כ\"ג), ושואל ומשיב מהדו\"ק (סימן קפ\"א), והבית יצחק (סי' פ\"ד), ועוד שהמרדכי (ריש גיטין) כתב בשם ספר חכמה דכשידוע שהעכו\"ם לא מרעי נפשייהו, נאמנים מן התורה.","b":false},{"t":"ובשו\"ת שמע שלמה ח\"א (חאהע\"ז סימן ה') הבאתי דברי החת\"ס ח\"א (סימן מ\"ג) שכתב שהגאון הגדול בדורו מהר\"ם באנעט ע\"ה השיב לו, דאין להתיר עדות הערכאות אם אינם מסיחים לפי תומם, אע\"פ שלא משקרים, שהתורה אמרה אל תשת רשע עד. והרי הרא\"ש לא התיר עדות בעלי תשובה משום שאין תחילתם בכשרות. והחת\"ס השיב לו שהאחרונים התירו בההיא דהרא\"ש ז\"ל. והאריך לחזק דבריו להתיר בערכאות גם כשאינם מסל\"ת, ובסימן צ\"ד שם, הוסיף עוד דנאמנות הערכאות היא מעיקר הדין משום דקים להו שאינם משקרים, וכהאיבעית אימא דגמרא בגיטין שם, וכתב שזה עדיף מעדים שאין נאמנים אלא מגזרת הכתוב, דאפשר שהעדים משקרים אלא התורה האמינתם. וכמשמעות דברי הרמב\"ם (ספ\"ז מהלכות יסודי התורה ה\"ח). וכן פסק הגאון משיב דבר (סימן כ\"ג). וכתב דבגוי רגיל שאין לו חיוב להגיד אמרו דבעינן מסל\"ת, אבל הערכאות שחייבים להגיד לא בעינן מסל\"ת. וכן פסק להקל למעשה הגאון ר\"י אלחנן בספרו באר יצחק (סימן ה' ענף ב') וגם בספרו עין יצחק. וגם באבני נזר (סימן ס\"ז) כתב שדעת רוב האחרונים להתיר בערכאות, וגם הוא התיר, וכן הוא במהרש\"ם ח\"ג (סימן י'). והבאר משה ירושלמסקי (סימן ו') כתב שכבר פשטה הוראה לסמוך על עדות הערכאות, והכי נקיט בערוך השלחן (סימן י\"ז אות פ') שגדולי הדורות שלפנינו התירו בפשיטות, ועיין בכל זה באוצר הפוסקים (סימן י\"ז סעיף י\"ד ס\"ק קי\"ג) שהאריכו בכל זה מאד מאד.","b":false},{"t":"ובין היתר הזכירו דברי מהרי\"ק (שרש קכ\"א) שהעלה להתיר, וכ\"פ הכנסת יחזקאל (סימן נ\"ב) ומהר\"ש ענגיל ח\"א (סי' ע\"א). וסדר אליה רבא (סימן ג').","b":false},{"t":"והנה שם בשמע שלמה (אות ד') הזכרתי מדברי הפוסקים שהחמירו בעדויות של השופטים וערכאות מפני חששות שונות, ואח\"כ הבאתי דברי הפוסקים שסוברים שאין לחוש לאותם חששות, ושכן כתב מהר\"ם שיק (סימן מ\"ב), ובשו\"ת מהר\"י ענגיל (סי' כ\"ו) הביא דברי הרשב\"א ז\"ל בתשובה ח\"א (סימן תתקפ\"ה) והביאה מרן ז\"ל בב\"י (סימן ס\"ח), שגם במקום שהערכאות מעמידים נער שיקבע מספר ההרוגים ושמותיהם, שייכת חזקה זו שלא משקרים, דכל מי שמשמש בצבא אימת הצבא עליו. וכ\"כ הבאר יצחק סימן ה', והשו\"מ מהדו\"ק (סי' קפ\"ח), ובית יצחק (סימן פ\"ד). ע\"ש.","b":false},{"t":"ובנידון דידן קיל טפי, דלא שייך בזה החששות שנאמרו שם, דשמא יאמר כך שמעתי, וזה מה שאמרו לי, וכו' כיעויין שם. דגם המפקדה יושבת וקובעת את ניהול הטיסות וכיצד ומתי יתבצעו, ולא יכולים להתנער מאחריות, שאם לא יעשו הרישום והכיתוב בתכלית הדקדוק והדיוק, יבואו על עונשם וכדאי בזיון וקצף, ואין שום השתמטות, ותירוצים לא יועילו להם. ובפרט שהרישומים נענשו בכמה אופנים וע\"י כמה אנשים שונים, ועוד שזה לא היה בשעת מלחמה אלא בעת שלום, וזה מקרה יחידי ואין שום בלבול. וגם שהוקמה ועדת בדיקה של מומחים בעל פה. ובכה\"ג נראה לענ\"ד שכולי עלמא יודו דיש לסמוך ע\"ז בודאות.","b":false},{"t":"ועוד שכתבתי שם באותה תשובה (אות ד' ד\"ה עוד יש) דגם המחמירים שלא לסמוך על ערכאות אלא במסל\"ת, הנה מצאנו לכמה פוסקים דס\"ל שדנים את הכתוב בפרוטוקולים של הערכאות כדין עדות במסל\"ת, וכמ\"ש החת\"ס (סי' מ\"ד) שכתב וז\"ל, אבל בצבא המלחמה או בשפיטהל הם כותבים הדברים לעצמם, וא\"כ זה המספר הבא לפני הערכי, ואומר לו פלוני מת נחשב כמסל\"ת. וכן בספר תוספת חיים בקונטרס העגונות (דף מ\"ח) כתב שכל מה שתכתב בפרוטוקול לצורך עצמם הוי כמסל\"ת. וכן בבית שלמה (סימן מ\"ז) כתב בשיטת הריב\"ש, דכשבא להודיע למלאת חובתו שפיר נחשב למסל\"ת. וכבר כתב הרמ\"א סימן י\"ז סט\"ו בהגה, שגוי השואל לגוי הוי מסל\"ת. וכן הכריע מהר\"ם מלובלין (סימן ז') שלא כדברי הר\"ן ז\"ל. ומהר\"י ענגיל (סימן כ\"ו) כתב דמ\"ש ה\"ה ז\"ל (פ\"י מה\"ג הכ\"ח) דמסל\"ת בכתב אינו נאמן, היינו דוקא בסתם גוי שצריך לבחון דרגת המסל\"ת, אבל זה שלא אמר ליהודי אלא לחברו הגוי שאין לו נ\"מ לדינא, וגם שאינו לשם עדות אלא שכותב לעצמו לידיעה, בזה אין חילוק בין בכתב ובין בע\"פ. ודלא כמו שחשש הבית אפרים, וכן העלה בשו\"מ (מהדו\"ק ח\"ד סימן קמ\"ו) ובתפארת יוסף (סימן ז') כהנ\"ל. ועיין בעזרת נשים שם (אות י\"ב) מה שכתב בכל זה.","b":false},{"t":"ועוד דמהר\"י ענגיל באוצר יוסף (עמוד ג') כתב שא\"צ לדרוש בערכאות מנין להו, דהוי כעד מפי עד, שדעת מהר\"י ווייל (בש\"ע ס\"ה), שאין צריך לשלוח אחר הראשון לשואלו אפי' כשהוא בעיר. ולא דמי לאמור בש\"ע ס\"ח, שצריך לשאול לעד איך ראית ובמה ידעת. דרק כשאמר האשה מותרת, הוא שצריך לשואלו, אבל אם אמר שהבעל מת, א\"צ לשואלו. וע\"ש בעזרת נשים שם (אות י\"ד) שהביא דבריו באורך. וע\"ש מה שכתבתי עוד בזה בעוניי לאותו נדון.","b":false},{"t":"ובנידון זה הוא פשוט טפי, שאלה נוהלים המונהגים בכל הטיסות שבכל העולם, וק\"ו בצבא מסודר שיש בזה הקפדה יתירה, ויש עליהם אימה ופחד לדייק בתכלית הדיוק, ועל כל דבר ודבר מעמידים ועדת חקירה נוקשה, ולא נושאים פני איש.","b":false},{"t":"ואע\"ג דיש עוד אריכות רבה מאד בענינים אלו בדברי הפוסקים חדשים גם ישנים, וכבר הארכתי בזה בשמע שלמה ח\"א שם. מ\"מ בנידון זה הדבר פשוט וא\"צ להאריך בו כלל, שאין מי שיפקפק בנאמנות הרישומים והכיתובים של המפקדה בדבר מי הם האנשים שעלו לכל טיסה ומה תפקידם וכו'. ובפרט אחר שועדת החוקרים המומחים הצליבו את כל סוגי הכיתובים שנעשו בין ע\"י המדריכים ובין ע\"י המפקדה שבכל השלבים, ונמצא הכל מתאים ומורה שאלו הם האנשים שעלו למסוק הזה בטיסה הזאת.","b":false},{"t":"ואם לא די בכל זאת, הנה הבדיקות המקצועיות של הד.נ.א. ושל טביעות האצבעות, ומערכות השיניים הסירו כל הספקות לגמרי, שהוכח בבירור גמור שאלו האנשים שנכתבו ונרשמו כנוסעי המסוק ההוא בטיסה ההיא, אכן אלו הם שגופותיהם נמצאו ונלקטו ממקום התופת, בדיוק כפי שהם רשומים באותה טיסה, לפי כל הבחינות שנעשו ע\"י גדולי המומחים.","b":false},{"t":"ואחר שהתברר היטב ובודאות שכל אלו היו במסוק בעת שהתנפץ והתפוצץ, הרי די בזה כדי לקבוע שהם מתו. ומי מהם שהיה נשוי, מתירים את אשתו, שהרי זה יותר ממי שהעידו עליו שנפל לכבשן של אש וכו', שבודאי ימות ומעידין עליו להשיא את אשתו. וכאמור לעיל. שכן לעניות דעתי אין בזה ספק שבמצב זה כל אלה שהיו שם נספו, אם לה היה נס מופלא וגלוי, ואין אנו סומכים על הנסים וכנ\"ל.","b":false},{"t":"וגם אם יתעקש מאן דהוא להעלות על דעתו שאולי נשאר אחד מהם בחיים, מ\"מ הרי ודאי ופשיטא שלא נשאר במסוק, שהרי המסוק התפוצץ ונחלק לחלקים קטנים והתפזר הוא וכל אשר בו בין ההרים הגבוהים, ונזרקו מגובה עצום ונתפזרו פזר גדול על פני שטח של ארבע מאות מטרים, וחלקים מהם נחתו על גבי זיזים שונים מרומו של ההר ועד קרקעית הנחל למטה. ואין ספק שכולם מתו. ועל כל פנים אין בעולם מי שיחלוק, שלכל הפחות יש בזה רוב מוצק וברור כשמש, שעפ\"י רוב זה לא ימצא אדם חי בפיצוץ כזה. אלא שאם נאמר כן, לא נוכל להתיר שום אחת מנשותיהם, שהלכה היא שאין מעידין להתיר אשתו אלא במקום שבודאי ימות שם ולא עפ\"י זה שיש רוב סיכויים שימות, שהרי במים שאין להם סוף רובם של הנופלים שם ולא ימצאו מתים הם, ואפ\"ה אין מתירים מחשש שמא הוא מהמיעוט ומפני חומר האיסור של אשת איש.","b":false},{"t":"וכן נמי בנפל בגוב אריות, בודאי דרובם למיתה, ואפ\"ה לא מעידים עליו להתיר את אשתו וכנ\"ל. (וכבר כתבתי שלפי דעתי נראה ברור שהמצב הזה הוא כמו שהעידו עליו שנפל לכבשן של אש או יורה של שמן רותחת שמעידים עליו.)","b":false},{"t":"מ\"מ מצאנו להפוסקים דכשיש תרי רובי מתירים את אשתו. אעפ\"י שאין ודאות גמורה שהוא מת. וכמו שכתב מרן הראש\"ל ביבי\"א ח\"ו (חאה\"ע סימן ד') במטוס של צה\"ל שנפגע ע\"י טיל של האויב והתפוצץ ונפל לים, וחברו של הטייס הנז' שטס במטוס אחר סמוך לו (שטסו כזוג לתקיפת סוללות טילים של האויב, אמר ששמע את ההתפוצצות וראה שברים מהמטוס בוערים וקרא לו במכשירי הקשר ולא נענה, והסתכל סביב לראות אם הטייס ההוא הצליח לנטוש את המטוס ע\"י מצנח ולא הבחין בנטישה, וכתב מרן נר\"ו שם, דבמקרה זה אין אומרים לא ראיתי אינה ראיה, כמ\"ש בכתובות (כ\"ג ע\"א), דשאני הכא שהם טסו יחד וכל אחד מצווה לשים לב על חברו ולדווח על כך. (ועכ\"פ כיון שהמטוס נפל למים שאין להם סוף אין לנו ודאות שהוא נהרג, ומכלל ספק לא נפק לגמרי).","b":false},{"t":"וכתב דיש כאן תרי רובי למיתה, שעפ\"י הרוב הטייס נהרג בהתרסק המטוס, ואת\"ל שנפל לים, רוב הנטבעים למיתה, ובתרי רובי י\"ל דאזלינן לקולא, וכמ\"ש הגאון רבי יעקב אב\"ד דאזמיר, בשו\"ת בית יעקב באשה עגונה שהעיד גוי מסל\"ת שהיה בעלה גוסס בעת שטבע במים שאין להם סוף, ופסק להתירה להנשא, דרוב הנטבעים במים שאל\"ס למיתה, ורק רבנן החמירו לחוש למיעוט הנמלטין, וכאן יש עוד רוב דרוב הגוססין למיתה והו\"ל תרי רובי, רוב הגוססין למיתה ורוב הנטבעים למיתה, בזה מותרת גם מדרבנן.","b":false},{"t":"והוכיח כן מכתובות (ט\"ו ע\"א) שנערה שנאסרה אסורה לכהן אפילו שרוב העיר כשרים לכהונה, שחז\"ל החמירו מפני מעלת יוחסין. ומ\"מ בתרי רובי כשרה לכהן, וכ\"פ בש\"ע אהע\"ז (סימן ו' בסופו). וה\"נ אע\"פ שהחמירו במים שאל\"ס, כשנוסף לזה עוד רוב אחר שריא, וכתב שם שמר חמיו גאב\"ד טיקטין מהר\"ר יצחק אייזיק ז\"ל כתב לו שאין לסמוך על זה, דגם בתרי רובי חששו למיעוטא, ואין לדמות זה ליוחסין שאין מדמים גזרות חכמים זו לזו. וכמ\"ש התוספות בכתובות (פ\"ד ע\"א) בד\"ה לכתובת אשה ע\"ש. שו\"כ דאולם גאב\"ד בריסק מה\"ר מרדכי ז\"ל הסכים להבית יעקב הנז', וכן עשו מעשה והתירוה להנשא. ומרן נר\"ו כתב שם לחזק את ההיתר הזה, עפ\"י מה שהעלה בסימן הקודם דהעיקר כדברי רבותינו הספרדים [הנזכרים בפני יהושע בקו\"א לכתובות (סימן מ\"ו) וז\"ל, ויאמר יהושע עתה באתי במגילת ספר כתלמיד הדן לפני רבותיו בקרקע, ואף שיודע אני מיעוט ערכי לעומת גדולי האחרונים הספרדים, ומכללם הפרי חדש והגט פשוט שכל אחד מהם קטנו עבה ממתני, ומה גם כולם, ומתירא אני להכניס ראשי ביניהם, שמא ירוצו את גולגולתי, אמנם עצור במילין לא אוכל וכו'. עיין ביב\"א שם סימן ג' אות י\"ב מזה.] דנקטינן להלכה ולמעשה כרבותינו הספרדים להתיר עגונא עפ\"י ספק ספיקא אע\"פ שהוא נגד חזקת אשת איש. ולפי זה כ\"ש הוא שיש להתיר עגונא עפ\"י תרי רובי, דהתוספות בכתובות (י\"ד ע\"א) בד\"ה אלמנת עיסה כתבו בשם ר\"י וריב\"א דעיסה היא משפחה שנטמע בה ספק חלל וע\"כ חשיב לה לקמן ס\"ס, שכל א' מהמשפחה ההיא ספק אם הוא שנטמע או לא, ואם זה הוא שנטמע, עדיין יש ספק אם הוא חלל או כשר. וכתבו שם דבת עיסה אין לה חזקת כשרות, וע\"כ לא הקילו בה, אע\"ג דבעלמא מקילין בס\"ס, כאן עשו מעלה ביוחסין, וכמו שהצריכו לקמן תרי רובי, אע\"ג דבעלמא ברוב אחד סגי, עכ\"ד התוס', ולפ\"ז יוצא דתרי רובי עדיף מס\"ס, שביוחסין לא התירו בס\"ס כשאין חזקת כשרות, אבל בתרי רובי התירו. וא\"כ בעגונא דקי\"ל שמתירים בס\"ס ק\"ו שיש להתיר בתרי רובי. וש\"י.","b":false},{"t":"וכתב דבמטוס יש תרי רובי להקל, שעפי\"ר אם הטייס היה צונח היה חברו רואהו, ואפילו את\"ל שנפל חי לים הרי רוב הנטבעים למיתה, ויש להתיר את אשתו לכתחלה. וע\"ש עוד באות ב', שמפלפל ומסלסל בדבר ה' זו הלכה באורך ובעומק של סוגיא קשה זו, ותרוה נחת.","b":false},{"t":"והכא נמי דעדיפא מינה דההתפוצצות היתה בפגיעה בצוק ומיד התפוצץ ונהרס כל המטוס, והרוב למיתה בודאי, ואפילו את\"ל שפלט אחד מהם הרי לא לים הוא נפל אלא לסלע ההרים וצוקיהם ומי יפול מגבהים אלה ויחיה, וגם שחיפשו שם מיד הצוות הרומני עוד באותו יום ואספו וליקטו, ועוד באו למחרת הצוות הישראלי ולא הניחו אבן על אבן בחיפושיהם ודקדוקיהם, ולא נמצא זכר של חיים. ולכל הפחות יש כאן תרי רובי למיתה ויש להתיר האשה.","b":false},{"t":"עוד ראיתי בחפש'י לדברי הגאון רבי משה פיינשטיין ע\"ה, באגרו\"מ חאהע\"ז (סימן מ\"ח) שכתב בענין עדות הערכאות על אחד שעלה לאוירון והאוירון נפל בים, ותחלה כתב בפשיטות גמורה, שיש לסמוך עליהם משום דערכאות לא חשידי לשקר, וכדברי החת\"ס ועוד אחרונים, וגם שהודיעו קודם ששאלה וקודם שהגיע הזמן שצריכה לשאול, יש לזה דין מסל\"ת שלא רק שלא שאלה אלא עדיין לא הגיע הזמן ולא היה עליהם להשיב.","b":false},{"t":"ומעתה יצא לדון בזה שנפל למים שאין להם סוף, וכתב דיפה כתב הרב השואל שיש בזה תרי רובי, דרוב הנופלים מאוירון מתים תיכף, ורוב מאלה שנטבעים במים שאין להם סוף מתים, והאחרונים מתירין בתרי רובי, וע\"ש שהזכיר מה שהקשה הפ\"ת שמהתוס' יבמות (קכ\"א) מוכח שגם בתרי רובי אסור. אבל לדינא הא מתירין האחרונים. וכתב שבחידושיו תירץ קושיא זו באופן נכון.","b":false},{"t":"עו\"כ שבנפילה מאוירון שזה גבוה מאד אין גם מיעוט שניצולין, וגם יותר מעשר שנים שלא נשמע כלום ממנו, שדעת תה\"ד בפסקים (סי' קל\"ט) ואחריו והחת\"ס (סי' נ\"ח וסי' ס\"ה), שבזמננו כל אדם כצורבא מדרבנן שיש לו קול שע\"י הדואר וכו', אפשר להוודע אפילו מקצה העולם, וכ\"ש עתה בימינו ע\"י טלגראם וטלפון וכדומה שהוא לאין מספר יותר מהיר מזמן החת\"ס וכ\"ש מזמן תה\"ד, ואולי באופן זה היו מתירין בלא ספק כלל, וגם יש שיטת מהר\"א מוורדון שבמרדכי, שבעצם מים שאל\"ס הוא מתיר לאחר הרבה שנים שמשערים חכמי הדור ויר\"ש שאין להתספק עוד שהוא חי, וחזי לאצטרופי, וע\"ש עוד. עכד\"ק.","b":false},{"t":"(והצירופים שהזכיר כבר הבאתי אותם בתשובו' הקודמות בעניני העגונות והן נדפס'ו בחלקי שו\"ת ש\"ש).","b":false},{"t":"ועינינו הרואות שגם הגרמ\"פ זללה\"ה פשיטא ליה להתיר בתרי רובי למיתה, וכמ\"ש ג\"ע ביביע אומר הנ\"ל.","b":false},{"t":"ובאמת שהמקרה שבו אנו עסוקים הוא חמור טפי מנדונו של הגר\"מ פיינשטין ז\"ל, שבנדונו כנראה האוירון נפל מאליו מחמת קלקול במנועים וכיו\"ב שמנעו המשך עמידתו באויר, ונפל לים ואפ\"ה התיר. וק\"ו בן בנו של ק\"ו לנידון זה, שהמסוק התנפץ בצוק של הר גבוה מאד וכולו נשבר ועלה באש ונתפרק לפריטים קטנים והתפזר פיזור גדול מאד. דבודאי שיש כאן תרי רובי.","b":false},{"t":"והנה כתבתי ההיתר דתרי רובי לרווחא דמילתא, אבל לענ\"ד אין זה רק מכוח רוב, אלא כאמור מי שהיה בתוך המסוק, הרי דינו כמו שראוהו ביורה רותחת של שמן וכיוצ\"ב. דבודאי ימות, בלא שום ספק כלל וא\"צ להיתר דתרי רובי.","b":false},{"t":"וגם שמיד בדקו ואין זה כמים שאל\"ס, שא\"א לבדוק, אלא אפשר ואפשר והם בדקו והשתמשו בכל הכלים האפשריים שראויים למקום הררי קשה כזה, והצליחו לאסוף חלקי שברים קטנטנים, ומה שלא נמצא הוא רק מסיבה אחת שהאש הנוראה אכלה מה שאכלה ומה שנפלט ונפל משיני האש ומלתעותיה האיומות, הצליחו ללקט אחד אל אחד, ועשו כל דבר שניתן להעשות במאמצים על אנושיים, וזה מה שהעלו, ומסרו לנו פרטים מפורטים מאד על כל אחד ואחד, ונוכחנו לדעת בבירור גמור שאכן השיגו השגים גדולים וחשובים מאד, בחיפושיהם ובבדיקותיהם. ולא נותר עוד ספק בליבנו שאכן כל אלה שהיו רשומים כנוסעים במסוק הזה לכל תפקידיהם ועמדותיהם, אכן היו שם ומשם לא יצא אחד מהם חי, שכן יש גופות וחלקים מהם מכל אחד, וכל זה נבדק במיומנות ומקצועיות גבוהים ביותר. וכנ\"ל.","b":false},{"t":"ויש עוד תוספת תשובה שבנידון זה נמצאו מן הגופות, באופן שיכלו לבדוק בבדיקות המקובלות כיום, ואשר משתמשים בהם בכל העולם והתקבלו כבדיקות מוכחות ביותר, שככל שחולף הזמן מתברר יותר ויותר שבטביעת האצבעות היא יחודית לכל אדם לבדו, ולא ימצא אחד מכל יושבי תבל אשר בכל המדינות הרחוקות והקרובות שטביעת אצבעו דומה לאדם אחר, אלא אצל כל אדם גדול וקטון, טביעת האצבע שלו היא יחודית ומיוחדת לו לבדו בלבד, ואין לו דמיון בזה, ובמשך הזמן הוכרו מומחים גדולים לזה, שהם בעלי שם ויודעים להראות לכל מי שירצה את ההבדלים, והגם שיש בזה כמה צורות כלליות, כמדומני שבעה צורות כלליות, והן כעין אבות בציור הטביעה שהטביע הבורא ב\"ה בכל אדם ואדם, מ\"מ התולדות הם למיליארדים רבים לאין מספר ואין קצבה, וכל אחד הוא יחודי בזה, ועדיין לא נמצא מי שטביעת אצבעו זהה לאדם אחר קרוב או רחוק, וגם בזמננו שהמחשבים השתלטו על כל התחומים, ועל פיהם ישק דבר גדול וקטן שם הוא, ובהנעת איזה סימנים עם לחיצה על כמה כפתורים, מוציא דברים מדברים שונים ומגוונים, ומחלקם לחלקים ובודקם בדייקנות ובצייתנות, באין פוצה פה ומצפצף, ותוצאותיו מקובלות בלא ערעור, ואם רוצים עוד בוחנים בדרכים שונות עד שיוצאים מכל ספק, עדיין טוענים כולי עלמא באין מחלוקת בדבר, שלא נמצא אחד דומה לחברו בכל העולם, מה רבו מעשי ה' יתברך, ולו נתכנו עלילות, ואותו דבר אין צורת האזן והפנים שתדמה בטביעתה לעוד אחד בעולם, וכן נמי בכף הרגל וגם ברשתית העין ועוד. וכאן מצאו ובדקו טביעות האצבעות של הנמצאים בין שברי המסוק עם הרישומים שברשות הצבא והיו מדוייקים, ובזמנו הציגו לפנינו במכון הצבאי לזיהוי חללים את דרכי הבדיקה של טביעת האצבעות, והחיפוש בנתונים שמאוחסנים במחשבים, ומפליא לעשות.","b":false},{"t":"וכן בדקו ע\"י רקמות שנלקחו מן הנמצאים ובדקו את הבדיקות של דנ\"א שהם מיומנים בהם בימינו מאד מאד, וגם בדיקה זו נתפרסמה מסוף העולם ועד סופו, ועל פיה מסיקים מסקנות בכל התחומים כמפורסם.","b":false},{"t":"גם יש רופאי שיניים מומחים שהתמחו בבדיקות אלו עפ\"י טיפולים שהיו לאיש או לאשה שנספו, ומשוים זה למה שמצאו ויש להם גם בזה הצלחות מרובות, ומדייקים מאד גם בזה.","b":false},{"t":"ומהממצאים שמצאו והעלו הרי המסקנות ברורות ומוחלטות שאכן כל האנשים הרשומים שהם נסעו במסוק זה, היו בתוכו ושם נמצאו בין שבריו, ולא היה אדם אחר נוסף, וגם לא נעדר אחד מהם, אלא הכל נכון ומדוייק בתכלית הדקדוק. וכאמור יש שיכלו לבצע כל שלשת הבדיקות הנ\"ל, וכן עשו והתוצאה מכל הבדיקות היתה שוה, שאכן זה הוא האיש פלוני אלמוני ולא אחר. ויש שלא השיגו לבצע בו כל שלשת הבדיקות, אך לכל הפחות נעשו לפחות שתים מתוך שלשת הבדיקות הנ\"ל, בכל אחד מהם.","b":false},{"t":"ואעפ\"י שראוי להאריך בטיבם של בדיקות אלו, ולקבוע מעמדם עפ\"י ההלכה, לדעת אם נחשב לסימן מובהק שעל פיו ניתן להתיר את האשה לעלמא, בנידון זה אין אנו צריכים לסמוך כל כך על הבדיקות הנ\"ל כדי להתיר את נשיהם של אלו שהיו במסוק, דבעצם הבירור שהתברר בדיוק מי הם נוסעי המסוק, די לנו כדי לקבוע את מותם ולהתיר את נשיהם. מן הטעמים דלעיל.","b":false},{"t":"ועל כן לא אאריך הפעם בטיבם של בדיקות אלו ע\"פ ההלכה לכל אחד מהם, ודי לנו לציין את מה שכתב מרן נר\"ו ביביע אומר הנ\"ל (ח\"ו סי' ג' אות כ'), שדן בענין מרשם שינים שנמצא אצל רופא שינים שטיפל בו, והזכיר תשובת מהרא\"י שהביא מהר\"י ברונא בתשובותיו (סימן ג\"ן) שאם יש נקב בשן חשיב סימן מובהק, ועדיף מהעיד על גבשושית שעל גבי החוטם, שכתב באור זרוע דהוי סימן מובהק וסמכינן עליה ע\"ש: וכיו\"ב כתב בשו\"ת מהרי\"ו (סימן ק\"נ) והובא בכנה\"ג (סי' י\"ז הגה\"ט אות שכ\"ב) ושאר אחרונים.","b":false},{"t":"וכתב על זה מרן נר\"ו, וכ\"ש כאן שיש סתימות ועקירות בכמה מקומות, ובצמצום המקומות, דהו\"ל כנקב בצד אות פלונית (גיטין כ\"ז ע\"ב, וטוש\"ע סי' קל\"ב ס\"ד) וכבר האריכו האחרונים בכיוצ\"ב. עיין בשו\"ת זבחי צדק ח\"ב (עמוד רע\"א – רע\"ב). ובערוה\"ש (סי' י\"ז ס\"ק קע\"ג) כתב יש מי שפסק שנקב מפולש בשן הוי סימן מובהק, ולא נהירא לפסוק כן בזמנינו שנתרבה כאב השינים ויש בהם הרבה נקבים, וביבי\"א כתב, מיהו בצמצום המקומות בדיוק למעלה ולמטה ימין ושמאל, נראה דדמי לנקב בצד אות פלונית, שהרי גם בקלף הגט מצוי שנעשה בו נקבים בעת העיבוד, וכמ\"ש מהר\"י ברונא שם, שנקב השן לא דמי לנקב בגט דשם בעי' שיאמר בצד אות פלונית, הא נקב בעלמא לא מהני דשאני קלפים שרגיל להיות בהם נקבים (ועל כן הצריכו שיאמר שהנקב הוא בצד אות פלונית) משא\"כ בשן דלא שכיח ע\"ש. וממילא י\"ל שגם בזה\"ז דשכיחי נקבים בשיניים אם אמר המקום בצמצום י\"ל דחשיב סימן מובהק. ומהר\"י ברונא גופיה חזר וכתב דבשן לא מהני אא\"כ אמר נקב יש בשן זה שבצד שן פלוני. ע\"ש. ועכ\"פ במרשם השינים שיש הרבה סתימות ועקירות ובצמצום המקומות, נראה דחשיב סימן מובהק. ועיין בשו\"ת עין יצחק (סי' מ\"ב אות י\"ז), ושו\"ת מהר\"ם שיק (סי' מ\"א), וכתב סופר (סי' ל\"א) ועוד ועכ\"פ בודאי דחזי לאצטרופי טובא עם עוד סימנים, עכ\"ל של יבי\"א. ובימינו יש גם שיש להם צילום פנורמי של כל השיניים יחד, והוא יחודי בצורתו לכל אדם ואדם והוא סימן מובהק, ובפרט בהצטרף עם מרשם השינים כהנזכר ביבי\"א דפשיטא דהוי סימן מובהק. ובפרט בנדון זה שיש בכל אחד מהנספים לפחות שני סימנים מגו תלת הנ\"ל. דפשיטא דחשיבי סימן מובהק.","b":false},{"t":"וביבי\"א שם כתב עוד וז\"ל, וכן צירפנו זיהוי ע\"פ טביעת אצבעות, ובירחון הפרדס (תמוז תשי\"ג) כתב הרה\"ג דב בורשטיין ז\"ל אב\"ד ת\"א – יפו, שהואיל ומנוי וגמור בסוד חכמי המשפט והרפואה שהרשטוטים באצבעות האדם אין להם דמיון כלל מאחד לחברו ואפילו אחד מני אלף או רבוא, לכן יש להקל בעגונא ע\"פ זיהוי של טביעת אצבעות של החלל, והסכים עמו רב אחד בירחון הפרדס תשי\"ד. והובא באוה\"פ ח\"ה (דף קנ\"ב ע\"ד) וסמכנו ע\"ז בצירוף הוכחות ואמדנות אחרות. עכ\"ל.","b":false},{"t":"וכאמור בימינו הדברים התפתחו והתקדמו מאד, וגם שיש עוד בדיקה אחרת בכל אחת מן הגופות, וע\"כ יש לסמוך ע\"ז לזיהוי החלל כדי להעיד עליו להתיר את אשתו.","b":false},{"t":"והעולה על כולנה הוא מעצם הבירור שעשו החוקרים מפי האחראים והממונים, מפיהם ומפי כתבי רשומיהם שחייבים להעלות על הכתב כל תוכנית של כל טיסה וטיסה, עם כל הפרטים ופרטי פרטים, עד שהתברר מעל כל ספק שאכן אלו הם האנשים שהיו במסוק הנז' בעת הפיצוץ. וכבר כתב האגרו\"מ ומרן נר\"ו ביבי\"א הנ\"ל, דיש בזה תרי רובי שהנוסעים מתו, אך נדון זה עדיף טפי מהנדונים שבהם דברו הגאונים הנ\"ל, ששם בנידונם המטוס נפל בים שהם מים שאין להם סוף, דבזה יש חשש שאולי נמלט וניצל, אלא שגם במים שאין להם סוף רוב הנטבעים למיתה, והתירו ע\"פ זה. ונדון זה מלבד שהפיצוץ והניפוץ הזה הוא אינו משאיר סיכוי כל שהוא לשום אחד מהם, כאשר התנגש בעוצמה בצוק סלע קשה כזה. ואפילו על גבי קרקע כשמכונית מתנגשת חזיתית באחרת, או בקיר רח\"ל הסיכויים לחיים הם קלושים, וק\"ו למקרה זה, ועוד דאם נפלט אחד מהם הרי לא לים הוא נפל, אלא לגלגולי סלעים ענקיים וחבטות בין מורדות ההרים בגבהים עצומים כאלה שאינו מגיע לקרקע עד שנעשה אברים אברים רח\"ל. ולא רק תרי רובי יש בזה אלא נחשב שנתברר היטב שהיה במקום שלא יוכל לחיות כלל, כי אם עפ\"י נס גלוי וגדול, ולנסים לא חיישינן. וזה גרע טפי מכבשן של אש ויורה רותחת.","b":false},{"t":"ובשו\"ת שמע שלמה ח\"ה (חאה\"ע סימן ט\"ז) בהיתר של עגונא שבעלה היה במקום עבודתו במגדל התאומים במנהטן שבארה\"ב, ושם (באות ד') דנתי במי שנפל לגוב אריות, או ליורה רותחת וכו'. ובאות ה' שם, הבאתי דברי הפוסקים באחד שהיה בספינה שעלתה באש והוא היה אסור בשלשלאות של ברזל ע\"ש. וכן מ\"ש במנחת יצחק ח\"א (סי' צ\"ט) במי שרגליו קרושות והיה בבית חולים, ונפלה שם שרפה רח\"ל, ע\"ש. וכן עוד דוגמאות מדברי הפוסקים, שהעלו שכל שאינו יכול להנצל, מעידים עליו. ע\"ש.","b":false},{"t":"ואשר מכוח זה העליתי שאחר שהתברר שבעלה היה שם באותה שעה, וכפי שהאשה מעידה שהתקשר אליה ואמר לה שהוא במקום העבודה ושמע פיצוץ עז והוא רץ להציל עצמו, וידוע שמקום עבודתו הוא בקומה מאה וארבעה, והפיצוץ הנורא היה בקומה תשעים ושבעה, וזה מצב שאין שום אפשרות לינצל ממנו רח\"ל, שהוא רץ לרדת במדרגות והאש כבר בוערת מתחתיו והוא רץ לקראתה וע\"ש.","b":false},{"t":"והנה גם בנדון זה האפשרות להנצל מהמסוק בהתפוצצות והתנפצות כזאת עם האש הנוראה, ומן הנפילה וההתרסקות בגבהים שכאלה, היא לא תיתכן אלא בנס גדול, ולנסים לא חיישינן.","b":false},{"t":"וביחד עם כל הבדיקות והממצאים, המסקנא ברורה שעלינו לקבוע שאכן כל אלו ששהו במטוס ההוא, כולם נספו בלא שום ספק, ויש לקבוע את מותם, ויהי רצון מלפני אבינו שבשמים שתהיה נשמתם צרורה בצרור החיים וינוחו בשלום על משכבותם, ה' הוא נחלתם, בגן עדן תהי מנוחתם עם כל מתי ישראל בכלל הרחמים והסליחות, אמן.","b":false},{"t":"ולנשואים שביניהם, נשיהם מותרות לעלמא ויש לקבוע מעמדן שהן אלמנות.","b":false},{"t":"זה הנלע\"ד אם יסכימו לזה חברי שליט\"א.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"הראשון לציון הרב הראשי לישראל","b":false},{"t":"י\"ט סיון תשע\"א","b":false},{"t":"אני מצטרף לדברי כבוד הראש\"ל שליט\"א","b":false},{"t":"שלמה דיכובסקי","b":true},{"t":"לכבוד","b":false},{"t":"הראשון לציון","b":false},{"t":"הרב הגאון שלמה משה עמאר שליט\"א","b":false},{"t":"קראתי את פסיקתו של הרב בעיון.","b":false},{"t":"הפסיקה חשובה ונפלאה ביותר, ותואמת את ערך כבוד הנפטר בצה\"ל, ואת הרגישות הרבה שבה נוהג צבאנו היקר במשפחות השכולות בזמנים הקשים, מיד לאחר נפילת בנם או בתם.","b":false},{"t":"בדבריו המופלאים מסדיר הראש\"ל בצורה רהוטה ורגישה במיוחד את האופן שבו יש לנהוג באירועים נוראים ומצערים מעין אלה, ל\"ע.","b":false},{"t":"מברך אני את הראש\"ל על פסיקתו זו, המקיפה ומעמידה ברגישות רבה את המסקנות ההלכתיות. ובודאי יקרה לרבנות עד מאוד ההליכה המשותפת בעת המורכבת הזו.","b":false},{"t":"בברכה,","b":false},{"t":"הרב רפי פרץ, תא\"ל","b":false},{"t":"הרב הראשי לצה\"ל","b":false}]},{"t":"בענין בעל חנות שמכר חמצו ובא אדם וקנה בחנות חמץ שלא מידיעת בעל החנות אם בטלה המכירה","p":[{"t":"בעהית\"ש. בשני בשבת חמשה ימים באייר התשס\"ז.","b":false},{"t":"לכבוד ידידי וחביבי","b":false},{"t":"הרב הגאון רבי יעקב אריאל שליט\"א","b":false},{"t":"הרב הראשי לרמת גן ת\"ו","b":false},{"t":"שלום שלום בכפלים וברכות משמים, ילוו לכת\"ר ולסובבים הודו לעד אמן.","b":false},{"t":"אחדשה\"ט כנאה וכיאה!","b":false},{"t":"במה שדן מעכת\"ר שליט\"א בבעלי סופרמקטים שמוכרים את חמצם כנהוג, ועוטפים את המדפים של החמץ בכיסוי בכדי שלא יקחו מהם, ובתוך הפסח לדאבונינו ישנם לקוחות שלוקחים מצרכים של חמץ, והקופאית שאינה שמה לב, או שלא איכפת לה, מצרפת את המצרכים הללו לחשבון עם שאר המצרכים. וכת\"ר כותב שבעה\"ב לא רק שלא איכפת לו, אלא גם ניחא לו למכור סחורתו כולל גם החמץ. ומסתפק אם עי\"ז בטלה המכירה של החמץ שמכר בעה\"ב לגוי ע\"י הרבנות המקומית.","b":false},{"t":"א.","b":false},{"t":"אי חיישינן שמא לא מכר בעל החנות את חמצו בלב שלם","b":true},{"t":"ולמד מדברי הגאון בעל אגרות משה ז\"ל בתשובותיו (או\"ח ח\"ד סימן צ\"ה) שמסתמא לא חיישינן שהחנווני שמכר חמצו כנהוג, מכרו שלא בלב גמור. דכל זמן שאין אנן סהדי שלא מכר בלב שלם, אין לחוש, דדברים שבלב אינן דברים. ואדרבא יש חזקה דלא שבק היתרא ואכיל איסורא, כדאמר רבא בחולין (ד' ע\"א), ואפילו במקום שאין חזקה, מ\"מ אין אנן סהדי, וע\"כ אפילו אם באמת לא היתה המכירה בלב שלם, מ\"מ המכירה קיימת. דאין בכח הדברים שבלב לבטל המכירה, דדברים שבלב אינם דברים.","b":false},{"t":"וכת\"ר ציין שמקור הדברים שאין לבטל המעשה אלא כשיש אנן סהדי שכן הוא בלבו. הוא בתוספות קידושין (מ\"ט ע\"ב) ובריטב\"א שם (נ' ע\"א), ועיין באגרו\"מ חיו\"ד ח\"ג (סי' ק\"ו) לענין גרות מסופקת, וכתב דיש לחלק בין גרות ובין חמץ. ועפי\"ז עלה ונסתפק אם החמץ של אותה חנות הוא חמץ שעבר עליו הפסח. עכ\"ד.","b":false},{"t":"ותחילה אומר שההצעה שכתב כת\"ר, לדרוש מכל רשתות המרכולים להוציא מהברקוד, את כל מוצרי החמץ לזמן הפסח, כדי שלא יוכלו להמכר, כי על ידי זה לא תוכל הקופאית לקבוע את מחירם ולהעלותו בחשבון, הינה הצעה טובה מאד, וגם אם אין בזה נפק\"מ לעצם המכירה, הרי זה יועיל למנוע מסחר בחמץ תוך הפסח. ובלי נדר אדבר עם מחלקת הכשרות שע\"י הרה\"ר לישראל לטפל בזה, כדי להביא להחלטה כללית של בעלי הרשתות בענין. וה' יעזרנו על דבר כבוד שמו. אמן.","b":false},{"t":"והנה בשנה שעברה כתבתי שני מאמרים ארוכים, בענין מכירת חמץ של אחרים בלא ידיעתם, מדין זכין לאדם שלא בפניו, ובמאמר השני (הנדפס בשו\"ת שמע שלמה ח\"ו חאו\"ח סי' ז), דנתי בדברי המקנה (בקידושין ג' ע\"א) דזכין \"לאדם\" שלא בפניו. אבל אין זכין \"מאדם\" שלא בפניו. ויש שרצו ללמוד כן, גם בדברי נתיבות המשפט (סימן קצ\"ה סק\"א ד\"ה ועוד), וע\"ש שדחיתי דבריהם וביארתי שלא לזה כיוון בעל הנתיבות, והארכתי בדברי גדולי האחרונים בזה, ובאמת מצד הסברא אין מקום לחלק, דזכיה היא מדין \"שליחות\", וכשאדם ממנה שליח מהני, בין למכור ובין לקנות, ואין שום חילוק ביניהם, דמיד שעשאו שליח הוא עומד במקומו לבצע השליחות, וידו כידו וכו', בלי קנין ובלי עדים, רק מיד שקנה או מכר עפ\"י שליחותו, באותו הרגע נקנה המגרש למשלח, או יצא מרשותו ונכנס לרשות הקונה אותו. וחז\"ל חידשו הדין דזכין לאדם שלא בפניו, שאפשר להיות שלוחו של אותו אדם בלי ידיעתו, ובלי שהוא מינה אותו לכך, אם הוא רוצה לעשות הדבר לטובתו, ובתנאי שאכן דבר זה הוא זכות עבורו. וכל שהוא זכות עבורו באופן ברור, מיד נעשה שלוחו שלא בפניו, וכל מה שיעשה מתייחס לזה שמכוין אליו, כל שהוא זכות עבורו. וכל מה שהרב נתיבות המשפט דן שם הוא רק בעצם הזכות אם אכן זכות היא לו, או לא, ושעל זה צריך אומדן שהוא זכות עבורו. ע\"ש.","b":false},{"t":"ועל פי זה העליתי דהגם דבמכירת חמץ שלא מידיעת הבעלים, הו\"ל \"זכין מאדם\", שמוכרים את חמצו של אותו אדם לגוי, מ\"מ כיון שברור הדבר שהוא זכות, ואין לו שום הפסד כלל ועיקר, שכל מה שיקח הגוי יבא לחשבון ע\"י בקיאים בשומא, ושלם ישלם הגוי במושלם. אנן סהדי דניחא ליה, להנצל מעברה חמורה, כשאין לו שום הפסד כלל ועיקר. וזה שמוכר לו נעשה שלוחו, ושליח יכול למכור בשופי. והיא מכירה גמורה.","b":false},{"t":"ב.","b":false},{"t":"מי שמכר את חמצו ולקח מן החמץ לאכילה או למכור אם זה מבטל את כל \"מכירת החמץ\".","b":true},{"t":"עוד כתבתי שם דאפילו אם יקח היהודי הזה מן החמץ המכור בתוך הפסח, אין המכירה מתבטלת בזה, ולכל היותר הוי גזלן שגזל מן הגוי הקונה, וחייב בהשבה, אך אין בכוח המעשה הזה לבטל את המכירה. ועוד, דלגוי הקונה אין מזה שום הפסד, כי הרי בזמן התשלום יבואו שמאים מוסמכים וישומו את כל הסחורה, ובודאי שמה שלקח אותו יהודי, או מכר מן החמץ, לא יובא בחשבון, והגוי הקונה לא יִדָּרֵשׁ לשלם עבורו, ואיך תתבטל המכירה.","b":false},{"t":"ועוד שאנו נוהגים בזה עפ\"י עצת מרן בעל יבי\"א שליט\"א שאנו מוכרים יחד עמו בב\"ד של שלשה את החמץ לגוי מזה כמה שנים, ומתנים עם הגוי הקונה בפירוש, שהוא מרשה ליהודי המוכר ליכנס וליטול מה שירצה, ואם כי עיקר הכונה היא בשביל תרופות אם יצטרכו להם בפסח, ושאר ענינים של פקו\"נ ח\"ו, מ\"מ אנו מתנים על זה בסתם, ומסבירים לגוי שאין לו הפסד מזה, כי כל מה שיטול הישראל משך ימי החג לא יובא בחשבון ולא יִדָּרֵשׁ לשלם עבורו. אך למעשה הוא שלו ממש שמוכרים לו הכל, אלא שהגוי מסכים שיקחו משלו בעת הצורך. וא\"כ אם איזה יהודי יקח מן המָכור, אין בזה לבטל המכירה, והיא עומדת בעינה.","b":false},{"t":"ועפי\"ז מצאתי תרופה להציל את אחב\"י מאיסור חמץ שעבר עליו הפסח באחד המקומות הידועים שמוכרים בו דברים שונים, וביניהם גם משקאות של חמץ כגון וויסקי ווודקה ועוד משקאות, ואינם מוכרים חמצם לגוי, כי לצערנו הם ממשיכים במכירה והחנות פתוחה גם בימי הפסח, וידוע שכל העולם ממשיכים לקנות מהם אחר פסח ויש תקלה גדולה, שכל החמץ שלהם יש לו דין חמץ של יהודי שעבר עליו הפסח ואסור אפילו בהנאה, ואין פוצה פה ומצפצף. ודיברו איתם והם מוכנים למכור החמץ לגוי, בלי לתת להם תעודה כל שהיא. ואמרתי תפסת מועט תפסת נציל מה שניתן, וה' יעזור וישלים עלינו לטובה דמצוה גוררת מצוה, ואולי יעזור ה' ויפסיקו למכור בפסח. ולכל הפחות יועיל ששאר הסחורה לא תיאסר אחר הפסח, ועוד תקנה יש בזה, שגם מה שמוכרים לא משלהם הוא, אלא משל הגוי, וגם להם יש פחות איסורים, ובפרט דבודאי שרוב הקונים בפסח דברי חמץ הם גוים שאינם בני ברית, ונמצא שהמכירה מתבצעת מגוי לגוי אחר. ויכול הקונה לברר מה מכרו בפסח ולקבל התמורה, שהכל ערוך וכתוב עלי ספר החשבונות, אין פרץ ואין יוצאת. ואמרתי רעיון זה לפני מרן שליט\"א והסכים על ידי.","b":false},{"t":"וע\"ש שדנתי באורך גדול בדברי גדול, הוא הגאון הנודע בדורו רבנו יצחק אלחנן ספקטור ע\"ה בשו\"ת באר יצחק (סימן א' וב') בענין הזכיה והשליחות בזה. ע\"ש.","b":false},{"t":"ומה שחושש כת\"ר שזה מוכיח שלא גמר בדעתו למכור לגוי, אינו נראה לעניות דעתי, דחזקה היא על כל יהודי, שלא יבחר באיסור כשאין לו שום הפסד אם יאכל היתר. וכאן הרי אינו מפסיד כלום, שהרי גם אם תושלם המכירה אחר הפסח ותצא אל הפועל, מ\"מ הוא יקבל שכרו ותמורתו, ואם אחר הפסח לא תצא לפועל, הרי לא הפסיד דבר, ולמה נעלה על דעתנו שאין הישראל חפץ במכירה.","b":false},{"t":"ועוד שהרי בעל המרכול מוכר גם לשומרי מצות, ולמה נחשוד בו שירצה להכשילם, ובפרט ובמיוחד שאם יכשיל אותם, סוף דבר הכל נשמע, וכשידעו ימנעו ולא יקנו ממנו, ולא מיבעיא שלא יקנו אותו חמץ, אלא ימנעו רגלם מחנותו לגמרי, כי לא יאמינו בו עוד.","b":false},{"t":"נמצא שלא רק שלא מבטל המכירה, אלא שהוא מעונין במכירה וחפץ בה מאד, ומה שמכר בפסח הוא מתוך שרוצה להרויח גם את זה, אבל מה שלא מכר נשאר של הגוי. מה גם דאינו יכול לבטל מה שכבר מכר ואפילו אם ירצה. שכמו שצריך דעת מוכר ודעת קונה בשביל לבצע המכירה, כן צריכים דעת שניהם והסכמתם המלאה, כדי לבטל המכירה שכבר עשו מדעת שניהם.","b":false},{"t":"ואחר העיון ראיתי שכונתי בזה להגאון הגדול רבי משה פיינשטיין ע\"ה בספרו אגרות משה חאו\"ח (ח\"א סימן קמ\"ט) שדן בחנונים שמוכרים חמצם ע\"י הרב כנהוג, והחנוני חשוד לסחור בחמץ ולמכור חמץ בפסח, מהחמץ שמכר לגוי, וכתב וז\"ל, פשוט שאין זה ביטול המכירה, כי מצד תנאי המכירה לעכו\"ם, נכתב בשטר המכירה שמה שיטול יהיה כקונה אז מהעכו\"ם ויצטרך לנכות מהסך שחייב לו העכו\"ם, וממילא אין כאן שום ביטול על המכירה, ומה שלא לקח הוא של העכו\"ם. ובלא זה אין שייך לבטל קנין שכבר נעשה, ואינו שוב בעלים על זה, אלא הוא כקונה מחדש, או כגוזל, שהוא ודאי עובר על בל יראה כיון שקנה, בין למקח בין לגזל, אבל רק על מה שלקח בידו יקנה ולא על מה שנשאר. עכ\"ל.","b":false},{"t":"והנה ברור בדב\"ק שאין בנטילת חפצים מהחמץ משום ביטול חמץ, ואפילו שלוקח הרבה ולצורך מכירתו וכו', ואפילו שהוא עושה בכונה ובמזיד, עם כל זה לא מתבטלת המכירה. וק\"ו בנדו\"ד שבעה\"ב לא מכר ולא נטל מן החמץ, אלא הלקוח עשה כן בדרך לא נכונה ולא ישרה, והקופאית רשמה בחשבון בלא משים, או בלא איכפתיות, אך בעה\"ב לא ידע כלל, וגם אם ידע והעלים עיניו, אינו כלום והמכירה קיימת ובמקומה עומדת, והוא פשוט.","b":false},{"t":"אלא שעיקר הספק של כת\"ר, הוא לא על עצם הנטילה מן הסחורה של הגוי, אלא שחושש שזה שבעה\"ב לא איכפת לו שיקחו, מהוה אומדנא דמוכח שאינו חפץ במכירה לגוי, ותתבטל המכירה בגלל שאין גמירות דעת של המוכר, הנה כבר כתבתי לדחות חששא זו ג\"כ וכנ\"ל.","b":false},{"t":"והלום ראיתי בדברי האגרו\"מ שם, שעמד גם על זה, וכתב בזה\"ל, ואין לומר שאיגלאי מילתא למפרע, שלא מכר בלב שלם אלא שהערים, דמהיכי תיתי נימא כן, דהגם שחשוד לעבור להנאתו כשאינו יכול בהיתר, לא יעבור על מה שיכול לעשות בהיתר, ואפילו אם נאמר שבזה\"ז אין החזקה דלא מנח היתרא וכו' דחולין (דף ד'), הוא רק שלא יחליף שלא יבקש תחבולות להיתר, אבל על מה שעשה בהיתר ממש, ודאי לא נימא שבלבו לא רצה בהיתר, ולכן ברור ופשוט שהמכירה קיימת. וטוב עשה כתר\"ה שהשתדל שימכרו חמצם. עכל\"ה.","b":false},{"t":"נמצא דפשיטא ליה, שאין בעצם הדבר שסוחר בחמץ המכור, תוך ימי הפסח, כדי ללמד שאין לו גמירות דעת, והמכירה מכירה בלא ספק כלל ועיקר.","b":false},{"t":"ג.","b":false},{"t":"משא ומתן בדברי ה\"שדי חמד\" בדין חנוני שמוכר בפסח מן החמץ שמכר לגוי.","b":true},{"t":"ונזכרתי עתה כי בשנה שעברה מסרתי שיעור ביום ה' אייר ברמלה (במסגרת יום שכולו תורה שנקבע ביום העצמאות שהפך ליום של לימוד תורה דרבים, הגדול בכל ימות השנה). ודיברתי בענינים אלו, ולמחרת כתב לי הרה\"ג ר' אברהם כהן שליט\"א רב שכונה שם, ומחבר ספרי ילקוט אברך, והעירני מדברי השדי חמד במערכת חמץ ומצה (סימן ט' סוף אות ל\"ה, כרך ח' עמוד ר\"ז) וז\"ל השד\"ח, וזאת להודיע כי לפני איזה שנים היה מעשה בעיר הזאת, שאחד מכר חמץ לנכרי בחול המועד, ואותו חמץ הוא מכללות החמץ שמכר לעכו\"ם קודם הפסח, ואסרתי כל חמצו לאחר הפסח לכל ישראל, וכן הוכרז בבתי כנסיות, שכל חמצו של פלוני אסור לכל ישראל, שכיון ששלח ידו במה שמכר לעכו\"ם, נתבטלה המכירה שלפני פסח, והוי חמץ של ישראל שעבר עליו הפסח, והיה מן הראוי לאוסרו בהנאה, ולהצריכו להשליכו לאיבוד, אלא שהיה סך רב כמה מאות רובל כסף, וידעתי כי לא ישמע לקול מלחשים, ומוטב לבחור הרע במיעוטו, תפסת מועט תפסת, והיה ג\"כ קצת סניף מה שטען שמשרתו הוא שעשה כן שלא בידיעתו, אלא שלא האמנתי לו, וגם השכנים לעזו עליו כי גם ידו במעל. וקנסתי אותו ונתן פדיון נפשו לצדקה לעניים כאשר הושת עליו, והוא רחום. וכו'. עכ\"ל.","b":false},{"t":"והנה דברים אלו היו בהעלם מעיני קדשו דהגאון אגרו\"מ ע\"ה, והיה מקום לומר דאפשר שאם ראה לדבר הגאון שד\"ח ז\"ל היה חוזר בו, שהוא ז\"ל פסק רק מכח סברא. ובפרט דהשד\"ח שם כתב שכן פסק מהר\"ם שיק ז\"ל שהעושה סחורה בחמץ שמכר לגוי, מכירתו בטלה, והוי חמץ של ישראל שעבר עליו הפסח, ואסור עכ\"פ לכל ישראל, עו\"כ שם שכן מתבאר מתשובת גאון גדול שבשו\"ת אורי וישעי, שע\"י שיסחרו בחמץ שמכר לנכרי תתבטל המכירה, וכן כתבתי אני הדל בסימן זה אות א' (בד\"ה הנה מעיד) ועי\"ל באות ט\"ל (ד\"ה ועוד יש לפקפק) עכ\"ל השד\"ח.","b":false},{"t":"וראיתי בשד\"ח שם (עמוד ר\"ו ד\"ה שוב) שכתב ולפי שאין ספר של מהר\"ם שיק מצוי אעתיק את לשונו והוא (בסימן ר\"ה) וז\"ל, נשאלתי בדין ערב פסח שחל בשבת, שטוב לבער החמץ בערב שבת קודם חצות, אם מותר להם למכור הקמח וכדומה בחנותם עד סמוך לשבת קדש וכו', אלא דיש לדון דהרי מכירת חמץ לנכרי שנוהגין עכשיו למכור, ודאי שהוא בכלל ביעור, וא\"כ מחוייבים לכתחילה למכור החמץ קודם שיגיע זמן איסורו כי היכי דלא ליטעי, וכיון שכבר מכר איך רשאי ליהנות ממנו, והרי בזה הוא מבטל המכירה, ואם נימא דהעכו\"ם הוא עצמו ימכור בערב שבת, יש לחוש לתקלה, שמתוך כך יקילו גם בפסח עצמו שימכור עכו\"ם, ובזה יש הרבה חששות שרוצה בקיומו, ונהנה מחמץ. ואין אני מניח בקהלתי למכור על ידי עכו\"ם אלא א\"כ שנוטל העכו\"ם לביתו, ובחנות אחרת שאינו נקרא על שם ישראל, וכו'. עכ\"ל. (וע\"ש שהעתיק כל תשובתו). והנה ממ\"ש דאם כבר מכר לגוי, אינו רשאי ליהנות ממנו, והרי בזה הוא מבטל המכירה. מזה למד השד\"ח שאם מכר היהודי מהחמץ בפסח מתבטלת המכירה.","b":false},{"t":"ואי לאו דמסתפינא הייתי אומר שכונת הגאון מהר\"ם שיק ע\"ה, היא רק בנידון דידיה, שמוכרים החמץ ביום ששי בשעה שרגילים למכור כל שנה ושנה, אע\"ג שעדיין אוכלים חמץ, עד למחר ביום שבת בשעת איסור חמץ. והוא כדי שלא יבואו לטעות בשנה אחרת, ומזה יצא לדון איך ימשיך החנוני למכור חמץ לכבוד שבת, והרי כבר מכר אותו לגוי, ואפשר דרק בכה\"ג שעדיין החמץ מותר גמור, וכו\"ע אוכלים חמץ עדיין, וא\"כ ברור שגם דעתו להמשיך למכור כרגיל שהרי הזמן הוא של היתר חמץ, ובזה הוא דקאמר, שבכך מבטל את המכירה. אבל אדם שמכר חמצו, וידוע שבפסח אסור לו ליהנות ממנו, והוא חוטא ומוכר, אפשר שיודה מהר\"ם שיק ז\"ל שהמכירה קיימת, ולכל היותר יש לו דין גזלן, דאיך מתבטלת המכירה, והרי גם אם ירצה להדיא לבטלה אינו יכול לבטלה.","b":false},{"t":"והמעיין שם בראש התשובה (שבשד\"ח) יראה שדן הרבה בזה, והעלה דכשם שמותר לשייר חמץ לאכילתו של שבת, כן מותר לו לשייר חמץ למכור קודם כניסת שבת, וע\"ז יצא לדון, דמכירת חמץ היא כביעור חמץ, וחייבים למכור לגוי קודם זמן איסורו. ושאל איך יוכל למכור לאחרים, אחר שכבר מכר לגוי, והרי בזה מבטל המכירה לגוי, דזה אינו גנבה או גזלה, אלא מלכתחילה גלוי וידוע, שממשיכים לאכול חמץ עד למחר בשעת איסורו. וה\"נ ברור שימשיך למכור עד סמוך לכניסת שבת, וא\"כ יש בזה להראות שהמכירה מלכתחילה אינה מכירה כלל, כך נלע\"ד לישב דברי מהר\"ם שיק ע\"ה, ואם כן אין ראיה לנדו\"ד כלל.","b":false},{"t":"גם מה שדן השד\"ח בחמץ של ישראל מומר וכתב שם (סימן ט' אות א' ד\"ה הנה מעיד, בכרך ח' עמוד 367) וז\"ל הנה מעיד בשם רבותיו לקדושים אשר בארץ, שהיו מבקשים ומכריחים את הישראל מומר למכור חמצם, (ע\"י שאיימו שלא יקנו מהם). ואני הדל איני יודע באיזה אופן היו מוכרים הישראל מומר, דיש ב' דרכים למומרים הללו למכור חמצם לנכרי, האחד, שימכרו חמצם לנכרי וישבתו הם ממסחר זה, מערב פסח עד אחר הפסח, כדרך שבני ישראל עושים, ובזה אמרינן לפעלא טבא והוא תיקון גדול להרים מכשול, שלא יכשלו בנ\"י בחמץ שעבר עליו הפסח. והשני שמובן מהמכתב של הרב הנ\"ל, שיחתמו בשטר ההרשאה בלבד, אבל הם עצמם לא ישבתו ממסחרם וישאו ויתנו בחמץ גם אחר מכירתו לגוי ונוהגים בכל ימי הפסח בחמצם כמעשיהם בכל ימות השנה, ואם באופן זה היו מתנהגים, אני בער ולא אדע מה הועילו בתקנתם, שהרי כשחוזר ונושא ונותן בכל ימי הפסח בחמץ הרי הוא מבטל הרשאתו כאילו לא היתה, ומה שימכור הרב את חמצו בכלל שאר החמץ, לא יועיל לו כלל. ואתה תחזה דברי גאון גדול הובאו בשו\"ת אורי וישעי (סימן קכ\"א) שהתמרמר מאד על כיו\"ב והבאתי דב\"ק בסימן זה אות ו' (ד\"ה וגורמת המכירה) ועי\"ל סימן זה אות ל\"ה (ד\"ה וזאת). עכ\"ל.","b":false},{"t":"והנה גם בזה מיירי ב\"מומר\" שחותם על הרשאה ותו לא מידי, והוא מתכוין להמשיך למכור כמו בכל ימות השנה כלשונו, ואפשר דרק בזה הוא דמבטל המכירה, ולא על מי שמוכר באקראי.","b":false},{"t":"אלא דמדבריו ז\"ל (אות ל\"ה ד\"ה וזאת) עולה דגם על מכירה באקראי אסר כל חמצו לאחר הפסח משום שבטלה המכירה. וכנ\"ל. ואולם י\"ל דשם ג\"כ מיירי שהיה מוכר כדרכו ומשקר, שכן כתב השד\"ח שם שלא האמין לו, וגם השכנים לעזו עליו וכו'. ועוד דנראה דקנס קנסו ליה התם שלא ילמדו למכור חמץ בפסח ואפילו לגוי. וקצת ראיה יש לזה, ממה שלא אסר לו כל החמץ רק קנס אותו קנס כל שהוא כמ\"ש שם, ואם באמת המכירה בטלה לגמרי איך אפשר להתיר לו שאר החמץ, על כן נראה שמדין \"קנס ותקנה לרבים\" אייתי עלה, אך במקום שהוא ממשיך למכור כרגיל בזה הוא כן חושש לביטול המכירה.","b":false},{"t":"אלא שגם זה צריך להבין איך מתבטלת המכירה, והרי כבר הרשה את הרב להיות שלוחו למכור, והרב כבר מכר לגוי והוי מכר גמור, ומה שלוקח עתה מהחמץ ומוכר, בודאי הוא חוטא רח\"ל, ועובר על בל יראה ובל ימצא וגם על איסור גזל, אבל איך תתבטל המכירה.","b":false},{"t":"ובאמת מדברי הפוסקים שהביא השד\"ח (שם סימן ט' אות א') שדנו במכר חמץ לישראל מומר דיש מצדדים להתיר בדיעבד, ע\"ש. ואח\"כ כתב וז\"ל, ורב אחד כתב לי, וז\"ל פה נמצא ישראל מומר שעסקו ביי\"ש עסק גדול, שיש לו כמה סקלאדין בכמה עיירות חוץ מפה, ושלחתי השמש אליו שיבקשו בשמי, שאחר הפסח אהיה חייב להודיע לכל העיירות ולהכריז בבתי כנסיות, שהחמץ שלו אסור, ויותר טוב שיחתום על כתב הרשאה והכל על מקומו יבא בשלום. וכן עשו רבותינו ז\"ל שבקשו והכריחו תמיד הישראל מומר שיש להם עסק בחמץ, למכור חמצם למען לא יהיה קלקול משני הצדדים, וכן היה שחתם על שטר ההרשאה. ויש מגמגמים בדבר, כי י\"א שמעולם לא שמע כזאת, ומהם אומרים שלא היה לי לשלוח אליו רק אחרי הפסח להכריז, ורבים כאלה, לכן יודיע כ\"ת דעתו וכו'. עכ\"ל. וע\"ז דן השד\"ח אח\"כ וכנ\"ל.","b":false},{"t":"ועכ\"פ הרב הנ\"ל מעיד בשם רבותיו לקדושים אשר בארץ ע\"ה, שהתירו אפילו בכהאי גוונא שהוא מומר גמור ומוכר חמץ בפסח כמו בכל ימות השנה, ופסקו דחמצו אינו אסור אחר הפסח, דהמכירה שמכר לגוי קיימת, והוה ליה חמץ של גוי שעבר עליו הפסח ומותר אפילו באכילה.","b":false},{"t":"וגם השד\"ח שחלק עליהם י\"ל דרק בכה\"ג, שהוא מומר ומוכר כמו בכל השנה רק בזה החמיר. אבל בנדו\"ד שיש איזה אנשים ששולחים ידם ולוקחים מן הבא לידם, אפשר שיודה גם השד\"ח, דלא בטלה בהכי המכירה לגוי, וכמו שביארתי לעיל בס\"ד.","b":false},{"t":"ועוד יותר דכאמור נראה העיקר לדינא, דאי אפשר לבטל את המכירה, אחר שמכר כדין בהדרכת הרב והבית דין, ועושים כל הקנינים של תורה, וגם של החוק הכללי אחת מהן לא נעדרה, וגם כותבים בשטר המכר שאם אחר זמן יבא הגוי הקונה לשלם, יביאו מנהלי חשבונות ושמאים בקיאים שישומו ויחשבו את הכל, וישלם ככל אשר יושת עליו עפ\"י החמץ הנמצא, וכל מה שיקחו או יאבדו, או ימכרו לאחרים בודאי לא יבא לחשבון כלל, ולא ידרש לשלם על זה. וא\"כ מאיזה סיבה יש לדון שהמכירה תתבטל, ולכל היותר הוא יקרא גזלן, או מיפר חוזה, אבל זו הפרה ששייכת על מה שלקח, ולא הפרה שמבטלת את כל המכירה. ובפרט דברור כשמש שאין לקונה קפידא בזה, ואין לו מזה הפסד.","b":false},{"t":"וע\"כ נלע\"ד דגם מ\"ש השדי חמד בשם אותם גדולים הוא רק למגדר מילתא וכמ\"ש לעיל, והוכחתי כן ממה שהסתפקו בקנס שקנסו לאותו אדם שמכר מהחמץ המכור לגוי תוך הפסח. ואם באמת המכירה בטלה, מה יועיל הקנס, והלא המכירה בטילה, ונמצא שכל החמץ שייך לו, וחמץ של יהודי שעבר עליו הפסח אסור בהנאה, ומה יועיל ומה יציל אותו הקנס, אלא ודאי שגם הם לא אמרו את זה אלא למיגדר מילתא, ואולי להדר בענין היכא דאפשר.","b":false},{"t":"ובאמת בעלי החנויות בודאי ובודאי שמעונינים במכירה שתתקיים, כי הלא פרנסתם תלויה בזה, דבלא\"ה יש קהל גדול שלא יקנו מהם, ורובו הגדול של העם נזהר מאד בחמץ. [והיה מעשה בת\"א יפו, במיני מרקט שלא מכר חמצו, ואחר דו\"ד אסרנו לו הכל, ואע\"פ שהוא לא שומר תורה, מיד אחר הפסח, הוציא את כל החמץ שהיה לו ושרף אותו ברוב עם, למרות שהיה מדובר בעלות גדולה מאד. כי ידע שבלי זה לא יקנו ממנו עוד].","b":false},{"t":"ד.","b":false},{"t":"האם יש למכור גם חמץ של עוברי עבירה אע\"פ שידוע שיסחרו בו כדי למעט באיסור כל מה דאפשר","b":true},{"t":"וכאשר דימיתי כן מצאתי בחסדי ה' שכבר קדמני בזה בשו\"ת חלקת יעקב להגר\"י ברייש ז\"ל ח\"ג (סי' ל\"א) שכתב דכל מה שכתב השדי חמד בשם הפוסקים לאסור, הוא רק למיגדר מילתא במקום שאפשר, שהוא במקום ששומעים לרבנים, אבל במקום שאם ימנעו מלמכור חמצם של אנשים אלו, יגרום לאיסורים רבים יותר, ולמכשול דרבים שיקנו חמץ שעבר עליו הפסח, ובודאי דבכה\"ג אין לדחות אפילו עבריין כזה, ויש לסייעם למכור חמצם כדין.","b":false},{"t":"ולא כל מקום וכל זמן שוים בזה, והוב\"ד בקצרה בספר פסקי תשובות בהל' מכירת חמץ (סימן תמ\"ח סק\"כ, עמוד ע\"ו אות 83). ע\"ש. וכתב שם שיש מגדולי הפוסקים החולקים (על מ\"ש השד\"ח) וסוברים שהמכירה שרירה וקיימת, כיון שבזמנינו מחייבים את הנכרי לשלם עבור כל החמץ שמוכרים לו, והמכירה מתקיימת לפי כל כללי הקנינים, ואפילו אם אין גמירות דעת מצד המוכר, זה לא מבטל את המכירה, ומה שלוקח את החמץ בפסח ומשתמש בו, הרי הוא כגוזל את הנכרי או כקונה ממנו מחדש, ועל החמץ הזה בודאי עובר עליו ונאסר בהנאה, אך על שאר החמץ אין בו איסור אחרי הפסח, כיון שהמכירה לא מתבטלת.","b":false},{"t":"וכתב שכן פסק בשו\"ת דברי חיים ח\"ב (סימן מ\"ו), וכן ציין לאגרות משה שהזכרתי לעיל. ושכ\"כ גם בח\"ב (סימן צ\"א). ושוב כתב שבספר שערי ההלכה ומנהג מהאדמו\"ר מליובאויטש זצ\"ל ח\"ב (סימן קצ\"ה) מונה שש סיבות שבודאי יש למכור חמצם של אלו, ולפי שו\"ע הרב (סעיף י\"ג) משמע שגם אם משתמשים בחמץ, המכירה לא בטלה, והריהו נחשב לגוזל את הנכרי ותו לא מידי. ע\"ש.","b":false},{"t":"ולפי האמור אפי' גזל אין בו, אבל לכו\"ע בודאי עבר על אותו חמץ שמכר בחג, בבל יראה ובל ימצא, והחמץ ההוא אסור בהנאה אחר הפסח, אך מ\"מ אינו מבטל כל המכירה. ועיין עוד מ\"ש שם אות 86. ושמחתי שיש רבים וגדולים שכתבו כן. וכן עיקר.","b":false},{"t":"וכל זה הוא אפילו אם מכר במזיד, אבל בנידון זה ששאל מעלת כת\"ר שליט\"א, נלע\"ד דלכו\"ע המכירה קיימת, שהרי בעה\"ב מכר חמצו כדין, ולא נגע בו אלא הפרישו וכיסהו שלא יקנו ולא יקחו ממנו, ובא מאן דהו והוציאו שלא ברשות, והקופאית רשמה בלי לדעת, ועכ\"פ לא על דעתו של בעה\"ב, בודאי דבזה אין מי שיאמר שהמכירה בטלה.","b":false},{"t":"ואפילו הכי עצתו של כת\"ר טובה, לבטל הקוד של חפצי החמץ מן המחשב. ודיברתי בזה עם הרה\"ג יעקב סבאג שליט\"א ראש אגף הכשרות ברה\"ר לישראל, ואמר לי שאכן הנושא בטיפול, והדברים עלו על ידו לפני הנהלת הרשתות הגדולות, ולא התקבל, וכעת זה יעלה לדיון בועדת הכשרות בתקוה שתצא החלטה מחייבת בענין.","b":false},{"t":"ואותם שמוכרים במזיד, בודאי אין לתת להם תעודה שמכרו, אך יש לשקול היטב אם ניתן להציל רבים מעוון, שלא יכשלו בחמץ של יהודי שעבר עליו הפסח.","b":false},{"t":"וסוף דבר שכינסנו את כל ראשי ומנהלי הסופרמרקטים לסוגיהם, ביחד עם ועדת הכשרות ושני הרבנים הראשיים, ודברנו על לבם, על חשיבות המצוה וחומרת האיסור, ושהעולם סומכים עליהם, ולדעת כמה פוסקים המכירה מתבטלת, ואז יש מכשול גדול לרבים, וה' נתן לנו חן בעיניהם, וקבלו עליהם לתקן שבכל ערבי פסחים, יסירו כל הקודים של החמץ מן המחשבים, באופן שלא יוכלו לבצע מכירת דברים של חמץ לקונים בתוך שבעת ימי חג הפסח. והיינו מודים ומהללים לשמו יתברך שסייענו במצוה חשובה זאת.","b":false},{"t":"והנה בתוך כדי דיבור מרגע שהתקבלה החלטה זו, הביאו לי הפסק הזה לחתום עליו, כי מיד אחרי זה הייתי אמור לנסוע לרמת גן לשיעורי תורה, וחנוכת בית כנסת שבנה ראש העיר מר צבי בר הי\"ו, וצירפתי את ההחלטה לחתימה בשמחה ובהודיה לה' יתברך, ובאותו ערב מסרתי כל זה לידי כבוד הרב של רמת גן שליט\"א, וראיתי בזה יד ה' ישתבח שמו ויתעלה כסא הדרו.","b":false},{"t":"המצפה לישועת ה' ברחמים על עמנו ועל נחלת אבותינו.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"הצעת פתרון \"למעוכבות גירושין\" עפ\"י ההלכה","p":[{"t":"בעזהית\"ש. מוצש\"ק קרח \"בקר ויודע ה'\" כ\"ט סיון התשס\"ו","b":false},{"t":"הנה זעקת בנות ישראל באה אלינו, ובפרט מבנות חו\"ל, ששם אין כוח ב\"ד יפה מצד השלטונות, להטיל על הסרבנים עונשים והרחקות, כדי שיקיימו את מצות חכמים שפסקו שעליהם לגרש, וזאת לאחר שכבר התגרשו גירושין אזרחיים, והפרידו את כל המשותף ביניהם בהסכמה, ולפעמים זה נעשה ביוזמת הבעל, ולאחר מכן הוא מתעלם ממנה, ואינו מטה אזן לשמוע את דברי בית הדין, ומעגן את אשתו אלמנות חיות וקצרה ידי בית הדין מלהושיען, כי אין להם סמכות מהשלטונות לפעול בדבר כראוי לו.","b":false},{"t":"והנה רבים עסקו בזה וביניהם שכתבו דברים שהם רחוקים מלבא לידי מעשה, כגון המדברים על \"הפקעת קידושין\" וכיו\"ב, וראיתי כמה דברים שאין בהם מטעמה של הלכה, ולא נכתבו מתוך ידיעה מבוססת, כראוי לחמורות כאלה. ה' יצלינו מהם. כל לעומת זה, הראוני את תשובתו הרמת'ה של הגאון הגדול רבי בצלאל ז'ולטי ע\"ה רבה של ירושלים (שנדפסה בהפרדס), ובה כתב הצעה טובה ומבוססת, שיכינו \"הסכם נישואין\" אשר יכתב ויחתם וגם יאושר עובר לגירושין, ובו יתחייב הבעל בעת הנישואין, שאם יהיה ביניהם פירוד אזרחי, מתחייב הבעל לתת לה מזונות בסך אלפיים דולר בכל שבוע, עד שיתן לה גט כדמו\"י. וזאת מדין מעוכבת להנשא מחמתו. כמ\"ש בב\"מ (י\"ב ע\"ב), א\"ר זירא מגורשת ואינה מגורשת, בעלה חייב במזונותיה.","b":false},{"t":"ועוד הוסיף שיכתבו בהסכם, שהבעל זכאי לבא לפני בית דין רבני מוסמך, ויוכל לדרוש שיפטרוהו מהחיוב הזה, בין בכולו ובין ממקצתו, לפי ראות עיני הב\"ד. [וכנראה שכונת הרב ז\"ל שמתוך כך, ישאו ויתנו עמו בענין הגירושין כפי הראוי].","b":false},{"t":"א.","b":false},{"t":"בדין התחייבות מזונות שהאשה מרויחה לפרנסתה, ובגדר חיוב מזונות במגורשת ואינה מגורשת.","b":true},{"t":"וכתב שם, שהתחייבות זו היא כדין, ואפילו שהיא עובדת ומרויחה לפרנסתה, והוכיח מרש\"י בכתובות (צ\"ד ע\"ב), שכתב בד\"ה מגורשת ואינה מגורשת, ומן האירוסין, ולא לאשמעינן וכו', אלא אגב אורחיה אשמעינן דמגורשת ואינה מגורשת כגון זרק לה גיטה, ספק קרוב לה ספק קרוב לו ברה\"ר, אין לה מזונות מן היתומים אם מת. עכ\"ל. וע\"ז כתב, ואעפ\"י שארוסה אין לה מזונות, מ\"מ כשהיא מעוכבת מחמתו להנשא, הוא כן חייב לה מזונות. ועיין בשיטה מקובצת שם (קמ\"ב ע\"ב), ד\"ה וז\"ל הרא\"ש ז\"ל מגורשת ואינה מגורשת, ופירש\"י ז\"ל מן האירוסין וכו', ויש מקשים היכי מצי לפרש מן האירוסין, הא אפילו כשאינה גרושה, ארוסה אין לה מזונות, ונראה לי דלא קשה דכיון דהיא מגורשת ואינה מגורשת, אגידא ביה ולא מציא לאנסובי לעלמא, חייב במזונותיה, ואין חילוק בין מן האירוסין בין מן הנישואין, והוי כמו הגיע זמן ולא נישאו. ע\"כ.","b":false},{"t":"ופירש הרב ז\"ל את דבריו, שמגורשת ואינה מגורשת שבעלה חייב במזונותיה, אין זה משום ספק חיוב מזונות מתורת נשואה, אלא הוא חיוב חדש של מזונות, משום דאגידא ביה. וגם בארוסה שלא היה חייב לה מזונות מעולם, מ\"מ בספק מגורשת חייב במזונותיה (וכן דומה להגיע זמן, דשם ודאי לא מדין נשואה).","b":false},{"t":"ובתשובה שכתבתי בזה בס\"ד, והיא נדפס'ה בשו\"ת שמע שלמה ח\"ב (חאהע\"ז סימן י\"ט), הוכחתי כן בפשיטות מדברי רש\"י ז\"ל בכתובות שם, בד\"ה כדרבי זירא, וז\"ל דאמר בעלה חייב במזונותיה בחייו, משום דמעוכבת בשבילו להנשא, אבל לאחר מיתה לא, דדילמא גרושין הוו, ואין לה מזונות, דמספיקא לא מפקינן ממונא. עכ\"ל.","b":false},{"t":"ואם באמת חיוב מזונות דמגורשת ואינה מגורשת, הוא מדין מזונות נשואה דכל זמן שלא גירשה לגמרי, עדיין החיוב במקומו עומד, עד שיגרשה גירושין גמורים. א\"כ גם לאחר מותו יתחייבו היתומים במזונותיה, שהרי החיוב עמד בעינו כל זמן שהיה חי. ואעפ\"י שאפשר לדחות ולומר, דעכ\"פ כשמת כבר נגמר הקשר ביניהם, מ\"מ האמת יורה דרכו למעיין היטב, שאין זה חיוב מזונות רגיל. אלא קנסא הוא שקנסוהו שלא יעגננה אלמנות חיות, וזה שייך רק בחיים חיותו, אבל אחר שמת שכבר אין ענין של עגינות כלל, אין לה מזונות. וזה גם מדוקדק היטב בלשונו, של רש\"י ז\"ל שם שכתב: דחייב במזונותיה בחייו משום דמעוכבת בשבילו להנשא. וכ\"נ גם מהתוספות שם ד\"ה לאתויי, שהקשו על פירש\"י ז\"ל (בד\"ה מגורשת), שכתב דאתא לאשמועינן דמגורשת אין לה מזונות מן היתומים. וכתבו שזו היא מילתא דפשיטא, דמספק שמא מגורשת גמורה היתה, לא תוציא מזונות מן היתומים. ע\"ש. ואם חיוב המזונות בזה הוא משום דעדיין אגידא ביה וחייב מדין נשואה, מאי פשיטא להו דלאחר מיתה אין לה מהיתומים, ואדרבא י\"ל דכמו שבעלה חייב במזונותיה בחייו משום שהיתה עדיין אגידא ביה, ונשאר חיוב המזונות של נשואה על כנו, ה\"נ יתחייבו יורשיו אחריו מתנאי כתובה כמו כל אלמנה שניזונת מנכסי בעלה אחר מותו.","b":false},{"t":"אבל אם החיוב במגורשת ואינה מגורשת, אינו מדין מזונות נשואה אלא חיוב חדש הוא זה ומשום שמעכבה מלינשא לעלמא, ואולי קנס הוא שקנסוהו חז\"ל על שמעכבה, אתי שפיר קושית התוס', דפשיטא שאין היתומים חיייבים במזונות אלו, דהם לא שייכים לעיכוב הזה כלל ועיקר, ועוד שכבר קנתה עצמה במיתת הבעל, ואין עוד מי שיעכב עליה.","b":false},{"t":"וכתבתי שם שכן עולה להדיא מדברי הישועות יעקב, שהובא בפתחי תשובה (סימן צ\"ג סק\"ב), שעלה ונסתפק באשה שאמרה שלא בפני בעלה שהוא גירשה. ואח\"כ בא בעלה והכחישה, דלפי זה אסורה לינשא לעלמא, ואחר זמן באו עדים והעידו שאכן בעלה גירשה כאשר אמרה בתחילה, או שבעלה הודה על כך בעצמו. אי נימא דחייב במזונותיה כל אותה תקופה שהיה מכחישה, ועל ידו היתה מעוכבת מלהנשא, או מכיון דאגלאי מילתא למפרע דמגורשת היתה, אין מקום לדון על חיוב מזונות כלל. והסיק דהעיקר נראה לי, דהחיוב במזונות אלו הוא מדין מזונות נשואה, דכל זמן שלא התגרשה ממנו לגמרי, עדיין החיוב במקומו עומד, וממילא איך שייך לחייב את זה על אותם שנים או חדשים שהיתה כבר גרושה ממנו לגמרי.","b":false},{"t":"ובאמת שכן למדו מזה בפסקי דין רבניים של בתי הדין כרך ג' (עמוד 45), שחיוב מזונות דמעוכבת, הוא דין מיוחד שחייבוהו כדי שלא יעכבה מלהנשא, והיא תקנה מיוחדת שקנסוהו כדי שלא יעגנה.","b":false},{"t":"ומכל זה יש חיזוק גדול למסקנא, שחיוב המזונות בספק מגורשת, הוא דין מיוחד שחז\"ל הטילו עליו חיוב זה, שלא יעגן את אשתו.","b":false},{"t":"ב.","b":false},{"t":"בדעת הרמב\"ם בדין מי שמעכב את אשתו לקבל את גיטה שחייב במזונותיה, ויבואר אם מעשי ידיה שייכין לבעל.","b":true},{"t":"עוד כתב שם הגריב\"ז ז\"ל, שכן נראה מהרמב\"ם ז\"ל בהלכות גירושין (פ\"ו הלכה ל'), שכתב, הבעל ששלח גט לאשתו, הרי הוא חייב במזונותיה ובכל תנאי הכתובה עד שיגיע הגט לידה. והמגיד משנה שם כתב, דבפרק י\"ח מהלכות אישות (הכ\"ה), נתבאר דאפילו בספק מגורשת הבעל חייב במזונותיה בחייו. ומשמע שאין לה שאר תנאי הכתובה, כיון שהיא ספק מגורשת. וזהו שאמרו (בכתובות צ\"ז ע\"ב), שאינה ניזונת מן היורשים, ומזון האלמנה הוא מתנאי הכתובה. ואע\"פ שאינה ראיה ברורה דאיכא למימר שאני מזונות דלאחר מיתה דלא אגידא ביה, אבל שאר תנאים שהן על הבעל כיון שבידו לגרשה ואינו מגרשה גירושין גמורים, אפשר שחייב בהם בחייו, מ\"מ ממ\"ש רבינו כאן נראה שאינו חייב, שאל\"כ היה לו להשמיענו אפילו בספק מגורשת (שחייב בכל תנאי הכתובה וכ\"ש בזאת), וכן עיקר שאין לחייב את הבעל אלא בראיה ברורה, וכ\"ש לדעת רבינו שכתב בפ\"א מהלכות נחלות (ה\"ט), שספק מגורשת שמתה אין הבעל יורשה. עכ\"ל. וכתב הגריב\"ז ז\"ל דלכאורה מאי שנא מזונות משאר תנאי הכתובה, והלא להרמב\"ם ז\"ל גם מזונות הם מתנאי כתובה כמ\"ש בפי\"ב מהל' אישות ה\"ד, ופי\"ז שם הי\"ט. אלא מוכח שחיוב המזונות של ספק מגורשת הוא חיוב חדש, משום שהיא מעוכבת מחמתו, הלכך תיקנו לה מזונות ולא שאר תנאי הכתובה.","b":false},{"t":"עוד כתב שם דיוק נפלא, שבפ\"ו מהלכות גירושין הנ\"ל, כתב הבעל ששלח גט לאשתו, הרי הוא \"חייב במזונותיה\" עד שיגיע הגט לידה, ואילו בפי\"ח מהלכות אישות הלכה כ\"ה, בספק מגורשת, לא כתב שהוא חייב במזונותיה, אלא כתב בזה\"ל, אבל בחיי בעלה יש לה מזונות עד שתתגרש גירושין גמורים. עכ\"ל. והיינו טעמא דאין זה מדין חיוב המזונות הרגיל שהבעל חייב לאשתו, דמצד זה אינו חייב במזונותיה, כי מספק אין להוציא מיד המוחזק, אלא שיש לה מזונות עד שתתגרש גירושין גמורים, והוא דין מיוחד כי היא מעוכבת מחמתו, חייבוהו במזונותיה, כי היכי דלא לעגנה.","b":false},{"t":"עוד כתב שם ולפי זה נראה, שאין לו זכות במעשה ידיה, הגם שנותן לה מזונות, כיון שאין חיוב זה מתורת מזונות נשואה, אלא שהוא חיוב חדש, משום שהיא מעוכבת מחמתו.","b":false},{"t":"ושוב הזכיר את מחלוקת הראשונים, בהגיע זמן ולא נישאו, דאמרו בכתובות (ב' ע\"ב), דאוכלות משלו ואוכלות בתרומה. ובשיטה מקובצת בכתובות (ק\"ז ע\"ב), ד\"ה ואי, כתבו בשם הרא\"ה ז\"ל דבארוסה אין מעשה ידיה שלו עד שתנשא לו. ואעפי\"כ כשהגיע זמן חייב במזונותיה, ואולם בחידושי הריטב\"א ז\"ל כתובות (נ\"ז ע\"א), כתב וז\"ל, אוכלת משלו, פירוש שהוא חייב במזונותיה, וה\"ה בכסותה ופרנסה כאילו נכנסה לחופה וזוכה במציאתה ובמעשה ידיה. ע\"כ. ועיין אור שמח (פ\"י מהלכות אישות הי\"ט), שנסתפק בזה. ע\"ש.","b":false},{"t":"וכבר כתבתי כל זה בתשובה שם, ואמרתי שגם הריטב\"א ז\"ל יודה במעוכבת מחמתו, דשאני הגיע זמן ולא נישאו, שעשאוה כמו שנכנסה כבר לחופה. כדי שלא יעכבנה בחינם, וכנשואה שוו לה, וע\"כ מעשה ידיה ומציאתה שלו הן, אבל זאת שהיא ספק מגורשת, ורוצים שלא יעגנה אלמנות חיות, וע\"כ קנסו ליה שישלם לה מזונות, לא הקלו עליו שיקבל מעשה ידיה, דלאו כנשואה שוו לה, דאדרבה רוצים ללחוץ עליו בחיוב מזונותיה, שימהר לגרשה. וכן ראיתי שהרב ז\"ל גופיה כתב כן, וכתב דהוי כמ\"ש המ\"מ שם בדעת הרמב\"ם ז\"ל דספק מגורשת אין לה תנאי הכתובה, כי אם מזונות בלבד. וא\"כ י\"ל שגם מעשה ידיה אין לו שגם זה מכלל תנאי הכתובה, וגם לא זוכה במציאתה. וכבר העליתי כן לדינא בשמע שלמה ח\"א וח\"ג שם.","b":false},{"t":"ג.","b":false},{"t":"בדין מזונות ספק מגורשת, ואם בעלה יורשה.","b":true},{"t":"אלא שראיתי להגאון ריב\"ז ז\"ל באותה תשובה, שחזר והיה מסתפק בדין מזונות מעוכבת מחמתו, ששב והביא דברי השיטה מקובצת בבא מציעא (י\"ב ע\"ב), על מ\"ש בגמרא שם ד\"ה ולענין פסק הלכה, מציאת אשתו מגורשת ואינה מגורשת, הרי היא שלה. וכתבו משם רמ\"ך ז\"ל, אעפי\"כ חייב במזונותיה, וה\"ה שהוא חייב בכל תנאי ממון של הכתובה, ואם מתה יורשה מכל מה שתחת ידו מספק, וקרוב לומר שאם נשבית אינו חייב לפדותה, כיון שהיא ספק מגורשת, אין אני קורא בה ואהדרינך לי לאינתו. וה\"ה שאינו אוכל פירות, כיון שנתן לה גט, ואפשר לומר כיון שאינה מגורשת ודאי, עדיין אשתו היא לכל דבר, חוץ מזכות מציאתה. ע\"כ. הרי מבואר בדבריו שספק מגורשת היא כנשואה וחייב לה בכל תנאי ממון של כתובה, ואם מתה יורשה מכל מה שתחת ידו מספק. והטעם כיון שאינה מגורשת ודאי, היא עדין אשתו לכל דבר (ויש להעיר דמ\"מ לא אמר מע\"י שלו).","b":false},{"t":"עוד כתב שם שכן משמע מדברי הראב\"ד ז\"ל בהשגתו על הרי\"ף ז\"ל (כתובות ק\"ג ע\"ב), שהביא דברי הירושלמי, שכל עוד שלא נתן לה כתובה חייב במזונותיה, ובתוך דבריו כתב וז\"ל, אלמא כל זמן שלא נתן לה כתובה שייכא ביה, ואית ליה זכייה עלוייה, והם מעשה ידיה תחת מזונותיה וכו'. ונראה דהראב\"ד אזיל לטעמיה בהל' נחלות (פ\"א ה\"ט), שבספק מגורשת בעלה יורשה. וכן הוא בדברי הרמ\"ך ז\"ל הנ\"ל, דבעלה יורשה בכל מה שתחת ידו מספק, והיינו כאשתו לכל דבר, והראב\"ד ז\"ל כתב את זה גם להירושלמי, דכל עוד שלא פרע לה כתובתה, הרי הוא לגבי ממונות כאשתו לכל דבר, ואולם הרמב\"ם ז\"ל כתב בהלכות נחלות (פ\"א ה\"ט), דספק מגורשת אין בעלה יורשה. ואין לה כל תנאי הכתובה. כמ\"ש בהלכות גירושין (פ\"ו ה\"ל), הנ\"ל. וחיוב מזונותיה הוא חיוב מחודש, משום שהיא מעוכבת מחמתו. ואפ\"ל דאין לו זכות במעשה ידיה. וזה לא רק בספק מגורשת אלא אפילו מגורשת גמורה, כל עוד שהיא מעוכבת מחמתו להנשא, יש לה מזונות.","b":false},{"t":"ד.","b":false},{"t":"אשה שזינתה ובעלה אינו מחוייב לגרשה אם חייב ליתן לה מזונותיה.","b":true},{"t":"ועיין בדו\"ח לרעק\"א חלק הכתבים (צ\"א ע\"ב), בשם המג\"א שכתב דבזינתה אם אינו מחוייב לגרשה, חייב ליתן לה שאר וכסות. ורעק\"א ז\"ל העיר ע\"ז וז\"ל, אבל באמת דברי המג\"א לא מובנים לי, דכיון דאסורה לו מחמת מעשיה, ליכא חיוב מזונות. ועיין יבמות (פ\"ה ע\"א). ע\"כ. וכתב הרב ז\"ל, דכונת המג\"א היא, דכיון שאינו רוצה לגרשה, א\"כ היא מעוכבת מחמתו, וחייב במזונותיה, ולא מדין חיוב מזונות דנשואה, אלא חיוב מחודש, משום שהיא מעוכבת מחמתו, וע\"כ הגם שמעשיה גרמו לה, מ\"מ כיון שבידו לגרשה והוא מעכבה, חייבוהו במזונותיה. והא דאמרו ביבמות שם, דבאסורה לו לית לה מזונות אעפ\"י שהם נשואים, דילמא מעכבה גביה, שם מדובר במזונות של נשואה, והיא אינה רוצה להתגרש ממנו, אלא הוא רוצה לגרשה, בזה אמרו שאין לה מזונות כדי שתתגרש ולא ימשיכו לחיות באיסור זע\"ז, (אבל כשהוא מעכבה אפילו שהיא אסורה לו ומעשיה גרמו לכך, ס\"ל למג\"א דיש לה מזונות של מעוכבת מחמתו).","b":false},{"t":"עוד כתב הרב ז\"ל: ומעתה בנידון זה, כשקיים פירוד אזרחי והבעל מסרב לתת לה גט, אם התחייב בשעת הנישואין לשלם לה סכום מסויים למזונות, וזה כולל כסות ומדור, הרי ההתחייבות היא כדין, שהרי היא מעוכבת מחמתו להנשא. והרי אפילו זינתה שמעשיה גרמו לה, דעת המג\"א שהוא חייב במזונותיה. אלא שלכאורה לשיטת הראשונים הנ\"ל, שגם במעוכבת להנשא מחמתו, אם הוא נותן לה מזונות, הוא זוכה במע\"י, וא\"כ הבעל יכול לדרוש את מע\"י, כשהיא עובדת ומרויחה לפרנסתה, ויכול לומר לה צאי מעשה ידיך למזונותיך, ויפטר ממזונותיה.","b":false},{"t":"ואולם הח\"מ (סימן ק\"ב), כתב משם הב\"ח, שנוהגים במדינות אלה שאין להוציא מיד האשה שום העדפה שעל ידי הדחק, והלא כל מעשה ידי האשה בימינו, היא העדפה שע\"י הדחק, וא\"כ יכול הבעל להתחייב לנהוג כמנהג המדינות, שאין לו זכות במעשה ידיה, שהוא העדפה שע\"י הדחק. ועוד דנפסק בשו\"ע אהע\"ז (סימן ס\"ט ס\"ו), התנית האשה שלא יזכה הבעל באחד הדברים שהוא זוכה בהם, התנאי קיים, וא\"כ אפשר להתנות לפני הנישואין שבמקרה של פירוד אזרחי ביניהם, אין לו כל זכות באחד מן הדברים שהוא זוכה בהם, דהיינו לא במע\"י ולא בפירות נכסי מלוג שלה. ולא בירושתה, כמבואר שם בשו\"ע (סימן ס\"ט ס\"ז), ומ\"מ הוא חייב במזונותיה כדין, שהרי היא מעוכבת מחמתו, וע\"ש שכתב שהצעה זו היא טובה.","b":false},{"t":"ה.","b":false},{"t":"אם אמרינן בחיוב מזונות דמעוכבת לינשא, שעולה עמו.","b":true},{"t":"עוד כתב שם מול סו\"ף, דהסך אלפיים דולר שהציע, לכתוב בהסכם הזה, כמובן זה תלוי במעמדו הכספי של הבעל, דבמזונות קי\"ל עולה עמו. אלא שיש להסתפק אם בחיוב מזונות דמעוכבת להנשא מחמתו שהוא חיוב מחודש של מזונות, האם אומרים בזה הכלל דעולה עמו. דאפשר שזה נאמר רק בחיוב מזונות דנשואה, אבל זאת שחכמים דואגים שלא תתעגן, ואשר ע\"כ חייבוהו במזונותיה שימהר לגרשה, יש מקום לומר דבזה לא אמרו עולה עמו.","b":false},{"t":"ומ\"מ הבעל יכול לחייב עצמו במזונות לפי כבודו ומעמדו. וזה כדין, גם במזונות של מעוכבת מחמתו (ובאמת בשו\"מ תנינא (ח\"ד סי' ק\"ע), כתב דלא עולה עמו במזונות אלו).","b":false},{"t":"ועוד דלפי הצעה זו הבעל זכאי להגיש תביעה בב\"ד רבני לפטור אותו מספק זה לגמרי או ממקצתו. וסיים דזו רק הצעה גרידא ולא חוות דעת הלכתי, כי זה נתון לגדולי התורה באמריקא שלהם זה נוגע להלכה ולמעשה. וביחוד זה נתון לגאון ישראל ותפארתו הגאון האדיר מרן ר' משה פיינשטיין (שליט\"א), וכאשר יגזור כן יקום. עכ\"ל.","b":false},{"t":"והנה במה שרואים בסוף דבריו דהגרי\"ב ז'ולטי ז\"ל, דמסתפק בחיוב מזונות דמעוכבת, אם אפשר לומר בהם עולה עמו, או לא, ואם זוכה במעשה ידיה, ואז יכול הוא לומר לה צאי מעשה ידיך למזונותיך, ומתוך ספקות אלו היה מהסס בעצם התקנה הזאת. ואפילו אחרי שכתב לסמוך על מנהג המדינות (ח\"מ בשם הב\"ח), דאין הבעל זוכה בהעדפה שע\"י הדחק, ושכל המע\"י בזמנינו הם העדפה שע\"י הדחק, מ\"מ כתב דהסכום שנקבע בהסכם תלוי במעמדו הכספי של הבעל, ורק נסתפק אי אמרינן במזונות אלו, שהיא עולה עמו, או לא.","b":false},{"t":"ואולם אחר המחילה רבה מהדר\"ג העלים עיניו מתשובתו של הגאון הגדול בדורו רבינו הרא\"ם ז\"ל (סימן ל\"ד), שכתב דספק מגורשת אעפ\"י שהבעל חייב במזונותיה, מ\"מ אינו זוכה במעשה ידיה. ע\"ש.","b":false},{"t":"ו.","b":false},{"t":"אם חיוב מזונות למעוכבת מלהנשא הוא חיוב מחודש.","b":true},{"t":"ובאמת שגם הגריב\"ז ז\"ל העלה בפשיטות דאין מזונות מעוכבת כמזונות נשואה, אלא זה חיוב מחודש שתיקנו למי שמעכב אשתו. וחזר ע\"ז כמה פעמים, ובזה פי' גם את דברי המג\"א דלא יקשה מה שהקשה עליו רעק\"א ז\"ל, דאחר שמעשיה גרמו לה ליאסר שזינתה תחתיו, אמאי חייב במזונותיה. והוא ז\"ל פי' דכיון דבידו לגרשה והוא מעכבה מלינשא, ע\"כ נכלל בחיוב המיוחד הזה של מזונות מעוכבת מחמתו. וא\"כ מאחר דפשיטא ליה שזה חיוב מיוחד, מהיכי תיתי לומר שמעשה ידיה שלו, דבשלמא מזונות רגילים שהוא קיום הבית, וחכמים ראו שיש לשתפם יחד בקיום הבית כשעיקר הנטל מוטל על שכמו של הבעל, והוא חייב במזונות, אך ביחד עם זאת תיקנו שמעשה ידיה ומציאתה של האשה, יהיו של הבעל. ויש בזה משום נשיאה בעול בשותפות, ולא יראה לבעל שהוא נותן כל מה שיש לו, ואחריות ההוצאות מוטלים עליו, והיא עושה אוצר לעצמה ממעשה ידיה ומציאותיה, ואולי זה מ\"ש חז\"ל. משום איבה. כי ההרגשה הזאת שהעול כולו מוטל רק על אחד מהם, והשני עושה לעצמו ולעתידו, יש בה להביאם לאיבה ולשנאה.","b":false},{"t":"אבל מזונות אלו, שהם באים במטרה של לחץ על הבעל, שלא יעגן את אשתו אלמנות חיות, ואין כאן ענין של סידור מערכת חיים משותפים, שהרי הם במצב של גירושין, ואינם יכולים לחזור לחיות ביחד בשלום, אא\"כ יערכו קידושין ונישואין מחדש ברצון שני הצדדים, כי למעשה הם מגורשים בספק, וצריך לתת לה גט אחר כדי לצאת מן הספק. וע\"כ פשוט שאין במזונות אלו שהטילו חז\"ל על הבעל, כדי לסדר את חייהם המשותפים, אלא כל מטרתו, שלא לתת יד לבעל לעגן אשתו מתוך שנאה ונקמנות וכדומה, ע\"כ הטילו עליו חוב של מזונות כדי להכביד עליו, ויעדיף לגרשה כדי לפטור עצמו מחוב זה. וא\"כ אין סברא שיתקנו מעשה ידיה, דלא שייך במזונות אלו לתקן מע\"י לבעל.","b":false},{"t":"ובאמת במסכת ב\"מ (י\"ב ע\"ב), אמרו במפורש, דמגורשת ואינה מגורשת בעלה חייב במזונותיה, אך מציאתה שלה. דמציאתה שלו משום איבה, והכא תהיה לה איבה ואיבה, וע\"ז כתב הרא\"ם ז\"ל (סימן ל\"ד), דגם מעשה ידיה שלה, שגם מע\"י כמו מציאתה תיקנו שיהיו לבעלה משום איבה, ובכה\"ג לא שייך איבה. ומאחר ומעשה ידיה שלה, בודאי שאינו יכול לומר לה צאי מעשה ידיך למזונותיך. והוא נשאר בחיוביו, שחייב עצמו במזונותיה. ויש לו אפשרות לבא לב\"ד רבני וידרוש להפחית או לבטל אותו חיוב, וביה\"ד יבדוק את המצב, ועפי\"ז יפסוק בחיובו, ואם יש צורך לחייבו בסכומים גבוהים כדי לאלצו לגרשה בג\"פ כדת, יעשו כראות עיני ביה\"ד, שכל מטרת המזונות הללו אינם אלא לקיומה של מטרה זו, שיגרשנה, ולא יעגנה לפי שנאתו ונקמנותו. ומה שצריך שיתחייב בסכום מסויים עובר לגירושין, הוא כדי שיוכלו לבצע את זה ע\"י בית משפט אזרחי, שכן בחו\"ל אין כח ב\"ד יפה לבצע חיובים כאלה מכוח הדין, וע\"כ אותו חיוב צריך להיות מאושר בבית משפט אזרחי ואם לא יתן לה גט, תפנה לבית משפט שיאלצו לשלם לה מה שהתחייב, אלא שיש לו זכות לדרוש בב\"ד רבני ביטול החיוב או הפחתתו, וזה חלק מההסכם, שרק ב\"ד רבני יכול לבטל או להפחית, והמטרה שיבא לב\"ד וידברו על הגט, ויראו בשלמי הרעה הזאת ויפסקו עפ\"י ראות עיניהם כי להם משפט הבחירה.","b":false},{"t":"אלא שהגרי\"ב ז'ולטי ע\"ה, חשש מפני דעות הראשונים שכתבו, גבי הגיע זמן ולא נישאו, דמעשה ידיה הם של בעלה שחייבוהו לזונה. והם השיטמ\"ק בב\"מ (י\"ב ע\"ב), דשם אמרו שחייב לזונה, ומציאתה שלה. וכתבו שם בד\"ה ולענין פסק הלכה, וה\"ה שהוא חייב בכל תנאי ממון של הכתובה, ואם מתה יורשה, בכל מה שתחת ידו מספק, וקרוב לומר שאם נשבית אינו חייב לפדותה, כיון שהיא ספק מגורשת, אין אני קורא בה ואהדרינך לי לאינתו. וה\"ה שאינו אוכל פירות, כיון שנתן לה גט. וכו'. וכנ\"ל. ולפי עניות דעתי אין שום ראיה מזה דמע\"י שלו, כי לא הזכיר מע\"י כלל וכלל, למרות שפירט וכתב דין הפדיון והפירות והירושה, ואילו מע\"י שגם הן תנאי כתובה לא הזכיר כלל. ואדרבה לפי ענ\"ד זה מלמד שהוא משוה מע\"י למציאה שבכל מקום הזכירום ביחד, וטעם אחד נאמר בהם, שהם משום איבה, וכיון שבגמ' אמרו במפורש שמציאתה שלה, תהיה לה איבה ואיבה, אזי ה\"ה והוא הטעם שגם מע\"י שלה שדינם כמציאתה, וטעמם ג\"כ משום איבה, וכיון שהיא ספק מגורשת, ואסור להם לשוב זל\"ז אלא א\"כ יערכו חו\"ק מחדש, וכל מטרת המזונות היא כדי לזרזו לגרשה, ואשר ע\"כ בודאי אין שום שייכות לחוש לאיבה בזה, ע\"כ מע\"י הם שלה כמו שמציאתה שלה אעפ\"י שהוא זנה.","b":false},{"t":"ז.","b":false},{"t":"למה בגמ' הזכירו במעוכבת להנשא שמציאתה שלה ולא הזכירו מעשי ידיה.","b":false},{"t":"ואין להקשות למה אמרו דין מציאתה בגמרא ולא הזכירו מעשה ידיה, דלק\"מ דבמס' ב\"מ דנים בדיני מציאות, וע\"כ הזכירו מענין המסכת ולא מע\"י, והאחד ילמד על חברו, וכפי שכתב הרא\"ם ז\"ל שלומדים מע\"י שהם שלה מדין המציאה המבואר בגמרא. וכאמור בשיטמ\"ק פירטו יתר הזכויות והחובות שהם מתנאי הכתובה, ואילו מע\"י לא הזכירו כלל, והיינו טעמא שהוא כמבואר בגמרא שם, כיון שדינו וטעמו כדין מציאתה, שהגמרא אמרה במפורש שהם שלה. וע\"כ אין מדברי השמ\"ק שום ראיה לדחות דברי הרא\"ם ז\"ל המפורשים, וכן כל הראיות הברורות ונכוחות הנ\"ל.","b":false},{"t":"ח.","b":false},{"t":"כל שהמזונות משום קנס אין הבעל זוכה במעשי ידי אשתו.","b":true},{"t":"עוד כתב שם הגרי\"ב ז'ולטי ז\"ל, שכן משמע מדברי הראב\"ד ז\"ל בהשגתו על הרי\"ף ז\"ל שהביא את הירושלמי שכל זמן שלא פרע לה כתובתה חייב במזונותיה, וכתב הראב\"ד דעדיין שייכא ביה, ומעשה ידיה שלו תחת מזונותיה, והוסיף דהראב\"ד ז\"ל לשיטתו דפסק בהל' נחלות (פ\"א ה\"ט), שספק מגורשת בעלה יורשה, שהיא כאשתו. והנה נכון שהראב\"ד ז\"ל אזיל לשיטתו דאמר בעלה יורשה כי לא נגמרו גירושיה, ועדיין אגידא ביה, ומזה מפרש דגם מזונותיה של מגורשת וא\"מ אינם קנס, אלא המשך החיוב הקודם, ולפי\"ז מובן דמע\"י שלו כקדם וכבתחילה. אבל הרמב\"ם ז\"ל שם פסק דאינו יורשה, ואין לה כל תנאי הכתובה, מלבד מזונותיה בלבד. וכמ\"ש בהל' גירושין (פ\"ו הלכה ל'). וכ\"כ המ\"מ שם, וזהו דעת רוב הפוסקים, ומזה עצמו למדנו דס\"ל כרש\"י ותוס' ורוב הראשונים, שמזונותיה של ספק מגורשת, הם חיוב מחודש ולא המשך המזונות הקודמים שלפני הגט, וקנסא הוא שקנסוהו כדי שלא יעגנה ולא יעכב השלמת גירושיה.","b":false},{"t":"ואשר לפי זה בודאי דלא זוכה במעשה ידיה, דאין מזונות אלו מכוח מזונות הנישואין, שבהם תיקנו לו, שזוכה במעשה ידיה תחת מזונותיה. רק קנסו אותו שיהיה חייב במזונותיה, עד שיגמור גירושיה, כדי שלא יתעלל בה ויעגנה. ואין זה קשור עם התקנה של מע\"י תחת מזונותיה, וגם דלא שייך בזה איבה, וע\"כ לא שייך לומר דמסתמא תיקנו שיהיה כמו מזונות נשואה, דשם תיקנו לו מע\"י משום איבה וכאן לא שייך איבה, וע\"כ לא תיקנו לו מעשה ידיה. גם אין לומר שכבר נקבע שהחיוב במזונות נוטל כנגדם מעשה ידיה, דזה נאמר במזונות של נשואה ובנמשך מהם, אבל מזונות מגורשת ואינה מגורשת, אין הם המשך המזונות של הנישואין, ואין שום קשר ביניהם. וכ\"כ הכס\"מ (פ\"ו מה\"ג ה\"ל), דרק מזונות בלבד מגיע לה ספק מגורשת, ולא שאר תנאי כתובה. ע\"ש.","b":false},{"t":"והנה התוספות ביבמות (מ\"א ע\"ב), בד\"ה עמד בדין וברח, כתבו בסוף הדיבור (על חיוב המזונות ליבמה אחר שדן אם חייב לה רק כשעמד בדין וברח, או אפילו לא ברח), כתבו בזוה\"ל, וקצת נראה דמחמת קנס שקנסוהו חכמים שלא כנסה, תיקנו לה מזונות. דהא אין מעשה ידיה שלו, כדאמר בכתובות (ק\"ז ע\"ב), אי משום מעשה ידיה לא משעבדא ליה. עכ\"ל. והנה מפורש בדבריהם דכשהמזונו' אינם מדין מזונות, אלא קנס, אז לא זוכה במעשה ידיה. ואחר שכבר הוכחנו דלרוב הראשונים, חיוב המזונות של מגורשת וא\"מ, הוא חיוב מחודש וקנסא הוא שלא יעגן את אשתו, א\"כ פשיטא שאין מע\"י שלו.","b":false},{"t":"וכן בקדש ראיתי בפד\"ר (כרך י'), שהביאו דברי התוס' הללו, ושכן כתב גם הרא\"ש ז\"ל בפסקיו שם, כדברי התוס', דכל שהמזונות הם קנס, אין הבעל זוכה במעשה ידיה, ולהלן נביא מדבריהם שם בעהית\"ש.","b":false},{"t":"עוד זימן ה' לידי מציאה יפה, תוך כדי עיון בדין מגורשת ואינה מגורשת אם עולה עמו לענין מזונותיה, שהגאון שואל ומשיב במה\"ת (ח\"ד סימן ק\"ע), ד\"ה אמנם מלבד, העלה דאינה עולה עמו כיעו\"ש. וראיתי לו שם שכתב וז\"ל, וכשיש לה שדה תהיה אוכלת ומסתפקת במה שתרצה, וגם אם תשביח השדה יהיה השבח שלה, דמעשה ידיה של ספק מגורשת הם שלה, דמע\"י לא תיקנו רק משום איבה כמבואר בכתובות (נ\"ט), והכא תיהוי לה איבה ואיבה, דמטעם זה מציאתה לעצמה, כמ\"ש באהע\"ז (סימן פ\"ד), וא\"כ השבח שלה. וכו'. עכ\"ל.","b":false},{"t":"והרי לפנינו שגם הגאון שואל ומשיב מיפשט פשיטא ליה, דמעשה ידיה של המגורשת ואינה מגורשת, הם שלה, ואין לבעלה בהם כלום, אעפ\"י שהוא חייב במזונותיה, וכמ\"ש הרא\"ם ז\"ל. וכאמור כן עולה בפשיטות מדברי רוב הראשונים, ובפרט לאור דברי התוס' דיבמות (מ\"א ע\"ב), הנז'.","b":false},{"t":"ועיין מ\"ש בדין מזונות דמעוכבת מחמתו בשו\"ת שמע שלמה (ח\"א סימן י\"א אות ט'), ועוד יותר בשמע שלמה ח\"ב (חאהע\"ז סימן י\"ט), והבאתי מפד\"ר כרך ג' (עמוד 45), שלמדו מהישועות יעקב הנ\"ל, שחיוב המזונות של מעוכבת מחמתו הוא לא המשך של חיוב המזונות של נשואה, אלא הוא דין מחודש שמחייבים לבעל כדי לזרזו לגרש אשתו ולא יעגנה אלמנות חיות.","b":false},{"t":"וכתבתי דלפי זה גם בעובדת ומרויחה כדי מחייתה, יש לחייבו במזונותיה, דזה לא הוי חיוב מזונות רגיל שתיקנו לו מעשה ידיה תחת מזונותיה, אלא זו תקנה מיוחדת שקנסוהו כדי שלא יעגנה, וע\"כ אינו זוכה במעשה ידיה. וכן פסקו להדיא בביה\"ד הגדול כאמור בפד\"ר כרך י' (עמוד 294), לחייבו במזונות אפילו שהיא עובדת ומרויחה, וסמכו על אילן גדול הוא רבינו אליהו מזרחי ע\"ה (בסימן ל\"ד), דמגורשת ואינה מגורשת בעלה חייב במזונותיה, ואינו זוכה במעשה ידיה. וכתבו שם שזו דעה מוסכמת.","b":false},{"t":"וכן הזכרתי שם את דברי רש\"י ז\"ל בכתובות (צ\"ז ע\"ב), ד\"ה כדרבי זירא, שכתב בפירוש שחיוב מזונות אלו הן משום שמעוכבת בשבילו להנשא. וכנ\"ל. ושכן עולה מהתוספות שם (ד\"ה לאתויי), להדיא. ומאחר וזה חיוב מיוחד כדי שיגרשנה, פשוט שאינו זוכה במעשה ידיה, וכדברי הרא\"ם ז\"ל. וע\"כ אפילו שהיא עובדת ומרויחה כדי מחיתה, יש לחייבו במזונותיה כל זמן שמעכבה מלהנשא, שלא כדין.","b":false},{"t":"ולעומת זה הבאתי פס\"ד מב\"ד הגדול מהגר\"א הורוויץ שליט\"א, והוא בפד\"ר כרך ט\"ו (עמוד 14), שכתב לדחות את הפסקי דין שניתנו ע\"י ביה\"ד הקודם, והעלה דחיוב המזונות במגורשת ואינה מגורשת, אינו קנס ותקנה מיוחדת, אלא זו מההלכות של חיוב מזונות אשה, דכל זמן שהיא אגידא ביה, הוא חייב במזונותיה, ולא משום שמעכבה, אלא אפילו אם היא לא מבקשת גט, ג\"כ חייב במזונותיה משום דאגידא ביה. והביא כמה ראיות המוכיחות כדבריו, ואני בעניותי הבאתי ראיותיו באותה תשובה, ודחיתי אותם, וגם הוכחתי מהם היפך מדבריו. וקיימתי בזה את דברי הרבנים הגאונים שלפניו, שפסקו דחיוב מזונות דמעוכבת מחמתו, קנס הוא שקנסוהו חכמים, או תקנה מיוחדת כדי לזרזו לגרשה ולא יעגנה. וע\"כ גם אם עובת ומרויחה מחייבים אותו במזונותיה. וכן עשינו מעשה בבה\"ד בפתח תקוה, לחייב הבעל שסירב לגרש את אשתו למרות שחייבנו אותו לגרשה, וחייבנו אותו במזונות עבורה אעפ\"י שהיתה עובדת ומרויחה כדי מחיתה. ומלבד דהדבר מבואר להדיא בישועות יעקב הנז', שחייב מזונות לבעל שעיכב אשתו בשקר, והתברר שבאמת היתה גרושה ממנו לגמרי, אך כיון שעיכבה בטענותיו, חייבו לשלם לה מזונות לכל התקופה שעיכבה, ומזה מוכח שאין אלו מזונות רגילים, וע\"כ לא שייך לדרוש מעשה ידיה. וכאמור כן מבואר ומפורש בדברי רש\"י והתוספות בכתובות (צ\"ז ע\"ב), הנ\"ל. וכן מוכח מהרי\"ף והרמב\"ם ז\"ל כאשר כתבתי לעיל. וכ\"פ הרא\"ם ז\"ל להדיא דאין לו מעשה ידיה. והגר\"א הורוויץ שליט\"א באותו פס\"ד, כתב להוכיח מהרא\"ם ז\"ל גופיה בתשובה אחרת (סימן ל'), שבה כתב דאם רוצה לגרשה אעפ\"י שאינו יכול לגרשה בעל כרחה מצד התקנה, כיון שמן הדין מצי לגרשה בע\"כ פטור ממזונותיה, וע\"ש שרצה להוכיח מזה היפך ממ\"ש הרא\"ם בסימן ל\"ד, דמעשה ידיה שלה אעפ\"י שהוא זן אותה, ובתשובתי שם (אות ו'), הבאתי דבריו ודחיתי אותם ג\"כ והוכחתי דהרא\"ם אזיל לשיטתו, שהמזונות של מעוכבת אינן דומים למזונות רגילים כלל. והוכחתי שלהרא\"ם אין חיוב מזונות כל זמן שהיא אגידא ביה, וע\"ש שהארכתי בכל הדברים וביררתי אותם הדק היטב היטב הדק, עד שיוצאים מן הספק.","b":false},{"t":"ובאות ט' שם, כתבתי דמהרמב\"ם ז\"ל בהל' אישות (פי\"ח הכ\"ה), היה מקום להוכיח כדבריו, שכל זמן שאגידא ביה חייב במזונותיה, וכן נמי מהרשב\"ם ז\"ל בב\"ב (מ\"ז ע\"ב), ד\"ה מגורשת וכו', אך יישבתי הדברים על נכון להוכיח שאין מזונות מעוכבת מזונות רגילים, אלא הם תקנה מיוחדת כדי לזרז ולאלץ הבעל לגרש את אשתו, ולא להמשיך לעגנה.","b":false},{"t":"ובאות י' שם הבאתי גם דברי מו\"ר במשנת יעקב על הל' אישות (פ\"י הי\"ט אות ב' עמוד קמ\"ב), שעמד ע\"ד רש\"י ז\"ל בכתובות (צ\"ז ע\"ב), וכן מ\"ש בשיטה מקובצת שם, מדברי הרמב\"ן ז\"ל כיע\"ש. וכן הביא מדברי מהרי\"ט ז\"ל ח\"א (סימן קי\"ג), שפסק לחייב הבעל הנכפה במזונות אשתו גם אם אינה עמו, כל זמן שאינו מוציאה בגט, שהרי גדולה מזו אמרו בפ\"ק דב\"מ (י\"ב ע\"א), כל מקום שאמרו חכמים מגורשת ואינה מגורשת בעלה חייב במזונותיה, אעפ\"י שנתן לה כתובתה, כל זמן שהיא מעוכבת מלינשא מחמתו. וכתב הרב נר\"ו, דמבואר במהרי\"ט דזה יסוד לחיוב המזונות מחמת דמעוכבת מלינשא מחמתו שאינו מגרשה.","b":false},{"t":"עוד העיר שם בדברי מהרי\"ט ז\"ל דהו\"ל להוכיח מרש\"י ז\"ל הנ\"ל ומהרא\"ש ז\"ל שם, אבל מההיא דב\"מ (י\"ב ע\"א), י\"ל דשא\"ה שהיא ספק מגורשת, וי\"ל דחייב במזונותיה, משום דהוי ספק פירעון. ושב ויישב למהרי\"ט ז\"ל די\"ל דס\"ל כההפלאה בכתובות (צ\"ז ע\"ב), על התוס' ד\"ה לאתויי, דחוב המזונות חל בכל יום ויום מחדש, והו\"ל כאיני יודע אם נתחייבתי, והיה צריך להיות פטור. ומדחייבוהו במזונות למד מהרי\"ט ז\"ל, דהחיוב הוא בגלל העיכוב שמעכבה מלינשא בזה שאינו מגרשה בג\"פ כדת משה וישראל, ושפיר למד מזה לחייב את הנכפה במזונות אשתו, כל זמן שלא מגרשה. וע\"ש.","b":false},{"t":"והוספתי שם בשולי הדברים, דאפילו אם לא נאמר שמהרי\"ט קאי בשיטת ההפלאה הנ\"ל, אלא חיוב המזונות חל מיום נישואיהם, ואינו מתחדש בכל יום מחדש. מ\"מ כשזרק לה גיטה ספק קרוב לה וכו', אינו חשוב ספק פירעון, אלא הוי ספק בעצם החיוב, דהגירושין אינם במקום פירעון המזונות, אלא עקירת החיוב של המזונות, וא\"כ ספק גירושין, הוא ספק אם נעקר החיוב או שעודנו קיים, ולא גרע מכל ספק בחיוב, דאמרינן ביה מספיקא לא מפקינן ממונא, ובזה יש ליישב דברי האור שמח, ממ\"ש עליו במשנת יעקב שם.","b":false},{"t":"ועי\"ש עוד מ\"ש לחזק כל זה בסברא וזו המסקנא דחיוב מזונות דספק גרושה הוא רק מפני העיכוב שמתעכבת בגללו, וכדי שלא ינהג בה בנקמנות ויעגנה. ע\"כ עשו תקנה זו, שתהיה לו לסיבה להזדרז לגרשה. ופשוט דהעיקר כפסקו של הרא\"ם ז\"ל (סי' ל\"ד), דמעשה ידיה שלה הם, אעפ\"י שהיא ניזונת ממנו.","b":false},{"t":"וע\"כ בהסכם זה שמתחייב הבעל במזונותיה במדה ויתגרשו אזרחית, כל זמן שלא ניתן לה את גיטה בביה\"ד, יש בזה חיוב מן הדין, דמזונות ודאי חייב, שהרי הגירושין האזרחיים אינם כלום, אלא שבהסכם מחייבים אותו בסכום גבוה, ולא מתחשבים בזה, אם היא עובדת ומרויחה כדי מחיתה, מ\"מ כיון שבידו לגרשה ולהפטר מכל זה, הרי זה כדין, שכך היא תקנת חז\"ל לחייב הבעל במזונות שלא יעכב את אשתו, ועם זה מעשה ידיה שלה הם.","b":false},{"t":"ט.","b":false},{"t":"כל שההסכם נעשה לפני הנישואין אין חשש כפיה בגט.","b":true},{"t":"ועוד יש להוסיף דגם לדעת החולקים, אין בזה חשש, שכן בהסכם זה מתחייב לזה עוד לפני החתונה, וכההיא דפרק חזקת הבתים שאמרה לו שלא תינשא לו עד שיכתוב לה כל רכושו. ועוד וזה עיקר, דעם ההתחייבות הזו, הם כותבים בהסכם שיכול ורשאי לתבוע לבטל החיוב או להפחיתו, ובתנאי שיבא לפני בי\"ד רבני שדנים בדין תורתנו הקדושה, שזה כל ישראל מחוייבים ועומדים, ובבואם לפני בית הדין ויעמדו וישמיעו כל דבריהם וטענותיהם, וב\"ד יראה וישפוט כדת וכדין, ואין פה שום כפיה לא על הגט ולא על הממון, רק כפיה להביאו לב\"ד רבני, ולדון עפ\"י דין תורה.","b":false},{"t":"וע\"כ נלע\"ד שההסכם הזה אשר יסדו רבה של ירושלים המנוח הגאון רבי בצלאל ז'ולטי ע\"ה, הוא טוב ונכון, ורב התועלת למנוע מעגינות מבנות ישראל שבחו\"ל. ולמנוע איסורים חמורים של א\"א ח\"ו, ורבוי ממזרים ה' יצילנו. ואם יסכימו ע\"ז גדולי דורנו שליט\"א נוכל להביאו לפני רבני ודייני ישראל, שיציעו את זה לפני המשפט. וכאשר הם יודעים שיש עליהם מורא מלכות כזה, ממילא ימנעו ולא יבואו מלכתחילה למצב של עיגון וכדו'. וגם אם יהיה מיעוטא דמיעוטא שינסו לעגן נשותיהן שלא כדין, הרי ההסכם הזה יאלצם לבא להתדיין בפני ב\"ד רבני, והם יפסקו להם כדת וכדין, ועל ישראל שלום.","b":false},{"t":"המצפה לישועת ה' על עמנו ונחלת אבותינו.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"בענין דבש מלכות אם מותר לאכלו","p":[{"t":"א.","b":false},{"t":"הטעם שהדבש מותר באכילה ואין בו משום היוצא מן הטמא.","b":true},{"t":"הנה במסכת בכורות (ז' ע\"ב), איתא, מפני מה אמרו דבש דבורים מותר, מפני שמכניסות אותו לגופן, ואין ממצות אותו מגופן. ופירש\"י ז\"ל, שמכניסות אותו לגופן, שאוכלין מפרחי האילן, ומהן נעשה הדבש במעיהן, ואין ממצין אותו, דובשנו מגופו. עכ\"ל. ומרש\"י ז\"ל משמע דאע\"ג דהדבש הוא מהפרחים בלבד, בלא שום תערובת מגופן של הדבורים, מ\"מ הוא נעשה במעיהם לדבש.","b":false},{"t":"אבל בפירוש רבינו גרשום ז\"ל שם כתב, שמכניסות אותו לגופן שיונקים אותו מעשבי ההרים. ואין ממצות אותו מגופן, כשמוציאים אותו, אלא כי היכי דעל הכי נפיק. עכ\"ל. וש\"מ דאין שום שינוי כלל בדבש, רק כבולעו כך פולטו, בלא שום תוספת או עיבוד. ובעצם כן נראה מלשון הרמב\"ם ז\"ל (פ\"ג מהלכות מאכלות אסורות ה\"ג), וז\"ל, דבש דבורים ודבש צרעים מותר, מפני שאינו מתמצית גופן, אלא שימצאו אותו לאכול ממנו בימות הגשמים. עכ\"ל. ודבריו ז\"ל מורים שהלך בדרכו של רבנו גרשום ז\"ל הנז'.","b":false},{"t":"והנה יש לדון בדבש מלכות, אם הותר כמו הדבש הרגיל, דאפשר דזה בא מתמצית גופו, ולא דמי לדבש הרגיל שהתורה התירתו.","b":false},{"t":"ב.","b":false},{"t":"בדין דבש צרעות.","b":true},{"t":"ומ\"ש הרמב\"ם להתיר גם דבש של צרעין הוא תלוי במחלוקת התנאים, דבבכורות שם הביאו תוספתא, דתניא רבי יעקב אומר אך את זה תאכלו מכל שרץ העוף זה אתה אוכל וכו', אלא שרץ עוף טמא אי אתה אוכל אבל אתה אוכל מה שעוף טמא משריץ, ואיזה זה דבש דבורים, יכול גם דבש הגזין והצירעין, אמרת לא, ומה ראית לרבות דבש דבורים ולהוציא הגזין והצירעין, מרבה אני דבש דבורים שאין לו שם לווי, ומוציא אני דבש הגזין והצירעין שיש לו שם לווי. ופירש\"י ז\"ל שם ד\"ה רב ששת וכו', דרבי יעקב סובר דטעמא דדבש לאו משום שמכניסות וכו', אלא רחמנא שרייה בהדיא, וגזירת הכתוב היא. עכ\"ל.","b":false},{"t":"עוד אמרו בגמרא שם כמאן אזלא הא דתניא במכשירין (פ\"ו מ\"ד), דבש הגזין והצירעין טהור, ומותר באכילה, דלא כר' יעקב, וצ\"ל דלת\"ק דתלה היתר הדבש בזה דלאו מתמצית גופם הוא, ולא משום גזה\"כ, א\"כ הוא מתיר גם דבש הגזין והצירעין, דגם הם לא ממצים דבשן מגופן, אבל ר' יעקב שהתיר דבש מגזה\"כ, ס\"ל דלא התיר הכתוב אלא דבש סתם שהוא של דבורים, שאין לו שם לווי.","b":false},{"t":"והרמב\"ם ז\"ל פסק כת\"ק וע\"כ התיר דבש הצירעין. וכ\"כ הרב המגיד ז\"ל על הרמב\"ם שם, שדבש צירעין הוא מחלוקת התנאים, וסתמא דמתניתין במסכת מכשירין (פ\"ו מ\"ד), דלא כרבי יעקב. וכתב שם דסתמא דמתניתין שמתירה דבש צירעין הוא כת\"ק, שתלה היתר הדבש משום שאינן ממצות אותו מגופן, וכנ\"ל, והלכה כסתם. (וע\"כ פסק הרמב\"ם ז\"ל כת\"ק).","b":false},{"t":"והרא\"ש ז\"ל (בכורות פ\"א סימן ז'), הזכיר את הגמ', ואחר כתב בזה\"ל ר\"ת ז\"ל פסק בספר הישר דלא כר' יעקב, משום דסתם מתניתין דמסכת מכשירין דלא כותיה, דתנן התם דבש צירעה טהור ומותר באכילה. והרא\"ש ז\"ל תמה ע\"ז דבגמ' דידן אמרו דרב ששת כרבי יעקב ס\"ל. עוד כתב, דאע\"ג דלא אצטריך למימר הוא דאמר כר' יעקב, אלא ללישנא בתרא התם, אבל ללישנא קמא לא קשה מידי, מ\"מ ר\"ת רגיל לפסוק כלישנא בתרא, ובשל תורה הלך אחר המחמיר, וכן הלכתא דדבש גיזין וצירעין אסור. ע\"כ.","b":false},{"t":"וכן פסק הרמב\"ן ז\"ל בהל' בכורות (במס' בכורות דף ד' ע\"א בהלכותיו), וז\"ל, הא מילתא מסתברא לן למיפסק לחומרא ולא משום דאתברר לן מילתא הכין, אלא כיון דרב ששת סבר לה כרבי יעקב, ולא אשכחן אמורא דפליג עליה, איכא למימר דהלכתא כוותיה, דהא אמורא אמר כותיה, ועוד דהא דייק לה ממתניתין (דא\"ל רב ששת תניתוה שהיוצא מן הטמא טמא). וכיון דבגמ' לא דחי ליה מהאי דיוקא דדייק ממתניתין ש\"מ דדוקא הוא וקושטא הוא דמתני' כר' יעקב היא, ואע\"ג דלא מפרשא בהדיא הכי, וכיון דתנן סתמא כרבי יעקב הלכתא כותיה, ודאי אשכחן נמי סתמא כרבנן, דתנן במכשירין בפרק בתרא דדבש צירעין טהור ומותר באכילה, אפי\"ה האי סתמא דדייק לה רב ששת אלימא, משום דתני לה גבי הלכתא דהאי דינא, ולא אלימא ההיא סתמא אחרינתא דקתני לה בר מדוכתה אגב גררא למשרי איסורא. ובגמ' לא אותבוה לרב ששת מינה ולא אייתו לה ההיא סתמא כל עיקר. [פלא, שכן הביאוה ואמרו דלא אזלא כר' יעקב]. ועוד דלא יהא אלא ספק, הא קי\"ל ספק איסור לחומרא, והכי נמי אשכחן לחד מרבוותא דמסיק בה כרב ששת, ואשכחינן לאחרינתא דמסיק הלכתא כרבנן, ודחי לה לר' יעקב ולרב ששת דקאי כותיה. עכ\"ל. ויש הרבה לשאת ולתת בדב\"ק, ולא ראיתי למהרי\"ט אלגאזי ז\"ל שם שעמד על סוגיא זו כלל. ועוד חזון למועד אי\"ה ב\"ה.","b":false},{"t":"וה\"ה ז\"ל (פ\"ג מהמ\"א ה\"ג), כתב שהרמב\"ם ז\"ל פסק כסתמא דמתני' דמכשירין (פ\"ו מ\"ד), והוסיף דאע\"ג דבפ\"ק דבכורות משמע דרב ששת דאמר מי רגלים של חמור אסור ס\"ל כר' יעקב, ודייק לה ממתני' דקתני היוצא מן הטמא טמא, ולא אמר מטמא [אלא מן הטמא, ופירש\"י שם ריש ע\"ב מטמא, משמע מגופיה דטמא. מן הטמא, משמע מינו של טמא, והני נמי מינא דטמא הן דדמו לחלב.] ע\"כ ההוא דיוקא לאו דיוקא הוא, דא\"כ קשיא סתמא אסתמא, אלא היוצא מן הטמא אורחא דלישנא הוא, ותו דמשמע התם במסקנא דגמ' דלא כר' יעקב, דאמר בשלהי שמעתין כמאן דלא כר' יעקב. ועוד יש לי לומר דרב ששת לא ס\"ל כר' יעקב אלא בטעמיה, דדבש רחמנא שרייה, ולאו משום שאינו תמצית גופן, דא\"כ הו\"ל מי רגלים מותרים, ומתני' קתני היוצא מן הטמא טמא. אבל מה שחלק ר' יעקב במדרש הכתוב בין דבש שיש לו שם לווי לדבש שאין לו שם לווי, לא ס\"ל כותיה, אלא כיון דכתיב אך את זה לא תאכלו מכל שרץ העוף, אבל אתה אוכל מה שמשריץ, לא מפלגינן בין דבש שיש לו שם לווי או אין לו, וע\"כ לא הקשו סתמא אסתמא, וכו'. ולפי\"ז מתני' דדבש צירעין אפילו רב ששת מודה בה לענין דינא, ואטעמא דברייתא הוא דפליג, ורבינו פסק כסתם מתני' דמכשירין וכטעמא דברייתא, ודחי לדרב ששת, וס\"ל דמי רגלים של חמור מותרין, כמ\"ש בפ\"ד ה\"כ. והרמב\"ן ז\"ל פסק בהלכותיו להחמיר, ואסר דבש צירעין, וכתב שיש מי שפוסק כן. עכ\"ל הה\"מ ז\"ל.","b":false},{"t":"והטור (סס\"י פ\"א), כתב דבש דבורים מותר ואין בו משום אבר מן החי וכו'. ודבש הגיזין והצירעין כתב ר\"ת שהוא מותר וכ\"כ הרמב\"ם. וא\"א הרא\"ש ז\"ל כתב לאסור בדבש הגיזין והצירעין. עכ\"ל.","b":false},{"t":"ומרן ז\"ל בב\"י שם דבש הגיזין והצירעין כתב ר\"ת וכו', בבכורות (ז' ע\"ב), אהא דבעו מרב ששת מי רגלים של חמור מהו ופשט להו דאסור, מותיב בגמ' מדתניא מפני מה אמרו דבש דבורים מותר, מפני שמכניסים אותו לתוך גופן ואין ממצות אותו מגופן, ומשני הוא דאמר כר' יעקב דאמר דובשא רחמנא שרייה, דתניא ר' יעקב אומר אך את זה לא תאכלו מכל שרץ העוף, שרץ עוף טמא אי אתה אוכל, אבל אתה אוכל מה שעוף טמא משריץ ואי זה זה דבש דבורים, יכול אף דבש הגיזין והצרעין אמרת לא, ומה ראית, מרבה אני דבש דבורים שאין לו שם לווי וכו'. כמאן אזלא הא דתניא דבש הגיזין והצרעין טהור ומותר באכילה דלא כר' יעקב. ופירש\"י דר' יעקב לאו משום שמכניסות לגופן הוא, אלא דרחמנא שרייה להדיא וגזרת הכתוב הוא וכו'. עוד כתב הב\"י, וכתב הרב רבינו אשר ז\"ל רבינו חננאל (כנר' דלא גריס ר\"ת אלא ר\"ח), פסק דלא כרבי יעקב, משום דסתם מתני' דמכשירין דלא כותיה, ותימא הוא וכו'. (ככל שכתבתי לעיל מהרא\"ש ז\"ל), [ובמקום שכתוב ברא\"ש אצלנו ולפי שרגיל ר\"ת לפסוק כאיכא דאמרי, גורס הב\"י ר\"ח, וכן הוא גם במעדני יו\"ט שם]. אבל הרמב\"ם פ\"ג פסק דדבש צרעין מותר, כסתם מתני' דמכשירין, ואע\"פ שלא הזכיר גזין, לישנא דמתני' נקט, ואה\"נ דשרו, דאין חילוק בין גיזין לצרעין, דלתרווייהו שם לווי אית להו, וכיון דחד שרי ממילא משמע דה\"ה לאידך, וכבר כתבתי דהוא פוסק דלא כרב ששת, וכבר האריך ה\"ה לתת טעם לדבריו, וכתב שהרמב\"ן פסק בהלכותיו להחמיר ואסר דבש צרעין וכתב שיש מי שפסק כן. עוד כתב הב\"י שם, מ\"כ דבש גזין וצרעין אין מצוי לנו כלל ולתערובת לכ\"ע לא חיישינן מהרי\"א ז\"ל. עכ\"ל הב\"י.","b":false},{"t":"ג.","b":false},{"t":"בדין מי רגלי החמור ושאר פירשות דעלמא.","b":true},{"t":"והנה מכל האמור עולה דלת\"ק דמתיר דבש דבורים, מן הסברא דלא מתמצה מגופן של הדבורים, אלא כבולעו כך פולטו, והם רק משמשים לו לאוספו ולשמרו, אז ה\"ה נמי לדבש צרעין וגיזין, דגם הם כך טבעם ללקט הצוף מן הפרחים והעשבים ולשומרו לעת מצוא, אבל לרבי יעקב דצריך היתר מיוחד בתורה לדבש דבורים, ולא סמכינן אסברא דלא מתמצה מגופן, א\"כ דבש צירעין וגיזין דאית ליה שם לווי, נשאר באיסורו, דאינו בכלל ההיתר דנפיק מדרשא דקרא דאך את זה תאכלו וכו'.","b":false},{"t":"ועוד יש נ\"מ לגבי מי רגלים דחמור, דגם הם לא ממצו מגופיה רק מיא עול מיא נפיק, דרב ששת דס\"ל כרבי יעקב אסרם, דמי רגלי החמור ודאי לא נכללו בהיתר הדבש, אבל ת\"ק דלא בעי היתר דקרא, רק מתיר הדבש משום שאינו מתמצה מגופן, וע\"כ מתיר גם דבש גיזין וצרעין, ה\"ה יש להתיר מי רגלי החמור, שגם הם לא מתמצו מגופן.","b":false},{"t":"וכ\"כ הרמב\"ם ז\"ל (פ\"ד מהמ\"א ה\"כ), וז\"ל, עור הבא כנגד פניו של חמור מותר באכילה, מפני שהוא כמו הפרש ומי רגלים, שהן מותרים. עכ\"ל. והראב\"ד ז\"ל השיגו וז\"ל, א\"א רב ששת פשט להו לאיסורא בבכורות (ז' ע\"א), ממתניתין. עכ\"ל. והרב המגיד ז\"ל כתב ע\"ד הראב\"ד ז\"ל, וכבר כתבתי בזה פ\"ג ה\"ג, ונתתי טעם לדברי רבינו, שסבור דההיא דרב ששת לאו הלכתא, שהיוצא מן הטמא טמא, הוא מגופיה דטמא הוא דוקא, וכ\"ד קצת מן המפרשים ז\"ל. וע\"ש מה שתמה בסתירת דברי הרמב\"ן ז\"ל שאסר מי רגלי חמור והתיר עור שבא נגד פניו. ע\"ש.","b":false},{"t":"ואני תמה בדברי הרמב\"ם ז\"ל למה צריך לומר כפרש ומי רגלים שהן מותרים, דמשמע דהיתר המי רגלים הוא משום דהוי פירשא בעלמא, וכמו קיבת הנבלה וקיבת הטמא, שכתב שם בהי\"ט דמותרת מפני שהיא כשאר הטינופת שבגוף. עכ\"ל. והרי בגמרא אמרו שמי רגלי החמור מותרים דלא מתמצה מגופו, ודינם כדבש לרבנן. והרמב\"ם ז\"ל פסק כרבנן ולא כר' יעקב.","b":false},{"t":"ועוד קשה לי על מה דנים בגמרא, והרי מי רגלים עוברים דרכי העיכול, ובמה עדיפים הם מקיבה של טמאה דחשיב כשאר טנופת ושרי, ומה צריך לתלות במתמצה מגופו או לא. ומתחילה חשבתי דשאני מי רגלים שאינם עוברים דרך הקיבה כאוכלים, אך הנה בדברי הרמב\"ם ז\"ל משווה להו לפרש.","b":false},{"t":"וראיתי בביאור הגר\"א (בהשמטות הרמב\"ם פרנקל עמוד שצ\"א, פ\"ד ה\"כ), שכתב ומי רגלים שהן מותרים, שסובר דרב ששת לאו הלכתא הוא, כיון דפירשא הוא מותר, כמו פרש שור הנסקל (לקמן הכ\"ב), וכמו חלב הקיבה של נבלה בספ\"ק דחולין, כמ\"ש הריק\"ס שם (לעיל הי\"ט), ועור החמור שם. (ליקוט). [בשו\"ע ומ\"ר אסורין] פסק כל\"ב דרב ששת שם, דהגאונים פסקו בכ\"מ כל\"ב. ובשל תורה הילך אחר המחמיר, הרא\"ש שם. [בשו\"ע ויש מי שמתיר] הוא הרמב\"ם, וס\"ל ג\"כ דהסוגיא והלכתא בכ\"מ כל\"ב, ומדחזינן סתמא במתני' דבש צירעין טהור במס' מכשירין דלא כר' יעקב ורב ששת ס\"ל כר' יעקב, ע\"כ אין הלכה כרב ששת. וע\"ל ס\"ט. [פ\"ג ה\"ג], ואע\"ג דללישנא קמא דרב ששת אתי אפילו כמתני' דלא כר' יעקב, מ\"מ אזיל לשיטתיה כנ\"ל דל\"ב בכ\"מ עיקר. והמרדכי כתב דמ\"ר דחמור אסורין ושל שאר מותרין אפילו לל\"ב, וה\"פ של סוסים וגמלים כיון דלא שתו אינשי ודאי פירשא בעלמא הוא ומותרין, כי תיבעי וכו' (ע\"כ). עכ\"ל הגר\"א.","b":false},{"t":"ד.","b":false},{"t":"מהו דבש מלכות ואם הוא דומה לדבש דבורים.","b":true},{"t":"ומעתה נבא לדון בדבש מלכות, אשר למעשה הוא שונה לגמרי מן הדבש, ואינו דבש, שהדבש לא מתמצה מגופן של הדבורים, רק נאסף בפיהם ויוצא כמו שהוא, אבל דבש מלכות, המדענים אומרים שהוא יוצא מאחת הבלוטות שלהן, וא\"כ זה מתמצית גופן הוא, ועוד דהוא מר מאד, וכדי שיהיה ראוי לאכילה, מערבין מעט מהאוכל הזה עם דבש רב מאד, ויש בו סגולות רפואיות רבות ועצומות, ודנו בו גדולי זמננו אם נכלל בכלל היתר הדבש, או לא.","b":false},{"t":"ואביא כאן מה שכתב בזה הגאון הישיש כמוהר\"ר אליעזר יהודה וואלדנברג (שליט\"א) בציץ אליעזר חי\"א (סימן נ\"ט), וכתב דלתנא קמא שמתיר הדבש של הדבורים משום שאינו מתמצה מגופן, דבש מלכות אסור, שהרי הוא מתמצית גופן. אבל לרבי יעקב דהתורה התירה הדבש בגזרת הכתוב, גם זה מותר. ורב ששת סבר כרבי יעקב, וע\"כ אסר מי רגלי החמור, אע\"פ שאינו מתמצית גופו של החמור, דהתורה התירה דבש בגזרת הכתוב, אבל בלי זה היינו אוסרים אותו, אע\"פ שאינו מתמצה מגופו, וע\"כ מי רגלים אסור, דדבש התירה תורה, ולא מי רגלים. וכתב דלר' יעקב גם דבש מלכות מותר דהוא בכלל הדבש שהתירה תורה בגזרת הכתוב. ע\"ש.","b":false},{"t":"ואחר המחילה מהדר\"ג יש שתי תשובות לדון בענין, הראשונה היא די\"ל דרק דבש סתם התירה תורה, והוא דבש דבורים, שאין לו שם לווי, משא\"כ דבש מלכות שיש לו שם לווי, דאינו נקרא דבש סתם, וכבר אמרו בברייתא שבגמרא שם, יכול גם דבש הגזין והצרעין (בכלל ההיתר הנלמד מהפסוק), אמרת לא, ומה ראית לרבות דבש דבורים ולהוציא הגזין והצרעין, מרבה אני דבש דבורים שאין לו שם לווי, ומוציא אני דבש הגזין והצרעין שיש לו שם לווי. ע\"כ. וכאן זה גרע יותר דאין שמו דבש כלל רק \"מזון מלכות\", ובלע\"ז נמי יש לו שמות שונים.","b":false},{"t":"ועוד דהדבר המיוחד ביותר בדבש הוא המתיקות שלו, וכשרוצים לתאר דבר מתוק, אומרים כמו דבש, ויש נוסחא בברכות של ליל ראש השנה שאומרים שתהיה שנה טובה ומתוקה כדבש, וכל דבר רך וטוב נקרא בהשאלה דבש, וכמ\"ש במשלי דבש מצאת אכלת דייך. ודי בזה. והמזון הזה של המלכות הוא מר כלענה, כידוע, ולא נאה לו שם דבש כלל ועיקר. ורק מפני שרגילים לערבו עם כמות דבש גדולה, ע\"כ נקרא שמו דבש, ע\"ש הדבש האמיתי שהוא מרובה עליו בעשרות מונים, אבל איהו גופיה לא שייך לשם דבש כלל, ואיך אפשר לומר שהוא כלול בהיתר שלמד ר' יעקב מהפסוק להתירו בגזרת הכתוב.","b":false},{"t":"זאת ועוד אחרת, די\"ל דגם לר' יעקב שהתיר הדבש, הוא מגזרת הכתוב, מ\"מ אין להתיר אלא דבש שאינו מתמצית גופם של הדבורים, אבל זה שהוא מתמצית גופן ממש, י\"ל דאסור לכולי עלמא, דר' יעקב בא להחמיר ולא להקל, דת\"ק שהתיר מטעם שאינו מגופן ממש, מתיר גם דבש צרעין וגזין, וכן מתיר מ\"ר של חמור, ור' יעקב אמר שזה שאינו מגופן אין בו די להתיר, אלא בעינן שהתורה תתיר וע\"כ רק דבש דבורים לחודיה הוא דשרי לר' יעקב, שזה נלמד מהפסוק דאך את זה לא תאכלו וכו', וע\"כ אפילו שדבש גזין וצרעין גם הוא אינו מתמצית גופן מ\"מ אינו נכלל בהיתר זה, אבל על דבר שהוא מתמצה מגוף טמא ע\"ז לא דנו כלל ולכו\"ע אסור. תדע שבכל הדיון בגמ' לא דנו על דבר שהוא מתמצה מגופן כלל, אלא רק על דברים שהן לא מתמצית גופן, שהרי הקשו על רב ששת מדברי ת\"ק דההיתר של הדבש הוא מפני שאינו מתמצה מגופן של הדבורים, ומקשו עליו על מה שאסר מ\"ר של חמור גם לצד שהם לא מתמצים מגופו, רק מיא עול מיא נפיק, ואמר להו תניתוה היוצא מן הטמא טמא. וע\"ז תירצו, הוא דאמר כרבי יעקב וכו', כלומר דר' יעקב ות\"ק נחלקו רק בדברים שאין מתמצין מגופן. ואע\"ג דאפ\"ל דהביא רק אלה, משום ת\"ק דתלה כל ההיתר רק בזה דאינו מתמצה מגופן, וע\"כ א\"א להביא דוגמא שכן מתמצה מגופן דלת\"ק הוא אסור לגמרי, אבל לר' יעקב י\"ל דגם בזה הוא מתיר, אך זה אינו, דלא מצאנו שיתיר בדבר שמתמצה מגופו. ועוד דר' יעקב אינו מתיר כי אם בדבש של דבורים בלבד, והוא ודאי לא מתמצה מגופן, ואדרבה דבש צרעין וגזין הוא אוסר, אע\"ג דלא מתמצה מגופן, אבל דבר המתמצה מגופן ודאי דלא מתיר, ואפילו שהוא מגופן של דבורים דהרי לא התיר כל היוצא מן הדבורים אלא רק דבש דבורים בלבד, ובפירוש אמר דרק דבש דבורים שאין לו שם לווי הוא שהתיר, ותו לא מידי.","b":false},{"t":"ובפרט דכאמור אין זה דבש כלל, ואין שום דרך להתירו לפי ר' יעקב, וגם לרבנן אין לו היתר, דהוא כן מתמצה מגופן של הדבורים, והו\"ל שפיר היוצא מן הטמא ואסור.","b":false},{"t":"וע\"ש שדן בפסק ההלכה בפלוגתא דת\"ק ורבי יעקב, והזכיר מחלוקת הראשונים בזה, וכבר הארכתי בזה לעיל. ע\"ש. והזכיר דמרן ז\"ל בשו\"ע יו\"ד (סימן פא), סתם כדעת הרמב\"ם ז\"ל, וכתב דיש מי שאוסר, והגאון המחבר זצ\"ל, דן בהא דקי\"ל כסתמא דמרן, וכתב לפקפק בזה די\"א שאין לפסוק כן. אך בזה אין צריך להאריך, שכבר פשטה הוראה בכל מקום כסתמא דמרן ז\"ל.","b":false},{"t":"עוד כתב שם דיש סתמא אחרת כנגד זה, דבסימן פ\"א ס\"א, פסק בסתם דמי רגלי בהמה טמאה אסורים כבשרה, ויש מי שמתיר במי רגליה. ע\"כ. והרי אין מי רגלי בהמה טמאה אסורים אלא לרב ששת והוא סבר כרבי יעקב, וסתם כדבריו, והביא דעת הרמב\"ם ז\"ל בשם ויש מי שמתיר. ומזה מוכיח הגאון ציץ אליעזר דהעיקר כר' יעקב וכשיטת הרא\"ש והרמב\"ן ז\"ל.","b":false},{"t":"ולענ\"ד אין זה מוכרח, דהא עיקר הנ\"מ בן ת\"ק לר' יעקב הוא בדבש צרעין, שזה מפורש בהדיא בברייתא דלר' יעקב אסור, ולת\"ק גם דבש גזין וצרעין מותר. ובזה סתם מרן להתיר כת\"ק. ומה שסתם במי רגלי בהמה טמאה לאסור אינו סותר לההיא סתמא, ולא כהבנת הגאון ציץ אליעזר זצ\"ל. אלא המעיין בדברי מרן ז\"ל בב\"י (בסי' פ\"א), יראה דרוח אחרת עמו בזה, שהביא הסוגיא דגמ' דבכורות (ז ע\"א), הנ\"ל, וכתב ומשמע דללישנא בתרא בכל מי רגלים דטמאה קא מיבעיא ליה, אלא דנקט מי רגלי חמור משום דאורחא דאינשי למשתי (דמעלו לירקונא), וכיון דפשט להו לאיסורא, שמעינן דכל מי רגלי טמאה אסורין. ונראה מדברי הרא\"ש ז\"ל שם דהלכתא כלישנא בתרא להחמיר בשל תורה, אבל הרמב\"ם כתב בפ\"ד מהמ\"א עור הבא כנגד פניו של חמור מותר באכילה מפני שהוא כמו הפרש והמי רגלים שהם מותרים. נראה שהוא פוסק דאפילו מי רגלים דחמור מותרים. וזה תימה, דאפילו את\"ל דסבר דלית הלכתא כלישנא בתרא דמחמיר, היינו להתיר מ\"ר דסוסים וגמלים, אבל מ\"ר דחמור דללישנא קמא נמי אסירי, איך יתכן להתירם. וה\"ה ז\"ל נדחק (בפ\"ג ה\"ג), כדי לתרץ זה. עכ\"ל ב\"י.","b":false},{"t":"והמעיין בדברי הב\"י, יראה דמפרש בסוגיא דאיסור מי רגלי בהמה טמאה אינו תלוי בהילכתא דת\"ק ור' יעקב, אלא לכו\"ע אסורים. דפתר לה מדתנן, היוצא מן הטמא, ולא אמר מהטמא. ועיין לעיל בשם רש\"י ז\"ל על זה. ואע\"ג דהקשו על רב ששת מדברי ת\"ק, ותירצו דהוא סבר כרבי יעקב. היינו משום דהבינו בדרב ששת שמתיר גם לצד דמי רגלי בהמה לא מימצו מגופה, דהוי כדבש דבורים ולת\"ק היו צריכים להתיר, ע\"ז אמר דהוא סבר כרבי יעקב. אבל באמת הסתפקו בזה, דאמרו כי מיבעיא להו דחמור, דעכירי ודמו לחלב מאי, מגופיה קא מיתמצי ואסירי, אי דילמא מיא עול ומיא נפיק. ואמר להו רב ששת, תניתוה היוצא מן הטמא טמא. וממילא גם ללישנא בתרא הוא כן, והחילוק ביניהם הוא דללישנא קמא מבעיא להו רק בחמורים, ולא בסוסים וגמלים דהנהו פשיטא להו דלאו מגופייהו מימצו דהא אינן עכורים. אבל ללישנא בתרא בכולם מבעיא ליה, אלא דנקט מ\"ר חמור דדרך לשתותם משום ירקון, אבל הספק אם מ\"ר הוא מתמצית גופו או לאו, נשאר בעינו גם ללישנא בתרא, ורב ששת אסר בכל גונא, דדייק לה ממתני' דקתני היוצא מן הטמא ולא מהטמא, לרבות גם מה שאינן מתמצית הגוף, וע\"ז אמרו דהוא סובר כרבי יעקב. אבל אה\"נ דגם לדידן דפסקנו כת\"ק נמי מ\"ר אלו אסורים, מחשש דשמא מגופן דבהמות טמאות הוא מתמצה.","b":false},{"t":"ואם כנים דברים אלו, אולי יובן בזה מ\"ש הרמב\"ם ז\"ל בהמ\"א (פ\"ד ה\"כ), שהזכרתי לעיל, שתלה ההיתר דמי רגלי בהמה טמאה, בכך שהם פירשא בעלמא, והערתי לעיל למה צריך לזה. והרי הוא ז\"ל פסק כת\"ק דההיתר של הדבש לא צריך לגזרת הכתוב, רק תלוי בזה שלא מתמצה מן הגוף, ומ\"ר נמי לא מתמצא מן הגוף, וא\"כ אפילו אם לא היו המ\"ר פרש הם מותרים. ולהנ\"ל אתי שפיר, דאם באמת יש חשש שגם מ\"ר מתמצה מן הגוף אזי יש לאסור המ\"ר גם לשיטת ת\"ק. וכך היה לנו לומר. וי\"ל דע\"כ שיכל הרמב\"ם ז\"ל את ידיו ושינה טעמו של דבר, ותלה ההיתר דמ\"ר בכך שהם פירשא בעלמא, דעפי\"ז מותר גם אם הם מתמצים מן הגוף.","b":false},{"t":"ובזה נדחים דברי הגאון ציץ אליעזר זצ\"ל, שכתב שיש סתירה בדברי מרן דבדין דבש צרעין סתם כת\"ק, ובדין מ\"ר של בהמה טמאה סתם כר' יעקב, ועפי\"ז רצה להסיק דהלכה כר' יעקב, ולפי מה שכתבתי אינו כן דבאמת ההלכה ברורה היא כת\"ק, ומה שסתם לאסור מי רגלי בהמה טמאה, הוא מטעם אחר דלא ברור לנו שאינן מתמצין מגוף הבהמה וכנ\"ל. והכל על מקומו בשלום.","b":false},{"t":"ה.","b":false},{"t":"בדעת מרן השו\"ע בענינים הנ\"ל.","b":true},{"t":"ועדיין צ\"ע למה פסק מרן ז\"ל לאסור והלא הוא פירשא בעלמא, ואפשר שחשש לזה שרגילים לשתות מפני הירקון, אולי מיקרי ראוי לשתיה. ועפ\"י האמור י\"ל דגם אם העיקר לאסור בדבש של גזין וצרעין, כפי שהעלה הציץ אליעזר, וכתב שם שכן היא מסקנת הפר\"ח (סימן פ\"א ס\"ק כ\"ח), דהעיקר בזה כהרא\"ש והרמב\"ן ז\"ל (וכבר כתבתי שדעת מרן ברורה שפסק כר\"ח ור\"ת והרמב\"ן ז\"ל, עכ\"פ אין שום מקום להתיר דבש המלכות, עפ\"י היתר זה, דגם לר' יעקב אין מזון זה נכלל בהיתר הדבש וכנ\"ל, ולא כמש\"כ בציץ אליעזר).","b":false},{"t":"וגם דר' יעקב לא בא להקל אלא להחמיר ולומר שגם דברים שאינן מתמצית הגוף הטמא, כדבש צרעין ג\"כ אסור, משום דיש לדבש שלהם שם לווי ולא נכללו בהיתר של גזרת הכתוב, ולא בא להתיר דבר שמתמצה מהגוף הטמא, כמו מזון מלכות. תדע שגם רב ששת דסבר לה כר' יעקב, וע\"כ אסר מ\"ר של חמור, שאינו בכלל גזה\"כ, ולא נחית לדון עליו אלא משום שיש צד שאין המי רגלים מתמצים מגופו, ועל צד זה דנו אם להתיר, ורב ששת אסר גם לצד זה, משום שהדבש הותר ע\"י גזה\"כ, וזה לא נכלל בגזה\"כ, וק\"ו במזון מלכות שגם יש לו שם לווי, וגם מתמצה מגוף הדבורה, והוא אינו דבש כלל וכמ\"ש לעיל.","b":false},{"t":"שו\"ר שהרב ציץ אליעזר גופיה שב לדון בדעת מרן והרמ\"א ז\"ל (באות ד' שם), שאפשר לפרשם כמו שפירש ה\"ה ז\"ל בדעת הרמב\"ם ז\"ל, וכמ\"ש הפרי מגדים במשבצות זהב שם (סק\"א), והאריך לדחות דברי הפמ\"ג בפלפול גדול. ע\"ש. והאמת יורה דרכו.","b":false},{"t":"עוד כתב בציץ אליעזר שם (אות ו), שגם אם נתפוס שאין הכרעה בשו\"ע בדין זה, כיון שמצאנו כ\"כ הרבה פוסקים שסוברים שהיתר הדבש הוא מגזרת הכתוב, ולא משום שאינו מתמצה מגופו, יוצא לפ\"ז דמזון מלכות מותר וכו', עכ\"ד. וכבר ביארתי באה\"ט דאדרבה י\"ל דמזון לכו\"ע אינו בכלל ההיתר של הדבש בין לת\"ק ובין לרבי יהודה. עוד כתב שם דאפשר שגם החולקים יודו בחולה שאין בו סכנה דמותר בו, ובכלל זה גם תשות כוחו וחוסר אונים. ע\"ש.","b":false},{"t":"ו.","b":false},{"t":"\"שם לווי\" מה הוא.","b":true},{"t":"עוד ראיתי להציץ אליעזר שם (מאות ז' ואילך), שדן בפירוש המושג \"שם לווי\", מה הוא. ונפלאתי שלא העלה בדעתו לדון בענין שכתבתי, דגזה\"כ לא התירה אלא מה שלא מתמצה מגופן.","b":false},{"t":"ובאות י' שם הביא תוספתא (פ\"א דבכורות ה\"ה), שדבש גיזין אינו אלא ריר בעלמא, ויש מי שרצה לומר שגם מזון מלכות הוא ריר ולא דבש, ואינו בכלל ההיתר. וכתב בזה\"ל, \"איך יכולים להעלות בדעת לקרוא למזון המובחר של הדבורים לדידהו, בשם ריר בלבד, הא אצלם בתאי דונג, להיותו מזון מיוחד לפרנס בו הזחל המיועד להיות מלכת הדבורים\" וכו'. עכ\"ל.","b":false},{"t":"והנה מלבד מה שיש לומר דלא לפי חשיבות הדבר אצל הדבורים נקבע חשיבותו אם הוא ראוי וחשוב אוכל או ריר בעלמא, אלא אם ראוי וחשוב אצל בני אדם, ואמנם יש דרגה שניה והוא ענין שראוי לאכילת כלב, או לא ראוי. וגם זה הוא באכילה, ודבר שהוא מר כלענה אינו ראוי גם לכלב, ומה שהזחלים ניזונים ממנו, אין זה נחשב לאכילה, שאין זה דרך אכילה, ואפשר שלא רק בזחלים לא נחשב דרך אכילה, דהנה הדבורים והזבובים אוכלים מכל המזדמן להם, גם מדברים שפסולים לאכילת כלב, שלא בכדי אמרו חז\"ל אכילת כלב, שהוא אוכל ושותה כדרך האכילה והשתיה אצל בנ\"א, רק שהוא אוכל גם מה שאין בנ\"א מסוגלים לאכול (וכמ\"ש בכלב שב על קיאו), אבל הזבובים והדבורים אכילתם במושגים אחרים לגמרי, ואין ללמוד מזה על חשיבות החומר שממנו הם אוכלים, וק\"ו לזחלים. ואולם, חומר זה חשוב הוא שמגדל את הזחל שאוכל אותו, ומחזקו מאוד יותר מחבריו בעשרות מונים, וכן נמי יש בו רפואות וסגולות להנאתן ורווחתן של בני אדם, אך אין זה קשור עם חשיבות שיקרא ראוי לאכילה וכיוצ\"ב.","b":false},{"t":"ועוד דכבר כתבתי דעל כל פנים אינו דבש כלל, ולא נכלל עם ההיתר של הדבש, בין לת\"ק ובין לר' יעקב, לת\"ק לא הותר כי זה מתמצה מגופן, ולר' יעקב פשיטא שאין לזה היתר מכוח הגזה\"כ.","b":false},{"t":"ז.","b":false},{"t":"יש מקום להתיר דבש מלכות, משום שהוא מר ולא ראוי לאכילה.","b":true},{"t":"ואולם למרות שלפי עניות דעתי אין מקום להתיר מזון מלכות, ולהחשיבו כמו דבש, אלא י\"ל דבאמת חל עליו הכלל דהיוצא מן הטמא. ודלא כהרב ציץ אליעזר זצ\"ל. עכ\"פ יש לדון להתירו מצד שאינו ראוי לאכילה כלל, שהוא מר כלענה, וגם לא נוצר לשם אכילה.","b":false},{"t":"וראיתי לו להציץ אליעזר שגם הוא פנה לדרך זו, שכתב שם (אות י\"ד), דכיון שהוא עצמו מר כלענה, ואינו ראוי לאכילה, רק ע\"י תערובת של הרבה דבש, פי שלושים ושבע ויותר מכמות מזון המלכות. ודבר שטעמו פגום אינו אוסר תערובתו ובטל ברוב היתר, כמ\"ש ביו\"ד (סימן ק\"ג). ואעפ\"י שהוא המעמיד שיתהווה הכל אף התועלת המקווה, הנה הפר\"ח (בסימן פ\"א סק\"א), כתב דגם המעמיד לא נאסר בדבר שנסרח ומותר להעמיד בו גבינה. עוד כתב, דכיון דמיסודו הוא מר כלענה מסתבר שאין בזה משום מבטל איסור לכתחילה, דמעיקרא הוא פגום.","b":false},{"t":"ולהלן (באות ט\"ו), כתב דאע\"ג דהדבש שמערבים בו, ממתיק את המר הזה, יש להתירו, והביא את דעת החוות דעת בזה. ע\"ש. עוד כתב (באות ט\"ז), לחזק את הנ\"ל, והקשה למה הגמרא לא הזכירה מזון מלכות כלל, ובע\"כ דהיה פשוט לחז\"ל שהוא פירשא דעלמא, דמצד עצמו אינו ראוי לשום דבר, ואפילו לרפואה, וע\"כ לא חל עליו שם איסור דמעיקרא. ע\"ש.","b":false},{"t":"ובמחילת כבוד תורתו, אי משום הא לא איריא, דבפשטות נראה דלא דנו עליו כיון שאינו בר אכילה ולא נשאל עליו אדם מעולם, ואין מזה הכרח שהחשיבוהו פירשא בעלמא.","b":false},{"t":"והנלע\"ד בזה דבאמת יש לו דין פירשא בעלמא, דכל דבר שעבר בדרכי העיכול כבר יצא מענינו הראשון ופנים חדשות באו לכאן. ומצאנו בחולין (קט\"ז ע\"א): \"והלכתא אין מעמידין [גבינה] בעור קיבת נבלה, אבל מעמידין בקיבת נבלה, ובקיבת כשרה שינקה מטרפה, וכ\"ש בקיבת טרפה שינקה מן הכשרה. מאי טעמא, חלב המוכנס בה פירשא בעלמא הוא\". ואע\"ג דהתוספות שם כתבו בשם ר\"ת דלא התירו אלא בחלב שנקפה, אבל אם עדיין צלול אסור, מ\"מ דעת הרי\"ף והגאונים דגם צלול מותר. וכך הם דברי הרמב\"ם ז\"ל (פ\"ט מהמ\"א הט\"ו), וז\"ל: \"קיבה שבשלה בחלב שבה, מותרת, שאינו חלב, אלא הרי הוא כטנופת, שהרי ישתנה במעיים\". עכ\"ל. ומדכתב, בחלב שבה, משמע אפילו שיש לו מראה חלב. וכ\"כ הרדב\"ז ז\"ל שם בשם הגאונים, ודלא כר\"ת. וכ\"כ ה\"ה ז\"ל (בפ\"ד מהמ\"א הי\"ט). וכ\"כ מרן ז\"ל בכסף משנה שם, שכן נראה דעת הרמב\"ם (בפ\"ד הי\"ט). וע\"ש. והארכתי בכל זה בשו\"ת שמע שלמה ח\"ה (חיו\"ד סימן י\"ב). ע\"ש. וכ\"כ להוכיח שם ממ\"ש במסכת ע\"ז (כ\"ט ע\"ב), קיבת עולה, כהן שדעתו יפה שורפה חיה. ובודאי דבראויה לאכילה מיירי, אלא שכהן שהוא איסטניס לא יכול לאוכלה כשנמצאה בקיבה, וע\"ז כהן שדעתו יפה, שאינו איסטניס, שורפה יפה. אבל כשנתקלקלה אפילו שדעתו יפה לא יוכל לאוכלה. וכתבתי שם שגם לר\"ת אינו אסור אלא מדרבנן, ומשום מראית העין. ועוד דאם הגיע למצב שאינו ראוי לכלב יודה להתיר.","b":false},{"t":"עוד כתב הרמב\"ם (פ\"ב מהמ\"א הכ\"א), \"אבל האוכל בריה טמאה בפני עצמה כולה, הרי זה לוקה מן התורה, ואפילו היתה פחותה מן החרדל, בין שאכלה מתה ובין שאכלה חיה, ואפילו סרחה הבריה ונשתנית צורתה, הואיל ואכלה כולה לוקה\". עכ\"ל. וכתב הרב המגיד ז\"ל שם, בשלא סרחה והבאישה עד כדי שלא תהא ראויה לאדם, אבל אם סרחה כ\"כ, כבר ביאר רבינו בפי\"ד (הי\"א), שמי שאכל אוכל האסור שהסריח והבאיש ובטל מאוכל אדם הרי זה פטור, וכן הוא, דהלכה כרבי שמעון במס' עבודה זרה (ס\"ח ע\"א), דאמר נבלה שאיה\"נ ראויה לגר, לא שמה נבלה וכמ\"ש שם. עכ\"ל.","b":false},{"t":"ובתשובה ההיא כתבתי, דרק בנפסל מאכילת אדם הוא דכתב הרמב\"ם ז\"ל פטור, דמשמע דאיסורא דרבנן מיהא איכא, אבל נסרחה הרבה עד שאינה ראויה גם לאכילת כלב, אין בו איסור כלל, ואפילו דרבנן, דבטל ממנו שם אוכל לגמרי. וע\"ש שהבאתי הוכחות לזה. ע\"ש.","b":false},{"t":"ועיין בב\"י (רס\"י ק\"ג), ובט\"ז שם (סק\"א), דנותן טעם לפגם אינו אוסר תערובתו, והוא עצמו אסור, אך א\"צ ששים כנגדו. והנה המזון הזה שהוא מר כלענה, ואינו ראוי אפילו לאכילת כלב, דגם כלב אינו אוכל דבר מר כ\"כ. וגם שאינו עשוי למאכל כלל, רק שמצאו בו סגולות ורפואות חשובות, וע\"כ חיפשו ומצאו דרך ליהנות ממנו ע\"י שמערבים בכמות גדולה של דבש, עד שמבטלים מרירותו לגמרי, וכל כונתם לאוכלו כתרופה להתרפאות ולהתחזק בו. ואפשר דזה מותר גם כשהוא רוצה לאוכלו כמו שהוא. וק\"ו כשהוא מעורב ברוב היתר, דהא כמו שהוא אינו ראוי אפילו לאכילת כלב, ויצא לגמרי מכלל אוכל, ותו אין בו איסור כלל.","b":false},{"t":"ח.","b":false},{"t":"בדברי המנחת שלמה בענין דבש מלכות.","b":true},{"t":"וחתני כבני הרה\"ג רי\"מ נר\"ו הראני מ\"ש בזה הגאון המופלא מוהרש\"ז אוירבך זצ\"ל בשו\"ת מנחת שלמה ח\"ב (סימן ס\"ד תשובה ג'), והיא תשובה לבעל ציץ אליעזר, להעיר לו על התשובה הנזכרת, ותמה עליו על שהוכיח ממה שלא דיברו חז\"ל על דבש מלכות, די\"ל דכיון שהוא מר כלענה ואינו מאכל כלל וע\"כ לא שייך לדבר בזה, ולמה יזכירוהו, ומהיכי תיתי לומר דאינו חלוק מכל היוצא מן הטמא דאסור. עכ\"ל. ובעוניי כתבתי כדברים הללו לעיל.","b":false},{"t":"עוד כתב שם שעד לפני מספר שנים היה מורה בזה להתיר, דהיוצא מן הטמא שאינו ראוי לאכילה מתחילתו דינו כנבלה סרוחה מעיקרא, ולא חייל שם איסור כלל. אך כאשר התבוננתי שגם היוצא מן האוזן ומן החוטם, ועוד דברים מאוסים כאלה, דינם כמים ומכשירים, וחשיבי כמשקין הראויים לאדם לשתיה, כמבואר במסכת מכשירין וברמב\"ם (פ\"י מהלכות טומאת אוכלין ה\"ב), ואפשר שגם זה [מזון מלכות] חשוב כראוי למאכל לאדם, וגם מר שיחיה אמר לי שלדעתו זה ראוי לאכילה, ולכן מאז איני אומר בזה לא לאיסור ולא להיתר. עכ\"ל.","b":false},{"t":"וע\"ש עוד תשובה להגרש\"ז אוירבך ז\"ל בזה, שהשיב ע\"ד הגרא\"י וולדנברג (שליט\"א) (שנדפסה בחי\"ב סימן ד\"ן, ואינו תח\"י). ובאות ב' חזר לבאר דברו, דכיון דהיוצא מן החוטם והאוזן הו\"ל תולדות מים להכשיר (לטומאה), והרמב\"ם ז\"ל גופיה (בפ\"ב מהלכות טומאת אוכלים הי\"ד), פסק דמשקה שנפסד ואינו ראוי לשתית אדם, אינו מקבל טומאה אינו מכשיר, דכתיב \"אשר ישתה\", בע\"כ צ\"ל דמי האזן חשיבי ראויים לשתית אדם, והתינח מי רגלים של אדם ושל חמור י\"ל דזה רק בגלל המיאוס. ואפשר דשפיר חזי לשתיה מי שאינו יודע ממיאוסם, אבל בשל אוזן וחוטם לא הבינותי. עכ\"ל. וע\"ע שם תשובה נוספת מזה, וחזר על הנ\"ל, ובסופו העלה להתיר [מזון מלכות] לחולה שאין בו סכנה. ע\"ש.","b":false},{"t":"ואחר המחילה רבה מהדר\"ג רבינו המנחת שלמה ע\"ה, בדלותי נראה שהעיקר כמשנתו הראשונה, שהיה מתיר מזון מלכות משום שאינו ראוי לאכילה כלל. דמפורש בגמרא ובפוסקים דנבלה סרוחה לא אוסרת דבענין ראויה לגר. וכמ\"ש במסכת ע\"ז (ס\"ח ע\"א), דתניא לא תאכלו כל נבלה לגר אשר בשעריך וגו', כל הראויה לגר קרויה נבלה, שאין ראויה לגר אינה קרויה נבלה. (ופירש\"י שהסריחה, אלמא מדאפגים בטל איסורה. ע\"כ). ור\"מ ממעט רק סרוחה מעיקרא. (ופירש\"י מוכת שחין מחיים, דאיפגמא קודם שבאה לידי נבלה, לא חל שם נבלה עלה, אבל היכא דאיתסר מעיקרא, שוב לא פקע איסור משום פגם). ורבי שמעון אומר סרוחה מעיקרא לא צריך קרא עפרא בעלמא הוא, והפסוק בא למעט נתנבלה ואחר כך נסרחה.","b":false},{"t":"ט.","b":false},{"t":"במחלוקת רבי מאיר ורבי שמעון הלכה כמי.","b":true},{"t":"ובתשובה בשמע שלמה (ח\"ה סימן י\"ב), הבאתי דעת הנוב\"י (חיו\"ד סימן כ\"ו), שכ' דאין לנו הכרעה בפלוגתא דר\"מ ור\"ש הלכה כדברי מי, דהיא בעיא דלא איפשיטא בערובין (מ\"ו ע\"ב). ואולם במבוא התלמוד כתוב דר\"מ ור\"ש הלכה כר\"ש, והוא נגד סוגיא דערובין הנזכרת. אולם בהליכות עולם כתב דר\"מ ור\"ש הלכה כהמחמיר. ולפ\"ז ראוי לפסוק בנבלה סרוחה כר\"מ, דלא התיר אלא בסרוחה מעיקרא. עכת\"ד הנוב\"י.","b":false},{"t":"והבאתי שם דברי החיד\"א (שזימן ה' לידי באותו יום), בספרו עין זוכר (מערכת ר' או' י\"א דקכ\"ד ע\"א), שכתב בשם ספר הקדוש קנה (דף פ\"ג), דר\"מ ור\"ש הלכה כר\"ש, ושכ\"כ התשב\"ץ למהר\"ם (סימן י\"ח), וכ\"כ במבוא התלמוד לר\"ש הנגיד, וכ\"כ להרא\"ש בפסקיו (פרק אין מעמידין), וכן אמרו בירושלמי דהלכה כר\"ש. וכ\"כ בה\"ג (דף ק\"כ). וכבר האריך בזה ביד מלאכי (אות תק\"ף). וכתב החיד\"א שכבר האריך בזה בברכ\"י אהע\"ז (סימן טו\"ב). ועיין עוד מ\"ש בספרו פתח עיניים ע\"ד עיר וקדיש מהר\"ם די לונזאנו ז\"ל. ותמה על מהר\"ר יחזקאל לנדא נר\"ו בשו\"ת נוב\"י בי\"ד (סימן כ\"ו), שתמה על מבוא התלמוד, ונעלם ממנו אמבוהא דספרי. וע\"ש שם שהאריך בזה.","b":false},{"t":"וגם מרן נר\"ו ביבי\"א ח\"ח (חיו\"ד סימן י\"א), האריך בזה, והביא את הירושלמי שם (פ\"ח ה\"ז), וכן בתרומות (פ\"ח הט\"ו), שכתבו ר\"מ ור\"ש הלכה כר\"ש, ושכן כתב מרן ז\"ל בכסף משנה (פ\"ח מהלכות תרומות הט\"ו), דבתלמוד בבלי לא איפשיטא הך בעיא, אך בירושלמי אפשיטא, ונקטינן כפשיטותא דהירושלמי. [וע\"ש שכתבתי לחזק בזה מה שכבר העלתי כמה פעמים דבמקום דאיכא פלוגתא בבבלי, ובירושלמי פשטוה, נקטינן כהירושלמי. ולזה כיון הגר\"א בדבריו בכמה מקומות, שכתב, שדרך הרמב\"ם לפסוק כהירושלמי נגד הבבלי. עי\"ש]. עוד כתב ביבי\"א שם שכ\"כ הראב\"ד ז\"ל בהלכות טומאת המת (פכ\"ד ה\"ד), דהלכה כר\"ש, וע\"ש שהרחבתי עוד בזה. ועיין ביבי\"א שם. וכאמור כבר עמד מרן החיד\"א ז\"ל, ותמה על הנוב\"י בחיים חיותו, ודחה דבריו, אלא קי\"ל כר\"ש דנבלה שהסריחה גם לאחר שנתנבלה לא שמה נבלה.","b":false},{"t":"עוד כתב כתב שם דלא נחלקו ר\"מ ור\"ש אלא באינה ראויה לגר, שנפסלה מאכילת אדם אבל עדיין נקראת אוכל, כי היא ראויה לכלב, אבל אם נפסלה גם לאכילת כלב, יצאה מכלל אכילה לגמרי ומותרת גם לר\"מ. ופשיטא שגם הנוב\"י יודה בזה, ומבואר בדבריו שם להדיא (בד\"ה ואומר אני), וז\"ל, אבל שלפוחית הנ\"ל של דג טמא הוא, והוא אסור מן התורה, וכבר חל עליו שם איסור ואינו נפקע ממנו ע\"י שנתייבש, עד שיתייבש שלא יהיה ראוי לכלב וכו'. עכ\"ל. וש\"מ דאם הגיע לכך שלא ראוי לכלב הותר לגמרי גם להנוב\"י.","b":false},{"t":"ומזון מלכות גם לכלב אינו ראוי מצד מרירותו הרבה, וגם שהוא פירשא בעלמא, שנתעכל ונעשה כחלק מגופו, והיא הפרשה שפורשת מן הבלוטות שלו. ואפילו חלב של טמאה שנמצא בקיבה של טמאה הותר לגמרי, כי נתעכל. אעפ\"י שעדיין ראוי וטוב הוא, וק\"ו בזה.","b":false},{"t":"י.","b":false},{"t":"ביישוב דעת הרמב\"ם בענין זה.","b":true},{"t":"ומה שקשה לו ברמב\"ם ז\"ל, אעפ\"י שנראים הדברים כמו סותרים זה את זה מפ\"ב לפ\"י, ובאמת צריך ליישב הענין דבר דבור על אופניו, אך לא נוכל לשנות הלכות ברורות וסוגיות שלמות מכוח קושיא זו, ומה גם שאין בכל זה כדי להבין דברי רבינו הרמב\"ם.","b":false},{"t":"ובחסדי ה' מצאתי שכבר עמד על קושיא זו הרב משנה אחרונה, בפ\"ו דמכשירין משנה ה', דבמשנה ד' שם תנן שבעה משקין הן, הטל והמים וכו'. ובמשנה שאחריה תנן תולדות למים היוצאין מן העין מן האוזן מן החוטם מן הפה, מי רגלים בין גדולים בין קטנים, לדעתו ושלא לדעתו. ע\"כ. ובמשנה אחרונה כתב, מכלל דשבעה משקין עצמן הן אבות, כדאמרינן בב\"ק. וכתב הרמב\"ם ז\"ל בפ\"י מהלכות טומאת אוכלין, דתולדות הם כאבות בין להכשיר ובין לטומאה, ומשמע לפי זה דלא קרו להו תולדות, אלא משום שאינן משקים אלא מדברי סופרים. ואולם הני דלעיל (השבעה), הם הלכה למשה מסיני, וכן משמע מדחשיב הכא מי רגלים דהוו משקה. ואנן הא קי\"ל דמשקה סרוח אינו מקבל טומאה, דכתיב אשר ישתה, פרט למשקה סרוח. וכמ\"ש הרמב\"ם ז\"ל (פ\"ב מהלכות טומאת אוכלים הי\"ד). אלא מדאורייתא ממעט למשקה סרוח, והכא מדרבנן איירי. וכן משמע לעיל (פ\"ב מ\"ג), כדפרישית שם וכו'. עכ\"ל. (וע\"ש מה שהקשה ממתניתין דפרה (פ\"ט מ\"ג), ומה שנו\"נ בזה).","b":false},{"t":"נמצאנו למדים שהרב משנה אחרונה כבר עמד על הערת הגרש\"ז אויערבך ז\"ל, דאיך מי אוזן וחוטם מכשירין, והא קי\"ל דמשקה סרוח אינו מקבל טומאה, ומפרש דמן התורה כל אלה לא מכשירים ולא מקבלים טומאה, דבעינן אשר ישתה וליכא, אלא שרבנן גזרו עלייהו טומאה קלה מדבריהם, וע\"ש בסוף דבריו שהסביר למה גזרו עליהם.","b":false},{"t":"ועפי\"ז אין משם ראיה לאסור בדבש מלכות, דבאמת גם מי חוטם ומי אוזן לא חשיבי מים מן התורה, ולא מקבלים טומאה ולא מכשירין, רק רבנן גזרו עלייהו. ואין ללמוד מזה לאיסורי אכילה, דרק בטומאה גזרו חכמים ולא באיסורי אכילה.","b":false},{"t":"ובפרט במזון זה שהוא מר כלענה ואינו ראוי לאכילה כלל, ואפילו לאכילת כלב אינו ראוי, ולא חל עליו שם איסור. (והרי הוא כציפורניים ושער שלא חל עליהם שם איסור כלל). ובכה\"ג לא חל עליו האיסור דהיוצא מן הטמא. ולא עדיף מעור הקיבה שנתייבש והיה כעץ, שפסק בעל שיבולי הלקט דמותר להעמיד בו גבינה, דאין בו טעם בשר כלל, וכ\"פ בשו\"ע יו\"ד (סימן פ\"ז), ואעפ\"י שעדיין יש בו כוח המעמיד להעמיד גבינות, מאחר ואינו נותן בה טעם בשר, מותר גמור. וה\"נ הרי לא שאינו טעם בו טעם אלא הוא פוגם, כי טעמו מר כלענה. ובודאי דמותר לערבו בדבש הדבורים הרגיל, ואעפ\"י שנותן בו תוספת ויטמינים וכו', אין בכך כלום, דזו תוספת של סגולות ולא תוספת טעם או שבח, אלא רק פוגם ומקלקל. ואין בזה משום דבר המעמיד, דאפילו בעור היבש שמעמיד הגבינה מותר וכנ\"ל. וק\"ו בזה דלא מעמיד מאומה שהדבש עומד ביופיו וטעמו מצד עצמו, ובזה לא מוסיף בו כלום, שתוספת הויטמינים אינה ענין של העמדה כלל. ובפרט שמצד עצמו אינו ראוי לאכילה כלל.","b":false},{"t":"אלא דקשה לי על המשנה אחרונה, דלמה לא כתב הרמב\"ם ז\"ל בפ\"ב הי\"ד דהמים שסרחו עד שאינן ראויים לשתיית אדם דאעפ\"י שמן התורה אינו מטמא ומכשיר, מ\"מ מדרבנן מכשיר לטומאה וגם מקבל טומאה, ואדרבה מסתימת דבריו שם, נראה דמשנפסל מאכילת אדם נטהר לגמרי ותו אינו מכשיר ולא מטמא מה\"ת ולא מדרבנן. ושו\"כ דברי המשנה אחרונה שהתעורר ע\"ז בסוף דבריו שם, וכתב, ומ\"מ צ\"ע דלא אשתמיט בשום דוכתא לאחד מן המחברים לכתוב זה במשקה סרוח, דיש בהם טומאה מד\"ס, וידים שאני דשכיח, דעסקניות הן. עכ\"ל. ובתחילה חשבתי ליישב ולומר, דלא מיירי (בפ\"י מטומאת אוכלין), בצואת האוזן והחוטם וכיו\"ב, דאלו בודאי לא מכשירין, וגם המשקין הקרובים לזה פסולים הם, ולא מכשירים. אלא מיירי במים צלולים שיצאו מן החוטם או מן האוזן ע\"י חולי וכדומה, והוי דומיא דמי העין, ואם לא היינו יודעים מקורם של מים אלו אפשר שלא היו נחשבים למאוסים, שהם צלולים ואין בהם ריח רע או סירחון ואפשר דבכה\"ג הוא דמכשירין לטומאה מה\"ת, או מגזירת חז\"ל כהמשנה אחרונה, ולא דמי למים שהסריחו ונפסדו משתיית אדם.","b":false},{"t":"אלא דכל כה\"ג היה להם לחז\"ל לפרש דבריהם, דמיירי רק בכה\"ג שהם צלולים וזכים וכו'. ועוד דקשה לומר שיש מי אוזן כאלו, וא\"כ הרי הוא דבר שאינו שכיח כלל. ועוד שקשה ממי רגלים, שהם מכלל תולדות המים, ולא מיבעיא לפירוש הר\"ש וסיעתו דפירשו הא דתנן התם מי רגלים בין גדולים בין קטנים, דהיינו שיצאו מבית הרעי, אלא אפילו להרמב\"ם ז\"ל ורוב המפרשים שפירשו דגדולים וקטנים היינו של אנשים גדולים ושל קטנים, והכל הוא מי רגלים, עכ\"פ גם מי\"ר סרוחים הם ופסולים לשתיית אדם, ולמה הם מכשירים. ועוד דאמרו שם שגם זוב הזב וש\"ז ודם נדות מכל המכשירין לטומאה ופשיטא דכל אלו אינן ראויין לאדם .","b":false},{"t":"יא.","b":false},{"t":"מחדש דמשקין מכשירין לטומאה, אעפ\"י שאינם ראויים לשתיה.","b":true},{"t":"והנראה לעניות דעתי, דבאמת במכשירין לטומאה לא בעינן משקה הראוי לשתיה דוקא, אלא כל דבר אשר משקה הוא מכשיר לקבל טומאה, ואפשר דמן התורה בעינן ראוי לשתיה, שהרי למדו שדם מכשיר, מדכתיב ודם חללים ישתה, אך בתולדות ודאי דלא בעינן שיהיה ראוי לשתיה, ואפשר דזה מדרבנן, כמו שכתב הרב בעל משנה אחרונה הנ\"ל (ולמטה בהערה הבאתי איזה חיזוקים לדבריו), ואפשר שהם ג\"כ מן התורה, ולא צריכים להיות ראויים לשתיה. תדע דתנן (מכשירין פ\"ו מ\"ו), אלו מטמאין ומכשירין זובו של זב, ורירו, ושכבת זרעו, וכו', ודם הנידה. וכתב ר\"ע מברטנורה ז\"ל, שהן עצמן משקין טמאין ומטמאים ומכשירים כאחד. ע\"ש. ופשוט שכל אלו אינן ראויים לשתיה כלל, והם מטמאים ומכשירים לטומאה.","b":false},{"t":"וה\"ה והוא הביאור גם בתולדות המים הנ\"ל, דאע\"ג דאינן ראויין לשתיה, עכ\"פ מכשירין לטומאה, (אם מדרבנן או מדאורייתא). אלא שהמשנה אחרונה הבין ממה שאמרו בתורת כהנים (פרשת שמיני פ' ח'), ופסקה הרמב\"ם ז\"ל (פ\"ב מהלכות טומאת אוכלים הי\"ד), [ועי\"ש בכ\"מ הכ\"א, שהביא את התורת כהנים]. ומזה הבינו דאין המשקה מכשיר לטומאה צריך להיות ראוי לשתיית אדם, וכך הבין גם הגרש\"ז אוירבך זצ\"ל, ומשום כך היה קשה להם ממי האוזן והחוטם וכו', שהן מכשירין לטומאה. אבל באמת לא כך הוא המדה, אלא דמים שהן ראויין לשתיית אדם מצד טבעם, בעינן שיהיו ראויים לשתיה, ואם הסריחו והתקלקלו עד שאינן ראויין לשתיית אדם, בזה הם יצאו מכלל מים \"אשר ישתה\", ושוב אינן מכשירין לא מן התורה ולא מדרבנן, דיצאו מכלל מים, כי הגדר של מים שיהיו ראויים לשתיית אדם, ואלה לא ראויים עוד. וע\"כ אינן מטמאין ולא מכשירין. אבל משקין שאינן ראויין לשתיית אדם מלכתחילה, שמתחילת היווצרותם היו מאוסים ולא היו ראויים מעולם לשתיית אדם, כגון: הזב ושכבת זרעו ודם הנידות, וכן מי האוזן והחוטם, כל אלו מעולם לא היו ראויים לשתיית אדם. בזה לא בעינן כלל שיהיו ראויים לשתיית אדם, אלא כך היו מעיקרא, והן משקין המכשירין לטומאה, וכן מי רגלי אדם. תדע שהרמב\"ם ז\"ל גופיה כתב בפ\"ד דינם כפרש ממש, וכנ\"ל, ועם כל זה פסק בהלכות טומאת אוכלים (פ\"י ה\"ב), דמי רגלים בין של גדולים ובין של קטנים, מכשירין לקבל טומאה, והרי זה מבואר דלא בעינן הראויין לאדם. אלא דשם (פ\"ב הי\"ד), מדבר במים ממש, דמעצם טבעם הם ראויים לאדם. בזה הוא דכתב שאם הסריחו עד שאינן ראויין לאדם, אינן מכשירין, דבזה יצאו מכלל מים לגמרי.","b":false},{"t":"וחתני כבני רע\"י יוסף שליט\"א הראני דברי מרן החזו\"א ע\"ה על בכורות (ז' ע\"א, סוף אות י\"ד), שעמד ע\"ד הרמב\"ם (פ\"ד מהמ\"א ה\"כ), דהשווה מי רגלים לפרש, וכתב ומשמע דמי רגלים מותר משום פרש, וזה תמוה דכל הסוגיא אינו בנפסל מאכילת אדם, ותנן (מכשירין פ\"ו מ\"ה), דמי רגלים מכשירין, אלמא דאינן פרש, ואפשר שצ\"ל ומי רגלים שלהם, ור\"ל של חמורים, ויותר יתכן ומ\"ר שלו ור\"ל של חמור שהזכיר, והוא כדעת ר\"ת. עכ\"ל הטהור.","b":false},{"t":"ולענ\"ד מהסוגיא לא קשה מידי, וכמ\"ש לעיל, דבגמרא הסתפקו אם מי רגלים מתמצים מגופו או לא, ומ\"ש דשתו להו אינשי משום ירקונא, אפשר דס\"ל להרמב\"ם ז\"ל דאין זה ראוי לאדם כלל, רק דשתי ליה כאחת הרפואות אע\"ג דאינו ראוי לשתיה. ומ\"ש במכשירין, דמי רגלים מכשירין, וכ\"פ הרמב\"ם ז\"ל וכנ\"ל, גם זה אינו הוכחה דראוי לאדם, אלא ראיה דא\"צ שיהיה ראוי לאדם שיכשיר לטומאה, דהא גם זוב הזב וש\"ז ודם נידות וכן מי החוטם וכו' כולם מכשירין, ולא יעלה על הדעת דראויין הן לאדם, אלא בע\"כ דאע\"ג דאינן ראויים מכשירין, ושאני התם שטבע המים שהם ראויים לשתיית אדם, אלא שאלו התקלקלו ויצאו מגדר מים, ושוב לא מכשירים. והאמת יורה דרכו דאין אדם שיכול לשתות מי רגלים כלל ועיקר. וגם בימיהם היה כן, רק שתו משום ירקון, וכבר כתבתי דגם העובדא שעובר בדרכי העיכול כבר עושה אותו לפירשא. ודי בזה.","b":false},{"t":"ויש לחזק עוד את החילוק הנ\"ל, דהנה הרמב\"ם ז\"ל פסק בהלכות טומאת אוכלין (פ\"ב הכ\"א), כל משקה שנטמאת ואחר שנטמא, נפסד והסריח הרי זה בטומאתו לעולם, שאין המשקה יוצא ע\"י הכלב לעולם. ואין למשקה שנטמא טהרה, חוץ מן מים בלבד, הטביל מים טמאים במקווה וכו'. עכ\"ל. ופירוש הדברים פשוט, דגבי אוכל שנטמא אם נפסד עד שאינו ראוי לכלב נטהר, אבל אם נפסל מלאכול לאדם, ועדיין הוא ראוי לכלב הרי זה טמא כמו שהיה. וזה מפורש בהלכה י\"ח שם, וגבי משקין מחדש דלעולם הן ראויין לכלב, וע\"כ אינן יוצאין מטומאתן אעפ\"י שנפסלו לאכילת אדם, דבזה אינן יוצאים מטומאתן.","b":false},{"t":"נמצא דשייכת טומאה באוכל ומשקה שאינו ראוי לאדם, לפחות לענין שאינו יוצא מטומאתו, אלא שלכתחילה לא מקבל טומאה כשהוא במצב שאינו ראוי לאדם. אבל כשנטמא כבר נשאר בטומאתו, עד שיפסל מאכילת כלב. ובע\"כ שהטעם שלא מקבל טומאה לכתחילה, משום שהמים וכן האוכל הם ראויים לאדם רק שאלו התקלקלו, אך מי רגלים ומי אוזן וחוטם וכיו\"ב, שכך היא בריאתן במאיסות ולא שהתקלקלו והסריחו, בזה הם מקבלים טומאה וגם מכשירין, כל זמן שהן ראויין לכלב, וכשנפסלו מאכילת כלב ג\"כ, אז נטהרו לגמרי, וכמו שכן כתב הרמב\"ם ז\"ל בפ\"ד מאבות הטומאה הי\"ב.","b":false},{"t":"ותנן בטהרות (פ\"ח מ\"ו), כלל אמרו בטהרות, כל המיוחד לאוכל אדם טמא, עד שיפסל מאכילת כלב, וכל שאינו מיוחד לאוכל אדם טהור, עד שייחדנו לאדם. וכתב רבינו עובדיה מברטנורא ז\"ל דיש חילוק בין אפוקי טומאה מיניה ובין לאתויי טומאה עליה. עכ\"ל. וכתב התוי\"ט שם דהיא גמרא בכריתות (כ\"א), ומשמע דבאוכל שכבר נטמא מיירי, והיינו לאפוקי טומאה מיניה, וע\"ש.","b":false},{"t":"ובמשנה אחרונה שם כתב, דגם במשקין איתיה להאי כללא, וכמ\"ש הרמב\"ם ז\"ל בפ\"ב מהלכות טו\"א, וכתב דנחלקו הרמב\"ם והראב\"ד ז\"ל בזה, דהרמב\"ם ז\"ל ס\"ל דבנפסל מאכילת אדם אינו מקבל טומאה, אעפ\"י שעדיין ראוי לאכילת כלב, ולהראב\"ד ז\"ל כל זמן שראוי לאכילת כלב מקבל טומאה. וע\"ש שהאריך בדברי הראשונים.","b":false},{"t":"ובע\"כ צ\"ל דבזה שיצא מגדר בריאתו יצא מכלל טומאה, שאינו מקבל טומאה להרמב\"ם ז\"ל, ואעפ\"י שעדיין לא יצא מגדר מאכל לגמרי, שהרי עדיין הוא ראוי לכלב, מ\"מ נשתנה מטבעו ומעמדו שנברא עמו שהיה ראוי לאדם. ולא מחכים עד שיצא מכלל אוכל לגמרי. אבל כשכבר נטמא בעודו במעמדו, שוב לא נפיק מטומאתו בזה שירד ממעמדו, אלא כ\"ז שיש עליו שם אוכל, דהיינו שהוא עדיין ראוי לכלב, עדיין טומאתו בו כבתחילה, דהשינוי ממעמדו היסודי, מהווה גורם לשנות בדין הטומאה דלא מקבל טומאה. אבל כשכבר נטמא, אין בכוח שינוי זה להוציאו מטומאתו. אלא לזה צריך שינוי גמור, שיצא ממנו שם אוכל, דהיינו כשנפסל מאכילת כלב, דבזה נפסק לגמרי מכלל אוכל.","b":false},{"t":"הכלל העולה: דמזון מלכות מותר לערבו בדבש ולאכלו, גם לבריאים, וק\"ו שבפועל קונים אותו כשהוא מעורב בדבש ונתבטל בו. ואלו שמערבבים אותו עושים כן גם בשביל החולים, ואפילו לערבו לכתחילה בשביל בריא, מותר. זה הנלענ\"ד. וה' יאיר עינינו בתורתו ויצילנו מכל טעות ומכשול. אמן.","b":false},{"t":"המצפה לישועת ה' על עמנו ועל נחלת אבותנו בב\"א.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"בענין הקינואה אם יש בה משום קטניות בפסח","p":[{"t":"בס\"ד, ‏כ\"ג אדר, תשס\"ז","b":false},{"t":"לכבוד ידידי ומכובדי חה\"כ פרופסור מנחם בן ששון הי\"ו, יו\"ר ועדת החוקה בעיה\"ק ירושלים ת\"ו","b":false},{"t":"החיים והשלום.","b":true},{"t":"בדבר שאלתו שאלת חכם, על דבר \"זרעוני הקינוא'ה\" הגדלים בבוליביה, ולפי הצילום שהראוני הם גדלים בעלים הדומים לסלק הלבן, וראיתי שמשייכים אותם למשפחת התרד, וחוקרי הטבע והבריאות, מצאו שהוא מאכל \"בריא ומזין\", וגם נוח וקל לעיכול, והוא עשיר במרכיבים תזונתיים חשובים, עד שנקרא בפיהם בהשאלה \"אם הדגנים\", אעפ\"י שאיננו מין דגן כלל, וכתבו שאינו מכיל גלוטן, וכנראה שגם לכב' השואל המלומד דבר זה פשוט לו, ואשר על כן לא שאל על חשש חמץ, רק זאת שאלתו אם הוא ממיני הקטניות.","b":false},{"t":"א.","b":false},{"t":"מקור ענין החומרא בקטניות.","b":true},{"t":"בפסחים (ל\"ה ע\"א) שנינו, אלו דברים שאדם יוצא בהם ידי חובת מצה, בחטים ובשעורים ובכוסמין ובשיבולת שועל ושיפון. ובגמרא דייקו מזה, דרק אלו ולא אחרים. מנא הני מילי, אמר ריש לקיש וכן תנא דבי רבי ישמעאל אמר קרא, לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות, דברים הבאים לידי חימוץ, אדם יוצא בהם ידי חובת מצה, יצאו אלו שאינם באים לידי חימוץ, אלא לידי סירחון. ופירש\"י ז\"ל, אורז ודוחן אין עושין חמץ, ואם מחמיץ אותם מסריחין. עוד אמרו שם שרבי יוחנן בן נורי אומר אורז מין דגן הוא. ואמרו שם דלית דחש לר\"י בן נורי. ע\"כ.","b":false},{"t":"והטור א\"ח (ריש סימן תג\"ן) כתב, ואלו דברים שיוצאים בהם ידי חובת מצה, בחטים ובשעורים וכו', אבל לא באורז ושאר מינים, וגם אינם באים לידי חימוץ ומותר לעשות מהן תבשיל, וכן מכל מיני קטניות, ויש אוסרים לאכול אורז וכל מיני קטניות בתבשיל, לפי שמיני חטים מתערבים בהם, וחומרא יתירה היא זו, ולא נהגו כן. וכתב הב\"י דמ\"ש חומרא יתרה היא, גם ר\"י כתב שהוא מנהג שטות, זולתי אם הם עושים להחמיר על עצמם, ולא ידעתי למה. עכ\"ל. ובהגהות מיימוניות פרק ה' כתב בשם סמ\"ק (סי' רכב עמ' רלא הגהות הר\"ף אות יב) על הקטניות כגון פולים ועדשים יש נוהגים איסור לאכלם בפסח וכן ה\"ר שמואל מאיורה אבל ה\"ר יחיאל ושאר גדולים היו נוהגין בהם היתר, וקשה מאד הדבר להתיר כיון שאחרים נהגו בהם איסור (עי' פסחים נ, ב) ונראה שלא נהגו בו איסור משום חימוץ דלא טעו אינשי בזה, דתינוקות של בית רבן יודעין אותו, דבפירוש אמרינן בגמרא (לה, א) דאינו בא לידי חימוץ אלא חמשה מינים בלבד אלא אסרום משום דדגן מעשה קדרה וקטנית מעשה קדרה גזירה הא אטו הא, וגם יש מקומות שעושין פת מקטנית ואתי לאיחלופי בדייסא שהוא מעשה קדרה, אבל מיני ירקות דלא דמי לדגן כלל לא אתי לאיחלופי וגם פעמים תבואה מעורבת בהם ואי אפשר לבררו יפה והחרדל כמו כן יש לאסרו בפסח משום דהוא מידי דמידגן (עי' נדרים נה, א) אף על גב דבימיהם היה מותר מכל מקום עתה יש להחמיר בדורות הללו שאינם בקיאים כל כך באיסור והיתר כדורות הראשונים כדפירש רב סעדיה גאון. עכ\"ל. וגם המרדכי בפרק כל שעה (סי' תקפח) כתב כל זה בשם סמ\"ק (שם), ולית דחש לדברים הללו זולתי האשכנזים, עכ\"ל הב\"י.","b":false},{"t":"והד\"מ (אות ב') כתב ואנו בני האשכנזים נהגנו להחמיר. וכתב בת\"ה (סי' קי\"ג) ואפילו הכי מותר להשהות מיני קטניות דמידגן בביתו אעפ\"י שנפל עליהם מים, דבהא לא גזרינן משום שאר מיני דגן, וכן מותר להדליק באותן שמנים הנעשים ממיני קטניות, ואם נמצא גרגיר של קטניות בקדרה או בתבשיל לא מחמרינן כלל לאסור התבשיל וע\"ש. עו\"כ בסוף דבריו שם, וכתב מהרי\"ל דמותר לאכול זרע אקלייה לרפואה דלא הוי מין קטניות, ונ\"ל דה\"ה הזרע הנקרא בל\"א אני'ס דאין זה מין קטניות, וכן משמע לעיל (סי' ר\"ד) דאניס'ה ואלייג'ר אינם מין קטניות. עכ\"ל.","b":false},{"t":"וכ\"פ מרן ז\"ל בשו\"ע (סימן תג\"ן ס\"א) דאורז ושאר קטניות אינם באים לידי חימוץ, ומותר לעשות מהם תבשיל. והרמ\"א ז\"ל בהגה כתב דיש אוסרים, והמנהג באשכנז להחמיר ואין לשנות, מיהו פשוט דאין אוסרים בדיעבד אם נפלו תוך התבשיל, וכן מותר להדליק בשמנים הנעשים מהם. ואין אוסרים אם נפלו לתוך התבשיל. וכן מותר להניח קטניות בבית. וזרע אקליז'א ואני'ס ואליינצ'ר אינן מיני קטניות ומותר לאוכלן בפסח. כן נ\"ל.","b":false},{"t":"והמשנ\"ב (סק\"ו) כתב, דהוא רק חומרא ולא מעיקר הדין, וטעם החומרא משום שמתערבת בהם תבואה, וא\"א לבוררם יפה. ועוד שכמה פעמים טוחנים האורז ושאר קטניות ואופין מהם לחם, ויש עמי הארץ שלא יבחינו בין קמח זה לקמח דגן, ויקילו בפת של דגן, ע\"כ אסרו גם את זה. ואפילו לבשל אורז וקטניות שלמות אסרו, משום לא פלוג.","b":false},{"t":"וע\"ש בביאוה\"ל שהביא לשון רבינו מנוח ז\"ל שהוסיף טעם חשוב, שיש שנים שאין ברכה והתבואה מתקלקלת, וחוזרת להיות זונים (מלשון תזנה הארץ), ובשנה גשומה חוזרת התבואה להיות ויצא\"ש פאר מנטל\"ש, וע\"כ אסרו כל הקטניות ע\"כ. ופי' הביאוה\"ל, שיש ב' מיני חטים שבשנה שאינה כתיקונה, משתנות ונראות כמיני זרעונים, וע\"כ אסרו כל מיני זרעונים. עכ\"ל.","b":false},{"t":"והכף החיים (סימן תג\"ן סק\"י) הביא דברי היעב\"ץ ז\"ל בספרו מור וקציעה וז\"ל, ומעידני על אבא מארי הגאון (חכ\"צ) זצ\"ל כמה צער נצטער אותו צדיק על זאת וכו', היה מתרעם ואומר אי איישר חילי אבטליניה למנהג גרוע זה, שהוא חומרא דאתי לידי קולא ונפק מיניה חורבא ומכשול באיסור חמץ, כי מתוך שאין מיני קטניות מצויין להמון לאכול ולשבוע, צריכים לאפות לחם מצה הרבה, בפרטות העניים וכו', ומתוך כך אין נזהרים בעיסה כראוי וכו', קרוב הדבר שנכשלים באיסור כרת רח\"ל, דהוה חש להמון רבת עם שלא תלעוז עליו המדינה וכו'. והובא במחזיק ברכה (אות א'). והבשמים ראש (סי' שמ\"ח) ג\"כ תמה על מנהג זה וכתב שהוא בטעות. ואולם הפר\"ח הביא לזה סמך מהש\"ס. (ולהלן כתבתי משם אפרקסתא דעניא, שאין ראיתו מוכרחת, וכונתו רק להביא סמך כל שהוא). וכתב הפר\"ח, שע\"כ יש לאסור כל מידי דדמי לדגן משום דמחלף להו בדגן. אבל אין כן מנהגנו (הספרדים) זולתי באורז ששנה אחת אחר שנבדק ג\"פ, נמצא בו גרעין חטה, ומאותו יום לא אכלנוהו בפסח. עכ\"ל. וכ\"כ מרן החיד\"א ז\"ל בספרו טוב עין (סי' ט' אות ו') דבאורז נהגו בעה\"ק ירושלים מרבית הת\"ח יראי ה' שלא לאוכלו בפסח, דהוה עובדא שביררו האורז כמה פעמים, ואחר שבישלוהו נמצאה בו חטה, ולכן נמנעו מלאוכלו, אבל אין למחות ביד האוכלים, ובפרט שבעה\"ק הוא מזון עניים ותינוקות. ע\"ש.","b":false},{"t":"עו\"כ הכה\"ח שגם בס' פקודת אלעזר (סי' נ\"א) כתב דעכשיו נוהגין גם הספרדים בירושלים ת\"ו לאסור הקטניות בפסח ע\"ש. והכה\"ח כתב אמנם עתה בזה\"ז נתרבו האוכלוסים יותר ויותר ממה שהיו, וכל אחד ואחד מחזיק במנהגו, יש אוכלים קטניות בפסח ויש אין אוכלים, ואין בזה משום לא תתגודדו, כיון שכל קהלה היא בפני עצמה. וכמ\"ש לקמן סימן תס\"ח בס\"ד. עכ\"ד.","b":false},{"t":"ומדברי הרב פקוד\"א אין ראיה שהוא היה מהחכמים שעלו מארץ מרוקו, ושם כולם לא אוכלים אורז מדורות עולם, ורובם לא אוכלים קטניות יבשות, ומסתמא היה קשור עם חכמי המערב שבעה\"ק ירושלים ת\"ו, וע\"כ לא היו אוכלים, אבל שאר הספרדים לא החמירו בזה מעולם. מלבד איזה יחידים או משפחות יחידות ומועטות שהחמירו על עצמם שלא לאכול אורז בפסח. וכפי שידוע אצלנו ולא עת האס'ף. והן היום בכל רחבי ארץ ישראל וגם בעה\"ק ירושלים כל קהלות הספרדים אוכלים קטניות אפילו יבשות וכן אוכלים אורז, רק שמקפידים מאד לבררו הדק היטב ג\"פ לפני הפסח, ואין פוצה פה ומצפצף, מלבד יוצאי מרוקו שנזהרים באורז, ורובם נזהרים גם בקטניות היבשים. אבל כל מיני קטניות ירוקים ולחים כמו שעועית ופולים ואפונה וכו' כשהם ירוקים הם עיקר מאכלינו בימי הפסח.","b":false},{"t":"ובדידי הוה עובדא בהיותי בעיה\"ק בני ברק שבא אלי אברך מיוצאי מרוקו, איזה ימים קודם הפסח, ושאל אם יכול לעשות התרה כדי לאכול אורז בפסח, ואמרתי לו שמנהגנו מאז ומתמיד שלא לאוכלו, ושאל עוד אם תועיל לו התרה, ואמרתי לו כן, וכפי שכן פסק גדול דורנו בעל יבי\"א שליט\"א, וביום ראשון דחג הפסח בא אלי וסיר האורז בידו, ואמר שאכן עשה התרה, ובדק את האורז ג\"פ הדק היטב, והנה בעת שבישלו בחג את האורז מצאו בו חטה אחת והביא להראות לי. ואמר שמעתה יקפיד לשמור מנהג קדמונינו. כי מעולם לא מצא חטה גם בחול, וראה בזה אות וסימן להמנע. והעיקר לדינא שמי שרוצה להתיר ולאכול אורז בפסח וכן שאר קטניות, רשאי. וכפי שפסק פאה\"ד מרן הראש\"ל נר\"ו בספריו הקדושים.","b":false},{"t":"ועיין עוד במשנ\"ב (סק\"ז) שכתב דבשעה\"ד שאין לו מה לאכול, מותר לבשל כל המינים חוץ מה' מיני דגן, ומ\"מ גם בכגון זה יקדים קטניות לאורז ודוחן ורעצקע, שהן דומין יותר לה' מיני דגן, ושייך בהו טפי למיגזר, עו\"כ ופשוט דה\"ה לחולה אפילו שאין בו סכנה דמותר לבשל לו אם צריך לזה. אלא דצריך לבדוק יפה יפה בדקדוק היטב שלא ימצאו בם גרעינים של ה' מיני דגן. והחת\"ס (סי' קכ\"ב) כתב דאפילו במקום שיש להתיר מ\"מ יחלטנו לכתחילה ברותחין, דכל מה שאפשר לתקן מתקנין וכ\"כ הח\"א. עכ\"ל.","b":false},{"t":"ובכה\"ח שם (אות י\"ג) כתב, דבשעת הדחק ושנת רעבון וכמעט לא ימצאו העניים מה לאכול, עיין שד\"ח (מע' חמץ ומצה סי' ו' אות א') שהביא פלוגתא בזה, והוא ז\"ל מכריע כדעת המתירים, ודוקא לעניים ולחיי שעה, ולא לזולתם. ע\"ש.","b":false},{"t":"וכ\"כ חיי\"א שם דבשעה\"ד שאין לאדם מה לאכול אלא בדוחק גדול, מותר לבשל קטניות ושאר דברים, ומ\"מ כל מה שאפשר ליזהר מאורז ודוחן (שקורין בערבית דוכו'ן) ורעצק'י שקורין טארטאק'י יזהר מהם, כי הם דומים יותר לה' מינים. עכ\"ל. וע\"ע בנשמת אדם (סי' י\"ט). ע\"כ.","b":false},{"t":"עו\"כ שם (או' י\"ד) משם הברכ\"י, שבשו\"ת מכתם לדוד (סי' כ') באחד שהגיע לכפר ישמעאלים, שהתיר לו לאכול קטניות בפסח, הגם שאין מנהגו לאוכלם, ואם אין לו מי שיתיר לו מותר גם בלי התרה, ואם אפשר יזהר מהאורז דגרע מכולהו. ובכל מקום שיש להתיר מ\"מ לכתחילה יחליטנו ברותחים, דכל מה שאפשר לתקן מתקנינן. תשובת חת\"ס (סי' קכ\"ב).","b":false},{"t":"ועל האני'ס שכתב הרמ\"א שאינן קטניות, ומותר לאוכלן בפסח. כתב המשנ\"ב (ס\"ק י\"ג) דמ\"מ צריכים שלא יתערב בהם מה' מיני דגן, וע\"כ י\"א דטוב להחמיר שלא לאכול אני'ס וקִימ'ל עד יום אחרון, כי א\"א לבררם יפה. ועיין בט\"ז וח\"י בזה.","b":false},{"t":"ב.","b":false},{"t":"תיאור צמח הקינואה ואם שייך בו חומרת קטניות.","b":true},{"t":"והנה הקינוא'ה היא לא קטנית, שאינה גודלת בשרביטין, אלא (לפי הצילומים שהראוני הרי זה דומה לשֶבֶת שהוא האניס) ואמנם יש שוני ביניהם, שהאניס הוא תבלין לתבל או את האוכל, ואין טוחנים אותו ואין עושים ממנו לחם, אלא יש מערבים הגרגירים שלו בעיסה להטעים הלחם, אבל קינוא'ה הוא מאכל שמבשלים אותו, או טוחנים ולשים ממנו לחמניות. ובזה לכאורה יש מקום לומר שגם הוא בכלל הגזרה של הקטניות, מצד שמבשלים אותו. וגם טוחנים אותו לקמח, ושייך לכוללו עם הקטניות והאורז והדוחן.","b":false},{"t":"ומאידך י\"ל דלא גזרו אלא על אותם דברים שגזרו עליהם, אבל דברים שלא היו בזמן הגזרה לא נכללו מכלל הגזרה, וכמו שכתבו רוב האחרונים בענין תפוחי אדמה, שכיון שלא היו בזמן הגזרה, אעפ\"י שמייבשים אותם ועושים מהם קמח ומוכרים אותו בכל החנויות, ולשים ואופים מהם עוגות לרוב, והם דומים במראיהם לעוגות הרגילות, וגם בטעם הם קרובים מאד לעוגות הרגילות העשויות מקמח חטים, ואמרו שלא גזרו עליהם, וכך נתפשטה ההלכה ופוק חזי מאי עמא דבר, ולהלן אציין מדברי הפוסקים בזה.","b":false},{"t":"ג.","b":false},{"t":"קפה אם שייך בו גזירת קטניות.","b":true},{"t":"והנה בשו\"ת חכם צבי (ליקוטי תשובות סי' קכ\"ז) כתב באות ב', בענין הקפה, שאינו בכלל מנהג בני אשכנז הנוהגים איסור באכילת קטניות, דהבו דלא להוסיף על המנהג, ולא גרע מזרע אליז'א ואני'ס שנהגו בהם היתר, כמ\"ש הרמ\"א סימן תג\"ן ס\"א בהגה. וכ\"ש הקאהוי שבאותו זמן שהתחילו לנהוג איסור בקטניות לא היה הקאהוי מצוי כלל במדינות הללו, ולא ידעו מה הוא. וגם אינו מאכל ולא עושין ממנו מעשה קדרה, אלא קולין וטוחנין אותו ועושין ממנו משקה, המתקיים לשעתו, ואינו נעשה לימים רבים כדרך שכר שעורים, ושנינו במשנתנו (פרה פ\"ט מ\"ו, חגיגה כ\"ג ע\"א) לא יעבירם בנהר ובספינה, ור' חנניה בן עקביה אומר לא אסור אלא בירדן וכו', וכמעשה שהיה. ודברי הרמב\"ם בזה (בהלכות פרה פ\"י ה\"ב), ובדין הנושא חבית של קודש, נושא את המדרס (פי\"ב מהל' אבות הטומאה ה\"ג). עכ\"ל.","b":false},{"t":"וכ\"כ כה\"ח סופר (סימן תג\"ן אות כ\"א) בשם א\"א (סי' תס\"ד) דקאו'י נוהגין בו היתר. ושכ\"כ במש\"ז (סימן תג\"ן אות א') דנוהגים היתר בשתיית קפה. דלית ביה עירוב. ואינו דומה לדגן, ואין לאסור במקום שנוהגין היתר. וכן בתפוחי אדמה דשרי, אם לא במקום שנהגו איסור.","b":false},{"t":"עו\"כ (שם או' כ\"ב) בשם שבו\"י ח\"ב (סי' ה') שאם חרכו הקפה קודם פסח יש להתיר. והחֹק יוסף חלק עליו, וכתב שכן הורה מֹר חמיו הג\"ר אברהם ברודא. והברכ\"י כתב שהעיקר כהשבו\"י. דהבו דלא לוסיף שהקפה הוא אילן ונעשה משקה. וע\"ש שאפילו במקום שהחמירו בקפה, אם חרכו אותו קודם פסח מותר כהשבו\"י. והביאו שע\"ת (אות א') וכתב דבמקומות אלו נהגו היתר פשוט בקפה, ואעפי\"כ זריזין מקדימין לחורכו קודם פסח. וכן לברור אותו קודם קליה, מתערובת אורז ושאר מינים, ותבא עליהם ברכת טוב. והרב עיקרי הד\"ט (סי' ח\"י אות ל') כתב דאצלם פשוט לשתות קפה גם אם לא נחרך קודם פסח. ועיין עוד בכה\"ח שם (אות כ\"ג) מה שכתב בענין התה. ע\"ש.","b":false},{"t":"והנה הוציאו את הקפה מכלל המנהג שאסר את הקטניות ודומיהם, משום שהקפה לא היה מצוי במדינותיהם, בעת שהתחילו באיסור הקטניות. ואעפ\"י שהיה בעולם במקומות אחרים, מ\"מ כיון שלא היה באותן מדינות, לא נכלל בכלל הגזרה, והבו דלא להוסיף על המנהג. וכ\"ש בקינואה שרק בעת האחרונה הגיע למחוזותינו, ובודאי גמור שלא היה ידוע אז באותן מדינות, והבו דלא להוסיף גם זה בכלל הקטניות.","b":false},{"t":"אלא שהחכם צבי זלל\"ה הוסיף שהקפה אינו מאכל ולא עושים ממני מעשה קדרה, אלא רק משקה. ועוד כתבו שאר הפוסקים דהוא אילן ולא דומה לדגן. ואילו הקינוא'ה עושים ממנו מעשה קדרה וגם אופים ממנו. אך עכ\"פ אינו בכלל הגזרה, והחכם צבי מצא עוד טעם בקפה להתיר. אבל די בטעם הראשון לבדו כדי להתיר.","b":false},{"t":"ד.","b":false},{"t":"למחמירים בקטניות אי יש להחמיר בקמח תפוחי אדמה.","b":true},{"t":"והלום ראיתי בשו\"ת אפרקסתא דעניא ח\"א (סי' קי\"ז) שנשאל מהג\"ר צבי קינסטליכער אבד\"ק הרמנשטאדט. אם מותר להכין קמח מתפוחי אדמה בבית חרושת לצורך פסח. וציין לשו\"ת לבושי מרדכי שהתיר בזה לק\"ק סערדהל, אך רבו בספר ערוגת הבושם א\"ח (סי' קכ\"ד) החמיר בזה. עפ\"י פסחים (מ\"ב ע\"ב) דאסר רבא קידרא דחסיסי היכא דשכיחי עבדי. והרב שם מחלק דלעשות מאפה מקמח תפו\"א בביתו הוי כאתרא דלא שכיחי עבדי, משא\"כ בביח\"ר. והרב השואל תמה דא\"כ למה לא אסרוהו על ההמון, ואפילו בבית היראים הו\"ל לאסור, שלא יאמרו כל הסריקין אסורים וכו'. וע\"כ צ\"ל שכיון דבזה\"ז זהירים מאד בעניני פסח גם עמי הארץ, והוי כמו מה שאמרו ריש פסחים הכל חברים אצל בדיקת חמץ. ואין בכוחנו לגזור גזרות חדשות. עו\"כ הרב הנז' שיש לחוש שיערבו קמח תפו\"א בקמח של המצות ועי\"ז ימהר להחמיץ. ותמה גם ע\"ז, דבזה\"ז עשיית הקמח ואפיית המצות הוא בהשגחת הרב וכו'. ולא מקרי שכיחי עבדי, ועוד דלפ\"ז היו צריכים לאסור גם תפו\"א עצמם ולא רק הקמח שנעשה מהם. שמא יערבם בלישת המצות. עכת\"ד.","b":false},{"t":"ובעל אפרקסתא דעניא השיבו דהרב ערוגת הבושם סמך על פר\"ח, שכתב דהאידנא אין הדורות מתוקנים והוי כההיא דרבא, ויש לאסור כל דדמי לדגן, דמחלף להו בדגן, דמדמי דורות שאין מתוקנים לעבדים הנז'. ואין לסמוך על מ\"ש השואל דהקמח ואפיית המצות הם בהשגחה, דלא כל המקומות שוין. אלא דאעיקרא אין ראיה מהפר\"ח, דהוא בא לישב עצם הגזרה של הקטניות, דאיך גזרו אחר חתימת התלמוד, וחתר למצא להם סמך כל שהוא, והביאו מהחסיסי, ודוקא להערוך שחסיסי הוא קמח עדשים. דרש\"י פירש שהוא כותיקא וכ\"פ רבים מהראשונים. והרי\"ף פי' מצה אפויה. וכבר עמד ע\"ז הברכ\"י (תס\"ג או' א') ע\"ש. וסגי ליה להפר\"ח בסמך כל שהוא לישב גזרת הראשונים, דהט\"ז כתב כלל דכל שהתורה התירה אין כוח ביד חז\"ל לאסור, וע\"כ הביא סמך, אבל אין כונת פר\"ח שהוא ראיה גמורה. והוא עצמו כתב דשם לא נוהגין כן, ואם היא ראיה גמורה היה לו לצוות שינהגו כן, וע\"ש עוד (סי' תס\"א ד\"ה עו\"כ) דלמד מהגמ' ההיא להתיר כל מה שהתורה התירה. ובשו\"ת אריה דבי עלאי למד מהפר\"ח, להתיר לאפות פת מתפו\"א בפסח כרצונו. וגם הברכ\"י הביא דברי פר\"ח דסי' תס\"א, וכתב דלא כהכנה\"ג דאין לנו לגזור מדעתנו. וע\"ש עוד מזה. דהביא מראב\"ן שלא טוב לעשות פרפיל מקמח מצה אפויה. ע\"ש.","b":false},{"t":"והרב כתב דשאני קמח תפו\"א, דפשוט שלא היה בכלל גזירת הקטניות, דרוב מאכלינו בפסח הוא תפו\"א בעינם או באופן מלאכותי, ואיך נגזור ונוסיף על גזרת קטניות שעליה גופה תמה הפר\"ח, ואע\"ג דהחיי\"א (כלל קכ\"ז ס\"א) כתב שגזרו על הכל מפני הטעות, שבימיהם וגם עכשיו עושים מהם קמח בכמה מקומות, משמע שגדר הגזרה הוא לאסור כל מה שעושים ממנו קמח. ולכאורה יש לאסור גם תפו\"א, אבל א\"כ היו צריכים לאסור גם תפו\"א גופן כמו בשאר קטניות. אלא ודאי דכל שלא היה בכלל הגדר בשעת הגזרה, אע\"ג דנתחדש לעשות ממנו קמח, לא נכנס בכלל הגזרה למפרע. וע\"ש שמפרש כן גם בדברי חיי\"א.","b":false},{"t":"והביא דברי שו\"ע דבעל התניא שמשמע דגדר הגזרה היא, שתבשיל הקטניות דומה לתבשיל דגן. וכתב דא\"כ יש לאסור תפו\"א עצמם. אלא ודאי דמה שלא היה בכלל הגזרה, אין לנו רשות לגזור עליו. וע\"ש שמפרש דגם בעל התניא ה\"ק דרק בקטניות גזרו, ולא כל הקטניות אלא רק באותם קטניות שבישולם דומה לתבשיל מיני דגן. משא\"כ אניס וכדו', שהם קטניות אלא שאין בישולם דומה, חוץ מהחרדל שאפילו שאין בישולו כדגן, מ\"מ גדל בשרביטין ודומה לגידול קטניות ונאסר בכלליה. [ולמד מזה דר\"ל שהיה בכלל הגזרה] וחוץ מן הכמון, שאפילו שאין תבשילו דומה, מ\"מ גרעיניו דומים לדגן. והחמירו בו. וע\"ש שלמד מדבריו דגם מה שבכלל קטניות, לא נאסר אלא בהיות לו דמיון לדגן, או בתבשיל, או בגידול בשרביטין, או בצורת גרעיניו. אבל מה שאינו בכלל קטניות שרי בכל גונא. וכן כל מיני ירקות אין מחמירים בהם כלל, הואיל ואינן דומים כלל לדגן. עכ\"ל. וכתב המחבר דתפו\"א ג\"כ בכלל ירקות השדה ולא נכנס כלל בסוגי קטניות. וע\"ש בזה.","b":false},{"t":"עו\"כ בא וראה כמה הצטערו האב ובנו אבירי הרועים חכ\"צ והיעב\"ץ ז\"ל בספר מור וקציעה על גזירת הקטניות, ועליהם רמז שע\"ת (רס\"י תנ\"ג), ועיין לעיל שכתבתי דבריהם בשם כה\"ח סק\"י, וע\"ש בסקי\"א. אלא דכל גדולי עולם אחזו שלא להקל, ומהרי\"ל כתב דהמיקל בזה הוא בכלל העובר על דברי חכמים חייב מיתה רח\"ל. מ\"מ הבו דלא לוסיף עלה לכרות אוכל מפי עניי עם, ואפילו אי הוי ספק, הרי זה ספק במנהג ולקולא, כ\"ש דודאי אינו בכלל הגזירה. ועיין שד\"ח מע' חמץ ומצה סי' ו' אות ט' ד\"ה אך הרב, בשם ספר עמק הלכה.","b":false},{"t":"עוד הביא משו\"ת שאילת יעב\"ץ (סי' קמ\"ז או' ד') הובא בשע\"ת, שכשהיה במנהיים, רצו לאסור תפו\"א כי עושים מהם קמח, ועמד כנגדם, ביודעו שאין הצבור יכול לעמוד בלי זה, והוא מאכלי עניים, ונצח אותם ע\"י אנשי הקהל שצוו על הרב המורה, שלא יאסור מה שלא אסרו הרבנים שישבו שם על כסא ההוראה. ומה טוב אם יסכימו כל חכמי הדור לדעת אחת, ומסופקני אם יבא הדבר פ\"א על מכונו בדור הזה, שגברה הקנאה, ויראים יותר מן המנהגים כמפני גופי תורה. עכ\"ל. (וכתב המחבר שזה קאי על גוף גזרת הקטניות שדיבר בו מקודם, והרי כבר רצו לאסור תפו\"א אלא שהיעב\"ץ גבר. ולא עלה על דעתם לאסור לעשות מהם קמח. א\"ו דפשיטא להו שאם הם מותרים גם הקמח שלהם מותר. [עוד ציין מספר שאילת יעב\"ץ ח\"ב (סי' ס\"ה) בענין צוקר, ובאמת שאין הדעת סובלת כל החומרות המתחדשות בכל יום. וע\"ע שם סי' קכ\"ד].","b":false},{"t":"עו\"כ המחבר שע\"י התפשטות קמח תפו\"א ימעטו באפיית מצות, שא\"א לצאת בהם י\"ח שימור, ונודע דברי החת\"ס (סימן קכ\"א) שכתב להקל גם בקטניות, במקום שיש מכשול ע\"י אפיית מצות הרבה, וכמ\"ש בתשובות הרא\"ש (כלל נ\"ה סי' י' ד\"ה כל המנהגים) דאפילו מנהג שנהגו, אם יכול לבא לידי מכשול יש לבטל המנהג, ועיין שד\"ח (חומ\"ץ סי' ו') כ\"ש בזה שאינו מין קטניות ויש בו תקוה למעט עי\"ז אפיית המצות. ודאי יאה ויאה.","b":false},{"t":"עוד הזכיר דברי צל\"ח (פסחים ל\"ה) דקטניות מחמיץ ע\"י דבר אחר ע\"ש שרצה להוציא גם מזה קולא לתפו\"א. והזכיר דברי שאילת יעב\"ץ (סי' ס\"ה) בשם אביו הגאון בסוכר הנקח מגוי, ולואי שכזית מצה אפיקומן יהיה כשר כ\"כ כמוהו.","b":false},{"t":"ואשר ע\"כ על בית חרושת אין לחוש לאחלופי ולערבובי, כמ\"ש בתה\"ד (סימן קי\"ט) דרק אם הכשר ביוקר אז חוששים לחילוף ע\"ש וברמ\"א יו\"ד (סימן קי\"ח ס\"ב), וע\"ש מ\"ש בשם שד\"ח שם.","b":false},{"t":"עוד כתב שם דאין לחוש שיערבו קמח תפוחי אדמה בקמח מצות, ודן בהא דשבועות (מ\"ו, ב) דלא מחזקינן אינשי בגנבי ורשיעי. ע\"ש. וכ\"ש בעניני פסח דזהירי אינשי טפי וע\"ש שהאריך בדברי הפוסקי' בזה.","b":false},{"t":"א\"כ בנ\"ד אותם שהצבור מוסרים לו עסק המצות רובם ככולם בחזקת כשרות, כ\"ש בעניני פסח דחמירי גם לאנשי דלא מעלי, ועיין דרכי תשובה שם סק\"ז בשם פרי תואר שבזמנינו אין ע\"ה חשודים אלא במילי דחזינהו דמזלזלי בהו, אבל ביי\"נ במערב לא חשידי כלל ע\"ש, ובנ\"ד גם ע\"ה מדקדקים לענין פסח ולא חשידי, וגם דלא מרע אומנותיה, כ\"ש בדאיכא מו\"צ במתא דודאי מירתת, וע\"ש עוד מזה, ויש בזה תרתי אימת פסח, ואימת ב\"ד, ולא חיישי' אפילו לשכחה. והביא משו\"ת לבושי מרדכי מה\"ת (סי' קמ\"ה) דכיון שידוע שיש ספירט מיוחד לפסח אין חוששין שיחליפו באחר.","b":false},{"t":"ובשו\"ת מהר\"ם שיק (א\"ח סי' רל\"ו) החמיר למכור קמח של פסח בחוה\"מ פסח משום מראית העין, ודן בדברי פר\"ח דלא חיישינן למראית העין, דשאני התם בקמח קטניות או קמח מצה אפויה, שהמדקדק בראיה יפה רואה שאינו מדגן, אלא שהיו יכולים לומר מה זה מותר גם זה מותר, וע\"כ שם לא חיישינן למראית העין, וכתב המחבר דגם בקמח תפו\"א ניכר היטב למסתכל היטב שאינו מדגן. וע\"ש עוד בזה. עכת\"ד. הרי שהביא גדולי עולם שאין חוששין לקמח תפו\"א וכן הסיק הוא ז\"ל באותות ומופתים, וכ\"פ למעשה.","b":false},{"t":"ועיקר טעמו הוא שהתפו\"א לא היה בזמן שגזרו אותה גזרה, וכאמור גם הקינוא'ה לא שערוה אבותינו, וגם היום אינו נפוץ במקומותינו, ורוב בני אדם לא שמעו ע\"ז כלל, וא\"כ אינו בכלל גזירת הקטניות, אלא שיתר הטעמים שכתב להקל בתפו\"א, אינם שייכים בקינוא'ה, וגם שגרעיניו קטנים כמו של הדגן. אך עם כל זה הרי לא היה בכלל הגזרה, [ולהלן אכתוב בס\"ד דיש להקל גם משום שעיקרו עשוי למאכל הטבעונים להתרפאות ולהתחזק בבריאות].","b":false},{"t":"וגם בשו\"ת חלקת יעקב חיו\"ד (סי' כ\"ח) [דן בתפו\"א שנתבשלו ע\"י אדים בביח\"ר של גויים, אם יש בהם משום בישולי עכו\"ם, והעלה להתיר בשעה\"ד, יעו\"ש]. ודן שם בתרמילים של פולים ירוקים, וכן הפולים הירוקים עצמם, שראה בשם הגאון ר\"א אפענהיים דאפשר שאינן בכלל קטניות, וראיה מנדרים (נ\"ד) הנודר מן הירק אסור בפולין הלחין. וכתב הר\"ן שם, דפולין הם בכלל הירק, וקטניות אינן בכלל ירקות, כמבואר במשנה, וכתב שקשה לסמוך ע\"ז לדינא, דבנדרים אזלינן בתר לשון בנ\"א כמ\"ש בנדרים (ל') ובכ\"מ, ולשון תורה ולשון חכמים לחוד, ולשון בני אדם לחוד. וכתב דאין להתיר, כי אין דוחק כל כך, והוא דבר התמוה לרבים, עיין יו\"ד (סי' רמ\"ב ס\"י). והביא דברי ברכ\"י (סי' תג\"ן סק\"ב) וז\"ל פולים לחים נראה שמותרים, ב\"ד (סי' רי\"ו), ולי ההדיוט יש לפקפק לבני אשכנז שנהגו להחמיר אפילו בחרדל שדומה לקטניות. ויש לדחות ראיית הרב בית דוד, ושיבח לה' שזכה לדבריו. ע\"ש.","b":false},{"t":"והמדקדק בדבריו ז\"ל יראה שהוא נוטה להתיר מעיקר הדין, אלא שהוא תמוה לרבים, וכל זה רק בגלל שאינו ממש קטנית אלא ירק, וק\"ו לקינואה, שבודאי אינו קטנית, וגם לא גדל בשרביטין דודאי קיל טפי, והעולה על כולנה שזה לא היה במקומותינו כלל, ולא נכללו בכלל גזרת הקטניות.","b":false},{"t":"ה.","b":false},{"t":"כל שלא גזרו בו גזירת קטניות בתחילה אין לנו לגזור בו.","b":true},{"t":"ומעתה נביא דברי הגאון אגרות משה ז\"ל בחאו\"ח ג' (סימן ס\"ג) שדן בבוטנים שכתב, שבהרבה מקומות אכלו מהם בפסח, והרב השואל תמה ע\"ז, כי שמע שבכמה מקומות עושים ממנו קמח. וכתב הרב ז\"ל שאין \"כלל\" שכל הדברים שעושים מהם קמח נאסרים ממנהג זה, דתפו\"א עושים ממנו קמח בכל המקומות, וגם בדורות קודמים, ומעולם לא חששו לאוסרו,","b":false},{"t":"עו\"כ שגם הטעם שכתב הטור שמתערבים בו מיני חטים, נמי אינו \"כלל\" לאסור כל מה שיכול להתערב בו חטים ושעורים, דהא אניס וקימעל שמתערבים בהם מיני חטים ושעורים, כמפורש בט\"ז (סק\"א) ובמג\"א (סק\"ג) וכתבו שקשה לבודקם, ומ\"מ לא אסרום, וכמפורש ברמ\"א. ומאידך נוהגים לאסור חרדל דהוי כמיני קטניות, כמ\"ש הרמ\"א (סי' תס\"ד) אעפ\"י שאין בו הטעמים הנ\"ל. ולכן אין לנו אלא מה שמפורש שנהגו לאסור, וכן מה שידוע ומפורסם.","b":false},{"t":"והסביר הענין, דזה לא נאסר בקיבוץ חכמים, אלא שהנהיגו את העם להחמיר ולא לאכול מינים מסויימים שהיו רגילים לאוכלם, וזאת מן הטעם שמתערב בהם חטים, ושעושים מהם קמח, וע\"כ לא נאסרו אלא אותם מינים שהנהיגו, ולא השאר. שהרי לא גזרו בקיבוץ חכמים עד שנאמר שתיקנו שכל הדברים שיש חשש עירבוב, או שעושים מהם קמח יהיו אסורים, וע\"כ תפו\"א שלא היו מצויים אז כידוע, וממילא לא הנהיגו לאוסרם אינם בכלל האיסור, אעפ\"י ששייך בהם אותו הטעם ממש, אין ללמוד מן המנהג. ומשנתרבו תפו\"א במדינותינו לא רצו לאוסרם, או מפני הצורך, או משום שטעם האיסור קלוש, עיין ב\"י שהר\"י קרא לזה מנהג שטות, וגם משמע שהר\"ר יחיאל ושאר גדולים לא נהגו בהם איסור, גם במקום שהיה מנהגן לאסור, שכתב על זה, וקשה להתיר כיון שאחרים נהגו בהם איסור. ועל כן חכמי הדור האחרונים לא רצו להוסיף גם המינים שהתחדשו אח\"כ, רק שא\"א להתיר מה שכבר נהגו לאיסור.","b":false},{"t":"וגם אניס וקימל אפשר שלא היו רגילים אז לזורעם במקום שזרעו מיני דגן, ולא היה טעם להנהיג בהם איסור, וע\"כ גם אחר שהחלו לזורעם ליד הדגן, לא רצו לאוסרם. וע\"כ גם הבוטנים לא אסרום בהרבה מקומות, ובמקום שאין מנהג אין לאסור, כי אין להחמיר בדברים אלה, וכמ\"ש הח\"י, ואלו שנוהגים שלא לאכול הבוטנים אסורים, אבל מספק אין לאסור. (וכ\"כ בעל אפרקסתא דעניא הנ\"ל, דמספק שרי, שכל ספק במנהג לקולא.)","b":false},{"t":"וע\"כ שייך שיתן הכשר על הבוטנים שלא נתערב בהם חמץ, ויאכלו אלו שלא נהגו בהם איסור. וכן ראיתי שנותנים הכשר על פינאט אויל (שמן בוטנים) מהאי טעמא. עכ\"ד.","b":false},{"t":"ובאמת במרוקו נהגו שלא לאכול אורז כלל, וכל ערי מרוקו שוים בזה, אך בשאר הקטניות היבשות יש מנהגים שונים, דיש שלא אוכלים בוטנים וגרעינים ויש שאוכלים אותם, אבל כל הקטניות הירוקים אוכלים כולם, ואורז וחומוס כולם לא אוכלים. ומוכרחים לומר כמו ההסבר שכתב האגרו\"מ.","b":false},{"t":"ועכ\"פ ראינו בדברי הגאון ז\"ל דדברים שלא היו אז לא גזרו בהם כלל, וכל מה שהזכרתי למעלה מהגאונים הנ\"ל הם מסייעים ליה בזה.","b":false},{"t":"ובדברי אגרו\"מ מבואר עוד, דמה שלא היה אז, אינו נכלל בכלל הגזרה דקטניות, אפילו ששייך בו הטעם שבגללו אסור הקטניות, לא אסרינן ליה, וע\"כ לא אסרו תפו\"א אעפ\"י שעושין מהם קמח, ולא אסרו אני'ס וקימ'ל, אעפ\"י שרגיל שמתערבים בהם מיני דגן, וקשה לבוררן כמ\"ש הפוסקים, עם כל זה לא אסרום, כמפורש בהגהת הרמ\"א ז\"ל.","b":false},{"t":"ו.","b":false},{"t":"בדבר שהוא מסופק אם הוא בכלל קטניות אין להחמיר בו. ומה דין השומשום.","b":true},{"t":"ועוד חידש האגרות משה, דאפילו בספק אין לאסור, כמו בוטנים דיש מקומות שנהגו בהם איסור, ושם בלבד הם אסורים, אבל מספק אין לאסור. וכנ\"ל גם בשו\"ת אפרקסתא דעניא. וק\"ו לנ\"ד דהוא דבר חדש לגמרי במקומותינו, דאעפ\"י שיש שעושים מהם קמח, או אם יתברר שיש בהם תערובת דגן, מ\"מ אין לאוסרם, אלא לחייב בדיקה טובה ומדוקדקת, ובפרט שגם העושים מהם קמח הם מיעוטא דמיעוטא, ולא דמי לקמח תפו\"א, ואפ\"ה פשט המנהג בכל מקום להקל בקמח תפו\"א, וק\"ו בזה שכל כולו אינו מצוי כלל, וק\"ו שהקמח שלו עוד יותר לא מצוי.","b":false},{"t":"ועוד ראיתי בשו\"ת מלמד להועיל ח\"א (א\"ח סימן פ\"ז) שדן על השומשום אם הוא קטנית, ואם שמנו מותר בפסח. ובתחילת דבריו כתב שרבני אשכנז והונגריה ורוסיה חשבו ששומשום הוא הפרג (מאהן), אבל זה לא נכון אלא שומשום הוא זעזאם, שגם בערבית נקרא אלשומשו'ם. וע\"כ מ\"ש הגאון מוהרש\"ז בשו\"ע שלו (א\"ח סימן תג\"ן על השומשום כונתו לפרג.","b":false},{"t":"אכן רבני המזרח יודעים השומשום, ויש מקומות שאוכלים בפסח שמן שושמשמין כמ\"ש בברכי יוסף (סי' תמ\"ז אות י\"ד), שרוב המון ישראל אוכלים שמן שומשומין בפסח, ובסימן תג'ן אות ה' כתב, שבירושלים המחמירים שלא לאכול שומשומין מתירין להדליק בו. וכ\"כ גם במחזיק ברכה (סי' תס\"ז אות ה') ועיין בלב חיים (הובא בשד\"ח מערכת חמץ ומצה סי' א' אות ב') דלענין הדלקה בודאי יש להקל.","b":false},{"t":"עו\"כ ולענין אם השומשום נקרא קטניות, הנה אין מבואר בפוסקים גדר מלת קטניות, רק הט\"ז (סי' תג'ן סק\"א) כתב דחרדל מפני שגדל בשרביטין, הוא כקטניות. וכפי ששמעתי ששומשומין אינו גדל בשרביטין, אח\"ז ראיתי ביו\"ד (סימן רצ\"ב ס\"ג) שהשומשומין נכלל בקטניות, ומאחר שיש אחרונים שאוסרין את שמנו אפילו להדלקה, מפני שמעורב בו דגן, ש\"מ שיש בו חשש כבקטניות, גם אין דעת הט\"ז לומר שכל שאינו גדל בשרביטין אינו בכלל גזרת הקטניות. ולפ\"ז יש להחמיר בשומשומין ובפרט שדומה קצת לעדשים. [א\"ה זה לא מובן דלא דמו זל\"ז כלל.] וע\"ש שדן למעשה בענין הדלקה בשמן קטניות, וכן אם מותר לערב מעט שמן שומשומין במרגרינה, אם יש בזה משום מבטל איסור לכתחילה. עוד דן שם במנהג שבירושלים בשמן שומשומין. והעלה שהמנהג לאוסרו בירושלים, וגם הספרדים אוסרים אותו. וע\"ש.","b":false},{"t":"ועכ\"פ גם מדבריו נראה דאילולי שמצא לפוסקים שהשומשום נכלל בקטניות, וגם שאסרו את שמנו, לא היה אוסרו, וקינואה שעליו אני דן כאן, מעולם לא כללוהו בכלל הקטניות, ולא אסרו אדם מעולם.","b":false},{"t":"ז.","b":false},{"t":"שמן כותנה אם הוא בכלל קטניות.","b":true},{"t":"עוד ראיתי להגאון מנחת יצחק ח\"ג (סימן קל\"ח) אות ב', בשמן של צמר גפן לפסח אם יש בזה משום קטניות, וכתב דהמעדני שמואל (סימן קי\"ז אות כ\"ה) כתב בשם גדולי האחרונים, ובפרט משו\"ע הרש\"ז ( תנ\"ג ס\"ד) שכתב דלא נהגו איסור אלא במיני קטניות, אבל מיני זרעים וכו' וכיוצ\"ב משאר זרעוני גינה, אין נוהגין איסור, חוץ מהחרדל וכו', וכן כל מיני ירקות, אין מחמירין הואיל ואינן דומין לדגן, וע\"כ היה נראה להקל בזרע צמר גפן, אחרי בדיקה היטב שלא יתערב בהם א' מה' מיני דגן, וכמ\"ש הט\"ז שם (סק\"א) דמבואר ברמב\"ם (הל' כלאים פ\"ה הי\"ט) דקנבוס וקנרס וצמר גפן הרי הן כשאר מיני ירקות. ומקדשין בכרם. עכ\"ל. וכונתו לחלוקי הזרעונים שהזכיר (שם פ\"א ה\"ח וט') דחילקם לשלשה, תבואה, קטנית, וזרעוני גינה, ויש מהם הנקראים מיני זרעים, ויש שנקראים מיני ירקות, ע\"ש, וא\"כ עולה דצמר גפן מכלל ירקות הוא ולא בכלל קטנית, אבל עדיין לא ברירא לן דבר זה.","b":false},{"t":"ובאות ב, כתב דמה שמנה הרמב\"ם ז\"ל הקנבוס עם קנרס וצמר גפן, הנה הכס\"מ שם העיר דהא עיקר כלאים דאורייתא הוי קנבוס ולוף ודומיהם, וכמ\"ש שם בריש הפרק, ומאי קמ\"ל, וע\"כ לא גרסי' קנבוס, והרדב\"ז כתב שמקור להרמב\"ם בזה, מהמשנה דכלאים (פ\"ח מ\"ח) קנבוס רבי טרפון אומר אינו כלאים, וחכ\"א כלאים, והקונרס כלאים בכרם. וכונתו כמ\"ש הר\"ש בכלאים (פ\"ה מ\"ח) דהא דאמרי' במנחות (ט\"ו ע\"ב) קנבוס ולוף אסרה תורה, אתיא כרבנן, דאי ר\"ט אין קנבוס כלאים בכרם, וא\"כ מ\"ש הרמב\"ם שם, ומה שכתב בראש הפרק היינו הך, אלא שעדיין קשה מה שהקשה הכס\"מ דלמה חזר ע\"ז מאי קמ\"ל, וע\"ש באות ג' שהאריך לישב את הרמב\"ם, והעלה דזרע הקנבוס וזרע צמר גפן שוים.","b":false},{"t":"עו\"כ דהחי\"א בנשמת אדם (שאלה ל\"ב) הוכיח דשמן קטניות אסור באכילה מדברי הרב תרומת הדשן (סי' ק\"ב) שכתב דמותר ליהנות משמן זרע פשתן ושומשומין וזרע קנבוס, ומשמע דבאכילה אסור. ע\"ש. והרי אוסר שמן קנבוס. וגם בתשו' מהרי\"ל (סי' כ\"ח) כתב בזה\"ל, וזרע קנבוס, הר\"מ מרזבוק התיר כמון, אמנם לפי הסמ\"ק נראה לאסור כל דמידגן כמו חרדל וקטניות כמ\"ש שם. אך אין ליזהר מלהדליק בשמן. עכ\"ל. ור\"ל דאסור באכילה, ובזה נראה דזרע צמר גפן לא עדיף מזה, דיש להם ערך אחד. והביא מזכרון יהודה (א\"ח סי' קל\"ט) דמנהג ישראל לאסור כל השמנים מזרעונים, דעכ\"פ צריכים בירור מתערובת של מיני תבואה, ומי יכול להשגיח ע\"ש. עכת\"ד.","b":false},{"t":"והמדקדק בדברי הגאון מנחת יצחק ז\"ל, יראה דלא אסר שמן של צמר גפן, אלא אחר שהסיק בדברי הרמב\"ם ז\"ל בהלכות כלאים, דזרע צמר גפן שוה לזרע הקנבוס. אבל בלא זה רצה להתיר זרע צמר גפן, עפ\"י דברי שו\"ע דהגרש\"ז ז\"ל (סי' תג\"ן ס\"ד) דכתב, שלא נהגו איסור אלא במיני קטניות, אבל במיני זרעים וכיו\"ב משאר זרעוני גינה אין נוהגין איסור, חוץ מחרדל, וכו'. והמנח\"י הזכיר לדברי הרמב\"ם ז\"ל בכלאים (פ\"א ה\"ח וט') שחילק הזרעים לשלשה, תבואה, קטניות וזרעוני גינה. וכנ\"ל. [והנה יש מקום לשאת ולתת בדב\"ק במ\"ש על הקנרס והצמר גפן, ועוד חזון למועד אי\"ה. ובתשובה בענין כלאים והיא בכת\"י, דנתי בענינים אלו. ע\"ש].","b":false},{"t":"עכ\"פ לא החמיר אלא אחר שבא למסקנא, לשיטתו בדעת הרמב\"ם ז\"ל דצמר גפן וקנרס שוין הם. ומצא שאסרו שמן קנבוס באכילה, וע\"כ החמיר גם בשמן של צמר גפן דשוין הם. אבל זרעוני הקינואה שבנ\"ד, דאין להם שום שייכות לכל אלה, והוא דבר שבא מקרוב לא ידעוהו אבותינו, אין לנו לחדש ולגזור מעצמנו, אלא הבו דלא לוסיף על גזרת הקדמונים. ואנו חוזרים למה שמוסכם מהפוסקים, ואשר הגדירו היטב הגאון אגרות משה ז\"ל הנ\"ל, דלא נאסר אלא מה שהיה בכלל הגזרה דוקא. אבל כל דבר שלא היה ידוע באותם מדינות בזמן שהנהיגו גזרה זו, אעפ\"י שיש בו הטעמים שהזכירו באיסור זה, לא נאסר. וכנ\"ל.","b":false},{"t":"ועיין בכה\"ח (אות ל\"ו) שכתב על הדור'א, שנהגו בעה\"ק להאכילם לתרנגולים בפסח משום דאינו מחמיץ, וכן נהגו קמאי דקמאי, מזבח אדמה (דף ד' ע\"ג) ועיין חיים שאל ח\"ב (סי' מ\"ז) עכ\"ל. ומה שכתב שמתירים לתרנגולים, הוא משום שאינו ראוי לאדם, אבל רואים שלמרות שהוא דומה לדגן הרבה יותר מן קינואה, לא מחמיץ ומתירים להשתמש בו בפסח. ואולי לא גזרו עליו משום שלא ראוי לאדם, וקינואה ודאי לא גזרו משום שלא היה מצוי כלל.","b":false},{"t":"ועוד דהקינואה נאכל לאנשים שאינם יכולים לאכול פת ומזונות הרגילים, אם משום שהגלוטן מזיק להם, ואם משום קשיי עיכול וכיוצ\"ב, והקינואה מזין היטב וגם קל לעיכול, ובאמת הוא נמכר בחנויות שמוכרים דברים טבעוניים לריפוי ובריאות, ולאלה הזקוקים למאכל זה, הרי\"ז שעת הדחק, וכבר התירו כל הפוסקים בשעה\"ד שאין אוכלים מצויים, לאכול קטניות ממש. וכתב המשנה ברורה (סק\"ז) ופשוט דה\"ה לחולה אפילו שאין בו סכנה, דמותר לבשל לו אם צריך לזה. וכולהו איתנהו בקינואה, ויש להתירה. אלא שחובה גדולה לבררם בירור מדוקדק לפני הפסח, ויבדקו אותם בחיפוש אחר חיפוש ג' פעמים, שלא יהיו בהם מיני דגן או אורז ושאר קטניות, ואם אפשר לחלוט אותם תחילה, שירתיחו המים עד שיעלו בועות ואז יתנו בהם את הקינואה. והוא תיקון גדול וכמ\"ש החת\"ס. (סימן קכ\"ב). הובא במשנה ברורה שם, ושכן כתב גם החיי אדם והוא תיקון חשוב לענין זה.","b":false},{"t":"ואם אי אפשר לתקנו בחליטה מאיזה סיבה שמונעת, עכ\"פ יבדקוהו ג\"פ בדק היטב. ושרי.","b":false},{"t":"זה הנראה לעניות דעתי, וה' יאיר עינינו בתורתו שלא נבוש ולא נכלם לעולם ועד.","b":false},{"t":"המצפה לישועת ה' ברחמים על עמנו ועל נחלת אבותינו בב\"א.","b":false},{"t":"שלמה משה עמאר","b":true},{"t":"ראשון לציון הרב הראשי לישראל","b":false}]},{"t":"בענין פרי ה-שבו","p":[{"t":"בעהית\"ש, בששי בשבת תשעה עשר יום באדר התשס\"ד.","b":false},{"t":"2-472/ס\"ד","b":false},{"t":"למעלת ידידי וחביבי","b":false},{"t":"הרה\"ג ר' משה יוסף שליט\"א","b":false},{"t":"ראש בד\"צ בית יוסף","b":false},{"t":"בעה\"ק ירושלים תובב\"א.","b":false},{"t":"החיים והשלום וכט\"ס.","b":false},{"t":"אמש דיבר אתי מרן הראש\"ל פאר דורנו בעל יבי\"א שליט\"א בענין פרי ה\"שבו\", המצויים בבראזיל, ואמרתי למרן הרב שליט\"א שכבר כתבתי בזה בעת שכתבתי על האילים האדומים שמגיעים מאוסטרליה ששם העליתי שהאיילים ההם אינם טהורים.","b":false},{"t":"ואילו בפרי השבו נלע\"ד בפשיטות שהם טהורים, וכבר העלו כן גדולי הרבנים, ופוק חזי מאי עמא דבר.","b":false},{"t":"(א) למעשה יש בהם כל הסימנים שנאמרו בסימני טהרה, מעלים גרה ומפריסים פרסה, ואין להם לא שניים ולא ניבים בחניכיים העליונים. וכבר אמרו במסכת חולין (נ\"ט ע\"א) ת\"ר אלו הן סימני בהמה וכו'. כל בהמה שמעלה גרה בידוע שאין לה שיניים למעלה וטהורה, וכללא הוא וכו'. ועוד שיניים מי כתיבי באורייתא, אלא ה\"ק כל בהמה שאין לה שיניים למעלה בידוע שהיא מעלת גרה ומפרסת פרסה וטהורה, ולבדוק בפרסותיה כגון שהיו פרסותיה חתוכות, וכדרב חסדא דא\"ר חסדא היה מהלך במדבר ומצא בהמה שפרסותיה חתוכות, בודק בפיה אם אין לה שיניים למעלה בידוע שהיא טהורה, אם לאו בידוע שהיא טמאה, ובלבד שיכיר גמל, גמל ניבי אית ליה, אלא ובלבד שיכיר בן גמל. וכו' ע\"כ. [דלעיל אמרו שהגמל הצעיר אעפ\"י שאין פרסותיו סדוקות אין לו שיניים למעלה, וכשגודל גודלים לו שני ניבים בשני צידי הלסת].","b":false},{"t":"וכבר ביארתי שם שגם לבהמות והחיות הטהורות יש להם טוחנות גם למעלה, והם דברים מפורסמים, וכן מבואר בכף החיים יו\"ד (סימן ע\"ט סק\"ב) דדוקא שינים אין לטהורות, אבל מכתשות יש להן בין בלחי העליון בין בלחי התחתון, בין מלמעלה בין מלמטה כנודע. עכ\"ל. ולפי חכמי הזואולוגיה, יש לגדולות שלש תת טוחנות ושלש טוחנות למעלה בכל צד.","b":false},{"t":"ומה שאין להם לטהורות הן החותכות שהן השיניים הקדמיות והניבים שהם סמוכים להם וארוכים וצורתן שונה מהחותכות, ומשום כך שאלו בגמרא שם, והרי גמל אין לו שיניים למעלה ואינו מפריס פרסה, ותירצו ניבי אית ליה, דמתחילה ס\"ד דניבים אינם בכלל השיניים, ואסיק דגם הניבים הם בכלל השיניים וכל שיש לו ניבים למעלה טמא הוא.","b":false},{"t":"וכ\"כ הרמב\"ם ז\"ל בהלכות מאכלות אסורות (פ\"א ה\"ב) סימני בהמה וחיה נתפרשו בתורה והם שני סימנים מפרסת פרסה ומעלת גרה, עד שיהיו שניהם, וכל בהמה וחיה שהיא מעלה גרה אין לה שיניים בלחי העליון, וכל בהמה שהיא מעלת גרה הרי היא מפרסת פרסה חוץ מן הגמל, וכל בהמה שהיא מפרסת פרסה הרי היא מעלת גרה חוץ מן החזיר. עכ\"ל.","b":false},{"t":"ובהלכה ג' כתב, לפיכך המוצא בהמה במדבר ואינו מכירה ומצאה חתוכת הפרסות בודק בפיה אם אין לה שיניים למעלה בידוע שהיא טהורה והוא שיכיר גמל, מצא בהמה שפיה חתוך בודק בפרסותיה אם היא שסועה טהורה, והוא שיכיר חזיר וכו'. עכ\"ל.","b":false},{"t":"וכ\"פ הש\"ע ביו\"ד (סימן ע\"ט ס\"א) וכן הסכמת כל הפוסקים ז\"ל. ולא נזכר ענין של מסורת בבהמה וחיה לא בגמ' ולא בראשונים וענין מסורת נזכר רק גבי עוף, דאמרו בחולין (ס\"ג ע\"ב) אמר רבי יצחק עוף טהור נאכל במסורת. וכ\"פ מרן ז\"ל בש\"ע יו\"ד (סימן פ' סעיף ס\"ב) וז\"ל ואעפ\"י שיש לו ג' סימנים אלו אין לאוכלו, לפי שאנו חוששין שמא הוא דורס, אא\"כ יש להם מסורת שמסרו להם אבותיהם שהוא טהור. עכ\"ל. והטעם פשוט משום שלא נתפרשו סימני העוף, רק מנה הכתוב את העופות הלא טהורים, וכל שאר העופות טהורים. והטמאים שמנה הכתוב הם ארבעה ועשרים, והיות ואין אנו בקיאים בשמותם, ע\"כ נתנו לנו חז\"ל שלשה סימנים, ובזה הורו לנו שאין די בסימנים אלו אלא בעינן מסורת דוקא, אבל סימני בהמה וחיה מפורשים הם בתורה. ומשו\"כ לא נזכר בגמ' ולא בפוסקים ענין המסורת אלא בעופות, ולא בבהמה וחיה.","b":false},{"t":"(ב) והנה בש\"ע (סימן פ' ס\"א) כתוב חיה טהורה חלבה מותר ודמה אסור וטעון כסוי הדם, וחכמים נתנו סימנים וכו', ואם חסר א' מאלו השלשה סימנים חלבה אסור. עכ\"ל.","b":false},{"t":"וכתב הש\"ך שם (סק\"א) אם הם (הקרנים) מפוצלות וכו', עיין פירוש דברים אלו בב\"י, ולפי שאין לנו עתה אלא מה שקבלנו במסורת וכדלקמן סימן פ\"ב גבי סימני העוף, קיצרתי. עכ\"ל. נמצא דהש\"ך מצריך מסורת גם בחיה.","b":false},{"t":"והפמ\"ג בשפתי דעת (סימן פ' אות א') כתב ע\"ד הש\"ך דשם (סי' פ\"ב ס\"ג) דהצריכו מסורת בעוף האו\"ה (כלל נ\"ו אות ח\"י) כתב לפי שרבו הפירושים מהו סימן הדורס אי כפר\"ת ע\"ש, משא\"כ בסימני חיה ובהמה לא הזכירו דאינו נאכל אלא במסורת, ובהמה ודאי אין בקיאות להכיר מפרסת פרסה ומעלת גרה, וכו' אלא דהש\"ך נמי ה\"ק, כיון שרבו הפירושים (בקרני החיות) אין לאכול החֵלב אלא במסורת, דאין אנו בקיאים במובלע חרקייהו ושאר הסימנים. ע\"ש.","b":false},{"t":"הנה מבואר דהוא ז\"ל מפרש בדעת הש\"ך דמצריך מסורת בחיה כדי להתיר החלב שלה, אבל להיתר בשרה א\"צ במסורת, כיון שהסימנין ידועים. אבל להתיר החלב צריך להיות בקיא בקרנים, והואיל וסימנים רבים נאמרו בהם, ודעות רבים יש בזה בראשונים ובאחרונים בכל סימן וסימן מהם, וקשה לעמוד על אמיתת הענין, ע\"כ אמר שאין להתיר החלב של חיה, אלא עפ\"י מסורת בלבד.","b":false},{"t":"ולפי\"ז פשוט ופשיטא דבהמה א\"צ במסורת כלל ועיקר, דשם אין סימני קרנים, רק הסימנים המפורשים בתורה, וגם הסימן של השיניים שאמרו חז\"ל הוא קל להכירו וא\"צ בידיעה מיוחדת וע\"כ א\"צ במסורת כלל ועיקר, גם לדעת הש\"ך.","b":false},{"t":"ומכל הראשונים נראה להדיא דא\"צ במסורת אלא בעוף כמו שמפורש בגמ' חולין (ס\"ג ע\"ב), והטעם פשוט דבתורה לא מפורשים הסימנים וכנ\"ל.","b":false},{"t":"וכן הן דברי מרן ז\"ל בש\"ע (סימן פ' סוף ס\"ב) וז\"ל, ואעפ\"י שיש לו ג' סימנים אלו, אין לאכלו, לפי שאנו חוששין שמא הוא דורס, אא\"כ יש להם מסורת שמסרו להם אבותיהם שהוא טהור. עכ\"ל.","b":false},{"t":"[ובענין המסורת עיין שו\"ג שם]. אבל בבהמה וחיה שסימניהם מפורשים בתורה לא הצריכו מסורת, והש\"ך הוא יחידי בזה.","b":false},{"t":"וכאמור הפמ\"ג פירש בדעתו של הש\"ך דלא הצריך מסורת, אלא כדי להתיר חלבו בלבד, ומסתבר טעמיה, כי באמת יש מבוכה גדולה בביאור הסימנים שאמרו חז\"ל (חולין נ\"ט ע\"ב), בקרני החיה.","b":false},{"t":"(ג) ואולם הרב חכמת אדם ז\"ל (שער או\"ה כלל ל\"ו ס\"א) כתב דאין אנו אוכלים אלא מה שקבלנו במסורת מרבותינו, כמ\"ש בסעיף ו' בעופות, ושם בס\"ו כתב, אבל אנו במדינתנו קי\"ל כאותם פוסקים דכל הסימנים שבעולם לא מהני להתיר אלא מה שנמסר לנו מאבותינו.","b":false},{"t":"והנה מרן החזו\"א ע\"ה במכתבו שנדפס בחיו\"ד (סימן י\"א אות ד') כתב, אחרי שידוע כמה החמירו רבותינו הראשונים והאחרונים ז\"ל שלא לפרוץ גדר שגדרו הראשונים ז\"ל, אין לנו לנטות מדברי הגאון חכמת אדם שקבע בספרו שמנהגנו שלא לאכול בהמות וחיות אלא במסורת, וכפי פשטן של דברי הש\"ך (סימן פ' סק\"א) ודלא כהפמ\"ג. וכו'. עכ\"ל.","b":false},{"t":"ובאמת בפשיטות אדרבה נראה כהפמ\"ג דראשית לא הזכיר הש\"ך בדבריו בהמה, והסימן ההוא מיירי רק בחיות וסימנים שהם סימני הקרניים, וגם שזה נגד כל הפוסקים ראשונים ואחרונים שכולם לא הזכירו מסורת אלא בעופות שנזכר בש\"ס, וגם שיש טעמים מיוחדים לעופות. וכדי להבין דברי הש\"ך ולא יהיו תמוהים, פירשם הפמ\"ג דמיירי בהתרת החלב של החיה, דבזה בעי' מסורת, כי קשה לעמוד על סימני הקרניים שרבו בהם הדעות והפירושים.","b":false},{"t":"והנה החזו\"א המשיך וכתב באותו מכתב בסוגרים, שבאמת דברי הפמ\"ג אינם מתקבלים בלשון הש\"ך, שאם כונתו ז\"ל שיש לנו לקבל מינים חדשים בלי מסורת, אלא שאנו צריכים לנהוג בהם חומרי חיה וחומרי בהמה, א\"כ זה חידוש שחידשו הש\"ך, והיה לו לכותבו בלשון הוראה שנראה לו, אבל לשונו זה משמש לדבר ידוע מאי דעמא דבר, וזה ודאי לא שכיח כלל שקיבלנו מין חדש ונהגנו בו חומרי חיה וחומרי בהמה. אלא ודאי כונתו ז\"ל שאין לנו אלא בהמות כבשים ועזים, וכמ\"ש הר\"מ, והיה ידוע לש\"ך ז\"ל דעת חכמים שלא היו מזדקקים להכניס לשמוש מין חדש ומה שהזכיר (בסי' פ\"ב) בעופות היינו שאנו נוהגים בבהמות מנהג העופות. ולא שבא ללמוד משם, והכל משום מיגדר מילתא דנתמעטו הלבבות, ונוח לנו להחזיק במסורת, [וגם אם נקבל חדשים נסתבך בחלבן וכסוי דמן ותואר אבריהם לענין טרפות כגון עינוניתא דורדא וכיו\"ב, ואין עלינו לחפש הטעמים]. עכ\"ל בסוגרים.","b":false},{"t":"וכתלמיד הדן על הקרקע וכדי להתלמד, אני שואל, וכי לפי פירושו של מרן החזו\"א בש\"ך, אין זה חידוש גדול, שבגמ' וכה\"פ הזכירו מסורת רק בעופות, והוא מחדש להנהיגה גם בבהמות וחיות, שלא די בסימנים דאורייתא וגם לא די במה שהוסיפו חז\"ל כמו שיניים וכו', ומצריך מסורת, וא\"כ למה לא כתבה בלשון הוראה לומר ונראה לי, והגם שמרן ז\"ל שיכל ידיו בחכמה וכתב שבא ללמד על דבר ידוע מאי דעמא דבר וכו', מ\"מ היה לו לפחות לומר ובימינו או מאז איזה דורות נהגו לסלסל בזה ולא לסמוך על הסימנים כי נתמעטו הלבבות, ועשאום כמו בעופות להצריך מסורת דוקא. ומשלא כתב כן לכאורה יש מקום לדברי הפמ\"ג שהיה זקן ורגיל בלשונות הש\"ך ונאמן ביתו המושל בכל מכמני לשונו ונבכי מובאיו ומוצאיו הרבים, ודבריו דברי טעם כהנ\"ל.","b":false},{"t":"עוד הוסיף מרן החזו\"א ע\"ה וכתב, ואין כונת החכמ\"א שלא לקבל חיות אבל בהמות מותר, דהרי הש\"ך כתב דלפיכך קיצר, ואם יש חילוק בין חיות לבהמות אכתי אנו צריכים לסימני חיה, אלא ודאי כונתו, שבכל אופן אין אנו מקבלים מין חדש. וגם לדברי הפמ\"ג, לדידן אסור משום מנהג שקבע בחכמ\"א וספרו התפשט בדורו בכל ארץ ליטא. אבל העיקר שדברי הש\"ך הן כפי' החכמ\"א, ואין לפרוץ גדר במנהגן של ישראל, ואין לנו שום הכרח לזה, ודי לנו בבקר וצאן שבמסורת עכלה\"ט.","b":false},{"t":"והנה מלשון הש\"ך אדרבה נראה להדיא דקיצר בדין הקרנים של החיות, וז\"ל שם (סי' פ' סק\"א) אם הם מפוצלות כרוכות והדורות וחרוקות, עיין פי' של דברים אלו בב\"י, ולפי שאין לנו עתה אלא מה שקבלנו מאבותינו במסורת וכדלקמן (סימן פ\"ב) גבי סימני העוף קיצרתי. עכ\"ל. ואדרבה משמע דקאי רק על חיות שהרי מדבר על סימני קרני החיות, שבהם נאמרו פי' שונים ומגוונים, שע\"ז רמז כמו שפי' הב\"י, ואמר שמקצר בזה כי צריך מסורת, ומי הכניס כאן בהמות, ויותר מסתבר לכאורה כהפמ\"ג דקאי על היתר חלב החיה, שזה תלוי בסימני הקרנים.","b":false},{"t":"ואולי שעיקר כונתו שכיון וספר חכמ\"א התפשט בליטא, הרי זה מנהג דליטא ואין לשנות. וצ\"ע.","b":false},{"t":"וע\"ש בחזו\"א שהביאו עוד מכתב ממנו (באות ה') וז\"ל, יסוד הדבר לקבוע כונת הש\"ך (יו\"ד סימן פ' סק\"א) שכתב שאינו נכנס להאריך בפי' סימני הקרנים שאמרו חכמים להכריע בין חיה לבהמה, לפי שאין לנו עתה אלא מה שקבלנו במסורת, וכדלקמן (סימן פ\"ב) גבי סימני עוף.","b":false},{"t":"רהיטת הדברים שמנהגנו שלא לאכול מין חדש ע\"י סימנים כמו שכתב הרמ\"א בעוף, [וצ\"ל דהיה פשוט להם מנהג זה, והדור של הש\"ך דור של חכמים גדולים, הב\"ד של החלקת מחוקק, והגאון רבי יהושע השל, ורבני הגלילות, וכל ישראל היו נשמעין להם על פיהם יצאו ועל פיהם יבואו, והיה שימת לב לכל מנהג].","b":false},{"t":"ובחכ\"א (שם דין ט') כ' דאפשר לקבל עוף שאין אנו מכירין אותו, אבל אין לקבל אלא אדם גדול וזה אין נמצא האידנא כלל, ולא פירש אם יעידו שנים מהו. עו\"כ דצריך שידעו שנוהגים עפ\"י חכמים, וזה קשה לברר, האידנא דהעולם קשור, כמעט שלא נחשב שלא ידעו מין זה, אלא פירשו בכונה (קובץ איגרות ח\"ב, אגרת פ\"ג). עכ\"ל.","b":false},{"t":"והחידוש בזה שכאן כתב להדיא שהש\"ך לא נכנס להאריך בפי' סימני הקרנים שאמרו חכמים להכריע בין חיה לבהמה, וכו'. והוא כמ\"ש לעיל, וא\"כ מנלן שהש\"ך מצריך מסורת גם בבהמה.","b":false},{"t":"(ד) והנה מלבד דעת הפמ\"ג שהובא בחזו\"א. מצאתי עוד בספר יבין דעה להגאון רבי ישראל יהושע ז\"ל מקוטנא, על ש\"ע יו\"ד (סימן פ' סק\"א) שכתב בסוף דבריו שם וז\"ל, ודע דהא דסימני מפריס פרסה היא בין לבהמה בין לחיה, כל שמפריס פרסה ומעלה גרה הוא סימן טהרה, ולא הוצרכנו לדין דקרנים חרוקות כרוכות והדורות אלא להתיר חֵלבה. ודלא כמ\"ש בעל בית יעקב (הובא בפ\"ת שם) דדוקא לסימני בהמה טהורה סמכינן אסימנים דמפריס פרסה ולא לחיה, וזה ליתא, דבהדיא אמרינן דחיה בכלל בהמה לסימנים. וכ\"נ להדיא מדברי התוספות והרא\"ש דסימנים אלו מהני גם לחיה, ולא הוצרכנו לסימנים דקרנים אלא להתיר חֵלבה, וכ\"נ מבואר מדברי הרשב\"א בחידושיו, שכתב דמצא מין ממיני בע\"ח שמפריס פרסה ומעלה גרה, בודק בסימני הקרניים כדי להתיר חלבה, משמע דוקא להתיר חלבה אבל בשרה בלי זה מותר. עכ\"ל.","b":false},{"t":"ראינו בדבריו ז\"ל דמפשט פשיטא ליה להתיר כל בשר ע\"י שמפריס פרסה ומעלה גרה וא\"צ לשום סימן אחר, ולא הזכיר שום מסורת.","b":false},{"t":"וע\"ש עוד בדבריו ז\"ל שכן מפרש את דברי הש\"ך הנ\"ל, וז\"ל, ומ\"ש הש\"ך (סי' פ' סק\"א) דבזה\"ז בעינן מסורת היינו להתיר חלבה, אבל לא בשרה. ואין זה צריך לפנים. עכ\"ל.","b":false},{"t":"הא קמן דגם בדעת הש\"ך פשיטא ליה דבשר החיה אין צריכים מסורת. ורק להתיר חֵלבה הוא דמצריך הש\"ך מסורת. והן הן דברי הפמ\"ג הנ\"ל.","b":false},{"t":"וכן הוא בספר כף החיים (סימן פ' אות ה') שהביא הרבה אחרונים ההולכים בשיטת הש\"ך, והם לה\"פ (אות א') בית לחם יהודה (אות א') וכ\"כ לה\"פ (סעיף ב') דכל זה הוא לדינא דגמרא, אבל אנו אין לנו עתה אלא מה שקיבלנו במסורת, וכדלקמן (סימן פ\"ב) בהגה גבי סימני העוף. ע\"ש. וכ\"כ המש\"ז (אות ב') ובשפ\"ד (אות א') וחכמת אדם (כלל ל\"ו אות א'), ערוך השלחן (סוף אות י') וזבחי צדק (אות ב') כתב דבעיר בגדד יע\"א יש להם מסורת וקבלה בג' מיני חיות איל צבי ויחמור, והא דצריך קבלה ומסורת ה\"ד לענין חֵלב, אבל לענין בשר א\"צ בקיאות דהא ניכר במעלה גרה ומפריס פרסה, וכ\"כ ב\"י (בעמ\"ז אות ג'), וכן משמע מדברי הש\"ע שכתב ואם חסר א' מאלו הג' סימנים חלבה אסור, משמע אבל בשרה מותר. עכ\"ל.","b":false},{"t":"וגם מהפ\"ת (סי' פ' סק\"א) מבואר כהנ\"ל שהוא ז\"ל דחה דברי הבית יעקב שמצריך גם סימני הקרנים לטהרה, דס\"ל דבחיה לא מהני רק מפרסת פרסה ומעלת גרה, אלא בעינן גם סימני הקרנים כדי להתיר בשרה, והפ\"ת כתב עליו שאין דינו דין אמת, דאדרבה מדסיים מרן ז\"ל בש\"ע, ואם חסר אחד מאלו השלשה סימנים חלבה אסור, מבואר דעכ\"פ טהורה היא ובשרה מותר, וגם בסימן ע\"ט ס\"א, כתב, סימני בהמה וחיה נתפרשו בתורה וכו' משמע דמעלת גרה ומפרסת פרסה מהני גם בחיה לסימן טהרה, והוא פשוט. וע\"ש.","b":false},{"t":"נמצא דגם הפ\"ת מוכיח במישור מהש\"ע דלהתיר בשר החיה א\"צ בסימני הקרנים, ופשיטא הס\"ל דגם מסורת לא צריכים לזה. ועכ\"פ גם להבי\"ע אפשר דא\"צ מסורת, רק דמצריך גם סימני הקרנים, ותו לא מידי.","b":false},{"t":"(ה) והן היום (כ\"א אדר תשס\"ד) ביקרתי בבית הגאון המובהק מגדולי פוסקי הדור בעל שבט הלוי שליט\"א, ודיברנו בענין בהמות אלו ואמרתי לו חלק מדברי הנז', בדרך קצרה, ואמר לי שהוא ג\"כ מתיר בהמות אלו, וכבר כתב תשובה ע\"ז והיא לו' נדפסה בשו\"ת שבט הלוי ח\"י.","b":false},{"t":"והיה עמי ספר יבין דעה להגרי\"י מקוטנא ז\"ל הנ\"ל, והראיתי לפניו את הדברים הנ\"ל, ושמח עליהם כמוצא שלל רב, וביקשני להניח לו הספר לעיין בו, וכן הראיתי לו את דברי הרב כה\"ח הנ\"ל.","b":false},{"t":"ונתתי שמחה בלבי שגם הגאון הגדול הנז' נר\"ו מתיר בזה.","b":false},{"t":"ובאמת כן הוא פשטות הגמ' (חולין נ\"ט ע\"א) כדרב חסדא דאמר היה מהלך במדבר ומצא בהמה שפרסותיה חתוכות בודק בפיה אם אין לה שינים למעלה בידוע שהיא טהורה. ושם מיירי שאינו מכירה כלל ובודאי דאין לו שום מסורת, ומתירה רק ע\"פ העובדא שאין לה שינים למעלה, וק\"ו בפרות \"שבו\" שפרסותיהם שסועות והם מעלות גרה, ואין לה שינים למעלה. ודאי שהן כשרות וא\"צ מסורת.","b":false},{"t":"וכבר דן בזה הגאון קול מבשר (הרב משולם ראטה ז\"ל) ח\"א (סימן ט') שהשיב לועד הרבנים החרדים בפאריז, על הבהמות דמאדאגאסקר שהם קצת משונים מהבהמות שלנו, ובדקו אותם ואין להם שינים ולא ניבים בלחי העליון וגם היא מפרסת פרסה, אך נסתפקנו אולי היא חיה, ודמה צריך כסוי, וקשה לעמוד על הבירור ע\"י בדיקת הקרנים בסימנים כרוכות חדוקות והדורות או מפוצלות, כיון שרבו הדעות והפירושים בזה, ועוד חששו (הרבנים השואלים) לדעת הבית יעקב המובא בפתחי תשובה, שלדעתו סימן הקרנים הם גם סימן טהרה לחיה, ובלא סימן הקרנים אסורה באכילה.","b":false},{"t":"והרב ז\"ל השיב, דלית מאן דחייש לדעת הבי\"ע הנז', דמוכח מכל הפוסקים ומלשון הש\"ע (סימן פ' ס\"א) שכתב דאם חסר אחד מאלו השלשה סימנים חלבה אסור, וכתב ע\"ז הכרתי ופלתי (סי' פ' סק\"ב) חלבה הוא דאסור, אבל בשרה מותר, כיון דמפרסת פרסה ומעלת גרה. ועוד דהריב\"ם בתוס' חולין נ\"ט ע\"ב ד\"ה ואלו הן, דלרבנן דרבי דוסא, צריך סימני קרנים לאפוקי מספק בהמה, וסימני הטלפיים שפרסותיו סדוקות לאפוקי מחיה טמאה, אבל לר' דוסא כל שיש לה קרנים א\"צ לחזר אחר הטלפים, דבודאי חיה טהורה היא וחלבה מותר. דקימ\"ל חיה טמאה אין לה קרנים, א\"כ תיפוק ליה דגם להתיר בשרה באכילה צריך לחזר אחר הקרניים אעפ\"י שיש לה טלפיים, אלא ברור דהקרניים באו רק להתיר חלבה, דהבשר הותר עפ\"י סימני טהרה ודלא כהבית יעקב.","b":false},{"t":"עו\"כ שם שהגאון מהרי\"א הרצוג ז\"ל הרה\"ר לישראל, הביא דברי הגאון ר' יהושע מקושטא בספרו יכין ובועז שגם הוא דחה דברי הבי\"ע, והעלה דקרניים אינם סימני טהרה לבשר, וכן הוסיף הקול מבשר, דאם אכן הסימנים של הקרניים נכונים אז היא חיה, ואם לאו הרי היא בהמה וטהורה היא עפ\"י סימני פרסותיה ומעלת גרה, וא\"צ לסימן של הקרניים.","b":false},{"t":"עו\"כ דאע\"ג שבכל ספק אמרינן חלבה אסור וצריך כסוי, מ\"מ בשינוי מעט אין להוציאה מכלל בהמה. עו\"כ שהרבנים מפאריז כתבו שמנהל גן החיות אמר שבספרי הזואולוגיה נמנית בין הבהמות. וכן היא דעתו של הגאון הרב הרצוג הרה\"ר לישראל שזה מין בקר וא\"צ כסוי, ומומחים מובהקים אישרו דעתו, שהיא בהמה ביתית בלי שום ספק וגם הוא ז\"ל הסכים לזה. עכ\"ד.","b":false},{"t":"ובזמנו כשהייתי חוקר על האיל האוסטראלי הנקרא האיל האדום, הפגישוני עם פרופסור יורם יו\"ט ראש המחלקה הזואולוגית בתל אביב (שנחשב מגדולי המומחים בענינים אלו) ובתוך הדברים שאלתיו אם האיל הוא פרֵה ורבה עם האילים של א\"י ושאר מקומות והשיב בשלילה. ומזה נקבע שהם שני סוגים, וע\"ש בתשובה ההיא מ\"ש בזה. ושוב שאלתיו על הסבו הזה, ואמר שהם פרים ורבים עם שאר הפרות ויולדים כדרך כל הפרות, ועתה גם מפורסם הדבר שבא\"י מתערבים אותם פרות ושוורים מהמין ההוא עם אלה שבא\"י ומולידים וגם בניהם יולדים.","b":false},{"t":"ולפי עניות דעתי זו הוכחה פשוטה וברורה מן המציאות שהן פרות רגילות, בלא שום ספק שבעולם.","b":false},{"t":"(ו) ולענ\"ד גם למי שמחמיר להצריך מסורת יודה בנ\"ד בא\"צ מסורת כלל, דלא אמרו אלא בדברים חדשים מקרוב באו, ולא ידעום מקודם, בזה הוא דאמרו דאעפ\"י שיש להם סימנים לא די בכך וצריך מסורת.","b":false},{"t":"למשל בתרנגול הודו, דהיה ע\"ז רעש גדול בהרבה מקומות שלא הכירום, ומלבד שבעוף צריך מסורת מדינא דגמרא וכנ\"ל, הנה זה מין חדש שאינו לא מן התרנגולים ולא מן היונים ולא משאר העופות שרגילים לאוכלם, ובזה צריך מסורת.","b":false},{"t":"אבל בזה שהתברר באר היטב שהוא מהפרות הרגילות בלא שום חילוק ואינו מין חדש, בזה גם המחמירים יודו שא\"צ במסורת כלל, שהרי העובדא המפורסמת היום שהם פרים ורבים עם העגלים והפרות הרגילים, מוכיחה כמאה עדים שהם פרות רגילות. וכמו שיש כמה סוגים, פרה הולנדית ואוסטראלית, וערבית ועוד, ה\"נ יש פרה הודית הנקראת סבו, ואין שום הבדל וא\"צ בזה לשום מסורת כלל ועיקר.","b":false},{"t":"ועוד גם אם יש צורך במסורת, הרי יש להם מסורת שבמקומות שהם היו שם אכלו אותם עם ישראל אשר שם, וכמו בהודו ואגפיה, וכן בבראזיל שכמעט שאין שם בהמות אחרות רק מהמין הזה, וגם בארגנטינה ואורגואי יש הרבה מהסוג הזה ואוכלים אותם בלי פקפוק, וגם לא\"י שחטו מהם והעידו ראשי צוותות השוחטים הותיקים שכבר לפני קרוב לארבעים שנה שחטו מהם בחבש ויבאו הבשר ארצה.","b":false},{"t":"ועוד העיד לפני אחד מחשובי הרבנים המומחים בשחיטה ובדיקה כב' הרה\"ג ר' יהודה טביב שליט\"א ואמר לי ששאל לזקני רבני תימן העי\"א ואמרו לו שגם בתימן היו להם פרות כאלו עם גיבנת וקוראים לה תורבני'א, והיו אוכלים אותם בשופי.","b":false},{"t":"וידוע דכשיש מקומות שאכלו מהני המסורת שלהם גם למקומות אחרים דבש\"ע יו\"ד (סימן וק\"ו בזה שבמקומות שהיו מסוג הזה היו אוכלים אותם, ובמקומות אחרים לא היו.","b":false},{"t":"ובפרט שבזה לרוב הפוסקים ככולם, א\"צ במסורת כלל, ובודאי דדי לנו במסורת של המקומות ההם, שבהם היו מצויים אותם סוגים, להתירם גם בשאר מקומות לכו\"ע.","b":false},{"t":"וכבר כתבתי שמבואר בגמרא ובכל הפוסקים, דכל שאין לה שינים למעלה בידוע שטהורה היא בלא פקפוק.","b":false},{"t":"וכ\"כ הפרי חדש (סימן ע\"ט סק\"ג) וז\"ל לפי שאין לך בטהורים שיהיה לה שינים מלמעלה, ואין לך בטמאים שאין לה שינים מלמעלה, וכל שיש לה שינים למעלה בידוע שהיא טמאה. עכ\"ל. ועיין עוד בפרי תואר לבעל אוה\"ח הקדוש (סימן ע\"ט אות ב') ע\"ד הש\"ע שם, שכתב וכל בהמה וחיה שאין לה שינים בלחי העליון ולא ניבים, שהם תלתלי בשר כעין ניבים בולטים בחניכים, וי\"א שניבין הם שני שינים למעלה א' מכאן ואחד מכאן בקצוות הלסתות בידוע שהיא טהורה, והוא שיכיר בן גמל שאין לו ניבין עד שיגדיל וכו' עכ\"ל. [ואלה גם כשגודלים אין להם לא שינים ולא ניבין]. וכתב הפר\"ת, ע\"כ משמע דבעינן לסימן טהרה שלא יהיו לה לא שינים ולא ניבים, והכי משמע להדיא מהש\"ס. יע\"ש. וכן עולה גם מדברי השו\"ג ושאר האחרונים.","b":false},{"t":"ומאחר ופירוש לנו הפר\"ח שאין לך בטמאים שאין לה שינים מלמעלה, וזאת אין לה שינים למעלה כלל, ודאי דאינה מן הטמאים.","b":false},{"t":"וכן הוא לשון רבינו המאירי ז\"ל, ג\"כ בחולין שם, וז\"ל, שכל בהמה טהורה אין לה שינים בלחי העליון, וכל בהמה טמאה יש לה שינים למעלה, חוץ מן הגמל הבחור. עכ\"ל. (וע\"ע שם בהמשך דבריו).","b":false},{"t":"הרי מפורש בראשונים ובאחרונים דכל שאין לה שינים למעלה, היא טהורה, ואיך נחוש לה אנן לאוסרה ובפרט שגם פרסותיה שסועות כדין וגם מעלה גרה. ועוד דהש\"ך יחידי בזה שמצריך מסורת בחיות, ונאמן ביתו שמפרש בו כל דיבור ודיבור הרב פמ\"ג מפרש לדבריו דאינו מצריך מסורת להתיר בשר החיה, אלא כדי להתיר החֵלב שלה בלבד, וכן פירשו ג\"כ הגאון רבי יהושע ישראל מקוטנא ז\"ל וכן פירש בדבריו גם הגאון בעל זבחי צדק.","b":false},{"t":"וכבר אוכלים מהם כיום רבבות אלפי ישראל החרדים ע\"ד ה', ואיך נלעיז עליהם ח\"ו.","b":false},{"t":"ועוד שביררתי שגם יש מסורת שאכלום במקומות שבהם היה מצוי הסוג הזה, וגם בתימן היו אוכלים אותם.","b":false},{"t":"וכאמור כן פסקו הגאון מוהרי\"א הרצוג ז\"ל הרה\"ר לישראל, וכן פסק הגר\"מ ראטה ז\"ל בקול מבשר.","b":false},{"t":"וכן פסק הגאון המובהק רבינו שמואל וואזנר שליט\"א בספרו וכן אמר לי פה אל פה.","b":false},{"t":"וגם בשיחה עם מרן מופה\"ד רבינו עובדיה יוסף שליט\"א פשיטא ליה להתירם.","b":false},{"t":"מפתחות – פרי השבו","b":true},{"t":"(א) פרי השבו יש להם סימני טהרה, מעלים גרה ומפריסים פרסה – ואין להם שינים בלחי העליון לא שינים ולא ניבים – בחולין נ\"ט ת\"ר אלו הן סימני בהמה וכו', אלא ה\"ק כל בהמה שאין לה שינים למעלה בידוע שהיא מעלת גרה – וכדרב חסדא היה מהלך במדבר וכו' אם אין לה שינים וכו', אם לאו כידוע שהיא טהורה – כבר ביארתי בתשו' אחרת, שגם לטהורות יש טוחנות למעלה, אבל חותכות וניבים אין להם למעלה – ומתחילה הוה ס\"ד בגמ' דניבים לא חשיבי שינים וע\"כ שאלו מגמל, והשיבו ניבי אית ליה. – הרמב\"ם (פ\"א ה\"ב) סימני בהמה וחיה נתפרשו בתורה, והם שני וכו', וכל בהמה וחיה שהיא מעלה גרה, אין לה שינים בלחי העליון וכו' – ובהלכה ג' כתב הדין דרב חסדא. וכ\"פ בש\"ע, ומוסכם מכל הפוסקים – ענין המסורת לא נזכר בבהמה ובחיה כלל – אבל בעוף אמרו בגמ' (ס\"ג:) דאעפ\"י שיש לו ג' סימנים בעינן מסורת, וכן בש\"ע (פ' ס\"ב) – והטעם שהתורה לא כתבה סימן לעוף רק מנתה כ\"ד עופות טמאים והשאר כולם טהורים – ומשום דלא קים לן בכ\"ד אלו, ואין לנו סימנים מובהקים ע\"כ צריך מסורת –","b":false},{"t":"(ב) בש\"ע (פ' ס\"א) חיה טהורה חלבה מותר וכו' ויש סימנים בקרנים וכו' – וידוע דפירושים רבים נאמרו בכ\"א מהסימנים של הקרנים – וכתב הש\"ך (סק\"א) שאין לנו אלא מה שקבלנו במסורת – הפמ\"ג פ\"י בדבריו, שאין להתיר חלב החיה אלא במסורת – ולפ\"ז פשוט דבבהמה לכ\"ע א\"צ מסורת כלל –","b":false},{"t":"(ג) החכמת אדם כ' דאין אוכלים אלא מה שקיבלנו במסורת – והחזו\"א כ' דאין לנטות מהחכמ\"א שקבע שמנהגנו שלא לאכול בהמות וחיות, אלא במסורת כלל – החזו\"א כ' שדברי הפמ\"ג אינם מתקבלים בלשון הש\"ך – דאם בא לחדש דבר שאין מסורת לנהוג בו חומרי חיה ובהמה היה לו לומר נראה לי, אבל לשונו משמש לדבר ידוע וכו' – והערתי וכי לפי' של מרן החזו\"א אין זה חידוש, וגם למ\"ש דהכי עמא דבר, עכ\"פ לא נזכר בשום פוסק – עו\"כ דאין כונת החכמ\"א רק על חיות, דהש\"ך כ' שלפיכך קיצר, ואם יש חילוק עדיין צריכים לסימני חיה – ודברי חכמ\"א התפשט בכל ליטא ואין לפרוץ גדר – ואדרבה מהש\"ך נר' שקיצר בסימני הקרנים מפני שרבו בהם הפירושים, אבל בהמה מאן דכר – ועיקר סמיכת החזו\"א הוא המנהג, וזה בליטא – וכ\"ן ממכתב אחר של החזו\"א –","b":false},{"t":"(ד) גם הגר\"י מקוטנא כתב בפשיטות דסימני הקרנים הם רק להתיר החלב, ומוכיח מהראשונים עו\"כ דמ\"ש הש\"ך דבעי' מסורת, היינו להתיר חלבה, וכדברי הפמ\"ג – וכ\"כ כה\"ח בשם זבח\"צ דא\"צ מסורת אלא להתיר חלבה – וכ\"מ מהש\"ע שכתב, ואם חסר א' משלשה אלו חלבה אסור – וכ\"נ להדיא מהפ\"ת בדחותו דברי הבי\"ע ושכן הבין בדברי הש\"ע –","b":false},{"t":"(ה) וביקרתי בבית הגר\"ש וואזנר שליט\"א, ודיברנו בזה ואמרתי לו מ\"ש בזה, ואמר שגם הוא התיר את השבו ונתתי שמחה בלבי – עוד נלע\"ד להוכיח מדרב חסדא פיה מהלך במדבר וכו', אם אין לה שינים בידוע שהיא טהורה – ומשמע בפשיטות דבכל גונא שאין לה שינים טהורה, וא\"צ מסורת – וכן העלה הקול מבשר דלא חיישי' לדעת הבי\"ע ד\"כ בכו\"פ דחלבה הוא דאסור בחסר א' מג' סימנים, אבל בשרה מותר – עו\"כ שהגר\"י הרצוג הביא בביא ד' הגר\"י מקושטא שגם הוא דחה ד' הביע – והביא מהמומחים לזואולוגיה שהיא מהבהמות ולא חיה – ובעת שהייתי חוקר על האילים, אמר לי פרופ' מומחה שהשבו פרה ורבה עם שאר בהמות וגם ולדותיהם ממשיכים להוליד – וכעת כבר נודע .. עשו בא\"י עדרים של ולדי מעורבים משבו ושאר פרות –","b":false},{"t":"(ו) לענ\"ד גם מי שמחמיר להצריך מסורת אפשר דבנ\"ד א\"צ – י\"ל דרק בדברים שאינם ידועים מקודם – כגון תרנגול הודו דהרבה מקומות לא ידעו מזה – העובדא שהם פרים ורבים עם יתר הפרות מוכיחה, שהן מין אחד – וכמו שיש פרות הולנדיות, ויש אוסטרליות, ויש ערביות וכו', ה\"נ ישנו הסווג הזה – וכבר התפשטו בכל העולם זה שנים רבות שכל הבד\"צ שחטו ואכלו מהם שנים רבות – ועוד מעידים שבתימן אכלו אותם פרות עם הגיבנת – ובפרט שלדעת רוב ככל הפוסקי' בבהמות א\"צ מסורת כלל – והפר\"ח כ', ואין לך בטמאים שאין לה שינים למעלה – גם הפר\"ת כ' וכל בהמה וחיה שאין לה שינים בלחי העליון ולא ניבים וכו', בידוע שהיא טהורה. וכן הוא בשו\"ג ושאר אחרונים – וכ\"כ המאירי שכל בהמה טמאה אין לה שינים בלחי העליון, וכל בהמה טמאה יש לה שינים למעלה – וגם בחיות הש\"ך הוא יחידי, וגם שהפמ\"ג והגר\"י מקוטנא פירשו דעתו, רק להתיר החלב – וכבר פשטה אכילתם בקרב כל ישראל כמעט, ואיך נלעיז עליהם – ועוד שיש מסורת באיזה מקומן של זבחים – והעיקר להתיר וכמו שפסקו הגר\"י הרצוג והגר\"מ ראטה ז\"ל, וכ\"פ הגר\"ש וואזנר שליט\"א וגם מפוה\"ד מרן בעל יביע אומר פשיטא ליה להתירם.","b":false}]}];